INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Salomon régnait donc sur Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Et voici les chefs qui étaient avec lui: Azarias, fils de Sadoc;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Eliaph et Achia, fils de Séba, scribes; Josaphath, fils d\'Achilud, gardien des actes publics.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Banaïas, fils de Joïada, général de l\'armée; Sadoc et Abiathar, prêtres;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Ornia, fils de Nathan, chef de ceux qui se tenaient près du roi, et Zabuth, fils de Nathan, ami du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Achisar était économe; et Eliac économe; Eliab, fils de Saph, était chef des tribus, et Adoniram, fils d\'Audon, intendant des impôts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Et Salomon avait douze officiers sur tout Israël, pour approvisionner le roi et toute sa maison; chaque tribu faisait l\'approvisionnement d\'un mois par année.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Voici leurs noms: Béen, fils de Or, en la montagne d\'Ephraïm; le premier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Ben-Dacar, à Macès, à Salabin, à Bethsamys et à Elon, jusqu\'à Géthanan; le second.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Ben-Esdi en Araboth, Socho et tout le territoire d\'Opher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Ben-Aminadab avait tout Nephthador; il avait épousé Téphath, fille de Salomon; encore un.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Bana, fils d\'Achilud, avait Ithaanach, Mageddo et toute la maison de Dan, vers Saséthan sous Esraé, et le territoire depuis Bethsan jusqu\'à Sabelmaüla, et jusqu\'à Maèber-Lucam; encore un.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Ben-Naber était à Rhaboth-Galaad, et avait tout le territoire d\'Ergab en Bitsan, soixante villes grandes et fortes avec des verrous d\'airain; encore un.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Achinadab, fils de Saddo, avait Manaïm.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Achimaas était en Nephthali; celui-ci avait épousé Basemmath, fille de Salomon; encore un.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baanan, fils de Chusi, était en Aser et en Baaloth; encore un.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Sémeï, fils d\'Ela en Benjamin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Gaber, fils d\'Adaï, en la terre de Gad, de Séhon, roi d\'Esebon, et de Og, roi de Basan, et il était Naseph (Nasib) en la terre de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Josaphat, fils de Phuasud, en Issachar.');
