INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Ainsi, les officiers approvisionnaient le roi Stillemon, et chacun avait son mois pour subvenir à ce qui était demandé pour sa table; et ils n\'intervertissaient jamais l\'ordre établi. Ils faisaient transporter l\'orge et la paille pour les chevaux de selle et les attelages du roi, en tout lieu où il se trouvait, chacun selon ce qui lui était prescrit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Et voici ce qu\'il fallait chaque jour à Salomon: trente mesures de fleur de farine, et soixante mesures de farine pétrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Dix veaux choisis, vingt bœufs pris au pâturage, et cent brebis, et en outre des cerfs, des chevreuils parqués et engraissés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Car il était chef de toute la contrée en deçà de l\'Euphrate, et la paix régnait tout alentour de ses territoires.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Et le Seigneur avait doué Salomon d\'une grande intelligence, d\'une grande sagesse, et d\'une richesse de cœur abondante comme le sable du rivage de la mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Et le Seigneur avait doué Salomon d\'une grande intelligence, d\'une grande sagesse, et d\'une richesse de cœur abondante comme le sable du rivage de la mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Et le Seigneur avait doué Salomon d\'une grande intelligence, d\'une grande sagesse, et d\'une richesse de cœur abondante comme le sable du rivage de la mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Et le Seigneur avait doué Salomon d\'une grande intelligence, d\'une grande sagesse, et d\'une richesse de cœur abondante comme le sable du rivage de la mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Et le Seigneur avait doué Salomon d\'une grande intelligence, d\'une grande sagesse, et d\'une richesse de cœur abondante comme le sable du rivage de la mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'La sagesse de Salomon s\'accrut et surpassa celle des anciens, celle de tous les sages de l\'Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Et il était le plus sage des hommes; il était plus sage que Géthan le Zarite, qu\'Enan, que Chalcad et que Darala, fils de Mal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Et il dit trois mille proverbes et cinq mille cantiques.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Et il disserta sur tous les arbres, depuis le cèdre du Liban jusqu\'à l\'hysope qui sort des murailles; il parla de tous les quadrupèdes, de tous les oiseaux, de tous les reptiles et de tous les poissons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Et tous les peuples venaient pour entendre la sagesse de Salomon; et combien y eut-il de rois de la terre qui vinrent entendre la sagesse de Salomon! Et Salomon avait épousé la fille du Pharaon d\'Égypte; il l\'avait amenée dans la ville de David, en attendant qu\'il eût achevé le temple du Seigneur, ainsi que son propre palais et les remparts de Jérusalem. Alors, le Pharaon vint d\'Égypte; il prit Gazer et il la livra aux flammes; il extermina le Chananéen qui habitait Mergab, et il donna ces conquêtes à sa fille, femme de Salomon, et Salomon rebâtit Gazer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Et Hiram, roi de Tyr, envoya ses serviteurs, sachant que Salomon avait été oint à la place de David, son père; car Hiram avait aimé David tous les jours de sa vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Salomon envoya aussi des messagers à Hiram, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Tu sais que David, mon père, n\'a pu bâtir un temple au nom du Seigneur mon Dieu, à cause des guerres qui ont éclaté tout alentour, jusqu\'à ce que le Seigneur eût abattu ses ennemis sous la plante de ses pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Maintenant, le Seigneur mon Dieu m\'a donné la paix tout alentour; il n\'est point de complot contre moi ni de mauvais desseins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 19, 'Et voilà que j\'ai résolu de bâtir un temple au nom du Seigneur mon Dieu, comme le Seigneur Dieu l\'a dit à David mon père: C\'est ton fils, que je mettrai sur le trône à ta place, qui bâtira un temple à mon nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 20, 'Donne donc tes ordres, et que l\'on coupe des arbres du Liban; voici mes serviteurs pour aider les tiens, et je te paierai le salaire de tes services comme tu le demanderas; car tu sais que parmi nous personne n\'est aussi habile que les Sidoniens à travailler le bois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 21, 'Or, Hiram fut grandement réjoui d\'entendre ces paroles, et il dit: Béni soit aujourd\'hui le Seigneur, qui a donné à David un fils aussi sage pour gouverner ce peuple nombreux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 22, 'Puis, il envoya dire à Salomon: J\'ai ouï toutes les choses au sujet desquelles tu as envoyé près de moi; je ferai tout ce que tu veux; cèdres et sapins,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 23, 'Mes serviteurs transporteront tout du Liban à la mer; on en formera des radeaux jusqu\'au lieu que tu m\'indiqueras; là, je les ferai délier, et tu les enlèveras, et tu feras tout ce que je désire en donnant des vivres à ma maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 24, 'Hiram donna donc à Salomon des cèdres, des sapins et tout ce qu\'il voulut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 25, 'Et Salomon donna à Hiram vingt mille mesures de froment pour alimenter sa maison, et vingt mille mesures d\'huile battue; voilà ce que Salomon donna par an à Hiram.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 26, 'Or, le Seigneur avait donné à Salomon la sagesse comme il le lui avait dit. Et la paix régnait entre Hiram et Salomon, qui contractèrent entre eux une alliance.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 27, 'Le roi imposa une corvée à tout Israël, et il requit pour ce service trente mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 28, 'Il les fit partir pour le Liban, dix mille par dix mille qui se relevaient mois par mois; ils passaient un mois au Liban et deux mois chez eux. Adoniram était à leur tête.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 29, 'Et Salomon employait soixante-dix mille hommes à transporter les matériaux, et quatre-vingt mille à tailler des pierres dans la montagne,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 30, 'Sans compter les conducteurs des travaux; il y en avait trois mille six cents habiles à ces sortes d\'œuvres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 31, 'Et l\'on mit trois ans à préparer les pierres et les bois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 32, 'Et l\'on mit trois ans à préparer les pierres et les bois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Ce fut en l\'an quatre cent quarante de la sortie d\'Égypte, pendant le second mois de la quatrième année du règne de Salomon, Que le roi donna l\'ordre de prendre des pierres, grandes et chères, pour les fondations du temple, et des pierres parfaitement taillées. Les fils de Salomon et les fils d\'Hiram les taillèrent et les transportèrent. En la quatrième année on jeta les fondements du temple du Seigneur, pendant le mois de Zin, le second mois. En la onzième année du règne de Salomon, pendant le mois de Baal, le huitième mois, le temple fut achevé, selon sa destination et selon les plans arrêtés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Le temple que le roi bâtit au Seigneur avait quarante coudées de long, vingt de large et vingt-cinq d\'élévation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Le vestibule, sur la façade de l\'édifice, était long de vingt coudées, la largeur même du temple en sa façade. Et le roi bâtit le temple, et il l\'acheva.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Il fit au temple des fenêtres inclinées et cachées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Il fit, contre les murs du temple, des étages qui entouraient le temple et l\'oracle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'L\'étage inférieur avait cinq coudées de large; celui du milieu six, le troisième sept; il les sépara extérieurement du temple tout alentour, pour que cette construction ne s\'engageât pas dans le mur du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Le temple fut bâti en pierres blanches taillées à angles droits; et, pendant qu\'on l\'élevait, on n\'entendit dans le temple ni le marteau, ni la hache, ni aucun outil de fer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Le porche de l\'étage inférieur était sous l\'aile droite du temple; un escalier tournant menait au milieu; et, du milieu, au troisième étage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Salomon bâtit ainsi le temple; il l\'acheva, et il le lambrissa de cèdre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Il éleva tout le long du temple des panneaux, ayant chacun cinq coudées de hauteur, et il les maintint dans des cadres de bois de cèdre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Il fit ainsi en bois de cèdre le dedans du temple, depuis le sol jusqu\'au haut des murs et jusqu\'aux solives; il revêtit l\'intérieur de lambris de bois, et il fit tout alentour une corniche de sapin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Il fit ainsi en bois de cèdre le dedans du temple, depuis le sol jusqu\'au haut des murs et jusqu\'aux solives; il revêtit l\'intérieur de lambris de bois, et il fit tout alentour une corniche de sapin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'Il fit ainsi en bois de cèdre le dedans du temple, depuis le sol jusqu\'au haut des murs et jusqu\'aux solives; il revêtit l\'intérieur de lambris de bois, et il fit tout alentour une corniche de sapin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Il fit ainsi en bois de cèdre le dedans du temple, depuis le sol jusqu\'au haut des murs et jusqu\'aux solives; il revêtit l\'intérieur de lambris de bois, et il fit tout alentour une corniche de sapin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Il fit ainsi en bois de cèdre le dedans du temple, depuis le sol jusqu\'au haut des murs et jusqu\'aux solives; il revêtit l\'intérieur de lambris de bois, et il fit tout alentour une corniche de sapin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Il éleva une cloison de vingt coudées depuis le sol du temple jusqu\'aux solives; au delà de cette cloison étaient l\'oracle et le Saint des saints.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Et la nef avait quarante coudées,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Jusqu\'à la cloison qui la séparait de l\'oracle, où devait être renfermée l\'arche de l\'alliance du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Jusqu\'à la cloison qui la séparait de l\'oracle, où devait être renfermée l\'arche de l\'alliance du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Or, cet oracle avait vingt coudées de long, vingt coudées de large, vingt coudées de haut, et il le revêtit de lames d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Et il fit devant l\'oracle l\'autel du Seigneur et il le revêtit d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Il revêtit d\'or tout le temple en toutes ses parties.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Il fit dans l\'oracle deux chérubins de la taille de dix coudées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'L\'un avait des ailes de cinq coudées, et le second avait des ailes de cinq coudées; de la naissance d\'une aile à la naissance de l\'autre, il y avait dix coudées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Le second était semblable au premier, et ils avaient l\'un et l\'autre les mêmes dimensions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'L\'un des deux chérubins était d\'une taille de dix coudées, et l\'autre pareillement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Et les deux chérubins étaient placés au milieu du temple intérieur, et ils ouvraient les ailes; l\'extrémité de l\'aile de l\'un touchait à l\'un des murs, l\'extrémité de l\'aile de l\'autre touchait au mur opposé; au milieu du temple, les deux autres ailes de chacun se rejoignaient par leurs extrémités.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Le roi revêtit d\'or les chérubins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Il fit, sur tous les murs autour du temple, des ciselures, œuvre variée, et il sculpta des palmes intérieurement et extérieurement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Il revêtit d\'or le plancher du temple au dedans et au dehors.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'A l\'entrée de l\'oracle, il posa des portes de bois de genièvre, avec des pilastres à [cinq] faces.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Les deux portes du temple étaient en sapin; [et il sculpta sur les battants des chérubins et des palmiers aux feuilles déployées, et il les recouvrit d\'or, et l\'or revêtait aussi les chérubins et les palmiers.]');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, '[Et ainsi il fit pour la porte du temple des linteaux de genièvre, et des portiques à quatre côtés.]');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, '[Et les deux portes étaient en planches de sapin; une porte constituée de deux battants avec leurs gonds, et de même l\'autre porte.]');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Elles étaient ornées de chérubins et de palmes aux feuilles déployées, et les saillies étaient revêtues d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Il bâtit le parvis intérieur: trois assises de pierres de taille, et tout alentour un lambris de cèdre. Et il plaça parallèlement à la façade du temple le voile du parvis du vestibule.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Le roi Salomon envoya demander et obtint Hiram de Tyr,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Fils d\'une femme veuve, issu de la tribu de Nephthali. Son père était un Tyrien, forgeron plein d\'art, d\'intelligence et d\'habileté pour faire toutes sortes d\'ouvrages d\'airain; quand on l\'eut amené au roi Salomon, il lui fit tous ses travaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Il jeta en fonte les deux colonnes du vestibule du temple, chacune haute de dix-huit coudées, ayant quatorze coudées de périmètre et des cannelures de quatre doigts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Il jeta en fonte, pour les colonnes, deux chapiteaux, ayant chacun cinq coudées de haut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Il fabriqua deux filets d\'airain pour couvrir les deux chapiteaux des colonnes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Et, pour chaque chapiteau, une guirlande suspendue; deux lignes de grenades d\'airain en forme de filets, suspendues en guirlande, une ligne au- dessus de l\'autre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Il dressa les colonnes du vestibule du temple: à l\'un, il donna le nom de Jachum, et à l\'autre, il donna le nom de Boloz.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Et il plaça, dans les chapiteaux des colonnes, dans le sens de la façade du vestibule, des lis d\'airain de quatre coudées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Une architrave réunit les deux colonnes, et il y eut de chaque côté une architrave en retour, de la même épaisseur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Et il fit la mer complètement circulaire; tout autour, il y avait dix coudées d\'un bord à l\'autre; elle était profonde de cinq coudées, et avait trente-trois coudées de circonférence intérieure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Au-dessous de ses bords, il fit des étais tout alentour, dix par coudée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Ses bords s\'évasaient comme une coupe en forme de fleur de lis; et elle avait une palme d\'épaisseur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Il fit douze bœufs sous la mer: trois regardant le septentrion, trois regardant l\'occident, trois regardant le midi, trois regardant le levant; leurs queues étaient tournées vers l\'intérieur du temple, et la mer les couvrait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Il fit dix bassins d\'airain, chacun long de cinq coudées, large de quatre, haut de six.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Ces bassins étaient composés de pièces de rapport, et les pièces rapportées étaient entre les parties saillantes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Et, sur les pièces rapportées, entres les parties saillantes, il fit des lions, des bœufs, des œuvres variées; et, sur les parties saillantes, en dessus comme en dessous, les places des lions et des bœufs, œuvre allant en pente.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Et chaque bassin avait quatre roues d\'airain, ses accessoires étaient d\'airain; et, des quatre côtés, il y avait des supports sous les cuvettes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Il y avait des crampons dans les bassins et dans les roues; la hauteur d\'une roue était d\'une demi-coudée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Et les roues étaient faites comme les roues d\'un char; leurs crampons, leurs bandes, leurs accessoires, étaient jetés en fonte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Les quatre supports, aux quatre coins de chaque bassin, faisaient saillie sur lui, et les maintenaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Le bassin, dans sa partie supérieure, était terminé par une moulure saillante d\'une demi-coudée tout alentour; les crampons s\'emboîtaient dans son contour, et le bassin avait une ouverture à l\'emboîtement des crampons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Toute sa surface était ornée de chérubins, de lions et de palmes; chacune de ces sculptures faisant saillie sur le fond tout alentour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Et les dix bassins étaient faits de même, et avaient les mêmes dimensions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Et il fit dix cuvettes d\'airain, profondes de quatre coudées, contenant chacune quarante conges; et chacune de ces cuvettes fut placée dans l\'un des dix bassins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Hiram plaça cinq bassins du côté de l\'aile droite du temple, les cinq autres du côté de l\'aile gauche, et la mer du côté de l\'aile droite, à l\'orient vers le midi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Et Hiram fit encore les chaudières, les poêles et les coupes; enfin, il acheva tous les travaux qu\'il fit pour le roi Salomon dans le temple du Seigneur, savoir:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'les deux colonnes et les deux guirlandes pour leurs chapiteaux, et deux filets pour couvrir les deux guirlandes des cannelures qui étaient sur les colonnes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Les quatre cents grenades entremêlées dans les filets; deux rangées de grenades par filet, pour voiler les guirlandes de la coupe, en forme de lis, sur les deux colonnes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Les dix bassins et les dix cuvettes posées dans les bassins,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'La mer et les douze bœufs sous la mer;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Les chaudières, les poêles, les coupes et tous les vases que Salomon lui avait commandés pour le temple du Seigneur, et les quarante-huit colonnes du palais du roi et du temple du Seigneur. Tels furent les travaux qu\'Hiram fit en entier pour le roi Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'On ne pesa point l\'airain que l\'on y employa; la quantité en fut telle qu\'on ne put la mesurer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'On jeta l\'airain en fonte auprès du Jourdain dans une terre argileuse, entre Socchoth et Sira.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Salomon prit les ornements qu\'Hiram avait faits dans le temple du Seigneur: l\'autel d\'or, la table d\'or des pains de proposition;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Les cinq chandeliers d\'or placés à gauche, et les cinq placés à droite de la face de l\'oracle, tous d\'or et de pièces rajustées; et les petites lampes, et les luminaires, et les burettes d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Il avait fait faire aussi les panneaux des portiques, les clous, les coupes, les plats et les encensoirs d\'or, et les panneaux des portes intérieures du temple et du Saint des saints, et les portes d\'or de la nef.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Tous les travaux du temple du Seigneur que Salomon fit faire étant terminés, il transporta les objets d\'or et d\'argent consacrés par David son père, et par lui-même, et il les déposa dans le trésor du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Ensuite, Salomon fit bâtir pour lui-même un palais en treize ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Il le bâtit en cèdres du Liban; ce palais était long de cent coudées, large de cinquante, haut de trente; il avait trois rangs de colonnes de cèdre; et les traverses entre les chapiteaux étaient en cèdre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Il plafonna le palais au-dessus des colonnes; chaque rang de colonnes en comptait quarante-cinq.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Et il fit trois chambres par rangée, et elles étaient également espacées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'Il fit toutes les portes, et les intervalles formant les chambres étaient carrés, et les portes correspondaient aux portes dans les trois rangées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Il fit un vestibule de colonnes, lequel avait cinquante coudées de long et cinquante coudées de large, et se rattachait à un autre vestibule qui lui faisait face; et il y avait, sur la façade des vestibules, des colonnes très grosses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Il fit aussi le vestibule des trônes, où le roi jugeait; c\'était la galerie du jugement;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Et le palais auquel appartenaient ces vestibules et où le roi devait demeurer avait un parvis, par où on allait à ces vestibules, et construit comme eux; il fit encore le palais de la fille du Pharaon, que le roi avait épousée, de même architecture que les vestibules.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Tous ces bâtiments étaient en bonnes pierres de taille, sculptées par intervalles extérieurement, depuis le sol jusqu\'à la corniche; au dehors il y avait un grand parvis;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Ses fondations étaient de grandes et belles pierres, longues de dix et de huit coudées,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'En haut desquelles il y avait de belles pierres aussi grandes que les pierres de taille, et des cèdres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'Et il y avait autour du parvis trois rangs de pierres de taille, et un rang de cèdres sculptés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'Ainsi Salomon acheva tout son palais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Lorsqu\'au bout de vingt ans, Salomon eut achevé de bâtir le temple du Seigneur et son palais, il rassembla dans Sion tous les anciens d\'Israël pour enlever de la ville de David (la même que Sion) l\'arche de l\'alliance du Seigneur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Au mois d\'Athanin;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Et les prêtres transportèrent l\'arche,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Ainsi que le tabernacle du témoignage, et les objets consacrés dans le tabernacle du témoignage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Et le roi et tout Israël, devant l\'arche, sacrifiaient des brebis et des bœufs en quantité innombrable.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Les prêtres introduisirent l\'arche à sa place, dans l\'oracle du temple, dans le Saint des saints, sous les ailes des chérubins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Car les chérubins déployaient leurs ailes au-dessus de l\'emplacement de l\'arche, et ils en couvraient l\'arche et ses leviers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Ces leviers étaient dressés, et leurs extrémités se voyaient dès l\'entrée du Saint des saints devant l\'oracle, mais on ne pouvait les voir du dehors.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Il n\'y avait rien dans l\'arche sinon les deux tables de pierre, les tables de l\'alliance que Moïse y avait déposées sur le mont Horeb, et sur lesquelles le Seigneur avait écrit son alliance avec les fils d\'Israël lorsqu\'ils revenaient de la terre d\'Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Or, quand les prêtres sortirent du Saint des saints il advint qu\'une nuée remplit le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Et les prêtres ne purent y demeurer, ni faire le service divin, à cause de la nuée; car la gloire du Seigneur avait rempli le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Et les prêtres ne purent y demeurer, ni faire le service divin, à cause de la nuée; car la gloire du Seigneur avait rempli le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Et les prêtres ne purent y demeurer, ni faire le service divin, à cause de la nuée; car la gloire du Seigneur avait rempli le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Alors, le roi se retourna vers le peuple, et il bénit tout Israël, et toute l\'Église d\'Israël était restée debout.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Et il dit: Béni soit aujourd\'hui le Seigneur Dieu d\'Israël, qui, de sa bouche, a parlé concernant David mon père, et qui de ses mains a rempli ses promesses, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Depuis le jour où j\'ai tiré de l\'Égypte mon peuple Israël, je n\'ai choisi en Israël ni ville, ni tribu, pour qu\'on bâtit un temple où résidât mon Nom; puis, j\'ai choisi Jérusalem pour que mon nom y réside, et j\'ai choisi David pour qu\'il soit sur mon peuple Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Or, mon père avait en son cœur la pensée de bâtir un temple au nom du Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Et le Seigneur dit à David, mon père: En récompense de ce que la pensée t\'est venue au cœur de bâtir un temple à mon nom, tu as fait de belles actions, parce que cette pensée était en ton cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Néanmoins, tu ne bâtiras point ce temple, mais ton fils, qui sortira de toi, le bâtira à mon nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Le Seigneur a relevé la parole qu\'il avait dite, j\'ai été suscité à la place de David mon père; et je me suis assis sur le trône d\'Israël, comme l\'avait dit le Seigneur; et j\'ai bâti un temple au nom du Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'J\'y ai préparé un emplacement pour l\'arche qui renferme l\'alliance du Seigneur avec nos pères, tandis qu\'il les ramenait de la terre d\'Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Ensuite, Salomon se tint devant l\'autel du Seigneur et devant toute l\'Église d\'Israël; il étendit les deux mains vers le ciel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Et il dit: Seigneur Dieu d\'Israël, il n\'est point au ciel ni sur la terre de Dieu tel que vous, gardant alliance et miséricorde pour le serviteur qui marche de tout son cœur devant vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Vous avez gardé cette alliance et cette miséricorde, pour votre serviteur David; car vous avez parlé de votre bouche, et de vos mains vous avez rempli vos promesses; comme il se voit aujourd\'hui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Maintenant, Seigneur Dieu d\'Israël, gardez pour votre serviteur David, mon père, cette parole que vous lui avez dite: Il ne manquera jamais d\'hommes de ton sang pour être assis sur le trône d\'Israël devant ma face, pourvu que les enfants observent leurs voies, et qu\'ils marchent à mes yeux comme toi-même as marché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Maintenant, Seigneur Dieu d\'Israël, que votre promesse à David mon père, votre serviteur, soit confirmée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Est-il donc croyable que Dieu réside sur la terre parmi les hommes? Si le ciel et le ciel des cieux ne peuvent vous contenir, combien moins encore ce temple que j\'ai bâti à votre nom?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'O Seigneur Dieu d\'Israël, ayez égard à ma demande; écoutez aujourd\'hui la prière que vous fait votre serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Que vos yeux soient ouverts nuit et jour sur ce temple, sur ce lieu dont vous avez dit: C\'est là que sera mon nom; et écoutez-y la prière que vous y fait nuit et jour votre serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Oui, vous écouterez la prière de votre serviteur et de votre peuple Israël, toutes les fois qu\'ils prieront en ce lieu; vous les entendrez du lieu que vous habitez au ciel; et vous agirez, et vous serez indulgent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Quelque péché qu\'un homme ait commis contre son prochain, même quand il aura songé à le maudire, s\'il vient, s\'il se confesse, dans le temple devant votre autel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Du haut du ciel vous l\'entendrez et vous agirez, et vous jugerez le peuple d\'Israël, de telle sorte que l\'inique sera considéré comme inique; que vous ferez retomber sur sa tête son égarement dans ses voies, que le juste sera justifié, et que vous le rétribuerez selon son équité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Lorsque votre peuple Israël tombera devant ses ennemis parce qu\'il aura péché contre vous, ils se convertiront, ils rendront gloire au nom du Seigneur; ils prieront, et ils supplieront en votre temple:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Alors, du haut du ciel vous les écouterez, vous leur remettrez leurs péchés, et vous les ramènerez dans la terre que vous avez donnée à leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Lorsque vous aurez fermé le ciel, et qu\'il n\'y aura plus de pluie parce que les fils d\'Israël auront péché contre vous, ils prieront en ce lieu; ils rendront gloire au nom du Seigneur, et ils détesteront leurs péchés, après que vous les aurez humiliés,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Et du haut du ciel vous les écouterez, et vous remettrez les péchés de vos serviteurs, de votre peuple; vous leur montrerez la bonne voie qu\'ils doivent suivre, et vous accorderez de la pluie à la terre que vous avez donnée pour héritage à votre peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Lorsqu\'il y aura famine, lorsqu\'il y aura mortalité par suite de la chaleur brûlante ou du ravage des sauterelles, lorsqu\'il y aura rouille des blés, lorsqu\'un ennemi opprimera le peuple en l\'une de ses villes, lorsqu\'il y aura partout accident et peine,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Toute prière, toute supplication que l\'homme vous fera dans le temple les mains étendues, après avoir reconnu la plaie de son cœur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Vous l\'écouterez du haut du ciel, du lieu où est votre demeure; vous serez miséricordieux, vous agirez et vous rétribuerez l\'homme selon sa voie, selon ce que vous aurez vu dans son cœur, car vous seul connaissez le cœur de tous les fils des hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Ainsi auront-ils crainte de vous tout le temps qu\'ils vivront en la terre que vous avez donnée à nos pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Lorsque l\'étranger qui n\'est point de votre peuple,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'Entrera aussi et priera dans ce lieu,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Du haut du ciel, du lieu où est votre demeure, vous accomplirez tout ce que vous aura demandé l\'étranger, afin que tous les peuples connaissent votre nom, qu\'ils aient crainte de vous comme le peuple d\'Israël, et qu\'ils sachent que votre nom est invoqué dans ce temple que j\'ai bâti.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Si votre peuple va en guerre contre ses ennemis dans une voie où vous lui ferez prendre la fuite, il invoquera le nom du Seigneur en se tournant vers la ville que vous vous êtes choisie, et vers le temple que j\'ai bâti à votre nom,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Et, du haut du ciel, vous écouterez sa demande et sa prière, et vous rendrez sur lui votre jugement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Ils pècheront contre vous, car il n\'est point d\'homme qui ne pèche, et vous les emmènerez, vous les livrerez à leurs ennemis, et les captifs seront conduits en une terre voisine ou lointaine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'Et, dans la terre où on les aura conduits, ils convertiront leurs cœurs, ils se repentiront dans le lieu de leur exil, et ils vous prieront, disant: Nous avons péché, nous avons été déréglés et iniques.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'Et ils reviendront à vous de tout leur cœur, de toute leur âme, en la demeure de leurs ennemis où vous les aurez transportés; et ils vous prieront, tournés vers la terre que vous avez donnée à leurs pères, vers la ville que vous vous êtes choisie, et vers ce temple que j\'ai bâti au nom du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Et du haut du ciel, du lieu où est votre demeure, vous les écouterez,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Vous leur remettrez leurs iniquités, leurs péchés contre vous, et toutes leurs prévarications; vous leur accorderez d\'exciter la compassion des ennemis qui les retiendront en captivité, et ceux-ci leur feront miséricorde.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Car c\'est votre peuple, c\'est votre héritage, que vous avez tiré de la terre d\'Égypte, du milieu d\'une fournaise de fer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Que vos yeux, que vos oreilles, restent ouverts à la prière que vous fait votre serviteur, à la prière que vous fait votre peuple Israël; écoutez-les en toutes les choses pour lesquelles ils vous invoqueront.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Car c\'est vous qui les avez mis à part, entre tous les autres peuples, pour être votre héritage, comme vous l\'aviez promis à Moïse, lorsque vous avez ramené nos pères de la terre d\'Égypte, Seigneur, ô Seigneur. Alors, Salomon parla du temple qu\'il avait fait bâtir; il fit connaître le soleil dans le ciel: Le Seigneur a voulu habiter dans une nuée ténébreuse; bâtis-moi, a-t-il dit, un temple, une demeure magnifique pour que j\'y habite d\'une manière nouvelle. {Voici n\'est-ce pas écrit dans le livre des hymnes?}');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Lorsque Salomon eut achevé toute cette prière, cette oraison au Seigneur, il se tint debout après s\'être agenouillé devant l\'autel du Seigneur; puis, les mains étendues vers le ciel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Debout, il bénit à haute voix toute l\'Église d\'Israël, et il dit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Béni soit aujourd\'hui le Seigneur qui a donné la paix à Israël son peuple, selon tout ce qu\'il avait dit! Nulle de ses paroles ne s\'est trouvée en défaut parmi toutes les bonnes paroles qu\'il avait dites par la bouche de Moïse, son serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Puisse le Seigneur Dieu être avec nous comme il a été avec nos pères, puisse-t-il ne nous jamais abandonner, et ne nous point détourner');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'D\'incliner vers lui nos cœurs, de marcher dans toutes ses voies et d\'observer tous ses commandements, tous les préceptes qu\'il a donnés à nos pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Puissent ces prières que je viens de faire ici devant le Seigneur notre Dieu être près de lui nuit et jour, qu\'elles donnent la justice à votre serviteur, et à votre peuple Israël, à jamais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Afin que tous les peuples de la terre sachent que le Seigneur Dieu est le seul Dieu, et qu\'il n\'y a point d\'autre Dieu que lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Puissent nos cœurs être parfaits devant le Seigneur notre Dieu, marcher saintement dans ses préceptes, et observer ses commandements, comme aujourd\'hui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Ensuite, le roi et tous les fils d\'Israël immolèrent des victimes devant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Et le roi Salomon sacrifia des hosties pacifiques et les offrit au Seigneur: vingt-deux mille bœufs, cent vingt mille brebis; puis, le roi et tous les fils d\'Israël firent la dédicace du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Ce jour-là, le roi consacra le milieu du parvis devant la façade du temple; car c\'est là qu\'il fit les holocaustes et les sacrifices, et qu\'il brûla la graisse des hosties pacifiques, parce que l\'autel d\'airain dressé devant le Seigneur était trop petit pour suffire aux holocaustes et aux hosties pacifiques.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Et le roi Salomon, ce jour-là, commença la fête, et avec lui tout Isarël, une immense assemblée accourue depuis les gorges d\'Emath jusqu\'au fleuve d\'Égypte, devant le Seigneur notre Dieu, au temple qu\'on lui avait bâti; ils mangeaient, buvaient et se réjouissaient devant le Seigneur notre Dieu, pendant sept jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Et le huitième jour, Salomon congédia le peuple, et ils bénirent le roi. Et chacun s\'en retourna en sa demeure plein de joie, le cœur pénétré des biens que le Seigneur avait accordés à David son serviteur, ainsi qu\'à Israël son peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Après que Salomon eut achevé de bâtir le temple du Seigneur et le palais du roi, et tout ce qu\'il avait eu dessein de construire,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Le Seigneur apparut une seconde fois à Salomon, comme en Gabaon déjà il lui était apparu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Et le Seigneur lui dit: J\'ai entendu ta prière et les oraisons que tu as faites devant moi; et je t\'ai accordé tout ce que tu avais demandé, j\'ai sanctifié ce temple que tu as bâti pour que mon nom y résidât à jamais; mes yeux et mon cœur y seront toujours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Pour toi, si tu marches devant moi, comme a marché David ton père, en droiture et sainteté de cœur, pour agir selon tout ce que je t\'ai ordonné; si tu observes mes commandements et mes ordonnances,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Je maintiendrai à jamais ton trône sur Israël comme je l\'ai promis à David ton père, disant: Jamais il ne manquera d\'hommes issus de toi pour régner sur Israël;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Mais si vous et vos enfants vous détournez de moi, si vous n\'observez point les commandements et les ordonnances que Moïse vous a fait connaître; si vous suivez, si vous servez d\'autres dieux, si vous les adorez,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'J\'enlèverai Israël de la terre où je l\'ai établi; le temple que j\'ai sanctifié par mon nom, je le rejetterai de devant ma face; Israël sera, parmi tous les peuples, comme une chose effacée, comme un sujet de moquerie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Ce temple si haut sera en un tel état, que le passant, frappé de stupeur, sifflera et dira: Pourquoi donc le Seigneur a-t-il ainsi traité cette terre et ce temple?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Et on lui répondra: C\'est pour avoir abandonné le Seigneur leur Dieu, qui avait ramené leurs pères de l\'Égypte, et de la maison de servitude; ils se sont attachés à des dieux étrangers, ils les ont adorés, et les ont servis; voilà pourquoi le Seigneur a fait retomber sur eux leurs propres crimes. Or, le roi Salomon avait déjà conduit la fille du Pharaon de la ville de David au palais qu\'en ces temps-là il s\'était bâti.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Pendant les vingt ans qu\'il mit à construire les deux édifices, le temple du Seigneur et le palais du roi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Hiram, roi de Tyr, vint en aide à Salomon en lui donnant des cèdres et des sapins, de l\'or et tout ce qu\'il voulut; en échange le roi donna à Hiram vingt villes de la province de Galilée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Et Hiram sortit de Tyr, et alla en Galilée pour voir les villes que lui avait données Salomon; mais elles ne lui plurent pas,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Et il dit: Que sont ces villes que tu m\'as données, frère? Et il les appela Orion, nom qu\'elles portent encore de nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Ensuite, Hiram apporta à Salomon cent vingt talents d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'C\'est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d\'Elath, sur le rivage de la mer Rouge, en la terre d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Et le roi Hiram envoya sur le vaisseau des serviteurs, matelots exercés à naviguer sur mer, qui s\'embarquèrent avec les serviteurs de Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Et ils allèrent à Ophir; et ils y prirent cent vingt talents d\'or, et ils les apportèrent au roi Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Et la reine de Saba ouït le nom de Salomon et le nom du Seigneur, et elle vint pour éprouver le roi en lui proposant des énigmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Elle entra dans Jérusalem avec une suite nombreuse, et des chameaux chargés de parfums et d\'une immense quantité d\'or et de pierres précieuses; elle fut introduite auprès de Salomon, et elle lui dit toutes les choses qu\'il y avait en son cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Salomon l\'éclaira sur toutes ses questions; il n\'y eut pas une de ses questions à laquelle le roi négligeât de répondre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Et la reine de Saba vit toute la sagesse de Salomon, le palais qu\'il avait bâti,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Les mets de sa table, les logements de ses serviteurs, la tenue de ses officiers, ses vêtements, ses échansons, et les holocaustes qu\'il offrait dans le temple du Seigneur, et elle en fut hors d\'elle-même.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Et elle dit au roi Salomon: C\'était la vérité qu\'on m\'avait dite en mon pays,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Au sujet de ton éloquence et de ta sagesse; j\'avais refusé de croire ce qu\'on m\'en avait rapporté, jusqu\'à ce que je fusse venue moi-même et que j\'eusse vu de mes yeux; et je reconnais qu\'on ne m\'avait point appris la moitié de ce qui réellement existe. Tu as beaucoup ajouté aux merveilles dont j\'avais ouï parler chez moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Heureuses tes femmes, heureux tes serviteurs qui sont toujours auprès de toi, et qui recueillent toute ta sagesse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Béni soit le Seigneur ton Dieu qui s\'est complu en toi, pour te donner le trône d\'Israël, parce que le Seigneur Dieu aime ce peuple, et qu\'il l\'affermira pour toujours. Le Seigneur t\'a fait leur roi pour que les jugements soient selon la justice et selon l\'équité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Elle donna à Salomon cent vingt talents d\'or, et une immense quantité d\'épices et de pierres précieuses. Il n\'était jamais arrivé à Jérusalem autant d\'épices que la reine de Saba en donna au roi Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Et le vaisseau d\'Hiram qui avait transporté l\'or d\'Ophir, apporta une énorme quantité de bois rares et de pierres précieuses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Et le roi fit avec les bois des balustrades pour le temple et le palais; puis, des lyres et des harpes pour les chanteurs. Il n\'était jamais arrivé de tels bois rares en la terre promise, et l\'on n\'en avait vu nulle part avant ce jour-là.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Et le roi Salomon donna à la reine de Saba tout ce qu\'elle voulut, tout ce qu\'elle lui demanda, outre ce qu\'il lui donna spontanément. Et elle s\'en alla, et elle retourna en sa contrée avec tous ses serviteurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Et le poids de l\'or, qui arriva au roi Salomon en une année, fut de six cent soixante-six talents,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Sans compter les tributs de ceux qui lui étaient soumis, marchands, rois de la rive gauche de l\'Euphrate, ou princes de la terre promise.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Et Salomon fit faire trois cents javelines d\'or battu, chacune de trois cents sicles d\'or,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Et trois cents armures d\'or battu, de trois mines d\'or chacune; et il les consacra dans le palais de bois du Liban.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Il fit faire aussi un grand trône d\'ivoire, qu\'il revêtit de lames d\'or très fin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'On montait sur le trône par six degrés; il y avait des faces de taureaux derrière le trône, deux bras des deux côtés du siège et deux lions auprès des bras.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Il y avait douze lions sur les degrés, six à droite, six à gauche; on ne voyait rien de semblable dans aucun royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Et tous les vases dont se servait Salomon étaient d\'or, ses baignoires étaient d\'or; tous les meubles du palais de bois du Liban étaient d\'or et de pièces rapportées. On n\'y voyait point d\'argent; car ce métal était compté pour rien du temps de Salomon; Et cela parce que Salomon avait un vaisseau de Tharsis à la mer, avec la flotte d\'Hiram; tous les trois ans un vaisseau venait de Tharsis chargé d\'or, d\'argent et de pierres rares et travaillées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Voici l\'emploi des richesses que le roi amassa: Il bâtit le temple du Seigneur, son propre palais, les remparts de Jérusalem, la citadelle qui renfermait l\'enceinte de la ville de David, Assur, Magdal, Gazer, Béthoron-la-Haute, Jéthermuth, toutes les villes des chars et toutes les villes des cavaliers; il éleva des constructions tant à Jérusalem que dans la terre promise, pour prévenir les séditions des peuples qu\'on avait épargnés, de l\'Hettéen, de l\'Amorrhéen, du Phérézéen, du Chananéen, de l\'Evéen et du Jébuséen, de tous ceux qui n\'étaient point du sang d\'Israël, et dont les fils vivaient dans la terre promise, parce que les fils d\'Israël n\'avaient pu les exterminer; Salomon les avait obligés à payer un tribut qu\'ils paient encore de nos jours. Or, Salomon n\'exigeait rien des fils d\'Israël, parce qu\'ils étaient ses guerriers, ses serviteurs, ses chefs, les intendants de ses chars et ses cavaliers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Et Salomon fut grand en science et en richesses par-dessus tous les rois de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Tous les rois de la terre demandèrent à le voir, et à entendre la sagesse que Dieu avait mise en son cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Et, chaque année, ils lui apportaient tous des présents des vases d\'or, des vêtements, de la myrrhe, des épices, des chevaux et des mules.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomon avait, pour ses chars, quatre mille cavales, et dix mille chevaux pour ses cavaliers; il les avait mis dans les villes des chars ou auprès de lui à Jérusalem, et il était chef de tous les rois depuis l\'Euphrate jusqu\'au territoire des Philistins et aux frontières de l\'Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Et le roi rendit à Jérusalem l\'or et l\'argent aussi communs que les pierres; il y amena autant de cèdres qu\'il y a de mûriers dans les champs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Salomon tirait des chevaux de l\'Égypte; il y avait à Thécoé un marché royal, et on les allait prendre à Thécoé à prix d\'argent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'L\'attelage d\'un char, venant d\'Égypte, coûtait cent sicles d\'argent et cinquante sicles par cheval. Il en était de même pour tous les rois des Hettéens et de la Syrie; ces achats venaient par mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 30, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 31, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 32, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 33, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Et le roi Salomon aimait les femmes. Il avait sept cents femmes princesses et trois cents concubines. Il avait épousé des femmes étrangères: la fille du Pharaon, puis des Moabites, des Ammonites, des Syriennes, des Iduméennes, des Hettéennes et des Amorrhéennes,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Des femmes de ces peuples dont le Seigneur avait dit aux fils d\'Israël: « Vous n\'aurez point avec eux de commerce, ni eux avec vous, de peur qu\'ils ne détournent vos cœurs vers leurs idoles. » Salomon s\'était attaché à elles, il les aimait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Et, au temps de sa vieillesse, son cœur ne fut point parfait à l\'égard du Seigneur son Dieu, comme le cœur de David, son père. Car les femmes étrangères détournèrent son cœur vers leurs dieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Et, au temps de sa vieillesse, son cœur ne fut point parfait à l\'égard du Seigneur son Dieu, comme le cœur de David, son père. Car les femmes étrangères détournèrent son cœur vers leurs dieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Alors, Salomon bâtit un haut lieu à Chamos, idole de Moab; à leur roi, idole des fils d\'Ammon,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Et à Astarté, abomination des Sidoniens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'A toutes ses femmes étrangères, il accorda de sacrifier à leurs idoles et de les encenser.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Et Salomon fit le mal devant le Seigneur; il ne suivit point le Seigneur, comme l\'avait suivi David, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Et le Seigneur se courrouça contre Salomon, parce qu\'il avait détourné son cœur du Seigneur Dieu d\'Israël qui lui était apparu deux fois,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'Et lui avait expressément commandé de ne jamais suivre d\'autres dieux, d\'être attentif à faire tout ce qu\'avait prescrit le Seigneur Dieu; en effet, son cœur n\'était point parfait à l\'égard du Seigneur, comme le cœur de David, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Et le Seigneur dit à Salomon: En punition de ce que tu as agi de la sorte et n\'as point gardé mes commandements et mes ordonnances que je t\'avais donnés, je déchirerai dans tes mains ton royaume, et j\'en donnerai une part à ton serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Seulement, à cause de David, ton père, je ne ferai point ces choses de ton vivant; je retirerai des mains de ton fils cette part du royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Car je ne le lui prendrai pas tout entier; je laisserai un sceptre à ton fils, à cause de David, mon serviteur, et à cause de Jérusalem, ville que j\'ai choisie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Et le Seigneur avait suscité des satans contre Salomon: Ader l\'Iduméen et Esron, fils d\'Eliadaé de Raama, jadis serviteur d\'Adadézer, roi de Suba; ils avaient rassemblé des hommes contre lui, et Ader, chef de cette troupe, avait pris Damas; il fut l\'ennemi d\'Israël tant que vécut Salomon, et il était de la famille des rois de l\'Idumée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Or, ceci était advenu: Dans le temps que David exterminait Edom, et que Joab, général de son armée, était à ensevelir les morts, car ils frappaient tous les mâles dans l\'Idumée,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(Joab y passa six mois avec tout Israël, jusqu\'à ce qu\'ils eussent détruit tous les mâles de l\'Idumée.)');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Ader s\'enfuit emmenant avec lui tous les Iduméens, serviteurs de son père; il se réfugia en Égypte, alors petit enfant;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Et des hommes de la ville de Madian s\'étaient soulevés; quand Ader et les siens entrèrent dans Pharan, prirent avec eux les hommes, et allèrent chez le Pharaon, roi d\'Égypte. Ader fut introduit auprès du Pharaon; le roi lui donna une demeure, et lui assigna des vivres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Et Ader trouva grâce devant le Pharaon, et le roi lui fit épouser la sœur de sa femme Thécémina, la sœur aînée de Thécémina.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Cette sœur de Thécémina enfanta pour Ader un fils nommé Ganebath, que Thécémina éleva avec les fils du Pharaon; Ganebath était donc parmi les fils du Pharaon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Lorsque Ader apprit en Égypte que David dormait auprès de ses pères, et que Joab, général de son armée, était mort; il dit au Pharaon: Congédie-moi, et je retournerai dans mon pays.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Et le Pharaon répondit à Ader: Que te manque-t-il parmi nous? Pourquoi demandes-tu à retourner en ton pays? Ader reprit: Je désire que tu me congédies. Et il revint en sa contrée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Voilà d\'où venait la méchanceté d\'Ader, il contristait Israël et il régnait sur Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Voilà d\'où venait la méchanceté d\'Ader, il contristait Israël et il régnait sur Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Voilà d\'où venait la méchanceté d\'Ader, il contristait Israël et il régnait sur Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Or, Jéroboam, fils de Nabat l\'Ephrathéen de Sarira, fils d\'une femme veuve, était serviteur de Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Voici à quelle occasion il leva les mains contre le roi son maître. Le roi Salomon était à bâtir la citadelle, et il entourait de murs l\'enceinte de la ville de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Jéroboam était vaillant, et Salomon discerna que le jeune serviteur était un homme d\'action, et il le nomma intendant des tributs de la maison de Joseph.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'En ce temps-là, Jéroboam sortit de Jérusalem, et il fut rencontré sur la route par Achias, le prophète silonite. Achias se détourna du chemin, et Achias était enveloppé d\'un manteau neuf; ils étaient seuls tous les deux dans les champs,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Et Achias ôta son manteau neuf et le déchira en douze parts,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Et il dit à Jéroboam: Prends pour toi dix de ces lambeaux; car voici ce que dit le Seigneur Dieu d\'Israël: Je déchirerai entre les mains de Salomon son royaume, et je te donnerai dix tribus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Et il lui restera deux tribus, à cause de mon serviteur David, et à cause de Jérusalem, ville que j\'ai choisie parmi toutes les tribus d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'C\'est en punition de ce qu\'il m\'a abandonné; de ce qu\'il a sacrifié à Astarté, abomination des Sidoniens, à Chamos, aux idoles de Moab et à leur roi, abomination des fils d\'Ammon, et de ce qu\'il n\'a point marché en toutes mes voies pour faire devant moi ce qui est droit, comme l\'a fait David, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Toutefois, je ne retirerai point de sa main le royaume entier; je le lui laisserai même tout le reste de sa vie, à cause de David, son père, mon élu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Mais je prendrai le royaume des mains de son fils, et je te donnerai dix tribus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Et je laisserai à son fils deux tribus, afin qu\'il y ait toujours devant moi, pour mon serviteur David, un trône en Jérusalem, dans la ville que je me suis choisie pour que mon nom y résidât.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Pour toi, je te prendrai, et tu règneras comme le désire ton âme; tu seras roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Et, si tu observes tout ce que je t\'ordonnerai, si tu marches en mes voies, si tu fais devant moi ce qui est droit, en gardant mes commandements et mes ordonnances, comme a fait David, mon serviteur, je serai avec toi, et je te bâtirai une maison sûre, de même que j\'en ai bâti une pour David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Et Salomon chercha à faire périr Jéroboam; mais il partit, et s\'enfuit auprès de Sésac, roi d\'Égypte, et il y demeura jusqu\'à la mort de Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Et Salomon chercha à faire périr Jéroboam; mais il partit, et s\'enfuit auprès de Sésac, roi d\'Égypte, et il y demeura jusqu\'à la mort de Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Le reste de l\'histoire de Salomon, tout ce qu\'il a fait, toute sa sagesse, ne sont-ils pas écrits au livre de la vie de Salomon?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Salomon régna quarante ans sur tout Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Et il s\'endormit avec ses pères, et on l\'ensevelit en la ville de David. Dès que Jéroboam, fils de Nabat, l\'apprit, comme il était encore en Égypte, où il s\'était établi pour éviter la colère de Salomon, il revint à sa ville, en la terre de Sarira, dans la montagne d\'Ephraïm. Le roi Salomon s\'était endormi avec ses pères, et Roboam, son fils, régnait à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 44, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Alors, le roi Roboam se rendit à Sichem, parce que tout Israël y était venu pour le proclamer roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Et le peuple parla au roi Roboam, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Et le peuple parla au roi Roboam, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Ton père a rendu pesant notre joug; allège donc maintenant la servitude trop dure de ton père; que notre joug soit moins lourd, et nous te servirons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Et il leur dit: Allez-vous-en pendant trois jours; puis, revenez près de moi, et ils s\'en allèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Et le roi consulta les anciens qui, du vivant de Salomon, son père, se tenaient auprès de lui, disant: Que me conseillez-vous de répondre à ce peuple?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Ils lui dirent: Si aujourd\'hui tu te montres le serviteur de ce peuple, si tu te montres agréable pour lui, si tu lui dit de bonnes paroles, ils seront tes serviteurs tous les jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Mais il dédaigna le conseil que les anciens lui avaient donné, et il consulta les jeunes gens élevés avec lui, et qui se tenaient auprès de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Et il leur dit: Que me conseillez-vous? Que dois-je répondre à ce peuple qui me dit: Allège le joug que nous a mis ton père?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Or, les jeunes gens élevés avec lui, et qui se tenaient auprès de lui, dirent: Tu diras ces choses à ce peuple qui t\'a dit: Ton père a rendu pesant notre joug, maintenant donc, allège-le, tu leur diras ces choses: Mon petit doigt est plus gros que les reins de mon père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Mon père vous a chargés d\'un joug pesant, je le rendrai pour vous plus pesant encore. Mon père vous a châtiés à coups de fouet, moi je vous châtierai avec des scorpions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Or, tout Israël se réunit autour du roi Roboam, le troisième jour, comme il le leur avait prescrit, disant: Revenez dans trois jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Et le roi leur répondit durement, car il avait dédaigné le conseil que les anciens lui avaient donné.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Et il leur parla selon le conseil des jeunes gens, et il leur dit: Mon père vous a chargés d\'un joug pesant, je le rendrai pour vous plus pesant encore; mon père vous a châtiés à coups de fouet, je vous châtierai avec des scorpions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Et le roi n\'avait point écouté les fils d\'Israël, parce que le Seigneur s\'était tourné contre lui, afin de confirmer la parole qu\'il avait dite concernant Jéroboam, fils de Nabat, par Achias le Silonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Quand Israël vit que le roi ne l\'avait pas écouté, le peuple répondit au roi: Qu\'y a-t-il entre nous et David? Notre héritage ne dépend pas du fils de Jessé. Hâte-toi, ô Israël! de retourner en tes demeures; et toi, David, nourris ta maison. Et Israël s\'en alla chacun en sa demeure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Alors, le roi leur envoya Adonisam, intendant des impôts; ils le lapidèrent, il mourut; et le roi Roboam s\'empressa de fuir pour se renfermer dans Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Alors, le roi leur envoya Adonisam, intendant des impôts; ils le lapidèrent, il mourut; et le roi Roboam s\'empressa de fuir pour se renfermer dans Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Et jusqu\'à nos jours la maison de David a été rejetée par Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Et tout Israël apprit que Jéroboam était revenu d\'Égypte, et ils l\'envoyèrent chercher pour venir à l\'assemblée; ils le proclamèrent roi d\'Israël, et il ne resta plus à la maison de David que les tribus de Juda et de Benjamin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Cependant, Roboam était entré à Jérusalem; il réunit la synagogue de Juda et la tribu de Benjamin, cent vingt mille jeunes gens allant à la guerre, afin de combattre Israël, et de recouvrer la royauté pour le fils de Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Mais la parole du Seigneur vint à Samaïas, homme de Dieu, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Parle à Roboam, fils de Salomon, roi de Juda, à toute la maison de Juda, à Benjamin et au reste du peuple, dis-leur:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Voici ce que dit le Seigneur: Ne partez pas, ne combattez point vos frères, les fils d\'Israël; retournez chacun en votre demeure, car cette chose est de moi. Ils obéirent à la parole du Seigneur, et, selon son ordre, ils renoncèrent à marcher. Ainsi, le roi Salomon s\'était endormi avec ses pères; il avait été enseveli auprès d\'eux dans la ville de David; et Roboam, son fils, régnait à sa place en Jérusalem. Il avait seize ans quand il monta sur le trône, et il régna douze ans à Jérusalem. Sa mère se nommait Naanan, fille d\'Ana, fils de Naas, roi des fils d\'Ammon. Il fit le mal devant le Seigneur, et il ne marcha point en la voie de David, son aïeul. Or, il y avait un homme de la montagne d\'Ephraïm, serviteur de Salomon, et son nom était Jéroboam, et sa mère, femme prostituée, s\'appelait Sarira. Salomon le nomma chef, et lui donna le bâton de commandement pour recueillir les tributs de la maison de Joseph. Il bâtit, pour Salomon, Sarira, dans la montagne d\'Ephraïm; et il avait trois cents chars traînés par des chevaux. C\'est lui qui éleva la citadelle avec les impôts de la maison d\'Ephraïm; c\'est lui aussi qui entoura de murs la ville de David, et il s\'enorgueillit jusqu\'à désirer la royauté. Alors, Salomon tenta de le mettre à mort; il eut crainte, il se réfugia chez Sésac, roi d\'Égypte, et il demeura près de lui jusqu\'à la mort de Salomon. Jéroboam apprit en Égypte que Salomon était mort, et il s\'ouvrit à Sésac, roi d\'Égypte, disant: Congédie-moi, et je retournerai en mon pays. Sésac répliqua: Demande-moi ce que tu désires, et je te l\'accorderai. Or, Sésac avait donné pour femme à Jéroboam Ano, sœur aînée de Thécémina, sa femme. Elle était grande parmi les filles du roi, et elle avait enfanté pour Jéroboam Abias, son fils. Jéroboam dit donc à Sésac: il faut que tu me congédies, et je partirai. Jéroboam sortit, en effet, de l\'Égypte, et il revint dans la terre de Sarira, de la montagne d\'Ephrem, et il y réunit toute la tribu d\'Ephraïm, et il y bâtit une forteresse. En ce temps-là, son fils fut atteint d\'une violente maladie, et Jéroboam partit pour consulter au sujet de l\'enfant, et il dit à Ano, sa femme: Lève- toi, viens, et consulte Dieu au sujet de l\'entant; demande s\'il vivra, et s\'il guérira de sa maladie. Or, il y avait en Silom un homme appelé Achias, âgé de soixante ans; la parole du Seigneur était en lui. Et Jéroboam dit à sa femme: Lève-toi, prends en tes mains des pains pour l\'homme de Dieu, des gâteaux pour ses enfants, du raisin et un pot de miel. La femme se leva, elle prit en ses mains des pains, deux gâteaux, du raisin et un pot de miel pour Achias. Or, l\'homme était vieux, et ses yeux obscurcis voyaient difficilement. Ano partit de Sarira, et elle se mit en marche. Comme elle entrait dans la ville où demeurait Achias le Silonite, le vieillard dit à son serviteur: Cours à la rencontre d\'Ano, femme de Jéroboam, et dis-lui: Entre, et ne t\'arrête pas. Voici ce que dit le Seigneur: Je t\'envoie des malheurs. Ano fut introduite auprès de l\'homme de Dieu, et Achias lui dit: Pourquoi m\'as-tu apporté des pains, du raisin, des gâteaux et un pot de miel? Voici ce que dit le Seigneur: Tu vas t\'éloigner de moi, et ceci adviendra: Quand tu seras arrivée en la ville de Sarira, tes servantes viendront à ta rencontre, et elles te diront: L\'enfant est mort. Car, voici ce qui dit le Seigneur: Je détruirai les mâles nés de Jéroboam; il y aura, dans la ville, des morts issus de Jéroboam; les chiens les dévoreront; et celui qui mourra dans les champs, les oiseaux du ciel le mangeront. Et on va se lamenter au sujet de l\'enfant, on dira: Malheur à moi! Seigneur, parce qu\'en lui s\'est trouvée la bonne parole du Seigneur. La femme, après l\'avoir ouï, s\'en alla; et, comme elle arrivait à Sarira, l\'enfant mourut; on l\'accueillit avec des cris de douleur. Après cela, Jéroboam alla à Sichem, en la montagne d\'Ephraïm; il y rassembla les tribus d\'Israël, et Roboam, fils de Salomon, s\'y rendit. Et la parole du Seigneur vint à Samaïas fils d\'Enlami, disant: Prends avec toi un manteau neuf sur lequel la pluie n\'est pas encore tombée, déchire-le en douze parts et présente-le à Jéroboam, disant: Voici ce que dit le Seigneur: Prends pour toi dix de ces lambeaux pour t\'en revêtir. Jéroboam les prit, et Samaïas dit: C\'est là ce que dit le Seigneur, concernant les dix tribus d\'Israël. Le peuple a dit à Roboam, fils de Salomon: Ton père a rendu pesant notre collier, et il a augmenté le poids des mets de sa table; maintenant donc, allège ce qui nous grève, et nous te servirons. Et Roboam a dit au peuple: Encore trois jours, et je vous répondrai; puis, Roboam dit à ses serviteurs: Amenez-moi les anciens, et je tiendrai conseil avec eux sur ce que je devrai répondre au peuple dans trois jours. Roboam répéta aux anciens les paroles du peuple, et les anciens du peuple s\'écrièrent: Le peuple a bien parlé. Mais Roboam dispersa leur assemblée qui ne lui était pas agréable; il fit venir, et l\'on introduisit ceux qui avaient été élevés avec lui, et il leur dit: Le peuple m\'a dit telle et telle chose, et il répéta les paroles du peuple. Aussitôt les jeunes gens s\'écrièrent: Voici ce qu\'il faut répondre au peuple: Mon petit doigt est plus gros que les reins de mon père; mon père vous a fait marcher à coups de fouet, moi je vous commanderai avec des scorpions. Ces paroles plurent à Roboam, et il répondit au peuple selon ce que lui avaient suggéré les jeunes gens élevés avec lui. Et le peuple, comme un seul homme, chacun s\'adressant à son voisin, s\'écria: Qu\'y a-t-il entre nous et David? Notre héritage ne dépend pas du fils de Jessé; retournons tous en nos demeures, ô Israël! car cet homme n\'est point notre chef ni notre roi. Tout le peuple sortit donc de Sichem et se dispersa; chacun retourna en sa demeure. Roboam ne perdit point courage; Il partit, et, étant monté sur son char, il rentra dans Jérusalem. Et toute la tribu de Juda, toute la tribu de Benjamin le suivirent. Au commencement de l\'année, Roboam rassembla tous les gens de guerre de Juda et de Benjamin, et il partit pour combattre Jéroboam à Sichem. Et la parole du Seigneur vint à Samaïas, homme de Dieu, disant: Parle à Roboam, roi de Juda, et à toute la maison de Juda, à Benjamin et à tout le reste du peuple, dis-leur: Voici ce que dit le Seigneur: Ne partez point, ne combattez pas vos frères, les fils d\'Israël; retournez chacun en votre demeure, car cette chose est de moi; et ils obéirent à la parole du Seigneur; et, selon son ordre, ils renoncèrent à marcher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Ensuite, Jéroboam rebâtit Sichem en la montagne d\'Ephraïm, et il y demeura; puis, il sortit, et il bâtit Pharmel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Et Jéroboam se dit en son cœur: La royauté va retourner à la maison de David;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Si ce peuple continue de faire des sacrifices dans le temple du Seigneur à Jérusalem, le cœur du peuple retournera au Seigneur et à son maître Roboam, roi de Juda, et ils me feront périr.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Le roi prit donc conseil, et il se décida; il fit deux génisses d\'or, et il dit au peuple: C\'est assez de voyages à Jérusalem; Israël, voici tes dieux, qui t\'ont ramené de l\'Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Et il plaça l\'une des deux génisses à Béthel, et il donna l\'autre à Dan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Et cette chose devint une cause de péché; le peuple alla jusqu\'à Dan, devant l\'une des deux génisses, et il abandonna le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Il bâtit des temples sur les hauts lieux; il prit des prêtres de toutes les tribus du peuple, et ces prêtres n\'étaient pas des fils de Lévi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Jéroboam institua aussi une fête le huitième mois, quinzième jour de la lune, le jour même que l\'on fêtait en la terre de Juda, et il monta à l\'autel qu\'il avait élevé à Béthel pour y sacrifier aux génisses qu\'il avait fabriquées, et il plaça en Béthel les prêtres des hauts lieux qu\'il avait consacrés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Et il monta à l\'autel qu\'il avait dressé, le quinzième jour du huitième mois, pendant la fête qu\'il avait imaginée en son cœur; il fit célébrer cette fête par les fils d\'Israël, et il monta à l\'autel pour y sacrifier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 34, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 35, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 36, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 37, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 38, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 39, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 40, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 41, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 42, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 43, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 44, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 45, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 46, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 47, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 48, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 49, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 50, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 51, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 52, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 53, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 54, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Or, voilà qu\'un homme de Dieu vint de Juda à Béthel avec la parole du Seigneur, et Jéroboam était devant l\'autel pour y sacrifier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Et l\'homme cria contre l\'autel avec la parole du Seigneur, et il dit: Autel! autel! Voici ce que dit le Seigneur: Il naîtra de la maison de David un fils, son nom sera Josias; il immolera sur toi les prêtres des hauts lieux qui font pour toi des sacrifices, et il brûlera sur toi des ossements humains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Et, ce jour même, l\'homme donna un signe, et dit: Voici la parole qu\'a dite le Seigneur; il a dit: Voilà que l\'autel est fendu; la graisse qu\'on y a déposée va se répandre à terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Lorsque le roi Jéroboam eut ouï les paroles de l\'homme de Dieu et ses imprécations contre l\'autel, il étendit sur lui la main, et il dit: Saisissez- le. Aussitôt la main que de l\'autel il avait étendue vers l\'homme, se dessécha, et il ne put la ramener à lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Et l\'autel se fendit, et la graisse qu\'on y avait déposée se répandit à terre, selon le signe que l\'homme de Dieu avait donné avec la parole du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Alors, le roi Jéroboam dit à l\'homme de Dieu: Prie devant le Seigneur ton Dieu, que je puisse ramener ma main. L\'homme de Dieu pria devant le Seigneur, et il rendit au roi l\'usage de sa main, qui redevint comme auparavant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Après cela, le roi dit à l\'homme de Dieu: Entre avec moi dans ma demeure, déjeune, et je te ferai des présents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Mais l\'homme de Dieu dit au roi: Tu me donnerais la moitié de ta maison que je n\'y entrerais pas avec toi; je ne mangerai pas de pain, je ne boirai point d\'eau en ce lieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Car le Seigneur, avec sa parole, m\'a fait un ordre, il a dit: Ne mange pas de pain, ne bois point d\'eau, et, en t\'en allant, ne prends pas le chemin par où tu es venu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Et il s\'en retourna par un autre chemin, et il ne prit point celui par où il était venu à Béthel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Or, il y avait à Béthel un prophète avancé en âge, et ses fils allèrent lui raconter les œuvres que, ce jour-là, l\'homme de Dieu avait faites en Béthel, et les paroles qu\'il avait dites au roi. Et leur père changea de visage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Et leur père dit: Par où s\'en va-t-il? Ses fils lui montrèrent le chemin que venait de prendre l\'homme de Dieu venu de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Et il dit à ses fils: Bâtez-moi l\'âne; ils lui bâtèrent son âne, et il courut après l\'homme.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Il prit le même chemin que l\'homme de Dieu; et il le trouva assis sous un chêne, et il lui dit: Es-tu l\'homme de Dieu venu de Juda? L\'autre répliqua: Je le suis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Et il lui dit: Viens avec moi, et mange du pain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Je ne puis te suivre, reprit l\'autre, ni manger du pain ni boire de l\'eau en ce lieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Car le Seigneur m\'a donné ses ordres de sa propre bouche; il a dit: Ne mange pas là de pain, n\'y bois point d\'eau, et, en t\'en allant, ne prends pas le chemin par où tu es venu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Mais le vieillard lui dit: Moi aussi je suis comme toi prophète; un ange du Seigneur m\'a parlé avec la parole du Seigneur, disant: Ramène-le avec toi en ta maison; qu\'il mange du pain, qu\'il boive de l\'eau. Or, le vieillard le trompait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Il revint donc, il mangea du pain, il but de l\'eau en sa maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Et ceci advint: Comme ils étaient assis à table, la parole du Seigneur vint au prophète qui l\'avait ramené.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Et il dit à l\'homme de Dieu qui était venu de Juda: Voici ce que dit le Seigneur: En punition de ce que tu as irrité la parole du Seigneur, de ce que tu n\'as point gardé le commandement que t\'avait fait le Seigneur ton Dieu,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'De ce que tu es revenu, de ce que tu as bu et mangé dans ce lieu, après qu\'il t\'avait dit: « Tu n\'y mangeras pas de pain, tu n\'y boiras point d\'eau, » ton corps n\'entrera pas dans le sépulcre de tes pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Or, quand l\'homme de Dieu eut mangé du pain et bu de l\'eau, il bâta son âne, et s\'en alla.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Mais un lion le trouva en route, et le tua; son corps resta étendu sur le chemin; l\'âne ne bougea pas, et le lion se tint auprès du corps.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Et des hommes vinrent à passer; ils virent le cadavre gisant sur le chemin, et le lion se tenant auprès du cadavre; puis, ils entrèrent dans la ville où demeurait le vieux prophète, et ils racontèrent ce qu\'ils avaient vu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Le vieillard l\'apprit, et il s\'écria: Ce doit être l\'homme de Dieu qui a irrité la parole du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Et il sortit, et il trouva le cadavre gisant sur le chemin, l\'âne et le lion se tenant auprès du corps; et le lion n\'avait point mangé le mort, et il n\'avait point déchiré l\'âne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Et il sortit, et il trouva le cadavre gisant sur le chemin, l\'âne et le lion se tenant auprès du corps; et le lion n\'avait point mangé le mort, et il n\'avait point déchiré l\'âne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Le prophète souleva le corps de l\'homme de Dieu, le plaça sur son âne, et le ramena à la ville, afin de l\'ensevelir');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Dans son propre sépulcre; et ils pleurèrent sur lui, disant: Hélas! frère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Après qu\'ils eurent pleuré sur lui, le vieillard dit à ses fils: Quand je mourrai, ensevelissez-moi dans le sépulcre où l\'homme de Dieu a été enseveli; placez-moi auprès de ses ossements, afin que mes ossements soient sauvés avec les siens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Car la chose qu\'il a dite d\'après la parole du Seigneur, concernant l\'autel de Béthel et les temples des hauts lieux en Samarie, s\'accomplira.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Après ces choses, Jéroboam ne se repentit point de sa méchanceté; il continua de prendre, parmi tout le peuple, des prêtres des hauts lieux. Le premier venu put avoir la main pleine, et devenir prêtre sur les hauts lieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Ce fut le péché de la maison de Jéroboam, cause de sa perte et de sa disparition de la face de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
