INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour qu\'y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Roboam fit le mal devant le Seigneur, et il l\'irrita, en faisant tout ce que faisaient ses pères quand ils tombaient dans le péché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Le peuple se bâtit des hauts lieux et des colonnes; il eut des bois sacrés sur toutes les collines élevées; et il adora sous tous les arbres touffus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Et il y eut une association dans la terre promise; il s\'y commit toutes les abominations des peuples que le Seigneur avait exterminés devant la face des fils d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Aussi, la cinquième année du règne de Roboam, Sésac, roi d\'Égypte, marcha contre Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Et il prit tous les trésors du temple du Seigneur, et tous les trésors du palais du roi, et les javelines d\'or que David avait enlevées aux fils d\'Adrazaar, roi de Suba, pour les placer à Jérusalem, et les armures d\'or qu\'avait fait fabriquer Salomon; Sésac emporta tout en Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Roboam remplaça les armures d\'or par des armures d\'airain, et il les mit sous la surveillance des chefs de ses coureurs, qui gardaient la porte de son palais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Et lorsque le roi entrait dans le temple du Seigneur, ses coureurs portaient les armures et les attachaient dans le dépôt des coureurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Quant au reste de l\'histoire de Roboam, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Et il y eut une guerre continuelle entre Roboam et Jéroboam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Et Roboam s\'endormit avec ses pères; il fut enseveli auprès d\'eux en la ville de David, et son fils Abiam le remplaça.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'En la dix-huitième année du règne de Jéroboam, fils de Nabat, Abiam, fils de Roboam, devint roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Et il régna trois ans à Jérusalem; sa mère, fille d\'Absalon, se nommait Maacha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Et il marcha dans les péchés que son père avait faits devant lui, et son cœur ne fut point parfait avec le Seigneur son Dieu, comme l\'était le cœur de son père David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Mais, à cause de David, le Seigneur lui donna un rejeton, afin de maintenir ses enfants après lui, et d\'affermir Jérusalem;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Parce que David avait fait ce qui est droit devant le Seigneur, et que, pendant toute sa vie, il ne s\'était jamais écarté des commandements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Quant au reste de l\'histoire d\'Abiam, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda? Et la guerre ne cessa pas entre Abiam et Jéroboam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Et Abiam s\'endormit avec ses pères, en la vingt-quatrième année du règne de Jéroboam; il fut enseveli auprès de ses pères en la ville de David; et son fils Asa régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Dans la vingt-quatrième année du règne de Jéroboam, roi d\'Israël, Asa devint roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Il régna quarante et un ans à Jérusalem; sa mère, fille d\'Absalon, se nommait Ana.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Et Asa fit ce qui était droit devant le Seigneur, comme son père David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Et il détruisit, dans la terre promise, les initiations, et il abolit les infâmes pratiques qu\'avaient adoptées ses pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Il expulsa Ana, sa mère, pour qu\'elle ne fût plus rien, parce qu\'elle réunissait une association d\'initiés dans son bois sacré, et il abattit ses refuges, et il les livra aux flammes dans la vallée de Cédron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Mais il ne détruisit pas les hauts lieux; néanmoins, le cœur d\'Asa fut parfait avec Dieu tout le temps qu\'il vécut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Et il transporta les colonnes de son père; il transporta dans le temple du Seigneur ses colonnes d\'or et d\'argent, et ses vases.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Et la guerre ne cessa point entre Asa et Baasa, roi d\'Israël, tout le temps de leur vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Baasa, roi d\'Israël, marcha contre Juda, et il se mit à bâtir Rhama, pour qu\'il n\'y eût personne qui pût sortir ni rentrer, en faveur du roi Asa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Asa, alors, prit tout l\'argent et tout l\'or qui se trouva dans les trésors du temple et du palais; il les confia à ses serviteurs, et il les envoya chez le fils d\'Ader, fils de Tabremon, fils d\'Esion, roi de Syrie, qui résidait à Damas, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Fais alliance entre moi et toi, entre la maison de mon père et la maison de ton père; voilà que je t\'ai envoyé des présents: de l\'argent et de l\'or; viens, romps ton alliance avec Baasa, roi d\'Israël, et il s\'éloignera de moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Et Ben-Ader écouta le roi Asa; il fit partir les chefs de ses armées contre les villes d\'Israël; ils dévastèrent Ahion, Dan, Abel de la maison de Maacha, et tout Cennereth jusqu\'aux confins de Nephthali.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Quand Baasa l\'apprit, il abandonna les constructions de Rhama, et il retourna à Thersa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Et le roi Asa, dans Enacim, donna ses ordres à tout Juda, ils enlevèrent les pierres de Rhama, et les bois que Baasa avait employés pour la bâtir. Ensuite, le roi s\'en servit pour fortifier toutes les collines de Benjamin, et pour y établir la tour du guet.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Quant au reste de l\'histoire d\'Asa, à toutes les actions qu\'il fit en sa puissance, à toutes les villes qu\'il bâtit, ne sont-ils pas inscrits au livre des Faits et gestes des rois de Juda? Toutefois, dans sa vieillesse, il, perdit l\'usage de ses pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Et Asa s\'endormit avec ses pères; il fut enseveli auprès d\'eux en la ville de David, son aïeul. Et Josaphat, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nabat, fils de Jéroboam, devint roi d\'Israël dans la seconde année du règne d\'Asa en Juda, et Nabat régna deux ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Et il fit le mai devant le Seigneur; il marcha dans la voie de son père, et dans les péchés où il avait fait tomber Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Et Baasa, fils d\'Achias, l\'assiégea à la tète de la maison de Bélaan, fils d\'Achias; il l\'entoura de palissades à Gabathon, ville des Philistins, que Nabat et tout Israël avaient investie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Et Baasa le tua, la troisième année du règne d\'Asa en Juda, et il régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Dès qu\'il fut proclamé, il extermina toute la maison de Jéroboam; nul de ceux des siens, qui avait souffle de vie, ne fut épargné, jusqu\'à ce que tout eût péri, selon la parole que le Seigneur avait dite par la voix de son serviteur Achias le Silonite,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'Concernant les péchés de Jéroboam, et le péché où il avait fait tomber Israël pour irriter le Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Quant au reste de l\'histoire de Nabat, n\'est-il pas écrit au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'En la troisième année du règne d\'Asa en Juda, Baasa, fils d\'Achias, fut proclamé roi d\'Israël, et il régna vingt-quatre ans à Thersa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'En la troisième année du règne d\'Asa en Juda, Baasa, fils d\'Achias, fut proclamé roi d\'Israël, et il régna vingt-quatre ans à Thersa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Et il fit le mal devant le Seigneur; il marcha dans la voie de Jéroboam, fils de Nabat, et dans les péchés où il avait fait tomber Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Et la parole du Seigneur vint à Jéhu, fils d\'Anani; celui-ci dit à Baasa:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'En punition de ce qu\'après avoir été, par moi, tiré de la poussière et élevé sur le trône d\'Israël, tu as marché dans la voie de Jéroboam, tu as fait tomber dans le péché tout mon peuple d\'Israël, qui, par ses vanités, a excité ma colère,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Je susciterai des ennemis contre toi Baasa et contre toute ta maison, et je leur livrerai ta maison comme je t\'ai livré la maison de Jéroboam, fils de Nabat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Les chiens dévoreront celui du sang de Baasa qui mourra dans la ville; et les oiseaux du ciel dévoreront celui qui mourra dans les champs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Quant au reste de l\'histoire de Baasa, n\'est-il pas écrit au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Et Baasa s\'endormit avec ses pères; il fut enseveli à Thersa, et son fils régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Or, le Seigneur avait parlé par la voix de Jéhu, fils d\'Anani, contre Baasa et sa maison, à cause de tout le mal qu\'il avait fait devant le Seigneur, pour irriter le Seigneur par les œuvres de ses mains, et pour que sa maison devînt comme celle de Jéroboam; et Baasa avait tué Jéhu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Et Ela, fils de Baasa, régna deux ans sur Israël, à Thersa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Et Zambri, chef de la moitié de sa cavalerie, se révolta contre lui; comme il était à boire, et déjà ivre, dans la maison d\'Osa, son économe, à Thersa,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Zambri entra, le frappa, le tua, et régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Et, aussitôt qu\'il fut proclamé roi, et qu\'il se fut assis sur le trône,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Il extermina toute la famille de Baasa, selon la parole qu\'avait dite le Seigneur sur la maison de Baasa, par la voix de Jéhu le prophète,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'Concernant les péchés de Baasa et de son fils Ela, et le péché où ils avaient fait tomber Israël, qui, par ses vanités, avait irrité le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Quant au reste de l\'histoire d\'Ela, n\'est-il pas écrit au livre des faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Zambri régna sept jours à Thersa; alors, Israël était campé devant Gabathon, ville des Philistins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Et le peuple mût dans le camp que l\'on disait: Zambri s\'est révolté et il a tué le roi; aussitôt, le peuple d\'Israël proclama roi Ambri, qui, ce jour-là, commandait l\'armée et le camp.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Et Ambri, avec tout Israël, partit de Gabathon, et il assiégea Thersa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Quand Zambri vit que sa ville était prise, il se réfugia dans un souterrain de son palais; puis, il brûla sur lui le palais, et il mourut,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'A cause des péchés qu\'il avait commis en faisant le mal devant le Seigneur, en faisait tomber Israël dans le péché, et en marchant dans la voie de Jéroboam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Pour le reste de l\'histoire de Zambri, n\'est-il pas écrit au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Alors, le peuple d\'Israël se divisa: la moitié voulut pour roi Thamni, fils de Gonath; l\'autre moitié, Ambri.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Le peuple qui suivait Ambri l\'emporta sur le peuple qui suivait Thamni, fils de Gonath; Thamni mourut, en ce temps-là, ainsi que Joram, son frère, et Ambri régna après Thamni.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'En la trente et unième année du règne d\'Asa en Juda, Ambri fut reconnu roi d\'Israël; il régna douze ans, dont six à Thersa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Et Ambri acheta la montagne de Samarie, de Samar, qui était maître de cette montagne, au prix de deux talents d\'argent; il bâtit sur la montagne une ville qu\'il appela Samarie, du nom de celui qui la lui avait vendue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Et Ambri fit le mal devant le Seigneur; il fit le mal plus que tous ceux qui avaient régné avant lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Il marcha dans toutes les voies de Jéroboam, fils de Nabat, et dans les péchés où il avait fait tomber tout Israël qui, par ses vanités, avait irrité le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Quant au reste de l\'histoire d\'Ambri, aux actions qu\'il fit dans sa puissance, ne sont-ils pas écrits au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Et Ambri s\'endormit avec ses pères; il fut inhumé à Samarie, et; son fils Achab régna à sa place. En la onzième année du règne d\'Ambri, Josaphat, fils d\'Asa, âgé de trente-cinq ans, monta sur le trône de Juda, et il régna vingt-cinq ans à Jérusalem. Sa mère, fille de Seli, se nommait Gazuba. Il marcha dans la voie d\'Asa, son père; il ne s\'en écarta pas, et il ne cessa point d\'être droit devant le Seigneur. Toutefois, il ne détruisit point les hauts lieux; on y sacrifiait encore, on y brûlait de l\'encens. Quant à ce qu\'il fit de concert avec le roi d\'Israël, à toutes les actions qu\'il fit en sa puissance, à toutes ses guerres, ne sont-ils pas écrits au livre des Faits et gestes des rois de Juda? Le reste des réunions d\'initiés, qui s\'étaient rétablies au temps de son père Asa, il le fit disparaître de la terre promise. En ce temps-là, il n\'y avait point de roi dans la Syrie, mais un Nasib. Le roi Josaphat construisit un vaisseau à Tharsis, afin d\'aller à Ophir chercher de l\'or; mais il ne partit pas, parce qu\'il fut brisé en Asion-Gaber. Alors, le roi d\'Israël dit à Josaphat: J\'enverrai mes serviteurs avec les tiens sur un vaisseau; mais Josaphat ne le voulut pas. Et Josaphat s\'endormit avec ses pères; il fut enseveli auprès d\'eux dans la ville de David, et son fils Joram régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'La seconde année du règne de Josaphat en Juda, Achab commença, dans Samarie, un règne de vingt-deux ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Et Achab fit le mal devant le Seigneur; il fit le mal plus que tous ceux qui avaient régné avant lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Il ne lui suffit pas de marcher dans les péchés de Jéroboam, fils de Nabat; il prit pour femme Jézabel, fille d\'Ethbaal, roi des Sidoniens; il l\'imita, il servit Baal, et l\'adora.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Et il éleva un autel à Baal dans le temple d\'abomination qu\'il avait bâti à Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Il planta un bois sacré, et il continua ses abominations pour irriter le Seigneur et perdre son âme. Il fit le mal plus que tous ceux qui, avant lui, avaient régné sur Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'En ces jours-là, Achiel le Béthélite rebâtit Jéricho en sacrifiant son premier-né, Abiron, qui mourut comme il jetait les fondations; et Segub, le plus jeune de ses fils, qui mourut quand il posa les portes, selon la parole que le Seigneur avait dite par la voix de Josué, fils de Nau.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 35, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 36, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 37, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 38, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 39, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 40, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 41, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 42, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Or, Elie le prophète thesbite, de Thesba en Galaad, dit à Achab: Vive le Seigneur, Dieu des armées, Dieu d\'Israël, devant qui je suis, il n\'y aura en ces années ni rosée ni pluie, sinon à ma voix.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Et la parole du Seigneur vint à Élie, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Va-t\'en d\'ici du côté de l\'orient, et cache-toi dans le torrent de Chorrath, en face du Jourdain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Tu boiras de l\'eau du torrent, et j\'ordonnerai aux corbeaux de te nourrir en ce lieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Et Elie fit selon la parole du Seigneur; il s\'établit dans le torrent de Chorrath, en face du Jourdain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Et les corbeaux lui apportèrent des pains à l\'aurore, et des chairs le soir; et il but de l\'eau du torrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Quelque temps après le torrent se tarit, car il n\'y eut point de pluie sur la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Et la parole du Seigneur vint à Elie, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Lève-toi et va-t\'en à Sarepta chez les Sidoniens; là, j\'ai prescrit à une femme veuve de te nourrir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Et il se leva, et il partit pour Sarepta; arrivé devant les portes de la ville, il y vit une femme veuve qui ramassait du bois. Et Elie cria après elle, et il lui dit: Prends un peu d\'eau dans une cruche, et je boirai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Elle en alla prendre; puis, le prophète cria après elle, et il lui dit: Apporte-moi un morceau du pain que tu as en ta maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Mais la femme répondit: Vive le Seigneur ton Dieu! je n\'ai pas un seul pain cuit, je n\'ai qu\'un peu de farine dans la maie et quelques gouttes d\'huile dans la fiole; je vais ramasser deux petits morceaux de bois; puis, je rentrerai, et je pétrirai pour moi et mes enfants; nous mangerons, et après nous mourrons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elie répliqua: Rassure-toi; rentre et fais ce que tu viens de dire; fais de plus pour moi un petit pain; tu me l\'apporteras d\'abord, tu en feras ensuite pour toi et pour tes enfants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Car voici ce que dit le Seigneur: La maie ne manquera plus de farine, et l\'huile ne baissera plus dans la fiole, jusqu\'au jour où le Seigneur donnera de la pluie à la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Et la femme s\'en alla; elle pétrit, elle mangea; et le prophète et ses enfants mangèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Et la maie ne manqua plus de farine, et l\'huile ne baissa pas dans la fiole, selon la parole que le Seigneur avait dite par la voix d\'Elie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Après cela, le fils de la femme maîtresse de la maison tomba malade, et sa maladie fut très violente; enfin le souffle de la vie se retira de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Et la femme dit à Elie: Qu\'y a-t-il entre moi et toi, homme de Dieu? Es-tu venu chez moi pour rappeler le souvenir de mes péchés, et pour faire mourir mon fils?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Et le prophète répondit à la femme: Donne-moi ton fils. Et il le prit de son sein; et il le porta dans la chambre où il demeurait, et il l\'étendit sur sa couche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Là, il cria et il dit: Malheur à moi, Seigneur! je vous prends à témoin en faveur de cette veuve chez qui j\'habite; vous l\'avez affligée en faisant mourir son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Ensuite, il souffla trois fois sur l\'enfant, il invoqua le Seigneur, et il dit: Seigneur mon Dieu, que l\'âme de cet enfant revienne en lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Et il en fut ainsi. L\'enfant jeta un grand cri;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Et Elie descendit de sa chambre dans la maison, et il le rendit à sa mère; et il lui dit: Regarde, ton enfant est en vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Et la femme dit à Elie: Je reconnais que tu es un homme de Dieu; la parole de Dieu dans ta bouche est véritable.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Après bien des jours, la parole du Seigneur vint à Elie pendant la troisième année, disant: Pars, présente-toi devant Achab, et je donnerai de la pluie à la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Et Elie partit pour se présenter devant Achab. En ce temps-là, il y avait à Samarie une famine très grande.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Et Achab appela son économe Abdias; or, Abdias craignait beaucoup le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Quand Jézabel frappait les prophètes du Seigneur, Abdias avait pris cent hommes qui prophétisaient; il les avait cachés cinquante par cinquante dans des cavernes où il les avait nourris de pain et d\'eau.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Et Achab dit à Abdias: Viens, parcourons la contrée, visitons les torrents et les fontaines; peut-être trouverons-nous de l\'herbe; nous y ferons paître les chevaux et les mules, et ils ne périront pas dans les étables.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Et ils se partagèrent les territoires à visiter; Achab prit une route; Abdias, de son côté, en prit une autre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Comme Abdias s\'en allait seul sur un chemin, Elie arriva seul à sa rencontre. Abdias, pressant le pas, tomba la face contre terre, et il dit: Est-ce bien toi, Elie, mon maître?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Elie répondit: C\'est moi; pars, et dis à ton maître: Voici Elie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Abdias reprit: Quel péché ai-je fait pour que tu livres ton serviteur aux mains d\'Achab, afin qu\'il me fasse mourir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Vive le Seigneur ton Dieu! il n\'est ni peuple ni royaume où mon maître n\'ait envoyé pour te prendre, et quand on disait: Elie n\'est pas ici, il portait la flamme en ce royaume et en ses campagnes, parce qu\'il ne t\'avait point trouvé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Et maintenant, tu veux que je parte et que je dise à ton maître: Voici Elie!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Voici ce qui adviendra: Lorsque je me serai éloigné de toi, l\'Esprit du Seigneur te ravira en une terre je ne sais laquelle; et je me présenterai devant Achab et je t\'annoncerai; mais lui, ne te trouvant pas, me fera mourir; or, ton serviteur, depuis son enfance, a la crainte de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Ne sais-tu pas, ô mon maître, que quand Jézabel tuait les prophètes du Seigneur, j\'ai caché cent prophètes du Seigneur, cinquante par cinquante, en des cavernes, et que je les ai nourris de pain et d\'eau?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Et maintenant, tu veux que je parte et que je dise à mon maître: Voici Elie! Mais il me tuera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Elie reprit: Vive le Seigneur Dieu des armées, devant qui je suis! aujourd\'hui même Achab me verra.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Abdias alla donc à la rencontre d\'Achab; il lui annonça le prophète, et Achab accourut au-devant d\'Elie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Aussitôt qu\'il aperçut Elie, il s\'écria: Es-tu donc celui qui pervertit Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Et le prophète répondit: Ce n\'est point moi qui pervertis Israël, mais toi-même et la maison de ton père; car, vous abandonnez le Seigneur votre Dieu pour suivre Baal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Donne à ce moment tes ordres: rassemble devant moi, sur le mont Carmel, tout le peuple des dix tribus avec les quatre cent cinquante prophètes de l\'opprobre, et les quatre cents prophètes des bois sacrés, qui mangent à la table de Jézabel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Et Achab envoya par tout Israël; et il rassembla sur le mont Carmel tous les prophètes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Devant eux tous, il mena Elie, et celui-ci leur dit: Jusqu\'à quand boiterez-vous des deux jambes? Si le Seigneur est Dieu, suivez le Seigneur; si Baal est Dieu, suivez Baal. Et le peuple ne souffla mot.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Elie dit ensuite au peuple: Il n\'y a plus que moi de prophète du Seigneur; les prophètes de Baal sont quatre cent cinquante, et les prophètes des bois sacrés quatre cents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Que l\'on nous donne deux bœufs; qu\'ils en choisissent un pour eux, qu\'ils le séparent par membres, qu\'ils le posent sur le bûcher sans qu\'on y mette le feu; moi cependant j\'apprêterai de même l\'autre bœuf, et je n\'allumerai point le bûcher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Criez alors au nom de vos dieux, et moi j\'invoquerai le nom du Seigneur mon Dieu; le Dieu qui nous exaucera en envoyant de la flamme, celui-là est Dieu. A ces mots tout le peuple répondit, et il dit: Tu as bien parlé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Aussitôt, Elie dit aux prophètes de l\'opprobre: Choisissez pour vous l\'un des bœufs, et apprêtez-le les premiers, car vous êtes nombreux; invoquez le nom de vos dieux, et n\'allumez pas le bûcher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Ils prirent le bœuf, ils l\'apprêtèrent, ils invoquèrent le nom de Baal depuis l\'aurore jusqu\'au milieu du jour, et ils dirent: Exaucez-nous, ô Baal, exaucez-nous. Mais il n\'y avait point de voix pour leur répondre, point d\'oreilles pour les ouïr, et ils passaient et repassaient devant l\'autel qu\'ils avaient élevé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Le milieu du jour vint, et le Thesbite Elie les railla, et il dit; Invoquez-le à grands cris, puisque vous le dites dieu; il est peut-être à méditer, il est peut-être en affaire, ou peut-être il dort, et il se réveillera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Ils firent donc leurs invocations à grands cris; puis, selon leurs rites, ils se firent des entailles avec des poignards et des lancettes, de telle sorte que le sang ruissela sur eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Et ils prophétisèrent jusqu\'à ce que le soleil commençât à décliner. Le moment étant venu où l\'on place sur l\'autel les victimes, Elie le Thesbite dit aux prophètes des abominations: Retirez-vous maintenant, et je ferai mon holocauste. Et ils se retirèrent, et ils partirent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Alors, Elie dit au peuple: Approchez-vote de moi, et tout le peuple s\'approcha de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Et Elie prit douze pierres selon le nombre des tribus issues d\'Israël à qui le Seigneur avait dit: Israël sera ton nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Et il mit en œuvre ces pierres au nom du Seigneur, et il répara l\'autel qui avait été renversé; autour de l\'autel il creusa une rigole, qui eût contenu deux mesures de semence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Et il empila du bois fendu sur l\'autel qu\'il avait construit, sépara par membres l\'holocauste, le posa sur les éclats de bois, et l\'empila sur l\'autel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Puis, il dit: Prenez-moi quatre cruches d\'eau que vous répandrez sur l\'holocauste et sur le bois. Ainsi firent-ils, et il dit: Redoublez; ils redoublèrent, et il dit: Recommencez une troisième fois, et ils recommencèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Et l\'eau coula autour de l\'autel, et la rigole en fut remplie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Et Elie cria au ciel, disant: Seigneur Dieu d\'Abraham, d\'Isaac et d\'Israël, exaucez-moi, Seigneur, exaucez-moi aujourd\'hui en m\'envoyant de la flamme; que tout le peuple reconnaisse que vous êtes le Seigneur Dieu d\'Israël, que je suis votre serviteur, et que je n\'ai rien fait, sinon par vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Exaucez-moi, Seigneur, exaucez-moi; que le peuple reconnaisse que vous êtes le Seigneur Dieu, et vous convertirez le cœur de ce peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Et une flamme descendit tu ciel, envoyée par le Seigneur; elle dévora l\'holocauste, le bûcher, l\'eau de la rigole; elle effleura les pierres de l\'autel et la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Et le peuple tomba la face contre terre, et il dit: En vérité, le Seigneur Dieu est le seul Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Elie dit ensuite au peuple: Saisissez les prophètes de Baal, que pas un seul ne soit épargné. Ils les saisirent, et Elie les traîna au torrent de Cisson, et là, il les égorgea.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Elie dit ensuite à Achab: Pars, mange et bois; car il y a un bruit de pluie qui arrive.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Et Achab partit pour manger et boire; et le prophète monta sur le Carmel; là, il se pencha vers la terre, la tête entre les genoux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Puis, il dit à son serviteur: Va, et regarde du côté de la mer. Le serviteur regarda, et il dit: il n\'y a rien. Mais son maître lui dit: Retournes-y sept fois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Et le serviteur y retourna sept fois; à la septième fois il vit un petit nuage semblable au pied d\'un homme, et ce nuage amenait de l\'eau; le maître alors dit au serviteur: Va trouver Achab, et dis-lui: Attelle ton char et mets-toi en route, de peur que la pluie ne te surprenne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Bientôt çà et là le ciel s\'obscurcit de nuées, le vent souffla, et il tomba une grande pluie. Et Achab, en pleurant, s\'en alla à Jezraël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Et la main du Seigneur s\'étendit sur Elie, et il serra sur ses reins sa ceinture, et il courut devant Achab jusqu\'à Jezraël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Et Achab apprit à Jézabel sa femme tout ce qu\'avait fait Elle, et comment il avait tué les prophètes par l\'épée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Et Jézabel envoya chez Elie, et elle dit: Si tu es Elie, moi je suis Jézabel: que Dieu me punisse et me punisse encore, si demain, à pareille heure, je n\'ai pas fait de ta vie ce que tu as fait de la vie de chacun d\'eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Et Elie eut crainte; il se leva; il s\'éloigna pour sauver sa vie, et se rendit à Bersabée en Juda, où il laissa son serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Lui-même s\'enfonça dans le désert à une journée de marche; il s\'assit sous un genévrier, et il demanda la mort, disant: C\'est assez, prenez maintenant mon âme, ô Seigneur, car je ne suis pas meilleur que mes pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Et il se coucha et il s\'endormit sous le genévrier; or voilà qu\'un ange le toucha, et lui dit: Lève-toi et mange.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Il regarda, et il vit auprès de sa tête des gâteaux d\'épeautre et une fiole d\'eau; il se leva, il mangea, il but et il s\'endormit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'L\'ange du Seigneur revint une seconde fois, le toucha, et lui dit: Lève- toi et mange, car tu as à faire un long chemin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Et il se leva; il mangea et il but, et il partit fortifié par ces aliments, et il marcha quarante jours et quarante nuits jusqu\'au mont Horeb.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Là, il entra dans la caverne; il en fit sa demeure, et la parole du Seigneur vint à lui, disant: Que fais-tu là, Elie?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Le prophète répondit: J\'ai eu le cœur rempli de zèle pour le Seigneur Tout-Puissant, parce que les fils d\'Israël vous ont abandonné, qu\'ils ont renversé vos autels, et tué par l\'épée vos prophètes; seul j\'ai survécu, et ils en veulent à ma vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Or, la voix reprit: Tu partiras demain; mais tiens-toi devant le Seigneur sur la montagne, regarde: le Seigneur va passer. Aussitôt, voilà qu\'un vent violent passa, déchirant la montagne, brisant les rochers, et le Seigneur n\'était pas dans le vent; après le vent, il y eut un tremblement de terre, et le Seigneur n\'était pas dans le tremblement de terre;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Après le tremblement de terre, vint une flamme, et le Seigneur n\'était pas dans la flamme; après la flamme, vint le murmure d\'un souffle léger.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Quand Elie entendit ce souffle, il se voila le visage de son manteau de peau de brebis; puis, il sortit et il se tint à l\'entrée de la caverne; alors, une voix s\'approcha de lui, disant: Que fais-tu là, Elie?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Et le prophète répondit: J\'ai eu le cœur plein de zèle pour le Seigneur Tout-Puissant, parce que les fils d\'Israël ont abandonné votre alliance, renversé vos autels, et tué par l\'épée vos prophètes; seul j\'ai survécu, et ils en veulent à ma vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Et le Seigneur lui dit: Pars, remets-toi en marche, prends le chemin du désert de Damas, tu iras, et tu sacreras Azaël pour être roi de Syrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Et tu sacreras Jéhu, fils de Namsi, pour être roi d\'Israël; et tu sacreras Elisée, fils de Saphat, pour être prophète après toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Celui qu\'épargnera l\'épée d\'Azaël, Jéhu le mettra à mort; celui qu\'épargnera l\'épée de Jéhu, Elisée le mettra à mort.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Et je me réserve, en Israël, sept mille hommes, les seuls qui n\'aient point fléchi le genou devant Baal, les seuls dont la bouche ne l\'ait point adoré.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Et Elie partit de ce lieu, et il trouva Elisée, fils de Saphat; celui-ci labourait avec des bœufs; il avait devant lui douze attelages, et seul il les conduisait. Le prophète alla droit à Elisée, et jeta sur lui son manteau de peau de brebis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Et Elisée abandonna ses bœufs; il suivit à grands pas Elie, et il lui dit: Je vais embrasser mon père; puis, je t\'accompagnerai. Elie reprit: Reviens, car j\'ai travaillé pour toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Et il s\'éloigna d\'Elie, il prit ses couples de bœufs, il les sacrifia, il les fit cuire avec l\'attirail des attelages, il les donna au peuple, et il mangea; enfin il rejoignit Elie et il le servit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Et Naboth le Jezraélite avait une vigne attenante à l\'aire d\'Achab, roi de Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Et Achab parla à Naboth, disant: Donne-moi ta vigne, j\'en ferai mon jardin potager, car elle près de ma demeure; je te donnerai une vigne meilleure que la tienne. Si tu le préfères, je te donnerai de l\'argent pour prix de ta vigne, et elle sera mon jardin potager.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Mais, Nabaoth dit à Achab: Dieu me préserve de te donner l\'héritage de mon père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Et l\'esprit d\'Achab fut troublé; il s\'étendit sur sa couche, se voila le visage, et ne mangea pas de pain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Et Jézabel sa femme entra vers lui, et elle lui dit: D\'où vient que tu as l\'esprit troublé, et que tu ne manges pas de pain?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Il lui répondit: C\'est parce que j\'ai parlé à Naboth le Jezraélite, disant: Donne-moi à prix d\'argent ta vigne, ou, si tu veux, je te donnerai en échange une autre vigne, et qu\'il m\'a répondu: Je ne te donnerai pas l\'héritage de mon père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Jézabel sa femme lui dit: Conduis-toi donc en roi envers Israël, lève- toi, mange du pain, reviens à toi, et moi je te donnerai la vigne de Naboth le Jezraélite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Ensuite, elle écrivit au nom d\'Achab une lettre qu\'elle scella du sceau royal, et elle l\'envoya aux anciens et aux premiers de la ville qui demeuraient avec Naboth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Or, elle avait écrit ceci dans la lettre: Ordonnez un jeûne et faites asseoir Naboth parmi les premiers du peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Puis, devant lui, apostez deux hommes, fils de pervers, qui portent témoignage contre lui, disant: Il a blasphémé contre Dieu et le roi, qu\'on l\'emmène, qu\'on le lapide, qu\'il meure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Et les hommes de sa ville, les anciens et les plus riches qui demeuraient avec lui, firent comme avait dit Jézabel dans la lettre qu\'elle leur avait envoyée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Ils ordonnèrent un jeûne, ils firent asseoir Naboth parmi les chefs du peuple,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Et les deux hommes, fils de pervers, entrèrent, et ils s\'assirent devant Naboth, et ils portèrent témoignage contre lui, disant: Tu as blasphémé contre Dieu et le roi. Et on l\'emmena hors de la ville, on le lapida, et il mourut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Puis, on envoya un message à Jézabel, disant: Naboth a été lapidé et il est mort.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Dès que Jézabel eut ouï le message, elle dit à Achab: Lève-toi, hérite de la vigne de Naboth le Jezraélite, qui n\'a point voulu te la donner à prix d\'argent; car Naboth n\'est plus vivant, il est mort.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Dès qu\'Achab ouït que Naboth le Jezraélite était mort, il déchira ses vêtements et se couvrit d\'un cilice; mais ensuite, il se leva, et il alla à la vigne de Naboth pour en prendre possession.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Et le Seigneur parla à Elie le Thesbite, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Lève-toi, va trouver Achab, roi d\'Israël, à Samarie, car il est dans la vigne de Naboth; il y est allé pour en prendre possession.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Et tu lui parleras, disant: Voici que dit le Seigneur: Comme tu as tué et hérité, voici, à cause de cela, ce que dit le Seigneur: En tout lieu où les chiens et les pourceaux ont léché le sang de Naboth, les chiens lécheront ton sang, et les prostituées se baigneront dans ton sang.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Et Achab dit à Elie: Tu m\'as donc trouvé, ô mon ennemi? Le prophète répondit: Je t\'ai trouvé, en ce que tu t\'es follement vendu pour faire le mal devant le Seigneur, et l\'irriter.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Et c\'est moi qui ferai fondre sur toi les malheurs, qui, allumerai le feu après toi, qui détruirai tout mâle de la maison d\'Achab, tout ce qui est enfermé, tout ce qui reste encore en Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Et je ferai de ta maison ce que j\'ai fait de la maison de Jéroboam, fils de Nabat, et de la maison de Baasa, fils d\'Achias, parce que tu m\'as irrité et que tu as fait tomber dans le péché tout Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Ensuite, le Seigneur s\'adressant à Jézabel lui dit: Les chiens te dévoreront dans les murs de Jezraël;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Celui de la maison d\'Achab qui mourra dans la ville, les chiens le dévoreront; celui qui mourra dans les champs, sera dévoré par les oiseaux du ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Quant à Achab, il a follement agi en se vendant pour faire le mal devant le Seigneur, perverti par sa femme Jézabel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Il s\'est rendu très abominable pour avoir marché à la suite des idoles, et imité tout ce que faisait l\'Amorrhéen que le Seigneur a exterminé devant la face des fils d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'A ces mots, Achab fut tout contrit devant la face du Seigneur; il s\'en alla pleurant; il déchira sa tunique, il se couvrit le corps d\'un cilice et il jeûna (il s\'était déjà enveloppé d\'un cilice le jour où il avait frappé Naboth le Jezraélite); et il s\'en alla tout humilié.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Et la parole du Seigneur vint encore à son serviteur Elie au sujet d\'Achab, et le Seigneur lui dit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'As-tu vu comme Achab était contrit devant ma face? Je ne ferai point fondre sur lui ces malheurs de son vivant, mais ce sera du vivant de son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Cependant Ben-Ader rassembla toute son armée, partit et assiégea Samarie; il avait avec lui trente-deux rois, toute sa cavalerie et tous ses chars. Et ils se mirent en campagne; ils assiégèrent Samarie, et ils donnèrent l\'assaut à ses remparts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Puis, le roi de Syrie envoya dans la ville dire à Achab, roi d\'Israël: Voici ce que dit Ben-Ader:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Ton argent et ton or m\'appartiennent; tes femmes et tes enfants m\'appartiennent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Le roi d\'Israël répondit: Comme tu l\'as dit, ô roi mon maître, je t\'appartiens, et toutes les choses que je possède.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Les messagers vinrent encore, et ils dirent: Voici ce que dit Ben-Ader: de t\'ai envoyé dire: Tu me livreras ton argent et ton or, et tes femmes et tes enfants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Demain donc, à pareille heure, j\'enverrai près de toi mes serviteurs; ils fouilleront dans ta maison et dans les maisons de tes serviteurs, et ils prendront toutes les choses désirables à leurs yeux, sur lesquelles ils auront mis la main.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Alors, le roi d\'Israël convoqua tous les anciens de la terre promise, et il dit: Écoutez, voyez quelle lâcheté demande cet homme: il me demande mes femmes, mes fils et mes filles. Quant à mon argent et à mon or, je ne les lui ai point refusés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Et les anciens et tout le peuple s\'écrièrent: Ne l\'écoute pas, n\'y consens point.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Il dit donc aux messagers de Ben-Ader: Dites à votre maître: Toutes les choses pour lesquelles tu as d\'abord envoyé à ton serviteur, je les ferai, mais cette dernière chose je ne puis la faire. Et les hommes partirent, et ils rapportèrent sa réponse à leur maître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Ben-Ader envoya encore à lui, disant: Que le Seigneur me punisse, et qu\'il me punisse encore, si votre tanière à renards de Samarie suffit pour contenir les piétons de mon armée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Le roi d\'Israël reprit: C\'est assez: que le tortu ne se glorifie pas comme l\'homme qui se tient droit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Lorsque cette réponse fut rapportée au Syrien, il était à boire sous sa tente avec tous les rois ses alliés, et il dit à ses serviteurs: Elevez un retranchement. Ils firent donc un retranchement autour de la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Or, voilà qu\'un prophète arriva devant Achab, roi d\'Israël, et dit: Voici ce que dit le Seigneur: As-tu vu cette innombrable multitude? Eh bien! aujourd\'hui je te la livre, et tu reconnaîtras que je suis le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Et Achab demanda: Par qui? Et le prophète reprit: Voici ce que dit le Seigneur: Par les jeunes fils des chefs des provinces. Et Achab dit: Qui commencera le combat? Le prophète répondit: Toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Et Achab passa en revue les jeunes fils des chefs des provinces; ils étaient deux cent trente; après cela, il passa en revue l\'armée, toute formée d\'hommes vaillants; il y en avait sept mille.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Puis, il sortit au milieu du jour, comme Ben-Ader était à boire et à s\'enivrer en Socchoth, lui et les trente-deux rois ses alliés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Et les jeunes fils des chefs des provinces sortirent d\'abord; on l\'alla rapporter au roi de Syrie, disant: Des hommes sont arrivés de Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Et il répondit: S\'ils viennent en paix, prenez-les vivants; s\'ils viennent en guerre, prenez-les vivants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Et les jeunes fils des chefs des provinces sortirent de la ville; cependant l\'armée les suivait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Et chacun frappa l\'homme le plus près de lui; puis, une seconde fois, chacun frappa l\'homme le plus près de lui; aussitôt, la Syrie prit la fuite, Israël la poursuivit, et Ben-Ader s\'échappa sur le cheval d\'un simple cavalier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Et le roi d\'Israël sortit; il prit tous les chevaux avec les chars, et il fit des Syriens un grand carnage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Ensuite, le prophète alla trouver le roi d\'Israël, à qui il dit: Fortifie-toi, observe, et vois ce que tu as à faire; car, l\'année révolue, Ben-Ader, roi de Syrie, reviendra contre toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Et les serviteurs du roi de Syrie lui dirent: Le Dieu d\'Israël est le Dieu des montagnes, et non le Dieu des vallées; voilà pourquoi ils nous ont vaincus; si nous leur faisons la guerre dans la plaine, nous l\'emporterons sur eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Fais ceci: renvoie les rois chacun en leur demeure, remplace-les par les princes des Philistins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Et nous te donnerons une autre armée aussi nombreuse que celle qui a été détruite; un cheval remplacera un cheval, des chars remplaceront les chars; nous les combattrons dans la plaine, et nous l\'emporterons sur eux. Et le roi les écouta, et il fit ainsi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'L\'année révolue, Ben-Ader passa en revue les forces de la Syrie, et il se porta en Aphèca pour combattre Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Les fils d\'Israël aussi passèrent en revue leur armée, et ils marchèrent contre eux. Et Israël campa vis-à-vis leur camp; ils étaient comme deux troupeaux de chèvres, et les Syriens remplissaient la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Alors, l\'homme de Dieu revint, et il dit au roi d\'Israël: Voici ce que dit le Seigneur: En punition de ce que la Syrie a dit: Le Dieu d\'Israël est le Dieu des montagnes et non le Dieu des vallées, je te livrerai cette armée innombrable, et tu reconnaîtras que je suis le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Et les deux camps restèrent sept jours l\'un vis-à-vis de l\'autre; le septième jour la bataille s\'engagea, et Israël tua aux Syriens cent mille piétons en une seule journée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 30, 'Et les survivants se réfugièrent dans Aphèca, dont les murs s\'écroulèrent sur vingt-sept mille de ceux qui s\'étaient échappés; Ben-Ader se cacha dans l\'alcôve d\'une chambre à coucher;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 31, 'Et il dit à ses serviteurs: Je sais que les rois d\'Israël sont des rois miséricordieux; couvrons nos reins de cilices:, passons-nous des cordes autour du cou, et sortons au-devant du roi d\'Israël; peut-être il nous renverra la vie sauve.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 32, 'Et ils se couvrirent les reins de cilices; ils se passèrent des cordes autour du cou, et ils dirent au roi d\'Israël: Ton serviteur Ben-Ader dit: Que j\'aie la vie sauve. Achab répondit: Vit-il encore? Il est mon frère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 33, 'Les serviteurs en tirèrent bon présage; ils firent des libations, et ils s\'emparèrent de la parole qui était sortie de la bouche d\'Achab, et ils dirent: Ben-Ader est ton frère. Il reprit: Allez le chercher et amenez-le. Ben-Ader sortit de sa retraite pour aller près d\'Achab, et ses serviteurs le firent monter auprès de lui sur un char.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 34, 'Et Achab dit: Je te rendrai les villes que mon père a prises au tien; tu pourras te faire des issues à Damas, comme mon père en a fait à Samarie, et je te renverrai après avoir conclu alliance avec toi. Et ils firent alliance, et il le renvoya.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 35, 'Mais un homme, l\'un des fils des prophètes, dit, d\'après la parole du Seigneur, à son voisin: Frappe-moi. Mais l\'autre ne voulut pas le frapper.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 36, 'Et le prophète lui dit: En punition de ce que tu n\'as point obéi à la voix du Seigneur, quand tu seras loin de moi un lion te tuera. En effet, l\'homme s\'éloigna, un lion le rencontra et le tua.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 37, 'Et le prophète alla trouver un autre homme, et il lui dit: Frappe-moi. L\'homme le frappa, le frappa encore, et l\'accabla de coups.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 38, 'Ensuite, le prophète partit, et il se tint sur le chemin qu\'avait pris le roi; or, il s\'était bandé les yeux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 39, 'Quand le roi vint à passer, il cria après lui, disant: Ton serviteur est allé à la guerre, et voilà qu\'un homme m\'a amené un homme, et m\'a dit: Garde cet homme; s\'il s\'échappe, tu me donneras ta vie pour sa vie, ou tu paieras un talent d\'argent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 40, 'Mais ton serviteur a eu beau regarder tout alentour çà et là, l\'homme s\'est évadé. A ces mots, le roi d\'Israël s\'écria: Tu me tends un piège; tu l\'as tué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 41, 'Et le prophète se hâta d\'ôter le bandeau qui couvrait ses yeux. Alors, le roi reconnut que c\'était l\'un des prophètes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 42, 'Et le prophète lui dit: Voici ce que dit le Seigneur: Parce que tu as laissé échapper un méchant homme, ta vie pour sa vie, ton peuple pour son peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 43, 'Le roi d\'Israël s\'en alla donc confondu et attristé; puis, il rentra dans Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Et il y demeura trois ans, sans qu\'il y eût guerre entre Israël et la Syrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Pendant la troisième année, Josaphat, roi de Juda, alla visiter le roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Or, le roi d\'Israël dit à ses serviteurs: Savez-vous que Ramoth-Galaad nous appartient, et que nous gardons le silence sans la réclamer du roi de Syrie?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Puis, le roi d\'Israël dit à Josaphat: Viendras-tu avec nous reprendre Ramoth-Galaad? Josaphat répondit: Comme je suis, tu es; ton peuple est comme mon peuple, tes chevaux sont comme mes chevaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Et Josaphat, roi de Juda, dit encore au roi d\'Israël: Consulte aujourd\'hui le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Le roi d\'Israël rassembla donc tous les prophètes, environ quatre cents, et il leur dit: Irai-je en guerre à Ramoth-Galaad ou m\'abstiendrai-je? Ils répondirent: Marche, et le Seigneur la livrera aux mains du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Et Josaphat dit au roi d\'Israël: N\'y a-t-il pas ici un prophète du Seigneur par qui nous puissions consulter le Seigneur?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Le roi d\'Israël répondit à Josaphat: Il y a ici un homme par qui l\'on peut consulter le Seigneur; mais je le hais, parce qu\'il me dit non de bonnes, mais de mauvaises choses; c\'est Michée, fils de Jemla. Josaphat reprit: Que le roi ne parle pas ainsi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Et le roi d\'Israël appela un eunuque, et il lui dit: Amène ici tout de suite Michée, fils de Jemla.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Or, le roi d\'Israël et Josaphat, roi de Juda, couverts de leurs armures, étaient assis chacun sur leur trône, vers la porte de Samarie, et tous les prophètes prophétisaient devant eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Et Sédécias, Chananéen, s\'était fait des cornes de fer, disant: Voici ce que dit le Seigneur: Avec ces cornes, tu frapperas la Syrie jusqu\'à ce qu\'elle soit détruite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'En même temps, tous les prophètes prophétisaient ainsi: Marche sur Ramoth-Galaad, tu réussiras; le Seigneur livrera à tes mains le roi de Syrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Et le messager qui était allé querir Michée, lui dit: Voilà que tous les prophètes, tout d\'une voix, disent de bonnes choses concernant le roi. Sois donc aussi en paroles comme l\'un d\'eux, et dis de bonnes choses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Mais Michée reprit: Vive le Seigneur! ce que le Seigneur me dira, je le répèterai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Puis, il alla devant le roi, et le roi lui dit: Michée, irai-je en guerre à Ramoth-Galaad, ou m\'abstiendrai-je? Et il répondit: Marche, le Seigneur fera réussir ce qui est dans les mains du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Et le roi lui dit: Combien de fois t\'adjurerai-je, pour que tu me dises la vérité au nom du Seigneur?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Michée répondit: Il n\'en est pas ainsi; car j\'ai vu tout Israël dispersé dans les montagnes comme un troupeau sans pasteur. Et le Seigneur a dit: Le Seigneur n\'est-il point leur Dieu? Que chacun aille en paix en sa maison');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Et le roi d\'Israël dit à Josaphat, roi de Juda: Ne te l\'ai-je point dit que cet homme me prophétise non de bonnes, mais de mauvaises choses?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Michée reprit: Non pas, ce n\'est point moi; écoute la parole du Seigneur; ce n\'est pas ainsi: j\'ai vu le Dieu d\'Israël assis sur son trône, et toute l\'armée du ciel se tenait près de lui à sa droite et à sa gauche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Et le Seigneur dit: Qui trompera Achab, roi d\'Israël, pour qu\'il parte en campagne, et qu\'il succombe à Ramoth-Galaad? Et l\'un répondait d\'une sorte, et l\'aube d\'une autre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Quand un esprit s\'avançant, se plaça devant le Seigneur, et dit: C\'est moi qui le tromperai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Et le Seigneur lui dit: De quelle manière? Et il reprit: Je partirai, et je serai un esprit trompeur dans la bouche de tous ses prophètes. Puis, le Seigneur dit: Tu le tromperas, tu prévaudras; va, et fais ce que tu as dit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Voilà donc que maintenant le Seigneur a placé un esprit trompeur dans la bouche de tous tes prophètes; car le Seigneur a dit sur toi de mauvaises choses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Et Sédécias le Chananéen, s\'avançant, frappa Michée à la joue, et il dit: Quel est l\'esprit du Seigneur qui parle par ta voix?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Michée reprit: Tu le verras le jour où tu fuiras de chambre en chambre pour t\'y cacher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Et le roi d\'Israël dit: Prenez Michée; menez-le à Semer, chef de la ville, et dites à Joas, fils du chef,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'De mettre cet homme en prison, où on le nourrira du pain et de l\'eau de l\'affliction, jusqu\'à ce que je revienne en paix.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Et Michée reprit: Si tu reviens en paix, le Seigneur n\'a point parlé par ma bouche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Le roi d\'Israël partit avec Josaphat, roi de Juda, pour Ramoth-Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Et le roi d\'Israël dit au roi de Juda: Je me déguiserai, et j\'engagerai la bataille, et tu auras mes vêtements. Le roi d\'Israël se déguisa donc, et il engagea la bataille.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Or, le roi de Syrie donna cet ordre aux trente-deux chefs de ses chars: N\'attaquez ni petit ni grand, mais le roi d\'Israël seul.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Quand les chefs des chars virent Josaphat, roi de Juda, ils se dirent: Voilà le roi d\'Israël, et ils l\'entourèrent pour l\'attaquer, mais Josaphat cria.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Aussitôt qu\'ils reconnurent que ce n\'était pas le roi d\'Israël, ils s\'éloignèrent de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Et l\'un d\'eux tendit son arc, visa droit au but, et Frappa le roi d\'Israël entre le poumon et la poitrine. Le roi dit alors à son cocher: Tourne bride, et emmène-moi hors de la mêlée; j\'ai une blessure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Et, ce jour-là, le combat tournait en déroute; Achab resta sur son char, devant les Syriens, depuis le matin jusqu\'au soir; il perdit, par sa blessure, des flots de sang qui coulèrent jusqu\'au fond du char; et le soir, il mourut; et, depuis qu\'il avait fui, son sang avait coulé jusqu\'au fond du char.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Au coucher du soleil, le héraut de l\'armée s\'arrêta, disant: Que chacun retourne en sa ville et en sa terre,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Car le roi est mort. Ceux d\'Israël revinrent donc à Samarie, et ils ensevelirent le roi dans cette ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Or, ils lavèrent le char à la fontaine de Samarie; les pourceaux et les chiens léchèrent le sang, et les prostituées se baignèrent dans le sang, selon la parole que le Seigneur avait dite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Quant au reste de l\'histoire d\'Achab, à la description du palais d\'ivoire qu\'il éleva, et de toutes les villes qu\'il bâtit, ne sont-ils pas écrits au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Achab s\'étant endormi avec ses pères, son fils Ochozias régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Cependant, Josaphat, fils d\'Asa, régna sur Juda; son règne avait commencé la quatrième année de celui d\'Achab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Il avait alors trente-cinq ans, et il régna vingt-cinq ans à Jérusalem; le nom de sa mère était Azuba (Gazuba), fille de Salai (Séli).');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Et il marcha dans la voie d\'Asa, son père; il ne s\'en écarta point, et il fut agréable aux yeux du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Seulement, il ne détruisit point les hauts lieux; le peuple y sacrifiait encore, et l\'on y brûlait de l\'encens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Et Josaphat vécut en paix avec le roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Quant au reste de l\'histoire de Josaphat et de ses actions dans sa puissance, n\'est-il pas écrit au livre des faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Et Josaphat s\'endormit avec ses pères; il fut enseveli auprès d\'eux en la ville de David, son aïeul, et son fils Joram régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Et Josaphat s\'endormit avec ses pères; il fut enseveli auprès d\'eux en la ville de David, son aïeul, et son fils Joram régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Et Josaphat s\'endormit avec ses pères; il fut enseveli auprès d\'eux en la ville de David, son aïeul, et son fils Joram régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Et Josaphat s\'endormit avec ses pères; il fut enseveli auprès d\'eux en la ville de David, son aïeul, et son fils Joram régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Et Josaphat s\'endormit avec ses pères; il fut enseveli auprès d\'eux en la ville de David, son aïeul, et son fils Joram régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Et Ochozias, fils d\'Achab, régna sur Israël en Samarie; son règne Et Ochozias, fils d\'Achab, régna sur Israël en Samarie; son règne commença la dix-septième année de celui de Josaphat, et il dura deux ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Et il fit le mal devant le Seigneur; il marcha dans la voie d\'Achab, son père, dans la voie de Jézabel, sa mère, et dans le péché où la maison de Jéroboam, fils de Nabat, fit tomber Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'Il servit Baal, et il l\'adora; il irrita le Seigneur Dieu d\'Israël, de la même manière qu\'on l\'avait irrité avant lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Après la mort d\'Achab, Moab se souleva contre Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Et Ochozias tomba à travers le treillis de sa chambre haute, en Samarie; il en fut malade; et il fit partir des messagers auxquels il dit: Allez demander à Baal-Mouche, dieu d\'Accaron, si je survivrai à cette maladie? Ils partirent, et ils le questionnèrent pour leur roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Or, un ange du Seigneur appelant Elie le Thesbite, dit: Lève-toi, va à la rencontre des messagers d\'Ochozias, roi de Samarie, et lu leur diras: Est-ce qu\'il n\'y a point de Dieu en Israël, que vous allez interroger Baal-Mouche, dieu d\'Accaron? Il n\'en sera pas ainsi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Voici ce que dit le Seigneur: La couche sur laquelle tu es monté, tu n\'en descendras plus; car assurément tu mourras. Elie partit donc, et il leur dit ces paroles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Et les messagers retournèrent auprès de leur maître, qui leur dit: Pourquoi êtes-vous revenus?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Ils répondirent: Un homme est venu à notre rencontre, il nous a dit: Retournez auprès du roi qui vous a envoyés, et dites-lui: Voici ce que dit le Seigneur: Est-ce qu\'il n\'y a point de Dieu en Israël, que tu vas consulter Baal-Mouche, le dieu d\'Accaron? Il n\'en sera point ainsi. La couche sur laquelle tu es montée, tu n\'en descendras plus, car tu mourras.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Ainsi, après leur retour, ils rapportèrent au roi les paroles d\'Elie, et le roi leur dit: Comment est l\'homme qui a été à votre rencontre, et qui vous a dit ces paroles?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Ils reprirent: C\'est un homme velu, qui est vêtu d\'une peau de brebis. Et le roi s\'écria: C\'est Elie le Thesbite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Puis, il envoya vers lui un chef de cinquante hommes; le chef partit avec sa troupe, et il vit Elie assis sur la cime de la montagne, et il lui dit: Descends, homme de Dieu, le roi te demande.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Or, Elle répondit: Si je suis un homme de Dieu, le feu du ciel va tomber et dévorer toi et tes cinquante hommes. Aussitôt, le feu du ciel tomba et dévora le chef avec sa troupe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Le roi lui envoya une seconde fois un chef et ses cinquante hommes. Et le chef dit à Elie: Homme de Dieu: Voici ce que dit le roi: Descends au plus vite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Le prophète répondit: Si je suis un homme de Dieu, le feu du ciel va tomber et dévorer toi et tes cinquante hommes. Aussitôt, le feu du ciel tomba, et dévora le chef avec sa troupe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Et le roi envoya encore un chef et ses cinquante hommes; et ce troisième chef partit, se mit à genoux devant Elie, le pria, et lui dit: Homme de Dieu, que ma vie et celle de ces cinquante hommes, tes serviteurs, ne soient pas sans prix à tes yeux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Le feu du ciel est tombé et a dévoré déjà deux chefs de cinquante hommes; maintenant donc, que ma vie ne soit pas sans prix à tes yeux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Or, l\'ange du Seigneur dit au prophète: Descends avec lui, ne crains rien d\'eux. Et le prophète se leva, et il se rendit avec eux au-devant du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Et il lui dit: Voici ce que dit le Seigneur: Pourquoi as-tu envoyé des messagers consulter Baal-Mouche, dieu d\'Accaron? Ce ne sera point ainsi: la couche sur laquelle tu es monté, tu n\'en descendras plus, car tu mourras.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Il mourut, en effet, selon la parole du Seigneur que le prophète lui avait dite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Quant au reste de l\'histoire d\'Ochozias, n\'est-il pas écrit au livre des faits et gestes des rois d\'Israël? Et Joram, fils d\'Achab, régna douze ans sur Israël en Samarie. Son règne commença la dix-huitième année de celui de Josaphat, roi de Juda. Et il fit le mal devant le Seigneur, mais point autant que ses frères et sa mère; il renversa même les colonnes que son père avaient élevées à Baal, et il les fit briser. Seulement, il resta attaché aux péchés qu\'avait commis la maison de Jéroboam, et où elle avait fait tomber Israël. Il ne s\'en corrigea pas, et la colère du Seigneur fut excitée contre la maison d\'Achab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 19, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 20, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 21, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 22, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Or, dans le temps que le Seigneur ravit Elie, comme au ciel au milieu d\'un tourbillon, Elie et Elisée sortirent de Galgala.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Et Elie dit à Elisée: Reste ici, car Dieu veut que j\'aille jusqu\'à Béthel. Elisée répondit: Vive le Seigneur, et vive ton \'âme, je ne te quitterai pas. Ils entrèrent donc à Béthel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Et les fils des prophètes qui étaient à Béthel, s\'approchèrent d\'Elisée, et ils lui dirent: Ne sais-tu pas qu\'aujourd\'hui le Seigneur doit ravir ton maître au-dessus de ta tête? Il répondit Oui, je le sais, gardez le silence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Elie dit ensuite à Elisée: Reste ici, car Dieu veut que j\'aille jusqu\'à Jéricho. Et il répondit: Vive le Seigneur, et vive ton âme! je ne te quitterai pas. Ils entrèrent donc à Jéricho.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Et les fils des prophètes qui étaient à Jéricho s\'approchèrent d\'Elisée, et ils lui dirent Ne sais-tu pas qu\'aujourd\'hui le Seigneur doit ravir ton maître au-dessus de ta tête? Il répondit: Oui, je le sais, gardez le silence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Elie lui dit ensuite: Reste ici, le Seigneur veut que j\'aille jusqu\'au Jourdain. Elisée répondit: Vive le Seigneur et vive ton âme! je ne te quitterai point. Ils marchèrent donc tous les deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Or, il y avait au loin, vis-à-vis d\'eux, cinquante fils des prophètes, et ils s\'arrêtèrent l\'un et l\'autre aux bords du fleuve.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Et Elie prit sa peau de brebis, la fit tourner, et en frappa l\'eau du fleuve: et l\'eau se sépara à leur droite et à leur gauche; ils passèrent tous les deux, et ils s\'en furent dans le désert.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Pendant qu\'ils traversaient le Jourdain, Elie dit à Elisée: Demande ce que je ferai pour toi avant d\'être ravi loin de toi. Elisée répondit: Que j\'aie part à ton double esprit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Elie reprit: Tu as demandé une chose difficile: si tu me vois quand je serai ravi d\'auprès de toi, il en sera pour toi ainsi; sinon, cela ne sera pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Ils parlaient ainsi en marchant, et voilà qu\'un char de feu et des chevaux de feu les séparèrent l\'un de l\'autre; puis, Elie fut ravi dans un tourbillon comme au ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Et Elisée le vit, et il cria: Père, père, char et conducteur d\'Israël. Bientôt il ne le vit plus; et il saisit ses vêtements, et il les déchira en deux lambeaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Ensuite, Elisée ramassa la peau de brebis qui était tombée de dessus Elie, et s\'en retourna. Il s\'arrêta aux bords du Jourdain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Et il prit la peau de brebis qui était tombée de dessus Elie, en frappa l\'eau du fleuve, et dit: Où est maintenant le Dieu d\'Elfe? Et il frappa les eaux, qui s\'ouvrirent à droite et à gauche, et Elisée passa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Les fils des prophètes qui étaient à Jéricho, sur la rive opposée, le virent alors arriver, et dirent: L\'esprit d\'Elie est resté sur Elisée. Et ils allèrent à sa rencontre, et se prosternèrent devant lui la face contre terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Puis, ils lui dirent: Il y a avec tes serviteurs cinquante hommes vaillants; qu\'ils partent, qu\'ils s\'informent de ton maître; est-ce que l\'Esprit du Seigneur l\'a ravi, et l\'a jeté dans le Jourdain ou sur l\'une des montagnes, ou sur l\'une des collines? Mais Elisée répondit: N\'envoyez pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Ils le pressèrent tant qu\'il en eut honte, il dit enfin: Envoyez; en conséquence, ils firent partir cinquante hommes qui cherchèrent trois jours, et ne trouvèrent point Elie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Ils revinrent auprès d\'Elisée, car il s\'était établi à Jéricho, et il leur dit: Ne vous avais-je point dit: Ne partez pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Or, les hommes de la ville dirent à Elisée: Voilà que la ville est bien située comme celles que regarde le Seigneur, mais les eaux y sont mauvaises et la terre est stérile.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Et Elisée dit: Prenez-moi une cruche neuve et mettez-y du sel. Ils prirent donc une cruche, et la lui apportèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Ensuite, Elisée alla à la source, y versa le sel, et dit: Voici ce que dit le Seigneur: J\'ai assaini ces eaux; il n\'y aura plus ici ni mortalité ni stérilité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Et les eaux sont restées saines jusqu\'à nos jours, selon 1a parole qu\'avait dite Elisée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'De là, il monta à Béthel, et comme il marchait dans le chemin, de petits enfants sortirent de la ville, le raillèrent, et lui dirent: Monte, chauve, monte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Il se retourna, les vit, et les maudit au nom du Seigneur; or, voilà que deux ours s\'élancèrent de la forêt, et mirent en pièces quarante-deux de ces enfants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'De là, il alla au mont Carmel, puis il retourna à Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Et Joram, fils d\'Achab, commença à régner sur Israël, la dix-huitième année du règne de Josaphat en Juda, et il régna douze ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Et il fit le mal aux yeux du Seigneur, mais point autant que son père et sa mère; il renversa même les colonnes de Baal que son père avait élevées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Seulement, il resta attaché au péché de Jéroboam, fils de Nabat, où celui- ci avait fait tomber Israël; il ne s\'en éloigna point.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Et Mosa, roi de Moab, était nourrisseur de troupeaux, et il rendait au roi d\'Israël cent mille moutons et cent mille béliers dans leur toison, de ceux qu\'il élevait chaque année.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Après la mort d\'Achab, le roi de Moab refusa son tribut au roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Et le roi Joram, ce jour-là, sortit de Samarie, et il passa en revue Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Il partit ensuite, et envoya des gens à Josaphat, roi de Juda, disant: Le roi de Moab m\'a refusé son tribut: marcheras-tu avec Israël pour combattre Moab? Il répondit: Je marcherai; tu es comme moi, je suis comme toi; ton peuple est comme mon peuple; tes chevaux sont comme mes chevaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Et il ajouta: Quel chemin prendrai-je? Joram lui dit: Le chemin du désert d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Et le roi d\'Israël partit avec le roi de Juda et le roi d\'Edom; ils firent sept journées de marche; or, le camp manquait d\'eau pour le bétail qui suivait l\'armée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Le roi d\'Israël dit alors: Malheur à nous! le Seigneur a appelé, sur ce chemin, les trois rois pour les livrer aux mains de Moab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Et Josaphat dit: N\'y a-t-il point ici de prophète du Seigneur par qui nous puissions le consulter? L\'un des serviteurs du roi d\'Israël répondit: il y a ici Elisée, fils de Saphat, celui qui versait de l\'eau sur les mains d\'Elie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Josaphat reprit: La parole du Seigneur est avec lui. Et le roi d\'Israël, ainsi que le roi de Juda et le roi d\'Edom, l\'alla trouver.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Or, Elisée dit au roi d\'Israël: Qu\'y a-t-il entre moi et toi? Va aux prophètes de ton père et aux prophètes de ta mère. Le roi d\'Israël reprit: Le Seigneur n\'a-t-il pas appelé les trois rois pour les livrer aux mains de Moab?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elisée répondit: Vive le Seigneur Dieu des armées devant qui je me tiens! je ne t\'aurais point regardé, je ne t\'aurais point vu, si je n\'avais respecté la présence de Josaphat, roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Maintenant, amenez-moi un joueur de harpe. Or, dans le temps que celui-ci jouait, la main du Seigneur fut sur Elisée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Et il s\'écria: Voici ce que dit le Seigneur: Creusez dans cette vallée, faites-y une multitude de fossés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Car voici ce que dit le Seigneur: Vous ne verrez point de vent, vous ne verrez point de pluie; néanmoins cette vallée se remplira d\'eau, et vous boirez, puis vous abreuverez vos chevaux et votre bétail.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Ceci est chose légère aux yeux du Seigneur; et je livrerai Moab à vos mains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Vous raserez toutes ses forteresses, vous abattrez tous ses arbres fruitiers, vous comblerez toutes les fontaines, et vous rendrez stérile toute bonne terre en la couvrant de cailloux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Le lendemain matin, tandis qu\'on brûlait la graisse des victimes, les eaux jaillirent du chemin d\'Edom, et la terre en fut couverte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Or, tout Moab apprit que les trois rois venaient le combattre; et il convoqua de toutes parts ses hommes de guerre, et il dit: Malheur à moi! Et l\'armée se rangea sur la frontière.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Et ils se levèrent de grand matin, et le soleil se leva sur les eaux, et Moab vit en face des eaux rouges comme du sang.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Et il dit: Voici du sang versé par l\'épée; les rois se seront combattus, chacun aura tué son voisin; maintenant, Moab, à toi les dépouilles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Et ils entrèrent dans le camp d\'Israël; mais Israël était debout, il tailla Moab en pièces; les fuyards se dispersèrent devant lui, il entra dans leur contrée et il frappa Moab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Il rasa ses villes fortes; sur toute terre fertile, chaque homme porta un caillou, de sorte qu\'elle en fut couverte; les vainqueurs comblèrent toutes les fontaines; ils abattirent tous les arbres fruitiers; il ne resta que les pierres des remparts abattus. Des frondeurs parcoururent la contrée et la frappèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Quand il vit la bataille perdue, le roi de Moab s\'entoura de sept cents hommes vaillants, qui, l\'épée à la main, cherchèrent à passer à travers Edom; mais ils ne le purent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Et il prit son fils premier-né, désigné pour régner à sa place, et il l\'offrit en holocauste sur les remparts; tout Israël en eut un grand remords; ils s\'éloignèrent de lui, et ils retournèrent en la terre promise.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Et une femme des fils des prophètes invoqua le secours d\'Elisée, disant: Mon mari, ton serviteur, est mort, et tu sais que ton serviteur avait la crainte de Dieu; or, son créancier est venu réclamer pour lui mes deux fils, et ils seront ses esclaves.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elisée répondit: Que ferai-je pour toi? Qu\'as-tu en ta maison? Elle reprit: Ta servante n\'a rien dans sa maison, sinon l\'huile dont je dois m\'oindre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Et il lui dit: Va, demande à tous tes voisins des vases vides, et ne te contente pas d\'un petit nombre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Puis, tu rentreras; tu fermeras la porte sur toi et sur tes fils; tu verseras ton huile dans ces vases; et à mesure que tu les auras remplis, tu les enlèveras.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Elle s\'éloigna d\'Elisée; et ferma sa porte sur elle et sur ses fils: ceux-ci lui apportèrent les vases, elle y versa l\'huile jusqu\'à ce qu\'ils en fussent pleins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Et elle dit à ses fils: Approchez encore un vase. Il n\'y en a plus, dirent-ils. Et l\'huile cessa de couler.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Alors elle alla trouver l\'homme de Dieu, et lui raconta ce qui venait d\'arriver. Elisée lui dit: Pars, et donne de l\'huile en paiement; tu acquitteras ainsi ta dette; ensuite, toi et tes deux fils vous vivrez du reste de l\'huile.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Un autre jour, Elisée traversa Sunam; il y avait là une femme riche qui le contraignit de manger de son pain; plus tard, toutes les fois qu\'il entrait en cette ville après une longue marche, il allait chez elle, et il y mangeait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Et la femme dit à son mari: Je vois bien que ce saint homme qui vient toujours chez nous est un homme de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Préparons pour lui une chambre haute, il ne la lui faut pas bien grande; mettons-y un lit, une table, une chaise, une lampe, et il y couchera quand il viendra chez nous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Or, un jour, il entra dans cette maison, monta à sa chambre, et se mit au lit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Puis, il dit à Giézi, son serviteur: Appelle-moi cette Sunamite. Giézi l\'appela, et elle se tint devant Elisée,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Qui dit à son serviteur, dis-lui: Voilà que pour nous tu t\'es donné tous ces soins: que devons-nous faire en ta faveur? As-tu quelque chose à demander au roi ou à l\'un des chefs de l\'armée? Elle répondit: Je suis dans ma maison, au milieu de mon peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Or, Elisée dit à Giézi: Que faut-il faire pour elle? Giézi, son serviteur, répondit: Elle n\'a point de fils, et son mari est vieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Et il la rappela; mais elle était restée près de la porte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Elisée lui dit: A pareille époque l\'an prochain, en cette même saison, tu vivras et tu embrasseras un fils. Et elle s\'écria: Non, seigneur, ne trompe point ta servante.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'En effet, la femme conçut; elle enfanta un fils au temps, en la saison, que lui avait dits Elisée, et elle vécut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Et l\'enfant grandit, et un jour qu\'il était vers son père auprès des moissonneurs,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Il dit à son père: Ma tête! ma tête! Et le père dit à son serviteur: Porte-le à sa mère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Et le serviteur le porta à sa mère, qui le tint couché sur ses genoux jusqu\'au milieu du jour; alors, il mourut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Et elle l\'emporta, l\'étendit sur le lit de l\'homme de Dieu, ferma sur lui la porte et sortit de la maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Puis, elle appela son mari et lui dit: Envoie-moi l\'un de tes serviteurs et une ânesse; je courrai jusqu\'à l\'homme de Dieu, et je reviendrai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Mais il dit: Pourquoi veux-tu l\'aller trouver ce jour-ci, qui n\'est ni sabbat ni nouvelle lune? Or, elle reprit: C\'est bien.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Aussitôt, elle bâta son ânesse, et elle dit à son serviteur: Allons, marche, ne m\'arrête point, sur ma monture, que je ne te dise: C\'est ici; alors tu iras trouver l\'homme de Dieu au mont Carmel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Elle partit donc, et alla jusqu\'à l\'homme de Dieu sur la montagne. Dès qu\'Elisée l\'aperçut venant à lui, il dit à Giézi, son serviteur: Voilà certainement cette Sunamite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Cours à sa rencontre, dis-lui: Vas-tu bien, et ton époux, et ton enfant? Elle répondit: Tout va bien.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Puis, elle aborda Elisée sur la montagne, elle lui baisa les pieds, et Giézi s\'avança pour la repousser; mais Elisée lui dit: Laisse-la, car son âme est pleine de douleur, et le Seigneur s\'est caché de moi; il ne me l\'a point dit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Et la femme ajouta: Est-ce que j\'avais demandé à mon maître un fils? N\'avais-je point dit: Ne me trompe pas?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Et Elisée dit à Giézi: Ceins-toi les reins, prends en ta main mon bâton, et pars; si tu rencontres un homme, ne le bénis pas; si un homme te bénit, ne lui réponds pas; ensuite, tu poseras mon bâton sur le visage de l\'enfant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Et la mère de l\'enfant dit: Vive le Seigneur et vive ton âme! je ne te quitterai point. Elisée se leva donc, et la suivit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Cependant, Giézi la devança; il posa le bâton sur le visage de l\'enfant; mais il n\'y avait plus de voix pour lui répondre, plus d\'oreilles pour l\'ouir; enfin il revint au-devant d\'elle, et lui dit: L\'enfant ne s\'est point réveillé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Et Elisée entra dans la maison; il vit l\'enfant mort étendu sur son lit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Et à peine entré dans la maison, Elisée ferma la porte sur eux tous, et il adora le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Il monta sur le lit; il se coucha sur l\'enfant; il mit sa bouche contre sa bouche, ses yeux contre ses yeux, ses mains sur ses mains; il se courba sur lui, et la chair de l\'enfant fut réchauffée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Et le prophète descendit; il marcha çà et là dans la maison; puis, il remonta et se courba sur l\'enfant, jusqu\'à sept fois; et l\'enfant ouvrit les yeux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Alors, Elisée appelant à grands cris son serviteur, lui dit: Fais venir cette Sunamite. Il la fit venir; elle entra auprès du prophète, et il lui dit: Prends ton fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'La femme s\'avança, se jeta aux pieds du prophète, et l\'adora la face contre terre; puis, elle prit son enfant et sortit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elisée retourna à Galgala; il y avait là grande famine, et les fils des prophètes étaient assis devant lui. Elisée dit à son serviteur: Prends une grande chaudière et fais cuire à manger pour les fils des prophètes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Lui-même alla aux champs recueillir des légumes sauvages; il trouva une vigne, il y prit des courges sauvages plein son manteau, et il les jeta dans la chaudière, sans qu\'on le vit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Cela fait, il porta aux hommes à manger, et tandis qu\'ils mangeaient de cette bouillie, ils jetèrent un cri, et dirent: La mort est dans la chaudière, ô homme de Dieu. Et ils ne purent manger davantage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Alors, il dit: Prenez de la farine et jetez-la dans la chaudière; et s\'adressant à Giézi, son serviteur, il ajouta: Donne de cette bouillie au peuple et qu\'ils mangent. Et il n\'y eut plus rien de mauvais dans la chaudière.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Et un homme vint de Bétharisa, et il présenta à l\'homme de Dieu de ses prémices: vingt pains d\'orge avec des cabas de figues; et l\'homme de Dieu dit: Donnez cela au peuple, et qu\'ils mangent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'A quoi son serviteur répondit: Pourquoi donner cela à cent hommes! Mais Elisée reprit: Donne-le au peuple, qu\'il mange; car le Seigneur a dit: Ils mangeront et ils en laisseront.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Et ils mangèrent et ils en laissèrent, selon la parole du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Et Naaman, général de l\'armée syrienne, était un homme considérable aux yeux de son maître, et d\'un aspect imposant; c\'était par lui que le Seigneur avait sauvé la Syrie, et l\'homme était très-puissant, mais il était lépreux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Or, des maraudeurs sortis de la Syrie avaient emmené captive, de la terre d\'Israël, une petite fille qui servait la femme de Naaman,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Cette fille dit à sa maîtresse: Plût à Dieu que mon maître fût en présence du prophète de Dieu en Samarie; il le guérirait de sa lèpre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Et la femme entra auprès de son seigneur, et elle lui dit: La jeune fille de la terre d\'Israël a parlé de telle et telle manière.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Et le roi de Syrie dit à Naaman: Vas-y, va, et j\'enverrai une lettre au roi d\'Israël. Naaman partit donc, et il prit avec lui dix talents d\'argent, six mille sicles d\'or, et dix robes diverses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Et il porta au roi d\'Israël la lettre où il était écrit: Dès que tu auras reçu cette lettre, tu guériras de sa lèpre mon serviteur Naaman, que j\'ai envoyé auprès de toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Quand le roi d\'Israël eut lu la lettre, il déchira ses vêtements, et il s\'écria: Suis-je un Dieu pour donner la mort et la vie? Pourquoi celui-ci envoie-t-il un homme auprès de moi, afin que je le guérisse de sa lèpre? Vous le voyez, il cherche un prétexte contre moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Aussitôt qu\'Elisée apprit que le roi d\'Israël avait déchiré ses vêtements, il envoya près de lui, disant: Pourquoi as-tu déchiré tes vêtements? Que Naaman vienne me trouver, qu\'il sache qu\'en Israël il y a un prophète.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Et Naaman y alla avec ses chevaux et son char, et il se tint à la porte d\'Elisée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Et le prophète lui envoya un messager, qui lui dit: Pars et baigne-toi sept fois dans le Jourdain, ta chair te reviendra, et tu seras guéri.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Mais, Naaman irrité s\'en alla en disant: Je m\'étais dit: Il va certainement venir me trouver; il se tiendra devant moi, il invoquera le nom du Seigneur son Dieu, il imposera les mains sur mes plaies, et il me guérira de la lèpre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Les eaux de l\'Abana et du Pharphar, fleuves de Damas, ne valent-elles pas mieux que toutes les eaux du Jourdain? Si je m\'y baigne après mon retour, ne serai-je point plus tôt guéri? Et il s\'éloigna, et il partit courroucé;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Et ses serviteurs s\'approchèrent de lui, disant: Si le prophète t\'avait prescrit une grande chose, ne la ferais-tu point? A plus forte raison, puisqu\'il t\'a dit: Baigne-toi, et tu seras guéri.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Et Naaman, ayant mis pied à terre, se baigna sept fois dans le Jourdain selon la parole d\'Elisée; et sa chair redevint comme la chair d\'un petit enfant; il était guéri.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Et il retourna en personne auprès d\'Elisée avec toute sa troupe; arrivé vers le prophète, il se tint debout devant lui, et dit: Je reconnais qu\'il n\'y a point de Dieu sur la terre sinon en Israël; maintenant reçois la bénédiction de ton serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Elisée répondit: Vive le Seigneur, devant qui je me tiens! je n\'accepterai rien. L\'autre le pressa d\'accepter, mais il ne le voulut pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Et Naaman dit: Puisque tu refuses, que l\'on donne du moins à ton serviteur assez de terre pour charger deux mulets; car ton serviteur ne fera plus d\'holocaustes, et ne brûlera plus d\'encens pour d\'autres dieux; il ne sacrifiera qu\'au Seigneur, à cause de cette affaire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Et que le Seigneur pardonne à ton serviteur, si, lorsque mon maître entrera dans le temple de Remman, pour y adorer, appuyé sur mon bras, je me prosterne aussi dans le temple de Remman, pendant que mon maître y adorera; que le Seigneur pardonne alors à ton serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Le prophète dit à Naaman: Va-t\'en en paix. Et il s\'éloigna pour retourner en la terre de Debratha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Mais Giézi, le serviteur d\'Elisée, se dit: Voilà que mon maître s\'est abstenu de rien accepter des choses qu\'avait apportées ce Naaman le Syrien; vive le Seigneur! je courrai après lui, et j\'en obtiendrai quoi que ce soit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Et Giézi courut après Naaman; le Syrien le vit courant après lui, et il retourna son char pour le rencontrer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Et Giézi dit: Tout va bien, mon maître m\'envoie, disant: Voilà que deux jeunes gens fils de prophètes m\'arrivent des montagnes d\'Ephraïm, donne-leur un talent d\'argent et deux robes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naaman répondit: Prends un double talent d\'argent. Et il prit deux talents d\'argent, en deux sacs, et deux robes, puis il les donna à porter à ses deux serviteurs qui partirent devant lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Il arriva à la brune, prit de leurs mains les présents, les déposa dans la maison, et congédia les deux hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Lui-même entra ensuite, et se tint auprès de son maître. Or, Elisée lui dit: Giézi, d\'où viens-tu? Celui-ci répondit: Ton serviteur ne s\'éloigne ni à droite, ni à gauche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Et le prophète reprit: Est-ce que mon cœur n\'était pas avec toi quand l\'homme a retourné son char pour aller à ta rencontre? Et maintenant, tu as pris de l\'argent, tu as reçu des robes; tu veux acheter des oliviers, des vignes, des brebis, des bœufs, des serviteurs et des servantes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Eh bien! la lèpre de Naaman s\'attachera à toi et à ta race pour toujours. Et Giézi sortit de sa présence, couvert d\'une lèpre blanche comme la neige.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Et les fils des prophètes dirent à Elisée: Vois, le lieu où nous demeurons devant toi est étroit pour nous;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Allons donc jusqu\'au Jourdain, que chaque homme prenne là une solive, puis nous y construirons pour nous une maison où nous demeurerons. Et il répondit: Allez.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'L\'un d\'eux ajouta doucement: Viens avec tes serviteurs; et il reprit: J\'irai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Et il partit avec eux; ils arrivèrent au Jourdain, et ils abattirent des arbres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Or, pendant que l\'un d\'eux coupait un tronc, le fer de sa cognée tomba dans l\'eau, et il cria: Hélas! maître, la voilà perdue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'L\'homme de Dieu dit: Où est-elle tombée? L\'autre lui montra la place; Elisée écorça une branche, il l\'y jeta, et le fer surnagea.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Et le prophète dit: Relève-le pour toi. L\'autre étendit la main et le reprit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Cependant, le roi de Syrie était à combattre Israël; il tint conseil avec ses serviteurs, et il dit: Je camperai en un tel lieu où l\'on peut se cacher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Et Elisée envoya au roi d\'Israël, disant: Prends garde de passer en cet endroit, car le roi de Syrie y est caché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Et le roi d\'Israël fit reconnaître le lieu que lui avait dit Elisée, et il s\'en garda plus d\'une et plus de deux fois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Et l\'âme du roi de Syrie en fut émue; il convoqua ses serviteurs, et il leur dit: Ne me direz-vous point qui me trahit auprès du roi d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Or, l\'un d\'eux répondit: Cela n\'est pas, ô roi mon maître, mais Elisée le prophète fait connaître au roi d\'Israël les discours que tu tiens jusque dans l\'alcôve de ta chambre à coucher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Et il leur dit: Allez, voyez où il est, et j\'enverrai des gens le prendre. Ils s\'en allèrent, et ils lui firent dire: Le voici en Dothaïm.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Et il y envoya des cavaliers, des chars, une force imposante; et ses gens y arrivèrent de nuit, et ils investirent la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'S\'étant levé de grand matin, le serviteur d\'Elisée sortit, et il vit l\'armée qui entourait la ville; il vit les cavaliers, les chars, et il dit au prophète: Hélas! maître, comment ferons-nous?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Mais son maître répondit: N\'aie point de crainte; car ceux qui sont avec nous, surpassent en nombre ceux qui sont avec eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Puis, le prophète pria, et dit: Seigneur, ouvrez les yeux de mon serviteur, qu\'il voie. Et le Seigneur ouvrit les yeux du serviteur; il vit la montagne couverte de chevaux de feu et de chars de feu, tout autour d\'Elisée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Et ces chevaux et ces chars descendirent à lui; alors, il pria le Seigneur, et il dit: Frappez ce peuple d\'aveuglement. Et le Seigneur les frappa d\'aveuglement, selon la parole du prophète.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Elisée leur dit: Ce n\'est point ici la ville, vous n\'êtes pas dans le chemin. Suivez-moi, et je vous mènerai vers l\'homme que vous cherchez. Et il les conduisit à Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Quand ils y furent entrés, le prophète dit: Seigneur, ouvrez-leur les yeux, qu\'ils voient. Et le Seigneur leur ouvrit les yeux, et ils virent. Or, voilà qu\'ils étaient au milieu de Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'En les voyant, le roi d\'Israël dit à Elisée: Faut-il frapper, père?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Il répondit: Ne les frappe point; frappe-t-on de l\'arc ou de l\'épée ceux que l\'on a fait captifs? Prépare pour eux des pains et de l\'eau; qu\'ils mangent et boivent, pour s\'en retourner ensuite auprès de leur maître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Le roi leur fit donc grande chère, ils mangèrent et burent; après quoi, il les renvoya, et ils s\'en allèrent retrouver leur maître, et les bandes de la Syrie cessèrent leurs excursions dans la terre d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Quelque temps après, Ben-Ader, roi de Syrie, réunit toute son armée, se mit en campagne, et assiégea Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Et il y eut une grande famine en Samarie; le siège se prolongea au point que la tête d\'un âne valut cinquante sicles d\'argent, et un peu de fiente de pigeon cinq sicles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Comme le roi d\'Israël passait sur les remparts, une femme cria à lui, disant: Sauve-moi, ô roi mon maître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Il lui dit: Si le Seigneur ne te sauve, comment pourrai-je te sauver? Ai-je rien du pressoir ou de l\'aire?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Le roi ajouta: Que t\'arrive-t-il? Elle reprit: La femme que voilà m\'a dit: Donne-moi ton fils, aujourd\'hui nous le mangerons, et demain nous mangerons le mien.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Nous avons donc fait bouillir mon fils et nous l\'avons mangé; puis, je lui ai dit le lendemain: Donne-moi ton fils, et aujourd\'hui nous le mangerons; mais elle a caché son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Lorsque le roi d\'Israël eut oui les paroles de la femme, il déchira ses vêtements, il traversa le rempart, et le peuple vit le cilice sur ses chairs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Et il s\'écria: Que Dieu me punisse et qu\'il me punisse encore, si la tête d\'Elisée est encore aujourd\'hui sur ses épaules.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Or, Elisée était assis en sa demeure, et les anciens étaient assis auprès de lui. Et le roi avait envoyé contre lui un homme; avant que celui-ci arrivât, le prophète dit aux anciens: Ne savez-vous pas que le fils du meurtre a envoyé prendre ma tête? Voyez, quand son messager sera arrivé; fermez la porte et retenez-le en dedans; n\'entendez-vous point derrière lui le bruit des pas de son maître?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Comme il parlait encore, le messager entra et dit: C\'est le Seigneur qui fait fondre sur nous ces maux; que puis-je encore attendre, du Seigneur?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 34, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 35, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Et le prophète répondit: Écoute la parole du Seigneur: Voici ce que dit le Seigneur: Demain, à pareille heure, la mesure de fleur de farine se vendra un sicle, et la double mesure d\'orge se vendra un sicle à la porte de Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Le grand officier (c\'était celui sur le bras duquel le roi s\'appuyait) dit à Elisée: A moins que le Seigneur n\'en fasse tomber du ciel des cataractes, cette parole peut-elle s\'accomplir? Et le prophète reprit; Tu le verras de tes yeux, mais tu n\'en mangeras point.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Or, il y avait quatre lépreux devant les portes de la ville, et ils se dirent entre eux: Pourquoi resterions-nous ici jusqu\'à la mort?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Si nous disons: Entrons dans la ville, nous y mourrons, car il y a grande famine dans la ville; et, si nous restons ici, nous y mourrons. Allons donc; et tombons dans le camp des Syriens; s\'ils nous prennent vivants, nous vivrons; s\'ils nous mettent à mort, eh bien! nous mourrons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Et ils se levèrent avant le jour pour entrer dans le camp des Syriens; ils entrèrent par un côté du camp où il n\'y avait point un seul homme.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Car le Seigneur avait fait retentir dans le camp des Syriens un bruit de chars et de chevaux, comme d\'une grande armée. Et chaque Syrien avait dit à son frère: Sans doute le roi d\'Israël a pris à sa solde les rois des Hettéens et les rois de l\'Égypte, pour qu\'ils marchent contre nous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Ils s\'étaient donc levés, et s\'étaient enfuis dans les ténèbres; ils avaient abandonné leurs tentes, leurs chevaux et leurs ânes; laissé le camp comme il était, et pris la fuite pour sauver leur vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Et les lépreux, ayant fait quelques pas dans le camp, entrèrent sous une tente, mangèrent, burent, enlevèrent de l\'argent, de l\'or, des vêtements, et s\'en allèrent; ensuite, un peu plus loin, ils entrèrent sous une autre tente, y prirent encore du butin; puis, ils en sortirent, et se cachèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Et ils se dirent entre eux: En resterons-nous là? Ce jour est un jour de bonne nouvelle; si nous gardons le silence, si nous demeurons ici jusqu\'à la prochaine aurore, nous serons en faute; partons donc, entrons dans la ville, et faisons notre rapport dans le palais du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Ils s\'en allèrent, appelèrent à grands cris aux portes de la ville, et dirent à ceux qui vinrent: Nous sommes entrés dans le camp des Syriens; il n\'y a ni homme ni voix humaine; il n\'y a plus que les chevaux et des ânes attachés, et leurs tentes sont restées comme elles étaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Et les gardes de la porte appelèrent à grands cris; puis, on porta la nouvelle au palais du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Le roi se leva qu\'il était encore nuit, et il dit à ses serviteurs: Je vais vous expliquer ce qu\'a fait le Syrien: il sait que nous sommes affamés; il est allé hors du camp pour se cacher dans la campagne, disant: Ils vont sortir, nous les prendrons vivants, et nous entrerons dans la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Or, l\'un de ses serviteurs répondit: Que l\'on prenne cinq chevaux parmi ceux qui restent encore vivants, de cette grande multitude des chevaux d\'Israël; nous les enverrons là, et nous verrons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Et ils prirent deux cavaliers que le roi d\'Israël envoya derrière le roi de Syrie, disant: Allez, et voyez.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Ces hommes suivirent les traces de l\'armée jusqu\'au Jourdain, et ils virent toute la route couverte de vêtements et de harnais que, dans leur frayeur, les Syriens avaient jetés; puis, ils revinrent faire au roi leur rapport.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Et le peuple sortit et pilla le camp des Syriens; la mesure de fleur de farine se vendit un sicle, selon la parole du Seigneur, et la double mesure d\'orge se vendit un sicle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Or, le roi avait placé devant la porte le grand officier, sur le bras duquel il s\'appuyait habituellement; et le peuple le foula aux pieds devant la porte, et il mourut, comme le lui avait dit l\'homme de Dieu, quand il était venu auprès de lui comme messager du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Alors, s\'accomplit la parole d\'Elisée au roi, quand il avait dit: La double mesure d\'orge se vendra un sicle, et la mesure de fleur de farine un sicle, et ce sera demain, à pareille heure, devant la porte de Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Or, le grand officier avait répondu au prophète: A moins que le Seigneur n\'en fasse tomber du ciel des cataractes, cette parole peut-elle s\'accomplir? A quoi Elisée avait repris: Tu le verras de tes yeux, mais tu n\'en mangeras point.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Et il en fut ainsi; le peuple le foula aux pieds devant la porte, et il mourut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Ensuite, Elisée parla à la femme dont il avait ressuscité le fils, disant: Lève-toi; pars, toi et ta maison; va, demeure où tu pourras; car le Seigneur a appelé sur cette terre la famine; elle y est venue pour sept ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Et la femme se leva; elle fit selon la parole d\'Élisée, elle et toute sa maison; puis, elle demeura sept ans au pays des Philistins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'A la fin des sept ans, la femme revint du pays des Philistins en sa ville, et elle alla réclamer du roi sa maison et ses champs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Or, le roi avait parlé à Giézi, serviteur d\'Elisée, homme de Dieu, disant: Raconte-moi toutes les grandes choses qu\'a faites Elisée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Et ceci advint: tandis qu\'il racontait au roi comment il avait ressuscité l\'enfant mort, la femme dont Elisée avait ressuscité le fils entra pour réclamer du roi sa maison et ses champs. Et Giézi s\'écria: O roi mon maître, voici la femme, et voici son fils qu\'Elisée a ressuscité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Le roi questionna la femme, qui lui raconta tout; et le roi lui donna un eunuque, à qui il dit: Rends-lui tout ce qui était à elle, et tous les produits de ses champs, depuis le jour où elle les a quittés jusqu\'à ce jour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Et Elisée alla à Damas, où Ben-Ader, roi de Syrie, était malade; on alla dire à ce dernier: L\'homme de Dieu est venu jusqu\'ici.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Et le roi dit à Azaël: Prends en ta main un présent; va trouver l\'homme de Dieu, et, par lui, demande au Seigneur si je guérirai de cette maladie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Azaël partit à la rencontre du prophète, ayant en la main un présent, et, de tout ce qu\'il y avait de bon à Damas, la charge de quarante chameaux; il marcha, s\'arrêta devant Elisée, et il lui dit: Ton fils Ben-Ader, roi de Syrie, m\'envoie t\'interroger, disant: Guérirai-je de cette maladie?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elisée dit: Retourne-t\'en, et dis-lui: Tu vivras certainement; mais le Seigneur m\'a appris qu\'il mourrait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Or, l\'homme de Dieu était en présence d\'Hazaël; il lui parla tout confus, et il se prit à pleurer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Et Azaël lui dit: Pourquoi mon seigneur pleure-t-il? Il répondit: Parce que je sais combien de malheurs tu causeras aux fils d\'Israël; tu livreras aux flammes leurs forteresses, tu feras périr par l\'épée leurs plus vaillants, tu écraseras leurs enfants à la mamelle, et tu feras avorter les femmes enceintes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Et Azaël répondit: Qu\'est donc ce chien mort, ton serviteur, pour accomplir de telles choses? Et le prophète reprit: Le Seigneur m\'a montré que tu serais roi de Syrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Et il se sépara d\'Elisée pour rentrer chez son maître; celui-ci lui demanda: Que t\'a dit Elisée? Il répondit: Que tu vivras.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Et, quand vint l\'aurore, il prit un manteau épais, le plongea dans l\'eau, et en couvrit la figure du roi qui mourut, et Azaël régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'La cinquième année du règne de Joram en Israël, et, du vivant de Josaphat, roi de Juda, Joram, fils de Josaphat, commença à régner.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Il avait trente-deux ans, et il régna huit ans en Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Il marcha dans la voie des rois d\'Israël comme avait fait la maison d\'Achab, parce que la fille d\'Achab était sa femme, et il fit le mal devant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Mais le Seigneur ne voulut pas détruire Juda, à cause de David, son serviteur; car il avait promis de lui donner un flambeau, et de le conserver toujours à ses fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Sous le règne de Joram, Edom s\'affranchit du joug de Juda, et se donna un roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Et Joram marcha sur Séir avec tous ses chars; il tailla en pièces Edom, qui l\'avait enveloppé lui et les chefs des chars; et ce peuple s\'enfuit chacun en sa demeure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Toutefois, Edom s\'affranchit pour toujours du joug de Juda; en ce même temps-là, Lobna s\'affranchit pareillement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Quant au reste de l\'histoire de Joram, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Et Joram s\'endormit avec ses pères; il fut enseveli auprès d\'eux dans la ville de David, son aïeul; et Ochozias, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Son règne commença dans la onzième année du règne de Joram en Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Il avait vingt-deux ans, et il régna un an à Jérusalem, et sa mère était Athalie, issue d\'Ambri, roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Il marcha dans la voie de la maison d\'Achab, et il fit le mal devant le Seigneur, comme la maison d\'Achab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Il alla avec Joram, fils d\'Achab, combattre Azaël, roi des Syriens, à Ramoth-Galaad, où les Syriens blessèrent Joram.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Et le roi Joram revint à Jezraël pour se guérir des blessures qu\'il avait reçues à Ramoth-Galaad, dans la bataille livrée au roi de Syrie; et Ochozias, fils de Joram, alla voir Joram, fils d\'Achab, parce qu\'il était malade.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Alors, le prophète Elisée appela l\'un des fils des prophètes, et il lui dit Ceins-toi les reins; prends en tes mains cette fiole d\'huile, et va à Ramoth- Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Entre, et tu verras Jéhu, fils de Josaphat fils de Namsi; tu iras auprès de lui et tu l\'emmèneras du milieu de ses frères, en un lieu retiré de ses appartements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Et tu prendras la fiole d\'huile; tu la lui verseras sur la tête, et tu diras: Voici ce que dit le Seigneur: Je t\'ai sacré roi d\'Israël; cela dit, tu ouvriras la porte, et tu partiras rapidement sans t\'arrêter.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Et le jeune prophète alla en Ramoth-Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Il entra, il vit les chefs de l\'armée assis ensemble, et il dit: Un mot à toi, chef. Jéhu demanda: Auquel de nous? Il répondit: A toi, chef,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Et Jéhu se leva, et ils allèrent à l\'intérieur de la maison; là, le prophète lui versa l\'huile sur la tête, et lui dit: Voici ce que dit le Seigneur Dieu d\'Israël: Je t\'ai sacré roi du peuple du Seigneur, roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Et tu extermineras de devant ma face la maison d\'Achab, ton maître; tu vengeras le sang des prophètes, mes serviteurs, et le sang de tous mes serviteurs qu\'a répandu la main de Jézabel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Et celui qu\'a répandu toute la maison d\'Achab; tu extermineras tout mâle de la maison d\'Achab, tout ce qui se tient enfermé et survit en Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Et je traiterai la maison d\'Achab comme celle de Jéroboam, fils de Nabat, comme celle de Baasa, fils d\'Achias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Et les chiens dévoreront Jézabel dans le champ de Jezraël, et il n\'y aura personne qui l\'ensevelisse. Puis, le prophète ouvrit la porte et s\'enfuit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Jéhu revint auprès des serviteurs de son maître, et ils lui dirent: Tout va bien. Pourquoi cet épileptique est-il venu te trouver? Il leur répondit: Vous connaissez l\'homme et son bavardage?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Mais ils dirent: Nullement, raconte-nous-le donc. Alors, Jéhu leur dit: Il m\'a parlé de telle et de telle manière, ajoutant: Voici ce que dit le Seigneur: Je t\'ai sacré roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Dès qu\'ils l\'eurent ouï, ils s\'empressèrent; chacun ôta son manteau et le mit sous les pieds de Jéhu au faîte des degrés; puis, ils sonnèrent du cor, et ils dirent: Jéhu est roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Ainsi, Jéhu, fils de Josaphat, fils de Namsi, se révolta contre Joram. Alors, Joram défendait Ramoth-Galaad, avec tout Israël, contre Azaël, roi de Syrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Et le roi Joram était revenu à Jezraël pour se guérir des blessures que les Syriens lui avaient faites quand il avait combattu Azaël, roi de Syrie. Et Jéhu dit aux siens: Si votre âme est avec moi, ne laissez sortir de la ville personne qui puisse aller tout dire à Jezraël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Ensuite, Jéhu monta à cheval, partit, et descendit à Jezraél, où le roi Joram était à panser les blessures que lui avaient faites les flèches des archers syriens quand il avait combattu Azaël, roi de Syrie; car il était vaillant et plein de force. Et Ochozias, roi de Juda, était venu voir Joram.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Et une sentinelle montée sur la tour de Jezraël, vit la poussière que soulevait Jéhu en approchant; et elle dit: Je vois de la poussière. A quoi Joram répondit: Prends un cavalier; fais-le partir au-devant d\'eux; qu\'il demande: Est-ce la paix?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Et un cavalier partit à leur rencontre, et il dit: Voici ce que dit le roi: Est-ce la paix? Jéhu répliqua: Qu\'y a-t-il entre toi et la paix? Va te joindre à ceux qui me suivent. Cependant, la sentinelle fit ce rapport: Le messager est allé jusqu\'à eux, et il n\'est point revenu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Et elle envoya un second messager; celui-ci arriva près d\'eux, et il dit: Voici ce que dit le roi: Est-ce la paix? Jéhu répliqua: Qu\'y a-t-il entre toi et la paix? Va te joindre à ceux qui me suivent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'L\'homme en sentinelle fit derechef ce rapport: Il est allé jusqu\'à eux, et il n\'est point revenu; le chef paraît être Jéhu, fils de Namsi; car il marche comme un furieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Et Joram dit: Qu\'on attelle. On attela son char; et Joram, roi d\'Israël, sortit avec Ochozias, roi de Juda, chacun sur son char; ils allèrent à la rencontre de Jéhu, et ils le trouvèrent dans le champ de Naboth le Jezraélite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Dès que Joram vit Jéhu, il s\'écria: Est-ce la paix, Jéhu? Jéhu répondit: Quoi! la paix! quand Jézabel, ta mère, multiplie ses débauches et ses sortilèges?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Alors, Joram tourna bride, s\'enfuit, et dit au roi de Juda Trahison! Ochozias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Mais Jéhu tendit son arc avec force, et il atteignit Joram entre les épaules; la flèche lui traversa le cœur, et il s\'affaissa sur ses genoux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Puis, Jéhu dit à Badecar, son lieutenant: Jette-le dans le champ de Naboth le Jezraélite; car je me souviens, et tu te souviens aussi, que, quand nous étions sur un char à la suite d\'Achab, son père, le Seigneur a prononcé cette sentence:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Si je n\'avais point vu hier le sang de Naboth et le sang de ses fils! dit le Seigneur; mais je les vengerai dans ce champ même, dit le Seigneur. Maintenant, prends-le et jette-le dans le champ, selon la parole du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Et Ochozias, roi de Juda, vit tout, et il prit la fuite par le chemin de Bethgan; Jéhu le poursuivit, et il dit: Tuez aussi celui-là. L\'un de ses gens le frappa sur son char comme il montait en Haï (la même que Jéblaam). Et Ochozias se réfugia dans Mageddo, où il mourut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Ses serviteurs le placèrent sur son char; ils le ramenèrent à Jérusalem, et ils l\'ensevelirent dans son sépulcre en la ville de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Ochozias était devenu roi de Juda, la onzième année du règne de Joram en Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Ensuite, Jéhu entra dans Jezraël; Jézabel l\'ouït, elle se farda le tour des yeux, orna sa tête, et se pencha à sa fenêtre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Quand Jéhu passa, elle lui cria: Zambri s\'est-il bien trouvé d\'avoir tué son maître?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Il leva les yeux vers sa fenêtre; il la vit, et il dit: Qui es-tu? Descends auprès de moi. Or, il y avait là deux eunuques qui se penchèrent vers lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Jéhu leur dit: Jetez-la par la fenêtre. Et ils la jetèrent; son sang jaillit sur les murs et sur les chevaux, et les chevaux la foulèrent aux pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Ensuite, Jéhu entra dans le palais; il mangea et il but; puis, il dit: Allez voir cette maudite, et ensevelissez-la, car c\'est une fille de roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Et ses gens sortirent pour l\'inhumer; mais ils ne trouvèrent plus rien d\'elle que le crâne, les pieds et les paumes des mains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Ils rentrèrent; ils lui en firent le rapport, et il dit: C\'est la parole du Seigneur qu\'il a dite par Elie le Thesbite, disant: Dans les champs de Jezraël, les chiens dévoreront les chairs de Jézabel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Et son cadavre sera comme du fumier sur la surface du champ de Jezraël, et nul ne pourra dire: C\'est Jézabel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Il y avait alors en Samarie soixante-dix fils d\'Achab: Jéhu écrivit une lettre qu\'il envoya dans Samarie aux chefs, aux anciens de la ville et aux gardiens des enfants d\'Achab; il leur disait:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Aussitôt que cette lettre vous sera parvenue, vous qui avez avec vous les fils de votre maître, et des chars, et des forteresses, et des armes,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Vous considèrerez quel est le meilleur et le plus droit des fils de votre maître, vous le placerez sur le trône de son père, et vous combattrez pour la maison de votre maître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Or, ils eurent crainte, et ils dirent: Si deux rois n\'ont pu tenir devant lui, comment lui résisterons-nous?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Et les chefs du palais, ceux de la ville, ainsi que les anciens et les gardiens des enfants, envoyèrent des messagers à Jéhu, disant: Nous aussi nous sommes tes serviteurs; tout ce que tu nous diras nous le ferons; nous ne proclamerons point de roi, nous ferons ce que bon te semblera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Jéhu leur écrivit une seconde lettre, où il disait: Si vous êtes à moi, si vous êtes dociles à mes ordres, prenez les têtes des hommes fils de votre maître, et apportez-les-moi demain, à pareille heure, en Jezraël. Or, les fils du roi étaient au nombre de soixante-dix, et les premiers de la ville les élevaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Dès que la lettre leur fut parvenue, ils prirent les fils du roi et ils les égorgèrent au nombre de soixante-dix. Puis, ils mirent les têtes dans des paniers, et ils les envoyèrent à Jéhu en Jezraël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Et le messager de Jéhu revint, et il fit son rapport, disant: Ils ont apporté les têtes des fils du roi. Et Jéhu dit: Faites-en deux monceaux, et laissez-les jusqu\'à demain matin des deux côtés de la porte de la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'L\'aurore parut, et il sortit; il s\'arrêta, et il dit à tout le peuple: Vous êtes justes: voilà que je me suis révolté contre mon maître, je l\'ai tué; mais qui donc à frappé tous ceux-ci?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Vous le voyez, nulle des paroles que le Seigneur a dites contre la maison d\'Achab ne devait tomber à terre; le Seigneur a exécuté tout ce qu\'il nous avait dit par Elie, son serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Et Jéhu extermina tout ce qu\'il y avait encore de la maison d\'Achab en Jezraël, et tous ses hommes éminents, tous ses amis et ses prêtres; pas un seul ne fut épargné.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Puis, il se mit en marche pour Samarie; il était dans la maison des bergers, sur la route,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Quand il rencontra les frères d\'Ochozias, roi de Juda, et il leur dit: Qui êtes-vous? Ils répondirent: Nous sommes les frères d\'Ochozias, et nous sommes partis pour saluer les fils du roi et les fils de la reine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Aussitôt, il dit: Prenez-les vifs. On les prit, et on les égorgea dans la maison des bergers: quarante-deux hommes! il n\'en resta pas un seul.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Et, s\'étant éloigné de ce lieu, il rencontra Jonadab, fils de Rhéchab; celui-ci le bénit, et Jéhu lui dit: Ton cœur est-il sincèrement avec le mien, comme mon cœur est avec le tien? Jonadab répondit: Il l\'est. Jéhu reprit: S\'il l\'est, donne-moi la main. Jonadab lui donna la main, et Jéhu le fit monter à côté de lui sur son char.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Et il lui dit: Viens avec moi, tu verras mon zèle pour le Seigneur. Puis, il le fit asseoir sur le siège.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Et il entra dans Samarie, et il extermina tout ce qui restait d\'Achab, jusqu\'à ce qu\'il l\'eût effacé, selon la parole que le Seigneur avait dite par la bouche d\'Elie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Ensuite, Jéhu rassembla tout le peuple, et il leur dit: Achab a servi faiblement Baal, Jéhu le servira magnifiquement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Maintenant donc, vous tous prophètes de Baal, convoquez ici tous ses serviteurs et tous ses prêtres, sans qu\'il manque un seul homme, car je vais faire un grand sacrifice à Baal; quiconque se cachera sera mis à mort. Or, Jéhu usait d\'artifice pour détruire tous les serviteurs de Baal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Il ajouta: Sanctifiez le sacerdoce de Baal. Et on fit une proclamation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Et Jéhu envoya des messagers en tout Israël, disant: Que de tous ses serviteurs, de tous ses prêtres, de tous ses prophètes, aucun ne fasse défaut, car je prépare un grand sacrifice. Celui qui ne viendra point ne restera pas en vie. Et tous les serviteurs de Baal vinrent, ainsi que tous ses prêtres et tous ses prophètes; il n\'y eut pas un homme qui ne vînt. Et ils entrèrent dans le temple de Baal, et le temple de Baal fut rempli d\'un bout à l\'autre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Et Jéhu dit au gardien des vêtements du temple: Apporte des robes pour tous les serviteurs de Baal. Et le gardien leur en donna.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Et Jéhu, avec Jonadab, fils de Rhéchab, entra dans le temple de Baal, et il dit aux serviteurs de Baal: Cherchez, voyez s\'il y a parmi vous des serviteurs du Seigneur, ou seulement des serviteurs de Baal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Puis, il pénétra plus loin pour offrir l\'encens et les holocaustes. Or, il avait aposté dehors quatre-vingts de ses hommes, leur disant: Celui qui laissera échapper l\'un de ceux que je livre entre vos mains, paiera de sa vie celle qu\'il aura sauvée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Après qu\'il eut consumé l\'holocauste, Jéhu dit à ses gardes et à ses officiers: Entrez, frappez-les, n\'en laissez pas sortir un seul. Et ils les passèrent an fil de l\'épée; ils les jetèrent sur le chemin; et, du temple de Baal, ils retournèrent à la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Et ils emportèrent la colonne de Baal, et ils la brûlèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Ils abattirent les colonnes de Baal, et, du temple, ils firent des latrines, qui existent encore de nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Jéhu effaça Baal de la terre d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Seulement, il ne se retira pas du péché de Jéroboam, fils de Nabat, du péché où il avait fait tomber Israël; il conserva les génisses d\'or de Béthel et de Dan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Le Seigneur dit à Jéhu: En récompense de ce que tu as fait d\'agréable à mes yeux, de ce que tu as traité selon mon cœur la maison d\'Achab, tes fils régneront sur Israël jusqu\'à la quatrième génération.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Mais Jéhu ne fut pas attentif à marcher de tout son cœur selon la loi du Seigneur Dieu d\'Israël; il ne se retira pas du péché de Jéroboam, du péché où il avait fait tomber tout le peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Et, en ces jours-là, le Seigneur commença de châtier Israël; Azaël le vainquit sur toutes ses frontières,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Jusqu\'à la rive orientale du Jourdain; il envahit toute la terre de Galaad, savoir: les tribus de Gad et de Ruben, et le territoire de Manassé, à partir d\'Aroer, qui est sur les bords du torrent d\'Anion, et Galaad et Basan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Quant au reste de l\'histoire de Jéhu, aux actions qu\'il fit en sa puissance et à ses combats, ne sont-ils pas écrits au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Et Jéhu s\'endormit avec ses pères; on l\'ensevelit en Samarie, et son fils Joachaz régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Jéhu avait régné vingt ans sur Israël en Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Et Athalie, mère d\'Ochosias, ayant vu que son fils était mort, détruisit toute la race royale.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Mais Josabeth, fille du roi Joram, sœur d\'Ochosias, enleva Joas, fils de son frère; elle le déroba du milieu des fils du roi que l\'on massacrait, et le mit, avec sa nourrice, dans une alcôve des chambres à coucher; puis, elle le cacha d\'Athalie, et il ne fut point tué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Il resta six ans caché avec elle dans le temple du Seigneur, pendant qu\'Athalie régnait sur la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Dans la septième année, Joïada envoya des messagers, et convoqua les centeniers des gardes et des coureurs; il les emmena dans le temple du Seigneur, et il fit avec eux l\'alliance du Seigneur; il leur fit prêter serment, leur montra le fils du roi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Et leur donna ses ordres, disant: Voilà ce que vous ferez. Le tiers de vos hommes, entrant en semaine, gardera la porte qui mène au palais du roi;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Un autre tiers gardera la porte de la grande rue, et le dernier tiers la porte derrière les coureurs; vous garderez tous le temple,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Et vous formerez deux troupes; tous ceux qui sortiront de semaine garderont aussi le temple du Seigneur auprès du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Ils entoureront le roi les armes à la main; quiconque entrera dans les rangs mourra; ils ne quitteront pas le roi, soit qu\'il entre, soit qu\'il sorte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Et les centeniers firent tout ce que leur avait prescrit le sage Joïada. Chacun d\'eux prit ses hommes; et ceux qui entraient en semaine se réunirent à ceux qui en sortaient, et ils s\'introduisirent auprès de Joïada le prêtre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Et le prêtre leur donna les épées et les lances du roi David qui étaient dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Et chacun des coureurs se tenait, les armes à la main, tant à droite qu\'à gauche de l\'autel, occupant les deux ailes du temple et entourant le roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Alors, Joïada leur présenta le fils du roi Ochozias; il lui donna la couronne et le livre de la loi, il le proclama roi et il le sacra; et les assistants battirent des mains, et ils crièrent: Vive le roi!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Et Athalie entendit la clameur de ceux du peuple qui couraient; elle entra, parmi le peuple, dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Elle vit le roi assis sur son trône selon la coutume; puis, autour de lui, les chanteurs, les trompettes. Et tout le peuple de la terre, plein de joie, sonnait de la trompette. Et Athalie déchira ses vêtements, et elle cria: Complot! complot!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Et le prêtre Joïada donna ses ordres aux centeniers, chefs de l\'armée; il leur dit: Entraînez-la hors des rangs; quiconque la suivra, mourra de mort par l\'épée. Et le prêtre ajouta: Qu\'elle ne meure point dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Ils mirent donc la main sur elle; et ils sortirent, prenant le chemin par où passaient les chevaux de la maison du roi, et là, ils la tuèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Et Joïada fit alliance entre le Seigneur et le roi; puis, entre le Seigneur et le peuple, pour que le peuple demeurât le peuple de Dieu; puis, enfin, entre le roi et le peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Et tout le peuple de la terre entra dans le temple de Baal; ils le renversèrent, ils brisèrent ses autels et ses images, et ils tuèrent devant l\'autel Mathan, prêtre de Baal. Ensuite, Joïada plaça des surveillants dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Il se mit à la tête des centeniers, des gardes, des coureurs et de tout le peuple de la terre; ils emmenèrent le roi du temple du Seigneur, et ils prirent la rue de la porte des coureurs du roi, et ils le firent asseoir sur le trône royal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Et tout le peuple de la terre fut en joie; la ville resta calme; Athalie avait péri par l\'épée dans le palais du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Joas avait sept ans quand commença son règne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Joas monta sur le trône la septième année du règne de Jéhu; il régna quarante ans à Jérusalem; le nom de sa mère était Sabia de Bersabée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Et Joas fit ce qui était droit devant le Seigneur tant que le prêtre Joïada vécut pour l\'éclairer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Seulement, aucun des autels des hauts lieux ne fut déplacé; le peuple y fit encore des sacrifices et y brûla de l\'encens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Or, Joas dit aux prêtres: Que les prêtres prennent tout l\'argent des choses saintes, entrant dans le temple du Seigneur, et provenant soit des évaluations, soit des dons que chacun fait au gré de son cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Que les prêtres le prennent, chacun selon son rang, et qu\'ils l\'emploient aux réparations du temple partout où ils en trouveront à faire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'En la vingt-troisième année du règne de Joas, le temple n\'était pas encore entièrement réparé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Alors, le roi Joas fit venir le prêtre Joïada et les autres prêtres, et il leur dit: Pourquoi le temple n\'est-il pas réparé? Désormais, ne prenez plus d\'argent selon votre rang; donnez-le pour réparer le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Et les prêtres consentirent à ne plus recevoir d\'argent du peuple, pourvu qu\'ils ne fussent plus chargés des réparations du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Et Joad le prêtre prit une cassette; il en troua le couvercle, et il le mit près de l\'autel, en la demeure d\'un homme appartenant au temple du Seigneur. Puis, les prêtres, gardiens de la porte, y versèrent tout l\'argent trouvé dans la maison du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Lorsqu\'ils virent qu\'il y avait beaucoup d\'argent dans la cassette, le scribe du roi et le grand prêtre lièrent et comptèrent l\'argent trouvé dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Puis, il remirent l\'argent qu\'on avait recueilli entre les mains de ceux qui exécutaient les travaux signalés par les surveillants du temple du Seigneur; ils en donnèrent aussi aux charpentiers et aux constructeurs employés au temple,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Ainsi qu\'aux maçons et aux tailleurs de pierre, afin qu\'ils achetassent des bois et des pierres de taille pour consolider le temple, jusqu\'à ce que l\'on eût dépensé tout ce que l\'on avait reçu, pour les réparations du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Mais on ne devait rien prendre de l\'argent offert dans le temple du Seigneur, pour fabriquer les portes d\'argent, les clous, les fioles, les trompettes, les vases d\'or et les vases d\'argent;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Parce qu\'on devait le donner à ceux qui faisaient les réparations; et ceux-ci l\'employèrent à consolider le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Et l\'on ne demanda pas de comptes aux hommes à qui l\'argent fut donné, pour qu\'ils le remissent aux ouvriers chargés des travaux, parce que les réparations furent exécutées de bonne foi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'L\'argent dû pour les péchés, l\'argent dû pour les omissions, tout ce qu\'on apporta dans le temple alla aux prêtres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'En ce temps-là, Azaël, roi de Syrie, sortit pour combattre Geth, et il s\'en empara; puis, il se retourna pour marcher sur Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Mais Joas, roi de Juda, prit toutes les offrandes consacrées par Josaphat, par Joram et par Ochozias, ses pères, rois de Juda; il prit ses propres offrandes et tout l\'or qui se trouva, soit dans le temple du Seigneur, soit dans le palais du roi; puis, il envoya tout à Azaël, roi de Syrie; et celui-ci s\'éloigna de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Quant au reste de l\'histoire de Joas, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Et ses serviteurs se révoltèrent; ils tramèrent un complot, et ils frappèrent Joas en la maison de Mello qui est à Sella.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 22, 'Jézirchar, fils de Jémuath, et Jézébuth, fils de Somer, ses serviteurs, le frappèrent, et il mourut; on l\'ensevelit auprès de ses pères en la ville de David; et son fils Amasias régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'En la vingt-troisième année du règne de Joas, fils d\'Ochozias, roi de Juda, Joachaz, fils de Jéhu, commença en Samarie un règne qui dura dix-sept ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Et il fit le mal aux \'yeux du Seigneur; il marcha dans les péchés où Jéroboam, fils de Nabat, avait fait tomber les fils d\'Israël, et il ne s\'en retira point.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Et le Seigneur se courrouça contre Israël; il les livra aux mains d\'Azaël, roi de Syrie, et aux mains d\'Ader, fils d\'Azaël, tant que ces rois vécurent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Mais Joachaz implora le Seigneur, et le Seigneur l\'écouta, parce qu\'il vit l\'affliction d\'Israël; car le roi de Syrie l\'affligeait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Et le Seigneur sauva Israël; le peuple fut affranchi du joug des Syriens, et les fils d\'Israël furent tranquilles en leurs demeures comme autrefois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Cependant, ils ne se retirèrent point des péchés où la maison de Jéroboam avait lait tomber Israël; ils marchèrent dans ces péchés, et laissèrent debout le bois sacré en Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Or, Joachaz n\'avait plus d\'armée, sauf cinquante cavaliers, dix chars et dix mille piétons, parce que le roi de Syrie avait détruit ses troupes, et les avait broyées comme la poussière que l\'on foule aux pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Quant au reste de l\'histoire de Joachaz, aux actions qu\'il fit en sa puissance, ne sont-ils pas écrits au livre des Faits et gestes des rois d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Et Joachaz s\'endormit avec ses pères; on l\'ensevelit en Samarie, et Joas, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'En la trente-septième année du règne de Joas, roi de Juda, Joas, fils de Joachaz, roi d\'Israël, commença en Samarie un règne qui dura seize ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Et il fit le mal aux yeux du Seigneur, et il ne se retira point des péchés où Jéroboam avait fait tomber Israël; il marcha dans ces péchés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Quant au reste de l\'histoire de Joas, roi d\'Israël, et à ses combats avec Amasias, roi de Juda, ne sont-ils pas écrits au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Et Joas s\'endormit avec ses pères; il avait assis sur son trône Jéroboam, et il fut enseveli en Samarie avec les rois d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Et Elisée tomba malade, de la maladie dont il mourut; Joas, roi d\'Israël, l\'alla trouver; il pleura devant lui, et il dit: Père, père, char et conducteur d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elisée lui dit: Prends un arc et une flèche; il prit donc un arc et une flèche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Puis, le prophète dit au roi: Place ta main sur l\'arc. Joas y plaça la main, et Elisée imposa ses mains sur les mains du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Ensuite, il dit: Ouvre la fenêtre du côté de l\'orient. Le roi ouvrit, et Elisée lui dit: Lance le trait. Il le lança, et le prophète dit: Trait de salut du Seigneur, trait de salut contre la Syrie; tu triompheras de la Syrie en Aphec, jusqu\'à ce que tu l\'aies consumée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Elisée lui dit encore: Prends l\'arc et les flèches. Le roi les prit, et le prophète dit au roi: Frappe la terre. Et le roi frappa trois fois; puis, il s\'arrêta.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'L\'homme de Dieu s\'en affligea sur lui, et il dit: Si tu avais frappé cinq ou six fois, tu aurais frappé la Syrie jusqu\'à ce que tu l\'eusses consumée. Maintenant, tu ne remporteras sur elle que trois victoires.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Et le prophète mourut, et on l\'ensevelit; et des maraudeurs de Moab, au commencement de cette année, vinrent dans la terre promise.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Or, ceci advint: pendant qu\'on ensevelissait Elisée, on vit le corps d\'un maraudeur; on le jeta dans la fosse du prophète; il y roula, il toucha les ossements d\'Elisée, il ressuscita et il se leva sur ses pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Azaël avait grandement affligé le peuple tout le temps de la vie de Joachaz.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Mais le Seigneur eut pitié et compassion des fils d\'Israël; il les regarda favorablement, à cause de son alliance avec Abraham, Isaac et Jacob; et le Seigneur ne voulut pas les détruire, il ne les rejeta pas de devant sa face.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Et Azaël mourut, et son fils Ader régna après lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Alors, Joas, fils de Joachaz, se remit en campagne, et il prit à Ader les villes que son père avait prises à Joachaz. Joas remporta trois victoires, et il reprit les villes d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'En la seconde année de Joas, fils de Joachaz, roi d\'Israël, commença le règne d\'Amasias, fils de Joas, roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Il avait alors vingt-cinq ans, et il en régna vingt-neuf en Jérusalem; le nom de sa mère était Joadim de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Et il fit ce qui était droit aux yeux du Seigneur, mais non pas comme David, son aïeul. Il fit tout ce qu\'avait fait Joas, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Il ne détruisit point les hauts lieux; le peuple offrit encore des sacrifices, et brûla de l\'encens sur les hauts lieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Quand la royauté fut affermie dans ses mains, il tua ceux de ses serviteurs qui avaient frappé son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Mais il ne fit pas périr les fils des meurtriers, se conformant à ce qui est écrit au livre de la loi de Moïse, et à l\'ordonnance du Seigneur, disant: Les pères ne seront pas mis à mort à cause des fils, et les fils ne seront pas mis à mort à cause des pères; chacun mourra pour son péché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Ensuite, il tailla en pièces, dans la vallée des Sels, dix mille hommes de l\'Idumée; et il prit, en cette guerre, le rocher auquel il donna le nom de Jéthoël, nom qui lui est resté jusqu\'à nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Alors, Amasias envoya des messagers à Joas, fils de Joachaz, fils de Jéhu, roi d\'Israël, disant: Viens, que nous nous voyions face à face.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Mais Joas, roi d\'Israël, fit répondre au roi de Juda: Le chardon du Liban envoya des gens au cèdre pour lui dire: Donne ta fille à mon fils pour femme; et les bêtes fauves du champ voisin passèrent, et elles foulèrent aux pieds le chardon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Tu as battu l\'Iduméen, et ton cœur s\'est exalté; glorifie-toi tranquillement en ta demeure; à quoi bon me cherches-tu querelle pour ta perte? Tu tomberas, et avec toi Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Amasias ne l\'écouta point; et Joas, roi d\'Israël, partit, et ils se virent face à face à Bethsamys en Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Mais Juda tomba devant Israël, et chacun s\'enfuit en sa demeure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Et Joas, roi d\'Israël, fit prisonnier, à Bethsamys, Amasias, fils de Joas, fils d\'Ochozias; il entra à Jérusalem, et il abattit le rempart depuis la porte d\'Ephraïm jusqu\'à la porte de l\'angle, sur une longueur de quatre cents coudées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Il prit l\'argent et l\'or, et tous les ornements qu\'il trouva soit dans le temple du Seigneur, soit dans le palais du roi; il se fit donner des otages, et il retourna en Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Quant au reste de l\'histoire de Joas, et à ses combats avec Amasias, ne sont-ils pas écrits au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Et Joas s\'endormit avec ses pères; il fut enseveli à Samarie avec les rois d\'Israël, et Jéroboam, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Amasias, fils de Joas, roi de Jérusalem, vécut encore quinze ans après la mort de Joas, fils de Joachaz, roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Quant au reste de l\'histoire d\'Amasias, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Et il y eut un complot contre lui en Jérusalem; il se réfugia à Lachis, où les conjurés le poursuivirent, et ils le tuèrent dans cette ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Puis, ils l\'enlevèrent sur un char, et il fut enseveli à Jérusalem auprès de ses pères, dans la ville de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Et tout le peuple de Juda fit choix d\'Azarias, alors âgé de seize ans, et ils le proclamèrent roi à la place d\'Amasias son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Ce fut lui qui bâtit Elath, après l\'avoir reprise pour Juda, lorsque le roi eut été déposé auprès de ses pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'En la quinzième année du règne d\'Amasias, fils de Joas, roi de Juda, Jéroboam, fils de Joas, roi d\'Israël, commença un règne qui dura quarante et un ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Et il fit le mal devant le Seigneur; il ne se retira pas des péchés où Jéroboam, fils de Nabat, avait fait tomber Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Ce fut lui qui rétablit les limites d\'Israël, depuis l\'entrée d\'Emath jusqu\'à la mer d\'Araba, selon la parole que le Seigneur Dieu d\'Israël avait fait connaître par son serviteur le prophète Jonas, fils d\'Amatbi, de Gethchopher;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Parce que le Seigneur avait vu l\'abaissement bien triste d\'Israël, son petit nombre, son asservissement, son indigence et son isolement; car il n\'était personne qui secourût Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Et le Seigneur dit qu\'il ne voulait pas effacer sous les cieux la race d\'Israël; mais il la sauva par les mains de Jéroboam, fils de Joas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Quant au reste de l\'histoire de Jéroboam, et aux actions qu\'il fit en sa puissance, et aux combats qui rendirent Damas et Emath de Juda à Israël, ne sont-ils pas écrits au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Et Jéroboam s\'endormit avec ses pères, avec les rois d\'Israël, et Zacharias, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'En la vingt-septième année du règne de Jéroboam en Israël, Azarias, fils d\'Amasias, monta sur le trône de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Il avait seize ans quand il devint roi, et il régna cinquante-deux ans à Jérusalem; sa mère se nommait Jéchélie de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Et il fit ce qui était droit aux yeux du Seigneur; il fit tout ce qu\'avait fait son père Amasias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Mais il ne détruisit point les hauts lieux, et le peuple offrit encore des sacrifices et brûla de l\'encens sur les hauts lieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Or, le doigt du Seigneur avait touché le roi, et il fut lépreux jusqu\'à sa mort, et il passa son règne dans une maison séparée; Joatham, fils du roi, régissait le palais, et jugeait le peuple de la terre promise.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Quant au reste de l\'histoire d\'Azarias, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Et Azarias s\'endormit avec ses pères; on l\'ensevelit auprès d\'eux en la ville de David, et Joatham, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'En la trente-huitième année du règne d\'Azarias en Juda, Zacharias, fils de Jéroboam, commença en Samarie un règne qui dura six mois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Et il fit le mal aux yeux du Seigneur comme avaient fait ses pères; il ne se retira point des péchés où Jéroboam, fils de Nabat, avait fait tomber Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Et Sellum, fils de Jabès, et d\'autres conspirèrent contre lui; ils le frappèrent devant le peuple et le tuèrent; et Sellum régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Le reste de l\'histoire de Zacharie est écrit au livre des Faits et gestes des rois d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Le Seigneur avait dit à Jéhu: Tes fils se maintiendront sur le trône d\'Israël jusqu\'à la quatrième génération. Et sa parole s\'accomplit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sellum, fils de Jabès, fut proclamé roi; en la trente-neuvième année du règne d\'Azarias en Juda, Sellum commença à Samarie un règne qui ne dura qu\'un mois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Car, Manahem, fils de Gaddi, vint de Tharsila, entra dans Samarie, et y frappa Sellum, fils de Jabès, et il le tua.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Le reste de l\'histoire de Sellum et sa révolte sont écrits au livre des faits et gestes des rois d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Alors, Manahem dévasta Thersa, tout ce qu\'elle contenait et tout son territoire, parce que cette ville lui avait fermé ses portes; il en fit le sac, et il fit avorter des femmes enceintes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'En la trente-neuvième année du règne d\'Azarias en Juda, Manahem, fils de Gaddi, commença en Samarie un règne qui dura dix ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Et il fit le mal aux yeux du Seigneur, et il ne se retira pas des péchés où Jéroboam, fils de Nabat, avait fait tomber Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Pendant son règne, Phua, roi des Assyriens, envahit la terre; et Manahem lui donna mille talents d\'argent pour qu\'il fût son allié.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Et Manahem leva cet argent en Israël, sur tout homme riche, lui prenant cinquante sicles pour les donner au roi des Assyriens; Phua s\'en retourna, et il ne resta point dans la terre promise.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Quant au reste de l\'histoire de Manahem, n\'est-il pas écrit au livre des Faits et gestes des rois d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Et Manahem s\'endormit avec ses pères, et son fils Phaceïa régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'En la cinquantième année du règne d\'Azarias en Juda, Phaceïa commença en Samarie un règne qui dura deux ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Et il fit le mal aux yeux du Seigneur; il ne se retira pas des péchés où Jéroboam avait fait tomber Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Et Phacée, fils de Romélie, un de ses grands officiers, conspira contre lui; il le frappa dans Samarie devant le palais du roi, avec Argob; Arias et cinquante hommes des quatre cents étaient avec lui; il le tua et il régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Le reste de l\'histoire de Phaceïa est écrit au livre des Faits et gestes des rois d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'En la cinquante-deuxième année du règne d\'Azarias en Juda, Phacée, fils de Romélie, commença en Samarie un règne qui dura vingt ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Il fit le mal aux yeux du Seigneur; il ne se retira pas des péchés où Jéroboam, fils de Nabat, avait fait tomber Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Sous le règne de Phacée, roi d\'Israël, Theglath-Phalasar, roi des Assyriens, vint prendre Aïon, Abel, Thamaacha, Anioch, Cenez, Asor, Galaan, la Galilée, toute la terre de Nephthali, et il emmena les habitants chez les Assyriens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Alors, Osée, fils d\'Ela, trama un complot contre Phacée, fils de Romélie; il le frappa, le tua, et régna à sa place en la vingtième année de Joatham, fils d\'Azarias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Le reste de l\'histoire de Phacée est écrit au livre des Faits et gestes du roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'En la seconde année du règne de Phacée en Israël, Joatham, fils d\'Azarias, devint roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Il avait vingt-cinq ans lorsqu\'il monta sur le trône, et il régna seize ans à Jérusalem; sa mère se nommait Jerusa, fille de Sadoc.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Et il fit ce qui est droit aux yeux du Seigneur, comme avait fait Azarias, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Mais il ne détruisit point les hauts lieux; le peuple faisait encore des sacrifices et brûlait de l\'encens sur les hauts lieux; ce fut lui qui bâtit la porte supérieure du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Quant au reste de l\'histoire de Joatham, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'En ces jours-là, le Seigneur commença d\'envoyer contre Juda, Rasin, roi de Syrie, et Phacée, fils de Romélie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Et Joatham s\'endormit avec ses pères; il fut enseveli auprès d\'eux en la ville de David, son aieul; et Achaz, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'En la dix-septième année du règne de Phacée, fils de Romélie, Achaz, fils de Joatham, devint roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Il avait vingt ans quand il monta sur le trône, et il régna seize ans à Jérusalem; il ne fit point ce qui est droit aux yeux du Seigneur son Dieu, aussi fidèlement que David, son aïeul.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Et il marcha dans la voie des rois d\'Israël; même il livra son fils aux flammes de Moloch, selon l\'abomination des peuples que le Seigneur avait exterminés devant la face des fils d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Et il immola des victimes sur les hauts lieux, sur les collines, et sous tout arbre touffu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Alors, Rasin, roi de Syrie, et Phacée, roi d\'Israël, vinrent combattre sous les murs de Jérusalem; ils assiégèrent Achaz, mais ils ne purent prévaloir sur lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'En temps-là, Rasin reprit Elath pour la Syrie, il en chassa les Juifs, et des Iduméens y vinrent; et ils y sont demeurés jusqu\'à nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Et Achaz envoya des messagers à Theglath-Phalasar, roi des Assyriens, disant: Moi et mon fils, nous sommes tes serviteurs; viens, sauve-moi des mains du roi de Syrie, et des mains du roi d\'Israël, qui se sont levés contre moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Achaz prit l\'argent et l\'or qui se trouva dans les trésors, soit du temple, soit du palais, et il en fit présent au roi d\'Assyrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Et le roi des Assyriens l\'écouta; il marcha sur Damas, la prit, la dépeupla, et mit à mort le roi Rasin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Et le roi Achaz alla dans Damas à la rencontre de Theglath-Phalasar; il vit un autel à Damas, et il envoya au prêtre Urie l\'image de l\'autel, ses proportions, sa structure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Et le prêtre Urie bâtit un autel selon le modèle que le roi lui avait envoyé de Damas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Puis, Achaz vit l\'autel et il y monta;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Il fit son holocauste, son sacrifice et sa libation, et il répandit le sang de ses hosties pacifiques offertes sur l\'autel');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'D\'airain qui était devant le Seigneur. Et il transporta cet autel de devant la façade du temple, du lieu entre l\'autel et le temple, et il le dressa du même côté en tirant vers le nord.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Ensuite, le roi Achaz donna ses ordres au prêtre Urie, disant: Tu présenteras, sur le grand autel, l\'holocauste du matin, les oblations du soir, l\'holocauste du roi et son oblation, l\'holocauste de tout le peuple, et son oblation et sa libation; tu répandras sur le même autel tout le sang de l\'holocauste et tout le sang de toute autre victime, et l\'autel d\'airain le matin me sera réservé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Et Urie le prêtre fit tout ce que lui avait prescrit le roi Achaz.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Le roi Achaz effaça les ciselures des bassins, il enleva les cuvettes qu\'ils supportaient, et il ôta, pour la mettre sur une base de pierre, la mer qui reposait sur les bœufs d\'airain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Et il construisit une base pour le trône dans le temple du Seigneur, et il transporta à l\'intérieur la porte extérieure par laquelle le roi entrait dans le temple, à cause du roi des Assyriens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Quant au reste de l\'histoire du roi Achaz, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Et Achaz s\'endormit avec ses pères; il fut enseveli dans la ville de David, et son fils Ezéchias régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'En la douzième année du règne d\'Achaz, en Juda, Osée, fils d\'Ela, commença en Samarie, sur Israël, un règne de neuf ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Et il fit le mal aux yeux du Seigneur, mais non comme les rois d\'Israël qui avaient existé avant lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Salmanasar, roi des Assyriens, marcha contre lui; Osée lui fut asservi, et il lui paya un tribut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Ensuite, Salmanasar trouva en Osée une iniquité, en ce qu\'il avait envoyé des messagers à Ségor, roi d\'Égypte, et n\'avait point payé cette année-là le tribut au roi des Assyriens; et celui-ci l\'assiégea et le jeta, enchaîné, dans une prison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Puis, il parcourut toute la terre d\'Israël, et monta à Samarie, qu\'il assiégea trois ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Ce fut en la neuvième année du règne d\'Osée, que Salmanasar prit Samarie, et transporta Israël en Assyrie, où il l\'établit en Hala, en Habor, sur le fleuve Gozan, et sur les montagnes des Mèdes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Et cela arriva, parce que les fils d\'Israël avaient péché contre le Seigneur leur Dieu, qui les avait tirés de l\'Égypte, et délivrés des mains du roi Pharaon; parce qu\'ils avaient craint d\'autres dieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Car ils avaient marché dans les voies des nations que le Seigneur avait exterminées devant les fils d\'Israël, et dans celles des rois d\'Israël qui avaient fait de tels péchés,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Et dans celles des enfants d\'Israël, adonnés à des coutumes qui n\'étaient point selon le Seigneur leur Dieu; ils s\'étaient bâti des hauts lieux en toutes les villes, depuis les tours des guetteurs jusqu\'aux cités entourées de remparts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Et ils s\'étaient dressé des colonnes dans des bois sacrés sur toutes les hautes collines, et sous tous les arbres touffus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Et ils avaient fait des sacrifices sur tous les hauts lieux, comme les nations que le Seigneur avait expulsées de devant leur face; ils avaient formé de honteuses associations, ils avaient gravé des images pour irriter le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Et ils avaient servi des idoles au sujet desquelles le Seigneur leur avait dit: Ne faites point cette offense au Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Cependant, le Seigneur protestait en Israël et en Juda par la bouche de tous ses voyants et de tous ses prophètes, disant: Détournez-vous de vos mauvaises voies, observez mes commandements et mes préceptes; suivez en toutes choses la loi que j\'ai donnée à vos pères, et tout ce que je leur ai mandé par mes serviteurs les prophètes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Mais ils ne l\'écoutaient point; ils s\'endurcissaient le cœur plus que ne l\'avaient fait leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Ils ne gardaient aucun des témoignages que portait le Seigneur; ils marchaient à la suite des vanités, étant vains eux-mêmes; à la suite des nations qui les entouraient, au sujet desquelles le Seigneur leur avait dit: Ne faites pas comme elles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Ils abandonnaient les commandements du Seigneur leur Dieu; ils s\'étaient fait deux génisses jetées en fonte; ils plantaient des bois sacrés; ils adoraient toute l\'armée du ciel, et ils servaient Baal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Et ils faisaient passer dans la flamme de Moloch leurs fils et leurs filles; ils usaient de la divination et des présages, et ils s\'attachaient à faire le mal aux yeux du Seigneur et à l\'irriter.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Et le Seigneur conçut un grand courroux contre Israël; il le rejeta de devant sa face, et il ne resta que la seule tribu de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Et Juda lui-même n\'observa point les commandements du Seigneur son Dieu; il marcha dans les voies d\'Israël, et il répudia le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Et le Seigneur se courrouça contre toute la race d\'Israël; il les ébranla, il les livra à tous ceux qui vinrent les piller, jusqu\'à ce. qu\'il les rejetât de devant sa face.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Il le fit surtout parce qu\'Israël ayant rejeté la maison de David, et s\'étant donné pour roi Jéroboam, fils de Nabat, Jéroboam entraîna Israël hors des voies du Seigneur, et lui fit commettre un grand péché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Car, les fils d\'Israël tombèrent tous dans le péché de Jéroboam, et ils ne s\'en retirèrent point,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Jusqu\'à ce que le Seigneur eût expulsé Israël de devant sa face, comme il l\'en avait menacé par la voix de tous ses serviteurs les prophètes. Et Israël fut emmené en la terre des Assyriens, où il est encore de nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Ensuite, le roi des Assyriens amena des hommes de Babylone, de Chuth, d\'Aïa, d\'Emath, de Sepharvaïm, et il les établit en Samarie à la place des fils d\'Israël; ils se partagèrent son territoire, et ils demeurèrent dans ses villes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Dans les premiers temps de leur séjour, ils ne craignaient point le Seigneur, et le Seigneur envoya contre eux des lions qui en tuèrent quelques- uns.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Ils le firent savoir au roi des Assyriens, disant: Les nations que tu as transportées et assises dans les villes de Samarie, ne connaissaient point les jugements du Dieu de cette terre; et il a envoyé contre eux des lions; et voilà que ces lions les tuent, parce qu\'ils ne savent pas les jugements du Dieu de cette terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Et le roi des Assyriens donna ses ordres, disant: Emmenez d\'ici des gens, qu\'ils partent, qu\'ils demeurent avec vous; ils vous éclaireront sur les jugements du Dieu de cette terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Et ils emmenèrent un des prêtres qu\'on avait transportés de Samarie; il s\'établit à Béthel; il les éclaira, et il leur apprit comme ils devaient craindre le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Mais, chaque nation fabriqua ses dieux; on les plaça dans les temples des hauts lieux que les Samaritains avaient construits; chaque nation eut les siens dans les villes qu\'elle habitait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Ceux de Babylone avaient fabriqué Soccoth-Benith; ceux de Chuth, Ergel; ceux d\'Emath, Asimath;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Les Evéens fabriquèrent Eblazer et Tharthac; ceux de Sepharvaïm firent le mal quand ils brûlèrent leurs fils dans les flammes d\'Adra-Moloch et d\'Ana- Moloch, leurs dieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Ils craignaient le Seigneur; mais ils avaient établi leurs abominations dans les temples des hauts lieux qu\'avaient construits les Samaritains, chacun dans la ville que sa nation habitait; ils craignaient le Seigneur; mais ils avaient institué pour eux des prêtres des hauts lieux, et ils sacrifiaient dans les temples des hauts lieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Ils craignaient le Seigneur, mais ils servirent leurs dieux selon l\'usage des nations dont ils avaient été tirés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Jusqu\'à ce jour, ils ont agi selon leurs usages; les mêmes gens craignent le Seigneur et agissent selon leurs mœurs, selon leurs usages, et en même temps selon la loi et les préceptes que le Seigneur a donnés aux fils de Jacob, qu\'il a appelé aussi Israël;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Avec qui le Seigneur fit jadis alliance, disant: Vous ne craindrez point d\'autres dieux, vous ne les adorerez pas, vous ne les servirez point, vous ne leur ferez point de sacrifices.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Vous ne craindrez, vous n\'adorerez, vous n\'honorerez par des sacrifices que le Seigneur qui vous a ramenés d\'Égypte par sa toute-puissance, et par son bras très-haut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Vous observerez toujours les ordonnances, les jugements, la loi et les commandements qu\'il a écrits, pour que vous les pratiquiez; vous ne craindrez point d\'autres dieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Et vous n\'abandonnerez point l\'alliance qu\'il a faite avec vous, et vous ne craindrez point d\'autres dieux;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Vous ne craindrez que le Seigneur votre Dieu, et il vous délivrera de tous vos ennemis;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Vous ne suivrez point les pratiques que suivent les Gentils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Ces nations nouvelles craignaient donc le Seigneur, et elles servaient leurs idoles; et leurs fils, et les fils de leurs fils, ont fait comme leurs pères jusqu\'à nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'En la troisième année du règne d\'Osée, en Israël, Ezéchias, fils d\'Achaz, devint roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Il avait vingt-cinq ans quand il monta sur le trône, et il régna vingt- neuf ans à Jérusalem; sa mère se nommait Abu, fille de Zacharie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Et il fit ce qui est droit aux yeux du Seigneur, se conformant à tout ce qu\'avait fait David, son aïeul.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Ce fut lui qui détruisit les hauts lieux, qui abattit les colonnes, qui arracha les bois sacrés, et le serpent d\'airain qu\'avait fait Moïse; car, jusqu\'à ces jours-là, les enfants d\'Israël l\'avaient encensé; Ezéchias lui donna le nom de Neesthan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'En Dieu seul il mit son espérance, et après lui il n\'y eut point en Juda de roi qui lui ressemblât, et il n\'y en avait pas eu parmi ceux qui l\'avaient précédé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Il s\'attacha au Seigneur, et il ne cessa pas de le suivre; il observa tous les commandements qu\'il avait donnés à Moïse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Et le Seigneur était avec lui, et il montra de la sagesse en toutes ses entreprises; il se révolta contre le roi des Assyriens, et il ne lui resta pas asservi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Ce fut lui qui frappa les Philistins jusqu\'à Gaza et sa banlieue, depuis les tours des guetteurs jusqu\'aux cités fortifiées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'En la quatrième année du règne d\'Ezéchias (la septième année du règne d\'Osée, en Israël), Salmanasar, roi des Assyriens, ayant marché contre Samarie, l\'assiégea.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Et il la prit au bout de trois ans, en la huitième année du règne d\'Ezéchias (la neuvième du règne d\'Osée, celle où tomba Samarie).');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Puis, le roi des Assyriens transporta ses habitants en Haba et en Habor, sur le fleuve Gozan, et sur les montagnes des Mèdes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Parce que les Samaritains n\'avaient point obéi à la voix du Seigneur, qu\'ils avaient violé son alliance, qu\'ils n\'avaient ni écouté, ni pratiqué ce qu\'il avait prescrit à son serviteur Moïse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'En la quatorzième année du règne d\'Ezéchias, Sennachérib, roi des Assyriens, vint assiéger les villes fortes de Juda, et il les prit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Alors, le roi Ezéchias envoya des messagers au roi des Assyriens à Lachis, disant: J\'ai failli, éloigne-toi de moi; ce dont tu me chargeras, je le porterai. Et le roi des Assyriens chargea Ezéchias d\'une taxe de trois cents talents d\'argent et trois cents talents d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Et le roi de Juda donna tout l\'argent qui se trouva dans le temple et dans les trésors de son palais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'En ce temps-là, Ezéchias ôta l\'or des portes du temple et les lames d\'or dont il avait lui-même revêtu les colonnes, et il les donna au roi des Assyriens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Et le roi des Assyriens envoya de Lachis, au roi Ezéchias, Tharthan, Rhaphis et Rhabsacès, accompagnés d\'une forte armée; ils arrivèrent devant Jérusalem, et s\'arrêtèrent à l\'aqueduc de la piscine supérieure qui est sur le chemin du Champ du Foulon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'De là, ils appelèrent à grands cris Ezéchias; aussitôt Eliacim, fils d\'Helcias, l\'économe; Sobna le scribe, et Joas, fils de Saphat, l\'archiviste, vinrent les trouver.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Et Rhabsacès leur dit: Dites à Ezéchias: Voici ce que dit le grand roi, le roi des Assyriens: Quel est l\'appui en qui tu t\'es confié?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Tu as dit (mais seulement des lèvres): Mon conseil, mon armée, inclinent pour la guerre; maintenant donc, en qui t\'es-tu confié, pour te révolter contre nous?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Voyons, n\'as-tu point foi en ce roseau brisé qu\'on appelle l\'Égypte? Il entrera dans la main de quiconque s\'appuiera sur lui, et il la percera. Voilà comment est le Pharaon d\'Égypte pour tous ceux qui se fient en lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Mais, tu m\'as dit: Nous nous confions en Dieu le Seigneur. Or, ce Dieu n\'est-il pas le même dont Ézéchias a détruit, sur les hauts lieux, les autels, quand il a donné cet ordre à Jérusalem et à Juda: Vous adorerez, devant cet autel seul, dans Jérusalem?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Eh bien! combats aujourd\'hui mon maître le roi des Assyriens, et je te donnerai deux mille chevaux, si tu peux te donner toi-même deux mille cavaliers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Comment donc feras-tu reculer le moindre des chefs qui servent mon maître? Et tu mets ta confiance en l\'Égypte, en ses chars, en ses chevaux!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Est-ce que nous sommes venus détruire cette terre sans le Seigneur? Le Seigneur m\'a dit: Marche sur cette terre, et détruis-la.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Et Eliacim, fils d\'Helcias, Sobna et Joas dirent à Rhabsacès: Parle syrien à tes serviteurs, car nous l\'entendons; ne nous parle pas en langue judaïque. Pourquoi parles-tu pour être ouï du peuple qui est sur les remparts?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Mais Rhabsacès répondit: Est-ce que mon maître m\'a envoyé dire ces paroles à ton maître et à toi? Ne sont-elles pas pour les hommes qui se tiennent sur les remparts, et qui sont réduits comme vous à manger leurs excréments et à boire leur urine?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Et Rbabsacès, se redressant, éleva la voix, et dit en langue judaïque: Écoutez les paroles du grand roi des Assyriens;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Voici ce que dit le roi: Qu\'Ezéchias ne vous excite point par ses discours, car il ne pourra vous arracher de mes mains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Qu\'Ézéchias ne vous fasse point espérer au Seigneur, disant: Le Seigneur nous délivrera; il ne livrera point sa ville au roi des Assyriens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'N\'écoutez point Ezéchias; car voici ce que dit le roi des Assyriens: Cherchez auprès de moi votre bénédiction; venez à moi, et chacun boira le vin de sa vigne, chacun mangera les fruits de son figuier, chacun boira l\'eau de sa citerne,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Jusqu\'à ce que je revienne pour vous transporter en une terre comme la vôtre, en une terre de blé et de vignes, terre de pain et de vin, terre d\'huile et de miel; et vous vivrez et vous ne mourrez point. N\'écoutez point Ezéchias; car il vous trompe, quand il dit: Le Seigneur vous délivrera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Les dieux des nations qui tour à tour sont tombées dans les mains du roi, les ont-ils délivrées?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Où est le dieu d\'Emath et d\'Arphad? Où est le dieu de Sepharvaïm, d\'Ana et d\'Abe? Ont-ils délivré Samarie de mes mains?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Quel est donc celui des dieux, de toutes les nations, qui ait délivré sa terre de mes mains? Le Seigneur délivrera-t-il Jérusalem de mes mains?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Et le peuple resta muet; personne ne répondit à ce discours; car le roi l\'avait ainsi ordonné, disant: Ne lui répondez pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Et l\'économe Eliacim, fils d\'Helcias, le scribe Sobna et l\'archiviste Joas, fils de Saphat, rentrèrent auprès d\'Ezéchias après avoir déchiré leurs vêtements; ils lui rapportèrent les paroles de Rhabsacès.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Lorsque le roi Ezéchias les eut ouïs, il déchira aussi ses vêtements, se couvrit d\'un cilice, et alla au temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Et il envoya Eliacim, et Sobna et Joas, couverts de cilices, auprès du prophète Isaïe, fils d\'Amos.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Et ils lui dirent: Voici ce que dit Ezéchias: Ce jour est un jour d\'affliction, de reproches et de provocation; car les fils prêts à naître sont venus jusqu\'aux douleurs; mais la mère, en mal d\'enfant, n\'a plus de force.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Si, de quelque manière, le Seigneur avait ouï toutes les paroles de Rhabsacès, que le roi des Assyriens, son maître, a envoyé pour outrager le Dieu vivant, pour blasphémer par ces paroles qu\'a sans doute entendues le Seigneur ton Dieu, prie donc pour ceux de nous qui restent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Ainsi, les serviteurs du roi Ezéchias vinrent à Isaïe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Et le prophète leur dit: Dites à votre maître: Voici ce que dit le Seigneur: Ne crains pas les paroles de blasphème que tu as entendues des serviteurs du roi d\'Assyrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Voilà que je mets en lui un esprit; il va apprendre une nouvelle, il va retourner en son royaume, et je le ferai périr, par le glaive, en son royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Pendant ce temps, Rhabsacès, ayant ouï dire que le roi était parti de Lachis, le rejoignit à Lobna, qu\'il assiégeait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Alors, le roi entendit parler de Tharaca, roi d\'Ethiopie; on disait: Voilà qu\'il s\'est mis en campagne pour te combattre. Sennachérib s\'en retourna donc; il envoya des messagers à Ezéchias, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Que ton Dieu, en qui tu as mis ta confiance, ne t\'excite pas, en te disant: Jérusalem ne sera pas livrée aux roi des Assyriens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Tu as ouï tout ce que les rois d\'Assyrie ont fait à toutes les contrées en les vouant à la destruction? Et toi tu leur échapperais!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Est-ce que les dieux des nations que nos pères ont anéanties, les ont préservées? Ont-ils sauvé Gozan, et Haran, et Rhaphis et les fils d\'Edem, qui habitaient Thaesthen?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Où sont les rois d\'Emath et d\'Arphad? Où est le roi des villes de Sepharvaïm, d\'Ana et d\'Aba?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Et Ezéchias prit cette lettre de Sennachérib des mains de ses messagers, et il la lut; puis, il monta au temple du Seigneur; il la déploya devant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Et il dit: Seigneur Dieu d\'Israël, qui êtes assis sur les chérubins, vous êtes le seul Dieu de tous les royaumes de la terre, vous avez créé le ciel et la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Seigneur, inclinez votre oreille, et écoutez; Seigneur, ouvrez les yeux, et voyez; soyez attentif aux paroles que Sennachérib envoie pour outrager le Dieu vivant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Il est vrai, Seigneur, que les rois des Assyriens ont dépeuplé les nations.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Ils ont livré leurs dieux aux flammes; car ce n\'étaient pas des dieux, mais des œuvres des mains des hommes, du bois ou de la pierre; ils les ont détruits.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Maintenant, Seigneur notre Dieu, délivrez-nous des mains de Sennachérib, et tous les royaumes de la terre sauront que vous seul êtes le Seigneur Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Et Isaïe, fils d\'Amos, envoya un messager chez Ezéchias, disant: Voici ce que dit le Seigneur Dieu des armées, Dieu d\'Israël: La prière que tu m\'as faite au sujet de Sennachérib, roi des Assyriens, je l\'ai entendue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Voici les paroles qu\'a dites sur lui le Seigneur: La vierge fille de Sion t\'a méprisé, et elle t\'a raillé; la vierge fille de Jérusalem a secoué sur toi la tête.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Qui donc as-tu outragé? Contre qui donc as-tu blasphémé? Contre qui donc as-tu élevé la voix et lancé tes regards hautains? C\'est contre le Saint d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Tu as outragé le Seigneur par tes messagers, et tu as dit: Avec la multitude de mes chars je suis monté sur la cime des montagnes, sur les pics du Liban; j\'ai abattu ses grands cèdres et ses plus beaux cyprès; je suis venu au cœur de la forêt de chênes du Carmel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Je me suis baigné dans des eaux étrangères, j\'en ai bu; et, sous la plante de mes pieds, j\'ai desséché tous les fleuves, même les plus profonds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Or, c\'est moi le Seigneur qui ai formé ce dessein et qui l\'ai accompli; j\'ai d\'abord excité l\'insolence de bandes étrangères habiles à combattre les villes fortifiées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Et ceux qui les habitaient ont eu les mains énervées; ils ont tremblé, ils ont été couverts de honte. Ils sont devenus comme l\'herbe des champs, comme la plante verte, comme le gazon des terrasses qu\'en marchant on foule aux pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Je connaissais ta demeure, ton départ, ta fureur et ta rage contre moi;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Tes menaces insolentes sont parvenues à mes oreilles; mais je mettrai un harpon dans tes narines et un mors à ta bouche, et je te renverrai par le chemin qu\'en venant tu as pris.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Pour toi, Ezéchias, voici le signe: mange cette année ce qui vient de soi-même; puis, l\'année prochaine, ce qui aura poussé. En la troisième année, il y aura semence et moisson; vous replanterez vos vignes et vous mangerez leurs fruits.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Et Sennachérib partit; il s\'en retourna, et il ne sortit plus de Ninive.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Car il sortira un reste de Jérusalem, un débris sauvé de la montagne de Sion; et cela nous sera accordé par l\'amour du Seigneur des armées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'N\'en est-il pas ainsi? Voici ce que dit le Seigneur, concernant le roi des Assyriens: Il n\'entrera point en cette ville, ses archers n\'y lanceront pas une flèche; il n\'y aura pas de bouclier qui s\'avance contre elle, on n\'élèvera point de retranchements autour de ses remparts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Il s\'en retournera par le chemin qu\'en venant il a pris, et il n\'entrera point en cette ville, dit le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'J\'étendrai mon bouclier sur cette ville, à cause de moi-même, et à cause de David, mon serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Or, la nuit survint, et l\'ange du Seigneur s\'avança, et il extermina, dans le camp des Assyriens, cent quatre-vingt-cinq mille hommes; les survivants se levèrent dès l\'aurore, et ils ne virent que des cadavres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Et Sennachérib partit; il s\'en retourna, et il ne sortit plus de Ninive.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Et, comme il adorait dans le temple son dieu Méserach, ses fils Adramélech et Sarasar le tuèrent à coups d\'épée; puis, ils se sauvèrent en la terre d\'Ararat, et Asordan, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'En ces jours-là, Ezéchias tomba malade d\'une maladie mortelle; le prophète Isaïe, fils d\'Amos, l\'alla trouver, et lui dit: Voici ce que dit le Seigneur: Donne tes ordres à ta maison; tu mourras, tu n\'as plus guère à vivre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Mais Ezéchias se retourna du côté du mur, et il pria le Seigneur, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Seigneur, souvenez-vous que j\'ai marché devant vous dans la vérité et de tout mon cœur, et que j\'ai fait ce que bon vous a semblé. Puis, Ezéchias se prit à pleurer amèrement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Isaïe était alors au milieu du parvis, et la parole du Seigneur vint à lui, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Rentre, et dis à Ezéchias, chef de mon peuple: Voici ce que dit le Seigneur Dieu de David, ton aïeul: J\'ai entendu ta prière, j\'ai vu tes larmes, je te guérirai; dans trois jours tu monteras au temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Et j\'ajouterai quinze ans à ta vie; je sauverai toi et cette ville du roi des Assyriens; j\'étendrai mon bouclier sur cette ville, à cause de moi-même et à cause de David, mon serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Et le prophète dit: Que l\'on prenne un cabas de figues, qu\'on les applique sur l\'ulcère, et il sera guéri.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Et Ezéchias dit au prophète: A quel signe reconnaîtrai-je que le Seigneur me guérira, et que dans trois jours je monterai au temple?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Isaïe répondit: Voici le signe\' du Seigneur, qui te montrera que sa parole doit s\'accomplir: L\'ombre s\'avancera-t-elle où reculera-t-elle de dix degrés?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Le roi reprit: L\'ombre avancera facilement de dix degrés. Ce n\'est point cela que je demande, mais que sur les marches elle recule de dix degrés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Et le prophète cria au Seigneur; et l\'ombre, sur les marches, recula de dix degrés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'En ce temps-là, Marodach, fils de Baladan, roi de Babylone, envoya à Ezéchias une lettre et des présents, parce qu\'il avait appris qu\'Ezéchias était malade.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Ezéchias en fut réjoui, et il montra aux messagers d\'abord toute la maison des épices, l\'argent et l\'or, les aromates et la bonne huile; ensuite, l\'arsenal; puis, tout ce qui se trouvait en ses trésors. Il n\'y eut rien qu\'Ezéchias ne fit voir dans son palais et dans ses domaines.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Mais le prophète Isaïe alla trouver le roi Ezéchias, et il lui dit: Que t\'ont dit ces hommes, et d\'où sont-ils venus? Le roi répondit: Ils sont venus vers moi d\'une contrée lointaine, de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Le prophète reprit: Qu\'ont-ils vu dans ton palais? Le roi dit: Ils ont vu ce que mon palais renferme; il n\'y a rien que je ne leur aie montré, soit dans mon palais, soit dans mes trésors.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Et le prophète Isaïe dit à Ezéchias: Écoute la parole du Seigneur:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Les jours approchent où tout ce que renferme ton palais sera pris, où tous les trésors que tes pères ont amassés jusqu\'à ce moment, iront à Babylone. Et la parole du Seigneur ne sera pas en défaut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Quant à tes fils, qui sortiront de toi, que tu auras engendrés, l\'ennemi les prendra, et ils seront eunuques dans le palais du roi de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Et Ezéchias dit à Isaïe: La parole que le Seigneur a dite est bonne; mais que la paix se maintienne tout le temps de ma vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Quant au reste de l\'histoire d\'Ezéchias, à ses guerres, à toutes ses actions, à la fontaine, l\'aqueduc et l\'eau qu\'il a amenée dans la ville, ne sont-ils pas écrits au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Et Ezéchias s\'endormit avec ses pères, et Manassé, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manassé avait douze ans quand il monta sur le trône, et il régna cinquante-cinq ans à Jérusalem; sa mère se nommait Apsiba.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Et il fit le mal aux yeux du Seigneur: les abominations des peuples que le Seigneur avait détruits devant les fils d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Il se pervertit, et il rebâtit les hauts lieux qu\'avait abattus Ezéchias, son père; il releva l\'autel de Baal; il planta des bois sacrés, comme Achab, roi d\'Israël; il adora toute l\'armée du ciel, et il la servit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Il bâtit un autel dans le temple du Seigneur, qui avait dit: En Jérusalem je placerai mon nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Et il bâtit un autel à toute l\'armée du ciel, dans chacun des deux parvis du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Et il fit passer de ses fils dans la flamme; il usa de la divination et des augures, il consacra des enclos; il multiplia les devins, faisant le mal aux yeux du Seigneur pour l\'irriter.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'L\'idole du bois sacré, il la mit dans le temple, dont le Seigneur avait dit à David et à Salomon, son fils: En ce temple et en cette ville de Jérusalem, que j\'ai choisie parmi toutes les tribus, je placerai mon nom pour toujours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Car je ne veux plus éloigner de la terre que j\'ai donnée à leurs pères le pied des fils d\'Israël, du moins de ceux qui garderont tout ce que j\'ai prescrit, tous les commandements que leur a fait connaître Moïse, mon serviteur;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Mais ils n\'écoutèrent pas le Seigneur; Manassé les égara, pour qu\'ils fissent le mal aux yeux du Seigneur, plus encore que les nations que le Seigneur avait détruites devant Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Et le Seigneur parla par la voix de ses serviteurs les prophètes, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'En punition de ce qu\'a fait Manassé, de ses abominations, de ses crimes, qui surpassent ceux de l\'Amorrhéen d\'autrefois, de ce qu\'il a fait tomber Israël dans le péché, par ses idoles,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Il n\'en sera pas ainsi. Voici ce que dit le Seigneur Dieu d\'Israël: Voilà que j\'apporte à Jérusalem et à Juda des maux tels, que les oreilles de quiconque les ouïra en tinteront.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Et j\'étendrai sur Jérusalem la mesure de Samarie et le niveau de la maison d\'Achab; je récurerai Jérusalem comme on récure un vase que l\'on retourne sens dessus dessous en l\'essuyant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Je répudierai les restes de mon héritage; je les livrerai aux mains de leurs ennemis; ils seront pour tous leurs ennemis une proie et un butin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'En punition de ce qu\'ils ont fait le mal à mes yeux, et de ce qu\'ils n\'ont jamais cessé de m\'irriter, depuis que j\'ai tiré leurs pères de l\'Égypte jusqu\'à ce jour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Or, Manassé répandit à grands flots le sang innocent, jusqu\'à ce que, d\'une extrémité à l\'autre, il en eût rempli Jérusalem, outre les péchés où il fit tomber Juda en faisant le mal aux yeux du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Quant au reste de l\'histoire de Manassé, et aux péchés où il tomba, ne sont-ils pas écrits au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Et Manassé s\'endormit avec ses pères; il fut enseveli dans le jardin de son palais, dans le jardin d\'Oza, et son fils Amos régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amos avait vingt-deux ans quand il monta sur le trône, et il régna deux ans à Jérusalem; sa mère se nommait Mésollam, fille d\'Arus de Jétéba.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Et il fit le mal aux yeux du Seigneur, comme l\'avait fait Manassé, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Il marcha dans toutes les voies où son père avait marché, et il servit les idoles que son père avait servies, et il les adora.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Il abandonna le Seigneur Dieu de ses pères; il ne marcha pas dans la voie du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Et les serviteurs d\'Amos conspirèrent contre lui, et ils le tuèrent dans son palais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Alors, le peuple de la terre mit à mort ceux qui avaient conspiré contre le roi Amos, et il proclama roi Josias, son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Quant au reste de l\'histoire d\'Amos, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Et on l\'ensevelit en son sépulcre dans le jardin d\'Oza, et Josias, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josias avait huit ans quand il monta sur le trône, et il régna trente et un ans à Jérusalem; sa mère se nommait Jedia, fille d\'Edia de Basuroth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Et il fit ce qui est droit aux yeux du Seigneur; il marcha dans toutes les voies de David, son aïeul; il n\'en dévia ni à droite ni à gauche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'En la troisième année du règne de Josias, le huitième mois, le roi envoya Saphan, fils d\'Ezélie, fils de Mésollam, scribe du temple du Seigneur, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Monte auprès d\'Helcias le grand prêtre; compte l\'argent offert par le peuple dans le temple, et recueilli par les gardiens de la porte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Qu\'ils remettent cet argent aux ouvriers employés dans le temple. Et l\'on donna cet argent aux ouvriers du temple, pour qu\'ils y fissent des réparations.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'On le donna aux charpentiers, aux constructeurs, aux maçons, pour acheter du bois et des pierres de taille, et consolider le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Mais on ne leur demanda pas compte de l\'argent qui leur fut confié, parce que les travaux furent exécutés de bonne foi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Or, le grand prêtre Helcias dit à Saphan le scribe: J\'ai trouvé dans le temple le livre de la loi. Et il lui donna le livre; puis, Saphan le lut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Ensuite, il entra auprès du roi dans le temple; il lui rapporta ce qui avait été fait, et il dit: Tes serviteurs ont fondu l\'argent trouvé dans le temple du Seigneur, et ils l\'ont remis aux ouvriers du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Et Saphan le scribe ajouta: Le prêtre Helcias m\'a donné un livre. Et Saphan le lut devant le roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Quand Josias ouït les paroles du livre de la loi, il déchira ses vêtements,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Et il donna ses ordres à Helcias le prêtre, à Achicam, fils de Saphan, à Achobor, fils de Michée, à Saphan le scribe, à Amie, serviteur du roi, et il leur dit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Allez au Seigneur vous enquérir de moi, de tout le peuple, de tout Juda, concernant les paroles de ce livre qu\'on a trouvé; car la colère dont le Seigneur s\'est enflammé contre nous est grande, parce que nos pères n\'ont point écouté les paroles de ce livre pour faire selon ce qui est écrit à notre sujet.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Et le prêtre Helcias, Achicam, Achobor, Saphan et Asaïe, allèrent chez la prophétesse Olda, mère de Sellem, fils de Thécuan, fils d\'Aras, gardien des vêtements. Elle demeurait à Jérusalem dans le quartier de Masena, et ils lui parlèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Et elle leur répondit: Voici ce que dit le Seigneur Dieu d\'Israël: Dites à l\'homme qui vous a envoyés près de moi:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Voici ce que dit le Seigneur: Voilà que j\'apporte des maux à ce lieu et à ceux qui l\'habitent, selon les paroles du livre qu\'a lu le roi de Juda;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'En punition de ce qu\'ils m\'ont abandonné, et de ce qu\'ils ont encensé d\'autres dieux, de sorte qu\'ils m\'ont irrité par toutes les œuvres de leurs mains; car ma colère est enflammée contre ce lieu, et elle ne s\'éteindra pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Quant au roi de Juda, qui vous a envoyés vous enquérir au Seigneur, dites-lui: Voici ce que dit le Seigneur Dieu d\'Israël au sujet des paroles que tu as entendues:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'En récompense de ce que ton cœur ne s\'est point endurci, de ce que devant moi tu es rentré en toi-même quand tu as ouï ce que j\'ai dit contre ce lieu et contre ceux qui l\'habitent, pour qu\'ils soient effacés et maudits; de ce que tu as déchiré tes vêtements et pleuré en ma présence: eh bien! moi aussi j\'ai entendu, dit le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Il n\'en sera pas ainsi: voilà que je te réunis à tes pères; tu descendras en paix dans ton sépulcre, et tes yeux ne verront aucun des maux que j\'apporte en ce lieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Et ils rapportèrent au roi ces paroles; et il envoya des messagers, et il assembla autour de lui tous les anciens de Juda et de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Et le roi monta au temple du Seigneur avec tout Juda, tous les habitants de Jérusalem, les prêtres, les prophètes, tout le peuple, depuis le petit jusqu\'au grand, et il lut à leurs oreilles toutes les paroles du livre de l\'alliance trouvé dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Ensuite, le roi, debout sur le piédestal, renouvela l\'alliance devant le Seigneur, afin de suivre le Seigneur, de garder ses commandements, ses témoignages et ses justices, de tout son cœur, dans la plénitude de son âme; et enfin, de faire revivre toutes les paroles de l\'alliance écrite dans le livre; or, tout le peuple acquiesça à l\'alliance.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Et le roi prescrivit à Helcias le grand prêtre, aux prêtres du second rang et aux gardiens de la porte, d\'enlever du temple du Seigneur tous les vases faits pour Baal, pour le bois sacré et pour l\'armée du ciel; il les brûla hors de Jérusalem dans la vallée de Cédron, et il en fit porter les cendres à Béthel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Puis, il brûla vifs les prêtres idolâtres qu\'avaient institués les rois de Juda et qui encensaient sur les hauts lieux, soit dans les villes de Juda, soit autour de Jérusalem, et aussi ceux qui encensaient Baal, le soleil, la lune, les douze signes et toute l\'armée du ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Et il emporta l\'idole des bois sacrés hors du temple, hors de Jérusalem dans le torrent de Cédron; il la réduisit en cendres qu\'il dispersa sur la sépulture des fils du peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Il démolit la demeure des initiés qu\'on avait construite dans le temple, et où les femmes tissaient des tentes pour le bois sacré.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Il assembla ensuite tous les prêtres des villes de Juda; et il souilla les hauts lieux, où les prêtres avaient brûlé de l\'encens, depuis Gebal jusqu\'à Bersabée; puis, il abattit la maison des portes, à côté de la demeure de de Josué, prince de Jérusalem, à gauche, en sortant de la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Cependant, les prêtres des hauts lieux ne montèrent plus à l\'autel du Seigneur à Jérusalem, à moins qu\'ils n\'eussent mangé des azymes au milieu de leurs frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Josias souilla encore Tapheth dans le val des fils d\'Ennom, où ils faisaient passer dans la flamme de Moloch, les uns leurs fils, les autres leurs filles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Il brûla les chevaux que les rois de Juda avaient consacrés au soleil, à l\'entrée du temple, dans le trésor de Nathan, eunuque du roi, à Pharurim; il brûla en outre le char du soleil,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Et les autels que les rois de Juda avaient élevés sur la terrasse au- dessus de la chambre d\'Achaz, et ceux que Manassé avait construits dans les deux parvis du temple; il en fit jeter les cendres dans le torrent de Cédron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Le roi souilla aussi le temple que Salomon, roi d\'Israël, avait érigé en face de Jérusalem, à droite du chemin de la montagne de Mosthath, en l\'honneur d\'Astarté, abomination des Sidoniens et de Chamos, abomination de Moab et de Moloch, abomination des Ammonites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Il mit en pièces leurs colonnes, détruisit leurs bois sacrés, et remplit d\'ossements humains le lieu où on les adorait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Puis, il abattit l\'autel qu\'en Béthel, sur le haut lieu, Jéroboam, fils de Nabat, avait élevé et où il avait fait tomber tout le peuple dans le péché; il le démolit. Il en broya les pierres, il les réduisit en poudre, et il brûla le bois sacré.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Et Josias, se détournant, vit les sépulcres de cette ville; aussitôt, il donna ses ordres: il en fit extraire les ossements, et il les brûla sur l\'autel pour le souiller, selon la parole du Seigneur qu\'avait dite l\'homme de Dieu quand Jéroboam avait célébré la fête de l\'autel; puis, se retournant encore, il leva les yeux et il vit la sépulture de cet homme de Dieu qui avait dit ces paroles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Et il dit: Quel est ce tombeau que j\'aperçois? Et les hommes de la ville lui répondirent: Celui de l\'homme de Dieu qui est venu de Juda, et qui a fait les imprécations contre l\'autel de Béthel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Et le roi dit: Respectez-le; que nul n\'enlève ses ossements. Et ses os furent sauvés avec ceux du prophète qui était venu de Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Josias détruisit donc tous les temples des hauts lieux que les rois d\'Israël avaient élevés dans les villes de Samarie, pour y irriter le Seigneur, et il y fit la même chose qu\'à Béthel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Et il sacrifia sur leurs autels tous les prêtres des hauts lieux qui étaient là, il y brûla les os des hommes, et il retourna à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Et le roi donna ses ordres à tout le peuple, disant: Immolez la pâque au Seigneur notre Dieu, comme il est écrit au livre de cette alliance.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Car, on n\'avait point ainsi célébré cette fête depuis le temps des Juges qui jugeaient Israël; ni sous les rois d\'Israël, ni sous les rois de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Ce ne fut qu\'en la dix-huitième année du règne de Josias, que l\'on immola la pâque au Seigneur à Jérusalem');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'En outre, Josias extermina les initiés et les devins; Il détruisit les idoles, les images et toutes les abominations qui existaient tant à Jérusalem qu\'en Juda, {afin de respecter les paroles de la Loi écrite dans le livre, que le prêtre Chelsias avait trouvé dans la maison du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Il n\'y avait point eu auparavant de roi qui, comme lui, se convertît à Dieu de tout son cœur, de toute son âme et de toutes ses forces, conformément à la loi de Moïse; et il n\'y en eut point après lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Mais le Seigneur ne détourna point la colère dont il était enflammé contre Juda, à cause des offenses qu\'il avait reçues de Manassé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Et le Seigneur dit: J\'expulserai aussi Juda de devant ma face comme j\'ai expulsé Israël; je répudierai cette ville que j\'avais choisie, cette Jérusalem, et le temple dont j\'avais dit: C\'est là que sera mon nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Quant au reste de l\'histoire de Josias, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Sous son règne, le Pharaon d\'Égypte Néchao marcha sur le fleuve Euphrate contre le roi des Assyriens; Josias se porta à sa rencontre, et Néchao le tua à Mageddo, au premier choc.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Les serviteurs placèrent son corps sur un char, et le ramenèrent de Mageddo à Jérusalem, et ils l\'ensevelirent dans son sépulcre; alors, le peuple de la terre prit Joachaz, fils de Josias; il le sacra, et il le proclama roi la place de son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Joachaz avait vingt-trois ans quand il monta sur le trône, et il régna trois mois à Jérusalem; le nom de sa mère était Amital, fille de Jérémie de Lebna.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Et il fit le mal aux yeux du Seigneur, comme l\'avaient fait ses pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Et le Pharaon Néchao le transporta en Rablaam dans la terre d\'Emath, pour qu\'il ne régnât point à Jérusalem; puis, il imposa à la terre un tribut de cent talents d\'argent et de cent talents d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'A sa place, le Pharaon Néchao leur donna pour roi Eliacim, fils de Josias, et il changea son nom, et il l\'appela Joacin. Et il emmena Joachaz en Égypte, où il mourut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Joacin donna au Pharaon de l\'argent et de l\'or, mais il taxa la terre pour payer le tribut au Pharaon; chacun donna de l\'argent et de l\'or selon sa taxe; tout le peuple donna donc le tribut au Pharaon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Joacin avait vingt-cinq ans lorsqu\'il monta sur le trône, et il régna onze ans à Jérusalem; sa mère se nommait Jeldaph, fille de Phadaël, de Rhuma.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Et il fit le mal aux yeux du Seigneur comme avaient fait tous ses aïeux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'En ce temps-là, Nabuchodonosor, roi de Babylone, vint, et Joacin lui fut asservi trois ans; ensuite il changea de pensée, et il refusa de lui obéir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Alors, le Seigneur envoya contre lui des bandes de la Chaldée, de la Syrie, de Moab et des fils d\'Ammon; il les envoya en la terre de Juda pour prévaloir sur elle, selon la parole que le Seigneur avait dite par la voix de ses serviteurs les prophètes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'De plus, la colère du Seigneur contre Juda voulait l\'expulser de devant sa face à cause des péchés de Manassé, et de tout ce qu\'avait fait ce roi;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'Car il avait versé le sang innocent, il en avait rempli Jérusalem; et le Seigneur ne voulait point s\'apaiser.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Quant au reste de l\'histoire de Joacin, n\'est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Et Joacin s\'endormit avec ses pères, et son fils Joachim, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Et le roi d\'Égypte ne sortit plus de sa contrée, parce que, depuis le torrent d\'Égypte jusqu\'à l\'Euphrate, le roi de Babylone avait pris tout ce qui appartenait à l\'Égyptien.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Joachim avait dix-huit ans quand il monta sur le trône, et il régna trois mois à Jérusalem; sa mère se nommait Nestha, fille d\'Ellanastham, de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Et il fit le mal devant le Seigneur, comme avait fait son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'En ce temps-là, Nabuchodonosor, roi de Babylone, marcha sur Jérusalem, et la ville fut investie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Et Nabuchodonosor mit le siège devant la ville, et ses serviteurs la tinrent assiégée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Or, Joachim, roi de Juda, se rendit au roi de Babylone, lui, ses serviteurs, sa mère, ses chefs et ses eunuques; le roi de Babylone le fit captif en la huitième année de son règne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Et il enleva de Jérusalem tous les trésors du temple du Seigneur et tous les trésors du palais du roi; il brisa tous les vaisseaux d\'or qu\'avait faits, dans le temple, le roi Salomon, selon la parole du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Et il emmena en captivité, au nombre de dix mille, tous les chefs, tous les hommes vaillants, et en outre tous les charpentiers et tous les maçons; il ne resta dans la terre que les indigents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Il transporta aussi à Babylone, Joachim, la mère du roi, les femmes du roi et ses eunuques; il conduisit tous les riches de la terre de Jérusalem à Babylone,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Et tous les hommes dans la force de l\'âge au nombre de soixante-dix mille, et mille charpentiers ou maçons, tous faisant la guerre. Le roi Nabuchodonosor les emmena captifs à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Et il remplaça Joachim par Batthanias, fils de Josias, et il donna à ce roi le nom de Sédécias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sédécias avait vingt-neuf ans quand il monta sur le trône, et il régna onze ans à Jérusalem; le nom de sa mère était Amital, fille de Jérémie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Et il fit le mal devant le Seigneur, comme avait fait Joacin;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Car, telle était la pensée du Seigneur contre Jérusalem et contre Juda, jusqu\'à ce qu\'il les eut expulsés de devant sa face. Or, Sédécias se révolta contre le roi de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Dans la neuvième année de son règne, le dixième mois, le roi Nabuchodonosor arriva de Babylone avec toute son armée contre Jérusalem; il campa autour de ses remparts, et il les enveloppa d\'une muraille qu\'il bâtit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Et la ville fut investie jusqu\'au neuvième mois de la onzième année du règne de Sédécias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'La famine prévalait dans la cité, et il n\'y avait pas de pains pour le peuple de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Une brèche fut faite aux murailles, et à la nuit les hommes de guerre sortirent par le chemin de la porte qui est entre les remparts, la porte même du jardin du roi; cependant, les Chaldéens entouraient le reste de la ville. Alors, le roi prit la route de la plaine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Et l\'armée des Chaldéens les poursuivit; Sédécias fut pris en Araboth-Jéricho, et toute sa troupe se dispersa tout alentour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Les Chaldéens firent donc le roi captif; ils le menèrent au roi de Babylone à Reblatha, et Nabuchodonosor prononça contre lui son arrêt.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Il égorgea tous ses fils sous ses yeux, qu\'ensuite il arracha; puis, après l\'avoir chargé de chaînes et d\'entraves, il l\'emmena à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Le septième jour du cinquième mois de la dix-neuvième année du règne de Nabuchodonosor, Nabuzardan son général en chef, celui qui se tenait devant lui, marcha sur Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Et il livra aux flammes le temple du Seigneur, le palais du roi et toutes les maisons de Jérusalem;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Le général en chef [brûla tout].');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Et Nabuzardan enleva tout ce qui survivait du peuple demeuré dans la ville, et ceux qui étaient tombés dans les mains du roi de Babylone, et tout le reste de la multitude.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Il ne laissa pour être vignerons et laboureurs que la plus infinie populace.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Et les Chaldéens brisèrent les colonnes d\'airain, les bassins et la mer d\'airain du temple; et ils emportèrent le métal à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Ils prirent aussi les chaudières, les fourchettes, les coupes, les encensoirs et les vases d\'airain employés dans le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Le général en chef prit les portes, les coupes d\'or et d\'argent,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Les deux colonnes, la mer et les bassins que Salomon avait placés dans le temple; on ne sut pas le poids de tous les ornements d\'airain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Chaque colonne avait dix-huit coudées de haut; elle était surmontée d\'un chapiteau d\'airain, haut de trois coudées, avec un filet entouré de grenades; elles étaient toutes les deux pareilles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Le général en chef fit aussi captifs Saraïas le grand prêtre, Sophonie prêtre du second rang, et les trois gardiens des portes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'On prit en outre: hors de la ville, un eunuque commandant les hommes de guerre; dans la ville, cinq de ceux qui voyaient la face du roi, et le scribe du chef de l\'armée qui rangeait les troupes en bataille, et soixante hommes de la campagne alors à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Nabuzardan conduisit les captifs au roi de Babylone, à Reblatha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Et Nabuchodonosor les frappa, et les fit mettre à mort à Reblatha dans la terre d\'Emath; puis, il emmena Juda loin de sa terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Et à la tête du peuple qui resta sur le territoire de Juda, le roi mit Godolias, fils d\'Achiman, fils de Saphan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Et tous les chefs de l\'armée, eux et leurs hommes, apprirent que le roi avait choisi Godolias; alors, Ismaël, fils de Nathanie; Jonas, fils de Careth; Saraïas, fils de Thanamath le Nephthalite, et Jézonias, fils de Machathi, l\'allèrent trouver avec leurs hommes à Maspha,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Et Godolias prêta serment à eux et à leurs hommes, disant: Ne craignez plus d\'invasion des Chaldéens, demeurez en votre terre, servez le roi de Babylone, et tout ira bien pour vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Et le septième mois, Ismaël, fils de Nathanie, de la race royale, et dix de ses hommes allèrent à Maspha; là, ils attaquèrent Godolias, et ils le tuèrent ainsi que les Chaldéens qui s\'y trouvaient avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Et tout le peuple, du petit au grand, et les chefs de l\'armée se levèrent, et ils s\'en allèrent en Égypte, car ils craignaient les Chaldéens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'En la trente-septième année de la captivité de Joachim, roi de Juda, le vingt-septième jour du douzième mois, Evilmerodach, roi de Babylone, dès la première année de son règne, releva la tête de Joachim, roi de Juda, et le fit sortir de prison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Et il lui parla avec douceur, et il lui donna un trône plus élevé que les trônes des autres rois qui l\'entouraient à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Il lui ôta ses vêtements de prisonnier, et il le fit manger, en sa présence, tous les jours de sa vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Et sa portion, portion perpétuelle, lui fut donnée de la maison du roi; il en fut ainsi tous les jours de sa vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Caïnan, Malalehel, Jared,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Enoch, Mathusalem, Larnech, Noé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Fils de Noé: Sem, Cham, Japheth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Fils de Japheth: Corner, Magog, Madaï, Javan, Elisa, Thobel, Mosoch et Thiras.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Fils de Gomer: Ascenez, Rhiphath et Thorgama.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Fils de Javan: Elisa, Tharsis, les Citians et les Rhodiens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Fils de Cham: Chus, Mesraïm, Phuth et Chanaan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Fils de Chus: Saba, Evila, Sabatha, Regma et Sabalhaca. Fils de Regma: Saba et Dadan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Et Chus engendra Nemrod; celui-ci commença à être puissant et chasseur sur la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Fils de Sem: Elam, Assur, Arphaxad,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Fils de Sem: Elam, Assur, Arphaxad,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Fils de Sem: Elam, Assur, Arphaxad,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Fils de Sem: Elam, Assur, Arphaxad,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Fils de Sem: Elam, Assur, Arphaxad,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Fils de Sem: Elam, Assur, Arphaxad,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Fils de Sem: Elam, Assur, Arphaxad,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Salé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Salé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Salé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Salé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Salé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Salé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Salé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Héber, Phaleg, Réhu,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Sarug, Nachor, Tharé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abraham.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Fils d\'Abraham: Isaac et Ismaël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Voici leurs familles: premier-né d\'Ismaël: Nabaïoth, Cédar, Abdéel, Massan,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Masma, Duala, Massi, Choddan, Thèman,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jethur, Naphis, Cedma; voilà les fils d\'Ismaël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Fils de Cettura, concubine d\'Abraham: elle lui enfanta: Zameran, Jezan, Madian, Madal, Jesboc et Sué. Fils de Jezan: Dedan et Saba.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Fils de Madian: Gephar, Aphir, Enoch, Abida et Elduga; voilà tous les fils de Cettura.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abraham engendra Isaac. Fils d\'Isaac: Jacob et Esaü.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Fils d\'Esaü: Eliphaz, Raguel, Jehul, Jeglon et Coré.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Fils d\'Eliphaz: Thêman, Omar, Sophar, Gatham, Canez, Thamna et Amalec.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Fils de Raguel: Nachoth, Zaré, Somé et Mozé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Fils de Seïr: Lotan, Sobal, Sébégon, Ana, Dison, Asar et Rison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Fils de Lotan: Horri et Héman; sœur de Lotan, Thamna.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Fils de Sobal: Alon, Machanath, Tébel, Sophi et Onan. Fils de Sébégon: Eth et Sonan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Fils de Sonan: Dison. Fils de Dison: Emeron, Asebon, Jethram et Harran.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Fils d\'Asar: Balaam, Zucam, Acan. Fils de Bison, Os et Aran.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Et voici leurs rois: Balac, fils de Béor; le nom de sa ville est Dennaba.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Balac mourut, et Jobab, fils de Zara de Bosora, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Jobab mourut, et Asom, de la terre des Thêmanites, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Asom mourut, et Adad, fils de Barad, régna à sa place; ce fut lui qui vainquit Madian dans le champ de Moab; le nom de sa ville est Gethaim.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Adad mourut, et Sebla (Samada) de Maseca régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Sebla mourut, et Saul de Rooboth, sur l\'Euphrate, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Saul mourut, et Balaennor (Ballanan), fils d\'Achobor, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Balaennor mourut, et Arad, fils de Barad, régna à sa place; le nom de sa ville est Phogor.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Chefs d\'Edom: le chef Thaman (Thamna), le chef Golada (Gola), le chef Jéther,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Le chef Elibamas (Olibema), le chef Ela, le chef Phinon,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Le chef Cenez, le chef Théman, le chef Bassor (Mazar),');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Le chef Magediel, le chef Zaphoin: voilà les chefs d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Voici les noms des fils d\'Israël: Ruben, Siméon, Lévi, Juda, Issachar, Zabulon,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph, Benjamin, Nephthali, Gad, Aser.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Fils de Juda: Her, Onan, Sela; tous trois naquirent de la fille de Savas (Sué), la Chananéenne; et Her, le premier-né de Juda, fit le mal devant le Seigneur, qui le tua.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Et Thamar, bru de Juda, enfanta Pharès et Zara; en tout: cinq fils de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Fils de Pharès: Esron et Jemuhel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Fils de Zara: Zambri, Etham, Aimuan, Calchal et Darad; en tout: cinq.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Fils de Charmi: Achar, le perturbateur d\'Israël, qui désobéit au sujet de l\'anathème.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Fils d\'Etham: Azarias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Fils d\'Esron, qui lui furent enfantés: Jeraméel, Aram et Caleb.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Aram engendra Aminadab; Aminadab engendra Nahasson, chef de la maison de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahasson engendra Salmon; Salmon engendra Booz;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Booz engendra Obed; Obed engendra Jessé;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Jessé engendra son premier-né Eliab, le second Aminadab, le troisième Samaa,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Nathanael le quatrième, Zabdé le cinquième,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Azam le sixième, et David le septième.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Et leurs sœurs furent: Sarvia et Abigaïl. Les fils de Sarvia furent: Abessa, Joab et Asaël; trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abagaïl enfanta Amessab, et le père d\'Amessab fut Jolhor l\'Ismaélite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Caleb, fils d\'Esron, prit pour femmes Gazuba et Jerioth; voici ses fils: Jasar, Subab et Ardon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Et Gazuba mourut, et Caleb prit pour femme Ephratha, et elle lui enfanta Hur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur engendra Urias; Urias engendra Beseléel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Après cela, Esron eut commerce avec la fille de Machir, père de Galaad, et il la prit pour femme; il avait alors soixante-cinq ans, et elle lui enfanta Seruch.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Seruch engendra Jaïr; il possédait vingt-trois villes en Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Il prit de plus Gessur et Aram, villes de Jaïr, parmi les siennes, et la terre de Canath avec ses villes: soixante villes; toutes appartenaient aux fils de Machir, père de Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Après la mort d\'Esron, Caleb épousa Ephratha; or, Abia, femme d\'Esron, lui avait enfanté Ascho, père de Thécoé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Les fils de Jeraméel, premier-né d\'Esron, furent: Ram, premier-né; puis, Banaa, Aram et Asan, son frère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Et Jeraméel avait une autre femme qui se nommait Atara; celle-ci fut la mère d\'Ozom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Les fils de Ram, premier-né de Jeraméel, furent: Mass, Jamin et Acor.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Les fils d\'Ozom furent: Samaï et Jadaé, et les fils de Samaï: Nadab et Abisur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'La femme d\'Abisur se nommait Abihaïl, et elle lui enfanta Achobor et Moêl.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Fils de Nadab: Salad et Aphaïn; Salad mourut sans enfants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Fils d\'Aphaïn: Iséuniel; fils d\'Isémiel: Sosan; fils de Sosan: Dadaï.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Fils de Dadaï: Achisamas, Jéther, Jonatham; Jéther mourut sans enfants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Fils de Jonathan: Phaleth et Ozam; voilà les fils de Jonathan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sosan n\'eut pas de fils, mais des filles; or, il avait un serviteur égyptien qui se nommait Johel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Et Sosan donna sa fille, pour femme, à son serviteur Johel; elle lui enfanta Ethi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Et Ethi engendra Nathan, et Nathan engendra Zabed.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zabed engendra Aphamel, et Aphamel engendra Obed.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed engendra Jéhu, et Jéhu engendra Azarias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azarias engendra Hellès, et Hellès engendra Eléaza.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eléaza engendra Sosomaï, et Sosomaï engendra Salum.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Salum engendra Jéhémie; Jéhémie engendra Elisama, et Elisama engendra Ismaël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Fils de Caleb, frère de Jeraméel Marisa, premier-né; c\'est le père de Siph; Marisa eut encore des fils, il fut le père d\'Hébron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Fils d\'Hébron: Coré, Thaphus, Rhicom et Samaa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Samaa engendra Rahem, père de Jéclan, et Jéclan engendra Samaï.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Mahon fut son fils, et Mahon fut le père de Bethsur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Gaïpha, concubine de Caleb, enfanta Aram, et Mosa et Gézué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Fils d\'Adaï: Rahem, Joatham, Sagar, Phalec, Gaïpha et Sagaé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Mocha, concubine de Caleb, enfanta Saber et Tharam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Sagaé engendra le père de Madmena, et Sahu, père de Mahabena, et le père de Gébal; la fille de Caleb s\'appelait Ascha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Voilà les fils de Caleb. Voici les fils d\'Hur, premier-né d\'Ephratha: Sobal, père de Cariathiarim,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salomon, père de Bétha, Lammon, père de Béthalaem, et Arim, père de Bethgedor.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Fils de Sobal, père de Cariathiarim: Araa, Aïsi, Ammanith');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Et Umasphaé; villes de Jdir: Ethalim, Miphitim, Hésamathim et Hémasaraïm, d\'où sont sortis les Sarathéens et les fils d\'Esthaam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Fils de Salomon: Béthalaem le Netophatite, Ataroth de la maison de Joab, la moitié de Manathi, et Esari.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Familles de lettrés, demeurant en Jabis: Thargathiim, et Samathiim et Sohathim. Ce sont les Cinéens, issus d\'Emath, père de la maison de Rhéchab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Voici les fils de David qui lui naquirent à Hébron; le premier-né fut: Amnon, fils de la Jezraélite Achinaam; le second, Damniel (Daluia), fils d\'Abigaïl du Carmel;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Le troisième, Absalon, fils de Moha (Maacha), fille de Tholmé, roi de Gedsur; le quatrième, Adonias (Ornia), fils d\'Aggith;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Le cinquième, Saphatia, fils d\'Abital; le sixième, Jethram, fils de sa femme Agla.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Il en eut six à Hébron, et il y régna sept ans et demi; après quoi, il régna trente-trois ans à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Voici ceux qui lui naquirent en Jérusalem: Samaa, Sobab, Nathan et Salomon. Quatre fils de Bethsabée, fille d\'Amiel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Puis, Ebaar, Elisa, Eliphaleth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nagé, Naphec, Japhie,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eliada et Eliphala; en tout: neuf.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Tous fils de David, outre les fils de ses concubines, et Thamar, leur sœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Fils de Salomon: Roboam, Abias son fils, Asa son fils, Josaphat son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Joram son fils, Ochozias son fils, Joas son. fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Amasias son fils, Azarias son fils, Joathan son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Achaz son fils, Ezéchias son fils, Manassé son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Amon son fils, Josias son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Fils de Josias: Joanan le premier-né, Joacin le second, Sédécias le troisième, et Salum le quatrième.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Fils de Joacin: Jéchonias son fils, Sédécias son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Fils de Jéchonias: Asir, Salathiel son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Melchiram, Phadaïas, Fanesar, Jécimie, Hosamath et Nabadias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Fils de Phadaïas: Zorobabel et Sémeï. Fils de Zorobabel: Mosollam et Ananias; Salometh fut leur sœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Il eut encore: Asubé, Ool, Barachie, Asadie et Asobed; cinq fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Fils d\'Ananias: Phalettie, Jésias son fils, Raphal son fils, Orna son fils, Abdias son fils, et Séchénias son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Fils de Sechénias: Samaïe. Fils de Samaie: Battus, Johel, Berri, Noadie et Saphat; six issus de Sechénias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Fils de Noadie: Elithenan, Ezécie, Ezricam; trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Fils d\'Elithenan: Odolie, Eliasebon, Phadaïe, Acub, Joanan, Dalaaïe et Anan; sept.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'De Juda sont issus: Pharès, Esron, Charmi, Hur, Sobal,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Et Rhada son fils. Et Sobal engendra Jeth, et Jeth engendra Achimaï et Laad; les Arathites (Sarathéens) sont issus d\'eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Voici les fils d\'Etham: Jezraël, Jesman et Jebdas; le nom de leur sœur était Eselebbon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Et Phanuel fut le père de Gedor, et Jazer le père d\'Osan. Voilà les fils de Hur, du premier-né d\'Ephratha, père de Béthalaem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Et Assur, père de Thécoé, eut deux femmes: Aoda et Thoada.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Et Aoda lui enfanta Ohaïe, Ephal, Thêman et Aasther; voilà tous les fils d\'Aoda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Fils de Thoada: Sereth, Saar et Esthanam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Et Coé engendra Enob et Sabatha; le frère de Rhéchab, fils d\'Iarin, est issu de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Et Igabès fut plus illustre que ses frères, et sa mère lui donna le nom d\'Igabès, disant: J\'ai enfanté comme Gabès.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Et Igabès invoqua le Dieu d\'Israël, disant: Qu\'il vous plaise de me bénir, et de me bénir, et de dilater mes limites; puisse votre main être avec moi; puissiez-vous faire connaître que vous ne m\'abaisserez point. Et Dieu lui accorda tout ce qu\'il avait demandé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Et Caleb, père d\'Ascha, engendra Machir; celui-ci, père d\'Assathon,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Engendra Bathraïas, Bessée et Thêman, père de la ville de Naas, frère d\'Eselom, fils de Cenez; ce sont les hommes de Rhéchab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Et les fils de Cenez furent: Gothoniel et Saraia; et Gothoniel eut pour fils Athath.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Et Manathi engendra Gophera, et Sarah engendra Jobab, père d\'Ageaddaïr; car ils étaient tous artisans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Fils de Caleb, fils de Jéphoné: Her, Ada et Noom; Ada fut le père de Cenez.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Fils d\'Alehel: Zib, Zépha, Thiria et Eserel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Fils d\'Esri: Jéther, Morad, Apher et Jamon; Jéther engendra Maron, Sémeï et Jesba, père d\'Esthemon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Et sa femme Adia enfanta Jared, père de Gedor, et Aber, père de Sochon, et Hatiel, père de Zamon. Et Morad épousa Betthia, fille du Pharaon, et il en eut des fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Et Iduée, sœur de Nachaïm, père de Cella, fut mère de Garmi, et d\'Esthemon le Nohathite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Fils de Semon: Amnon, Ana, fils de sa femme Phana, et Inon. Fils de Sei: Zoan, et les fils qu\'il eut de Zoab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Fils de Sela, fils de Juda: Her, père de Léchab, et Laada, père de Marisa; les habitants d\'Ephrathabac, qui appartient à la maison d\'Esoba, sont issus d\'eux,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Et Joacin, et les hommes de Hozeba, et Joas, et Saraph: ceux-ci demeurèrent en Moab, et Dieu les en ramena; Abederin, Athouciim.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'C\'étaient les potiers qui, avec le roi, habitaient Ataïm et Gadira; ils s\'étaient enrichis dans ce royaume, et ils s\'y étaient fixés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Fils de Siméon: Namuel, Jamin, Jarib, Zarès et Saül,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Salem son fils, Mabasam son fils, Masma son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Amuel son fils, Sabud son fils, Zacchur son fils, Sémeï son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Sémeï eut seize fils et six filles, et ses frères n\'eurent pas beaucoup d\'enfants. Et leurs familles ne se multiplièrent point comme les fils de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Et ils habitaient: en Bersabée, en Molada, en Esersual,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'En Balaa, en Esem et en Tholad,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'En Bathuel, en Herma et en Sicelag (Sécelac),');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'En Bethmarimoth, en Hemisuséosin et en la maison de Baruséorim; telles furent leurs villes jusqu\'au roi David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Et leurs villages étaient: Etan, et Hin, et Rhemnon, et Thocca, et Esar; cinq villages.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Et tous leurs villages étaient autour des villes jusqu\'à Baal: tel était leur domaine, et telle était sa distribution.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Et Mosobab, et Jémoloch, et Josias, fils d\'Amasias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Et Johel, et Jéhu, fils d\'Asabias, fils de Saraus fils d\'Asiel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Et Elionaï, et Jocaba, et Jasuïe, et Asaïe, et Jediel, et Ismaël, et Bananias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Et Zuza, fils de Saphaï, fils d\'Alon, fils de Jedia, fils de Semri, fils de Samaïe,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Furent ceux qui eurent le nom de chefs en leurs familles, et qui, en leurs maisons paternelles, se multiplièrent jusqu\'à la multitude;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Et ils partirent, et ils allèrent jusqu\'à Gérara, à l\'orient d\'Haï, chercher des pâturages pour leurs troupeaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Et ils en trouvèrent d\'excellents en abondance; et la contrée devant eux était vaste, et le calme et la paix y régnaient; car auparavant quelques fils de Cham seulement s\'y étaient établis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Or, ceux dont les noms sont écrits ci-dessus, entrèrent chez eux au temps d\'Ezéchias, roi de Juda; ils ruinèrent leurs demeures, ainsi que les Mineïens qu\'ils y avaient trouvés, et ils les détruisirent entièrement, comme on le voit encore, et ils demeurèrent à leur place dans cette contrée, parce qu\'il y avait des pâturages pour leur bétail.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Et cinq cents hommes de ces fils de Siméon avec leurs chefs: Phalaetti, Noadie 1 Raphia et Oziel, fils de Jési, se transportèrent en la montagne de Seïr.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Et ils exterminèrent les restes d\'Amalec, qui ne s\'en sont jamais relevés jusqu\'à nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Voici les fils de Ruben; il était le premier-né; mais parce qu\'il s\'était introduit dans la couche de son père, Jacob ayant donné sa bénédiction à son fils Joseph, le droit d\'aînesse de Ruben ne lui était plus compté.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Car Juda était fort parmi ses frères; le chef est sorti de lui, la bénédiction est restée à Joseph.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Fils de Ruben, premier-né d\'Israël: Enoch, Phallus, Asron et Charmi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Fils de Johel: Sémeï et Banaïas son fils. Fils de Gug, fils de Sémeï,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Micha, son fils Recha, son fils Johel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Son fils Behel, qu\'emmena Thelgath-Phalnasar, roi des Assyriens; il était le chef des Rubénites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Et, avec lui, furent emmenés ses frères, selon le dénombrement qui en fut fait par familles; les chefs de ces familles étaient: Johel, Zacharie,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Et Balec, fils d\'Azuz, fils de Sama, fils de Johel. Balec demeurait en Aroer, et vers Nebo et Belmasson.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Et il s\'était étendu à l\'orient jusqu\'au désert, du côté de l\'Euphrate, parce qu\'il avait de nombreux troupeaux en la terre de Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Et, sous le règne de Saül, ils furent en guerre avec leurs voisins, et ceux qui habitaient sous des tentes tombèrent entre leurs mains, et ils maîtrisèrent toute la contrée à l\'orient de Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Les fils de Gad, en face, demeurèrent en la terre de Basan jusqu\'à Sela.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Le premier-né fut Johel; le second Saphan; puis, venaient Jania, le scribe de Basan,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Et ses frères, par familles paternelles: Michel, Mosollam, Sébée, Joré, Joachan, Zué et Obed; sept.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Les fils d\'Abihaïl, fils d\'Uri, fils d\'Isaïe, fils de Galaad, fils de Michel, fils de Jésé, fils de Jeddé, fils de Bas,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Frère du fils d\'Abdiel, fils de Guni, chef de la maison paternelle,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Habitaient en Galaad, en Basan, en leurs bourgs et en tout le territoire de Saron jusqu\'à ses limites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Leur dénombrement fut fait du temps de Joatham, roi de Juda, et de Jéroboam, roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Les fils de Ruben, Gad et la demi-tribu de Manassé comptaient quarante- quatre mille sept cent soixante hommes, dans la force de l\'âge, portant glaive et bouclier, tendant l\'arc, exercés à la guerre, propres à marcher au combat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Et ils furent en guerre avec les Agaréens, les Ituréens, les Naphiséens et les Nadabéens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Et ils l\'emportèrent sur eux. Et les Agaréens, avec toutes leurs tentes, tombèrent entre leurs mains, parce que les vainqueurs avaient invoqué Dieu pendant la bataille; et Dieu les exauça, parce qu\'ils avaient espéré en lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Et ils prirent tout ce que les autres possédaient: cinquante mille chameaux, deux cent cinquante mille brebis, deux mille ânes; et la vie de cent mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Car une grande multitude de blessés succomba, parce que cette guerre s\'était faite selon la volonté de Dieu, et les vainqueurs habitèrent le territoire des vaincus Jusqu\'à la captivité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Et la demi-tribu de Manassé s\'étendit de Basan Baal, Hermon, Sanir et la montagne d\'Hermon; ses fils se multiplièrent dans le Liban.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Et voici leurs chefs, par familles: Opher, Sei, Eliel, Jérémie, Oduïa et Jediel; hommes riches et renommés, chefs des familles de la demi-tribu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Et ils répudièrent le Dieu de leurs pères, et ils se prostituèrent à la suite des dieux de la terre que le Seigneur avait effacés devant leur face.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Et le Dieu d\'Israël excita l\'esprit de Phaloch (Phul), roi d\'Assur, et l\'esprit de Thelgath-Phalnasar, roi d\'Assur. Ce roi enleva Ruben, et Gad, et la demi-tribu de Manassé, et il les transporta en Haach, en Hahor, et sur le fleuve Gozan, où ils sont restés jusqu\'à nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 27, 'Fils de Lévi: Gerson, Caath et Mérari.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 28, 'Fils de Caath: Amram et Isaar, Hébron et Oziel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 29, 'Enfants d\'Amram: Aaron, Moïse et Marie. Fils d\'Aaron: Nadab et Abiud, Eléazar et Ithamar.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 30, 'Eléazar engendra Phinéès, et Phinéès engendra Abisué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 31, 'Abisué engendra Bocci, et Bocci engendra Ozi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 32, 'Ozi engendra Zaraïas, et Zaraïas engendra Mariel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 33, 'Mariel engendra Amarias, et Amarias engendra Achitob.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 34, 'Achitob engendra Sadoc, et Sadoc engendra Achimaas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 35, 'Achimaas engendra Azarias, et Azarias engendra Johanan,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 36, 'Johanan engendra Azarias; ce fut lui qui exerça le sacerdoce dans le temple que Salomon bâtit à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 37, 'Azarias engendra Amarias, et Amarias engendra Achitob.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 38, 'Achitob engendra Sadoc, et Sadoc engendra Salom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 39, 'Salom engendra Helcias, et Helcias engendra Azarias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 40, 'Azarias engendra Saraias, et Sareas engendra Josadac.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 41, 'Josadac fut enlevé, avec Juda et Jérusalem, par Nabuchodonosor.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Fils de Lévi: Gerson, Caath et Mérari.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Fils de Gerson: Lobeni et Sémei.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Fils de Caath: Amram et Isaac, Hébron et Oziel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Fils de Mérari: Mooli et Musi; voici les familles de Lévi, désignées par les noms de leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'A Gerson et Lobeni son fils succèdent Jeth fils de ce dernier, Zamath son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Joab son fils, Addi son fils, Zara son fils, Jethri son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'De Caath descendent: Aminadab son fils, Coré son fils, Aser son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Elcana son fils, Abisaph son fils, Aser son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Thaat son fils, Uriel son fils, Saül son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'D\'Elcana descendent encore: Amessi et Achimoth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Elcana son fils, Saphi son fils, Cénaath son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Eliab son fils, Jéroboam son fils, Elcana son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Fils de Samuel: Sari, premier-né, et Ables.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Fils de Mérari: Mooli son fils, Lobeni son fils, Sémei son fils, Oza son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Samaa son fils, Aggia son fils, Asaïas son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Et voici ceux que David institua chefs des chœurs du tabernacle, lorsqu\'il eut transféré l\'arche à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Et ils s\'accompagnaient avec des instruments, devant le tabernacle du témoignage, jusqu\'à ce que Salomon eût bâti le temple du Seigneur à Jérusalem. Et ils servaient, chacun selon la fonction qui lui était assignée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Voici leurs noms et ceux de leurs pères: de Caath descendait: Hëman, chantre et harpiste, fils de Johel, fils de Samuel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Fils d\'Elcana, fils de Jéroboam, fils d\'Eliel, fils de Thoü,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Fils de Suph, fils d\'Elcana, fils de Maath, fils d\'Amathi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Fils d\'Elcana, fils de Johel, fils d\'Azarias, fils de Saphanie,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Fils de Thaath, fils d\'Aser, fils d\'Abiasaph, fils de Coré,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Fils d\'Isaar, fils de Caath, fils de Lévi, fils d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Et Asaph, chantre comme lui, qui se tenait à sa droite, était fils de Barachias, fils de Samaa,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Fils de Michel, fils de Baasie, fils de Melchias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Fils d\'Athani, fils de Zaaraï, fils d\'Adaï,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Fils d\'Etham, fils de Zamnaam, fils de Sémeï,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Fils de Jeth, petit-fils de Gerson, fils de Lévi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Et de Mérari descendaient les chantres qui se tenaient à gauche, dont le chef était: Ethan, fils de Cisa, fils d\'Abe, fils de Maloch,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Fils d\'Asebi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Fils d\'Amessias, fils de Bani, fils de Semer,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Fils de Mooli, fils de Musi, fils de Mérari, fils de Lévi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Et les lévites leurs frères, selon leurs familles paternelles, étaient attachés aux divers services du tabernacle de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Aaron, et, après lui, ses fils sacrifiaient sur l\'autel des holocaustes et sur l\'autel des parfums; ils remplissaient toutes les fonctions relatives au Saint des saints; et ils priaient pour Israël, conformément à ce que leur avait commandé Moïse serviteur de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Voici les fils d\'Aaron: Eléazar son fils, Phinéès son fils, Abisué son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Bocci son fils, Ozi son fils, Saraïa son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Mariel son fils, Amarias son fils, Achitob son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Sadoc son fils, Achimais son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Voici les demeures, les bourgs et les territoires, assignés par le sort, selon leurs familles, aux fils d\'Aaron, et aux fils de Caath.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Il leur fut donné Hébron, en la terre de Juda, et sa banlieue tout alentour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Mais les champs de la ville et ses bourgs appartenaient à Caleb, fils de Jéphoné.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Les villes de refuge furent aussi concédées aux fils d\'Aaron, savoir: Hébron, Lobna et sa banlieue, Selna et sa banlieue, Esthamo et sa banlieue,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Jethar et sa banlieue, Dabir et sa banlieue,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Asan et sa banlieue, Bethsamys et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Et, dans la tribu de Benjamin, Gabée et sa banlieue, Galemath et sa banlieue, Anathoth et sa banlieue. En tout treize villes par familles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Et le sort assigna au reste des fils de Caath, par familles, dix villes de la demi-tribu de Manassé, en deçà du Jourdain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Et aux fils de Gerson, par familles, treize villes des tribus d\'Issachar, d\'Aser, de Nephthali et de la demi-tribu de Manassé en Hasan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Et aux fils de Mérari, par familles, douze villes des tribus de Ruben, de Gad et de Zabulon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Et les fils d\'Israël accordèrent aux lévites ces villes et leurs banlieues.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Le sort désigna dans les tribus de Juda, de Siméon et de Benjamin, les villes auxquelles les lévites donnèrent leurs noms,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'D\'après les familles des fils de Caath. Et ils eurent aussi des villes du territoire d\'Ephraïm,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Y compris les villes de refuge: Sichem et sa banlieue, dans la montagne d\'Ephraïm, Gazer et sa banlieue,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Jecmaan et sa banlieue, Béthoron et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Et, en d\'autres territoires, Aïlon et sa banlieue, Gethremmon et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Et de la demi-tribu de Manassé: Anar et sa banlieue, Jemblaan et sa banlieue, selon les familles du reste des fils de Caath.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Les fils de Gerson, par familles, eurent dans l\'autre demi-tribu de Manassé, Golan en Basan et sa banlieue, Aseroth et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Et dans la tribu d\'Issachar: Cédés et sa banlieue, Deberi et sa banlieue, Dabor et sa banlieue,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Ramoth, Aïnan et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Et dans la tribu d\'Aser: Maasal et sa banlieue, Abdon et sa banlieue,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Acac et sa banlieue, Rhoob et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Et dans la tribu de Nephthali: Cédés en Gaulée et sa banlieue, Hamoth et sa banlieue, Cariathaïm et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Et dans la tribu de Zabulon: le sort attribua au reste des fils de Mérari, Remmon et sa banlieue, Thabor et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Et dans la vallée du Jourdain à l\'occident du fleuve: Jéricho, et dans la tribu de Ruben: Bosor dans le désert et sa banlieue, Jasa et sa banlieue,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Cadmoth et sa banlieue, Maephla et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Dans la tribu de Gad: Ramoth-Galaad et sa banlieue, Maanaïm et sa banlieue,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Esébon et sa banlieue, Jazer et sa banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Quant aux fils d\'Issachar, ils étaient quatre: Thola, Phua, Jasub et Sémeron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Fils de Thola: Ozi, Raphaïas, Jeriel, Jamaï, Jémasan et Samuel, chefs des familles issues de Thola; dont le nombre, au temps de David, fut de vingt-deux mille six cents hommes, tous nés forts et vaillants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Fils d\'Ozi: Jezraïe; fils de Jezraïe: Michel, Abdiu, Johel et Jésia; en tout cinq chefs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Et avec eux, il y eut dans leurs familles paternelles des hommes nés forts et vaillants, au nombre de trente-six mille en état de porter les armes; Car ils avaient eu beaucoup de femmes et beaucoup d\'enfants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Et leurs frères dans toutes les familles d\'Issachar, hommes forts et vaillants aussi, étaient quatre-vingt-sept mille; tel fut leur nombre total.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Fils de Benjamin: Balé, Bachir et Jediel; trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Fils de Balé: Esebon, Ozi, Oziel, Jerimuth et Uri; cinq. Chefs des familles issues de Balé, au nombre de vingt-deux mille trente-quatre hommes forts et vaillants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Fils de Bachir: Zémira, Joas, Eliézer, Elithénan, Amarias, Jerimuth, Abiud, Anathoth et Eliémeth; voilà tous les fils de Bachir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Et le nombre des familles dont, selon leur naissance, ils furent les premiers chefs, s\'éleva jusqu\'à vingt. mille deux cents hommes forts et vaillants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Fils de Jediel: Balaan, fils de Balaan; Jaiis, Benjamin, Aoth, Chanana, Zêthan, Tharsi et Achisaar.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Voilà tous les fils de Jediel, vaillants chefs de familles, dont le nombre fut de dix-sept mille deux cents hommes forts et vaillants, en état de porter les armes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Saphin et Aphin étaient fils de Hor, et Hasom était fils d\'Aor.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Fils de Nephtbali: Jasiel, Goni et Aser, Sellom, fils de ce dernier, et Balam son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Fils de Manassé: Esriel, qu\'enfanta sa concubine la Syrienne,, qui lui enfanta aussi Machir, père de Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Et Machir maria Aphin et Saphin; sa sœur s\'appelait Moocha, et le nom du second fils fut Saphaad; or, Saphaad n\'eut que des filles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Et Moocha, femme de Machir, enfanta un fils, et elle le nomma Pharès, et il eut un frère nommé Suros, le même que Galaad, et ses deux fils furent Ulam et Rocom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Fils d\'Ulam: Badam; voilà les fils de Galaad, fils de Machir, fils de Manassé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Et sa sœur Malécheth enfanta Isud, Abiézer et Maéla;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Et Semira eut pour fils Kim, Sichem, Lacim et Anian.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Fils d\'Ephraïm: Sothalath, Barad, Thaath, Elada, Saath,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Zabad, Sothelé, Azer et Eléad. Et des hommes de Geth les tuèrent tous, parce qu\'ils s\'étaient mis en campagne pour enlever leurs troupeaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Et leur père Ephraïm s\'affligea longtemps, et ses frères vinrent le consoler.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Et il s\'approcha de sa femme, et elle conçut, et elle eut un fils, et il le nomma Beria, parce que, dit-il, il est venu en ma maison dans notre malheur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Et sa fille s\'appelait Saraa, et elle fut de ceux qui survécurent, et elle bâtit Béthoron-la-Haute et Béthoron-la-Basse. Fils d\'Ozan: Seïra,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Et Raphé son fils, Saraph et Thaléès ses fils, et Thaen son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'A Laadan, son fils, naquit Amiud, père d\'Elisamai,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Père de Nun, père de Josué; tels furent ses fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Et leur demeure était Béthel et ses bourgs, et Noaran à l\'est, et à l\'occident Gazer et ses bourgs. Et Sichem et ses bourgs, jusqu\'à Gazar et ses bourgs,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Et jusqu\'aux confins des fils de Manassé, Bethsan et ses bourgs, Thanach et ses bourgs, Mageddo et ses bourgs, Dor et ses bourgs. C\'est là qu\'étaient établis les fils de Joseph, fils d\'Israél.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Enfants d\'Aser: Jemna, Suïa, Isuï, Beria et Soré, sa sœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Fils de Beria: Haber, Melchiel; ce dernier père de Berthaïth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Et Haber engendra Japhlet, Samer, Hothan et Sola, leur sœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Fils de Japhlet: Phasec, Bamahel et Asith; voilà les fils de Japhlet.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Fils de Samer: Achi, Rooga, Joba et Aram.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Fils de son frère Banehelam: Sopha, Imala, Sellés et Amal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Fils de Sopha: Sué, Arnaphar, Suda, Barin, Imran,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Basan, 0a, Sama, Salisa, Jethra et Bééra.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Fils de \'éther: Jephina, Phaspha et Ara.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Fils d\'Ola: Orech, Aniel et Rasia;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Tels furent les fils d\'Aser, tous chefs de familles, dont le nombre fut de vingt-six mille hommes d\'élite, forts et vaillants, en état de porter les armes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Et Benjamin engendra Balé son premier-né, Asbel le second, Aara le troisième,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noa le quatrième, Rapha le cinquième.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Et les fils de Balé furent: Adir, Gera, Abiud,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abessué, Noama, Achias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sephupham et Uram.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Voici les fils d\'Aod qui furent chefs des familles établies à Gabaa, et transportées ensuite à Machanathi');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Nooma, Achias et Gera, le même que Jeglaam, qui engendra Aza et Jachicho.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Et Saarin engendra dans les champs de Moab, après qu\'il eut répudié Osin et Baada, ses femmes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Et il eut de sa femme Ada: Jolad, Sebia, Misa, Melchas,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jébus, Zabia et Marina; tous chefs de familles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Et il avait eu d\'Osin: Abitol et Alphaal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Fils d\'Alphaal: Obed, Misaal, Somer (celui-ci bâtit Ona, et Aod et ses bourgs),');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Et Beria et Sama (ceux-ci furent chefs des familles qui demeurèrent en Ailam, et qui chassèrent les habitants de Geth),');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Et ses frères furent Sosec, Arimoth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zabadie, Ored, Eder,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Michel, Jespha et Joda, fils de Beria,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Et Zabadie, Mosollam, Azaci, Abar,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Isamari, Jexlias et Jobab, fils d\'Elphaal,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Et Jacim, Zachri, Zabdi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elionaï, Salathi, Elihéli,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaïe, Baraïe et Samarath, fils de Samaïth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Et Jesphan, Obed, Elihel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Zechri, Anan,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Ananie, Ambri, Aïlam, Anathoth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jathir, Jephudias et Phanuel, fils de Sosec,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Et Samsari, Saarias, Gotholie,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jarasie, Erie et Zéchri, fils de Iroam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Voilà les chefs de famille selon leur naissance, et ils habitèrent Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Et en Gabaon demeura le père de Gabaon, sa femme se nommait Moacha,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Et son fils premier-né Abdon; puis, venaient Sur, Cis, Baal, Nadab, Ner,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedur et son frère, Zachur et Maceloth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Et Maceloth engendra Samaa; et ceux-ci, vis-à-vis leurs frères, habitèrent Jérusalem avec leurs frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Et Ner engendra Cis, et Cis engendra Saül, et Saül engendra Jonathas, Melchisué, Aminadab et Asabal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Et Jonathas engendra Meribaal, et Meribaal engendra Micha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Fils de Micha: Phithon, Melach, Tharach et Achaz.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Et Achaz engendra Jada, et Jada engendra Salémath, Asmoth et Zambri, et Zambri engendra Mesa,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Et Mesa engendra Baana. Raphaïa fut son fils, Elasa son fils, Esel son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Et Esel eut six fils; voici leurs noms: Ezricam son premier-né; puis, Ismaïl, Saraïa, Abdias, Anan et Asa, tous fils d\'Esel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Fils d\'Asel, son frère: Aïlam le premier-né, Jas le second, et Eliphalet le troisième.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Et les fils d\'Aïlam étaient des hommes forts et vaillants, et ils tendaient l\'arc, et leurs fils et les fils de leurs fils se multiplièrent jusqu\'à cent cinquante. Tous étaient issus de Benjamin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Voilà tout Israël et son dénombrement, et ceux qui furent inscrits au livre des Rois d\'Israël et de Juda, après qu\'ils eurent été transportés à Babylone à cause de tous leurs péchés,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Et ceux qui les premiers revinrent en leurs possessions et dans les villes d\'Israël, prêtres, lévites et autres à qui cela fut permis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Jérusalem fut repeuplée par des fils de Juda, des fils de Benjamin, des fils d\'Ephraïm et des fils de Manassé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Il y eut parmi eux: Nothi, fils de Samiud, fils d\'Amri, fils d\'Ambraïm, fils de Buni, issus des fils de Pharès, fils de Juda,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Et de la famille de Seléni Asaie premier-né, et ses fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Issus de Zara; puis, Jehel et leurs frères au nombre de six cent quatre- vingt-dix.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Et des fils de Benjamin: Salem, fils de Mosollam, fils d\'Odes, fils d\'Asinu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Et Jemnaa, fils de Jéroboam et Elo ceux-ci étaient issus d\'Ozi, fils de Machir), et Mosollam, fils de Saphatia, fils de Raguel, fils de Jemnaï,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Et leurs frères, selon leur naissance, au nombre de neuf cent cinquante- six, tous chefs de familles dans leur tribu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Et parmi les prêtres: Jodaé, et Joarim, et Jachin;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Et Azarias, fils d\'Helcias, fils de Mosollam, fils de Sadoc, fils de Maraïoth, fils d\'Achitob, grand prêtre du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Et Adaie, fils d\'Ira, fils de Phaschor, fils de Melchia, et Maasaïa, fils d\'Adiel, fils d\'Ezira, fils de Mosollam, fils de Maselmoth, fils d\'Emmer;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Et leurs frères, chefs de familles dans leur tribu, au nombre de dix-sept cent soixante, hommes vaillants et forts employés au temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Et des lévites: Saulaie, fils d\'Asob, fils d\'Ezricam, fils d\'Asahia, des fils de Mérari.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Et Bacbacar, Arès, Galaal et Matthanias, fils de Micha, fils de Zéchri, fils d\'Asaph.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Et Abdias, fils de Samias, fils de Galaal, fils d\'Idithun, et Barachie, fils d\'Ossa, fils d\'Elcana, qui demeurait dans les bourgs de Notephati.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Les portiers étaient: Salom, Acum, Telmon et Diman, et ses frères; Salom était leur chef.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Et jusqu\'à ce jour, le chef est attaché à la porte royale du côté de l\'orient; les portes sont les mêmes que celles des camps des fils de Lévi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Or, Sellum était fils de Coré, fils d\'Abiasaph, fils de Coré, et ses frères les Coréites, entre autres services dans le temple, gardaient le tabernacle; et leurs pères dans les camps du Seigneur en avaient gardé l\'entrée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Et Phinéès, fils d\'Eléazar, avait été leur chef devant le Seigneur, et après lui ceux ci-dessus nommés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zacharie, fils de Mosollam, gardait la porte du tabernacle du témoignage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Tous ceux qu\'on avait choisis pour garder les portes du temple étaient au nombre de deux cent douze; ils étaient dénombrés selon leurs résidences; David et Samuel le voyant les avaient institués, s\'en remettant à leur foi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Et eux et leurs fils gardaient les portes du temple, et, dans le temple, le tabernacle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Les portes regardaient les quatre vents du côté de l\'orient, de la mer, de Borée et de Notos.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Et leurs frères demeuraient dans leurs résidences, et en partaient pour qu\'ils fussent relevés de sept en sept jours, à partir du jour du sabbat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'A quatre chefs étaient confiés les gardiens des portes, et les lévites veillaient à ce quel nul ne s\'introduisît furtivement dans les chambres, ni dans le trésor du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Car la garde leur en était remise, et ils en avaient les clefs, et chaque matin dès l\'aurore ils ouvraient les portes du lieu saint;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Et quelques-uns des leurs étaient chargés du service des vases, qu\'on ne déplaçait pas sans qu\'ils les eussent comptés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Et d\'autres avaient la surveillance des provisions destinées aux choses saintes: de la fleur de farine, du vin, de l\'huile, de, l\'encens, des aromates.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Et ceux qui préparaient les parfums et les aromates étaient pris parmi les fils des prêtres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Et Matthathias, issu de Lévi, fils premier-né de Salom le Coréite, avait la surveillance de tout ce qui se préparait après les sacrifices dans la poêle à frire du grand prêtre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Et Banaïas, issu de ses frères, de la maison de Caath, était chargé des pains de proposition que l\'on consacrait de sabbat en sabbat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Et les chefs des chantres-harpistes, de la famille des lévites, étaient désignés chaque jour, car jour et nuit ils étaient employés;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Et les chefs distribués par familles demeuraient à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Or, Jehel avait habité Gabaon, qu\'il avait fondée; et sa femme se nommait Moocha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Noms de ses fils: Abdon, premier-né; puis, Sur, Cis, Baal, Ner et Nadab,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedur et son frère, et Zachur et Maceloth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Et Maceloth engendra Samaa, et ceux-ci demeurèrent à Jérusalem au milieu de leurs frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Et Ner engendra Cis, et Cis engendra Saül, et Saül engendra Jonathas, et Melchisué, et Aminadab et Asabal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Et Jonathas engendra Meribaal, et Meribaal engendra Micha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Fils de Micha: Phithon, Malach et Tharach.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Et Achaz engendra Juda, et Juda engendra Galemeth, Gazmoth et Zambri, et Zambri engendra Massa;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Et Massa engendra Baana, et Raphaïe son fils, et Elasa son fils, et Esel son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Et Esel eut six fils, et voici leurs noms: Ezricam, le premier-né; puis, Ismaël, Saraïa, Abdias, Anan et Asa; voilà les fils d\'Esel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Et les Philistins livrèrent bataille à Israël, et les hommes d\'Israël prirent la fuite devant eux, et ils furent taillés en pièces dans la montagne de Gelboé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Et les Philistins poursuivirent Saül et ses fils; ils tuèrent Jonathas, Aminadab et Melchisué, fils de Saül.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Et le poids de la bataille tomba sur Saül; les archers le trouvèrent, et ils dirigèrent leurs flèches et tous leurs efforts contre lui, et ils le percèrent de traits.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Saül dit alors au serviteur qui portait ses armes: Tire ton épée et perce-moi, de peur que ces incirconcis ne m\'approchent et ne m\'outragent. Le serviteur qui portait ses armes ne le voulut pas, car il avait grande crainte. Mais Saül prit l\'épée et se jeta sur la pointe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Et le serviteur qui portait ses armes vit que Saül était mort; lui-même se jeta sur son épée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Et Saül et ses trois fils avaient succombé en cette bataille, et toute sa maison ensemble avait péri.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Et du vallon où s\'était réfugié Israël, chacun vit que Saül et ses fils étaient morts, et ils s\'enfuirent tous, abandonnant leurs villes. Les Philistins survinrent, et ils prirent possession de leurs demeures.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Le lendemain, ils sortirent pour dépouiller les morts, et ils trouvèrent Saül et ses fils gisant dans les montagnes de Gelboé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Et ils ôtèrent ses vêtements, prirent sa tête et ses armes, et les envoyèrent alentour en la terre des Philistins, pour annoncer ces nouvelles à leurs idoles et au peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Et ils déposèrent les armes dans le temple de leur dieu, et sa tête dans le temple de Dagon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Et les habitants de Galaad apprirent comment les Philistins avaient traité Saül et Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Et tous les hommes vaillants de Galaad se levèrent, enlevèrent le corps de Saül, et les corps de ses fils, les transportèrent à Jabès, et ensevelirent leurs ossements sous le chêne de Jabès, et ils jeûnèrent sept jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Ainsi mourut Saül, à cause des péchés commis par lui contre Dieu et contre les paroles du Seigneur qu\'il n\'avait point gardées; car il avait consulté une sorcière, et Samuel le prophète lui avait répondu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Et il n\'avait point interrogé le Seigneur; Dieu le fit donc périr, et il transmit la royauté à David, fils de Jessé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Ensuite, tout Israël, alla trouver David à Hébron, disant: Vois, nous sommes tes os et ta chair.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Précédemment, quand Saül régnait encore, c\'est toi qui conduisais et ramenais Israël, et le Seigneur notre Dieu avait dit: Tu seras le pasteur d\'Israël, tu seras le chef de mon peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Et tous les anciens d\'Israël allèrent en Hébron auprès du roi, et David fit alliance avec eux devant le Seigneur, en Hébron, et ils le sacrèrent roi d\'Israël, selon la parole du Seigneur transmise par Samuel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Et le roi et ses hommes partirent pour Jérusalem, la même que Jébus; les Jébuséens habitaient cette terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Et ils dirent à David: Tu n\'entreras pas ici. Et il prit la forteresse de Sion, la même que la ville de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Or, David avait dit: Celui qui, le premier, frappera le Jébuséen, sera général de mon armée; et Joab, fils de Sarvia, monta le premier à l\'assaut, et il fut nommé général.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Et David s\'établit dans la forteresse. A cause de cela, il l\'appela Ville de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Et il bâtit la ville alentour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'David alla ainsi grandissant, et le Seigneur tout-puissant était avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Voici les chefs des vaillants qui étaient avec David, et qui l\'aidèrent à affermir son pouvoir sur tout Israël, selon la parole du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Voici les noms des vaillants de David: Jésebada, fils d\'Achaman, le premier des trente. Ce fut lui qui tira l\'épée seul contre trois cents, et les tua tous en une fois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Après lui, Eléazar (Eléanan), fils de Dudi l\'Ahonite; celui-ci était de la première triade.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Il était avec David à Phasodamin, et les Philistins s\'y réunirent pour livrer bataille. Or, il y avait un champ en partie couvert d\'orge, et le peuple s\'enfuit devant les Philistins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Pour lui, il s\'arrêta au milieu du champ, et il le sauva; il tailla en pièces les Philistins, et le Seigneur opéra une grande délivrance.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Et trois, des trente chefs, se rendirent auprès de David, en la caverne d\'Odollam, quand les Philistins étaient campés dans le val des Géants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'David se tenait dans sa forteresse, et les Philistins avaient un poste à Bethléem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Et David eut un désir, et il dit: Qui m\'apportera à boire de l\'eau de la citerne qui est sous la porte de Bethléem?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Et les trois vaillants s\'ouvrirent un passage à travers le camp des Philistins, et ils puisèrent de l\'eau dans la citerne sous la porte de Bethléem, et ils l\'emportèrent, et ils la présentèrent à David; mais il ne voulut pas la boire, et il en fit une libation au Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Et il dit: Dieu me protège, je n\'en ferai rien; je croirais boire le sang des hommes qui ont exposé leur vie. Et il ne voulut point boire; voilà ce qu\'avaient fait les trois vaillants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Il y avait encore Abisaï (Abessa), frère de Joab; celui-ci était chef d\'une seconde triade; il avait tiré l\'épée contre trois cents qu\'il avait tués tous en une fois, et il s\'était fait un nom parmi les trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Et, dans sa triade, il fut illustre, et il en devint le chef; mais il n\'alla pas aussi loin que ceux de la première triade.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Il y avait aussi Banaïas, fils d\'un homme vaillant, fils de Joad; il avait fait beaucoup de belles actions en faveur de Cabséel; ce fut lui qui tua deux Ariel de Moab, et qui descendit dans une citerne, un jour de neige, et qui y tua un lion.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Il tua encore un Égyptien, homme prodigieux, haut de cinq coudées, qui tenait dans sa main une javeline semblable au mât d\'un tisserand; il l\'attaqua, n\'ayant qu\'un bâton, il lui arracha des mains sa javeline, et il le tua avec cette javeline.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Voilà ce que fit Banaïas, fils de Joad, et son nom figurait dans la seconde triade.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Et il fut plus illustre que les trente; mais il n\'alla pas si loin que la première triade, et David le mit à la tête de sa maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Et les vaillants de l\'armée étaient: Asaël, frère de Joab; Eléanan, fils de Dudi de Bethléem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Samoth d\'Arori, Hellès de Pheloni,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ora, fils d\'Eccis de Thécoé; Abiézer d\'Anathoth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Soboch d\'Usathi, Héli d\'Achoni,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maraï de Netophath; Thaod, fils de Nooza de Netophath;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Aïri, fils de Rebié de la montagne de Benjamin; Banaïas de Pharathon;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Uri de Nachali-Gaas, Abiel de Garabeth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azbon de Baromi, Eliaba de Salaboni,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Fils d\'Aasam le Gizonéen; Jonathas, fils de Sola d\'Arari;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Achim, fils d\'Achar d\'Arari; Elphat, fils de Thyrophar,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'De Mechorathri; Achias de Pheloni,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Eseré de Chadmadaïm; Naaré, fils d\'Azobé;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Johel, fils de Nathan; Mebaal, fils d\'Agari;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Selé, fils de l\'Ammonite; Nachor de Beroth, qui portait les armes du fils de Sarvia.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Iras de Jéther, Gaber de Jéther,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urie l\'Hettéen; Zabet, fils d\'Achaïas;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, fils de Saiza, l\'un des chefs de Ruben; et il y en avait trente avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Anan, fils de Moocha; Josaphat le Matthanéen,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Ozias d\'Astaroth; Samatha et Jehiel, fils de Hothan d\'Arari;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediel, fils de Sameri; et Jozaé son frère le Thosaïte,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Elihel le Mahoïte, et Jaribi, et Josias son fils, et Jethama le Moabite,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Daliel, et Obeth, et Jersiel le Mesobéen.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Et voici ceux qui accompagnaient David à Sicelag, quand il était contraint de se cacher de Saül, fils de Cis; et ils comptaient parmi les vaillants, hommes de secours dans les batailles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Ils tiraient leur arc de la main droite et de la main gauche; ils étaient frondeurs et archers. Des frères de Saül, de la tribu de Benjamin,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Le chef était Achiézer; puis, venaient Joas, fils d\'Asma le Gabathéen; Johel, Jophalet, fils d\'Asmoth; Berchia, Jehul d\'Anathoth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Samaïas de Gabaon, vaillant parmi les trente, et leur chef,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'puis, Jérémie, Jézéel, Joanan, Joazobath de Garathiim,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Azaï, Arimuth, Baalie, Samaraie et Saphatias d\'Haréphiel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Elcana, Jesuni, Ozriel, Jozara, Sobocam et les Coréens,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Et Jelia, Zabadie, fils de Joram, et ceux de Gédor.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Et, de la tribu de Gad, des hommes vaillants et forts, quittant le désert, rejoignirent David; tous exercés aux combats, portant bouclier et javelines, hommes à face de lion, et légers à la course dans les montagnes, comme des chevreuils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Aza était le chef, Abdias le second, Eliab le troisième,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Masmana le quatrième, Jérémie le cinquième,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Jéthi le sixième, Eliab le septième,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Joanan le huitième, Eléazer le neuvième,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Jérémia le dixième, Melcbanaï le onzième.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ils étaient les chefs de l\'armée des fils de Gad; celui du moindre rang commandait cent hommes; celui du rang le plus élevé en commandait mille.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Ce furent ceux-là qui passèrent le Jourdain pendant le premier mois, lorsqu\'il coulait à pleins bords, et ils mirent en fuite tous ceux qui habitaient ses deux rives.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Il vint aussi à David des auxiliaires des fils de Benjamin et de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Et David se porta au-devant d\'eux, et il leur dit: Si vous êtes venus en paix, mon cœur sera bienveillant pour vous; mais si vous n\'êtes point sincères, si vous avez dessein de me livrer à mes ennemis, que le Dieu de vos pères vous voie, et qu\'il vous punisse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Et l\'esprit entra en Amasaï, un chef des trente, et il dit: David, fils de Jessé, marche avec ton peuple, la paix, la paix avec toi, la paix avec tes auxiliaires; car c\'est ton Dieu qui t\'a secondé. Et David les accueillit, et il leur donna des commandements dans l\'armée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Et des fils de Manassé vinrent à David, dans le même temps que les Philistins étaient en guerre avec Saül, et qu\'ils avaient répudié le secours de David, parce que, dans leur conseil, les chefs des Philistins avaient dit: Il se réconciliera avec son maître Saül, en lui portant les têtes de nos hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Et comme il retournait à Sicelag, Edna, Josabeth, Rodiel, Michel, Josabeth, Elimuth et Semathi, vinrent auprès de lui, de Manassé; c\'étaient des chefs de mille hommes de Manassé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Et ils furent les auxiliaires de David contre ses ennemis; tous vaillants, comme ils l\'étaient, prirent rang parmi les chefs de l\'armée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Car cette armée s\'augmentait de jour en jour, et elle devenait forte comme l\'armée de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Et voici le dénombrement des chefs de l\'armée qui entrèrent avec David à Hébron, pour lui transmettre la royauté de Saül, selon la parole du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Fils de Juda, portant lance et bouclier: six mille huit cents, prêts à combattre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Fils de Siméon, vaillants prêts à combattre: sept mille cent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Fils de Lévi: quatre mille six cents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Joad conduisait les fils d\'Aaron; il avait avec lui trois mille sept cents hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Sadoc, jeune homme fort et vaillant, avait amené, de sa famille paternelle, vingt-deux chefs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Fils de Benjamin, frères de Saül: trois mille; mais le plus grand nombre de cette tribu formait encore la garde du palais de Saül.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Fils d\'Ephraïm: vingt mille, vaillants et forts, hommes illustres dans leurs familles paternelles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Fils de la demi-tribu de Manassé: dix-huit mille, qui furent recensés nominativement, pour établir roi David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Fils d\'Issachar, connaissant ce qu\'exigeaient les circonstances, sachant ce qu\'il y avait à faire pour Israël: deux cents, et avec eux tous leurs frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Fils de Zabulon, allant au combat avec toutes les armes de guerre: cinquante mille, auxiliaires de David, n\'ayant pas les mains vides.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Fils de Nephthali: mille chefs, et avec eux trente-sept mille hommes, portant lance et bouclier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Fils de Dan, prêts à combattre: vingt-huit mille huit cents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Fils d\'Aser: quarante mille auxiliaires.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Fils de Ruben, de Gad, et de la demi-tribu de Manassé, au delà du Jourdain, portant toutes les armes de guerre: cent vingt mille.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Tous ces hommes, qui étaient aguerris et prêts à combattre, vinrent à Hébron, pleins d\'un esprit pacifique, afin de proclamer David roi de tout Israël, et tout le reste du peuple n\'avait qu\'une âme pour couronner David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Et ils demeurèrent trois jours, mangeant et buvant ce que leurs frères avaient préparé pour eux,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 41, 'Et ce qu\'on leur apportait de tout le territoire depuis Issachar jusqu\'à Zabulon et Nephthali, sur des chameaux, des ânes, des mulets et des bœufs, savoir: des viandes cuites, de la farine, des figues, des raisins secs, du vin et de l\'huile, outre une multitude de bœufs et de moutons; car tout Israël était en joie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Et David tint conseil avec tous ses chefs, centeniers ou commandants de mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Et David dit à toute l\'Église d\'Israël: Si cela vous paraît bon et agréable au Seigneur notre Dieu, envoyons chez nos frères qui sont restés en tout le territoire d\'Israël, et chez les prêtres et les lévites, dans les villes où ils résident; qu\'il se réunissent à nous,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Et amenons auprès de nous l\'arche de notre Dieu; car, depuis l\'avènement de Saül, on ne l\'a point demandée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Et toute l\'Église dit qu\'il fallait faire ainsi; car ce discours avait plu à tout le peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Et David réunit tout Israël, depuis les confins de l\'Égypte jusqu\'aux défilés d\'Emath, pour ramener l\'arche de la ville d\'Iarim.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Et David la ramena; et tout Israël entra dans la ville de David, qui est en Juda, pour y introduire l\'arche du Seigneur Dieu assis sur les chérubins, où est invoqué son nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'On avait posé l\'arche de Dieu sur un chariot neuf de la maison d\'Aminadab; Oza et ses frères conduisaient l\'attelage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Et David et tout Israël jouaient de tout leur cœur de la flûte, de la lyre, du tambour, et des cymbales, et de la harpe, au milieu des cantiques.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Et ils vinrent jusqu\'à l\'aire; là, Oza étendit la main pour maintenir l\'arche que le mouvement d\'un bœuf avait fait pencher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Mais le Seigneur s\'irrita contre Oza, et il le frappa en ce lieu même, parce qu\'il avait porté la main sur l\'arche; et il mourut là devant Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Et David fut abattu, parce que Dieu avait châtié Oza, et ce lieu fut appelé le Châtiment d\'Oza, nom qu\'il porte encore de nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Et, ce jour-là, David eut crainte du Seigneur, et il dit: Comment ferai- je entrer chez moi l\'arche du Seigneur?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Et David ne ramena pas l\'arche avec lui dans la ville de David; mais la fit placer en la maison d\'Abdara le Géthéen.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Et l\'arche du Seigneur resta trois mois en la maison d\'Abdara le Géthéen, et le Seigneur bénit toute la maison d\'Abdara et tout ce qui lui appartenait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Et Hiram, roi de Tyr, envoya à David des messagers, des maçons et des charpentiers, avec des bois de cèdre, pour lui bâtir une maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Et David reconnut que le Seigneur l\'avait préparé pour être roi d\'Israël; car son royaume s\'était élevé et agrandi pour le bien être du peuple d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Et David prit encore des femmes à Jérusalem; elles lui enfantèrent des fils et des filles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Voici les noms de ceux qui naquirent à Jérusalem: Samaa, Sobab, Nathan, Salomon,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Baar (Ebeher), Elisa (Elisua), Eliphaleth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nageth (Naged), Naphath (Naphec), Japhia,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Eliada et Eliphalat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Cependant, les Philistins apprirent que David avait été sacré roi de tout Israël; et ils se mirent tous en campagne pour l\'attaquer; mais lui, l\'ayant su, sortit à leur rencontre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Et ils s\'avancèrent, et ils s\'entassèrent dans le val des Géants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Et David consulta Dieu, disant: Dois-je marcher contre les Philistins? me les livrerez-vous? Et le Seigneur lui répondit: Marche, car je te les livrerai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Et il alla à Baal-Pharasin, où il les battit, et il s\'écria: Dieu, par mes mains, a brisé mes ennemis comme brisent les eaux des torrents. A cause de cela, il donna à ce lieu le nom de Brisement d\'en haut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Or, les Philistins avaient abandonné là leurs dieux, et David dit: Livrez-les aux flammes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Et les Philistins continuèrent la guerre, et ils se réunirent encore dans le val des Géants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Et David consulta derechef le Seigneur, et le Seigneur lui dit: Ne les suis pas, fais un détour, et tu les aborderas près des poiriers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Et ceci arrivera: Lorsque tu entendras, de la colline des Poiriers, le bruit sourd de l\'ébranlement qu\'ils donneront au sol, tu engageras la bataille; car alors le Seigneur marchera devant toi pour frapper le camp des Philistins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'David fit ce que lui avait prescrit le Seigneur, et il tailla en pièces les Philistins, depuis Gabaon jusqu\'à Gazara.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Et le nom de David se répandit sur toute la terre, et le Seigneur inspira à tous les peuples la crainte de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Et il se bâtit des demeures en la ville de David, et il prépara un lieu pour l\'arche du Seigneur, et il fit un tabernacle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Alors David dit: Nul ne peut transporter l\'arche de Dieu, sinon les lévites; car le Seigneur les a choisis pour porter l\'arche du Seigneur et le servir éternellement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Et David réunit tout le peuple de Jérusalem, pour transporter l\'arche au lieu qu\'il avait préparé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'David convoqua aussi les lévites, fils d\'Aaron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Des fils de Caath: Uriel leur chef, et ses frères: cent vingt hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Des fils de Mérari: Asaie leur chef, et ses frères: deux cent vingt.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Des fils de Gerson: Johel leur chef, et ses frères: cent trente.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Des fils d\'Elisaphat: Sémeï leur chef, et ses frères: deux cents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Des fils d\'Hébron: Elihel leur chef, et ses frères: quatre-vingts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Des fils d\'Oziel: Aminadab leur chef, et ses frères: cent douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Et David appela les prêtres Sadoc et Abiathar avec les lévites: Uriel, et Asaïe, et Johel, et Sémeï, et Elihel, et Aminadab,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Et il leur dit: Vous êtes chefs de familles des lévites: purifiez-vous donc, et purifiez vos frères, et vous transporterez l\'arche du Dieu d\'Israël, au lieu que je lui ai préparé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Car, d\'abord, parce que vous n\'étiez point là; le Seigneur Dieu nous a châtiés, pour ne l\'avoir point cherché, selon la loi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Et les prêtres et les lévites se purifièrent, pour transporter l\'arche du Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Et les fils des lévites prirent l\'arche de Dieu de la manière prescrite par Moïse, d\'après la parole de Dieu et selon l\'Écriture; puis, ils posèrent les leviers sur leurs épaules.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Et David dit aux chefs des lévites: Choisissez parmi vos frères des chantres, s\'accompagnant d\'instruments: de lyres, de harpes et de cymbales, pour chanter bien haut des cantiques d\'allégresse,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Et les lévites désignèrent Hêman, fils de Johel; puis, Asaph, fils de Barachia, un de leurs frères; puis, Ethan, fils de Cisaïe, un des fils de Mérari, un de leurs frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'Et, avec eux, au second rang, leurs frères Zacharie, Oziel, Semiramoth, Jehiel, Eliohel, Eliab, Banaias, Maasaïe, Matthathias, Eliphena, Macélia, Abdedom, Jehiel et Ozias, qui étaient les portiers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Les chantres harpistes: Hêman, Asaph et Ethan, avaient des cymbales d\'airain pour les faire retentir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zacharie et Oziel, Semiramoth, Jéhiel, Oni, Eliab, Maasaïe, Banaïas, avaient des lyres sur l\'alcimoth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Et Matthathias, et Eliphalu, et Macélia, et Abdedom, et Jehiel, et Ozias, avaient des harpes pour renforcer l\'amasenith.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Honénias, chef des lévites, était maître du chant, à cause de son intelligence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Barachias et Elcana étaient portiers de l\'arche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Somnia, Josaphat, Nathanaël Amasaï, Zacharie, Banaïas et Eliézer, les prêtres, sonnaient de la trompette devant l\'arche de Dieu. Abdedom et Jehia étaient portiers de l\'arche de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'David, et les anciens d\'Israël et les chefs de mille hommes, partirent ainsi pour transférer l\'arche de l\'alliance de la maison d\'Abdedom, avec allégresse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Et comme Dieu fortifiait les lévites qui portaient l\'arche de l\'alliance du Seigneur, on sacrifia devant le cortège sept bœufs et sept béliers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Or, David était revêtu d\'une robe de lin, ainsi que tous les lévites qui portaient l\'arche de l\'alliance du Seigneur, et les chantres-harpistes, et Honénias, maître du chant; David avait comme eux une robe de lin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Et tout Israël conduisait l\'arche de l\'alliance du Seigneur, jetant des cris de joie et chantant: les uns au son des trompettes et des cymbales, les autres avec accompagnement de lyres et de harpes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Lorsque l\'arche de l\'alliance du Seigneur entra dans la ville de David, Michol, fille de Sain, se penchant à sa fenêtre, vit le roi David danser et toucher de la harpe; et, en son âme, elle le méprisa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Et ils introduisirent l\'arche de Dieu, et la placèrent au milieu du tabernacle que David avait dressé pour elle, et l\'on offrit devant Dieu des holocaustes et des hosties pacifiques.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Quand David eut fait ses offrandes d\'holocaustes et d\'hosties pacifiques, il bénit le peuple au nom du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Et il donna à chaque homme et à chaque femme d\'Israël un pain de boulanger, et un pain pétri avec du miel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Et il institua devant l\'arche de l\'alliance du Seigneur ceux des lévites qui devaient y être employés, pour chanter et louer le Seigneur Dieu d\'Israël, et lui rendre grâces.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaph fut le chef, et il eut pour second Zacharie; puis, Jehiel, Semiramoth et Jehiel, Matthathias, Eliab, Banaïas et Abdedom: Jehiel jouait de la lyre et de la harpe, et Asaph faisait retentir des cymbales.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Banaïas et Oziel les prêtres, sonnaient toujours de la trompette devant l\'arche de l\'alliance du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Et ce jour-là, pour la première fois, David prescrivit que l\'on chantât les louanges du Seigneur, sous la direction d\'Asaph et de ses frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Cantique. Rendez hommage au Seigneur, invoquez-le par son nom, faites connaître aux peuples ses désirs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Chantez-le, chantez ses louanges; racontez à tous les merveilles qu\'a faites le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Louez son saint nom; le cœur qui cherche à lui âtre agréable sera réjoui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Cherchez le Seigneur et soyez forts; cherchez toujours son visage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Souvenez-vous des prodiges qu\'il a faits, des merveilles et des jugements sortis de sa bouche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Enfants d\'Israël, ses serviteurs; fils de Jacob, ses élus;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Le Seigneur seul est notre Dieu; ses jugements sont sur toute la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Souvenons-nous toujours de son alliance, de la loi qu\'il nous a donnée pour des milliers de générations,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'De son alliance avec Abraham; de son serment à Isaac,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Il l\'a confirmé à Jacob comme un commandement, à Israël comme une alliance impérissable,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Disant: Je te donnerai la terre de Chanaan; c\'est ta part d\'héritage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Alors, ils étaient en petit nombre, ils étaient humbles, et ils étaient passagers sur cette terre,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Et ils allèrent d\'une nation à l\'autre, et d\'un royaume à un autre peuple,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Et à nul homme il ne permit de prévaloir sur eux, et à leur sujet il châtia des rois:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Ne touchez point à mes christs; ne maltraitez pas mes prophètes,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Chantez le Seigneur: que toute la terre le chante, proclamez chaque jour que lui seul est notre salut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, '[Racontez aux nations sa gloire, à tous les peuples ses merveilles.] Car le Seigneur est grand et digne de louanges infinies; il est redoutable plus que tous les dieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, '[Racontez aux nations sa gloire, à tous les peuples ses merveilles.] Car le Seigneur est grand et digne de louanges infinies; il est redoutable plus que tous les dieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Car, tous les dieux des nations sont des idoles, et notre Dieu a créé le ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Gloire et louange à lui face à face; force et joie au lieu où il réside.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Tribus des nations, donnez au Seigneur, donnez au Seigneur force et gloire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Glorifiez le nom du Seigneur; prenez des dons et offrez-les au Seigneur en sa présence, et adorez le Seigneur dans ses demeures saintes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Que toute la terre ait crainte devant lui; que la terre s\'affermisse et ne soit point ébranlée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Que le ciel se réjouisse, que la terre tressaille d\'allégresse, et qu\'ils disent aux nations: Le Seigneur règne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'La mer bruira dans sa plénitude, et l\'arbre des champs avec tout ce qu\'il porte se réjouira.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Alors, les arbres de la forêt se réjouiront devant le Seigneur, parce qu\'il est venu juger la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Rendez hommage au Seigneur, parce qu\'il est bon et que sa miséricorde est éternelle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Et dites: Sauvez-nous, ô Dieu notre salut; recueillez-nous et séparez- nous des nations, afin que nous chantions les louanges de votre saint nom, et que noua mettions notre gloire à vous louer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Béni soit le nom du Seigneur Dieu d\'Israël dans tous les siècles des siècles, et tout le peuple dira: Amen. Et ils louèrent le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Et ils laissèrent là devant l\'arche de l\'alliance du Seigneur Asaph et ses frères, pour faire devant l\'arche à perpétuité le service de chaque jour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Ils laissèrent aussi Abdedom et ses frères, au nombre de soixante-huit, et Abdedom, fils d\'Idithun, et Osa pour être portiers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Et Sadoc le prêtre, avec ses frères les prêtres, fut laissé devant le tabernacle du Seigneur, sur le haut lieu de Gabaon,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Afin d\'offrir des holocaustes au Seigneur, sur l\'autel des holocaustes à perpétuité, matin et soir, selon qu\'il est écrit en la loi du Seigneur, qu\'il a donnée aux fils d\'Israël par la voix de Moïse, son serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Et avec Sadoc étaient Hêman et Idithun, et le reste de ceux qu\'on avait nominativement désignés pour louer le Seigneur, parce que sa miséricorde est éternelle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Et ils avaient avec eux des trompettes et des cymbales, pour les faire retentir, et les instruments accompagnant les cantiques de Dieu. Et les fils d\'Idithun étaient gardiens des portes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Et le peuple s\'en retourna chacun en sa demeure, et David s\'en alla pour bénir sa maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Et quand David eut pris possession de son palais, il dit à Nathan le prophète: Voilà que j\'habite une maison de cèdre, tandis que l\'arche de l\'alliance du Seigneur repose sous des courtines de peaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Et Nathan dit à David: Tout ce qui est en ton cœur, fais-le, car Dieu est avec toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Mais, cette nuit même, la parole du Seigneur vint à Nathan, et lui dit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Va, et dis à mon serviteur David; Voici ce que dit le Seigneur: Tu ne me bâtiras pas un temple pour que je l\'habite,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Parce que je n\'ai point résidé dans un temple depuis que j\'ai tiré de l\'Égypte les fils d\'Israël jusqu\'à ce jour, et que je me suis tenu dans un tabernacle et sous un voile.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'En quelque lieu que j\'aie passé avec tout Israël, ai-je jamais dit à celle des tribus que j\'avais chargée de prendre soin de tout le peuple: Pourquoi ne m\'avez-vous point bâti une maison de cèdre?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Dis encore à mon serviteur David: Voici ce que dit le Seigneur tout- puissant: Je t\'ai tiré de la bergerie quand tu marchais derrière les troupeaux, pour que tu sois roi de mon peuple Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Je t\'ai accompagné partout où tu as marché, j\'ai exterminé devant toi tous tes ennemis, et je t\'ai rendu célèbre autant que les plus renommés des grands de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Et j\'adopterai un lieu pour mon peuple Israël; je l\'y fixerai et il s\'y abritera, chacun aura sa demeure, et il ne sentira plus d\'inquiétudes, et le fils de l\'iniquité ne l\'affligera plus comme il a fait dès le commencement,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Depuis les temps où j\'ai donné des juges à mon peuple; j\'ai humilié tous tes ennemis, et je t\'augmenterai, et le Seigneur te fera une maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Et, quand tes jours seront remplis, quand tu te seras endormi avec tes pères, j\'élèverai après toi ta race et celui qui sera issu de ton sang; et je préparerai son règne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Celui-là me bâtira un temple, et je dresserai son trône pour toujours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Je serai pour lui un père, et il sera pour moi un fils, et je ne lui retirerai point ma miséricorde, comme je l\'ai retirée à ceux qui t\'ont précédé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Et je l\'établirai en mon temple, et en son royaume pour toujours; et son trône sera toujours debout.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Ainsi, Nathan répéta à David toutes ces paroles, que lui-même avait ouïes en sa vision.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Alors, le roi David s\'en alla; et il se plaça devant le Seigneur, et il dit: Qui suis-je, Seigneur mon Dieu, et qu\'est ma maison pour que vous m\'aimiez à jamais?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Ce que vous en avez fait c\'était à vos yeux peu de chose, ô mon Dieu, et vous avez parlé de la maison de votre serviteur pour un avenir lointain, et vous m\'avez regardé comme on regarde un ami, et vous m\'avez élevé, Seigneur mon Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Que pourra faire encore David devant vous pour vous glorifier? Vous connaissez maintenant votre serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Vous avez opéré ces grandes choses au gré de votre cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Seigneur, nul ne vous ressemble, nul n\'est Dieu que vous, et vous vous êtes révélé par toutes les merveilles que nous avons oui redire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Et il n\'est point sur la terre de peuple qui ressemble à Israël votre peuple. Il n\'en est point que Dieu. ait guidé pour le racheter et s\'en faire un peuple pour lui-même, pour se faire à lui-même un grand et glorieux nom, et pour expulser les nations devant votre peuple que vous avez délivré de l\'Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Vous vous êtes donné, en Israël, un peuple qui sera votre peuple à jamais; et vous, Seigneur, vous êtes son Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Maintenant donc, Seigneur, que la promesse que vous avez faite à votre serviteur, concernant sa maison, soit à jamais confirmée; faites comme vous avez dit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Et que votre nom soit glorifié à jamais, et que l\'on y ait foi, et que l\'on dise: Seigneur, Seigneur tout-puissant, Dieu d\'Israël, la maison de David votre serviteur est érigée devant vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Car, Seigneur Dieu, vous avez révélé vos desseins à votre serviteur, disant: Je te bâtirai une maison; c\'est à ce sujet que votre serviteur a pensé à vous prier face à face.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Et maintenant, Seigneur, vous seul êtes Dieu, et c\'est vous qui avez fait à votre serviteur ces magnifiques promesses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Commencez donc et bénissez la maison de votre serviteur, pour qu\'elle subsiste toujours devant vous; car, Seigneur, vous l\'avez déjà bénie, bénissez-la donc à jamais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Il advint, après cela, que David battit les Philistins et qu\'il les mit en fuite; et il leur enleva Geth avec ses bourgs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Il vainquit Moab, et les fils de Moab lui furent asservis; et ils lui payèrent un tribut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'David vainquit aussi, dans le pays d\'Hémath, Adraazar, roi de Suba, qui s\'était mis en campagne pour se rendre maître des rives de l\'Euphrate.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Et David prit aux vaincus mille chars, sept mille chevaux et vingt mille piétons; puis, il énerva les attelages de tous les chars, et n\'en garda que cent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Et le Syrien de Damas marcha au secours d\'Adraazar, roi de Suba, et David tua au Syrien vingt-deux mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Et David mit une garnison dans la Syrie de Damas, et les Syriens lui furent asservis; ils lui payèrent un tribut. Et le Seigneur protégea David partout où il porta ses armes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Et David prit les colliers d\'or que portaient les serviteurs d\'Adraazar, et il les consacra dans Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Et David recueillit à Mathabeth (Métébac), et dans les principales villes d\'Adraazar, une prodigieuse quantité d\'airain, dont Salomon se servit pour fabriquer la mer d\'airain, et les colonnes et tous les vases d\'airain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Cependant Thoa (Thu), roi d\'Hémath, apprit que David avait taillé en pièces toute l\'armée d\'Adraazar.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Et il envoya vers David son fils Aduram (Jedduram), pour lui demander la paix et le bénir à cause de sa victoire sur Adraazar; car Thoa était ennemi d\'Adraazar. Et tous les vases d\'or, d\'argent et d\'airain,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Le roi David les consacra au Seigneur de même que l\'argent et l\'or qu\'il avait pris à toutes les nations: à l\'Idumée, à Moab, aux fils d\'Ammon, aux Philistins et aux fils d\'Amalec.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Et Abessa, fils de Sarvia, tailla en pièces quatre-vingt mille Philistins dans le val d\'Aïlon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Et il mit dans la vallée une garnison, et tous les Iduméens furent asservis à David, et le Seigneur protégea David partout où il porta ses armes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Ainsi, David régna sur tout Israël, et il jugea tout son peuple selon l\'équité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab, fils de Sarvia, commandait l\'armée; Josaphat, fils d\'Achilud, recueillait les actes publics.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Sadoc, fils d\'Achitob, et Achimélech, fils d\'Abiathar,, étaient prêtres, et Susa (Sasa), scribe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Et Banaïas, fils de Joad, commandait Chéléthi et Phéléthi, et les fils de David étaient les premiers lieutenants du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Et Naas, roi des fils d\'Ammon, mourut, et Anan (Annon), son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Et David dit: Je serai miséricordieux envers Anan, fils de Naas, de même que son père a été miséricordieux pour moi. En conséquence, il envoya des serviteurs pour le consoler au sujet de son père, et les serviteurs de David allèrent en la terre des fils d\'Ammon, auprès d\'Anan, pour le consoler.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Mais, les princes des fils d\'Ammon dirent à Anan: Est-ce pour glorifier devant toi ton père que David envoie ces consolateurs? N\'est-ce point plutôt pour s\'informer de ta ville et pour là reconnaître que ses serviteurs sont venus près de toi?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Anan saisit donc les serviteurs de David; il leur rasa la barbe; il coupa leurs manteaux, depuis le milieu du corps jusqu\'aux pieds; puis, il les chassa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'On vint dire à David ce qui leur était arrivé, et il envoya des gens à leur rencontre; car ils étaient cruellement déshonorés, et il leur dit: Demeurez à Jéricho jusqu\'à ce que votre barbe ait repoussé; puis, alors vous reviendrez.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Les fils d\'Ammon, voyant que le peuple d\'Israël se tenait pour outragé, Anan et les fils d\'Ammon envoyèrent mille talents d\'argent pour enrôler des chars et des cavaliers dans la Syrie de Mésopotamie, dans la Syrie Maacha et à Sobal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Ils enrôlèrent ainsi pour eux trente-deux mille chars, et le roi de Maacha avec tout son peuple. Ces auxiliaires vinrent, et ils campèrent vis-à-vis Médaba. Cependant, les fils d\'Ammon, sortant de leurs villes, se rassemblèrent, et ils s\'ébranlèrent pour combattre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'David l\'apprit, et il mit en mouvement Joab avec toute l\'armée des hommes vaillants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Et les fils d\'Ammon sortirent, et ils se rangèrent en bataille près des portes de la ville, et les rois leurs alliés campèrent, chacun de son côté, dans la campagne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Joab reconnut qu\'il aurait à livrer bataille devant son front et sur ses derrières; il rangea donc en face des Syriens les plus vaillants des jeunes fils d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Et il confia à son frère Abessa le reste de l\'armée, qui se déploya devant les fils d\'Ammon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Et il dit à son frère: Si le Syrien l\'emporte sur moi, tu viendras à mon aide, et si les fils d\'Ammon te font plier, j\'irai te secourir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Sois fort, agis en homme, pour l\'amour de notre peuple et pour les villes de notre Dieu; que le Seigneur ensuite fasse à sa volonté.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Et Joab avec sa troupe tomba sur les Syriens; et ceux-ci s\'enfuirent devant lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Quand les fils d\'Ammon virent que les Syriens fuyaient, ils s\'enfuirent eux-mêmes devant Abessa; et ils s\'enfermèrent dans leur ville, et Joab revint à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Et le Syrien, voyant qu\'Israël l\'avait mis en fuite, envoya des messagers qui levèrent toute la Syrie des rives du Jourdain, et à sa tête Sophath (Sobac), général en chef de l\'armée d\'Adraazar.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'On en instruisit David; il réunit tout Israël, passa le Jourdain, les atteignit et les aborda de front; aussitôt la bataille s\'engagea.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Les Syriens s\'enfuirent devant Israël; David leur tua sept mille hommes montés sur des chars, et quarante mille piétons; Sophath, le général en chef, périt.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Et tous les serviteurs d\'Adraazar, voyant qu\'ils avaient échoué devant Israël, traitèrent avec David, et ils lui furent asservis. Quant au Syrien, il ne voulut plus secourir les fils d\'Ammon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Le cours de l\'année ramena le temps où les rois se mettent en campagne. Joab emmena toutes les forces de l\'armée, et il ravagea la contrée des fils d\'Ammon; il assiégea ensuite Rhabba, pendant que David était resté à Jérusalem; Joab prit Rhabba (Rabbath), et la détruisit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Et David prit sur la tête du roi Molchom sa couronne, qui pesait un talent d\'or, et qui était ornée de pierres précieuses; elle allait à la tête de David; enfin, il rapporta de cette ville un immense butin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Et il emmena tout le peuple qui l\'habitait, et il l\'extermina en plaçant les uns sous des scies, les autres sous des haches de fer, d\'autres sous la cognée du bûcheron. Ce fut ainsi que David traita tous les fils d\'Ammon, et David et tout le peuple retournèrent à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Ensuite, la guerre recommença avec les Philistins de Gazer. Alors, Sobochaï le Sasathite tua Saphut, de la race des géants, après l\'avoir humilié.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Et il y eut une autre guerre avec les Philistins; et Eléanan, fils de Jaïr, tua Lachmi, frère de Goliath de Geth, qui portait une lance comme le mât d\'un tisserand.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Et il y eut encore une guerre avec Geth. Or, il y avait un homme de grande taille, issu des géants, et qui avait vingt-quatre doigts, six à chaque main, et six à chaque pied.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Et il insulta Israël; et Jonathas, dis de Semas, frère de David, le tua. Ces hommes étaient de la race de Rhapha de Geth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ils étaient quatre, tous géants, et ils tombèrent sous les coups de David et de ses serviteurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Et le diable se leva contre Israël; il excita le roi David à faire le dénombrement du peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Le roi dit donc à Joab et aux chefs de l\'armée: Allez et faites le dénombrement d\'Israël, depuis Dan jusqu\'à Bersabée; puis, rapportez-le-moi, et je saurai leur nombre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab répondit: Puisse le Seigneur ajouter à son peuple et le rendre cent fois aussi nombreux qu\'il l\'est, et puisse le roi mon maître le voir de ses yeux; puissent le voir aussi les serviteurs de mon maître; mais pourquoi mon maître a-t-il formé ce dessein? Est-ce pour qu\'il soit imputé à péché au peuple d\'Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Mais, la volonté du roi prévalut sur Joab, et Joab partit, et il parcourut tout Israël, et il revint à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Et Joab remit à David le dénombrement du peuple qu\'il avait recensé: il y avait en tout Israël onze cent mille hommes tirant l\'épée, et en Juda étaient quatre cent soixante-dix mille hommes tirant l\'épée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Et Joab n\'avait compté ni Lévi, ni Benjamin, parce qu\'il avait cédé à contre-cœur au roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Et la chose fut mauvaise devant Dieu, et il frappa Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Et David dit à Dieu: J\'ai gravement péché en ce que je viens de faire, et maintenant remettez à votre serviteur son iniquité, car j\'ai commis une insigne folie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Et le Seigneur parla à Gad le voyant, et il lui dit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Pars et adresse-toi à David, disant: Voici ce que dit le Seigneur: Je t\'apporte trois choses; choisis pour toi l\'une d\'elles, et tu l\'auras.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Gad alla trouver David, et il lui dit: Voici ce que dit le Seigneur: Choisis pour toi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Ou trois ans de famine, ou trois mois pendant lesquels tu fuiras devant tes ennemis qui te détruiront par le glaive, ou trois jours de mort causée par l\'épée du Seigneur en toute cette terre, et par l\'ange exterminateur parcourant tout l\'héritage d\'Israël: vois donc ce que je dois répondre à Celui qui m\'envoie te répéter sa parole.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Et David dit à Gad: Le choix des trois parts m\'est cruel; mais j\'aime mieux me livrer aux mains du Seigneur, parce qu\'il a eu souvent compassion de moi; je ne tomberai point dans les mains des hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Et le Seigneur envoya la mort en Israël, et soixante-dix mille hommes d\'Israël périrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Le Seigneur envoya aussi l\'ange à Jérusalem pour l\'exterminer, et comme il frappait, le Seigneur le vit et se repentit de tout ce mal, et il dit à l\'ange exterminateur: C\'est assez, arrête ta main. Or, l\'ange du Seigneur était auprès de l\'aire d\'Orna le Jébuséen.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'David, ayant levé les yeux, vit l\'ange du Seigneur se tenant entre la terre et le ciel; il avait à la main son épée nue, et il l\'étendait sur Jérusalem. Et David et les anciens couverts de cilices tombèrent la face contre terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Et David dit à Dieu: N\'est-ce pas moi qui ai prescrit de faire le dénombrement du peuple? C\'est moi qui suis le coupable; j\'ai grandement péché. Mais ces brebis qu\'ont-elles fait? Seigneur mon Dieu, que votre main soit contre moi et contre la maison de mon père; qu\'elle épargne ce peuple qui périt, ô Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Et l\'ange du Seigneur dit à Gad de prescrire à David qu\'il allât élever un autel au Seigneur dans l\'aire d\'Orna le Jébuséen.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Et David sortit, selon la parole que Gad lui avait dite au nom du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Et Orna se retourna, et il vit le roi et quatre de ses fils, tous se cachant, et Orna était à vanner du froment.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Et David arriva auprès d\'Orna, et Orna, quittant l\'aire, se prosterna la face contre terre devant David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Et David dit à Orna: Donne-moi l\'emplacement de ton aire, et j\'y bâtirai un autel au Seigneur; donne-le-moi à prix d\'argent, et le fléau cessera de frapper le peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Et Orna dit à David: Que le roi mon maître prenne et consacre ce que bon lui semble. Voici mes bœufs pour l\'holocauste, ma charrue pour le briller, et mon blé pour le sacrifice; je te donne tout.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Et le roi David dit à Orna: Nullement; certes, j\'achèterai toutes ces choses, car elles valent de l\'argent; je ne prendrai, pour le Seigneur, rien de ce qui est à toi; je ne présenterai pas au Seigneur un holocauste qui ne me coûte rien.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'David donna donc à Orna, pour son terrain, six cents sicles d\'or, au poids du sicle du sanctuaire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Il bâtit l\'autel du Seigneur, sur lequel il offrit des holocaustes et des hosties pacifiques; enfin, il cria au Seigneur, et le Seigneur l\'exauça; le feu du ciel, descendant sur l\'autel de l\'holocauste, consuma la victime.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Et le Seigneur parla à l\'ange, et l\'ange remit l\'épée dans le fourreau.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Dès lors, David, ayant vu que le Seigneur lui répondait dans l\'aire d\'Orna le Jébuséen, en fit un lieu de sacrifices.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Or, en ce temps-là, le tabernacle du Seigneur que Moïse avait fait dans le désert, et l\'autel des holocaustes, étaient sur le haut lieu de Gabaon. Par crainte de l\'ange exterminateur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Et David n\'avait pu s\'y transporter pour prier le Seigneur; il ne s\'était point empressé d\'y aller, à cause de l\'épée de l\'ange du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Et David dit: C\'est ici la maison du Seigneur, et voici l\'autel des holocaustes pour Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Puis, il ordonna de réunir tous les étrangers qui se trouvaient en la terre d\'Israël, et il chargea des tailleurs de pierres de tailler des pierres, pour bâtir la maison de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Et David prépara beaucoup de fer, des clous pour les portes et leurs vantaux, des gonds et une quantité d\'airain d\'un poids incalculable,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Et un nombre infini de cèdres que les Tyriens et les Sidoniens lui apportèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Et David dit: Mon fils Salomon est d\'âge tendre, et la maison qui doit être bâtie au Seigneur surpassera en magnificence, en renom et en gloire, toutes celles de la terre; je préparerai tout pour cela. Et David fit ses apprêts à profusion avant de mourir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Et il appela Salomon, son fils, et il lui ordonna de bâtir le temple du Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Et David dit à Salomon: Enfant, mon âme a voulu bâtir un temple au nom du Seigneur Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Mais la parole du Seigneur est venue à moi, disant: Tu as versé beaucoup de sang, tu as fait de grandes guerres; tu ne bâtiras point un temple à mon nom, parce que, devant moi, tu as répandu beaucoup de sang sur cette terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Voici qu\'un fils t\'est né; celui-là sera un homme de paix, et je le maintiendrai en paix avec tous les ennemis qui l\'entourent; car son nom est Salomon, et j\'accorderai, pendant sa vie, le repos et la paix à Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'C\'est lui qui bâtira un temple à mon nom, et il sera pour moi un fils, et moi je serai pour lui un père, et je dresserai son trône royal en Israël pour toujours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Maintenant, mon fils, le Seigneur sera avec toi; il te fera prospérer, et tu bâtiras le temple du Seigneur ton Dieu, comme il me l\'a fait savoir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Que le Seigneur te donne seulement l\'intelligence et la sagesse, et il t\'affermira sur Israël, pour que tu observes et que tu mettes en pratique la loi du Seigneur ton Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Alors, il te fera prospérer, si tu veilles à observer les commandements et les préceptes que le Seigneur a donnés au peuple par la voix de Moïse. Sois fort, et agis en homme; n\'aie ni crainte ni faiblesse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Vois, dans ma pauvreté, j\'ai préparé pour la maison du Seigneur: cent mille talents d\'or, un million de talents d\'argent, de l\'airain et du fer en telle abondance, qu\'on n\'en peut dire le compte. J\'ai aussi préparé des bois et des pierres, et tu y ajouteras encore,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Et tu t\'adjoindras une multitude d\'ouvriers, artisans, tailleurs de pierres, charpentiers, et tout homme habile à mettre en œuvre');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'L\'or, l\'argent, et une masse innombrable d\'airain et de fer. Courage donc, et agis, le Seigneur sera avec toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Ensuite, David ordonna à tous les chefs d\'Israël de seconder Salomon, son fils, et il leur dit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Le Seigneur n\'est-il pas avec vous? Il vous a donné le repos tout alentour; il vous a livré ceux qui habitaient la terre promise, et la terre s\'est soumise devant le Seigneur et devant son peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Appliquez-vous donc, cœur et âme, à chercher le Seigneur, excitez-vous, et bâtissez pour votre Dieu un lieu saint, afin d\'y transporter l\'arche de l\'alliance du Seigneur, avec les vases et les ornements consacrés à Dieu, qui résideront dans le temple élevé au nom du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Or, David était vieux et plein de jours, et il proclama roi à sa place son fils Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Il rassembla tous les chefs d\'Israël, les prêtres et les lévites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Les lévites de trente ans et au-dessus furent comptés, et il s\'en trouva trente-huit mille, savoir:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Vingt-quatre mille employés aux travaux du tabernacle du Seigneur, six mille scribes et juges;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Quatre mille portiers, et quatre mille chantres louant le Seigneur au son des instruments qu\'avait faits David pour accompagner ses louanges.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'David les divisa, et il assigna leurs jours de service aux fils de Lévi, aux familles de Gerson, Caath et Mérari.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Fils de Gerson: Edan et Sémeï.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Fils d\'Edan: Jehiel le premier, et Zêthan et Johel: trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Fils de Sémeï: Salomith, Jehiel et Dan. Tels sont les trois chefs des familles d\'Edan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Fils de Sémeï: Jeth, Ziza, Joas et Beria. Tels sont les quatre fils de Sémei.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jeth était le premier, et Ziza le second; Joas et Beria n\'eurent pas beaucoup d\'enfants, et ils ne formèrent qu\'une famille en une seule maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Fils de Caath: Amram, Isaar, Hébron, Oziel: quatre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Fils d\'Amram: Aaron et Moïse, et Aaron fut désigné pour servir dans le Saint des saints, lui et ses fils, à perpétuité, pour faire les sacrifices devant le Seigneur, pour servir et prier en son nom à perpétuité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Quant à Moïse, l\'homme de Dieu, ses fils furent comptés dans la tribu de Lévi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Fils de Moïse: Gersam et Eliézer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Fils de Gersam: Sobahel le premier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Eliézer eut aussi des enfants: Rabia fut le premier, et Eliézer n\'eut pas d\'autres fils; mais les fils de Rabia multiplièrent extrêmement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Fils d\'Isaar: Salomoth le premier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Fils d\'Hébron: Jeria le premier, Amaria le second, Jéziel le troisième, Jécémias le quatrième.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Fils d\'Oziel: Micha le premier, Isia le second.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Fils de Mérari: Mooli et Musi. Fils de Mooli: Eléazar et Cis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eléazar mourut, et il n\'avait point de fils, mais des filles, et les fils de Cis, leurs frères, les prirent pour femmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Fils de Musi: Mooli, et Eder, et Jarimoth; trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Tels furent les fils de Lévi, par familles paternelles, chefs de leurs familles, selon le recensement par noms et par têtes, faisant le service du tabernacle du Seigneur, Agés de trente ans et au-dessus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Or, David dit: Le Seigneur Dieu d\'Israël a donné le repos à son peuple, et il a choisi Jérusalem pour sa demeure à jamais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Les lévites n\'avaient donc plus dans leur service le transport du tabernacle et de ses ornements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Et, selon les dernières paroles de David, le dénombrement des fils de Lévi, âgés de trente ans et au-dessus, avait été fait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Et, d\'après Aaron, il avait réglé les emplois dans la demeure du Seigneur, tant dans les parvis que dans les chambres, et pour ce qui concernait la purification du Saint des saints, et les autres services du tabernacle,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Et les pains de proposition, et la fleur de farine des sacrifices, et les poêles à cuire les azymes, et la pâte, et les mesures,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Et les louanges du Seigneur qu\'on devait chanter du matin au soir,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Et tous les holocaustes à offrir au Seigneur, tant les jours de sabbat qu\'aux nouvelles lunes et aux fêtes, selon le nombre et les usages invariables, devant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Et il était prescrit aux lévites de garder le tabernacle du témoignage, et le Saint des saints, et les fils d\'Aaron leurs frères, pendant leur service dans le tabernacle du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Et les fils d\'Aaron étaient: Nadab, Abiud, Eléazar et Ithamar.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Or, Nadab et Abiud moururent sous les yeux de leur père, et ils n\'avaient point de fils; Eléazar et Ithamar, fils d\'Aaron, eurent donc le sacerdoce.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Et David distingua les fils d\'Eléazar, de qui descendait Sadoc, des fils d\'Ithamar, de qui était issu Achimélech, selon leur recensement, et leurs services, et leurs familles paternelles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Et il se trouva, parmi ces hommes forts, plus de chefs des fils d\'Eléazar que des fils d\'Ithamar, et David mit les premiers à la tête de seize familles, les seconds à la tête de huit familles seulement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Et il leur distribua leurs services par le sort; car, parmi les uns comme parmi les autres, il y avait des chefs des choses saintes, et des chefs du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Et le scribe Samaïas, fils de Nathanakl de la tribu de Lévi, écrivit la liste en présence du roi et des chefs, aidé de Sadoc le prêtre, et d\'Abimélech, fils d\'Abiathar, et des chefs des familles paternelles des prêtres et des lévites, inscrivant tour à tour un nom provenant d\'Eléazar, un nom provenant d\'Ithamar.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Le sort désigna en premier lieu Joarim; le second fut Jedia,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Le troisième Harib, le quatrième Séorim,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Le cinquième Melchias, le sixième Meïamin,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Le septième Cos, le huitième Abias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Le neuvième Jésua, le dixième Sechénias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Le onzième Eliabi, le douzième Jacim,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Le treizième Opha, le quatorzième Jezbaal,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Le quinzième Belga, le seizième Hemmer,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Le dix-septième Hézin, le dix-huitième Aphésé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Le dix-neuvième Phetaïe, le vingtième Ezecel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Le vingt et unième Achim, le vingt-deuxième Gamul,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Le vingt-troisième Abdallé, le vingt-quatrième Maasé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Tel fut leur recensement, selon leurs services, pour pénétrer dans le tabernacle du Seigneur, d\'après le règlement d\'Aaron, leur père, tel que le Seigneur l\'avait prescrit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Voici le reste des fils de Lévi: Fils d\'Amram: Sobael. Fils de Sobael: Jedia.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Le chef des fils de Raabia:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Salomoth, fils de Isaar; Jath, des fils de Salomoth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Les fils d\'Ecdiu: Amadias le second, Jaziel le troisième, Jecmoam le quatrième.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Des fils d\'Oziel: Micha. Des fils de Micha: Samer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Le frère de Micha: Isia. Fils de Micha: Zacharie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Les descendants des fils de Mérari: Mooli et Musi. Les fils d\'Ozia.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Fils de Mérari: Joram, et Sacchur, et Abaï.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Mooli avait eu encore Eléazar et Ithamar; mais Eléazar était mort sans laisser de fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Jeraméel, issu des fils de Cis,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Et Mooli, Eder et Jerimoth, issus de Musi. Tels étaient les fils des lévites par familles paternelles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Et ils tirèrent au sort, comme leurs frères les fils d\'Aaron, en présence du roi, de Sadoc, d\'Achimélech, et des chefs de familles des prêtres et des lévites; aussi bien les plus anciens chefs de familles que leurs frères les plus jeunes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Et le roi David et les chefs de l\'armée réglèrent les fonctions des fils d\'Asaph, d\'Hêman et d\'Idithun, chantres, s\'accompagnant de harpes, de lyres et de cymbales, et qui furent employés tour à tour, selon leur nombre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Fils d\'Asaph, attachés à la personne du roi: Sacchur, Joseph, Natharias et Enahel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Fils d\'Idithun: Godolias, Suri, Iséas, Asabias et Matthathias; six, en comptant leur père Idithun, s\'accompagnant de la harpe, et louant le Seigneur en lui rendant grâces.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Fils d\'Hêman: Bucias, Matthanias, Oziel, Subahel, Jerimoth, Ananias, Anan, Eliatha, Godollathi, Hornetthiézer, Jesbasaca, Mallithi, Otheri et Méasoth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Tous fils d\'Hêman, premier chantre du roi pour louer Dieu et exalter sa puissance. Ainsi, Dieu avait donné à Hêman quatorze fils, outre trois filles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Tous ses fils chantaient avec lui dans le tabernacle de Dieu, en s\'accompagnant de harpes, de lyres et de cymbales; ils servaient en la demeure de Dieu, attachés à la personne du roi, ainsi qu\'Asaph, Idithun et Hêman.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Et leur nombre, joint à celui de leurs frères, instruits à chanter le Seigneur, montait à deux cent quatre-vingt-huit, tout compris.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Et ils réglèrent aussi, par le sort, leur service journalier, après qu\'ils furent classés, selon leur plus ou moins de science et de talent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Et le sort désigna, en premier lieu: Godolias, fils de Joseph, fils d\'Asaph, et ses fils et ses frères; le second fut l\'émail, et ses fils et ses frères, au nombre de douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Le troisième Sacchur, et ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Le quatrième Jesri, et ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Le cinquième Nathan, et ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Le sixième Bucias, et ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Le septième Izeriel, et ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Le huitième Josias, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Le neuvième Matthanias, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Le dixième Sémeï, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Le onzième Asriel, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Le douzième Asabia, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Le treizième Subahel, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Le quatorzième Matthathias, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Le quinzième Jerimoth, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Le seizième Anania, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Le dix-septième Jesbasaca, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Le dix-huitième Ananias, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Le dix-neuvième Mallithi, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Le vingtième Eliatha, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Le vingt-unième Otheri, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Le vingt-deuxième Godolathi, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Le vingt-troisième Muzoth, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Le vingt-quatrième Rometthiézer, ses fils et ses frères: douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Ceux à qui les portes furent distribuées, étaient les fils de Coré, Mosellamia, de la famille d\'Asaph.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Et les fils de Mosellamia: Zacharie le premier-né, Jadiel le second, Zabadie le troisième, Jénuel le quatrième,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Jolam le cinquième, Jonathan le sixième, Elionai le septième, Abdedom le huitième.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Et les fils d\'Abdedom: Samaias le premier-né, Jozabath le second, Joath le troisième, Sachar le quatrième, Nathanaél le cinquième,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Amiel le sixième, Issachar le septième, Phelathi le huitième; car Dieu l\'avait béni.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Et à son premier fils Samaïas, des fils naquirent, et furent chefs dans leur famille, parce qu\'ils étaient forts');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Fils de Samaï: Otbni, Raphaël, Obed, Elzabath, Achiud, tous hommes forts, Elia, Sabachias et Isbacom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Tous issus d\'Abdedom; eux, et leurs fils et leurs frères, remplissant avec énergie leurs fonctions, au nombre de soixante-deux, issus d\'Abdedom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Mosellemia avait dix-huit fils et frères, tous hommes forts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Et les fils d\'Osa, issu de Mérari, et qui n\'était pas le premier-né, commandaient ce service; son père lui donna le commandement de la deuxième division.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Helcias venait après lui, Tablé était le troisième, Zacharie le quatrième; les fils et les frères d\'Osa étaient en tout: treize.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'C\'est entre eux que furent partagées les portes; chefs énergiques, servant avec autant de zèle que leurs frères, employés dans l\'intérieur du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Et ils tirèrent au sort les portes où ils devaient être placés, après qu\'on les eut classés, selon leur plus ou moins de force, par familles paternelles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Le sort désigna, pour la porte orientale, Sélémie et Zacharie; ensuite, les fils de Soaz, issu de Melchia, agitèrent les sorts, et celui de la porte du nord sortit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Abdedom eut la porte du midi, en face de la maison d\'Esephim.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Osa eut la seconde porte du côté de l\'orient, après celle qui mène au vestibule des degrés; un garde vis-à-vis l\'autre garde.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Il y avait chaque jour six hommes à la porte orientale, quatre à celle du nord, quatre à celle du midi et deux à Esephim,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Pour la relève, du côté du couchant quatre et deux à l\'entrée du chemin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Les portes étaient ainsi distribuées entre les fils dé Coré et ceux de Mérari.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Et des lévites, leurs frères, gardaient le trésor de la demeure du Seigneur et le trésor des consécrations.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Ceux-là étaient fils de Ladan; ils étaient issus des fils de Gerson; les chefs des familles provenaient de Ladan, le fils de Ladan le Gersonite était Jehiel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Zethom et Johel, son frère, fils de Jehiel, étaient intendants du trésor de la demeure du Seigneur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Avec les familles d\'Amram, d\'Issaar, d\'Hébron et d\'Oziel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Subael, issu de Gersam, fils de Moïse, était aussi intendant des trésors.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Or, Eliézer, l\'un de ses proches, eut pour fils Rabias, de qui descendirent: Josias, Joram, Zéchri et Salomoth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ce Salomoth et ses frères eurent l\'intendance de tous les trésors saints, que consacrèrent le roi David et les chefs de familles paternelles, commandants de mille hommes, ou centeniers, ou princes de l\'armée;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'C\'étaient les choses qu\'ils avaient enlevées des villes prises sur l\'ennemi, et consacrées pour subvenir aux frais de construction du temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Ainsi, tout ce qu\'avait consacré Samuel le prophète; Saül, fils de Cis; Abner, fils de Ner; Joab, fils de Servie, fut confié à Salomoth et à ses frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Honnias, issu d\'Isaar, et ses fils, furent chargés de fonctions extérieures en Israël; ils étaient scribes et juges.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Asubias, issu d\'Hébron, et ses frères, hommes forts, au nombre de dix- sept cents, avaient la surveillance d\'Israël, sur la rive occidentale du Jourdain, pour tout ce qui concernait le service du Seigneur et le gouvernement du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Urie était le chef de la postérité d\'Hébron, par familles paternelles; or, la quarantième année du règne de David, elle fut recensée en Jazer-Galaad, et Urie fut reconnu vaillant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Ses frères, les chefs de famille, au nombre de deux mille sept cents, étaient aussi des hommes forts; le roi les institua intendants de Ruben, de Gad et de la demi-tribu de Manassé, pour tout ce qui concernait les commandements du Seigneur et les ordres du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Et, pendant le cours de l\'année, de mois en mois, une division de vingt- quatre mille hommes, prise parmi tous les fils d\'Israël, chefs de familles, commandants de mille hommes, centeniers, scribes et serviteurs, était employée à exécuter les ordres du roi; chaque division était relevée à son tour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'A la tête de la première division employée le premier mois était Isboaz, fils de Zabdiel; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Il était issu de Pharès, et comme chef de tous les chefs de l\'armée, il commandait pendant le premier mois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'A la tête de la division du second mois était Dodia, fils d\'Eccoc, et il y avait encore pour chef de cette division Maceloth; ils étaient chefs de vingt- quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Banaïas, fils de Joad le prêtre, était le troisième chef, il commandait la division du troisième mois, pareillement vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ce Banaïas était le plus vaillant des trente; il était à leur tête, et son fils Zabad commandait avec lui sa division.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Le quatrième, celui du quatrième mois, était Asaël, frère de Joab, et son fils Zabadie; ses fils et ses frères partageaient son commandement sur vingt- quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Le cinquième chef, celui du cinquième mois, était Samaoth le Jezraïte; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Le sixième, celui du sixième mois, était Oduïas, fils d\'Eccès de Thécoé; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Le septième, celui du septième mois, était Relies de Phallus, des fils d\'Ephrahn; sa division comptait vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Le huitième, celui du huitième mois, était Sohochaï de Husathi, issu de Zara; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Le neuvième, celui du neuvième mois, était Abiézer d\'Anathoth, de la terre de Benjamin; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Le dixième, celui du dixième mois, était Méhéra de Netophathi, issu de Zara; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Le onzième, celui du onzième mois, était Baillas de Pharathon, des fils d\'Ephraïm; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Le douzième, celui du douzième mois, était Holdia de Netophathi, issu d\'Othoniel; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Et il y avait des chefs à la tête de claque tribu; celui de Ruben était Eliézer, fils de Zéchri; celui de Siméon, Saphatias, fils de Maacha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Celui de Lévi, Asabias, fils de Camuel; Sadoc était chef de la famille d\'Aaron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Le chef de Juda était Eliab, l\'un des frères de David; celui d\'Issachar Ambri, fils de Michel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Celui de Zabulon, Samain, fils d\'Abdiu; celui de Nephthali: Jerimoth, fils d\'Oziel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Celui d\'Ephraïm, Osé, fils d\'Oziu; celui de la demi-tribu de Manassé: Johel, fils de Phadaïa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Celui de l\'autre demi-tribu de Manassé, en Galaad, Jadaï, fils de Zadaïu; celui de Benjamin, Jasiel, fils d\'Abner.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Celui de Dan: Azariel, fils de Iroab; tels étaient les chefs de familles des tribus d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Et David ne fit point le dénombrement de ceux de vingt ans et au-dessous, car le Seigneur lui avait dit qu\'il multiplierait Israël comme les étoiles du ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Et Joab, fils de Sarvia, avait commencé le dénombrement du peuple, mais il ne l\'acheva point; et ce dénombrement causa la colère qui éclata contre Israël, et le nombre que l\'on avait trouvé fut supprimé du livre des faits et gestes du roi David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Asmoth, fils d\'Adaël, fut trésorier du roi, et Jonathas, fils d\'Ozia, trésorier de la contrée, des villes, des villages et des tours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Esdri, fils d\'Hélab, avait l\'intendance des laboureurs et ouvriers travaillant à la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Semei de Rahel, celle des champs; Zabni, fils de Jephni, celle des vignes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Balanan le Gedorite, celle des oliviers et des figuiers des champs; Joas, celle de l\'huile.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Satrai le Saronite, celle des bœufs qui paissaient en Saron; et Sophat, fils d\'Abdi, celle des bœufs à l\'étable.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Abias, l\'Ismaélite, celle des chameaux; Jadias de Merathon, celle des ânes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Jaziz l\'Agarite, celle des brebis. Tels étaient tous les intendants des domaines du roi David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jonathas, oncle paternel de David, était conseiller, homme intelligent; et Jehel, fils d\'Achami, était avec les fils du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achitophel était conseiller du roi, et Chusi son principal favori.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Après lui venaient Achitophel, Joad, fils de Banaïas et Abiathar. Joab était le général en chef du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Et David rassembla en Jérusalem tous les chefs d\'Israël, les chefs des juges, tous les chefs des gardes qui tour à tour veillaient à la personne du roi, les commandants de mille hommes, les centeniers, les trésoriers, les intendants de ses domaines, ceux des troupeaux du roi, les gouverneurs de ses fils, les eunuques, les vaillants et les guerriers de l\'armée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Et David se plaça au milieu de l\'assemblée, et il dit: Écoutez-moi, mes frères et mon peuple: J\'ai eu le dessein de bâtir une maison de repos, pour l\'arche de l\'alliance un lieu du Seigneur, où notre Seigneur arrête ses pas; j\'ai préparé ce qui convient pour cette construction.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Mais Dieu a dit: Tu ne bâtiras pas un temple où mon nom soit invoqué, parce que tu es un homme de guerre, et que tu as versé le sang.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Le Seigneur Dieu d\'Israël m\'a choisi dans la maison de mon père pour être à jamais roi d\'Israël, et il a choisi Juda pour sa tribu royale; dans Juda il a choisi la maison de mon père; et, parmi les fils de mon père, il a voulu que je fusse roi de tout Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Et, parmi tous mes fils, car le Seigneur m\'en a accordé un grand nombre, il a choisi Salomon, mon fils, pour l\'asseoir sur le trône du royaume du Seigneur, et pour qu\'il soit roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Et Dieu m\'a dit: Salomon, ton fils, bâtira mon parvis et mon temple; car je l\'ai choisi pour qu\'il soit mon fils, et je serai pour lui un père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Et je maintiendrai, dans tous les siècles, son royaume, s\'il observe sans faiblir, comme il les observe maintenant, mes commandements et mes préceptes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Je vous recommande donc en présence de toute l\'Église du Seigneur, et devant notre Dieu qui nous entend, d\'observer et d\'aimer tous les commandements du Seigneur notre Dieu, afin que vous possédiez cette terre féconde, et que vous en transmettiez l\'héritage à vos fils pour toujours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Et toi, Salomon, mon fils, reconnais le Dieu de tes pères, sers-le d\'un cœur pur et d\'une âme ferme, car le Seigneur sonde tous les cœurs et il connaît toutes les pensées. Si tu le cherches tu le trouveras, et si tu l\'abandonnes il t\'abandonnera pour toujours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Vois aujourd\'hui que le Seigneur t\'a choisi pour que tu lui bâtisses une maison où sera son sanctuaire; sois fort et agis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Ensuite, David donna à Salomon, son fils, le modèle du temple, de ses constructions, de ses trésors, de ses chambres hautes, des logements intérieurs et du propitiatoire,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Et le plan, qu\'il avait eu en l\'esprit, du parvis du temple du Seigneur, de tous les vestibules d\'alentour communiquant aux trésors, des trésors, des choses saintes et des chambres secrètes,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Et le règlement du service journalier des prêtres et des lévites, pour toutes leurs œuvres liturgiques dans le temple du Seigneur, et des trésors où seraient déposés les vases liturgiques employés aux cérémonies du culte dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Et il donna le poids des vases d\'or et d\'argent,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Des lampes et des chandeliers,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Il donna pareillement le poids des tables de proposition, de chaque table d\'or, et de chaque table d\'argent,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Et des fourchettes, et des coupes à libations, et des fioles d\'or, et des encensoirs, et d\'autres objets d\'or et d\'argent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Il lui montra aussi le poids, en or pur, de toutes les parties de l\'autel des parfums, et le modèle du char des deux chérubins aux ailes déployées, qui devaient ombrager l\'arche de l\'alliance du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'David donna tout cela à Salomon en écriture de la main du Seigneur, avec la sagesse dont il fut assisté pour réaliser le modèle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Et David dit à Salomon, son fils: Sois fort, agis en homme, exécute, n\'aie ni crainte, ni faiblesse; car le Seigneur Dieu est avec toi; il ne te négligera pas, il ne t\'abandonnera point que tu n\'aies terminé toute l\'œuvre destinée au service de son temple. Voici le modèle de sa nef et de son temple, de son trésor, des chambres hautes, des logements intérieurs et du propitiatoire; voici le plan du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Voici encore l\'ordre des fonctions journalières des prêtres et des lévites, dans tout le service du temple du Seigneur; et tu seras assisté en ton œuvre par chaque homme zélé et habile en quelque art, et les princes et tout le peuple exécuteront tous tes commandements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Et le roi David dit à toute l\'Église: Mon fils Salomon, en qui le Seigneur s\'est complu, est jeune et délicat, et l\'œuvre est grande, car elle n\'est point pour l\'homme, mais pour le Seigneur Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Autant que je l\'ai pu, j\'ai préparé pour le temple de mon Dieu: de l\'or, de l\'argent, de l\'airain, du fer, des bois, des pierres d\'onyx, quantité de pierres chères et variées, toutes sortes de pierres précieuses, et beaucoup de marbre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'De plus, comme je mets ma joie en la demeure de mon Dieu, j\'ai conservé l\'or et l\'argent que je me suis procuré pour moi-même; je le donne entièrement au temple de mon Dieu, outre ce que j\'ai amassé pour la maison des choses saintes, savoir:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Trois mille talents d\'or d\'Ophir, et sept mille talents d\'argent pur, pour que l\'on en recouvre les murs du lieu saint.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Il y aura ce qu\'il faut à la main de l\'artisan. Mais est-il quelqu\'un qui désire aujourd\'hui remplir ses mains pour le Seigneur?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Et les princes des familles le désirèrent, les princes des fils d\'Israël ainsi que les commandants de mille hommes, et les centeniers, et les intendants des travaux, et les architectes du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Et ils donnèrent pour les travaux du temple du Seigneur: cinq mille talents et dix mille sicles d\'or; dix mille talents d\'argent; dix-huit mille talents d\'airain et cent mille talents de fer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Et celui chez qui il se trouva quelque pierre précieuse, la donna pour le trésor du temple par les mains de Dehiel, de la famille de Gerson.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Et le peuple eut une grande joie à cause de ce zèle, car chacun eut ce zèle pour Dieu de plein cœur. Et le roi David fut comblé de joie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Et le roi David bénit le Seigneur devant toute l\'Église, disant: Béni soyez-vous, Seigneur Dieu d\'Israël, ô notre Père, dans tous les siècles des siècles!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'A vous, Seigneur, la magnificence, la force, la gloire, la victoire et la puissance; car vous êtes le maître de toutes les choses qui sont sur la terre et dans les cieux. Tous les rois des nations sont troublés devant vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'De vous viennent gloire et richesse; vous régnez sur toutes choses, ô Seigneur, prince de toutes les dominations; la force et le pouvoir résident en vos mains, et il dépend de vous, ô Tout-Puissant, de grandir et de fortifier toutes choses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Et maintenant, Seigneur, nous vous rendons hommage, nous louons votre nom et votre gloire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Et qui suis-je, moi, et qui est mon peuple, pour que nous ayons pu vous faire ces offrandes avec tant de zèle? Tout est à vous, et nous vous avons donné de ce qui vous appartient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Car nous sommes des passagers devant vous, et Nous passons comme tous nos pères; nos jours sur la terre sont comme l\'ombre, et rien n\'a de la durée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Seigneur notre Dieu, toutes les richesses que j\'ai préparées pour bâtir un temple à votre saint nom, viennent de vous; tout cela vous appartient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Et j\'ai reconnu, ô mon Dieu, que c\'est vous qui sondez les cœurs et que vous aimez la justice; et je vous ai fait mes offrandes dans la simplicité de mon cœur, et je viens de voir ici avec joie ce peuple mettre tant de zèle à vous faire ses offrandes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Seigneur Dieu d\'Abraham, d\'Isaac et d\'Israël nos pères, faites que votre peuple conserve toujours en son cœur le même amour, et dirigez son cœur vers vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Et donnez à mon fils Salomon un bon cœur pour exécuter vos commandements, pour être attentif à vos ordres et à vos témoignages, et pour conduire jusqu\'à la fin la construction de votre temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Et David dit à toute l\'Église: Bénissez le Seigneur notre Dieu. Et toute l\'Église bénit le Seigneur Dieu de leurs pères; ils plièrent les genoux et ils adorèrent le Seigneur et le roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Et David sacrifia au Seigneur; il offrit en holocauste à Dieu, dès le matin du jour suivant: mille bœufs, mille béliers, mille agneaux; il fit leurs libations, et il distribua des victimes en abondance à tout Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Et ils mangèrent, et ils burent avec joie devant le Seigneur toute la journée, et, pour la seconde fois, ils proclamèrent roi Salomon, fils de David; ils le sacrèrent roi devant le Seigneur, et ils sacrèrent Sadoc comme pontife.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Et Salomon s\'assit sur le trône de David son père; il fut honoré, et tout Israël lui obéit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Les princes, les vaillants, et tous les fils du roi David son père, se soumirent à sa puissance.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Et le Seigneur éleva Salomon au-dessus de tout Israël, il lui donna plus de gloire qu\'à nul des rois qui l\'avaient devancé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Or, David, fils de Jessé, avait régné sur Israël');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Quarante ans: sept à Hébron, trente-trois à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Et il finit en une heureuse vieillesse, plein de jours, de richesses et de gloire, et son fils Salomon régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Le reste des discours du roi David, ses premières et ses dernières paroles, sont écrits parmi les Récits de Samuel le voyant, de Nathan le prophète, et de Gad le voyant,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Concernant tout son règne, ses guerres et les événements arrivés tant à lui qu\'à Israël, et en tous les royaumes de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Et Salomon, fils de David, s\'affermit sur son trône; le Seigneur Dieu était avec lui, et il l\'éleva au comble des grandeurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Et Salomon parla à tout Israël, aux commandants de mille hommes, aux centeniers, aux juges, à tous les princes d\'Israël et aux princes de sa famille.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Et il alla avec toute l\'Église au lieu haut de Gabaon, où était le tabernacle du témoignage de Dieu, que Moïse serviteur de Dieu avait fait dans le désert.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Quant à l\'arche de Dieu, David l\'avait retirée de Cariathiarim, parce qu\'il lui avait préparé et dressé un tabernacle à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Mais l\'autel d\'airain qu\'avait fait Béséléel, fils d\'Urias, fils de Hur, était à Gabaon devant le tabernacle du Seigneur, et c\'est là que Salomon avec toute l\'Église alla interroger Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Et Salomon sacrifia sur l\'autel d\'airain devant le tabernacle du Seigneur; il y offrit un holocauste de mille victimes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'En cette nuit-là, le Seigneur apparut à Salomon, et il lui dit: Demande ce que tu veux que je te donne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Et Salomon dit à Dieu: Vous avez usé d\'une grande miséricorde envers David, mon père, et vous m\'avez fait roi à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Et maintenant, Seigneur Dieu, que votre nom soit engagé en faveur de David, mon père. Car, vous m\'avez proclamé roi d\'un peuple aussi nombreux que la poussière des champs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Donnez-moi la sagesse et l\'intelligence, pour que je puisse bien agir devant ce peuple; car, qui jugera votre grand peuple?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Et Dieu dit à Salomon: En récompense de ce que cela était en ton cœur, et que tu ne m\'as demandé ni richesses, ni gloire, ni la mort de tes ennemis, ni de longs jours, mais que tu m\'as demandé la sagesse et l\'intelligence, afin de juger mon peuple sur qui je t\'ai établi roi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Je te donne la sagesse et l\'intelligence, et je te donnerai la richesse et la gloire, tellement que ton pareil n\'a pas existé parmi les rois qui t\'ont devancé, et n\'existera pas parmi ceux qui te succèderont.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Et Salomon s\'en alla du haut lieu de Gabaon où était le tabernacle du témoignage, pour retourner à Jérusalem, et il régna sur Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Ensuite, Salomon rassembla ses chars et ses cavaliers; il eut quatorze cents chars et douze mille cavaliers; il laissa les chars dans les villes, mais la troupe demeura avec le roi à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Et le roi rendit à Jérusalem l\'argent et l\'or aussi communs que les pierres, et les cèdres en Judée aussi nombreux que les mûriers dans les champs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Salomon tirait des chevaux de l\'Égypte; des marchands partaient par ses ordres, ayant été chargés de les lui acheter,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Et ils revenaient, et ils ramenaient de l\'Égypte: un char moyennant six cents sicles d\'argent; un cheval moyennant cent cinquante sicles. Et il en était de même pour ce qu\'ils achetaient des rois des Hettéens ou de la Syrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 18, 'Et Salomon ordonna que l\'on bâtit un temple au nom du Seigneur; puis, pour lui-même, une demeure royale.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Il réunit soixante-dix mille manœuvres, quatre-vingt mille tailleurs de pierres qu\'il envoya dans la montagne, et trois mille six cents conducteurs de leurs travaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Il dépêcha des messagers à Hiram, roi de Tyr, disant: Tu en as bien usé avec David, mon père, tu lui as envoyé des cèdres pour bâtir le palais qu\'il devait habiter.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Or, voici que moi son fils, je bâtis un temple au nom du Seigneur mon Dieu, pour le lui consacrer, pour y brûler devant lui de l\'encens, pour y exposer toujours les pains de proposition, pour y offrir les holocaustes du matin et du soir, ceux des sabbats, des nouvelles lunes, et des fêtes du Seigneur notre Dieu à perpétuité en Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Le temple que je bâtis sera grand, parce que le Seigneur notre Dieu est grand plus que tous les dieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Mais, qui donc peut lui élever un temple? Car le ciel et le ciel des cieux ne contiennent pas sa gloire. Et moi, qui suis-je pour lui bâtir un temple, si ce n\'est seulement pour sacrifier devant lui?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Envoie-moi donc un homme adroit et instruit à façonner l\'or, l\'argent, l\'airain, le fer, le porphyre, l\'hyacinthe et l\'écarlate; et quelqu\'un sachant sculpter et ciseler, avec les gens habiles que j\'ai auprès de moi à Jérusalem, et qu\'a formés David mon père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Envoie-moi aussi des bois de cèdre, de genièvre et de pin du Liban, car je n\'ignore pas comment tes serviteurs savent équarrir les arbres du Liban. Et tes serviteurs, avec les miens,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Iront me préparer de la charpente en quantité, parce que la maison que je bâtis sera grande et magnifique.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'A tes serviteurs les charpentiers, je donne gratuitement pour leur nourriture: vingt mille mesures de froment, vingt mille mesures d\'orge, vingt mille mesures de vin, et vingt mille mesures d\'huile.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Hiram, roi de Tyr, répondit par écrit, et il fit passer sa lettre à Salomon, disant: Le Seigneur aime ton peuple, c\'est pourquoi il t\'a fait régner sur eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Et Hiram ajouta: Béni soit le Seigneur Dieu d\'Israël, qui a créé le ciel et la terre, qui a donné à David un fils sage, plein de savoir et d\'intelligence; c\'est ce fils qui bâtira le temple du Seigneur et son propre palais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Et moi je t\'envoie un homme intelligent et habile, Hiram, mon serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Sa mère est des filles de Dan, et son père un Tyrien; il sait façonner l\'or, l\'argent, l\'airain, le fer, les pierres et le bois; il sait tisser avec le porphyre, l\'hyacinthe, le lin et l\'écarlate; il sait sculpter et ciseler; il n\'est rien qu\'il ne sache inventer; il exécutera tout ce que tu lui commanderas, aidé de tes hommes habiles, et des hommes habiles de mon seigneur David, ton père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Quant aux vivres, à l\'orge, à l\'huile, au vin dont a parlé mon seigneur, qu\'il les envoie à ses serviteurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Et nous, nous équarrirons des arbres du Liban, autant qu\'il en faudra; nous en ferons des radeaux que nous conduirons par mer à Joppé, et tu les transporteras à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Alors, Salomon réunit tous les étrangers qui habitaient la terre d\'Israël, après le dénombrement qu\'avait fait son père David; or, il s\'en trouvait cent cinquante-trois mille six cents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Parmi eux, il prit soixante-dix mille manœuvres, quatre-vingt mille tailleurs de pierres, et trois mille six cents conducteurs des travaux, pour diriger cette multitude.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Et Salomon commença à bâtir le temple du Seigneur à Jérusalem, sur le mont Moria, où le Seigneur était apparu à David, son père, au lieu que David avait préparé, dans l\'aire d\'Orna le Jébuséen.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Il commença à bâtir le second mois de la quatrième année de son règne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Et voici comme Salomon commença à bâtir le temple du Seigneur: il lui donna soixante coudées de longueur (ce fut la première mesure), et vingt coudées de largeur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Le portique de la façade du temple eut vingt coudées de long; c\'était la largeur même de l\'édifice; sa hauteur fut de cent vingt coudées; Hiram le dora avec de l\'or pur, intérieurement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Et il revêtit de lambris de cèdre le corps de l\'édifice, et il le dora d\'or pur, sur lequel il grava des palmiers et des chaînes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Et il orna le temple de pierres précieuses d\'un vif éclat, et il le couvrit de lames d\'or, et il y employa de l\'or de Pharaïm.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Et il dora le temple, ses murs, ses portes, ses plafonds, les battants des portes, et il fit sur les parois des chérubins ciselés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Et il fit le Saint des saints, dont la façade avait vingt coudées de long, largeur du temple et dont les côtés étaient pareillement de vingt coudées; il le dora d\'or pur du poids de six cents talents; pour les chérubins ciselés,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Les clous pesaient chacun cinquante sicles d\'or; il revêtit aussi d\'or l\'étage supérieur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Puis, il fit, dans le Saint des saints, deux chérubins de bois qu\'il revêtit de lames d\'or pur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Les ailes des chérubins avaient un déploiement de vingt coudées; chaque aile était de cinq coudées, de sorte que l\'aile droite de l\'un des chérubins touchait un mur, et l\'aile gauche de l\'autre chérubin touchait le mur opposé; [et son autre aile de cinq coudées touchait l\'aile de l\'autre chérubin.]');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, '[Et l\'aile d\'un chérubin était de cinq coudées atteignant le mur du temple, et son autre aile était aussi de cinq coudées, joignant l\'aile de l\'autre chérubin.]');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Les ailes des deux chérubins étaient donc déployées, et il y avait entre les deux ailes extrêmes une distance de vingt coudées. Ils étaient en pied, le visage tourné vers l\'intérieur du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Il fit aussi un voile d\'hyacinthe, de pourpre, d\'écarlate et de lin, dans lequel étaient tissus des chérubins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Et il fit, devant le temple, deux colonnes, hautes de trente-cinq coudées, avec des chapiteaux de cinq coudées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Et il fit des chaînes dans l\'oracle, et il les plaça sur les chapiteaux des colonnes, et il fit cent petites grenades qu\'il posa sur les chaînes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Et il plaça les colonnes sur la façade du temple, l\'une à droite, l\'autre à gauche, et il appela celle de droite Rectitude, et celle de gauche Force.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Et il fit un autel d\'airain, long de vingt coudées, large de vingt, haut de dix.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Et il fit une mer, jetée en fonte, ronde, haute de cinq coudées, ayant dix coudées de diamètre, et trente coudées de circonférence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Il y avait, au-dessous de ses bords tout alentour, des figures de bœufs, et la piscine avait dix coudées de tour; on avait jeté en fonte deux espèces de bœufs, en deux sortes de moules,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Où on avait fait douze bœufs: trois regardant le nord, trois l\'occident, trois le midi, trois l\'orient; la mer était posée sur eux, et le derrière de leur corps était caché par elle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Elle avait un palme d\'épaisseur, et ses bords étaient comme ceux d\'une coupe, et ciselés de fleurs de lis; elle contenait trois mille mesures; il l\'acheva,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Et il fit dix bassins: il en plaça cinq à droite et cinq à gauche, pour qu\'on y lavât la matière des holocaustes; quant aux prêtres, ils se lavaient dans la mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Et il fit dix chandeliers d\'or, selon le modèle, et il les plaça dans la nef: cinq à droite, cinq à gauche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Et il fit dix tables, et il les plaça dans la nef: cinq à droite, cinq à gauche; et il fit cent fioles d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Il fil aussi le parvis des prêtres, le grand parvis, les portes du parvis, et il revêtit d\'airain leurs panneaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Il plaça la mer du côté droit du temple, vers l\'angle regardant l\'orient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Et Hiram fit les fourchettes, les poêles, la grille de l\'autel et tous ses vases; et il acheva tous les travaux que lui avait commandés le roi Salomon pour le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Il fit deux colonnes, et, sur leurs têtes, des cordons aux chapiteaux, et deux filets pour couvrir les deux chapiteaux des têtes de ces colonnes,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Et quatre cents clochettes d\'or dans les deux filets, et deux sortes de grenades dans chaque filet, pour couvrir les deux chapiteaux des têtes de colonnes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Et il fit dix bassins, et il fit les cuvettes pour les bassins,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Et la mer, et les douze bœufs qui la supportent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Et les vases pour les pieds, les seaux, les marmites, les crochets, et les autres vases qui lui étaient commandés; il les fit en airain pur, et il les apporta au roi dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Le roi les avait jetés en fonte, dans la vallée du Jourdain, en une terre argileuse de la maison de Soccoth, entre cette ville et Saredatha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Et Salomon fit tous ces ustensiles à profusion, car l\'airain ne put être épuisé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Et il fit tous les vaisseaux du temple du Seigneur, l\'autel d\'or, les tables de proposition,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Les chandeliers et les lampes en or pur, qui devaient éclairer la façade de l\'oracle, selon son plan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Il fit leurs mouchettes, leurs récipients, les coupes, les réchauds et les encensoirs, d\'or pur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Et la porte intérieure du temple qui mène au Saint des saints, et les portes d\'or du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 23, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Enfin, tous les travaux qu\'avait commandés Salomon pour le temple du Seigneur, furent achevés. Et Salomon transporta dans le trésor du temple les choses saintes de David son père, et l\'argent et l\'or, et les vaisseaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Alors, Salomon assembla dans Jérusalem tous les anciens du peuple, tous les princes des tribus, les princes des familles paternelles d\'Israël, pour transférer de Sion (la même que la ville de David) l\'arche de l\'alliance du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Et tout Israël fut assemblé devant le roi Salomon, pendant la fête, le septième mois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Tous les anciens d\'Israël y étaient venus; les lévites prirent l\'arche,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Le tabernacle du témoignage, et toutes les choses saintes que contenait le tabernacle; puis, les prêtres et les lévites le transportèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Or, le roi Salomon, toute la synagogue d\'Israël, les hommes craignant Dieu, tous ceux d\'entre eux qui étaient là rassemblés devant l\'arche, sacrifiaient des bœufs et des brebis en quantité innombrable.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Et les prêtres introduisirent l\'arche de l\'alliance du Seigneur au lieu qui lui était destiné dans l\'oracle du temple, dans le Saint des saints, sous les ailes des chérubins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Et les chérubins avaient les ailes déployées au-dessus du lieu où on mit l\'arche, et les chérubins couvraient l\'arche et les leviers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Mais les leviers faisaient saillie; et, de l\'intérieur du Saint des saints, on en voyait la tête en s\'adossant à la façade de l\'oracle; du dehors on ne les voyait pas: et ils sont restés là jusqu\'à nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Il n\'y avait rien dans l\'arche, sinon les deux tables que Moïse y avait déposées en Horeb; témoignage de l\'alliance du Seigneur avec les fils d\'Israël, quand il les eut fait sortir de l\'Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Et, au moment où les prêtres sortirent du sanctuaire (car tous avaient été consacrés, et ils n\'étaient point divisés encore par ordre journalier de service),');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Et, avec eux, les lévites, chanteurs de psaumes, tous subordonnés à Asaph, à Hêman, à Idithun, à leurs fils et à leurs frères, revêtus de robes de lin, portant des cymbales, des lyres, des harpes, se tenant en face de l\'autel, et, avec eux, cent vingt prêtres sonnant de la trompette,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Les trompettes, les harpes et les chants se réunirent en une seule harmonie pour louer d\'une seule voix et célébrer le Seigneur. Et les voix s\'élevaient accompagnées des trompettes, des cymbales et des instruments des chanteurs, et elles disaient: Rendez hommage à Dieu, parce qu\'il est bon, et que sa miséricorde est éternelle. Alors, le temple fut rempli d\'une nuée de gloire du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Et les prêtres ne purent y demeurer ni faire le service divin, à cause de la nuée; car la gloire du Seigneur avait rempli le temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Et Salomon s\'écria: Le Seigneur avait dit qu\'il habiterait dans le nuage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Et moi, Seigneur, j\'ai construit à votre saint nom un temple, préparé pour vous abriter à jamais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Puis, le roi se retourna, et il bénit toute l\'Église d\'Israël, et toute l\'Église d\'Israël était debout.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Et il ajouta: Béni soit le Seigneur Dieu d\'Israël, qui, de sa bouche, a parlé, concernant David, mon père; et qui, de ses mains, a rempli ses promesses; il avait dit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Depuis le jour où j\'ai tiré mon peuple de l\'Égypte, je n\'avais point choisi de ville, parmi toutes les tribus d\'Israël, pour qu\'on bâtit un temple ou résidât mon nom; je n\'avais point fait choix d\'un homme qui fût le chef de mon peuple Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Depuis, j\'ai choisi Jérusalem pour que mon nom y réside, et j\'ai choisi David pour qu\'il soit sur mon peuple Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Or, mon père avait en son cœur la pensée de bâtir un temple au nom du Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Et le Seigneur dit à David, mon père: La pensée est venue en ton cœur de bâtir un temple à mon nom; il est bon qu\'elle soit venue à ton cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Néanmoins, tu ne bâtiras point ce temple: c\'est le fils issu de tes entrailles qui le bâtira à mon nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Le Seigneur a relevé la parole qu\'il avait dite; j\'ai été suscité à la place de David, mon père, et je me suis assis sur le trône d\'Israël, comme l\'avait dit le Seigneur, et j\'ai bâti un temple au nom du Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Et j\'ai placé l\'arche qui renferme l\'alliance que le Seigneur a faite avec Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Ensuite, Salomon se tint devant l\'autel du Seigneur et devant toute l\'Église d\'Israël, et il étendit les mains;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Car il avait fait un piédestal d\'airain qu\'il avait placé au milieu du parvis du grand prêtre; ce piédestal avait cinq coudées de long, sur cinq de large, et trois de haut; or, le roi y était monté, et il se mit à genoux devant toute l\'Église d\'Israël, et il étendit les mains vers le ciel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'Et il dit: Seigneur Dieu d\'Israël, il n\'est point au ciel et sur la terre de Dieu tel que vous, gardant alliance et miséricorde pour vos serviteurs qui marchent de toute leur âme devant vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Ce que vous avez réservé à votre serviteur David, ce que vous lui avez promis, ce que vous lui avez dit de votre bouche, vous l\'avez exécuté de vos mains, comme il se voit aujourd\'hui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Maintenant, Seigneur Dieu d\'Israël, gardez pour votre serviteur David, mon père, cette parole que vous lui avez dite: il ne manquera jamais d\'hommes de ton sang pour être assis sur le trône d\'Israël, devant ma face, pourvu que tes enfants observent leurs voies, et qu\'ils marchent, à mes yeux, comme toi-même as marché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Maintenant, Seigneur Dieu d\'Israël, que votre promesse à David, mon père, votre serviteur, soit confirmée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Est-il donc croyable que Dieu réside sur la terre parmi les hommes? Si le ciel et le ciel des cieux ne peuvent vous contenir, comment ce temple, que j\'ai bâti à votre nom, vous contiendrait-il?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'O Seigneur Dieu d\'Israël, considérez la demande et la prière de votre serviteur, pour exaucer la demande et la prière que fait aujourd\'hui devant vous votre serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Que vos yeux soient ouverts nuit et jour sur ce temple, sur ce lieu dont vous avez dit que votre nom y serait invoqué; accueillez la prière que vous fait en ce lieu votre serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Oui, vous écouterez la prière de votre serviteur et de votre peuple Israël, toutes les fois qu\'ils prieront dans ce lieu; vous les entendrez du lieu que vous habitez au ciel, et vous les exaucerez, et vous leur serez propice.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Si un homme a péché contre son prochain, et que celui-ci prête serment contre lui et qu\'il lui défère le serment, et que le premier vienne jurer dans ce temple devant votre autel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Vous l\'entendrez du haut du ciel, et vous agirez, et vous jugerez vos serviteurs, pour rétribuer l\'inique et faire retomber ses mauvaises voies sur sa tête; pour justifier le juste et le rétribuer selon son équité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Et si votre peuple Israël est frappé par son ennemi; s\'ils ont péché contre vous, et qu\'ils se convertissent, qu\'ils rendent hommage à votre nom, qu\'ils prient et supplient devant vous en ce temple;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Vous les entendrez du haut du ciel, et vous serez miséricordieux pour les péchés de votre peuple Israël, et vous les ramènerez dans la terre que vous avez donnée à eux et à leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Lorsque vous aurez fermé le ciel et qu\'il n\'y aura plus de pluie, parce qu\'ils auront péché contre vous, ils prieront en ce lieu, et ils rendront gloire à votre nom, et ils feront pénitence de leurs péchés, après que vous les aurez humiliés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Et vous les entendrez du haut du ciel, et vous serez miséricordieux pour les péchés de vos serviteurs et de votre peuple Israël; car vous leur aurez montré la bonne voie qu\'ils doivent suivre, et vous accorderez de la pluie à la terre que vous avez donnée en héritage à votre peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Lorsqu\'il y aura en la terre: famine, mortalité, vents pestilentiels, jaunisse, sauterelles; lorsqu\'un ennemi aura opprimé votre peuple devant ses villes; dans toutes nos plaies et nos peines,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Toute prière, toute supplication, que vous feront dans ce temple, les mains étendues, soit un homme, soit le peuple entier d\'Israël, vous l\'exaucerez. Si quelqu\'un reconnaît sa faute et sa plaie,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Vous l\'écouterez du haut du ciel, du lieu où est votre demeure; vous serez miséricordieux, et vous rétribuerez chacun selon sa voie, selon ce que vous aurez vu dans son cœur, car vous seul connaissez le cœur des fils des hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Ainsi, auront-ils crainte de toutes vos voies, tout le temps qu\'ils vivront en la terre que vous avez donnée à nos pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Et tout étranger qui n\'est point de votre peuple Israël, et qui viendra d\'une contrée lointaine, à cause de votre grand nom, de votre forte main et de votre bras tout-puissant, entrera aussi et priera dans ce temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Et vous l\'entendrez du haut du ciel, du lieu où est votre demeure; vous agirez selon la prière de l\'étranger qui vous aura invoqué, afin que tous les peuples connaissent votre nom, et qu\'ils aient crainte de vous, comme le peuple d\'Israël, et qu\'ils sachent que votre nom est invoqué dans ce temple que j\'ai bâti.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Si votre peuple va en guerre contre ses ennemis, en suivant la voie où vous l\'aurez envoyé, et s\'il invoque le nom du Seigneur, tourné vers la ville que vous vous êtes choisie, et vers le temple que j\'ai bâti à votre nom,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Vous entendrez du haut du ciel sa demande et sa prière, et vous rendrez sur lui votre jugement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Ils pècheront contre vous, car il n\'est point d\'homme qui ne pèche; vous les frapperez, vous les livrerez à des ennemis qui les emmèneront captifs en leur terre voisine ou lointaine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Et en la terre où ils auront été transportés, ils convertiront leurs cœurs, et ils se repentiront, et ils prieront dans leur captivité, disant: Nous avons péché, nous avons été déréglés et iniques.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'Et ils reviendront à vous de tout leur cœur, de toute leur âme, en la contrée de ceux qui les auront pris, et où ils seront retenus captifs, et ils vous prieront, tournés vers la terre que vous avez donnée à leurs pères, vers la ville que vous vous êtes choisie, vers ce temple que j\'ai bâti au nom du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Et vous entendrez du haut du ciel, du lieu de votre demeure, leur demande et leur prière; vous les jugerez, et vous serez miséricordieux envers ce peuple qui aura péché contre vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Et maintenant, Seigneur, ouvrez les yeux, prêtez une oreille attentive à la prière que je fais en ce temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Levez-vous, ô Seigneur mon Dieu, pour entrer dans ce lieu de repos avec l\'arche de votre force; que vos prêtres se revêtent du salut, et que vos enfants se réjouissent de vos biens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Seigneur Dieu, ne vous détournez pas de votre christ; souvenez-vous de votre miséricorde envers David, votre serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Aussitôt que Salomon eut achevé sa prière, le feu du ciel descendit et dévora les holocaustes, et la gloire du Seigneur remplit le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Et, à ce moment-là, les prêtres ne purent entrer dans le temple, parce qu\'il était rempli de la gloire du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Et tous les fils d\'Israël virent le feu descendre; et la gloire du Seigneur remplir l\'édifice, et ils tombèrent la face sur le pavé du temple, et ils adorèrent le Seigneur, et ils le louèrent, à cause de sa bonté et de sa miséricorde infinies.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Ensuite, le roi et tout le peuple immolèrent des victimes devant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Et le roi Salomon offrit en sacrifice vingt-deux mille bœufs, et cent vingt mille têtes de menu bétail; le roi et tout le peuple firent ainsi la dédicace du temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Et les prêtres; chacun à son poste, et les lévites, avec les instruments et les chants du roi David, rendaient gloire au Seigneur et à sa miséricorde éternelle; devant eux, des prêtres sonnaient de la trompette, et tout le peuple se tenait debout.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Et Salomon consacra le milieu du parvis du temple, car c\'est là qu\'il offrit les holocaustes et qu\'il brûla la graisse des hosties pacifiques; car l\'autel d\'airain, qu\'avait fait Salomon, ne suffisait pas à contenir les holocaustes, les oblations et la graisse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Et le roi Salomon, en ce même temps-là, fit une fête de sept jours; avec lui était Israël, grande assemblée venue depuis l\'entrée d\'Emath jusqu\'au fleuve d\'Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Et le huitième jour il sanctifia la fin de la fête, parce que la fête de la Dédicace de l\'autel avait duré sept jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Et le vingt-troisième jour du septième mois, il renvoya le peuple, chacun en sa demeure, la joie dans le cœur, pénétré des biens que le Seigneur avait accordés à David, à Salomon et à Israël, son peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Or, Salomon avait achevé le temple du Seigneur, et son propre palais; et tout ce qu\'en son âme il avait désiré faire dans le temple et dans le palais, il l\'avait heureusement accompli.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Et le Seigneur lui apparut pendant la nuit, et il dit: J\'ai entendu ta prière; je me suis choisi ce lieu pour qu\'il y eût un temple où l\'on me sacrifiât.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Si je ferme le ciel et qu\'il n\'y ait point de pluie; si je commande aux sauterelles de dévorer vos arbres; si j\'envoie la peste à mon peuple;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'Et si mon peuple, pour qui mon nom est invoqué, rentre en soi-même, s\'il prie, s\'il désire ma présence, s\'il se détourne de la mauvaise voie, je l\'entendrai du haut du ciel; je serai miséricordieux pour ses péchés, et je guérirai sa terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Et mes yeux seront ouverts, et mes oreilles seront attentives à la prière qui sera faite eu ce temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Car j\'ai choisi et sanctifié cette demeure pour que mon nom y réside éternellement, et mes yeux et mon cœur y seront dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Et, si tu marches devant moi comme ton père, si tu fais ce que je t\'ai prescrit, si tu observes mes commandements et mes préceptes,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Je maintiendrai ton trône royal, selon l\'alliance que j\'ai faite avec David, disant: Jamais, en Israël, il ne manquera de chef issu de toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mais si vous vous pervertissez, si vous abandonnez les commandements et les préceptes que j\'ai mis devant vous, si vous suivez, si vous servez d\'autres dieux, si vous les adorez,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Je vous enlèverai de la terre que j\'ai donnée à vos pères, je rejetterai loin de ma vue ce temple que j\'ai consacré à mon nom; j\'en ferai la fable et le jouet des gentils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Et cette demeure superbe, le passant, à son aspect, sera frappé de stupeur, et il s\'écriera: Quel sujet a donc eu le Seigneur pour traiter ainsi leur terre et ce temple?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Et l\'on répondra: C\'est qu\'ils ont abandonné le Seigneur Dieu de leurs pères, qui les avait ramenés de l\'Égypte, et qu\'ils ont pris d\'autres dieux, qu\'ils les ont adorés, qu\'ils les ont servis; à cause de cela, il a fait fondre sur eux tous ces maux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Le roi Salomon avait mis vingt ans à construire ces deux édifices: le temple du Seigneur et son propre palais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Et il rebâtit les villes qu\'Hiram lui avait données, et il y établit des fils d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Puis, il se rendit à Bésoba, qu\'il entoura de remparts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Et il bâtit Thœdnior (Palmyre) dans le désert, ainsi que toutes les places fortes du pays d\'Emath.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Et il fit de Béthoron-la-Haute et de Béthoron-la-Basse deux forteresses, avec murailles, portes et verrous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Et il bâtit Balaath, ainsi que toutes les places fortes qui lui appartenaient, toutes les villes des chars, les villes des cavaliers, enfin tout ce qu\'il lui plut de bâtir tant à Jérusalem que dans le Liban, et dans tout son royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Tout ce qui restait de l\'Hettéen, de l\'Amorrhéen, de l\'Evéen, du Jébuséen; tout ce qui n\'était point d\'Israël,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Mais qui descendait de ceux que les fils d\'Israël n\'avaient point exterminés, et qui étaient restés avec eux en la terre promise, furent obligés de payer à Salomon un tribut qu\'ils paient encore de nos jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Et Salomon ne permit point qu\'il y eût en son royaume de serviteurs nés des fils d\'Israël; car ceux-ci étaient des guerriers, des chefs, des vaillants, qui commandaient les chars et les cavaliers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Il y en avait à la tête des intendants du roi Salomon; on en comptait deux cent cinquante dirigeant les travaux du peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Et Salomon conduisit la fille du Pharaon de la ville de David, au palais qu\'il avait bâti pour elle, car il avait dit: Ma femme ne doit pas demeurer en la ville de David, roi d\'Israël, parce qu\'une ville où est entrée l\'arche du Seigneur est sainte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Alors, Salomon offrit des holocaustes au Seigneur sur l\'autel qu\'il avait élevé au Seigneur devant le temple,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Selon la règle de chaque jour; il les offrit conformément aux commandements de Moïse sur les sabbats, les lunes et les fêtes des trois époques de l\'année: fête des azymes, fête des semaines, fête des tabernacles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Ensuite, conformément à l\'ordre établi par David, son père, il régla les fonctions des prêtres et celles des lévites, qui devaient servir et chanter journellement devant les prêtres; il désigna aussi les portiers; car, ainsi l\'avait prescrit David, homme de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Et on ne s\'écarta point des commandements du roi, concernant les prêtres et les lévites, en aucune chose, notamment en ce qui regardait les trésors.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Tous les travaux avaient été préparés à partir du jour où Salomon avait jeté les fondations du temple, jusqu\'à celui où la construction fut achevée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Alors, Salomon alla à Asiongaber et à Ailath, en la terre d\'Idumée, près du rivage de la mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Là, Hiram lui envoya des vaisseaux et des serviteurs habitués à la mer; ceux-ci naviguèrent, avec les serviteurs de Salomon, jusqu\'à Ophir; ils rapportèrent de là trois cent cinquante talents d\'or, et ils revinrent auprès du roi Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Et la reine de Saba ouït le renom de Salomon, et elle vint à Jérusalem avec une suite nombreuse, pour éprouver le roi Salomon, en lui proposant des énigmes; or, elle avait des chameaux chargés d\'épices, d\'or et de pierres précieuses; elle vint ainsi auprès de Salomon, et elle lui dit tout ce qu\'elle avait dans le cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Et Salomon résolut toutes ses questions, et il n\'y eut pas un mot qu\'il négligeât, auquel il ne répondît.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Et la reine de Saba vit la sagesse de Salomon, le palais qu\'il avait bâti,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'Les mets de sa table, les logements de ses serviteurs, la tenue de ses officiers et leurs vêtements, ses échansons, leur équipement et les holocaustes qu\'il consacra dans le temple du Seigneur, et elle en fut hors d\'elle-même.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Et elle dit au roi Salomon: C\'était la vérité qu\'on m\'avait dite en mon pays, au sujet de ton éloquence et de ta sagesse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Et j\'avais refusé de croire à ce qu\'on m\'en avait rapporté, jusqu\'à ce que je fusse venue moi-même et que j\'eusse vu de mes yeux; je reconnais qu\'on ne m\'avait point appris la moitié de ta sagesse. Tu as dépassé ce que j\'avais entendu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Heureux tes hommes, heureux tes serviteurs qui sont toujours auprès de toi, et qui recueillent toute ta sagesse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Béni soit le Seigneur ton Dieu qui s\'est complu en toi et qui t\'a mis sur le trône d\'Israël, pour que tu sois roi selon le cœur du Seigneur ton Dieu; car le Seigneur ton Dieu aime ce peuple, et il veut l\'affermir à jamais; et il t\'a établi leur roi, afin que tu observes le jugement et la justice.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Et elle donna à Salomon cent vingt talents d\'or, avec une immense quantité d\'épices, et des pierres précieuses. Il n\'y eut, en aucun temps, des épices comme celles que la reine de Saba donna au roi Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Cependant, les serviteurs de Salomon et les serviteurs d\'Hiram apportèrent à Salomon de l\'or d\'Ophir, des pins et des pierres précieuses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Le roi fit de ces pins les degrés du temple et du palais; il en fit aussi des cithares et des lyres pour les chanteurs, et on n\'avait jamais vu de tels arbres auparavant dans la terre de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Et le roi Salomon donna à la reine de Saba tout ce qu\'elle voulut, tout ce qu\'elle demanda, hormis ce qu\'elle-même lui avait donné. Et elle s\'en retourna en son pays.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Le poids de l\'or qui arriva au roi Salomon en une année, fut de six cent soixante-six talents,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Outre les impôts sur les hommes et les droits payés par les marchands. Et tous les rois de l\'Arabie, tous les princes de la terre promise apportaient au roi Salomon de l\'argent et de l\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Il fit faire deux cents longs boucliers d\'or avec six cents sicles d\'or battu, chacun pesant six cents sicles d\'or pur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Et trois cents petits boucliers d\'or battu, chacun pesant trois cents sicles d\'or; il les plaça tous dans le palais de bois du Liban.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Il fit faire aussi un grand trône d\'ivoire qu\'il revêtit de lames d\'or très fin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'On montait sur ce trône par six degrés revêtus d\'or, et il y avait des bras des deux côtés du siège, et deux lions auprès des bras,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Et douze lions sur les degrés: six à droite, six à gauche; on ne voyait rien de semblable dans aucun royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Et tous les vases dont se servait Salomon étaient d\'or, ainsi que tous les meubles du palais de bois du Liban. On n\'y voyait point d\'argent, car ce métal était compté pour rien, du temps de Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Et cela, parce qu\'un vaisseau de Salomon partait pour Tharsis avec les serviteurs du roi Hiram, et tous les trois ans des bâtiments en revenaient chargés d\'or, d\'argent, d\'ivoire et de singes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Ainsi, Salomon surpassa tous les rois en science et en richesses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Et tous les rois de la terre demandèrent à le voir, et à entendre la sagesse que Dieu avait mise en son cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Et chaque année, ils lui apportaient des présents: des vases, de l\'or, des vêtements, de la myrrhe, des épices, des chevaux et des mules.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomon avait pour ses chars quatre mille cavales et douze mille cavaliers; il les avait mis dans les villes des chars ou auprès de lui à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Et il était le chef de tous les rois, depuis l\'Euphrate jusqu\'au territoire des Philistins, et aux frontières de l\'Égypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Et le roi rendit à Jérusalem l\'or et l\'argent aussi communs que les pierres; et les cèdres aussi nombreux que les mûriers des champs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Et Salomon tirait des chevaux de l\'Égypte et de toute la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Le reste des actes de Salomon, les premiers et les derniers sont écrits dans les Récits de Nathan le prophète, et d\'Achias le Sélonite, et dans les Visions du voyant Johel, concernant Jéroboam, fils de Nabat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Et Salomon régna quarante ans sur Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Et Salomon s\'endormit avec ses pères; on l\'ensevelit en la ville de David, et son fils Roboam régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Et Roboam se rendit à Sichem, parce que tout Israël y était venu pour le proclamer roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Or, dès que Jéroboam, fils de Nabat, apprit ces nouvelles en Égypte, où il avait fui loin de Salomon, il en revint.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Et le peuple l\'envoya chercher, et il alla devant Roboam avec toute la synagogue, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Ton père a rendu notre joug bien dur; allège donc maintenant la servitude trop dure de ton père, que notre joug soit moins lourd, et nous te servirons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Et il leur dit: Allez-vous-en pendant trois jours; puis, revenez auprès de moi; et le peuple s\'en alla.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Le roi Roboam réunit les anciens qui, du vivant de Salomon, son père, se tenaient auprès de lui, disant: Que me conseillez-vous de répondre à ce peuple?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Il lui dirent: Si aujourd\'hui tu es bienveillant pour ce peuple, si tu veux bien lui dire de bonnes paroles, ils seront tes serviteurs tous les jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Mais, il dédaigna le conseil des anciens qu\'il avait consultés, et il consulta les jeunes gens élevés avec lui, qui se tenaient devant lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Et il leur dit: Comment me conseillez-vous de répondre à ce peuple qui me dit: Allège le joug que nous a mis ton père?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Or, les jeunes gens, élevés avec lui, dirent: Voici comment tu parleras à ce peuple qui t\'a dit: Ton père a rendu pesant notre joug, allège-le pour nous, réponds-leur: Mon petit doigt est plus gros que le corps de mon père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Mon père vous a châtiés avec un joug pesant, je le rendrai pour vous plus pesant encore; il vous a châtiés à coups de fouet, mais je vous châtierai avec des scorpions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Et Jéroboam revint le troisième jour, avec tout le peuple, auprès de Roboam comme il le leur avait prescrit, disant: Revenez dans trois jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Et le roi leur répondit durement, car il avait dédaigné le conseil des anciens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Et il leur parla selon le conseil des jeunes gens, et il leur dit: Mon père vous a chargés d\'un joug pesant, je le rendrai pour vous plus pesant encore; il vous a châtiés à coups de fouet, moi je vous châtierai avec des scorpions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Et le roi n\'avait point écouté les fils d\'Israël, parce que Dieu s\'était tourné contre lui, disant: « Le Seigneur a relevé la parole qu\'il a dite, par Achias le Sélonite, concernant Jéroboam, fils de Nabat,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Et tout Israël. » C\'est pourquoi le roi ne l\'avait pas écouté, et le peuple s\'écria: Qu\'y a-t-il entre nous et David? Notre héritage dépend-il du fils de Jessé? A tes tentes, ô Israël, et toi, David, veille sur ta maison. Et Israël s\'en alla chacun en sa demeure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Et les hommes d\'Israël qui habitaient Juda rentrèrent en leurs villes, et Jéroboam régna sur eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Et le roi envoya aux autres fils d\'Israël, Adoniram, intendant des impôts; ils le lapidèrent, il mourut; et le roi Roboam s\'empressa de monter sur son char pour fuir, et se renfermer dans Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Et jusqu\'à nos jours la maison de David a été rejetée par Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Roboam rentra donc à Jérusalem; puis, il réunit Juda et Benjamin, cent quatre-vingt mille jeunes gens allant à la guerre, afin de combattre Israël, et de recouvrer la royauté pour Roboam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Mais, la parole du Seigneur vint à Samaïas, homme de Dieu; disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Parle à Roboam, fils de Salomon, à tout Juda et à Benjamin, dis-leur:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Voici ce que dit le Seigneur: Ne partez pas, ne combattez point vos frères les fils d\'Israël, retournez chacun en votre demeure, car cette chose est de moi. Ils obéirent à la parole du Seigneur, et, selon son ordre, ils renoncèrent à marcher contre Jéroboam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Et Roboam habita Jérusalem, et il bâtit des places fortes en Judée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Il bâtit encore Bethléem, Etan, Thécoé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bethsura, Sochoth, Odollam,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Geth, Marisan, Ziph,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraï, Lachis, Azéca,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Saraa, Aïlon et Hébron, qui appartient à Juda et à Benjamin; toutes villes qu\'il entoura de remparts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Et il les fortifia, et leur donna des chefs auxquels il assigna des vivres, de l\'huile et du vin,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Et il approvisionna chacune d\'elles de lances et de boucliers, et il en multiplia les défenses; et il eut à lui Juda et Benjamin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Cependant, les prêtres et les lévites qui étaient en tout Israël, se rassemblaient auprès de lui de tous les points du territoire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Car, ils abandonnèrent leurs villes de résidence, et ils se rendirent en Juda et à Jérusalem, parce que Jéroboam et ses fils leur avaient ôté le service du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Et Jéroboam avait institué pour lui des prêtres des hauts lieux qui sacrifiaient aux idoles, aux choses vaines, aux veaux d\'or, qu\'avaient faits Jéroboam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Et il avait chassé des tribus d\'Israël ceux qui dévouaient leur cœur à chercher le Seigneur Dieu d\'Israël; et ils vinrent à Jérusalem pour sacrifier au Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Et ils affermirent le royaume de Juda, et Roboam, fils de Salomon, en fut fortifié pendant trois ans, parce qu\'il marcha trois ans dans les voies de David et de Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Roboam prit pour femmes Moolath, fille de Jerimuth, fils de David; et Abigaïl, fille d\'Eliab, fils de Jessé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Celle-ci lui enfanta des fils: Jéhu, Samoria et Zaam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Après cela, il épousa Maacha, fille d\'Absalon, et elle lui enfanta Abias, Jetthi, Zéza et Salémoth.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Or, Roboam aima Maacha, fille d\'Absalon, plus que toutes ses femmes et ses concubines, car il avait dix-huit femmes et soixante concubines; il eut d\'elles vingt-huit fils et soixante filles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Et il fit Adias, fils de Maacha, chef de tous ses frères, car il avait dessein de lui laisser le trône.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Et il le fortifia plus que tous ses autres fils dispersés sur tout le territoire de Juda et de Benjamin, dans les villes entourées de remparts où Roboam maintenait abondance de vivres, et où il leur fit épouser beaucoup de femmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Or, quand Roboam eut organisé son royaume et s\'y fut affermi, il abandonna les commandements du Seigneur, et tout le peuple suivit son exemple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Et la cinquième année de son règne, parce qu\'il avait péché contre le Seigneur, Susacim (Sésac), roi d\'Égypte, marcha contre Jérusalem,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Avec douze cents chars, soixante mille chevaux et une multitude innombrable des Libyens, de Troglodytes et d\'Ethiopiens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Et ils s\'emparèrent de toutes les forteresses de Juda, et ils arrivèrent devant Jérusalem,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Et Samaïas le prophète alla trouver Roboam et les princes de Juda, qui s\'étaient réunis à Jérusalem par crainte de Susacim, et il leur dit: Voici que dit le Seigneur: Vous m\'avez abandonné, et moi je vous abandonnerai pour vous livrer à Susacim.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Et le roi et les chefs de Juda eurent honte, et ils dirent: Le Seigneur est juste.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Quand le Seigneur vit qu\'ils s\'étaient repentis, la parole du Seigneur vint à Samaïas, disant: Ils se sont repentis, je ne les détruirai pas; je leur accorderai comme une ombre de salut, et ma colère ne tombera pas sur Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Ils seront asservis, et ils connaîtront la différence de ma servitude avec la servitude des rois de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Et Susacim, roi d\'Égypte, marcha contre Jérusalem; il prit tous les trésors du temple du Seigneur, et tous les trésors du palais du roi, il prit tout; il prit aussi les boucliers d\'or qu\'avait faits Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, '(Le roi Roboam les remplaça par des boucliers d\'airain). Et le roi Susacim mit au-dessus de lui des capitaines de ses gardes surveillant la porte du palais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Et lorsque le roi entrait dans le temple du Seigneur, les gardes y entraient aussi, et avec les coureurs ceux qui allaient à la rencontre des coureurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Mais parce qu\'il s\'était repenti, le Seigneur détourna de lui sa colère, et il ne fut pas entièrement détruit; car il y avait encore en Juda de bonnes pensées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Et le roi Roboam se raffermit en Jérusalem et il régna; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem dans la ville que, parmi toutes les tribus d\'Israël, le Seigneur s\'était choisie pour que son nom y fût invoqué; sa mère, nommée Noomma, était Ammonite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Et il fit le mal parce qu\'il ne dirigea pas son cœur à la recherche de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Quant aux discours de Roboam, les premiers et les derniers, et à ses actions, ne sont-ils pas écrits dans les Récits de Samaïas le prophète, et d\'Addo le voyant? Roboam fut toujours en guerre avec Jéroboam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Et Roboam alla rejoindre ses pères, et il fut enseveli dans la ville de David; et Abias, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'En la dix-huitième année du règne de Jéroboam, Abias commença à régner sur Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Il régna trois ans à Jérusalem; et le nom de sa mère était Maacha, fille d\'Uriel de Gabaon. Abias ne cessa pas d\'être en guerre avec Jéroboam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Et il rangea en bataille une armée de quatre cent mille hommes vaillants, et Jéroboam lui en opposa huit cent mille, vaillants aussi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Alors Abias monta sur la colline de Salomon qui est dans les montagnes d\'Ephraïm, et il dit: Jéroboam, écoute-moi ainsi que tout Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Ne devez-vous pas savoir que par une alliance sacrée, le Seigneur notre Dieu a donné pour toujours le royaume d\'Israël à David et à ses fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Mais, Jéroboam, fils de Nabat, serviteur de Salomon, fils de David, s\'est levé et s\'est révolté contre son maître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Et des hommes de pestilence, fils du péché, se sont joints à lui, qui s\'est révolté contre Roboam, fils de Salomon, et Roboam, qui était jeune et d\'un cœur craintif, n\'osa lui tenir tête.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Et vous maintenant, vous dites que vous résisterez au royaume du Seigneur que possèdent les fils de David; et vous êtes nombreux, et vous avez avec vous les veaux d\'or qu\'a faits Jéroboam, pour qu\'ils soient vos dieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'N\'avez-vous pas chassé les prêtres du Seigneur, les fils d\'Aaron et les lévites? Ne vous êtes-vous point fait des prêtres parmi le peuple de toute la terre? Quiconque arrive, pour se consacrer, avec un bœuf du troupeau et sept béliers, le voilà prêtre de ce qui n\'est point dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Quant à nous, nous n\'avons point abandonné le Seigneur; ce sont ses prêtres, fils d\'Aaron, et ses lévites qui le servent, et qui journellement');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Offrent des holocaustes au Seigneur, matin et soir, brûlent les parfums composés, déposent sur la table pure les pains de proposition, allument à la nuit le chandelier d\'or et les lampes qui doivent brûler; car, nous observons les préceptes du Seigneur Dieu de nos pères, que vous avez abandonné.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Voyez, le Seigneur et ses prêtres sont avec nous à notre tête; ce sont les trompettes sacrées qui nous donnent les signaux; fils d\'Israël, gardez- vous de combattre le Seigneur, car vous ne réussirez à rien.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Cependant, Jéroboam ramena sur les derrières de Juda une embuscade qu\'il avait dressée; il fut ainsi lui-même devant Juda, et son embuscade derrière.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Et Juda se retournant regarda, et voilà que la bataille était devant et derrière lui; alors, il cria au Seigneur, et les prêtres sonnèrent de la trompette.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Et les hommes de Juda crièrent, et il advint, pendant qu\'ils jetaient de grands cris, que le Seigneur frappa Jéroboam et Israël devant Abias et Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Et les fils d\'Israël s\'enfuirent devant Juda, et le Seigneur les livra au roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Abias et son peuple les frappèrent d\'une grande plaie, et cinq cent mille hommes vaillants succombèrent du côté d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Et, en ce jour-là, les fils d\'Israël furent humiliés, et les fils de Juda prévalurent, parce qu\'ils avaient espéré en Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Abias poursuivit Jéroboam, il lui prit des villes: Béthel et ses bourgs, Mayne et ses bourgs, Ephron et ses bourgs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Et Jéroboam fut sans force sous le règne d\'Abias; enfin, le Seigneur le frappa, et il mourut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Et Abias s\'affermit, et il épousa quatorze femmes, dont il eut vingt-deux fils et seize filles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Le reste de l\'histoire d\'Abias, ses actions et ses discours, sont écrits au livre du prophète Addo.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 23, 'Et Abias mourut, et il alla rejoindre ses pères, et on l\'ensevelit en la ville de David; et Asa, son fils, régna à sa place. Sous Asa, Juda fut en paix dix années.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Et il fit ce qui est bon et droit devant le Seigneur son Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Il répudia les autels des dieux étrangers et les hauts lieux; il brisa les colonnes, il abattit les bois sacrés,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Et il dit à Juda de chercher le Seigneur Dieu de leurs pères, et de pratiquer sa loi et ses commandements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Et il détruisit, dans toutes les villes de Juda, les autels et les idoles, et paisiblement');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Il fortifia des places en Juda; car la terre était en paix. Il n\'y eut point de guerre en ces années, parce que le Seigneur lui avait donné du repos.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Et il dit à Juda: Fortifions les villes, faisons-leur des murs, des tours, des portes, des verrous; nous prévaudrons sur la terre: car de même que nous avons cherché le Seigneur notre Dieu, il nous a cherchés; il nous a donné la paix tout alentour, et il nous a fait prospérer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Or, Asa avait en la terre de Juda une force de trois cent mille hommes portant javeline et bouclier; et, en la terre de Benjamin, deux cent quatre- vingt mille archers, ou fantassins armés à la légère; tous ces hommes étaient vaillants et aguerris.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Et Zara l\'Ethiopien marcha contre eux avec une armée d\'un million d\'hommes, et trois cents chars; il s\'avança jusqu\'à Marèsa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Asa sortit à sa rencontre, et rangea son armée en bataille dans la vallée, au nord de Marèsa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Et Asa cria au Seigneur son Dieu, et il dit: Seigneur, il ne vous est point impossible de sauver, soit avec beaucoup, soit avec peu; fortifiez-nous, Seigneur notre Dieu, car nous avons eu foi en vous, et c\'est en votre nom que nous avons marché contre cette grande multitude. Seigneur notre Dieu, que l\'homme ne prévaille pas contre vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Et le Seigneur frappa les Ethiopiens devant Juda, et les Ethiopiens s\'enfuirent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Asa et son peuple les poursuivirent jusqu\'à Gedsor. Les Ethiopiens tombèrent jusqu\'au dernier; car ils furent broyés devant le Seigneur et devant son armée, et les fils de Juda recueillirent d\'innombrables dépouilles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Et ils détruisirent les bourgs autour de Gedsor; car un grand trouble, venant du Seigneur, était sur eux. Les fils de Juda pillèrent leurs villes, et ils firent un riche butin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Ils détruisirent les tentes des troupeaux, ils dépouillèrent les habitants de la côte, ils emmenèrent quantité de moutons et de chameaux, et ils revinrent à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Et l\'Esprit de Dieu descendit sur Azarias, fils d\'Obed.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Et il sortit à la rencontre d\'Asa, de Juda et de Benjamin, et il dit: Écoutez-moi, Asa, et tout Juda et Benjamin: le Seigneur est avec vous, parce que vous êtes avec lui; si vous le cherchez, vous le trouverez; si vous l\'abandonnez, il vous abandonnera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Il y aura bien des jours en Israël sans vrai Dieu, sans prêtre qui le révèle, sans loi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Mais Dieu les convertira au Seigneur Dieu d\'Israël, et il sera trouvé par eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Et, en ces jours-là, il n\'y a point de paix pour agir; car un grand trouble, venant du Seigneur, est sur tous ceux qui habitent la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Et il y aura guerre de nation à nation, de ville à ville; car Dieu les aura troublés par toutes sertes d\'afflictions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Fortifiez-vous donc; que vos mains ne viennent point à défaillir; car il y a une récompense pour vos œuvres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Après avoir entendu ces paroles et la prophétie d\'Adad le prophète, le roi se fortifia, et il chassa les abominations de tout le territoire de Benjamin, et de Juda et de toutes les villes que possédait Jéroboam dans la montagne d\'Ephraïm; et il fit la dédicace de l\'autel du Seigneur qui était devant le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Puis, il rassembla Juda, Benjamin, les étrangers, résidant avec lui, venus d\'Ephraïm, de Manassé et de Siméon; car beaucoup de ceux d\'Israël s\'étaient joints au roi, parce qu\'ils avaient vu que le Seigneur était avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Et ils se réunirent à Jérusalem le troisième mois de la quinzième année du règne d\'Asa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Et, ce jour-là, ils sacrifièrent au Seigneur, des dépouilles qu\'ils avaient ramenées, sept cents bœufs, et sept mille brebis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Et ils firent alliance pour chercher le Seigneur Dieu de leurs pères, de tout leur cœur et de toute leur âme,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'Et pour que quiconque, jeune ou vieux, homme ou femme, ne chercherait pas le Seigneur Dieu d\'Israël, fût mis à mort.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Et ils prêtèrent serment au Seigneur à haute voix, au son des trompettes et des cors.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Et tout Juda se réjouit d\'avoir juré, car il l\'avait fait de tout son cœur, de toute son âme, et avec une pleine volonté de chercher le Seigneur; et ils le trouvèrent, et il leur donna la paix tout alentour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Et le roi expulsa Maacha, sa mère, pour qu\'il n\'y eût plus personne qui servît Astarté, et il abattit l\'idole, et il la brûla dans le torrent de Cédron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Néanmoins, les hauts lieux n\'étaient point détruits; ils prévalaient encore en Israël; mais le cœur d\'Asa fut parfait tous les jours de sa vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Et il consacra de nouveau les choses saintes de David, son aïeul, et celles du temple: argent, or et vaisseaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Et il n\'y eut point de guerre contre lui jusqu\'à la trente-cinquième année de son règne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Et, en la trente-huitième année du règne d\'Asa, le roi d\'Israël marcha contre Juda, et il bâtit Rhama pour empêcher le roi Asa de sortir et d\'entrer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Et Asa prit tout l\'argent et l\'or des trésors, tant du temple que du palais, et il l\'envoya au fils d\'Ader, roi de Syrie, qui résidait à Damas, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Fais avec moi l\'alliance qui existait entre ton père et le mien; voilà que je t\'offre de l\'argent et de l\'or; viens, disperse Baasa, roi d\'Israël, qu\'il s\'éloigne de mon royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Et le fils d\'Ader accueillit la demande d\'Asa; il fit partir les chefs de ses armées contre les villes d\'Israël, qui dévastèrent Ahion, Dan, Abelmaïn, et tout ce qui environne Nephthali.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Quand Baasa l\'apprit, il abandonna les constructions de Rhama, et il renonça à son entreprise.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Et le roi Asa rentra en possession de tout Juda, et il prit à Rhama les pierres et les bois que Baasa avait employés pour la bâtir, et il s\'en servit pour construire Gabaa et Maspha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'En ce temps-là, Anani le prophète vint trouver Asa, roi de Juda, et il lui dit: Parce que tu t\'es confié au roi de Syrie, et que tu n\'as point eu foi en ton Dieu, l\'armée de Syrie a échappé à tes mains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Les Ethiopiens et les Libyens n\'avaient-ils pas une armée nombreuse, pleine d\'audace, forte par ses cavaliers et sa multitude? Tu as eu foi en Dieu, et il te l\'a livrée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Car les regards du Seigneur sont fixés sur la terre pour fortifier tout cœur parfait devant lui; en cela, tu as follement agi, et maintenant, tu seras toujours en guerre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Asa se mit en colère contre le prophète, et il le jeta en prison, tant il avait de courroux; et, en ce temps-là, Asa maltraita quelques-uns de son peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Et les actes d\'Asa, les premiers et les derniers, sont écrits au livre des Rois de Juda et d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'En la trente-neuvième année de son règne, Asa souffrit d\'un mal aux pieds, dont il fut très-malade; et, en cette maladie, il ne chercha pas le Seigneur, mais les médecins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Et Asa s\'endormit avec ses pères, et il mourut en la quarantième année de son règne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Et on l\'ensevelit dans le sépulcre qu\'il s\'était creusé en la ville de David; or, on l\'avait étendu sur sa couche, on l\'avait rempli d\'aromates et de toutes les substances dent se composent les parfums, et on lui fit de magnifiques funérailles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Et Josaphat, son fils, régna à sa place, et il prévalut sur Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Il mit des garnisons dans toutes les places fortes de Juda, et donna des chefs à toutes les villes de Juda et aux villes d\'Ephraïm dont son père, Asa, s\'était emparé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Et le Seigneur fut avec Josaphat, parce qu\'il marcha dans les voies qu\'avait d\'abord suivies son père, et qu\'il ne chercha point les idoles,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Mais qu\'il chercha le Seigneur Dieu de son père, et qu\'il marcha selon les préceptes de son père, et non selon les œuvres d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Et le Seigneur fit prospérer le royaume entre ses mains, et tout Juda offrit des présents à Josaphat, qui acquit ainsi beaucoup de gloire et de richesses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Et son cœur fut exalté dans les voies du Seigneur, et il détruisit les hauts lieux et les bois sacrés sur le territoire de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'En la troisième année de son règne, il envoya, pour enseigner dans les villes de Juda, ses chefs et les fils des hommes vaillants: Abdias, Zacharie, Nathanaël et Michée,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Et, avec eux, les lévites Samaies, Nathanias, Zabdies, Asihel, Semiranaoth, Jonathas, Adonias, Tobias et Tobadonias; tous lévites, et les prêtres Elisama et Joram.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Et ils enseignèrent en Juda; ils avaient le livre de la loi du Seigneur, ils le lisaient dans les villes de Juda, et ils instruisaient le peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Et un grand trouble, venant du Seigneur, se répandit parmi les rois qui entouraient Juda, et ils ne firent point la guerre à Josaphat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Les Philistins lui envoyèrent de l\'argent et d\'autres dons; les Arabes lui amenèrent sept mille sept cents moutons et béliers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Et Josaphat alla toujours croissant jusqu\'à la magnificence, et il bâtit en Judée des palais et des forteresses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Et il exécuta de nombreux travaux en Judée, et eut à Jérusalem des guerriers vaillants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'En voici le dénombrement par familles paternelles; en Juda, commandants de mille hommes: Ednas le chef, et avec lui trois cent mille hommes vaillants;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Joanan, et avec lui deux cent quatre-vingt mille hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Amasias, fils de Zari, plein de zèle pour le Seigneur, et avec lui deux cent mille vaillants;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Et en Benjamin: Eliada, et avec lui deux cent mille archers ou fantassins armés à la légère;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Et Jozabad, et avec lui cent quatre-vingt mille hommes aguerris.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Tels étaient ceux qui servaient le roi, outre ceux qu\'il avait placés dans toutes les forteresses de la Judée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'La gloire et la richesse de Josaphat s\'accrurent encore, et il s\'allia par un mariage à la famille d\'Achab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Au bout de quelques années, il alla voir Achab en Samarie, et Achab immola, pour lui et sa suite, quantité de bœufs et de brebis; il lui fit beaucoup d\'amitiés pour l\'emmener avec lui contre Ramoth-Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Et Achab, roi d\'Israël, dit à Josaphat, roi de Juda: Viendras-tu avec moi à Ramoth-Galaad? L\'autre répondit: Comme tu es, je suis; mon peuple est comme ton peuple, il fera la guerre comme lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Et Josaphat dit au roi d\'Israël: Consulte aujourd\'hui le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Et le roi d\'Israël rassembla tous les prophètes, au nombre de quatre cents, et il leur dit: Irai-je en guerre à Ramoth-Galaad, ou m\'abstiendrai-je? Et ils répondirent: Marche, le Seigneur les livrera aux mains du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Et Josaphat dit: N\'y a-t-il plus ici un seul prophète du Seigneur par qui nous puissions consulter?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Et le roi d\'Israël répondit à Josaphat: Il y a encore un homme par qui l\'on peut consulter le Seigneur; mais je le hais, parce que, à mon sujet, il ne prophétise jamais le bien, mais toujours le mal. C\'est Michée, fils de Semis. Et Josaphat reprit: Que le roi ne tienne pas un tel langage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Et le roi appela un eunuque, et il dit: Fais venir tout de suite Michée, fils de Semis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Or, le roi d\'Israël et Josaphat, roi de Juda, revêtus de robes, étaient assis chacun sur son trône, sur l\'esplanade de la porte de Samarie, et tous les prophètes prophétisaient devant eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'L\'un d\'eux, Sédécias, fils de Chanaan, s\'était fait des cornes de fer, et il dit: Voici ce que dit le Seigneur: Avec ces cornes tu frapperas la Syrie jusqu\'à ce qu\'elle soit abattue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Et tous les prophètes prédisaient ainsi: Marche sur Ramoth-Galaad, et tu réussiras, et le Seigneur livrera à tes mains le roi de Syrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Et le messager qui était allé querir Michée dit à celui-ci: Tous les prophètes n\'ont qu\'une voix pour dire de bonnes choses concernant le roi; que tes paroles soient comme celles de l\'un d\'eux, et tu auras bien parlé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Mais Michée répondit: Vive le Seigneur! ce que le Seigneur me dira, je le répèterai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Et il alla devant le roi, et le roi lui dit: Michée, dois je aller en guerre à Ramoth-Galaad, ou m\'en abstenir? Et il répondit: Marche, et tu réussiras, et ils te seront livrés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Et le roi lui dit: Combien de fois t\'adjurerai-je pour que tu ne me dises rien que la vérité au nom du Seigneur?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Et Michée reprit: J\'ai vu Israël dispersé sur les montagnes, comme un troupeau sans pasteur. Et le Seigneur a dit: Ces hommes n\'ont point de chef, que chacun retourne en paix dans sa maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Et le roi d\'Israël dit à Josaphat, roi de Juda: Ne t\'ai-je point dit qu\'à mon sujet il ne prophétisait jamais le bien, mais toujours le mal?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Michée reprit: Il n\'en est pas ainsi; écoutez la parole du Seigneur: J\'ai vu le Seigneur assis sur son trône, et toute l\'armée du ciel se tenait auprès de lui à sa droite et à sa gauche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Et le Seigneur a dit: Qui trompera Achab, roi d\'Israël, pour qu\'il parte et succombe à Ramoth-Galaad? Et l\'un répondit au Seigneur d\'une sorte, l\'autre différemment.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Et l\'esprit sortit des rangs, et il se plaça devant le Seigneur, et il dit: C\'est moi qui le tromperai. Et le Seigneur reprit: De quelle manière?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Et il dit: Je partirai, et je serai un esprit trompeur en la bouche de tous ses prophètes. Et le Seigneur dit: Tu le tromperas, et tu prévaudras; va, et fais ce que tu as dit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Maintenant donc, voici que le Seigneur a placé un esprit trompeur en la bouche de tous tes prophètes, et le Seigneur t\'a annoncé le mal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Alors, Sédécias le Chananéen s\'avança, frappa Michée à la joue, et dit: Par quel chemin l\'Esprit du Seigneur est-il sorti de moi pour te parler à toi?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Et Michée reprit: Tu le verras le jour où tu passeras de chambre en chambre pour te cacher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Et le roi d\'Israël s\'écria: Que l\'on saisisse Michée; menez-le chez Emer, gouverneur de la ville, et chez le prince Joas, fils du roi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Et dites: Voici ce que dit le roi: Emprisonnez cet homme; qu\'il se nourrisse du pain et de l\'eau de l\'affiction jusqu\'à je revienne en paix.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Et Michée reprit: Si tu reviens en paix, le Seigneur n\'a point parlé par ma bouche. Et il ajouta: Peuple, écoutez-moi tous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Après cela, le roi d\'Israël partit avec Josaphat, roi de Juda, pour Ramoth-Galaad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Et le roi d\'Israël dit au roi de Juda: Aide-moi à me déguiser, et j\'engagerai la bataille, et toi tu auras mes vêtements. Le roi d\'Israël se déguisa donc, et il engagea la bataille.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Et le roi de Syrie donna cet ordre aux chefs des chars qui l\'accompagnaient: N\'attaquez ni petit ni grand, mais le seul roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Et ceci advint: quand les chefs des chars virent Josaphat, roi de Juda, ils se dirent: C\'est le roi d\'Israël. Et ils l\'entourèrent pour l\'attaquer; mais Josaphat cria au Seigneur, et le Seigneur voulut le sauver, et Dieu les détourna de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Et quand les chefs des chars virent que ce n\'était pas le roi d\'Israël, ils s\'éloignèrent de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Alors, un homme adroit, ayant tendu son arc, frappa le roi d\'Israël au flanc, au défaut de la cuirasse; et le roi dit à son cocher: Tourne bride, emmène-moi hors de la mêlée, car j\'ai une blessure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Et la bataille fut perdue pour lui ce jour-là, et il resta jusqu\'au soir sur son char, en face de l\'armée syrienne, et, au soleil couchant, il mourut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Et Josaphat, roi de Juda, revint en son palais à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Et le prophète Jéhu, fils d\'Anani, sortit à sa rencontre, et il lui dit Roi Josaphat, n\'as-tu pas porté secours à un impie, et donné ton amitié à un ennemi du Seigneur? A cause de cela, la colère du Seigneur a été excitée contre toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Cependant, il s\'est trouvé du bon en toi; car tu as détruit les bois sacrés en la terre de Juda, et, d\'un cœur droit, tu as cherché Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Et Josaphat résida en Jérusalem; il en sortit encore une fois pour visiter le peuple depuis Bersabée jusqu\'aux montagnes d\'Ephraïm, et il les ramena au Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Et il institua des juges dans toutes les places fortes de Juda: un par ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Et il dit aux juges: Soyez attentifs à ce que vous faites; car vous ne jugez pas pour l\'homme, mais pour le Seigneur, et les paroles du jugement sont avec vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Que la crainte du Seigneur soit donc en vous; veillez et agissez; car, avec le Seigneur notre Dieu, il n\'est point d\'iniquité; il n\'y a point à considérer la personne, ni à recevoir des présents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Et Josaphat institua en Jérusalem des prêtres, des lévites et des chefs de familles d\'Israël, pour juger les choses du Seigneur et les habitants de la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Et il leur donna ses ordres, disant: Vous ferez votre devoir avec la crainte de Dieu, en la plénitude et en la sincérité de votre cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Quels que soient ceux de vos frères qui, de leurs villes, viendront à vous en justice, soit pour une décision entre le sang et le sang, soit pour une application des commandements et des préceptes, déterminez bien pour eux le droit et la sentence; et ils ne pècheront pas envers le Seigneur, et il n\'y aura point de colère, ni contre vos frères, ni contre vous. Faites ainsi, et vous ne pècherez pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Et Ananias le prêtre sera votre chef en ce qui concernera le Seigneur; Zabdias, fils d\'Ismaël, prince de la maison de Juda, sera votre chef en ce qui concernera le roi, et vous aurez avec vous des scribes et des lévites; fortifiez-vous, et faites, et le Seigneur sera avec les bons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Après cela, les fils de Moab, les fils d\'Ammon, et, avec eux, des Minéens, se mirent en campagne pour attaquer Josaphat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Et des gens vinrent et ils l\'apprirent au roi, disant: Une grande multitude est venue contre toi des bords de la mer, du côté de la Syrie, et la voici en Asasan-Thamar (la même qu\'Engaddi).');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Et Josaphat eut crainte, et il s\'appliqua à chercher le Seigneur, et il proclama un jeûne dans tout Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Et Juda se rassembla pour chercher le Seigneur; et, de toutes les villes de Juda, on vint pour chercher le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Et Josaphat, avec toute l\'Église de Juda en Jérusalem, se tint debout dans le temple du Seigneur devant le parvis neuf.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'Et il dit: Seigneur Dieu de mes pères, n\'êtes-vous point Dieu dans le ciel au-dessus de nous? N\'êtes-vous pas le Seigneur de tous les royaumes des nations? N\'est-ce pas en vos mains que réside la force du pouvoir? Est-il quelqu\'un qui puisse vous résister?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'N\'êtes-vous pas le Seigneur dont le bras a exterminé les habitants de cette terre, devant les fils d\'Israël, votre peuple? Ne l\'avez-vous point donnée pour toujours à la race d\'Abraham, votre bien-aimé?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Elle y demeure; elle y a bâti un lieu saint à votre nom, disant');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Si le mal, le glaive, la vengeance, la mort, la famine, viennent sur nous, nous nous tiendrons devant le temple et devant vous, ô Seigneur, parce que votre nom est sur le temple, et, dans notre affliction, nous crierons à vous, et vous nous entendrez, et vous nous sauverez.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Et maintenant, voilà que les fils d\'Ammon, et Moab et ceux de la montagne de Seïr, chez qui vous n\'avez point permis à Israël de passer, à sa sortie d\'Égypte (car il s\'est détourné de leurs territoires, et ne les a point exterminés),');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Voilà qu\'ils nous attaquent pour entrer dans l\'héritage que vous nous avez donné, et pour nous en bannir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Seigneur notre Dieu, ne les jugerez-vous pas? Car nous n\'avons pas la force de résister à l\'immense multitude qui marche contre nous, et nous ne savons que leur faire, sinon de tourner nos yeux vers vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Or, tout Juda était là devant le Seigneur, avec leurs enfants et leurs femmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Et, dans l\'Église, l\'Esprit du Seigneur descendit sur Oziel, fils de Zacharie, des fils de Bandias, des fils d\'Elihel, fils du lévite Matthanias, des fils d\'Asaph.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Et il dit: Écoutez, ô Juda, et vous habitants de Jérusalem, et toi, roi Josaphat: voici ce que vous dit le Seigneur: N\'ayez point de crainte, ne tremblez pas devant cette multitude immense; car ce combat n\'est point de vous, mais de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Marchez demain contre elle; ils monteront le coteau d\'Assis, et vous les trouverez à l\'extrémité du torrent qui traverse le désert de Jerihel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Ce n\'est point à vous de les combattre; comprenez cela, et voyez comme le Seigneur, ô Juda et Jérusalem, opèrera votre salut. N\'ayez point de crainte, n\'hésitez pas à marcher demain à leur rencontre: le Seigneur est avec vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Et Josaphat, et tout Juda et les habitants de Jérusalem s\'étant prosternés la face contre terre tombèrent devant le Seigneur pour l\'adorer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Puis, les lévites des fils de Caath et des fils de Coré se levèrent pour chanter à haute voix les louanges du Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Et le peuple se leva dès l\'aurore, et ils sortirent dans le désert de Thécoé; et, pendant qu\'ils sortaient, Josaphat, se tenant immobile, cria, et dit: Écoutez-moi, Juda, et vous, habitants de Jérusalem, mettez votre confiance dans le Seigneur notre Dieu, et il se confiera en vous; mettez votre confiance dans son prophète, et vous prospérerez.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Ensuite, il tint conseil avec le peuple; puis, il plaça en tête de l\'armée, comme elle sortait, des chantres harpistes pour célébrer et louer les choses saintes, et ils disaient: Rendez gloire au Seigneur, car sa miséricorde est éternelle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Et, au moment où ils commençaient à chanter ses louanges, le Seigneur excita la guerre entre les fils d\'Ammon et Moab, d\'une part, et ceux de la montagne de Seïr, d\'autre part; ils avaient tous marché sur Israël, et ils se tournèrent les uns contre les autres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Les fils d\'Ammon et Moab se levèrent pour exterminer ceux de la montagne de Seïr, et, quand ils les eurent broyés, ils s\'attaquèrent mutuellement, de sorte qu\'ils se détruisirent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Lors donc que Juda arriva sur la hauteur d\'où l\'on découvre le désert, il regarda et il vit cette multitude, et voilà qu\'ils étaient tous tombés morts, et gisant à terre, pas un ne s\'était échappé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Et Josaphat avec tout son peuple descendit pour recueillir les dépouilles; ils trouvèrent quantité de bétail, des bagages, des couvertures et des choses précieuses; ils les prirent et ils mirent trois jours à recueillir le butin, tant il y en avait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Le quatrième jour, ils reprirent leurs rangs dans le val de la bénédiction; car, en ce lieu, ils bénirent le Seigneur; à cause de cela cette vallée est appelée encore de nos jours la Vallée de la Bénédiction.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Et tout Juda, Josaphat à sa tête, revint à Jérusalem avec une grande allégresse, car le Seigneur les avait comblés de joie aux dépens de leurs ennemis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Et ils entrèrent à Jérusalem au son des harpes et des cithares, auxquelles se joignirent les trompettes quand ils arrivèrent au temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Et il y eut un grand trouble venant du Seigneur, parmi tous les royaumes de la terre, quand ils surent que le Seigneur avait combattu les ennemis d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Ainsi le royaume de Josaphat fut en paix; car le Seigneur, alentour, apaisa tout.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Et Josaphat régna en Jérusalem; il avait trente-cinq ans lorsqu\'il monta sur le trône, et son règne dura vingt-cinq ans. Sa mère s\'appelait Azuba, fille de Sali.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Et il marcha dans les voies d\'Asa, son père, et il ne s\'en détourna pas, et il fit ce qui est droit aux yeux du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Cependant, les hauts lieux subsistèrent encore, et le peuple ne dirigea pas encore son cœur vers le Seigneur Dieu de ses pères..');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Le reste des actes de Josaphat, des premiers et des derniers, est compris dans les récits de Jéhu, fils d\'Anani, qui écrivit le livre des Rois d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Après cela, Josaphat, roi de Juda, fit alliance avec Ochozias, roi d\'Israël, et il pécha,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'En agissant et en marchant avec lui pour construire une flotte qui partit d\'Asion-Gaber, allant à Tharsis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Alors, Eliézer, fils de Dodia de Marine, prophétisa contre Josaphat, disant: Parce que tu t\'es lié avec Ochosias, le Seigneur a détruit ton ouvrage; il a brisé ta flotte, et elle n\'a pu aller jusqu\'à Tharsis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Et Josaphat s\'endormit avec ses pères; et il fut enseveli dans la ville de David, et Joram, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Il avait six frères nés de Josaphat: Azarias, Jehiel, Zacharie, Azarias, Michel et Zaphatias. Tels furent les fils de Josaphat, roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Leur père les avait richement dotés d\'argent, d\'or et d\'armes avec des places fortes en Juda; mais il laissa le royaume à Joram, parce qu\'il était le premier-né.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Et Joram se mit en marche dans son royaume, et il s\'affermit, et il fit périr par le glaive tous ses frères avec quelques-uns des chefs d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Il avait trente-deux ans quand il monta sur le trône, et il régna huit ans à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Et il marcha dans la voie du roi d\'Israël, comme avait fait la maison d\'Achab, parce que sa femme était fille d\'Achab, et il fit le mal devant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Toutefois, le Seigneur ne voulait pas détruire la maison de David, à cause de l\'alliance qu\'il avait faite avec lui, et parce qu\'il avait promis de donner, à lui et à ses fils, un flambeau qui ne s\'éteindrait jamais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'En ces jours-là, Edom se souleva contre Juda, et mit à sa tête un roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Et Joram partit avec ses chefs et toute sa cavalerie, et il se leva la nuit, et il tailla en pièces Edom qui l\'avait enveloppé; les chefs des chars, le peuple, tout s\'enfuit chacun en sa demeure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Or, Edom est resté en révolte contre Juda jusqu\'à nos jours. En ce temps- là, Lomna se souleva aussi contre Joram, parce qu\'il avait abandonné le Seigneur Dieu de ses pères,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Et qu\'il avait bâti des hauts lieux dans les villes de Juda, et entraîné les habitants de Jérusalem à se prostituer, et qu\'il avait égaré Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Alors, il lui vint une lettre du prophète Elie, disant: Voici ce que dit le Seigneur Dieu de David, ton aïeul: En punition de ce que tu n\'as point marché dans la voie de Josaphat, ton père, ni dans la voie d\'Asa, roi de la Judée;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Et de ce que tu as marché dans les voies des rois d\'Israël, et de ce que tu as entraîné Juda et les habitants de Jérusalem à se prostituer, comme s\'est prostituée la maison d\'Achab, et de ce que tu as tué tes frères, fils de ton père, qui valaient mieux que toi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Voilà que le Seigneur va te frapper d\'une grande plaie au milieu de ton peuple, de tes fils, de tes femmes, de toutes tes richesses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Tu seras atteint d\'une maladie cruelle, d\'un mal d\'entrailles, et tous tes intestins sortiront de jour en jour par l\'effet de cette maladie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Et le Seigneur excita contre Joram les Philistins, les Arabes et les voisins de l\'Éthiopie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Et ils marchèrent sur Juda, et furent vainqueurs; ils enlevèrent tout ce qu\'ils trouvèrent dans le palais du roi, avec ses fils et ses filles; il ne lui resta pas de fils, hormis Ochozias, le plus jeune de tous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Après cela, le Seigneur le frappa d\'un mal d\'entrailles incurable;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Et les jours s\'écoulèrent, et après deux ans accomplis, le mal avait fait sortir tous ses intestins, et il mourut dans une angoisse cruelle. Et son peuple ne lui fit point de funérailles comme il en avait fait à Josaphat, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Il était monté sur le trône à trente-deux ans, et il avait régné huit ans à Jérusalem, et il n\'avait pas marché d\'une manière digne de louange, et il fut enseveli dans la ville de David, mais non dans le sépulcre des rois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Et les habitants de Jérusalem proclamèrent roi à sa place Ochozias, son plus jeune fils, car l\'armée de brigands qui était venue de l\'Arabie et des bords de la mer, avait tué ses aînés; ainsi, Ochozias, fils de Joram, monta sur le trône de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Il avait alors vingt ans, et il régna un an à Jérusalem; le nom de sa mère était Athalie; elle était issue d\'Ambri.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Et il marcha dans les voies de la maison d\'Achab, parce que sa mère par ses conseils l\'entraînait à pécher.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Et il fit le mal devant le Seigneur comme la maison d\'Achab, car d\'elle seule il prit conseil après la mort de son père, et il se perdit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Marchant donc selon ses conseils, il se joignit à Joram, fils d\'Achab, roi d\'Israël, pour livrer bataille, à Ramoth-Galaad, au roi de Syrie Azaël, quand des archers atteignirent Joram.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Et Joram revint à Jezraël pour se guérir des blessures que les Syriens lui avaient faites en Ramoth-Galaad, lorsqu\'il combattait Azaël, roi de Syrie. Et Ochozias, fils de Joram, roi de Juda, alla voir, en Jezraël, Joram, roi d\'Israël, parce qu\'il était malade.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Et une catastrophe venant de Dieu arriva à Ochozias lorsqu\'il y fut; car, alors Joram sortit avec lui contre Jéhu, fils de Namesseï, l\'oint du Seigneur, suscité contre la maison d\'Achab.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Et au moment où Jéhu tirait vengeance de la maison d\'Achab, il trouva là les princes de Juda, et les frères d\'Ochozias employés à le servir, et il les tua.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Ensuite, il ordonna de chercher Ochozias; on le prit en Samarie soignant ses blessures, on le conduisit à Jéhu qui le mit à mort, et on l\'inhuma; car, dirent ces gens, il est issu de Josaphat qui de tout son cœur a cherché Dieu; il n\'y avait plus personne de la maison d\'Ochozias pour fortifier le pouvoir en son royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Et Athalie, mère d\'Ochozias, voyant son fils mort, se leva et détruisit toute la race royale en Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Mais Josabeth, fille du roi Joram, enleva Joas, fils d\'Ochozias; elle le déroba du milieu des fils du roi que l\'on massacrait; et elle le mit, avec sa nourrice, dans une alcôve des chambres à coucher. Puis, Josabeth, fille de Joram, sœur d\'Ochozias, femme de Joad le prêtre, le cacha d\'Athalie, qui ne le tua pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Il resta six ans avec Joad caché dans le temple de Dieu, pendant qu\'Athalie régnait sur la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Dans la huitième année, Joad se fortifia, il prit avec lui dans le temple du Seigneur les centeniers Azarias, fils de Joram; Ismaël, fils de Johanan; Azarias, fils d\'Obed; Maaseas, fils d\'Adia, et Elisaphan, fils de Zacharie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Ceux-ci parcoururent Juda, rassemblèrent les lévites de toutes les villes de Juda et les chefs de familles d\'Israël, et rentrèrent à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Et dans le temple du Seigneur toute l\'Église de Juda fit alliance avec le roi, et Joad leur montra le fils du roi, et il leur dit: Voilà le fils du roi: qu\'il règne, selon la parole du Seigneur concernant la maison de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Écoutez donc ce que vous avez à faire: Que le tiers des prêtres et des lévites commence son service de semaine et garde les portes d\'entrée,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Que l\'on place un autre tiers au palais du roi, le dernier tiers à la porte du milieu, et tout le peuple dans les parvis du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Que nul ne pénètre dans le temple hormis les prêtres, les lévites et ceux qui les servent. Ceux-là entreront parce qu\'ils sont saints, et tout le peuple fera la garde sainte autour du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Et les lévites entoureront la personne du roi, les armes à la main; ils mettront à mort quiconque s\'introduira dans le temple, et ils ne quitteront point le roi, soit qu\'il entre, soit qu\'il sorte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Les lévites et tout Juda se conformèrent aux ordres de Joad, et ceux qui sortaient de semaine restèrent avec ceux qui entraient en semaine, parce que le grand prêtre ne congédia point ceux dont le service finissait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Et Joad leur délivra les glaives, les boucliers et les armures du roi David, qui étaient dans le temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Et il rangea le peuple, chacun sous ses armes, autour du roi, à l\'aile droite du temple, et à l\'aile gauche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Alors, il amena le fils du roi; il lui donna la couronne et les témoignages; puis, Joad le prêtre et ses fils le proclamèrent roi, et ils le sacrèrent, et le peuple cria: Vive le roi!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Et Athalie entendit la rumeur du peuple courant, applaudissant, louant le roi, et elle entra auprès du roi dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Et elle regarda, et voilà que le roi était sur son siège; et il y avait aux portes les princes, les trompettes, et, autour du roi, des princes et tout le peuple de la terre plein de joie; et les trompettes sonnaient, et les chantres au son des instruments chantaient des cantiques et des louanges; et Athalie déchira sa robe, et elle s\'écria: Vous complotez et complotez.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Et Joad s\'avança pour donner ses ordres aux centeniers et aux chefs de l\'armée, et il leur dit: Jetez-la hors du temple, suivez-la, qu\'elle périsse par le glaive; et le prêtre ajouta: Qu\'elle ne meure pas dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Et ils la laissèrent libre de ses mouvements, et elle franchit la porte qui mène aux chevaux de la maison du roi, et là, ils la tuèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Et Joad fit alliance avec le roi et avec le peuple, pour que Juda fût le peuple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Et tout le peuple de la terre entra dans le temple de Baal, et ils renversèrent son autel, et ils brisèrent ses idoles, et ils tuèrent devant l\'autel Mathan, prêtre de Baal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Et Joad remit aux prêtres et aux lévites le service du temple de Dieu, rétablit l\'ordre des temps où ils devaient être employés, comme l\'avait prescrit David, tant pour la garde du temple que pour les offrandes d\'holocaustes, selon qu\'il est écrit en la loi de Moïse, en y ajoutant les réjouissances et les chants institués par David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Et les portiers veillèrent aux portes du temple, pour que nul homme impur n\'y pût entrer sous aucun prétexte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Et il prit les chefs de famille, les vaillants, les chefs du peuple et tout le peuple de la terre, et ils firent monter le roi dans le temple du Seigneur, d\'où il alla par la porte intérieure au palais du roi; là, ils assirent le roi sur le trône du royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Et tout le peuple de la terre fut en joie; la ville resta calme: Athalie avait été mise à mort.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas avait sept ans quand il monta sur le trône, et il régna quarante ans à Jérusalem; sa mère s\'appelait Sable de Bersabée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Et Joas fit ce qui est droit aux yeux du Seigneur, tant que Joad vécut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Joad lui fit épouser deux femmes, et il engendra des fils et des filles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Après cela, la pensée de restaurer le temple entra dans le cœur de Joas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Il réunit donc les prêtres et les lévites, et il leur dit: Allez dans toutes les villes de Juda, et recueillez de tout Israël de l\'argent pour réparer, d\'année en année, le temple du Seigneur; hâtez-vous de partir. Mais les lévites ne se hâtèrent pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Et le roi Joas appela Joad leur chef, et il lui dit: Pourquoi n\'as-tu point veillé à ce que les lévites apportassent de Juda et de Jérusalem ce qu\'a réglé Moïse l\'homme de Dieu, quand il eut rassemblé Israël au sujet du tabernacle du témoignage?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Car Athalie était pleine d\'iniquité, et ses fils ont ébranlé le temple de Dieu; ils ont employé pour Baal les choses saintes du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Et le roi ajouta: Que l\'on fasse une cassette, et qu\'on la place extérieurement à la porte principale du temple,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Et que l\'on proclame en Juda et à Jérusalem que chacun ait à apporter pour le Seigneur ce que Moïse, serviteur de Dieu, a dit dans le désert concernant Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Alors, tous les chefs donnèrent, tout le peuple donna; chacun apporta son offrande et la jeta dans la cassette, jusqu\'à ce qu\'elle fût remplie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Or, quand les lévites virent que l\'argent abondait, ils portèrent la cassette devant les intendants du roi; le scribe du roi avec l\'intendant du grand prêtre vinrent, et ils vidèrent la cassette; puis, ils la remirent à sa place. Ils firent de même chaque jour, et ils recueillirent beaucoup d\'argent,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Que le roi et Joad donnèrent aux conducteurs des travaux du temple; ceux-ci engagèrent des tailleurs de pierre et des charpentiers, et des hommes habiles à forger le fer et l\'airain, pour restaurer le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Et les travailleurs se mirent à l\'œuvre, qui prospéra entre leurs mains; ils rétablirent le temple du Seigneur jusqu\'aux fondations, et ils le consolidèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Quand ils eurent achevé, ils rapportèrent au roi et à Joad le reste de l\'argent, et l\'on fit des vases pour le temple du Seigneur, des ustensiles pour le service des holocaustes, des encensoirs d\'or et d\'argent. Enfin, on offrit des holocaustes perpétuels, tant que vécut Joad.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Et Joad devint vieux, et plein de jours, et il mourut âgé de cent trente ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'On l\'ensevelit en la ville de David avec les rois, parce qu\'il avait été bon envers Israël, envers Dieu et envers son temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Et après sa mort les princes de Juda entrèrent auprès de Joas, et ils se prosternèrent devant lui, et il leur prêta l\'oreille.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Et ils abandonnèrent le temple du Seigneur Dieu de nos pères, et ils servirent Astarté et les idoles; or, en ce jour-là, il y eut une colère du Seigneur contre Juda et contre Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Il leur envoya des prophètes pour les ramener à lui; mais, ils ne les écoutèrent pas; il leur signifia sa volonté; mais, ils n\'obéirent pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Alors l\'Esprit de Dieu vint sur Zacharie, fils de Joad, le prêtre, et il se plaça devant le peuple, et il s\'écria: Voici ce que dit le Seigneur: Pourquoi transgressez-vous les commandements du Seigneur? Vous ne prospèrerez pas, car vous avez abandonné le Seigneur, et il vous abandonnera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Mais, ils se jetèrent sur lui, et, par l\'ordre du roi Joas, ils le lapidèrent dans le parvis du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Ainsi, Joas oublia les bienfaits de Joad, et il fit lapider son fils. Celui-ci dit en mourant: Que le Seigneur voie et juge.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Et après que l\'année eut fini son cours, l\'armée syrienne marcha contre Joas; elle attaqua Juda et Jérusalem; elle extermina, au milieu du peuple, tous les princes, et elle envoya leurs dépouilles au roi de Damas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Elle était venue peu nombreuse; mais Dieu lui avait livré une grande armée, parce que les fils de Juda avaient abandonné le Dieu de leurs pères, et que le Seigneur avait prononcé l\'arrêt de Joas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Et après que les Syriens se furent éloignés de celui-ci, lorsqu\'ils l\'eurent laissé aux prises avec des maux cruels, ses serviteurs eux-mêmes portèrent la main sur lui pour le punir d\'avoir versé le sang du fils de Joad le prêtre; ils le tuèrent sur sa couche, et il mourut; et on l\'ensevelit dans la ville de David, mais non dans le sépulcre des rois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Et ceux qui l\'avaient assailli étaient Zabed, fils de Samaath l\'Ammonite, et Jozabed, fils de Samareth le Moabite,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Et tous les fils de ce dernier, car il y en avait cinq, qui se joignirent à lui. Le reste est écrit aux Récits des rois; et Amasias, fils de Joas, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amasias avait vingt-cinq ans lorsqu\'il monta sur le trône, et il régna vingt-neuf ans à Jérusalem; sa mère s\'appelait Joadan de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Et il fit ce qui est droit devant\' Dieu, mais non avec plénitude de cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Lorsqu\'il eut affermi sa royauté, il fit mettre à mort les serviteurs qui avaient tué le roi, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Mais il ne fit pas périr leurs fils, se conformant à l\'alliance de la loi du Seigneur. Car il est écrit, et tel est le commandement de Dieu: Les pères ne mourront pas à cause de leurs enfants, et les fils ne mourront pas à cause de leurs pères; mais chacun portera la peine de son péché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Ensuite, Amasias assembla la maison de Juda, et il les mit par familles paternelles sous des chefs de mille hommes et des centeniers, en Juda et en Jérusalem; il fit le dénombrement du peuple depuis vingt ans et au-dessus, et il trouva trois cent mille hommes capables de faire la guerre, sachant manier la javeline et le bouclier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Il enrôla de plus cent mille hommes d\'Israël, vaillants et robustes, au prix de cent talents d\'argent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Mais un homme de Dieu vint le trouver, disant: Roi, n\'emmène pas avec toi les troupes d\'Israël, car le Seigneur n\'est point avec Israël, ni avec aucun des fils d\'Ephraïm.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Si tu les prends pour te renforcer, le Seigneur te mettra en fuite devant tes ennemis; car il appartient au Seigneur de renforcer une armée ou de la mettre en fuites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Alors, Amasias dit à l\'homme de Dieu: Que deviendront les cent talents d\'argent que j\'ai donnés aux troupes d\'Israël? Et l\'homme de Dieu répondit: Il ne tient qu\'au Seigneur de t\'en rendre beaucoup plus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Et Amasias éloigna l\'armée qui était venue près de lui d\'Ephraïm, pour que chacun retournât en sa demeure. Et ils se courroucèrent vivement contre Juda, et ils s\'en allèrent chez eux la colère dans l\'âme.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Et Amasias se fortifia, et il prit son peuple, et il alla dans le val des Sels, et il tailla en pièces dix mille des fils de Seïr.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Et les fils de Juda firent, en outre, dix mille prisonniers; ils les transportèrent sur la cime du précipice, et ils les jetèrent au bas des rochers, et ces hommes furent déchirés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Et les hommes de l\'armée qu\'Amasias avait congédiés, pour qu\'ils n\'allassent pas en guerre avec lui, attaquèrent les villes de Juda, depuis Samarie jusqu\'à Béthoron, et ils y tuèrent trois mille hommes, et ils y firent un riche butin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Or, après qu\'Amasias revint ayant vaincu l\'Idumée, il en rapporta les dieux des fils de Séir, et il les tint pour des dieux véritables, et il se prosterna devant eux, et il leur fit des sacrifices.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Et la colère du Seigneur s\'enflamma centre Amasias, et il lui envoya le prophète, qui lui dit: Pourquoi as-tu cherché les dieux d\'un peuple qu\'ils n\'ont pu délivrer de tes mains?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Et, pendant que le prophète parlait encore, Amasias dit: Est-ce que je t\'ai fait conseiller du roi? Contiens-toi, si tu ne veux être fustigé. Et le prophète garda le silence, et il se dit: Je sais que le Seigneur a résolu de te détruire, parce que tu as fais cette chose, et que tu refuses d\'écouter mes conseils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Ensuite, Amasias, roi de Juda, délibéra, et il envoya dire à Joas, fils de Joachaz, fils de Jéhu, roi d\'Israël: Viens, que nous nous voyions face à face.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Et Joas, roi d\'Israël, envoya dire à Amasias: Le chardon du Liban envoya dire au cèdre du Liban: Donne en mariage ta fille à mon fils; mais voilà que les bêtes fauves des campagnes, qui sont dans le Liban, allaient venir, et les bêtes fauves vinrent, et elles foulèrent aux pieds le chardon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Or, tu as dit: Voilà que j\'ai vaincu l\'Idumée. Et ton cœur impérieux s\'est enorgueilli; reste donc en repos dans ta maison; car, pourquoi te mettre aux prises avec le malheur? Tu tomberas, et Juda avec toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Mais Amasias ne l\'écouta pas, car le Seigneur avait dessein de le livrer aux mains de Joas, parce qu\'il avait cherché les dieux d\'Edom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Joas, roi d\'Israël, partit donc, et les deux rois se virent l\'un l\'autre à Bethsamys en Judée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Et Juda tourna le dos devant Israël, et chacun s\'enfuit en sa demeure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Et Joas fit Amasias prisonnier, et il le ramena à Jérusalem; et il abattit un pan des remparts, long de quatre cents coudées, depuis la porte d\'Ephraïm jusqu\'à la porte de l\'angle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Et il prit l\'argent, l\'or, tous les ornements qu\'il trouva dans le temple du Seigneur, ce qui provenait d\'Abdedom, les trésors du palais du roi, des otages, et il retourna dans Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Amasias, fils de Joas, roi de Juda, vécut encore quinze ans après la mort de Joas, fils de Joachaz, roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Les restes des actes d\'Amasias, les premiers et les derniers, ne sont-ils pas écrits au livre des Rois de Juda?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Dans le temps où Amasias s\'était éloigné du Seigneur, un complot éclata contre lui, et il s\'enfuit de Jérusalem à Lachis; mais les révoltés envoyèrent à sa poursuite, et, en cette ville, ils le tuèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Et ils l\'enlevèrent sur un char, et ils l\'ensevelirent auprès de ses pères dans la ville de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Tout le peuple de la terre prit alors Ozias, qui avait seize ans, et ils le proclamèrent roi à la place d\'Amasias, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Il rebâtit Elath, et la rendit à Juda lorsque le roi se fut endormi avec ses pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Ozias avait seize ans quand il monta sur le trône, et il régna cinquante- deux ans à Jérusalem; sa mère s\'appelait Jéchélie de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Et il fit ce qui est droit devant le Seigneur, comme avait fait d\'abord Amasias, son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Il chercha le Seigneur tant que vécut Zacharie, homme sage et craignant Dieu; tant qu\'il vécut, Ozias chercha le Seigneur, et le Seigneur le fit prospérer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Il se mit en campagne, combattit les Philistins, renversa les murs de Geth, les murs de Jabner, les murs d\'Azot, et bâtit des villes, près d\'Azot, sur la terre des étrangers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Et le Seigneur le fortifia contre les Philistins, contre les Arabes qui habitent au milieu des rochers, et contre les Minéens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Alors, les Minéens lui firent des présents, et son nom se répandit jusqu\'à l\'entrée de l\'Égypte; car il se fortifia extrêmement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Ozias bâtit aussi des tours dans Jérusalem: sur la porte de l\'Angle, sur la porte de la Vallée, sur les angles, et il les fortifia.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Et il bâtit des tours dans le désert, et il fit, en pierres de taille, une multitude de citernes, parce qu\'il possédait de nombreux troupeaux dans les basses terres et dans la plaine, et il employait beaucoup de vignerons sur la montagne et sur le Carmel, car il était cultivateur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Son armée était aguerrie; au dehors, elle se rangeait en bataille; à l\'intérieur, elle se déployait pour qu\'on en fit la revue; ceux qui la dénombraient étaient le scribe Jehiel, le juge Maasias, et Ananias le lieutenant du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Le nombre des vaillants, chefs de familles, qui allaient en guerre, s\'élevait à deux mille deux cents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Et ils commandaient une armée aguerrie de trois cent soixante-dix mille cinq cents hommes, qui marchaient au combat, pleins de force et de vaillance, pour défendre le roi contre ses ennemis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Ozias les avait tous armés de longs boucliers, de javelines, de casques, d\'arcs et de frondes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Et il fit exécuter à Jérusalem des machines, œuvres d\'un habile calculateur, pour être sur les tours et sur les angles, ou pour lancer des traits ou de grosses pierres; partout, même au loin, on parla beaucoup de ses engins; car il en était merveilleusement secouru, et en tirait une grande force.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mais, comme il se fortifiait, son cœur s\'enorgueillit pour sa perte; et il pécha contre le Seigneur son Dieu, et il entra dans le temple du Seigneur pour brûler de l\'encens sur l\'autel des parfums.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Et Azarias le prêtre y entra sur ses pas, accompagné de quatre-vingts prêtres du Seigneur, hommes intrépides.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Et ils s\'arrêtèrent devant le roi Ozias, et ils lui dirent: Ce n\'est pas à toi, Ozias, d\'encenser le Seigneur, mais aux prêtres, fils d\'Aaron, qui sont consacrés pour faire les sacrifices. Sors du Saint des saints, car tu t\'es séparé du Seigneur, et cela ne tournera pas à ta gloire auprès de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Mais Ozias s\'irrita; or, il avait à la main l\'encensoir pour brûler de l\'encens dans le temple, et, pendant qu\'il s\'irritait contre les prêtres, la lèpre parut sur son front, devant les prêtres dans le temple du Seigneur, au pied de l\'autel des parfums.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Et le grand prêtre Azarias et les prêtres, en se retournant vers lui, virent la lèpre sur son front; ils eurent hâte de le faire sortir, et lui-même n\'était pas moins empressé, car le Seigneur l\'avait châtié.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Le roi Ozias resta lépreux jusqu\'au jour de sa mort; et lépreux, il demeura dans une maison isolée, parce qu\'il avait été retranché du temple du Seigneur. Et Joatham, son fils, fut mis à la tête du royaume, jugeant le peuple de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Le reste des actes d\'Ozias, les premiers et les derniers, ont été écrits par le prophète Jessé (Isaïe).');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Et Ozias s\'endormit avec ses pères, et on l\'ensevelit auprès d\'eux, dans le champ où est le sépulcre des rois, parce que, dirent-ils, il était lépreux. Et Joatham, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Joatham avait vingt-cinq ans lorsqu\'il monta sur le trône, et il régna seize ans à Jérusalem; sa mère s\'appelait Jerusa, fille de Sadoc.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Et il fit ce qui est droit devant le Seigneur, comme avait fait Ozias, son père; mais il n\'entra point dans le temple du Seigneur, et le peuple, encore une fois, se corrompit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Ce fut lui qui bâtit la porte du temple la plus élevée, et il ajouta beaucoup de constructions au mur d\'Ophel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Dans la montagne de Juda et dans les bois, il éleva des maisons et des tours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Il combattit le roi des fils d\'Ammon, et le vainquit; les fils d\'Ammon alors lui donnèrent par année cent talents d\'argent, dix mille mesures de froment et dix mille mesures d\'orge. Il reçut ce tribut la première année, et la seconde, et la troisième.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Joatham avait été vainqueur, parce qu\'il avait marché dans les voies du Seigneur son Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Le reste des actes de Joatham, et sa guerre, et ses faits et gestes sont écrits au livre des Rois de Juda et d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Et Joatham s\'endormit avec ses pères, et on l\'ensevelit en la ville de David, et son fils Achaz régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Et Joatham s\'endormit avec ses pères, et on l\'ensevelit en la ville de David, et son fils Achaz régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Achaz avait vingt-cinq ans lorsqu\'il monta sur le trône, et il régna seize ans à Jérusalem; et il ne fit point ce qui est droit devant le Seigneur, comme David, son aïeul.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Mais il marcha dans les voies des rois d\'Israël, car il fit des sculptures,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Et il sacrifia à leurs idoles dans le val de Benennom, et il fit passer ses enfants à travers la flamme; selon les abominations des peuples que le Seigneur avait exterminés devant les fils d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Et il brûla de l\'encens sur les hauts lieux, et sur les terrasses des maisons, et sous les arbres touffus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Alors le Seigneur Dieu le livra au roi de Syrie; il le frappa par ses mains, en permettant aux Syriens d\'emmener à Damas une multitude de captifs; il le livra aussi au roi d\'Israël, et de ses propres mains, il le frappa d\'une grande plaie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Phacée, fils de Romélie, roi d\'Israël, tua, en un seul jour, cent vingt mille hommes de Juda, forts et vaillants, parce qu\'ils avaient abandonné le Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Et Zéchri, homme vaillant d\'Ephraïm, tua Maasias, fils du roi; Esrican, son grand maître du palais, et Elcana, son lieutenant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Et les fils d\'Israël firent parmi leurs frères trois cent mille captifs: femmes, fils et filles; et ils leur enlevèrent un immense butin, et emportèrent les dépouilles à Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Or, il y avait là un prophète du Seigneur nommé Obed, qui sortit à la rencontre de l\'armée pendant qu\'elle revenait à Samarie, et il leur dit: Voilà que la colère du Seigneur Dieu de vos pères est sur Juda; il vous les a livrés, et vous les avez massacrés avec fureur, et le bruit en est monté jusqu\'au ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Et maintenant vous pensez garder comme esclaves les fils de Juda et de Jérusalem; mais ne suis-je point parmi vous pour prendre à témoin le Seigneur votre Dieu?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Écoutez-moi donc, et délivrez les captifs que vous avez enlevés chez vos frères; car la colère du Dieu terrible est sur vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Et les chefs des fils d\'Ephraïm: Udie, fils de Jean; Barachias, fils de Mosolmoth; Ezéchias, fils de Sellem; et Amasias, fils d\'Eldaï, s\'élevèrent pareillement contre ceux qui revenaient du combat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'Et ils leur dirent: Vous n\'introduirez point ici, chez nous, ces captifs; car, lorsque vous péchez contre le Seigneur, votre péché retombe sur nous; et vous entendez ajouter à vos péchés et à vos délits par ignorance, quand déjà vos fautes sont nombreuses, et quand une terrible colère du Seigneur est sur Israël?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Et les guerriers mirent en liberté les captifs, et ils leur rendirent les dépouilles, devant les chefs de toute l\'Église.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Et les hommes qui viennent d\'être nominativement désignés, se levèrent, prirent soin des captifs, les vêtirent d\'objets compris dans les dépouilles, les habillèrent, les chaussèrent, leur donnèrent des vivres pour manger, de l\'huile pour se parfumer, firent monter les infirmes sur des ânes, les menèrent avec leurs frères jusqu\'à Jéricho, ville des palmiers, et retournèrent à Samarie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'En ce temps-là, le roi Achaz envoya chez le roi assyrien demander son secours,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Et voici pourquoi: les Sidoniens faisaient des irruptions; ils frappaient Juda, et lui enlevaient des captifs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Les Philistins aussi avaient pris les armes contre les villes de la plaine, au midi de Juda, et s\'étaient emparés de Bethsamys,, de Galero, de Socho et de ses bourgs, de Thamna et de ses bourgs, de Gamzo et de ses bourgs, et ils s\'y étaient établis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Car le Seigneur avait humilié Juda, à cause du roi Achaz qui s\'était détourné du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Alors, Thelgath-Phalnasar, roi des Assyriens, intervint, mais contre lui, et il l\'opprima.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Et Achaz prit les richesses du temple du Seigneur, celles du palais du roi, celles des demeures des princes,, et il les donna au roi assyrien; or, celui-ci n\'était pas venu pour le secourir,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Mais pour l\'écraser; cependant, le roi Achaz continua de se détourner du Seigneur, et il dit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Je chercherai les dieux de Damas qui me frappent. Puis, il ajouta: Ce sont les dieux du roi de Syrie qui lui donnent de la force; je leur sacrifierai donc, et ils me protégeront. Et ils furent une cause de chute pour lui et pour Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Achaz retira donc les vases du temple du Seigneur, il les brisa, ferma les portes du temple, et se fit des autels dans tous les carrefours de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Et il établit des hauts lieux dans toutes les villes de Juda pour que l\'on y encensât des dieux étrangers; et les fils de Juda excitèrent le courroux du Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Le reste de ses faits et gestes, les premiers et les derniers, sont écrits au livre des Rois de Juda et d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Et Achaz s\'endormit avec ses pères, et il fut enseveli en la ville de David; mais on ne le transporta pas dans le sépulcre des rois d\'Israël, et son fils Ezéchias régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezéchias avait vingt-cinq ans lorsqu\'il monta sur le trône, et il régna vingt-neuf ans à Jérusalem; sa mère s\'appelait Abia, fille de Zacharie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Et il fit ce qui est droit devant le Seigneur, se conformant à tout ce qu\'avait fait David, son aïeul.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Dès qu\'il fut affermi dans son royaume, le premier mois, il ouvrit les portes du temple du Seigneur, et il les restaura.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Et il introduisit dans le temple les prêtres et les lévites, et il les réunit dans l\'aile orientale de l\'édifice.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Et il leur dit: Écoutez, lévites, purifiez-vous d\'abord; puis, vous purifierez le temple du Dieu de vos pères, et vous rejetterez toute impureté du lien saint.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Car VOS père se sont pervertis et ils ont fait le mal devant le Seigneur notre Dieu; ils l\'ont abandonné, ils ont détourné leur face du tabernacle du Seigneur, et s\'en sont éloignés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Ils ont fermé les portes du temple, ils ont éteint les lampes, ils n\'ont plus brûlé d\'encens, ils ont cessé d\'offrir des holocaustes dans le lieu saint du Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Alors, le Seigneur s\'est vivement irrité contre Juda et contre Jérusalem; il les a livrés au trouble, à l\'extermination et aux railleries, comme vous l\'avez vu de vos yeux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Vos pères ont été frappés par le glaive; vos fils, vos filles et vos femmes, ont été emmenés captifs en une contrée étrangère, où ils sont encore.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'A cause de cela, il est maintenant en mon cœur de faire alliance avec le Seigneur Dieu d\'Israël, et il détournera de nous sa terrible colère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Ne différez pas, car le Seigneur vous a choisis pour que vous vous teniez en sa présence, pour que vous le serviez et que vous brûliez devant lui de l\'encens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Et les lévites se levèrent, savoir: Des fils de Caath, Maath, fils d\'Amasi, et Johel, fils d\'Azarias; des fils de Mérari: Cis, fils d\'Abdi, et Azarias, fils d\'Ilaélel; des fils de Gerson: Jodaad, fils de Zemmath, et Joadam; ceux-ci descendaient de Joacha;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Des fils d\'Elisaphan: Zambri et Jehiel; des fils d\'Asaph: Zacharie et Matlhanias;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Des fils d\'Hêman: Jehiel et Sémeï; des fils d\'Idithun: Samaias et Oziel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Et ils réunirent leurs frères, et ils se purifièrent selon l\'ordre du roi, pour purifier ensuite le peuple du Seigneur, comme lui-même l\'avait prescrit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Et les prêtres entrèrent dans le temple du Seigneur pour le purifier, et ils rejetèrent toute impureté qu\'ils trouvèrent dans le temple et dans le parvis; puis, les lévites prirent les choses impures pour les porter au torrent de Cédron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'La purification commença le premier jour du premier mois, pendant la nouvelle lune, et, le huitième jour, ils entrèrent dans le temple du Seigneur, et ils le purifièrent en huit jours; le seizième jour du premier mois, tout était terminé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Et ils allèrent trouver le roi Ezéchias, et ils lui dirent: Nous avons tout purifié dans le temple du Seigneur: l\'autel des holocaustes et ses ustensiles, la table de proposition et ses accessoires.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Tous les objets que le roi Achaz avait souillés pendant son règne et son apostasie, nous les avons purifiés \'et mis en ordre; voilà que tout est exposé devant l\'autel du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Et le roi Ezéchias se leva de grand matin, et il assembla tous les chefs de la ville, et il monta au temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Et il offrit sept bœufs, sept béliers, sept agneaux et sept boucs, pour les péchés, pour le royaume, pour les saints et pour Israël; et il dit aux prêtres, fils d\'Aaron, de monter à l\'autel du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Et ils immolèrent les bœufs, et ils recueillirent le sang, et ils le répandirent sur l\'autel; et ils immolèrent les béliers, et ils répandirent le sang sur l\'autel; et ils immolèrent les agneaux, et ils répandirent le sang sur l\'autel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Et ils traînèrent devant le roi et devant l\'assemblée entière les boucs pour les péchés, et ils imposèrent sur eux les mains;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Et les prêtres les immolèrent, et ils firent l\'expiation en versant leur sang devant l\'autel, et ils firent l\'expiation en faveur de tout Israël; car le roi avait dit: L\'holocauste et le sacrifice pour les péchés sont pour tout Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Et il établit les lévites dans le temple du Seigneur au son des cymbales, des cithares et des harpes, comme l\'avait réglé le roi David, d\'accord avec Gad le voyant, et Nathan le prophète; car le Seigneur transmet ses commandements par les prophètes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Les lévites furent installés au son des instruments de David, et les prêtres au son des trompettes sacrées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Ensuite, Ezéchias ordonna de porter l\'holocauste sur l\'autel; et, lorsque l\'on commença l\'offrande de l\'holocauste, on commença à chanter les louanges du Seigneur, au son des trompettes et des instruments de David, roi d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Et toute l\'Église adora, et les chantres-harpistes chantèrent, et les trompettes sonnèrent jusqu\'à ce que l\'holocauste fût achevé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Et, lorsque les victimes furent consumées, le roi se prosterna, ainsi que toute l\'assistance, et ils adorèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Et le roi Ezéchias et les princes dirent aux lévites de chanter au Seigneur les psaumes tant du roi David que du prophète Asaph; ils chantèrent avec allégresse; puis, se prosternant, ils adorèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Et le roi Ézéchias prit la parole, et dit: Maintenant que vous vous êtes consacrés au Seigneur, amenez et offrez les victimes de louanges dans le temple du, Seigneur; et l\'Église offrit dans le temple des sacrifices et des louanges; et ceux qui avaient le cœur plein de zèle amenèrent des holocaustes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Voici le nombre des holocaustes qu\'offrit l\'Église: soixante-dix bœufs, cent béliers, deux cents agneaux; tous pour les holocaustes au Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Il y eut en outre: six cents bœufs consacrés, et trois mille brebis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Or, les prêtres étaient en petit nombre, et ils ne suffisaient pas à enlever les peaux des victimes; leurs frères, les lévites, les aidèrent jusqu\'à ce que l\'œuvre fût achevée, et que les prêtres se fussent purifiés; car les lévites sont plus promptement purifiés que les prêtres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Il y eut donc nombre de victimes pour les holocaustes; on brûla en grande quantité la graisse des hosties pacifiques, on répandit à flots les libations de l\'holocauste, et les cérémonies du temple furent rétablies.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Et Ezéchias et tout le peuple ressentirent une vive allégresse de ce que Dieu avait préparé cette fête à son peuple; car la chose s\'était faite soudainement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Et Ézéchias envoya en tout Israël et en Juda, et il écrivit des lettres à Ephraïm et à Manassé, pour qu\'ils vinssent au temple du Seigneur à Jérusalem, faire la Pâque du Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Et le roi, et les princes et toute l\'Église de Jérusalem, résolurent de faire la Pâque le second mois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Car ils ne la pouvaient faire en ce moment, parce qu\'il n\'y avait point assez de prêtres consacrés, et que tout le peuple n\'était point réuni à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Et cette décision fut agréable au roi et à toute l\'Église.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Ils ordonnèrent aussi que l\'on proclamât en tout Israël, depuis Bersabée jusqu\'à Dan, que l\'on eût à venir pour faire la Pâque du Seigneur Dieu à Jérusalem; car la multitude ne l\'avait jamais faite comme le prescrit l\'Écriture.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Les courriers, avec les lettres du roi et des princes, parcoururent tout Juda et tout Israël, selon l\'ordre d\'Ézéchias, et ils dirent: Fils d\'Israël, revenez au Seigneur Dieu d\'Abraham, d\'Isaac et d\'Israël; ramenez ceux de vous qui survivent et qui ont échappé aux mains du roi d\'Assyrie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Ne soyez pas comme vos pères et vos frères; ils se sont séparés du Seigneur Dieu de leurs pères, et le Seigneur les a livrés à la dévastation, comme vous avez vu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Maintenant donc, n\'endurcissez point vos cœurs comme vos pères; glorifiez le Seigneur votre Dieu, entrez dans le lieu saint qu\'il a consacré pour toujours; servez le Seigneur votre Dieu, et il détournera de vous sa terrible colère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Car, lorsque vous serez revenus au Seigneur, vos frères et vos enfants trouveront miséricorde chez ceux qui les ont emmenés captifs, et Dieu vous les ramènera en cette terre; car le Seigneur notre Dieu est miséricordieux et compatissant, et il ne détournera point de vous sa face, si nous retournons à lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Et les courriers passèrent de ville en ville, dans les montagnes d\'Ephraïm et de Manassé, jusqu\'à Zabulon, et ils furent un sujet de risée et de raillerie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Toutefois, des hommes d\'Aser, de Manassé et de Zabulon, rentrèrent en eux-mêmes, et vinrent à Jérusalem en Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Car la main du Seigneur excita leur cœur à partir et à suivre les ordres du roi et des princes, selon la parole du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Une grande multitude se réunit donc à Jérusalem pour faire la fête des azymes le second mois; l\'Église fut très-nombreuse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Et ils se levèrent, et ils abattirent dans Jérusalem tous les autels où l\'on brûlait de l\'encens pour les faux dieux; ils les enlevèrent et les jetèrent dans le torrent de Cédron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Et ils immolèrent la pâque le quatorzième jour de la seconde lune, et les prêtres et les lévites, s\'étant repentis et purifiés, offrirent des holocaustes dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Et chacun se tint à son rang, selon leur ordonnance et selon les commandements de Moïse, homme de Dieu; les prêtres reçurent le sang des mains des lévites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Car la plus grande partie de l\'Église ne s\'était point encore sanctifiée, et les lévites étaient prêts à immoler la pâque pour tous ceux qui n\'avaient pu se sanctifier au Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Parmi le peuple d\'Ephraïm, de Manassé, d\'Issachar, de Zabulon, le plus grand nombre ne s\'était pas purifié; mais ils mangèrent la pâque contrairement à l\'Écriture; à cause de cela, Ezéchias fit pour eux cette prière, disant: Que le Seigneur, dans sa bonté, soit propice');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'A tous les cœurs qui cherchent avec droiture le Seigneur Dieu de leurs pères, quoiqu\'ils n\'aient point la pureté que veulent les choses saintes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Et le Seigneur exauça Ezéchias, et il guérit tout le peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Et les fils d\'Israël, qui se trouvaient à Jérusalem, firent la fête des Azymes sept jours, en grande allégresse, célébrant chaque jour le Seigneur; et les prêtres et les lévites accompagnaient leurs chants avec les instruments consacrés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Et Ezéchias parla au cœur des lévites et de tous ceux qui comprenaient le mieux le Seigneur, et ils firent la fête des Azymes sept jours, sacrifiant l\'hostie pacifique, et rendant gloire au Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Et l\'Église résolut de fêter une seconde fois sept jours, et ils les fêtèrent avec joie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Car Ezéchias offrit à Juda et à l\'Église mille bœufs et sept mille brebis, et les princes amenèrent, pour le peuple, mille bœufs et dix mille brebis, et il y eut une multitude de prêtres qui furent sanctifiés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Et toute l\'Église était pénétrée de joie: prêtres, lévites, Église de Juda, peuple réuni à Jérusalem, prosélytes venus de la terre d\'Israël, étrangers habitant Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Et l\'allégresse fut grande en Jérusalem; on n\'y avait point vu pareille fête depuis les jours de Salomon et de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Et les prêtres et les lévites se levèrent, et ils bénirent le peuple, et leur voix fut entendue, et leur prière monta jusqu\'aux saintes demeures de Dieu dans le ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Et, quand tout fut fini, ceux d\'Israël qui se trouvaient dans les villes de Juda sortirent, brisèrent les Colonnes, arrachèrent les bois sacrés, démolirent les hauts lieux et les autels, dans tout Juda, dans Benjamin, dans Ephraïm, dans Manassé jusqu\'à la fin; et ceux d\'Israël rentrèrent chacun en son héritage et en sa ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Et Ezéchias régla les services des prêtres et des lévites, chacun selon son emploi, tant pour les holocaustes que pour les hosties pacifiques, les louanges, les actions de grâces, et la garde des portes ou des parvis du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Il régla aussi la part que devait donner le roi, de ce qui lui appartenait, pour les holocaustes du matin et du soir, pour les holocaustes des sabbats, des nouvelles lunes et des fêtes désignées en la loi du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Et il dit au peuple qui habitait Jérusalem de donner la part des prêtres et des lévites, afin qu\'ils fussent affermis dans le service du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Or, dès qu\'il eut ordonné ces choses, Israël apporta en abondance les prémices du blé, du vin, de l\'huile, du miel et de ce que produisent les champs; les fils d\'Israël et de Juda apportèrent des dîmes abondantes de tous leurs fruits.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Et ceux qui habitaient les villes de Juda offrirent aussi la dîme de leurs bœufs, de leurs brebis, de leurs chèvres; et ils la consacrèrent au Seigneur leur Dieu, et ils apportèrent, et ils offrirent de toutes choses des monceaux, des monceaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Et ils commencèrent, le troisième mois, à empiler ces monceaux, et eurent fini le septième mois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Et le roi Ezéchias et les princes vinrent, et ils virent ces monceaux, et ils bénirent le Seigneur et son peuple Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Et Ezéchias questionna les prêtres et les lévites au sujet de ces monceaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Et le prêtre Azarias, chef de la maison de Sadoc, lui dit: Depuis que l\'on apporte de ces prémices dans le temple du Seigneur, nous avons bu, nous avons mangé et nous avons laissé beaucoup; car le Seigneur a béni son peuple, et ces monceaux nous sont restés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Et le roi ordonna que l\'on préparât des magasins dans le temple du Seigneur, et on les prépara.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Et l\'on y transporta fidèlement les prémices et les dîmes, dont on donna l\'intendance au lévite Honénias et à Sémei, son frère et son lieutenant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Et Jehiel, Ozias, Naeth, Azaël, Jerimoth, Jozabad, Elihel, Samachie, Maath, Banaïas et ses fils, furent subordonnés à Honénias et à son frère Sémeï; ainsi que l\'ordonnèrent le roi Ezéchias et Azarias, qui avait le premier rang dans le temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Et Coré le lévite, fils de Jemna, gardien de la porte orientale, eut l\'intendance des dons que l\'on faisait, soit comme prémices du Seigneur, soit pour le Saint des saints,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Par les mains d\'Odom, de Benjamin, de Jésué, de Sémei, d\'Amarias et de Séchonias, ou par celles des prêtres à qui l\'on se confiait; et ils en faisaient la distribution à leurs frères, selon leurs services journaliers, du petit au grand,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Hormis les enfants mâles de trois ans et au-dessous, à tous ceux qui entraient dans le temple du Seigneur, selon l\'ordre des jours, pour s\'acquitter des fonctions qui leur étaient assignées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Ainsi se fit la distribution aux prêtres, par familles paternelles. Quant aux lévites de vingt ans et au-dessus, pendant leurs services journaliers,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Ils purent, dans leur classification, compter même leurs jeunes enfants, fils ou filles, quel qu\'en fût le nombre, parce qu\'ils avaient purifié fidèlement le sanctuaire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Aux fils d\'Aaron, exerçant le sacerdoce dans les villes, des hommes, nommés à cet effet en chaque ville, donnaient aussi une portion pour chaque mâle, parmi les prêtres; ils en donnaient pareillement à ceux qui étaient comptés comme lévites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Ezéchias établit cet ordre en tout Juda, et il fit ce qui est bon et droit devant le Seigneur son Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Et en toute œuvre qu\'il entreprit dans le temple du Seigneur, dans ses lois, dans ses ordonnances, il chercha son Dieu de toute son âme, et il agit, et il prospéra.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Or, après ces choses faites avec sincérité, Sennachérib, roi des Assyriens, vint envahir Juda, et campa devant les villes fortes pour s\'en emparer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Et Ezéchias vit que Sennachérib s\'avançait et menaçait Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Et il tint conseil avec ses anciens et ses vaillants, leur proposant de clore les fontaines hors de la ville; et ils l\'appuyèrent de toute leur force.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Il assembla donc beaucoup de monde, et il renferma en des murs les eaux des fontaines, ainsi que le ruisseau qui traverse la ville, disant: C\'est de peur que le roi d\'Assyrie, venant, ne trouve une abondance d\'eau qui le fortifierait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Et Ezéchias augmenta ses défenses; il rétablit toutes les parties des remparts qui s\'étaient écroulées et les tours; il bâtit en dehors une seconde enceinte, il releva les fortifications de la ville de David; enfin, il fit faire beaucoup d\'armes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Ensuite, il mit des chefs de guerre à la tête du peuple qui s\'assembla devant lui sur l\'esplanade, vers la porte de la Vallée, et il lui parla au cœur, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Soyez forts, agissez en hommes, n\'ayez ni crainte ni faiblesse devant le roi d\'Assyrie, et devant les peuples qui le suivent; car il y a plus d\'auxiliaires avec nous qu\'avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Il a pour lui des bras de chair; nous, nous avons le Seigneur notre Dieu, qui combattra pour nous et nous sauvera. Et le peuple fut encouragé par le discours d\'Ezéchias, roi de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Après cela, Sennachérib, roi des Assyriens, envoya ses serviteurs à Jérusalem, et lui-même, avec toute son armée, était autour de Lachis, et il envoya ses serviteurs au roi Ezéchias et à tout le peuple de Juda renfermé dans Jérusalem, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Voici ce que dit Sennachérib, roi des Assyriens: Sur quoi vous appuyez- vous pour rester immobiles dans l\'enceinte de Jérusalem?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Ezéchias ne vous a-t-il pas trompés, pour vous livrer à la faim, à la soif, à la mort, quand il vous a dit: Le Seigneur notre Dieu nous sauvera des mains du roi d\'Assyrie?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'N\'est-ce point cet Ezéchias qui a détruit ses autels et ses hauts lieux, et qui a dit à Juda et à Jérusalem: Vous adorerez sur cet autel, et, sur cet autel, vous offrirez de l\'encens?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ignorez-vous ce que moi et mes pères avons fait aux peuples de toute la terre? Parmi les dieux des nations de la terre, en est-il un seul qui ait pu sauver son peuple de mes mains?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Qui l\'a fait, parmi les dieux des nations que nos pères ont exterminées? Si nul d\'eux n\'a pu sauver son peuple de nos mains, votre Dieu pourra t-il le faire?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Qu\'Ezéchias cesse donc de vous tromper, qu\'il ne vous inspire pas une folle confiance, ne le croyez pas; car nul, des dieux des nations et des royaumes, n\'a pu sauver son peuple de mes mains et des mains de nos pères, et votre Dieu ne vous sauvera pas non plus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Or, les serviteurs de Sennachérib continuèrent de parler contre le Seigneur Dieu et contre son serviteur Ezéchias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Lui-même écrivit une lettre pour outrager le Seigneur Dieu d\'Israël, et il dit: De même que les dieux des nations de la terre n\'ont pu délivrer leurs peuples de mes mains, le Dieu d\'Ezéchias ne pourra en aucune manière sauver son peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Et l\'un des serviteurs cria, en langue judaïque, au peuple de Jérusalem qui se tenait sur les remparts, l\'invitant à haute voix à les seconder à démolir les murailles, à leur livrer la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Il parla aussi contre le Seigneur Dieu d\'Israël, de la même manière que contre les dieux des nations de la terre, œuvres des mains des hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Et, sur ces paroles, le roi Ezéchias et le prophète Isaïe, fils d\'Amos, prièrent, et crièrent au ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Et le Seigneur envoya un ange, et il extermina dans le camp assyrien tous les combattants, les chefs et les généraux. Et Sennachérib, la honte au front, retourna en son royaume, et il entra dans le temple de son Dieu; et des hommes, issus de son sang, le firent périr par le glaive.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Et le Seigneur sauva Ezéchias, ainsi que les habitants de Jérusalem, des mains de Sennachérib, roi d\'Assyrie, et des mains de tous les rois, et il leur donna le repos tout alentour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Et nombre de gens apportèrent à Jérusalem des présents pour le Seigneur et pour Ezéchias, roi de Juda, et, après cela, il fut glorifié aux yeux de toutes les nations.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'En ces jours-là, Ezéchias tomba malade à en mourir, et il pria le Seigneur, et le Seigneur l\'exauça, et il lui donna un signe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Mais Ezéchias ne lui rendit pas selon ce qu\'il en avait reçu; son cœur s\'enorgueillit, et la colère du Seigneur éclata contre le roi, contre Juda, contre Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Et Ezéchias s\'humilia de s\'être enorgueilli en son cœur, et, avec lui, tous les habitants de Jérusalem; et la colère du Seigneur ne vint plus sur eux tant que vécut Ezéchias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Et Ezéchias eut beaucoup de gloire et de richesses; il amassa, en ses trésors, de l\'or, de l\'argent, des pierreries; il eut des épices, des vases de prix et des arsenaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Il eut des villes où l\'on conservait du blé, du vin et de l\'huile; il eut des villages et des étables pour toute sorte de bétail, et des bergeries pour les menus troupeaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Il eut des villes, qu\'il bâtit pour lui-même, et une grande abondance de bœufs et de brebis; car le Seigneur lui donna d\'immenses richesses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Ce fut Ezéchias qui fit l\'aqueduc qui amena les eaux de la haute fontaine de Gihon en la ville basse de David, au midi. Ezéchias réussit en toutes ses entreprises.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Néanmoins, le Seigneur l\'abandonna pour l\'éprouver et savoir ce qu\'il avait dans le cœur, lorsque les envoyés des chefs de Babylone vinrent le trouver et le questionner sur le prodige qui avait éclaté en la terre promise.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Le reste des actes d\'Ezéchias et sa miséricorde sont écrits en la prophétie d\'Isaïe, fils d\'Amos, le prophète, et au livre des Rois de Juda et d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Et Ezéchias s\'endormit avec ses pères, et on l\'ensevelit au-dessus des sépulcres des fils de David; et tout Juda et les habitants de Jérusalem l\'honorèrent et le glorifièrent à sa mort. Et Manassé, son fils, régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manassé avait douze ans lorsqu\'il monta sur le trône, et il régna cinquante-cinq ans à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Il fit le mal devant le Seigneur, et commit toutes les abominations des peuples que le Seigneur avait exterminés devant Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Il se pervertit, et il releva les hauts lieux qu\'avait détruits Ezéchias, son père; il dressa des colonnes à Baal, planta des bois sacrés, adora toute l\'armée du ciel, et la servit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Et il bâtit des autels dans le temple dont le Seigneur avait dit: Mon nom sera toujours dans Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Et il bâtit des autels à toute l\'armée du ciel, dans les deux parvis du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Et il fit passer ses enfants à travers la flamme dans le val de Benennom; et il consulta les devins, les augures et les sorciers; il accueillit des ventriloques et des enchanteurs; il fit de plus en plus le mal devant le Seigneur, pour exciter sa colère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Et il plaça des statues et des images en fonte dans le temple dont le Seigneur avait dit à David et à Salomon, son fils: En ce temple et à Jérusalem, que j\'ai choisis parmi toutes les tribus d\'Israël, j\'établirai mon nom pour toujours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Et je n\'éloignerai plus le pied d\'Israël de la terre que j\'ai donnée à leurs pères, pourvu qu\'ils soient attentifs à faire tout ce que je leur ai commandé, en se conformant à toute la loi, aux ordonnances et aux jugements donnés par la main de Moïse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Ainsi, Manassé égara Juda et les habitants de Jérusalem, pour qu\'ils fissent le mal, plus que toutes les nations que le Seigneur avait exterminées devant Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Et le Seigneur parla à Manassé et à son peuple; mais ils ne l\'écoutèrent pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Et le Seigneur conduisit contre eux les chefs de l\'armée du roi d\'Assyrie, et ils prirent Manassé, et ils le chargèrent de chaînes, et ils l\'emmenèrent à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Et, dans son affliction, il chercha la face du Seigneur son Dieu, et il s\'humilia beaucoup devant la face du Seigneur Dieu de ses pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Et il le pria; or, Dieu entendit ses cris; il l\'exauça, et le ramena à Jérusalem dans son royaume, et Manassé reconnut que le Seigneur seul est Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Après cela, il bâtit le mur extérieur de la ville de David, du côté du midi, au sud du torrent, depuis l\'entrée de la porte des Poissons, continuant tout autour jusqu\'à Ophel,; il l\'éleva beaucoup, et il établit des chefs de l\'armée dans toutes les places fortes de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Et il enleva les dieux étrangers et les statues du temple du Seigneur, et les autels qu\'il avait dressés sur la montagne du temple du Seigneur, tant dans Jérusalem que hors de la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Et il releva l\'autel du Seigneur, et il y sacrifia des hosties pacifiques et des victimes de louanges; et il dit à Juda de servir le Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Toutefois, le peuple sacrifia encore sur les hauts lieux; mais seulement au Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Le reste des actes de Manassé, sa prière à Dieu, et les paroles des voyants qui lui parlèrent au nom du Seigneur Dieu d\'Israël,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'La prière qu\'il fit à Dieu et qui fut exaucée, ses péchés, ses égarements, et les endroits où il bâtit des hauts lieux, et où il plaça des bois sacrés et des statues, avant de se convertir, sont écrits aux Récits des voyants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Et Manassé s\'endormit avec ses pères, et on l\'ensevelit dans le jardin de son palais, et son fils Amon régna à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amon avait vingt-deux ans quand il monta sur le trône, et il régna deux ans à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Et il fit le mal devant le Seigneur, comme avait fait son père; il sacrifia à toutes les idoles qu\'avait faites Manassé, et il les servit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Et il ne s\'humilia pas devant le Seigneur, comme s\'était humilié son père; et il multiplia ses péchés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Et ses serviteurs se soulevèrent contre lui, et ils le tuèrent dans son palais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Et le peuple de la terre massacra les révoltés, et il proclama roi, à la place d\'Amon, Josias, son fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Josias avait huit ans quand il monta sur le trône, et il régna trente et un ans à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Il fit ce que est droit devant le Seigneur, et il marcha dans les voies de David, son aïeul; il ne s\'en écarta ni à droite ni à gauche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Et, dans la huitième année de son règne, il était encore un adolescent quand il commença à chercher le Seigneur Dieu de David; et, dans la douzième année, il se mit à purifier Juda et Jérusalem des hauts lieux, des bois sacrés, des ornements des autels et des idoles jetées en fonte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Et il renversa, de devant sa face, les autels de Baal et, au-dessus d\'eux, les hauts lieux; il abattit les bois sacrés et les statues; il brisa les idoles jetées en fonte, il les réduisit en poudre, et les jeta sur la surface des tombeaux de ceux qui leur avaient sacrifié.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Et il brûla les ossements de leurs prêtres sur les autels; et il purifia Jérusalem et Juda,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Puis, les villes de Manassé, d\'Ephraïm, de Siméon et de Nephthali, et les bourgs qui les environnaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Et il détruisit les autels et les bois sacrés, et il réduisit en poudre les idoles, et il renversa tous les hauts lieux d\'Israël, et il revint à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Dans la dix-huitième année de son règne, après avoir purifié la terre et son palais, il envoya Saphan, fils d\'Ezélias, Maasa, chef de la ville, et Juach, fils de Joachaz, son secrétaire-archiviste, pour réparer le temple du Seigneur son Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Il se rendirent auprès d\'Helcias, le grand prêtre, et ils lui donnèrent l\'argent offert au temple de Dieu, recueilli, par les lévites gardiens de la porte, des mains de Manassé, d\'Ephraïm, des princes, de tout le reste d\'Israël, des fils de Juda et de Benjamin, et des habitants de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Et ils donnèrent cet argent à ceux qui faisaient les travaux, qu\'on avait établis dans le temple du Seigneur; ils le donnèrent à ceux qui faisaient ce qu\'il y avait à faire pour restaurer et raffermir le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Ils ordonnèrent aussi aux charpentiers et aux maçons d\'acheter des pierres de taille et des solives pour recouvrir les logements que les rois de Juda avaient abattus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Et ces hommes se mirent fidèlement à l\'œuvre, et ils furent surveillés par Jeth et Abdias, lévites de la maison de Mérari, par Zacharie et Mosollam, des fils de Caath, et par tous les lévites qui savaient chanter et jouer des instruments,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Et les manœuvres et les ouvriers, chacun en son travail, étaient encore surveillés par les lévites scribes, juges et portiers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Or, tandis que l\'on transportait l\'argent donné pour le temple du Seigneur, Helcias, le prêtre, trouva un livre de la loi du Seigneur donnée par Moïse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Et Helcias prit la parole, et il dit à Saphan, le scribe: J\'ai trouvé dans le temple du Seigneur un livre de la loi. Et Helcias donna le livre à Saphan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Et Saphan porta le livre au roi, et il lui rendit compte, disant: Voici le compte de tout l\'argent qui a été remis à tes serviteurs chargés des travaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Or, cet argent, trouvé dans le temple du Seigneur, avait été monnayé et distribué aux surveillants, puis aux ouvriers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Et Saphan en rendit compte au roi, et il ajouta: Helcias m\'a donné un livre. Et Saphan le lut devant le roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Et quand Josias ouït les paroles du livre de la loi, il déchira ses vêtements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Et il donna ses ordres à Helcias, à Achicam, fils de Saphan, à Abdom, fils de Michée, à Saphan, le scribe, à Asaïe, serviteur du roi, et il leur dit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Allez et interrogez le Seigneur, pour moi et pour tout ce qui reste de Juda et d\'Israël, au sujet des paroles du livre qui a été trouvé; car la colère du Seigneur s\'est enflammée contre nous, parce que nos pères n\'ont point obéi aux commandements du Seigneur, et n\'ont point fait ce qui est écrit en ce livre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Or, Helcias et ceux à qui avait parlé le roi, allèrent trouver Olda, la prophétesse, femme de Sellem, file de Thécoé, fils d\'Aras; elle observait les commandements, et demeurait à Jérusalem dans le second quartier, et ils lui parlèrent relativement à ces choses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Et elle leur répondit: Voici ce que dit le Seigneur Dieu d\'Israël; dites à l\'homme qui vous a envoyés chez moi:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Voici ce que dit le Seigneur: Voilà que j\'amène le mal sur ce lieu,\' selon les paroles du livre qui a été lu devant le roi de Juda,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'En punition de ce qu\'ils m\'ont abandonné, de ce qu\'ils ont brûlé de l\'encens pour d\'autres dieux, afin de m\'irriter, par toutes les œuvres de leurs mains; car ma colère s\'est enflammée contre ce lieu, et elle ne s\'éteindra pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Quant au roi de Juda qui vous a envoyés chez moi, pour interroger le Seigneur, dites-lui: Voici ce que dit le Seigneur Dieu d\'Israël: Aux paroles que tu as entendues,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Ton cœur a été rempli de crainte; tu t\'es humilié devant moi, lorsque tu as ouï mes menaces contre ce lieu et contre ceux qui l\'habitent; tu t\'es humilié devant moi; tu as déchiré tes vêtements; tu as pleuré devant moi, et moi aussi j\'ai entendu, dit le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Voilà que je te réunis à tes pères; tu seras déposé en paix dans ton sépulcre, et tes yeux ne verront aucun des maux que j\'amène sur ce lieu et sur ceux qui l\'habitent. Et ils rapportèrent au roi ces paroles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Et le roi envoya des messagers, et il rassembla les anciens de Juda et de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Et le roi monta au temple du Seigneur, avec tout Juda, tous les habitants de Jérusalem, les prêtres, les lévites et le peuple entier, depuis le petit jusqu\'au grand, et il lut à leurs oreilles toutes les paroles du livre de l\'alliance, trouvé dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Et le roi se tint debout sur le piédestal, et il fit une alliance devant le Seigneur, pour marcher devant le Seigneur, garder ses commandements, ses témoignages et ses ordonnances, de tout son cœur et de toute son âme, afin de se conformer à toutes les paroles de l\'alliance écrites en ce livre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Et il fit lever tous ceux qui se trouvaient en Jérusalem; et Benjamin, et les habitants de Jérusalem firent une alliance dans le temple du Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Et Josias expulsa toutes les abominations de toute la terre des fils d\'Israël, et il obligea tous ceux qui se trouvaient dans la ville et en Israël à servir, tous les jours de sa vie, le Seigneur leur Dieu; et il ne se détourna point du Seigneur Dieu de ses pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Et Josias fit la Pâque du Seigneur son Dieu, et il immola la pâque, le quatorzième jour de la première lune.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Et il établit les prêtres dans leurs fonctions, et il les fortifia pour qu\'ils servissent dans le temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Et il prescrivit aux hommes valides parmi les lévites d\'Israël, de se consacrer au Seigneur; ils placèrent donc l\'arche sainte dans le temple qu\'avait bâti Salomon; puis, le roi dit aux lévites: Vous n\'avez plus rien à porter sur vos épaules, maintenant servez le Seigneur votre Dieu et Israël son peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Préparez-vous, par familles paternelles, selon l\'ordre de vos services journaliers; conformez-vous aux règlements du roi David, et à l\'ordre établi par son fils Salomon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Tenez-vous dans le temple; afin d\'y servir par divisions de familles paternelles, pour vos frères les fils du peuple; c\'est le privilège de la maison de Lévi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Immolez la pâque et préparez-la pour vos frères, afin d\'observer la loi du Seigneur que Moïse a fait connaître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Et Josias, pour que les enfants du peuple fissent la pâque, immola des brebis, des agneaux, des chevreaux, au nombre de trente mille, et trois mille bœufs, tous pris parmi les troupeaux qui lui appartenaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Et ses princes sacrifièrent aussi pour le peuple, les prêtres et les lévites. Helcias, et Zacharie, et Jehiel, princes des prêtres, donnèrent à ceux-ci, pour la pâque, deux mille six cents brebis, agneaux ou chevreaux, et trois cents bœufs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Et Honenias, Banaïas, Samaïas, son frère Nathanaël, Asabias, Jébiel et Jozabad, chefs des lévites, donnèrent à ceux-ci, pour la pâque, cinq mille têtes de menu bétail, et cinq cents bœufs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Et le service fut régulièrement rétabli; les prêtres se tinrent à leur rang ainsi que les lévites selon leurs divisions, comme l\'avait prescrit le roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Et ils immolèrent la pâque, et les prêtres répandirent de leurs mains le sang des victimes, et les lévites en enlevèrent les peaux;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Et ils préparèrent les holocaustes qui furent répartis, parmi le peuple, selon leurs divisions, par familles paternelles, pour qu\'on les offrît au Seigneur, dès le matin, comme il est écrit au livre de Moïse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Et ils rôtirent la pâque à la flamme, selon la loi, et ils firent bouillir les chairs saintes, dans des chaudières d\'airain et des marmites, et tout se passa heureusement, et quand les chairs furent bien cuites, ils se hâtèrent de les distribuer aux enfants du peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Ils en préparèrent ensuite pour eux-mêmes et pour les prêtres, car ces derniers restèrent jusqu\'à la nuit à offrir les holocaustes, et à brûler les graisses. Les lévites préparèrent donc leur propre repas, et celui de leurs frères les fils d\'Aaron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Pendant ce temps, les chantres-harpistes, fils d\'Asaph, étaient à leur poste, selon les règlements de David, d\'Asaph, d\'Hêman et d\'Idithun, prophètes de ce roi, ainsi que les chefs et les gardiens des portes; il ne leur était pas permis de s\'éloigner du service et des choses saintes; ce furent donc encore leurs frères les lévites, qui préparèrent leur repas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Ainsi, chaque service du Seigneur, ce jour-là, pour la célébration de la pâque et les offrandes d\'holocaustes sur l\'autel du Seigneur, se fit régulièrement par les soins du roi Josias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Les fils d\'Israël qui se trouvèrent à Jérusalem, en ce temps-là, firent aussi la pâque et la fête des azymes, pendant sept jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Et il n\'y avait pas eu en Israël pareille pâque, depuis le temps du prophète Samuel; nul des rois d\'Israël n\'avait fait la pâque comme la firent, pour le Seigneur, Josias, les prêtres et les lévites, tout Juda, ce qui se trouva là d\'Israël, et les habitants de la ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Ce fut en la dix-huitième année du règne de Josias, que cette pâque fut célébrée. Or, après tout ce que le roi Josias avait fait dans le temple, il brûla les ventriloques, les devins, et les images, et les idoles, et les sodomites, qui étaient en la terre de Juda et en Jérusalem, afin de confirmer les paroles de la loi, écrites dans le livre qu\'avait trouvé Helcias. Et il n\'y avait point eu auparavant de roi comme lui, qui se convertit au Seigneur, de tout son cœur, de toute son âme et de toute sa force, selon toute la loi de Moïse, et il n\'y en eut point après lui. Néanmoins, le Seigneur ne détourna point la terrible colère, dont il s\'était enflammé contre Juda, à cause des offenses qu\'il avait reçues de Manassé. Et le Seigneur dit: J\'expulserai aussi Juda de devant ma face, comme j\'ai expulsé Israël; et je répudierai cette ville que j\'avais choisie, cette Jérusalem et ce temple dont j\'avais dit: C\'est là que sera mon nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Et le Pharaon Néchao, roi d\'Égypte, marcha, sur le fleuve Euphrate, contre le roi des Assyriens, et Josias se porta à sa rencontre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Et Néchao lui envoya des messagers, disant: Qu\'y a-t-il entré moi et toi, roi de Jérusalem? Je ne suis pas venu aujourd\'hui pour te combattre, et Dieu m\'a prescrit de me hâter. Fais attention au Dieu qui est avec moi, si tu ne veux que je t\'extermine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Mais Josias ne détourna point de lui sa face; il se fortifia pour le combattre, sans tenir compte des paroles de Néchao, dites de la part de Dieu, et il, lui livra une bataille dans la plaine de Mageddo.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Là, des archers percèrent le roi Josias, et il dit à ses serviteurs: Emmenez-moi, car je souffre cruellement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Ses serviteurs le descendirent donc de son char, le placèrent sur un autre char qu\'il avait, et l\'emmenèrent à Jérusalem, où il mourut; il fut enseveli avec ses pères. Et tout Juda et Jérusalem pleurèrent sur Josias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jérémie a fait sur lui une lamentation que tous les chefs et les lemmes des princes ont chantée jusqu\'à ce jour; c\'est devenu comme une loi en Israël, et elle est écrite au livre des Lamentations.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Et les actions de Josias et son espérance furent conformes à ce qui est écrit en la loi du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'Et ses actes, les premiers et les derniers, sont écrits au livre des Rois d\'Israël et de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 28, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 29, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 30, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 31, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Le peuple prit Joachaz, fils de Josias, et il le sacra, et il le fit roi de Jérusalem, à la place de son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Joachaz avait vingt-trois ans quand il monta sur le trône, et il régna trois mois à Jérusalem; Sa mère se nommait Amital, fille de Jérémie de Lobna, Et il fit le mal devant le Seigneur; il suivit tous les mauvais exemples de ses pères; Et le Pharaon Néchao le chargea de chaînes à Déblatha, en la terre d\'Emath, pour qu\'il ne régnât pas à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Il l\'emmena en Égypte, et il frappa la terre d\'une contribution de cent talents d\'argent et d\'un talent d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Et le Pharaon Néchao fit roi de Juda, à la place de Josias son père, Éliacim, fils de Josias, et il changea son nom en celui de Joacim, et il prit son frère Joachaz, et il l\'emmena en Égypte, où il mourut. Mais il avait donné l\'argent et l\'or au Pharaon; en ce temps-là, on commença sur la terre à lever une taxe réglée par le Pharaon; chacun, autant qu\'il le put, emprunta l\'argent et l\'or du peuplade la terre, pour le donner au Pharaon Néchao.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Joacim avait vingt-cinq ans lorsqu\'il monta sur le trône, et il régna onze ans à Jérusalem; sa mère s\'appelait Zéchora, fille de Néria de Rhama; et il fit le mal devant le Seigneur, suivant tous les mauvais exemples de ses pères. Sous son règne, Nabuchodonosor, roi de Babylone, vint en la terre, et Joacim lui fut asservi trois ans, et il se révolta contre lui. Et le Seigneur envoya contre son peuple des Chaldéens, des maraudeurs, tant syriens que moabites, ou fils d\'Ammon ou samaritains, qui ensuite s\'éloignèrent pour confirmer la parole que le Seigneur avait dite par la voix de ses serviteurs les prophètes. Mais la colère du Seigneur persistait contre Juda, qu\'il voulait expulser de devant sa face, à cause des péchés que Manassé avait commis, Et du sang innocent qu\'avait répandu Joacim, car il en avait rempli Jérusalem; toutefois le Seigneur n\'avait pas dessein de les exterminer tout à fait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Nabuchodonosor marcha donc contre Joacim, le chargea de chaînes d\'airain, et l\'emmena à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Alors, il emporta une part des vaisseaux du temple du Seigneur, et il les mit dans le temple de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Quant au reste des faits et gestes de Joacim, n\'est-il pas écrit au livre des Récits des rois de Juda? Et Joacim s\'endormit avec ses pères, et on l\'ensevelit à Gonaza avec ses pères, et Jéchonias, son fils, fut proclamé roi à sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Jéchonias avait huit ans lorsqu\'il monta sur le trône, et il régna trois mois et dix jours à Jérusalem, et il fit le mal devant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Et pendant le cours de l\'année, le roi Nabuchodonosor envoya des troupes, et on l\'emmena à Babylone avec tous les vases précieux du temple du Seigneur, et l\'on proclama roi de Juda et de Jérusalem, Sédécias, frère de son père.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sédécias avait vingt et un ans lorsqu\'il monta sur le trône, et il régna onze ans à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Et il fit le mal devant le Seigneur, et il ne rentra en lui-même, ni devant le prophète Jérémie, ni à la parole du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Il se révolta contre le roi Nabuchodonosor, après qu\'au nom du Seigneur, le prophète l\'eût adjuré de n\'en rien faire; il endurcit son cœur et il se roidit le cou, de sorte qu\'il ne retourna pas au Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Et les premiers de Juda, et les prêtres et le peuple de la contrée, multiplièrent les offenses en commettant les abominations des peuples étrangers, et ils souillèrent le temple du Seigneur à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Et le Seigneur Dieu de leurs pères les avertit en leur envoyant ses prophètes, eu leur envoyant à chaque aurore des messagers, pour épargner son peuple et le lieu saint.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Mais ils raillaient ses envoyés, ils méprisaient ses discours, ils se moquaient de ses prophètes, jusqu\'à ce qu\'enfin la colère du Seigneur s\'enflammât contre le peuple et fût implacable.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Alors, le Seigneur amena contre eux le roi des Chaldéens, qui tua leurs jeunes fils par le glaive dans le temple et le sanctuaire; il n\'épargna pas Sédécias, et n\'eut point pitié des vierges de Jérusalem; les vainqueurs enlevèrent les anciens; le Seigneur leur avait livré toutes choses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Et tous les vaisseaux du temple de Dieu, grands et petits, et tous les trésors, tant du temple que du palais et des maisons des grands, furent transportés à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Et Nabuchodonosor brûla le temple du Seigneur; puis, il démolit les remparts de Jérusalem; il livra aux flammes tous ses palais, il détruisit tous les vases précieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Et il transporta le reste des habitants à Babylone, où ils furent esclaves du roi ou de ses fils, jusqu\'à l\'établissement de l\'empire des Mèdes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Afin que la parole du Seigneur qu\'avait fait connaître la bouche de Jérémie, le prophète, fût accomplie, et que la terre jouît de ses sabbats, et observât le sabbat tous les jours de sa désolation, jusqu\'à l\'achèvement des soixante-dix années.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'La première année de la domination de Cyrus, roi des Perses, après l\'accomplissement de la parole du Seigneur, qu\'avait dite la bouche de Jérémie, le Seigneur excita l\'esprit de Cyrus, roi des Perses, et il envoya dans tout le royaume une proclamation par écrit, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Voici ce que dit, à tous les royaumes de la terre, Cyrus, roi des Perses: Le Seigneur Dieu du ciel m\'a donné le pouvoir, et il m\'a prescrit de rebâtir son temple à Jérusalem, en Juda. Qui, parmi vous tous, est de son peuple? Qu\'il parte; son Dieu sera avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 24, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 25, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 26, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 27, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 28, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 29, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 30, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 31, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Et Josias conduisit la Pâque dans Jérusalem pour son Seigneur et il offrit la Pâque le quatorzième jour du premier mois');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'plaçant dans le temple du Seigneur les prêtres vêtus en fonction des offices du jour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Et il dit aux Lévites, les esclaves sacrés d’Israël, de se sanctifier envers le Seigneur par la mise en place du coffre saint du Seigneur dans la maison qu’avait bâtie Salomon, le fils de David, le roi: « Vous n’aurez pas à le soulever sur vos épaules;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'et maintenant servez le Seigneur, votre dieu, et prenez soin de son peuple Israël, et faites les préparatifs en fonction de vos lignées paternelles et de vos tribus suivant l’écrit de David, roi d’Israël, et suivant la grandeur de Salomon, son fils,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'et vous les Lévites, placez-vous dans le sanctuaire en fonction du district de vos pères, vous qui par votre place êtes devant vos frères, les fils d’Israël,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'et offrez la Pâque et préparez les offrandes pour vos frères et faites la Pâque selon l’ordonnance du Seigneur, celle qui a été donnée à Moïse. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Et Josias fit présent au peuple qui était là de trente milliers d’agneaux et de chevreaux, de trois mille taurillons; c’est sur les possessions royales que ces dons furent faits selon la promesse [faite] au peuple, aux prêtres et aux Lévites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Et Khelkias, Zakharias et Esyèlos, les chefs du sanctuaire, donnèrent aux prêtres, pour la Pâque, deux mille six cents moutons, trois cents taurillons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Et Jékhonias, Samaias, Nathanaël son frère, Asabias, Okhièlos et Joram, les chiliarques, donnèrent aux Lévites, pour la Pâque, cinq mille moutons, sept cents taurillons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Et voici ce qui se passa: les prêtres prirent place majestueusement, ainsi que les Lévites');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'tenant les pains sans levain, par tribus');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 12, 'et en fonction des districts des pères, devant le peuple, pour apporter l’offrande au Seigneur, selon ce qui est écrit dans le livre de Moïse, et il en fut ainsi le matin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 13, 'Et ils firent rôtir la Pâque avec le feu, comme il convient, et les offrandes, ils les firent bouillir dans les bassines et les chaudrons avec une bonne odeur, et ils les offrirent à tous les gens du peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 14, 'Or après cela ils firent les préparatifs pour eux-mêmes ainsi que pour les prêtres, leurs frères, les fils d’Aaron; en effet les prêtres faisaient monter la fumée des graisses jusqu’à une heure avancée, aussi les Lévites firent les préparatifs pour eux-mêmes ainsi que pour les prêtres, leurs frères, les fils d’Aaron.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 15, 'Et les psalmistes sacrés, les fils d’Asaph, étaient à leur place selon ce qui avait été fixé par David, de même qu’Asaph, Zakharias et Eddinous qui étaient à côté du roi, et de même les huissiers à chaque porte: il n’est pas permis à chacun de sortir de son office du jour, car leurs frères, les Lévites, avaient fait les préparatifs pour eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 16, 'Et l’on accomplit les rites du Seigneur ce jour-là, pour conduire la Pâque et apporter les offrandes sur l’autel du Seigneur, selon l’ordre du roi Josias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 17, 'Et les fils d’Israël qui étaient là en cette occasion conduisirent la Pâque et la fête des pains sans levain pendant sept jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 18, 'Et l’on n’avait pas conduit une Pâque pareille en Israël depuis le temps de Samuel le prophète');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 19, 'et tous les rois d’Israël n’avaient pas conduit une Pâque pareille à celle que conduisit Josias avec les prêtres, les Lévites, les Juifs et tout Israël, ceux qui étaient dans leur résidence à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 20, 'C’est la dix-huitième année du règne de Josias que fut conduite cette Pâque.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 21, 'Et les actes de Josias furent droits vis-à-vis de son Seigneur, d’un cœur plein de piété.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 22, 'Et les événements de sa vie ont été consignés dans les Chroniques qui précèdent, à propos de ceux qui ont commis des fautes et des impiétés envers le Seigneur au contact de tout peuple et de tout royaume, ainsi que des choses qui l’ont affligé pour les avoir éprouvées, et les paroles du Seigneur se dressèrent contre Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 23, 'Et après toute cette action de Josias, il arriva que Pharaon, le roi d’Egypte, alla réveiller la guerre à Kharkamus sur l’Euphrate, et à sa rencontre sortit Josias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 24, 'Et le roi d’Egypte lui envoya un messager disant: « Qu’y a-t-il entre moi et toi, roi de Judée?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 25, 'Ce n’est pas contre toi que j’ai été envoyé par le Seigneur-Dieu, car c’est sur l’Euphrate qu’est ma guerre. Et maintenant le Seigneur est avec moi, et le Seigneur qui est avec moi me presse: écarte-toi et ne t’oppose au Seigneur! »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 26, 'Et Josias ne se détourna pas sur son char: au contraire il entreprend de lui faire la guerre, sans considérer les paroles du prophète Jérémie qui viennent de la bouche du Seigneur;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 27, 'au contraire il organisa la guerre contre lui dans la plaine de Maggédaous, et les chefs descendirent contre le roi Josias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 28, 'Et le roi dit à ses esclaves: « Écartez-moi du combat, car me voilà trop faible ». Et aussitôt ses esclaves l’écartèrent du rang de bataille,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 29, 'et il monta sur son char, le second; et une fois ramené à Jérusalem il perdit la vie et fut enterré dans le tombeau de ses pères');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 30, 'Et dans toute la Judée ils firent le deuil de Josias, et le prophète Jérémie eut un chant de lamentation pour Josias, et ceux qui siègent au premier rang avec leurs femmes chantèrent des lamentations sur lui jusqu’à ce jour, et on l’a publié afin qu’il soit toujours pour toute la race d’Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 31, 'Cela d’ailleurs est consigné dans le livre des histoires sur les rois de Judée; et l’œuvre détaillée de l’action de Josias, de sa splendeur et de son intelligence dans la Loi du Seigneur, ce qui fut fait par lui auparavant et à ce moment-là, cette histoire est dans le livre des Rois d’Israël et de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 32, 'Et les gens du peuple prirent Jékhonias, le fils de Josias, et le désignèrent roi à la place de Josias son père, à l’âge de vingt-trois ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 33, 'Et il régna dans Juda et Jérusalem trois mois. Et le roi d’Egypte l’écarta de la royauté dans Jérusalem');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 34, 'et il frappa le peuple d’une amende de cent talents d’argent et d’un talent d’or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 35, 'Et le roi d’Egypte désigna roi Joakim, son frère, roi de la Judée et de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 36, 'Et Joakim enchaîna les hauts personnages, puis il prit avec lui son frère Zarios et le ramena d’Egypte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 37, 'Joakim avait vingt-cinq ans quand il devint roi de Judée et de Jérusalem, et il fit le mal vis-à-vis du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 38, 'Nabuchodonosor, le roi de Babylone, monta contre lui et, après l’avoir enchaîné dans des chaînes de bronze, il l’emmena à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 39, 'Et Nabuchodonosor puisa dans les objets sacrés du Seigneur, les emporta et les serra dans son temple à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 40, 'D’ailleurs les histoires le concernant, ainsi que son impureté et sa mécréance, sont consignées dans le livre des Chroniques des rois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 41, 'Et Joakim, son fils, devint roi à sa place; en effet quand il fut désigné, il avait dix-huit ans;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 42, 'or son règne est de trois mois et dix jours dans Jérusalem et il fit le mal devant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 43, 'Et à la fin de l’année Nabuchodonosor envoya une mission et le fit emmener à Babylone en même temps que les objets sacrés du Seigneur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 44, 'et il désigna Sédécias âgé de vingt et un ans, et son règne est d’onze ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 45, 'Et il fit le mal vis-à-vis du Seigneur et ne se blottit pas devant les paroles dites par le prophète Jérémie qui viennent de la bouche du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 46, 'Et après que le roi Nabuchodonosor lui eut fait prêter serment par le nom du Seigneur, il se parjura et fit défection, et durcissant son cou et son cœur il transgressa les Lois du Seigneur, dieu d’Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 47, 'Et de plus les chefs du peuple et des prêtres commirent un grand nombre d’impiétés et d’illégalités, dépassant toutes les impuretés de toutes les nations, et ils souillèrent le sanctuaire du Seigneur qui avait été sanctifié à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 48, 'Et le dieu de leurs pères les envoya rappeler par son messager, étant donné qu’il cherchait à les épargner, eux et sa tente.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 49, 'Mais eux rirent au nez de ses messagers, et le jour où parla le Seigneur, ils étaient là à se jouer de ses prophètes, jusqu’à ce qu’irrité contre son peuple à cause de ses mécréances il ordonne que montent contre eux les rois des Chaldéens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 50, 'Ceux-ci tuèrent leurs garçons par l’épée, à l’entour de leur saint sanctuaire, et ils n’épargnèrent ni garçon ni fille, ni vieux ni jeune: il les livra tous entre leurs mains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 51, 'Et ils enlevèrent tous les objets sacrés du Seigneur, les grands et les petits, et les coffres du Seigneur ainsi que les dépôts royaux, et ils les emportèrent à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 52, 'Et ils incendièrent la maison du Seigneur et démolirent les remparts de Jérusalem et ils en incendièrent les tours avec le feu');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 53, 'et ils achevèrent de rendre inutilisable tout ce qui faisait sa splendeur et il emmena les survivants avec son épée à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 54, 'Et ils furent ses esclaves, à lui et à ses fils, jusqu’à ce que règnent les Perses, pour l’accomplissement de la parole du Seigneur dans la bouche de Jérémie:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 55, '\" Jusqu’à ce que la terre ait son content de sabbats, tout le temps de sa dévastation, elle fera le sabbat jusqu’à l’accomplissement de soixante et dix ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 56, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 57, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 58, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Lors de la première année du règne de Cyrus sur les Perses, pour l’achèvement de la parole du Seigneur dans la bouche de Jérémie, le Seigneur éveilla l’âme de Cyrus, le roi des Perses, et il fit des proclamations par hérauts dans tout son royaume, et en même temps par des écrits, en ces termes:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, '« Voici ce que dit le roi des Perses, Cyrus: « C’est moi qu’a désigné roi de la terre le Seigneur d’Israël, le Seigneur, le Très Haut, et il m’a ordonné de lui bâtir une maison à Jérusalem, qui est en Judée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Si donc l’un de vous est de son peuple, que son Seigneur soit avec lui, et qu’il monte à Jérusalem qui est en Judée et bâtisse la maison du Seigneur d’Israël (c’est lui le Seigneur qui a planté sa tente à Jérusalem).');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Tous ceux donc qui habitent dans des lieux seront aidés chacun par les gens du lieu en or et argent en dons, avec chevaux et bestiaux, auxquels s’ajouteront d’autres dons votifs pour le sanctuaire du Seigneur qui est à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Et quand les chefs des tribus des lignées paternelles de Juda et de la tribu de Benjamin, les prêtres, les Lévites et tous ceux dont le Seigneur avait éveillé l’âme se présentèrent pour monter bâtir une maison pour le Seigneur, celle qui est à Jérusalem,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Eh bien, les gens des alentours les aidèrent en tout, argent et or, chevaux et bestiaux, et le plus de dons votifs possible des nombreuses personnes dont l’esprit avait été éveillé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Et le roi Cyrus fit sortir les objets sacrés du Seigneur que Nabuchodonosor avait emportés de Jérusalem et avait serrés dans son propre temple d’idoles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Mais Cyrus, le roi des Perses, les fit sortir et les confia à Mithridate, son trésorier, et par son intermédiaire ils furent confiés à Sanabassare, le prince de la Judée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Le nombre de ceux-ci était: mille coupes à libation en or, mille coupes à libation en argent, vingt-neuf encensoirs en argent,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'trente patères en or, deux mille quatre cent dix en argent et mille autres objets.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'On transporta l’ensemble des objets, en or et argent, au nombre de cinq mille quatre cent soixante-neuf, et ils furent emportés par Sanabassare de Babylone à Jérusalem en même temps que ceux qui sortaient de la captivité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Or, aux temps d’Artaxerxès, le roi des Perses, une lettre lui fut écrite contre les habitants de Judée et de Jérusalem par Beslémos, Mithradatès, Tabellios, Raoumos, Béeltéémos, le scribe Samsaios et le reste de ceux qui se rangeaient à leurs côtés mais habitaient la Samarie et les autres lieux; c’est la lettre écrite ci-dessous:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, '« Au roi Artaxerxès, seigneur, tes esclaves Raoumos, celui des nouvelles, le scribe Samsaios et le reste des juges de leur conseil qui sont dans la Syrie Creuse et la Phénicie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Qu’il soit maintenant connu du seigneur-roi qu’après être montés de vous vers nous, en allant vers Jérusalem, les Juifs construisent la ville, la rebelle et mauvaise, réparent ses places et ses remparts et s’occupent des fondations du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Si donc cette ville-là est construite et ses remparts achevés, ils n’accepteront sûrement pas de payer un tribut, et de plus ils s’opposeront aux rois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Et, puisqu’on active les travaux du temple, nous pensons qu’il est bon de ne pas négliger une telle chose et de s’adresser au seigneur-roi afin, si tu le trouves bon, que l’on aille voir dans les livres légués par tes pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Et tu trouveras dans les mémoires ce qui est écrit sur ces gens et tu te rendras compte que cette ville-là était rebelle et gênante pour les rois et les villes, et que les Juifs étaient des rebelles et y organisaient en outre des sièges depuis l’éternité, raison pour laquelle justement cette ville-là a été dévastée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Nous te représentons donc maintenant, seigneur-roi, que, si cette ville-là est bâtie et ses remparts relevés, tu n’auras plus de chemin pour descendre vers la Syrie Creuse et la Phénicie ».');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Alors le roi écrivit en réponse à Raoumos, celui qui écrivait les nouvelles, à Béeltéémos, à Samsaios le scribe et au reste de ceux qui se rangeaient à leurs côtés et habitaient la Samarie, la Syrie et la Phénicie, la lettre écrite ci-dessous:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'J’ai lu la lettre que vous m’avez envoyée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'J’ai donc ordonné qu’on aille voir, et l’on a trouvé que cette ville-là est depuis toujours à dresser le rang de bataille contre les rois, que les hommes y organisent des rébellions et des guerres');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'et que les rois étaient puissants et durs quand ils étaient les seigneurs dans Jérusalem et levaient un tribut sur la Syrie Creuse et la Phénicie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'J’ai donc maintenant ordonné qu’on empêche ces hommes-là de construire la ville');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'et qu’on veille à ce que rien ne soit fait en dehors de cela et à ce que les effets de leur malignité ne progressent pas davantage pour gêner les rois. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Alors, après avoir lu ce que leur avait écrit le roi Artaxerxès, Raoumos, le scribe Samsaios et ceux qui s’étaient rangés à leurs côtés levèrent le camp en hâte pour Jérusalem avec cavalerie et troupe en rang de bataille et commencèrent à s’opposer aux bâtisseurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Et la construction du sanctuaire qui est à Jérusalem était restée en suspens jusqu’à la deuxième année du règne de Darius, le roi des Perses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Et le roi Darius avait fait une grande réception pour tous ceux qui étaient sous lui, pour tous les serviteurs nés dans sa maison, pour tous les hauts personnages de Médie et de Perse,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'et pour tous les satrapes, stratèges et gouverneurs qui étaient sous lui de l’Inde jusqu’à l’Éthiopie dans les cent vingt-sept satrapies.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Et ils mangèrent et burent et, repus, se retirèrent; quant au roi Darius, il se retira dans sa chambre, se coucha et sombra dans le sommeil.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Alors les trois garçons, les gardes du corps, ceux qui gardaient la personne du roi, se dirent l’un à l’autre:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, '\" Disons chacun de nous une seule définition de ce qui est le plus fort; et celui dont la parole semblera plus sage que l’autre, le roi Darius lui donnera de grands dons et de grandes marques d’honneur pour sa victoire:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'se revêtir de pourpre, boire dans de la vaisselle d’or et coucher sur l’or, un char à frein d’or, un turban du lin le plus fin et un collier autour du cou,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'et il siégera à la deuxième place, après Darius, à cause de sa sagesse, et il sera nommé parent de Darius.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Et ils écrivirent alors chacun leur définition, y apposèrent leurs sceaux et la placèrent sous le coussin du roi Darius, et ils dirent:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, '\" Quand le roi s’éveillera, on lui donnera la tablette, et celui que choisira le roi avec les trois hauts personnages de Perse parce que sa définition est la plus sage, la victoire lui sera donnée comme c’est écrit. \"');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'L’un avait écrit: \" Le plus fort c’est le vin. \"');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'L’autre avait écrit: \" Le plus fort c’est le roi. \"');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Le troisième avait écrit: \" Les plus fortes ce sont les femmes, mais par- dessus tout est vainqueur la vérité. \"');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Et quand le roi se réveilla, on prit la tablette, on le lui donna et il le lut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 14, 'Et il envoya quérir tous les hauts personnages de la Perse et de la Médie, satrapes, stratèges, gouverneurs et excellences, il les fit asseoir dans la salle d’audience et on lut le billet en face d’eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 15, 'Et il dit: \" Appelez les garçons et ils expliqueront eux-mêmes leurs définitions. \" Et on les appela et ils entrèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 16, 'Et ils leur dirent: \" Commentez-nous ce que vous avez écrit. \"');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 17, 'Et le premier, celui qui avait parlé de la force du vin, commença et il s’exprima ainsi:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 18, '\" Messieurs, comment le vin est-il le plus fort? Il égare la pensée de tous les hommes qui le boivent,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 19, 'il fait une la pensée du roi et celle de l’orphelin, celle du serviteur et celle de l’homme libre, celle du pauvre et celle du riche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 20, 'Et il tourne toute pensée vers la bonne chère et la réjouissance, et on oublie tout chagrin et toute dette.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 21, 'Et il rend tous les cœurs riches et on oublie le roi et le satrape, et il fait parler de toutes choses par talents entiers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 22, 'Et on oublie, quand on boit, de se conduire en ami avec les amis et les frères, et en peu de temps on tire les couteaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 23, 'Et quand on a cuvé son vin, on ne se rappelle plus ce qu’on a fait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 24, 'Messieurs, le vin n’est-il pas le plus fort, puisqu’il oblige à agir ainsi? \" Et il se tut après avoir ainsi parlé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Et le deuxième, celui qui avait parlé de la force du roi, prit la parole.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, '« Messieurs, les hommes ne sont-ils pas les plus forts, eux qui exercent leur domination sur la terre et la mer, et sur tout ce qui s’y trouve?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Or le roi est le plus fort, et il est leur seigneur et il est leur maître, et tout ce qu’il peut leur dire, ils l’écoutent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'S’il leur dit de se faire la guerre l’un contre l’autre, ils le font. S’il les envoie contre les ennemis, ils marchent et abattent les montagnes, les remparts et les tours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Ils tuent et sont tués, et ils ne transgressent pas la parole du roi; s’ils sont vainqueurs, ils apportent tout au roi, aussi bien ce dont ils auront fait leur butin que toutes les autres choses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Et tous ceux qui ne sont pas soldats et ne font pas la guerre, mais qui cultivent la terre, à leur tour, lorsqu’ils ont semé, offrent au roi ce qu’ils ont moissonné; et se contraignant l’un l’autre ils offrent les tributs au roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Et lui-même est seul et unique: s’il dit de tuer, ils tuent; il a dit de relâcher, ils relâchent;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'il a dit de frapper, ils tapent; il a dit de dévaster, ils dévastent; il a dit de bâtir, ils bâtissent;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'il a dit d’abattre, ils abattent; il a dit de planter, ils plantent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'Et tout son peuple et ses forces armées l’écoutent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Outre cela, lui est sur un lit de table (il mange, boit et dort), tandis qu’eux veillent en cercle autour de lui, ils sont chacun dans l’impossibilité de partir et de vaquer à leurs occupations et ne sont pas sourds à ses ordres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Messieurs, comment le roi n’est-il pas le plus fort, puisqu’il est à ce point écouté? » Et il se tut.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Le troisième, celui qui avait parlé des femmes et de la vérité (c’est Zorobabel) prit la parole.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, '« Messieurs, n’est-il pas vrai que le roi est grand, les hommes nombreux et que le vin est fort? Qui donc est leur maître? Qui est leur seigneur? Est-ce que ce ne sont pas les femmes?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Les femmes ont engendré le roi et tout le peuple, qui est le seigneur de la terre et de la mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Et ils sont nés d’elles, et ce sont elles qui ont élevé ceux-là-mêmes qui ont planté les vignes d’où naît le vin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Et ce sont elles qui font les vêtements des hommes, et ce sont elles qui font de la splendeur pour les hommes, et les hommes ne peuvent pas être sans les femmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'S’ils amassent de l’or, de l’argent ou n’importe quelle belle chose, et qu’ils voient une seule femme, belle par son aspect et sa beauté,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'eh bien, négligeant tout cela ils bayent vers elle, et bouche bée ils la contemplent, et tous la choisissent de préférence à l’or, à l’argent ou à n’importe quelle belle chose.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'L’homme abandonne son propre père, qui l’a élevé, et le pays qui est le sien, et il se colle contre la femme qui est la sienne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Et avec sa femme il relâche son âme et ne se souvient ni de son père, ni de sa mère, ni de son pays.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Et par là il vous faut reconnaître que les femmes sont vos seigneurs; n’est-il pas vrai que vous vous donnez du mal et de la peine et que vous offrez tout, apportez tout aux femmes?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Et l’homme prend son épée et part faire une expédition, piller, voler et naviguer sur la mer et les fleuves;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'et il guette le lion et marche dans les ténèbres, et chaque fois qu’il fait un vol, une rapine ou va en maraude, il le rapporte à celle qu’il aime.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 25, 'Et l’homme chérit bien plus la femme qui est la sienne que son père et sa mère;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 26, 'et beaucoup sont désespérés par les pensées qui sont les leurs à cause des femmes et deviennent des esclaves à cause d’elles,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 27, 'et beaucoup périssent, tombent dans l’erreur et commettent des fautes à cause des femmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 28, 'Et maintenant, ne me croyez-vous pas? N’est-il pas vrai que le roi est grand par son pouvoir? N’est-il pas vrai que tous les pays se gardent bien de le toucher?»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 29, 'Je le regardais, lui et Apamè, la fille de Bartakos le magnifique, la favorite du roi: elle était assise à la droite du roi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 30, 'et elle enlevait le diadème de la tête du roi et s’en coiffait tandis qu’elle souffletait le roi de la main gauche!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 31, 'Et avec cela le roi la regardait bouche bée; et si elle lui sourit, il rit; si elle a de l’aigreur contre lui, il la flatte pour qu’elle se réconcilie avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 32, '« Messieurs, comment les femmes ne sont-elles pas fortes puisqu’elles agissent ainsi? »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 33, 'Et alors le roi et les hauts personnages se regardèrent les uns les autres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 34, 'Et il commença à parler de la vérité: « Messieurs, n’est-il pas vrai que les femmes sont fortes? Grande est la terre, haut est le ciel, et rapide dans sa course est le soleil, car il tourne dans le cercle du ciel et court rejoindre sa place en un jour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 35, 'N’est-il pas grand Celui qui a fait ces choses? Eh bien, la vérité est grande et plus forte que tout.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 36, 'Toute la terre fait appel à la vérité, et le ciel la bénit, et tous les ouvrages tremblent et frémissent, et il n’y a avec Lui aucune injustice.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 37, 'Injuste est le vin, injuste est le roi, injustes les femmes, injustes tous les fils des hommes, et injustes toutes leurs actions, toutes les choses de ce genre! Et il n’y a pas en eux de vérité, et dans leur injustice ils mourront!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 38, 'La vérité demeure, elle, et elle reste forte pour l’éternité, elle vit et règne pour l’éternité de l’éternité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 39, 'Et il n’est pas possible avec elle de faire acception des personnes, ni de faire de discriminations: elle fait ce qui est juste loin de tout ce qui est injuste ou mauvais; et tous approuvent ses actions, et dans son jugement il n’y a rien d’injuste.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 40, 'Et à elle est la force, et la tiare, et le pouvoir et la grandeur de toutes éternités! Béni soit le dieu de la vérité! »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 41, 'Et il cessa de parler. Et tout le peuple alors cria et ils dirent alors: « Grande est la vérité et elle est la plus forte! »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 42, 'Alors le roi lui dit: « Demande ce que tu veux en plus de ce qui est écrit, et nous te le donnerons, pour la manière dont tu t’es montré le plus sage; et tu siégeras près de moi et tu seras nommé mon parent. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 43, 'Alors il dit au roi: « Rappelle-toi le vœu que tu as fait de bâtir Jérusalem le jour où tu as reçu la tiare,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 44, 'ainsi que de rendre tous les objets qui ont été pris à Jérusalem, ceux que Cyrus a emportés lorsqu’il a fait vœu d’abattre Babylone et qu’il a fait vœu de les renvoyer là-bas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 45, 'Et toi tu as fait vœu de bâtir le temple que les Iduméens ont incendié quand la Judée fut dévastée par les Chaldéens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 46, 'Et c’est là maintenant ce que j’attends de toi, seigneur-roi, et ce que je te demande, et c’est là la grandeur qui relève de toi; je te prie donc d’accomplir le vœu que de ta bouche tu as fait vœu au roi du ciel d’accomplir. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 47, 'Alors le roi Darius se leva et l’embrassa, et il fit écrire en sa faveur les lettres pour tous les chefs de palais, gouverneurs, stratèges et satrapes, afin qu’ils l’escortent, lui et l’ensemble de ceux qui monteraient avec lui bâtir Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 48, 'Et il fit écrire des lettres à tous les gouverneurs de Syrie Creuse et de Phénicie ainsi qu’à ceux du Liban pour qu’ils fassent transporter des troncs de cèdres depuis le Liban à Jérusalem et afin qu’ils bâtissent la ville avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 49, 'Et il fit écrire une déclaration d’affranchissement en faveur de tous les Juifs qui quittaient son royaume pour monter vers la Judée, que tout officier, satrape, gouverneur ou chef de palais ne marche pas contre leurs portes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 50, 'que tout le pays sur lequel ils étendraient leur domination leur appartenait sans être frappé d’impôt; et afin que les Iduméens abandonnent les villages des Juifs qu’ils détenaient;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 51, 'et pour la construction du sanctuaire que soient donnés par an vingt talents jusqu’à ce qu’il soit construit,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 52, 'et que sur l’autel chaque jour on donne en apanage des holocaustes, selon le commandement qu’ils avaient d’en apporter dix-sept (cela faisait dix autres talents par an);');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 53, 'et que tous ceux qui s’avançaient de Babylone pour fonder la ville jouissent de leur liberté, eux et leurs enfants ainsi que les prêtres qui s’avançaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 54, 'Et il définit aussi par écrit le subside et l’habillement sacerdotal avec lequel on fait le culte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 55, 'Et en faveur des Lévites, il fit écrire de leur donner le subside jusqu’au jour où la maison serait achevée et Jérusalem construite,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 56, 'et en faveur de tous les gardes de la ville, il fit écrire de leur donner des lots de terre et une solde.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 57, 'Et il renvoya tous les objets que Cyrus avait emportés de Babylone; et tout ce que Cyrus avait dit de faire, il ordonna lui aussi de le faire ainsi que de [les] renvoyer à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 58, 'Et quand le garçon sortit, levant le visage vers le ciel en direction de Jérusalem, il bénit le roi du ciel, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 59, '« De toi vient la victoire, et de toi la sagesse, et à toi est la splendeur, et moi je suis ton serviteur!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 60, 'Tu es béni, toi qui m’as donné la sagesse, et je te reconnais, maître de mes pères! »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 61, 'Et il prit les lettres, partit à Babylone et annonça la nouvelle à tous ses frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 62, 'Et ils bénirent le dieu de leurs pères, parce qu’il leur avait donné remise et rémission');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 63, 'de monter et de bâtir Jérusalem et son sanctuaire sur lequel son nom avait été nommé, et ils burent de grandes coupes dans la musique et la joie pendant sept jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Après cela furent choisis pour monter les chefs de maison des lignées paternelles selon leurs tribus ainsi que leurs femmes, les fils et les filles, leurs serviteurs et leurs servantes, et leurs bestiaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Et Darius envoya avec eux mille cavaliers jusqu’à ce qu’ils les aient ramenés à Jérusalem dans la paix et dans la musique, celle des tambourins et des flûtes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'et tous leurs frères étaient là à jouer, et il les fit monter avec eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Et voici les noms des hommes qui montaient selon leurs lignées paternelles vers leurs tribus, dans leur district:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'les prêtres, les fils de Phinéés, fils d’Aaron (Jésus le fils de Josédék, fils de Saraios, et Joakim le fils de celui-ci) et Zorobabel, fils de Salathiel, de la maison de David, de la lignée de Pharés et de la tribu de Juda,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'celui qui, sous Darius le roi des Perses, avait dit des paroles sages, la deuxième année de son règne, au mois de Nisan qui est le premier mois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Voici d’autre part ceux de Judée qui montèrent de la captivité de l’exil, ceux que Nabuchodonosor le roi de Babylone avait fait immigrer vers Babylone');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'et qui retournèrent vers Jérusalem et le reste de la Judée, chacun vers la ville qui était la sienne, ceux qui partirent avec Zorobabel et avec Jésus, Néhémie, Zaraias, Résaios, Enènis, Mardochée, Béélsaros, Aspharasos, Borolios, Roïmos, Baana, leurs guides.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Nombre de ceux du peuple ainsi que ceux qui les guidaient: fils de Phoros: 2172.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Fils de Saphat: 472. Fils d’Aréé: 756.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Fils de Phaathmôab, à joindre aux fils de Jésus et Joab: 2812.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Fils d’Olamos: 1254. Fils de Zatos: 945. Fils de Khorbé: 705. Fils de Bani: 648.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Fils de Bèbaï: 623. Fils d’Asgad: 1322.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Fils d’Adonikam: 667. Fils de Bagoï: 2066. Fils d’Adinos: 454.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Fils d’Atèr, le fils d’Ezékhias: 92. Fils de Kilan et d’Azétas: 67. Fils d’Azouros: 432.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Fils d’Annias: 101. Fils d’Arom, fils de Bassaï: 323. Fils d’Ariphos: 112.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Fils de Baïtérous: 3005. Fils issus de Baïthlômôn: 123.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 18, 'Ceux issus de Nétébas: 55. Ceux issus d’Enatos: 158. Ceux issus de Baïtasmôn: 42.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 19, 'Ceux issus de Kariathiaris: 25. Ceux issus de Kapiras et de Bèrot: 743.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 20, 'Les Khadiazes et les Ammidiens: 422. Ceux issus de Kiramas et Gabbès: 621.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 21, 'Ceux issus de Makalôn: 122. Ceux issus de Baitoliô: 52. Fils de Niphis: 156.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 22, 'Fils de l’autre Kalamô et d’Onous: 725. Fils de Jérékhos: 345.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 23, 'Fils de Sanaas: 3330.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 24, 'Les prêtres: fils de Jeddos, le fils de Jésus, à joindre aux fils d’Anasib: 972. Fils d’Emmèros: 1052.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 25, 'Fils de Phassouros: 1247. Fils de Kharmè: 1017.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 26, 'Quant aux Lévites: fils de Jésus, Kadmièlos, Bannos et Soudios: 74.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 27, 'Les psalmistes sacrés, fils d’Asaph: 128.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 28, 'Les huissiers: fils de Salloum, fils d’Atar, Fils de Tolman, fils d’Akoub, fils d’Atèta, fils de Sobaï: 139 au total.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 29, 'Les esclaves sacrés: fils d’Esaü, fils d’Asipha, fils de Tabaôth, fils de Kèras, fils de Soua, fils de Phadaios, fils de Labana, fils d’Aggaba,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 30, 'fils d’Akoud, fils d’Outa, fils de Kétab, fils d’Agaba, fils de Subaï, fils d’Anan, fils de Kathoua, fils de Geddour,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 31, 'fils de Jaïros, fils de Daïsan, fils de Noéba, fils de Khaséba, fils de Gazéra, fils d’Ozios, fils de Phinoé, fils d’Asara, fils de Basthaï, fils d’Asana, fils de Maani, fils de Naphisi, fils d’Akouph, fils d’Akhiba, fils d’Asour, fils de Pharakim, fils de Basalôth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 32, 'fils de Mééda, fils de Koutha, fils de Kharéa, fils de Barkhous, fils de Sérar, fils de Thomoï, fils de Nasi, fils d’Atipha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 33, 'Fils des serviteurs de Salomon: fils d’Assaphiôth, fils de Pharida, fils de Jéèli, fils de Lozôn, fils d’Isdaël, fils de Saphuti,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 34, 'fils d’Agia, fils de Phakareth-sabiè, fils de Sarôthié, fils de Masias, fils de Gas, fils d’Addous, fils de Soubas, fils d’Apherra, fils de Barodis, fils de Saphat, fils d’Amon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 35, 'Total des esclaves sacrés et des fils des serviteurs de Salomon: 372.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 36, 'Voici ceux qui montèrent de Therméléth (leur chef était Karaath), d’Adan et d’Amar,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 37, 'et ne pouvaient pas déclarer que leurs lignées paternelles et leur famille étaient issues d’Israël: fils de Dalan le fils de Touban, fils de Nékodan: 652.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 38, 'Et issus des prêtres, ceux qui avaient des prétentions au sacerdoce et ne furent pas trouvés: fils d’Obbia, fils d’Akkos, fils de Joddous (celui qui avait pris Augia pour femme, parmi les filles de Pharzellaios et avait été appelé de son nom):');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 39, 'et ceux-là, comme on avait cherché leur liste généalogique dans le registre et qu’on ne l’avait pas trouvée, ils furent écartés des fonctions sacerdotales');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 40, 'et Néhémie leur dit, ainsi qu’Attharias, de ne pas avoir part aux choses saintes, jusqu’à ce que se lève un Grand Prêtre revêtu de la Révélation et de la Vérité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 41, 'Au total ils étaient: Israël, à partir des plus de douze ans, hormis les serviteurs et les servantes: 42.360; leurs serviteurs et leurs servantes: 7337; joueurs et chanteurs de psaltérion: 245.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 42, 'chameaux: 435, et chevaux: 7036; mulets: 245; bêtes de somme: 5525.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 43, 'Et parmi les chefs répartis par lignées paternelles, comme ils arrivaient au sanctuaire de Dieu qui est à Jérusalem, ils firent vœu de faire se lever la maison sur son emplacement, autant qu’il était en leur puissance,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 44, 'et de donner pour le sanctuaire un trésor, destiné aux travaux, de mille mines d’or, cinq mille mines d’argent et cent habits sacerdotaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 45, 'Et les prêtres, les Lévites et ceux du peuple s’établirent dans Jérusalem et son territoire, et les psalmistes sacrés et les huissiers, et tout Israël dans leurs villages.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 46, 'Au début du septième mois, et comme les fils d’Israël étaient chacun dans leurs biens, ils s’assemblèrent d’un même cœur sur l’aire de la première porte, celle qui donne sur l’est.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 47, 'Et Jésus, le fils de Josédék, se présenta avec ses frères les prêtres, ainsi que Zorobabel, le fils de Salathiel, avec ses frères, et ils disposèrent l’autel du Dieu d’Israël');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 48, 'pour y apporter les holocaustes conformément à ce qui est stipulé dans le livre de Moïse, l’homme de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 49, 'Et on se coalisa contre eux parmi les autres nations de la terre; et ils relevèrent l’autel sur son emplacement parce qu’ils étaient un objet de haine pour eux, et toutes les nations qui sont sur la terre les fortifièrent, et ils faisaient monter la fumée des offrandes au temps fixé et les holocaustes pour le Seigneur le matin et le soir,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 50, 'et ils conduisirent la fête de la fixation des tentes, comme il est ordonné dans la Loi, et des offrandes de chaque jour, comme il convenait,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 51, 'et après cela des oblations de continuité ainsi que les offrandes des sabbats, des nouvelles lunes et de toutes les fêtes sanctifiées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 52, 'Et tous ceux qui avaient fait un vœu à Dieu, commencèrent à partir de la nouvelle lune du septième mois à apporter des offrandes à Dieu; et le temple de Dieu n’était pas encore construit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 53, 'Et l’on donna de l’argent aux tailleurs de pierre et aux charpentiers, et les Sidoniens et les Tyriens eurent le manger et le boire ainsi qu’un festin pour qu’ils fassent venir du Liban des troncs de cèdre afin d’en flotter les radeaux jusqu’au port de Joppè, selon l’ordonnance qui leur avait été écrite par Cyrus, le roi des Perses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 54, 'Et la deuxième année, se présentant au sanctuaire de Dieu, à Jérusalem, le deuxième mois, Zorobabel le fils de Salathiel commença, ainsi que Jésus le fils de Josédék, leurs frères, les prêtres-Lévites et tous ceux qui étaient venus de la captivité jusqu’à Jérusalem');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 55, 'et ils posèrent les fondations du temple de Dieu à la nouvelle lune du deuxième mois de la deuxième année à leur arrivée en Judée et à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 56, 'Et ils placèrent les Lévites de plus de vingt ans à la tête des travaux du Seigneur, et Jésus, ses fils, ses frères, Kadmiel son frère, les fils de Jésus Emadaboun et les fils de Joda, fils d’Iliadoun avec leurs fils et leurs frères, tous les Lévites, prirent place, d’un même cœur, comme surveillants de travaux, œuvrant pour les travaux dans la maison de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 57, 'Et les bâtisseurs bâtirent le temple du Seigneur, et les prêtres en habits prirent place au milieu de la musique et des trompettes ainsi que les Lévites fils d’Asaph qui, avec leurs cymbales, chantaient des hymnes pour le Seigneur et le bénissaient, suivant l’exemple de David, roi d’Israël,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 58, 'et ils clamèrent par leurs hymnes leur reconnaissance du Seigneur: « Sa bonté et sa splendeur sont pour les éternités à tout Israël... »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 59, 'Et tous les gens du peuple soufflèrent dans les trompettes et crièrent, chantant à grand bruit des hymnes au Seigneur, pour le lever de la maison du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 60, 'Et les plus vieux parmi les prêtres-Lévites et parmi ceux qui siègent au premier rang selon leurs lignées paternelles, ceux qui avaient vu la maison précédente, vinrent vers sa construction avec cri et grande lamentation');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 61, 'et beaucoup allaient à grand bruit au milieu des trompettes et de la liesse');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 62, 'de sorte que le peuple n’entendait pas les trompettes à cause de la lamentation du peuple; c’est que la troupe des joueurs de trompettes était assez grande pour être entendue de loin!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 63, 'Et les ennemis de la tribu de Juda et de Benjamin, entendant cela, vinrent pour découvrir ce qu’était ce bruit de trompettes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 64, 'Et ils découvrirent que les gens sortis de la captivité construisaient le temple pour le Seigneur-Dieu d’Israël');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 65, 'et, s’approchant de Zorobabel, de Jésus et des chefs des lignées paternelles, ils leur disent: « Nous bâtirons avec vous!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 66, 'Car, pareillement à vous, nous écoutons votre Seigneur et nous lui sacrifions depuis les jours d’Asbasareth, roi des Assyriens, qui nous a emmenés ici. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 67, 'Et Zorobabel, Jésus et les chefs des lignées paternelles d’Israël leur dirent: « Ce n’est pas à vous et à nous de construire la maison pour le Seigneur, notre Dieu;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 68, 'car c’est nous seuls qui construirons pour le Seigneur d’Israël conformément à ce que nous a ordonné Cyrus, le roi des Perses. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 69, 'Or, les nations de la terre, pressant et assiégeant ceux qui étaient en Judée, avaient contrecarré la construction,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 70, 'et complotant, flattant le peuple et faisant des soulèvements, ils avaient empêché d’achever la construction tout le temps de la vie du roi Cyrus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 71, 'Et leur construction avait été contrecarrée pendant deux ans, jusqu’au règne de Darius.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 72, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 73, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Or, la deuxième année du règne de Darius, Aggée et Zacharie le fils d’Eddi, les prophètes, prophétisèrent sur les Juifs qui étaient en Judée et à Jérusalem au nom du Seigneur-Dieu d’Israël qui était sur eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Alors se leva Zorobabel, le fils de Salathiel, ainsi que Jésus, le fils de Josédék, et ils commencèrent à construire la maison du Seigneur, celle qui est à Jérusalem, tandis que les prophètes du Seigneur qui étaient avec eux les aidaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'À ce moment-même, Sisinnès le gouverneur de Syrie et de Phénicie, Sathrabouzanès et leurs compagnons étaient venus vers eux et se trouvaient là, et ils leur dirent:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, '« Qui vous a donné un ordre pour que vous construisiez cette maison et que vous acheviez cette toiture et tout le reste? Et qui sont les bâtisseurs qui achèvent cela? »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Et les anciens parmi les Juifs avaient eu de la part du Seigneur la faveur d’une visite venue sur la captivité');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'et on ne s’était pas opposé à leur construction jusqu’à ce que Darius signifie un ordre et s’exprime à leur sujet.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Copie de la lettre que Sisinnès, le gouverneur de Syrie et de Phénicie, Sathrabouzanès et leurs compagnons les chefs en Syrie et en Phénicie écrivirent et envoyèrent à Darius:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, '« Au roi Darius, salut! Que tout soit connu de notre seigneur le roi, à savoir que, comme nous nous étions présentés dans le pays de Judée et étions arrivés dans la ville de Jérusalem, nous avons surpris les anciens parmi les Juifs de la captivité en train de construire dans la ville de Jérusalem une maison pour le Seigneur, grande, étonnante, faite de pierres polies, avec des bois précieux mis sur les murs');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'et ces travaux se font avec ardeur (et le travail va bon train entre leurs mains) et ils sont accomplis en toute splendeur et avec application.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Alors nous nous sommes renseignés auprès de ces anciens, en disant: « Qui vous a donné un ordre pour que vous construisiez cette maison et que vous posiez les fondations de ces travaux? »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Nous les avons donc interrogés afin de te faire savoir et de te dire par écrit les hommes qui sont à leur tête, et nous leur demandions les pièces d’identité des meneurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Mais eux nous ont répondu en disant: « Nous sommes les serviteurs du Seigneur qui a créé le ciel et la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Et la maison avait été construite bien des années auparavant par un grand et puissant roi d’Israël, et elle avait été achevée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Et quand nos pères eurent exaspéré le Seigneur d’Israël, le céleste, en commettant des fautes envers lui, il les a livrés aux mains de Nabuchodonosor, roi de Babylone, roi des Chaldéens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Et ils ont abattu la maison, l’ont incendiée et ont emmené le peuple en captivité à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Or la première année du règne de Cyrus sur le pays de Babylone, le roi Cyrus a ordonné par écrit de construire cette maison;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'et les objets sacrés, en or et en argent, que Nabuchodonosor avait fait sortir de la maison qui est à Jérusalem et avait serrés dans son propre temple, le roi Cyrus les a fait ressortir du temple qui est à Babylone et il les a confiés à Zorobabel et au gouverneur Sanabassare,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'et il lui a ordonné d’emporter tous ces objets et de les déposer dans le temple qui est à Jérusalem, et que ce temple du Seigneur soit construit sur cet emplacement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Alors ce Sanabassare est arrivé et a jeté les fondations de la maison du Seigneur qui est à Jérusalem, et depuis ce temps jusqu’à maintenant elle a été en construction et n’avait pas connu d’achèvement. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, '« Maintenant donc, si tu le juges bon, roi, que l’on aille voir dans les archives royales du seigneur-roi qui sont à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Et si l’on trouve que c’est avec l’agrément du roi Cyrus que se fait la construction de la maison du Seigneur qui est à Jérusalem et que cela est jugé bon par notre seigneur-roi, qu’il s’exprime auprès de nous sur ce sujet. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Alors le roi Darius ordonna que l’on aille voir dans les archives royales situées à Babylone, et l’on trouva dans la forteresse d’Ecbatane qui est en pays mède un volume dans lequel était mentionné ceci:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 23, '« Première année du règne de Cyrus: le roi Cyrus a ordonné de bâtir la maison du Seigneur qui est à Jérusalem, où l’on sacrifie avec un feu continuel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 24, 'dont la hauteur est de soixante coudées, la largeur de soixante coudées, avec trois rangées de pierres polies et une rangée de bois étonnante du pays, et que la somme dépensée soit donnée en puisant dans la maison du roi Cyrus;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 25, 'et que les objets sacrés de la maison du Seigneur, ceux d’or comme ceux d’argent, que Nabuchodonosor a emportés de la maison qui est à Jérusalem et rapportés à Babylone, soient ramenés dans la maison qui est à Jérusalem, où ils étaient déposés, pour y être placés. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 26, 'Alors il ordonna à Sisinnès le gouverneur de Syrie et de Phénicie, à Sathrabouzanès, à leurs compagnons et aux chefs détachés en Syrie et en Phénicie de prendre soin de se tenir à l’écart de l’endroit, et de laisser Zorobabel, le serviteur du Seigneur mais gouverneur de Judée, et les anciens parmi les Juifs construire cette maison du Seigneur à cet endroit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 27, '« Et moi aussi j’ai ordonné en gros qu’on construise et qu’on soit attentif à ce qu’on collabore avec les gens sortis de la captivité de Judée, jusqu’à ce que soit achevée la maison du Seigneur;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 28, 'que sur la perception des impôts de Syrie Creuse et de Phénicie on donne soigneusement une contribution à ces hommes pour des offrandes au Seigneur, au gouverneur Zorobabel pour des taureaux, des béliers et des moutons,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 29, 'et pareillement aussi du blé, du sel, du vin et de l’huile continuellement, chaque année, selon ce que les prêtres qui sont à Jérusalem indiqueront d’en dépenser chaque jour, sans contestation,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 30, 'afin que soient apportées des libations au Dieu très-haut pour le roi et ses enfants et qu’on prie pour leur vie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 31, 'Et qu’on donne des ordres pour qu’à chacun de ceux qui auront transgressé l’une des choses qui ont été déclarées auparavant et ajoutées par écrit ou encore qui l’auront considérée comme non avenue, on prenne un arbre dans sa propriété, qu’on l’y pende et que ce qui lui appartient soit possession royale.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 32, 'Pour cette raison, puisse aussi le Seigneur, dont le nom a été donné là, anéantir tout roi et peuple qui tendra sa main pour s’opposer ou nuire à cette maison du Seigneur qui est à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 33, 'Moi, le roi Darius, j’ai décrété qu’il en soit fait soigneusement selon ces termes. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 34, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Alors Sisinnès le gouverneur de la Syrie Creuse et de la Phénicie, Sathrabouzanès et leurs compagnons suivirent à la lettre les ordres donnés par le roi Darius,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'supervisant les travaux sacrés en coopérant plus soigneusement avec les anciens parmi les Juifs et les chefs religieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Et les travaux sacrés allaient bon train, tandis que prophétisaient Aggée et Zacharie, les prophètes,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'et ils les achevèrent par ordonnance du Seigneur-Dieu d’Israël,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'et avec l’agrément de Cyrus, de Darius et d’Artaxerxès, roi des Perses, fut achevée la maison, la sainte maison, jusqu’au 23 du mois d’Adar de la sixième année du roi Darius.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Et les fils d’Israël, les prêtres, les Lévites et le reste de ceux qui, sortis de la captivité, s’étaient joints à eux, firent conformément à ce qui est dans le livre de Moïse:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'et pour l’inauguration du sanctuaire du Seigneur ils offrirent cent taureaux, deux cents béliers, quatre cents moutons,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'douze chevreaux pour la faute de tout Israël d’après le nombre tiré des maîtres de tribu d’Israël, qui sont douze;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'et les prêtres et les Lévites prirent place, vêtus en fonction de leurs tribus, aux travaux du Seigneur-Dieu d’Israël conformément au livre de Moïse, et les huissiers à chaque porte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Et les fils d’Israël issus de ceux qui étaient sortis de la captivité conduisirent la Pâque le 14 du premier mois; comme les prêtres et les Lévites avaient été purifiés ensemble,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'et que tous les fils de la captivité n’avaient pas été purifiés, comme les Lévites avaient tous été purifiés ensemble,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'eh bien ils offrirent la Pâque pour tous les fils de la captivité ainsi que pour leurs frères les prêtres et pour eux-mêmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Et les fils d’Israël mangèrent, ceux qui étaient sortis de la captivité, tous ceux qui s’étaient écartés des abominations des nations de la terre, en cherchant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Et ils conduisirent la fête des pains sans levain pendant sept jours, se réjouissant en face du Seigneur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'parce qu’il avait tourné le dessein du roi des Assyriens contre eux afin de fortifier leurs mains pour les travaux du Seigneur-Dieu d’Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Et, né bien après ces événements, sous le règne d’Artaxerxès le roi des Perses, s’avança Esdras, fils de Saraios, fils d’Ezérios, fils de Khelkios, fils de Salèmos,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'fils de Saddoukos, fils d’Akhitôb, fils d’Amarios, fils d’Ozios, fils de Bokka, fils d’Abisoué, fils de Phinéés, fils d’Eléazar, fils d’Aaron le premier prêtre;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'cet Esdras monta de Babylone en tant qu’il était un scribe talentueux dans la Loi de Moïse, celle qui a été donnée par le Dieu d’Israël,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'et le roi lui donna de la splendeur, car il avait trouvé grâce devant lui pour toutes ses requêtes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Et parmi les fils d’Israël, les prêtres, les Lévites, psalmistes sacrés, huissiers et esclaves sacrés, ils montèrent avec lui vers Jérusalem, en l’an sept du règne d’Artaxerxès dans le cinquième mois (c’était la septième année pour le roi);');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'en effet, étant sortis de Babylone à la nouvelle lune du premier mois, lors de la nouvelle lune du cinquième mois ils arrivèrent à Jérusalem grâce à la bonne route qui leur avait été donnée par le Seigneur à cause de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'En effet Esdras embrassait beaucoup de savoir de sorte à ne rien omettre des choses extraites de la Loi du Seigneur et de ses commandements, pour enseigner à tout Israël toutes les législations et les jugements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Et l’ordonnance écrite par le roi Artaxerxès parvint à Esdras le prêtre et le lecteur de la Loi du Seigneur, dont ce qui suit est la copie:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, '« Le roi Artaxerxès à Esdras le prêtre et lecteur de la Loi du Seigneur, salut!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Comme je rends aussi, moi, des sentences généreuses, j’ai ordonné que partent avec toi à Jérusalem ceux qui, par choix, le veulent parmi la nation des Juifs, les prêtres et les Lévites, et qui sont aussi dans notre royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Tous ceux donc qui le désirent, qu’ils prennent ensemble leur essor, comme il en a été décidé par moi ainsi que par les sept amis conseillers,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'afin qu’ils aillent voir ce qu’il y a en Judée et à Jérusalem, conformément à ce qu’il en est dans la Loi du Seigneur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'et qu’ils emportent des dons pour le Seigneur d’Israël (ceux dont j’ai fait le vœu ainsi que mes amis) à Jérusalem, ainsi que toute monnaie d’or et d’argent qu’on pourra trouver dans le territoire de Babylone pour le Seigneur à Jérusalem, avec ce qui a été donné en présent par la nation pour le sanctuaire de leur Seigneur, celui qui est à Jérusalem');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'afin d’amasser la monnaie d’or et d’argent pour des taureaux, des béliers, des moutons et ce qui les accompagne');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'de façon à apporter des offrandes sur l’autel de leur Seigneur, celui qui est à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Et tout ce que tu voudras faire avec tes frères de l’or et de l’argent, exécute-le selon la volonté de ton Dieu,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'ainsi que pour les objets sacrés du Seigneur qui t’ont été donnés pour les besoins du sanctuaire de ton Dieu, celui qui est à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Et le reste des choses dont éventuellement tu viendras à avoir besoin pour le sanctuaire de ton Dieu, tu les donneras sur le trésor royal;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'et moi aussi, Artaxerxès, le roi, j’ai donné des ordres aux trésoriers de Syrie et de Phénicie afin que tout ce que mandera Esdras le prêtre et lecteur de la Loi du Dieu, le Très-Haut, ils le lui donnent soigneusement, jusqu’à cent talents d’argent,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'et pareillement aussi jusqu’à cent kors de blé, cent mesures de vin et du sel en abondance;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'que tout ce qui est relatif à la Loi de Dieu soit exécuté soigneusement pour le Dieu, le Très-Haut, afin qu’il n’y ait pas de colère envers le royaume du roi et de ses fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Et l’on s’adresse aussi à vous afin que, pour tous les prêtres, les Lévites, psalmistes sacrés, huissiers, esclaves sacrés et agents de ce sanctuaire, il n’y ait aucune perception d’impôts ni d’autre imposition, et que personne n’ait le pouvoir de leur imposer quelque chose.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Et toi, Esdras, conformément à la sagesse du Dieu, désigne des juges et des légistes pour qu’ils légitiment dans toute la Syrie et la Phénicie tous ceux qui connaissent la Loi de ton Dieu; et quant à ceux qui ne la connaissent pas, tu la leur enseigneras.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Et tous ceux qui transgresseront la Loi de ton Dieu et celle du roi seront soigneusement punis, soit de mort, soit d’un châtiment (ou d’une amende en argent ou d’un emprisonnement). »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, '« Seul soit béni le Seigneur qui a donné ces idées au cœur du roi, pour glorifier sa maison qui est à Jérusalem,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'et qui m’a honoré devant le roi, les conseillers et tous ses amis et hauts personnages!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Et moi j’ai été ferme grâce au soutien du Seigneur, mon Dieu, et j’ai assemblé des hommes issus d’Israël de façon à ce qu’ils montent avec moi!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Et voici ceux qui les conduisaient, selon leurs lignées paternelles et leurs districts, ceux qui montèrent avec moi de Babylone dans le royaume du roi Artaxerxès:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'des fils de Phinéés, Garsomos; des fils de Jétamaros, Gamèlos; des fils de David, Attous, le fils de Sékhénias;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'des fils de Phoros, Zakharias et avec lui, d’après le registre, 150 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'des fils de Phaathmoab, Eliaonias de Zaraias et avec lui 200 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'des fils de Zathoès, Sékhénias de Jézélos et avec lui 300 hommes; des fils d’Adinos, Ben-Jonathou et avec lui 250 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'des fils d’Elam, Jésias de Gotholias et avec lui 70 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'des fils de Saphatias, Zaraias de Mikhaèlos et avec lui 70 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'des fils de Joab, Abadias de Jézélos et avec lui 212 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'des fils de Bani, Assalimoth de Josaphias et avec lui 160 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 37, 'des fils de Babi, Zakharias Bèbaï et avec lui 28 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 38, 'des fils d’Asgath, Joanès Acatan et avec lui 110 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 39, 'les derniers étaient des fils d’Adonikam, et voici leurs noms: Eliphalatos, Jéouèl et Samaias, et avec eux 70 hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 40, 'des fils de Bago, Outhi le fils d’Istalkouros et avec lui 70 hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 41, 'Je les assemblai sur le fleuve appelé Théra, et là-même nous campâmes trois jours, et je les examinai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 42, 'Et n’y trouvant pas de fils de prêtres et des Lévites,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 43, 'j’envoyai un message à Eléazare, Idouèlos, Maasma, Elanatan et Samaias, ainsi qu’à Joribas, Nathan, Ennatan, Zakharias et Mésolamos, les chefs et savants,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 44, 'et je leur dis d’aller auprès d’Addaios, le chef qui est à l’endroit du trésor,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 45, 'leur commandant de s’entretenir avec Addaios, ses frères et les trésoriers de l’endroit pour qu’ils nous envoient des gens qui rempliraient les fonctions sacerdotales dans la maison de notre Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 46, 'Et grâce à la main puissante de notre Seigneur, ils nous amenèrent des hommes savants, des fils de Mooli, fils de Lévi, fils d’Israël: Asébèbias, ses fils et ses frères, dix-huit;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 47, 'et Asébias, Announos et son frère Osaias, parmi les fils de Khanounaios, ainsi que leurs fils, vingt hommes;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 48, 'et parmi les esclaves sacrés, que David et les chefs avaient donnés pour le service des Lévites, deux cent vingt esclaves sacrés: et tous présentèrent leurs pièces d’identité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 49, 'Et là, je fis vœu d’un jeûne pour les garçons en face de notre Seigneur');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 50, 'afin de rechercher auprès de lui une bonne route pour nous, nos enfants qui étaient avec nous et nos bestiaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 51, 'En effet je m’étais blotti sans demander au roi des fantassins et des cavaliers ainsi qu’une escorte d’éclaireurs pour notre sécurité en face de ceux qui s’opposeraient à nous;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 52, 'en effet nous avions dit au roi: « La force de notre Seigneur sera avec ceux qui le cherchent en vue d’un redressement total.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 53, 'Et à nouveau nous priâmes notre Seigneur pour cela et nous le trouvâmes bien favorable.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 54, 'Et d’entre les maîtres de tribus parmi les prêtres, je mis à l’écart douze hommes, c’est-à-dire Sérébias, Asabias et dix hommes avec eux pris parmi leurs frères,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 55, 'et je leur pesai l’argent, l’or et les objets sacrés de la maison de notre Seigneur, dont le roi en personne avait fait présent ainsi que ses conseillers, les hauts personnages et tout Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 56, 'Et après les avoir pesés, je leur confiai six cent cinquante talents d’argent et des objets d’argent de cent talents, cent talents d’or et vingt plats d’or, et des objets de bronze (faits de bronze de bon aloi, ayant le brillant des objets semblables à l’or), douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 57, 'Et je leur dis: « Vous êtes sacrés pour le Seigneur vous aussi, de même que les objets sont sacrés, et l’argent et l’or sont un don votif pour le Seigneur, Seigneur de nos pères;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 58, 'veillez et montez la garde jusqu’à ce que vous les confiiez aux maîtres des tribus parmi les prêtres et les Lévites et aux chefs des lignées paternelles d’Israël à Jérusalem dans les chambres de la maison de notre Seigneur.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 59, 'Et les prêtres et les Lévites qui reçurent l’argent, l’or et les objets qui étaient à Jérusalem les portèrent dans le sanctuaire du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 60, 'Et après avoir levé le camp du fleuve Théra le 12 du premier mois, nous parvînmes à Jérusalem grâce à la main puissante de notre Seigneur qui était sur nous; et sur le trajet il nous protégea de tout ennemi, et nous arrivâmes à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 61, 'Et quand, là-même, vint le troisième jour, l’argent et l’or furent pesés et confiés, dans la maison de notre Seigneur, au prêtre Marmoth d’Ouria');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 62, '(et avec lui était Eléazar le fils de Phinéés, et il y avait avec eux Josabdos de Jésus et Moéth de Sabannos, les Lévites) toutes choses en considération du nombre et du poids, et leur poids total fut noté sur l’heure.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 63, 'Quant à ceux qui étaient sortis de la captivité et se trouvaient là, ils apportèrent en offrandes au Dieu d’Israël Seigneur douze taureaux pour tout Israël, quatre-vingt-seize béliers, soixante et douze moutons, douze boucs pour le salut; tout cela en offrande pour le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 64, 'Et ils remirent les ordonnances du roi aux chefs de palais royaux et aux gouverneurs de Syrie Creuse et de Phénicie, et ils glorifièrent le peuple et le sanctuaire du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 65, 'Et quand cela fut achevé, les chefs vinrent à moi, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 66, '« Le peuple d’Israël, les chefs, les prêtres et les Lévites n’ont pas tenu à l’écart les peuples de la terre qui sont d’une autre race et les impuretés de ces gens, Chananéens, Chettéens, Phérézéens, Jébuzéens, Moabites, Egyptiens et Iduméens;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 67, 'en effet ils ont habité avec leurs filles, aussi bien eux-mêmes que leurs fils, et la semence qui est sainte a été mêlée aux peuples de la terre qui sont d’une autre race, et ceux qui les conduisaient et les hauts personnages ont pris part à cette illégalité depuis le début de l’affaire.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 68, 'Et dès que j’entendis cela, je déchirai mes vêtements et mon habit sacré, je dépilai de la toison de ma tête et de ma barbe et je m’assis, soucieux et affligé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 69, 'Et auprès de moi se rassemblèrent tous ceux qui avaient jamais été mis en branle par la parole du Seigneur d’Israël, car j’étais endeuillé par l’illégalité, et je restai assis, affligé, jusqu’à l’offrande du soir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 70, 'Et après être sorti de la torpeur du jeûne, tenant, déchirés, mes vêtements et mon habit sacré, je fléchis les genoux, je tendis les mains vers le Seigneur et je lui dis:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 71, '« Seigneur, je suis dans la honte, je suis blotti devant ton visage;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 72, 'car nos fautes ont débordé par-dessus nos têtes, et nos erreurs se sont élevées jusqu’au ciel');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 73, 'depuis les temps de nos pères, et nous sommes dans une grande faute jusqu’à ce jour;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 74, 'et à cause de nos fautes et de celles de nos pères nous avons été livrés avec nos frères, avec nos rois et avec nos prêtres aux rois de la terre pour l’épée, la captivité et le butin, dans la honte, jusqu’au jour d’aujourd’hui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 75, 'Et maintenant, jusqu’où a pu aller ta pitié pour nous, Seigneur, pour que nous soient conservés une racine et un nom dans le lieu de ta sainteté');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 76, 'et, afin de dévoiler notre luminaire dans la maison de notre Seigneur, pour nous donner de la nourriture au moment de notre esclavage!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 77, 'Et pendant que nous étions esclaves, nous n’avons pas été abandonnés par notre Seigneur: il nous a fait être en faveur vis-à-vis des rois perses');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 78, 'pour qu’ils nous donnent de la nourriture, glorifient le sanctuaire de notre Seigneur et réveillent la Sion déserte afin de nous donner un fondement en Judée et à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 79, 'Et maintenant que dirons-nous, Seigneur, d’avoir cela? Car nous avons transgressé tes ordonnances, celles que tu as données par la main de tes serviteurs les prophètes, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 80, '« La terre vers laquelle vous allez pour la recueillir en héritage est une terre souillée par la souillure des gens de la terre qui sont d’une autre race, et ils l’ont remplie de leur impureté;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 81, 'et donc ne faites pas habiter vos filles avec leurs fils et ne prenez pas leurs filles pour vos fils;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 82, 'et en tout temps vous ne chercherez pas à pacifier vos relations avec eux, afin d’être forts pour manger les biens de la terre et les laisser en héritage à vos fils pour l’éternité.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 83, 'Et tout ce qui nous arrive est dû à nos actions qui sont mauvaises et à nos grandes fautes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 84, 'Car toi, Seigneur, tu avais allégé nos fautes, et tu nous avais donné une telle racine... Encore une fois nous nous sommes détournés, nous avons transgressé ta Loi pour nous mêler à l’impureté des peuples de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 85, 'Tu ne t’es pas irrité contre nous pour nous détruire jusqu’à ne plus conserver ni notre racine, ni notre semence, ni notre nom?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 86, 'Seigneur d’Israël, tu es vrai! Car en ce jour nous avons été conservés comme racine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 87, 'Voici que maintenant nous sommes en face de toi avec nos illégalités: car, à cause d’elles, nous ne pouvons plus nous tenir debout devant toi... »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 88, 'Et tandis que dans sa prière Esdras disait sa componction, pleurant, gisant à terre devant le sanctuaire, ils se rassemblèrent auprès de lui, venus de Jérusalem en une troupe extrêmement nombreuse, hommes, femmes et jeunes gens; car la lamentation était grande dans la foule.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 89, 'Et Jékhonias, le fils de Jéèlos, des fils d’Israël, prit la parole et dit à Esdras: « C’est nous qui avons commis une faute envers le Seigneur et avons habité avec des femmes d’une autre race, issues des peuples de la terre; et maintenant il y a un espoir pour Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 90, 'Qu’en ce lieu on nous fasse prêter serment devant le Seigneur de chasser toutes nos femmes qui sont issues de ceux d’une autre race, avec leurs enfants, comme tu en as jugé ainsi que tous ceux qui obéissent à la Loi du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 91, 'Lève-toi! Exécute! Car c’est à toi que revient la chose, et nous sommes avec toi pour prêter main-forte. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 92, 'Et Esdras se leva et fit prêter serment aux maîtres de tribu parmi les prêtres et les Lévites de tout Israël de faire comme il avait été dit; et ils jurèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 93, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 94, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 95, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 96, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Et Esdras se leva de la cour du sanctuaire, marcha vers la chambre de Joanan, le fils d’Eliasibos,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'et y trouva gîte sans toucher au pain et sans boire d’eau, endeuillé à cause des illégalités de la foule qui étaient grandes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Et dans toute la Judée et à Jérusalem il y eut pour tous ceux qui étaient sortis de la captivité une proclamation par héraut de se rassembler à Jérusalem;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'et tous ceux qui ne se présenteraient pas d’ici deux ou trois jours conformément au jugement des anciens qui siégeaient au premier rang, on consacrerait leurs bestiaux et leur personne serait déclarée étrangère à la foule de la captivité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Et ceux de la tribu de Juda et de Benjamin se rassemblèrent dans les trois jours à Jérusalem (c’était le neuvième mois, le 20 du mois),');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'et toute la foule vint siéger sur l’aire du sanctuaire, tremblant à cause de l’hiver qui sévissait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Et Esdras se leva et leur dit: « Vous avez agi illégalement, vous avez habité avec des femmes d’une autre race pour imputer une faute à Israël!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Et maintenant offrez au Seigneur-Dieu de nos pères un acte de reconnaissance qui soit splendeur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'faites sa volonté, éloignez-vous des peuples de la terre et des femmes qui sont d’une autre race! »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Et dans toute la foule ils s’exclamèrent et ils dirent avec une grande clameur: « Nous ferons comme tu as dit;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'mais la foule est nombreuse et le temps est hivernal, et nous n’avons pas la force de rester là en plein air, il n’y a pas moyen, et pour nous ce n’est pas l’affaire d’un jour ou deux: car nous avons commis davantage de fautes dans ces domaines.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Mais que ceux qui conduisent la foule restent, et que tous ceux qui sont de nos habitations et qui ont des femmes d’une autre race prennent date pour se présenter;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'et, pour chaque endroit aussi, les anciens et les juges jusqu’à ce qu’on détache de nous la colère du Seigneur pour cette affaire. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Jonathas, le fils d’Azaèlos, et Jésias, le fils de Thokanos, s’en chargèrent à ces conditions et Mossolamos, Lévis et Sabbataios furent leurs assesseurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Et ceux qui étaient sortis de la captivité agirent conformément à toutes ces conditions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 16, 'Et Esdras, le prêtre, se choisit des hommes qui étaient chefs de leurs lignées paternelles, tous par leur nom, et ils se réunirent à la nouvelle lune du dixième mois, afin d’examiner l’affaire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 17, 'Et l’on mena jusqu’au bout l’enquête contre les hommes qui détenaient des femmes d’une autre race, jusqu’à la nouvelle lune du premier mois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 18, 'Et l’on trouva parmi les prêtres qui étaient rassemblés des gens qui avaient des femmes d’une autre race;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 19, 'issus des fils de Jésus, le fils de Josédék, et de ses frères: Maséas, Eléazare, Joribos et Jodanos;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 20, 'et ils promirent, la main tendue, de chasser leurs femmes et, pour l’apaise-ment, des béliers en raison de leur erreur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 21, 'Et issus des fils d’Emmèr: Ananias, Zebdaios, Manès, Samaios, Jièl et Azarias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 22, 'Et issus des fils de Phaisour: Elionaïs, Massias et Ismaël, ainsi que Nathanaël, Okidèlos et Salthas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 23, 'Et issus des Lévites: Jozabdos, Séméïs, Kolios (c’est-à-dire Kalitas), Pathaios, Ooudas et Joanas;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 24, 'issus des psalmistes sacrés: Eliasibos, Bacchouros;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 25, 'issus des huissiers: Salloumos et Tolbanès.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 26, 'Issus d’Israël: issus des fils de Phoros: Jermas, Jésias, Melkhias, Miaminos, Eléazare, Asibias et Bannaias;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 27, 'issus des fils d’Elam: Matanias et Zakharias, Jezrièlos, Obadios, Jérémoth et Elias;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 28, 'et issus des fils de Zamoth: Eliadas, Eliasimos, Othonias, Jarimoth, ainsi que Sabathos et Zerdaias;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 29, 'et issus des fils de Bèbaï: Joannès, Ananias, Zabdos et Emathis;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 30, 'et issus des fils de Mani: Olamos, Mamoukhos, Jédaios et Jasoubos, ainsi qu’Asaèlos et Jérémoth;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 31, 'et issus des fils d’Addi: Naathos et Moosias, Lakhounos, Naïdos, Beskaspasmus, Sesthèle, Balnouos et Manassèas;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 32, 'et issus des fils d’Annan: Elionas, Asaias, Melkhias, Sabbaias et Simon Khosamaios;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 33, 'et issus des fils d’Asom: Maltannaios, Mattathias, Sabannaious, Eliphalat, Manassès et Séméï;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 34, 'et issus des fils de Baani: Jérémie, Momdios, Maèros, Jouèl et Mamdaï, ainsi que Pédias et Anos, Karabasion et Eliasibos, et Mamnitanaïmos, Eliasis, Bannous, Elialis, Soméïs, Sélémias, Nathanias; et issus des fils d’Ezora: Sessis, Ezril, Azaèlos, Samatos, Zambris, Josèpos;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 35, 'et issus des fils de Nooma: Mazitias, Zabadaias, Edaïs, Jouèl, Banaias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 36, 'Tous ceux-là avaient habité avec des femmes d’une autre race; et ils les répudièrent avec les enfants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 37, 'Et les prêtres et les Lévites et ceux d’Israël habitèrent à Jérusalem et dans son territoire. C’était la nouvelle lune du septième mois (et les fils d’Israël étaient dans leurs habitations),');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 38, 'alors toute la foule s’assembla d’un même cœur sur l’aire de la porte du sanctuaire qui donne sur l’est');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 39, 'et ils dirent à Esdras, le Grand Prêtre et lecteur, d’apporter la Loi de Moïse, celle qui avait été remise par le Seigneur-Dieu d’Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 40, 'Et le Grand Prêtre Esdras apporta la Loi à toute la foule, de l’homme jusqu’à la femme, et à tous les prêtres pour qu’ils entendent la Loi à la nouvelle lune du septième mois;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 41, 'et il lut sur l’aire de la porte du sanctuaire, de l’aurore jusqu’à midi, en face des hommes et femmes, et dans toute la foule ils abandonnèrent leur esprit à la Loi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 42, 'Et Esdras, le prêtre et lecteur de la Loi, se tenait debout sur l’estrade de bois qu’on avait préparée,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 43, 'et à côté de lui se tenaient Mattathias, Sammous, Ananias, Azarias, Ourias, Ezékias, Baalsamos sur la droite,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 44, 'et sur la gauche Phadaios, Misaël, Melkhias, Lothasoubos, Nabarias, Zakharias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 45, 'Et Esdras souleva le livre de la Loi en face de la foule (car il siégeait glorieusement au premier rang, en face de tous)');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 46, 'et alors, quand il défit la Loi, tous se tinrent debout. Et Esdras bénit le Seigneur-Dieu, Dieu le Très-Haut, Sabaoth Tout-Puissant,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 47, 'et toute la foule cria « Amen!», et après avoir levé haut leurs mains, ils tombèrent face contre terre pour se prosterner devant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 48, 'Jésus, Anniouth et Sarabias, Jadinos, Jakoubos, Sabbataios, Autaias et Maiannas, ainsi que Kalitas et Azarias, et Jozabdos, Ananias et Phalias, les Lévites, enseignaient la Loi du Seigneur et ils lisaient à la foule la Loi du Seigneur, en inspirant en même temps la lecture.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 49, 'Et Attaratès dit à Esdras, le Grand Prêtre et lecteur, et aux Lévites qui avaient enseigné à la foule, à tous les gens:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 50, '« Cette journée est sainte pour le Seigneur (et tous pleuraient tandis qu’ils écoutaient la Loi);');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 51, 'allez donc manger des nourritures grasses et boire des douceurs, et envoyez des colis à ceux qui n’en ont pas,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 52, 'car sainte est la journée pour le Seigneur; et ne vous affligez pas, car le Seigneur vous glorifiera. »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 53, 'Et les Lévites donnèrent des ordres à tout le peuple, disant: « Cette journée est sainte, ne vous affligez pas! »');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 54, 'Et ils allaient tous manger, boire, se réjouir, donner des colis à ceux qui n’en avaient pas et grandement se réjouir,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 55, 'parce qu’ils avaient aussi été inspirés par les paroles qui leur avaient été enseignées. Et ils se rassemblèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'La première année de la domination de Cyrus, roi des Perses, la parole du Seigneur qu\'avait proférée la bouche de Jérémie le prophète, devait s\'accomplir; le Seigneur excita l\'esprit de Cyrus, roi des Perses, et il envoya en tout son royaume une proclamation par écrit, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Voici ce qu\'a dit Cyrus, roi des Perses: Le Seigneur Dieu du ciel m\'a donné tous les royaumes de la terre, et lui-même a jeté les yeux sur moi pour que je lui bâtisse un temple à Jérusalem en Judée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Qui donc, parmi vous tous, est de son peuple? Son Dieu sera avec lui, et il partira pour Jérusalem en Judée; qu\'il y bâtisse le temple du Dieu d\'Israël; le seul Dieu est celui qui réside à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Tous ceux de ce peuple qui vivent encore, en quelque lieu qu\'ils habitent, les hommes de ce lieu les aideront de dons en argent, en or, en meubles, ou en bestiaux, outre ce qu\'ils offriront volontairement pour le temple de Dieu à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Alors, se levèrent les chefs de famille de Juda et de Benjamin, et les prêtres et les lévites, tous ceux que l\'Esprit de Dieu excita à partir et à relever le temple du Seigneur à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Et tous ceux qui les entouraient leur fortifièrent les mains avec des vases d\'argent, de l\'or, des meubles, des bestiaux et des présents, outre les dons volontaires pour le temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Et le roi Cyrus offrit les vases du temple du Seigneur que Nabuchodonosor avait enlevés de Jérusalem, et qu\'il avait dédiés au temple de son Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Cyrus, roi des Perses, les donna par la main de Mithradate le trésorier, et celui-ci les compta avec Sasabasar, chef de Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'En voici le nombre: trente coupes d\'or, mille d\'argent, vingt-neuf de divers genres, trente coupes d\'or,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Quatre cent dix doubles coupes d\'argent, et mille autres vases.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Il y avait en tout cinq mille quatre cents vases d\'or et d\'argent qui furent emportés par Sasabasar, du lieu d\'exil de Babylone, à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Et voici les fils de la terre promise qui partirent de la captivité et du lieu d\'exil où les avait transportés Nabuchodonosor, roi de Babylone, pour retourner à Jérusalem et en Juda, chacun en sa ville.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Ceux qui partirent avec Zorobabel furent: Josué, Néhémias, Saraïas, Réhétias, Mardochée, Balasan, Masphar, Bachué, Rehum, Baana. Voici le dénombrement du peuple d\'Israël');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Fils de Pharès: deux mille cent soixante-douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Fils de Saphatia: trois cent soixante-douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Fils d\'Arès: sept cent soixante-quinze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Fils de Phaath -Moab, issus des fils de Josué et de Joab: deux mille huit cent douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Fils d\'Elam: mille deux cent cinquante-quatre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Fils de Zatthua: neuf cent quarante-cinq.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Fils de Zacchu: sept cent soixante.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Fils de Banui: six cent quarante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Fils de Balai: six cent vingt-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Fils d\'Asgad: mille deux cent vingt-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Fils d\'Adonicam: six cent soixante-six.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Fils de Bagué: deux mille cinquante-six.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Fils d\'Addin: quatre cent cinquante-quatre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Fils d\'Ater, issu d\'Ezéchias: neuf cent huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Fils de Bassu: trois cent vingt-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Fils de Jora: cent douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Fils d\'Asum: deux cent vingt-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Fils de Gaber: quatre-vingt-quinze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 21, 'Fils de Bethléem: cent vingt-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 22, 'Fils de Netopha: cinquante-six.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 23, 'Fils d\'Anathoth: cent vingt-huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 24, 'Fils d\'Asmoth: quarante-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 25, 'Fils de Cariathiarim, Haphira et Beroth: sept cent quarante-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 26, 'Fils de Rhama et de Gabaa: six cent vingt et un.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 27, 'Hommes de Machmas: cent vingt-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 28, 'Hommes de Béthel et d\'Aia: quatre cent vingt-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 29, 'Fils de Nabu: cinquante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 30, 'Fils de Magebis: cent cinquante-six.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 31, 'Fils d\'Elamar: douze cent cinquante-quatre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 32, 'Fils d\'Elam: trois cent vingt.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 33, 'Fils de Lodadi et d\'Ono, sept cent vingt-cinq.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 34, 'Fils de Jéricho: trois cent quarante-cinq.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 35, 'Fils de Senaa: trois mille six cent trente.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 36, 'Prêtres, fils de Jedua, de la maison de Josué: neuf cent soixante-treize.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 37, 'Fils d\'Emmer: mille cinquante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 38, 'Fils de Phassur: douze cent quarante-sept.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 39, 'Fils d\'Erem: mille sept.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 40, 'Lévites, fils de Josué et de Cadmiel, des fils d\'Oduia: soixante-quatorze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 41, 'Chantres, fils d\'Asaph: cent vingt-huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 42, 'Fils des portiers: fils de Sellom, fils d\'Atér, fils de Telmon, fils d\'Acub, fils d\'Alita, fils de Sobaï: en tout, cent trente-neuf.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 43, 'Les Nathinéens: fils de Suthia, fils d\'Asupha, fils de Tabaoth');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 44, 'Fils de Cades, fils de Siaa, fils de Phadon,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 45, 'Fils de Laban, fils d\'Agaba, fils d\'Acub,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 46, 'Fils d\'Agab, fils de Selam, fils d\'Anan,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 47, 'Fils de Geddel, fils de Gaar, fils de Rhaïa,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 48, 'Fils de Rason, fils de Necoda, fils de Gazena,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 49, 'Fils d\'Azo, fils de Phasé, fils de Basi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 50, 'Fils d\'Asena, fils de Mounim, fils de Nephusim,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 51, 'Fils de Bacbuc, fils d\'Acupha, fils d\'Azur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 52, 'Fils de Basaloth, fils de Maüda, fils d\'Arsa,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 53, 'Fils de Barcos, fils de Sisara, fils de Théma,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 54, 'Fils de Nasthié, fils d\'Atupha,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 55, 'Fils de serviteurs de Salomon, fils de Sotaï, fils de Sephèra, fils de Phadura,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 56, 'Fils de Jeligla, fils de Darcon, fils de Gedel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 57, 'Fils de Saphatia, fils d\'Atil, fils de Phacherath, fils d\'Aseboïm, fils d\'Emeï;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 58, 'Total des Nathinéens et des fils d\'Abdeselma: trois cent quatre vingt- douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 59, 'Et voici tous ceux qui partirent de Thelmelech: Thelaresa, Cherub, Hédan, Emmer; et ils n\'étaient point capables de déclarer leurs familles paternelles ni leur race; car ils étaient nés hors d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 60, 'Fils de Daldia, fils de Rua, fils de Tobias, fils de Necoda: six cent cinquante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 61, 'Et parmi les fils des prêtres, les fils de Labia, les fils d\'Accus, les fils de Berzellaï, qui épousa l\'une des filles de Berzellaï le Galaadite, et qui prit son nom;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 62, 'Ceux-là cherchèrent leur généalogie, mais ils ne la trouvèrent pas, et ils furent rejetés du sacerdoce.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 63, 'Et l\'athersastha leur dit de ne point manger des choses les plus saintes jusqu\'à ce qu\'un prêtre fût suscité, portant lumières et perfections.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 64, 'Or, toute l\'Église réunie montait à environ quarante-deux mille trois cent soixante âmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 65, 'Sans compter leurs serviteurs et leurs servantes au nombre de sept mille trois cent trente-sept, parmi lesquels il y avait deux cents chantres et chanteuses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 66, 'Ils avaient sept mille trente-six chevaux, deux cent quarante-cinq mulets,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 67, 'Quatre cent trente-cinq chameaux, six mille sept cent vingt ânes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 68, 'Et quelques-uns des chefs de famille, lorsqu\'ils entrèrent dans le temple du Seigneur à Jérusalem, offrirent volontairement de le relever au lieu qui était préparé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 69, 'Autant que le comportaient leurs richesses; ils donnèrent donc, au trésor des travaux, soixante et un mille mines d\'or pur, cinq mille mines d\'argent, et cent costumes sacerdotaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 70, 'Et les prêtres, et les lévites, et ceux du peuple, et les chantres, et les portiers, et les Nathinéens, et tout Israël, s\'établirent dans leurs villes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Et le septième mois arriva, et les fils d\'Israël étaient dans leurs villes, et le peuple se rassembla comme un seul homme à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Et Josué, fils de Josédec, et les prêtres, ses frères, et Zorobabel, fils de Salathiel, et ses frères, s\'étant mis en avant, bâtirent l\'autel du Seigneur leur Dieu pour y offrir des holocaustes, comme il est écrit en la loi de Moise, homme de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Ils le relevèrent d\'abord où il était autrefois, car ils avaient crainte des peuples d\'alentour; ils rétablirent l\'holocauste du Seigneur, le matin et le soir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Et ils célébrèrent la fête des tabernacles, ainsi qu\'il est écrit, faisant les holocaustes quotidiens, selon le nombre déterminé jour par jour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Puis, après la fête, ils offrirent l\'holocauste perpétuel, les sacrifices des nouvelles lunes, et de toutes les fêtes consacrées au Seigneur, et ceux que l\'on offrait volontairement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Le premier jour du septième mois, ils commencèrent à offrir des holocaustes au Seigneur, et les fondations du temple n\'étaient pas encore jetées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Et ils donnèrent de l\'argent aux tailleurs de pierres, aux charpentiers; quant aux Sidoniens et aux Tyriens qui leur amenèrent jusqu\'au port de Joppé des cèdres du Liban, selon la permission que Cyrus, roi des Perses, leur avait accordée, ils leur donnèrent le manger et le boire, et de l\'huile.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Et la seconde année de leur retour dans le temple du Seigneur à Jérusalem, le second mois, Zorobabel, fils de Salathiel; Josué, fils de Josedec, ce qui restait de leurs frères les prêtres et les lévites, tous ceux qui étaient sortis de captivité, commencèrent les travaux, et ils chargèrent de la surveillance des ouvriers les lévites de vingt ans et au-dessus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Josué, ses fils et ses frères; Cadmiel, de la maison de Juda, et ses fils, prirent la direction des travaux qui se faisaient dans le temple, secondés par les lévites, fils d\'Henadad, et leurs fils et leurs frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Ils jetèrent les fondations pour y asseoir le temple du Seigneur; cependant, les prêtres, revêtus de leurs robes, sonnèrent de la trompette, et les lévites, fils d\'Asaph, au bruit des cymbales, chantaient les louanges du Seigneur, comme l\'avait prescrit David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Ils louaient le Seigneur et lui rendaient grâces tour à tour, parce qu\'il est bon, parce que sa miséricorde envers Israël doit durer toujours. Et dans sa joie, tout le peuple, à grands cris, louait le Seigneur, à cause de la fondation du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Et un grand nombre de prêtres, de lévites, de chefs de famille, avancés en âge, qui avaient vu le temple dans son premier état, et qui revoyaient de leurs yeux ce temple, élevaient la voix et pleuraient, tandis que la foule, en signe de joie, élevait encore plus haut le chant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Et nul ne pouvait distinguer les marques d\'allégresse de la voix de ceux qui pleuraient, parce que le peuple jetait de grands cris, et que la rumeur en retentissait au loin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Et ceux qui opprimaient Juda et Benjamin ouïrent que les enfants de la captivité bâtissaient un temple au Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Et ils s\'approchèrent de Zorobabel et des chefs de famille, et ils leur dirent: Nous bâtirons avec vous, parce que, comme vous, nous cherchons notre Dieu, et que nous lui sacrifions, depuis le temps d\'Asaradan, roi des Assyriens, qui nous a transportés ici.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Et Zorobabel, et Josué, et le reste des chefs de famille d\'Israël, leur répondirent: Ce n\'est pas avec vous que nous bâtirons un temple à notre Dieu; car, nous seuls, tous ensemble, nous bâtirons au Seigneur notre Dieu, comme nous l\'a prescrit Cyrus, roi des Perses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Et le peuple de la terre affaiblissait les mains de Juda, et il l\'empêchait de bâtir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Et des gens, salariés pour nuire aux fils de Juda, complotèrent pour ruiner leurs desseins, tant que vécut Cyrus, jusqu\'au règne de Darius, roi des Perses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Au commencement du règne d\'Assuérus, ils écrivirent une lettre contre ceux qui habitaient Jérusalem et Juda.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Et, durant les jours d\'Arthasastha, Tabéel écrivit une lettre bienveillante à Mithradate et aux autres serviteurs; le collecteur des impôts écrivit à Arthasastha, roi des Perses, une lettre en syriaque avec la traduction.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Rheum le chancelier, et Samsa le scribe, écrivirent aussi une lettre contre Jérusalem au roi Arthasastha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Voici ce que jugent Rhéum le chancelier, Samsa le scribe, et le reste de ceux qui, avec nous, sont tes serviteurs: les Dinéens, les Apharsathachéens, les Tharphaléens, les Apharséens, les Arechyéens, les Babyloniens, les Susanachéens, les Davéens,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Et les autres nations que le grand et vénérable Assenaphar a transportées dans les villes de Samarie; celles qui résident sur le territoire en deçà du fleuve.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Suit la teneur de la lettre qu\'ils envoyèrent: À Arthasastha, roi, ses serviteurs, en deçà du fleuve:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Que le roi sache que les Juifs qui sont partis de son territoire pour cette terre sont arrivés à Jérusalem, ville rebelle et méchante, qu\'ils la rebâtissent, qu\'ils en ont restauré les remparts, et qu\'ils les ont élevés au-dessus des fondations.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Que le roi sache bien qu\'aussitôt leur ville reconstruite et leurs murs réparés, ils cesseront d\'être tes tributaires, ils ne donneront rien; et ainsi, ils feront tort aux rois;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Et il ne nous est point possible de voir le roi outragé; c\'est pourquoi nous avons envoyé un message pour instruire le roi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Afin que l\'on regarde dans le livre des archives de tes pères, où tu trouveras et tu apprendras que cette ville est une ville rebelle, qu\'elle fait tort aux rois et aux royaumes, qu\'il y a toujours eu chez elle des esclaves fugitifs, et que c\'est pour cela qu\'elle a été dépeuplée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Nous déclarons donc au roi que, si cette ville est rebâtie, si ses remparts sont relevés, il n\'y aura plus de paix pour toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Et le roi envoya dire à Rhéum le chancelier, à Samsa le scribe, et à ses serviteurs qui habitaient en Samarie et en deçà du fleuve: La paix;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Le collecteur des impôts que vous nous avez envoyé a été appelé devant moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Et j\'ai fait un édit; puis, nous avons examiné, et nous avons trouvé que cette ville de tout temps s\'est soulevée contre les rois; que la rébellion, que la désertion y résident.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Or, il y a eu en Jérusalem des rois puissants; ils ont maîtrisé toute la contrée au delà de l\'Euphrate; d\'abondants revenus et des impôts leur ont été payés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Maintenant donc, faites un édit pour suspendre le travail de ces hommes; cette ville ne sera plus rebâtie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Soyez attentifs à maintenir cet édit; ne vous en relâchez point, de peur qu\'un jour le mal ne s\'y aggrave au détriment du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Le collecteur des impôts d\'Arthasastha, roi, lut donc cette lettre devant Rhéum le chancelier, Samsa le scribe, et les autres serviteurs du roi, et ils allèrent en toute hâte à Jérusalem et en Juda avec des troupes et de la cavalerie, et ils arrêtèrent les travaux du peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 24, 'Ainsi, la reconstruction du temple de Dieu fut suspendue à Jérusalem, et on ne la reprit qu\'à la seconde année du règne de Darius.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Or, Aggée le prophète, et Zacharie, fils d\'Addo, firent, devant les Juifs qui se trouvaient en Juda et à Jérusalem, au nom du Dieu d\'Israël, une prophétie qui les concernait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Alors, Zorobabel, fils de Salathiel, et Josué, fils de Josedec, se mirent en avant, et ils commencèrent à bâtir le temple de Dieu à Jérusalem, et les prophètes de Dieu étaient avec eux, leur prêtant secours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'En ce temps-là, Thanthanaï, gouverneur de ce côté de l\'Euphrate, et Satharbuzanaï, et les autres serviteurs du roi, vinrent à eux, et leur dirent: Qui a fait en votre faveur un édit pour que vous bâtissiez ce temple et que vous fassiez ces apprêts?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Et ils ajoutèrent: Quels sont les noms des hommes qui bâtissent cette ville?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Mais les yeux de Dieu étaient ouverts sur la captivité de Juda, et ces hommes ne suspendirent pas les travaux jusqu\'à ce qu\'un édit fût fait par Darius. Et alors, à ce sujet, le collecteur des impôts envoya');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'La traduction de la lettre qu\'avaient écrite, pour le roi Darius, Thanthanaï, gouverneur de ce côté de l\'Euphrate; Satharbuzanaï et les autres Apharsachéens, serviteurs du roi, sur la rive droite de l\'Euphrate.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Ils avaient écrit pour lui un rapport, et voici en quels termes: Paix entière au roi Darius.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Que le roi sache que nous sommes allés en Judée dans le temple du grand Dieu; or, ce temple est rebâti en pierres de choix, et des bois sont placés sur les murs, et ce travail est bien exécuté, et il va bien entre leurs mains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Après l\'avoir vu, nous avons interrogé les anciens, et nous leur avons ainsi parlé: Qui a fait en votre faveur un édit pour que vous bâtissiez ce temple, et que vous fassiez ces apprêts?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Et nous leur avons demandé leurs noms, afin de te les faire connaître, et de prendre par écrit les noms de leurs chefs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Et voici ce qu\'ils nous ont répondu: Nous sommes les serviteurs du Dieu du ciel et de la terre, et nous relevons ce temple qui avait été construit il y a bien des années; un grand roi d\'Israël l\'avait bâti, et il l\'avait établi pour son peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Mais, après cela, nos pères ont irrité le Dieu du ciel, qui les a livrés à Nabuchodonosor le Chaldéen, roi de Babylone; celui-ci a détruit ce temple, et emmené le peuple captif à Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Mais, dans la première année de sa domination, Cyrus, roi des Perses, a fait un édit pour que le temple de Dieu fût rebâti.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Et il a retiré du temple du roi les vases d\'or et d\'argent du temple de Dieu, enlevés de Jérusalem par Nabuchodonosor, et placés dans le temple de Babylone, et il les a remis au trésorier Sabanasar;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Et il lui a dit: Prends tous ces vases, pars, et remets-les à leur place dans le temple de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Alors, ce Sabanasar est venu, et il a jeté les fondations du temple de Dieu à Jérusalem; depuis ce temps; jusqu\'à cette heure, on a travaillé à le construire, et il n\'est pas encore achevé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Et maintenant, si le roi le trouve bon, qu\'il fasse faire des recherches dans le palais du trésor du roi de Babylone, afin de s\'assurer que le roi Cyrus a fait un édit pour que le temple de Dieu fût relevé en Jérusalem; et, quand le roi s\'en sera informé, qu\'il envoie auprès de vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Alors, le roi Darius fit un édit pour que l\'on cherchât dans les bibliothèques où est le trésor de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Et l\'on trouva en cette ville, dans le palais, un chapitre où ce mémorial était écrit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'En la première année de la domination du roi Cyrus, le roi Cyrus a fait cet édit, touchant le saint temple de Dieu à Jérusalem: Que le temple soit rebâti, ainsi que le lieu où l\'on sacrifiait des victimes. Et il en a déterminé la hauteur et la largeur: soixante coudées des deux parts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Et il a ajouté: Qu\'il y ait trois étages en pierres dures et un en bois, et que la dépense soit supportée par le trésor royal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Que l\'on rende les vases d\'or et d\'argent du temple de Dieu, apportés de Jérusalem par Nabuchodonosor, et mis à Babylone; qu\'ils retournent au temple de Jérusalem, à la place où ils étaient, dans le temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Maintenant, vous, gouverneurs au delà du fleuve, vous, Satharbuzanaï et Apharsachéens, mes serviteurs au delà du fleuve, donnez-leur ces choses, et tenez-vous loin d\'eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Laissez faire les travaux du temple de Dieu: que les chefs des Juifs, que leurs anciens bâtissent le temple au lieu où il était.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Un édit est aussi rendu par moi pour que vous ne vous mêliez en rien de ce que feront les anciens des Juifs, pendant qu\'ils bâtiront le temple de ce Dieu, et que, dans le but de ne point arrêter les travaux, on donne avec zèle à ces hommes, sur les impôts du roi, levés au delà de l\'Euphrate, ce qu\'il faudra pour la dépense.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Et, ce qui viendrait à leur manquer, qu\'on le leur donne jour par jour, à mesure qu\'ils le demanderont, soit des bœufs, des béliers, des agneaux, pour les holocaustes du Dieu du ciel, soit du froment, du sel, du vin et de l\'huile, selon le besoin des prêtres qui se trouvent à Jérusalem,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Afin qu\'ils fassent aisément leurs offrandes d\'odeur de suavité au Dieu du ciel, et qu\'ils prient pour la vie du roi et de ses fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Et j\'ai fait un édit portant que quiconque s\'écartera de mes ordres sera attaché à une poutre enlevée de sa maison, et mis à mort sur ce bois, et que sa maison sera confisquée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Puisse le Dieu, dont le nom résidera en ce temple, renverser tout roi ou peuple qui étendra la main pour endommager ou détruire le temple de Dieu à Jérusalem. Moi, Darius, j\'ai fait cet édit; qu\'on soit attentif à s\'y conformer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Alors, Tanthanaï, gouverneur en deçà de l\'Euphrate; Satharbuzanaï, et les autres serviteurs du roi à qui Darius avait écrit, lui obéirent avec zèle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Et les anciens des Juifs et les lévites bâtirent, selon la prophétie d\'Aggée le prophète, et de Zacharie, fils d\'Addo; et ils bâtirent, et ils achevèrent le temple suivant la volonté de Dieu, et grâce aux édits de Cyrus, de Darius et d\'Arthasastha, rois des Perses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Et ils achevèrent le temple le troisième jour du mois d\'adar, et la sixième année du règne de Darius.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Et les fils d\'Israël, et les prêtres, et les lévites, et le reste des fils de l\'exil, firent, avec allégresse, la dédicace du temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Pour la dédicace du temple de Dieu, ils offrirent cent bœufs, deux cents béliers, quatre cents agneaux; et l\'offrande pour les péchés de tout Israël fut de douze boucs, nombre égal à celui des tribus d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Ils rétablirent les prêtres selon leurs divisions, et les lévites selon leurs catégories, pour le service de Dieu à Jérusalem, comme il est écrit au livre de Moïse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Et les fils de l\'exil firent la Pâque le quatorzième jour du second mois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 20, 'Car les prêtres et les lévites s\'étaient purifiés; ils avaient tous été reconnus purs. Et ils immolèrent la pâque pour tous les fils de l\'exil, et pour leurs frères les prêtres et les lévites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 21, 'Et les fils d\'Israël mangèrent la pâque, tant ceux qui étaient revenus de l\'exil que ceux qui s\'étaient préservés de l\'impureté des peuples de la contrée, leurs voisins, et qui avaient cherché le Seigneur Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 22, 'Et ils célébrèrent la fête des Azymes durant sept jours avec allégresse; car le Seigneur les réjouit, et il avait incliné le cœur du roi d\'Assyrie en leur faveur pour fortifier leurs mains dans les travaux du temple du Dieu d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Et, après ces événements, sous le règne d\'Arthasastha, roi des Perses, partit Esdras, fils de Saraïas, fils d\'Azarias, fils d\'Helcias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Fils de Selum, fils de Saddoc, fils d\'Achitob,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Fils de Samarias, fils d\'Esrias, fils de Maréoth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Fils de Zaraïas, fils d\'Ozias, fils de Bocci,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Fils d\'Abisué, fils de Phinéès, fils d\'Eléazar, fils d\'Aaron le premier prêtre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Cet Esdras partit de Babylone; il était scribe et très instruit en la loi de Moïse donnée par le Seigneur Dieu d\'Israël. Et le roi le lui permit, parce que la main du Seigneur son Dieu était près de lui en tout ce qu\'il demandait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Et des chantres, et des portiers, et des Nathinéens, parmi les fils d\'Israël, prêtres ou lévites, partirent pour Jérusalem en la septième année du règne du roi Arthasastha.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Et ils arrivèrent à Jérusalem le cinquième mois de cette même année;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Car, le premier jour du premier mois, ils commencèrent à partir de Babylone, et, le premier jour du cinquième mois, ils entrèrent à Jérusalem, parce que la main du Seigneur était favorable à Esdras.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Esdras, en effet, s\'était adonné de tout son cœur à étudier la loi, à la mettre en pratique, et à enseigner aux fils d\'Israël les commandements et les préceptes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Et voici la traduction de l\'ordre qu\'Arthasastha donna à Esdras, scribe du livre des lois et commandements du Seigneur, plus de ses prescriptions concernant Israël:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Arthasastha, roi des rois, à Esdras, scribe de la loi du Seigneur Dieu du ciel: Que ta demande et ma réponse s\'accomplissent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'J\'ai fait un édit pour que, dans mon royaume, tout homme du peuple d\'Israël, et des prêtres, et des lévites, qui le voudra, parte avec toi pour Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Esdras est envoyé par le roi et ses sept conseillers, pour visiter la Judée et Jérusalem, conformément à la loi de Dieu qui est en ta main.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Et tu porteras l\'or et l\'argent que le roi et ses conseillers offrent volontairement, pour le temple du Seigneur, au Dieu d\'Israël qui réside en Jérusalem,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Et tout l\'argent et l\'or que tu recueilleras en tout le royaume de Babylone, donné volontairement par le peuple et les prêtres, pour le temple de Dieu, à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'À tous ceux qui iront à ce temple, prescris équitablement, selon ta loi, d\'amener des agneaux avec leurs oblations et leurs libations; tu les offriras sur l\'autel du temple du Seigneur votre Dieu à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Et si à toi et à tes frères il plaît, avec le reste de l\'or et de l\'argent, de faire quelque chose, faites-le comme il sera agréable à votre Dieu;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Et remettez en leur place, devant Dieu à Jérusalem, les vases qui te sont donnés pour le service du temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'S\'il est en outre des choses nécessaires au temple de ton Dieu qu\'il te semble bon de donner, tu les donneras aux frais du trésor royal');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Et de mon domaine. Moi, Arthasastha, roi, j\'ai fait un édit pour que l\'on donne promptement à Esdras, prêtre et scribe du Dieu du ciel, tout ce qu\'il vous demandera des trésors publics qui sont au delà de l\'Euphrate,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Jusqu\'à cent talents d\'argent, cent mesures de froment, cent tonneaux de vin, cent tonnes d\'huile; outre le sel, dont la quantité n\'est pas fixée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Que tout ce qui est selon la volonté du Dieu du ciel soit exécuté. Et vous, mes serviteurs, veillez à ce que nul ne mette la main sur le temple du Dieu du ciel, de peur que sa colère ne s\'allume contre le royaume du roi et de ses fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Sachez aussi, pour ce qui regarde tous les prêtres, lévites, chantres, portiers, Nathinéens, employés au service de ce Dieu, qu\'ils n\'ont point à vous payer d\'impôt, et que vous n\'avez point le pouvoir de leur rien demander de servile.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Et toi, Esdras, comme tu as en ta main la sagesse de Dieu, institue des scribes et des juges, afin qu\'au delà du fleuve ils rendent la justice à tout le peuple, à tous ceux qui connaissent la loi de ton Dieu, et enseignez cette loi à ceux qui l\'ignorent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Et quiconque ne se conformera pas avec zèle à la loi de Dieu et à la loi royale, sera jugé et condamné à mort, ou à une correction, ou à l\'amende sur son bien, ou à la prison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Béni soit le Seigneur Dieu de nos pères, qui a donné au roi un tel cœur, pour glorifier le temple du Seigneur à Jérusalem,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Et qui a fait tourner sur moi les yeux et la miséricorde du roi, de ses conseillers, des chefs du royaume et des grands. Et moi, j\'ai été fortifié par la main bienveillante de Dieu qui s\'est posée sur moi, et j\'ai rassemblé les chefs d\'Israël pour les emmener avec moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Et voici les noms des chefs de familles, qui sont venus avec moi sous le règne d\'Arthasastha, roi de Babylone');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Des fils de Phinéès, Gerson; des fils d\'Ithamar, Daniel; des fils de David, Attus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Des fils de Sachanie et des fils de Phoros, Zacharie, et avec lui ses compagnons, cent cinquante hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Des fils de Phaath-Moab, Eliana, fils de Saraïa, et avec lui deux cents hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Et des fils de Zathoé, Sechénias, fils d\'Aziel, et avec lui trois cents hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Et des fils d\'Adin, Obed, fils de Jonathas, et avec lui cinquante hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Et des fils d\'Elam, Isaïe, fils d\'Athélie, et avec lui soixante-dix hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Et des fils de Saphatie, Zabadie, fils de Michel, et avec lui quatre-vingts mâles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Et des fils de Joab, Abadie, fils de Jehiel, et avec lui deux cent dix-huit hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Et des fils de Baani, Selimuth, fils de Joséphie, et avec lui cent soixante hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Et des fils de Babi, Zacharie, fils de Babi, et avec lui vingt-huit mâles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Et des fils d\'Asgad, Johanan, fils d\'Accatan, et avec lui cent dix mâles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Et des fils d\'Adonicam, les derniers, et voici leurs noms: Eliphalat, Jehel et Samaia, et avec eux soixante mâles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Et des fils de Baguai, Uthaï et Zabud, et avec eux soixante-dix mâles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Je les réunis vers le fleuve qui se rend à Evi, et nous y restâmes campés trois jours; et je m\'informai du peuple et des prêtres, et je ne trouvai là pas un fils de Lévi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Ensuite, je donnai mes ordres à Eléazar, à Ariel, à Sémeïas et à Alonam, à Jarib, à Elnatham, à Nathan, à Zacharie, à Mesollam, à Joarim et à Elthanan, hommes doués de sagesse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Et je les envoyai aux chefs, avec l\'argent recueilli dans la contrée, et je leur mis sur les lèvres les paroles qu\'ils avaient à dire à leurs frères les Athinéens, en leur remettant l\'argent recueilli dans la contrée, afin qu\'ils nous amenassent des chantres pour le temple de notre Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Et comme la main de Dieu nous était favorable, ils nous amenèrent un homme: Sachon, des fils de Mooli, fils de Lévi, fils d\'Israël, et d\'abord arrivèrent ses fils et ses frères, en tout dix-huit;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 19, 'Ils nous amenèrent aussi Asebie et Isaïe, des fils de Mérari, et ses frères et ses fils, vingt personnes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 20, 'Et des Nathinéens que David et les chefs avaient donnés pour serviteurs aux lévites, deux cent vingt, tous désignés par leurs noms.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 21, 'Et là, sur le fleuve Ahua je proclamai un jeûne, pour nous humilier devant notre Dieu, et chercher par lui le droit chemin, pour nous et nos enfants, et tout notre bétail.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 22, 'En effet, j\'aurais eu honte de demander au roi des troupes et de la cavalerie, pour nous protéger en route contre tout ennemi, car nous avions dit au roi: La main de notre Dieu est sur tous ceux qui le cherchent pour le bien; mais sa puissance et sa colère sont sur tous ceux qui l\'abandonnent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 23, 'Et nous jeûnâmes, nous fîmes à ce sujet notre prière au Seigneur, et il nous exauça.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 24, 'Et je donnai mes ordres à douze des chefs des prêtres: à Sardias, Asabie, et dix de leurs frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 25, 'Et je pesai pour eux l\'argent, l\'or et les vases des prémices consacrées dans le temple de notre Dieu, que le roi, ses conseillers, ses princes, et tous ceux d\'Israël, qu\'on avait trouvés, avaient offerts,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 26, 'Je pesai ainsi entre leurs mains six cent cinquante talents d\'argent, cent vases d\'argent et cent talents d\'or;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 27, 'Et vingt tasses d\'or du poids d\'environ mille drachmes, et des vases de grand prix, en bel airain brillant, aussi précieux que s\'ils eussent été d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 28, 'Puis, je leur dis: Vous êtes saints aux yeux du Seigneur; les vases sont saints, l\'argent et l\'or ont été volontairement donnés pour le Seigneur Dieu de nos pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 29, 'Veillez sur eux et gardez-les jusqu\'à ce que vous les pesiez devant les princes des prêtres, devant les lévites et devant les chefs de familles de Jérusalem, dans le tabernacle du temple du Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 30, 'Cet or et cet argent pesés de cette manière, les prêtres et les lévites les reçurent pour les porter à Jérusalem, dans le temple du Seigneur notre Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 31, 'Alors, je levai mon camp du fleuve Ahua, le douzième jour du premier mois, pour aller à Jérusalem. Et la main du Seigneur notre Dieu était sur nous, et il nous préserva en route de tout ennemi, de toute attaque ou de toute hostilité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 32, 'Nous arrivâmes à Jérusalem, et nous y demeurâmes trois jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 33, 'Le quatrième jour, nous pesâmes l\'argent, l\'or et les vases, dans le temple du Seigneur, entre les mains de Merimoth, fils d\'Urie, le prêtre, en présence d\'Eléazar, fils de Phinéès; il y avait avec eux les lévites Josabad, fils de Josué, et Noadia, fils de Banaïa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 34, 'On en fit le compte, on en prit le poids, et le poids total fut écrit. En ce temps-là,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 35, 'Les fils de l\'exil revenus de la captivité offrirent en holocauste, au Dieu d\'Israël, douze bœufs pour tout Israël, quatre-vingt-onze béliers, soixante-dix-sept agneaux, et douze boucs pour le péché; tout cela fut offert en holocauste au Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 36, 'Et les édits du roi furent donnés à ses intendants et à ses gouverneurs, d\'en deçà du fleuve, qui glorifièrent le peuple et le temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Après cela, les chefs vinrent me trouver, et ils me dirent: Le peuple d\'Israël, les prêtres, les lévites, ne sont plus séparés des peuples de la terre en leurs abominations; du Chananéen, de l\'Hettéen, du Phérézéen, du Jébuséen, de l\'Ammonite, du Moabite, du Mosérite, de l\'Amorrhéen.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Ils se sont mariés, eux et leurs fils, parmi ces peuples, et la semence sainte s\'est détournée dans les nations de la terre, et la main des princes a été la première, en cette infraction à la loi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Or, quand j\'ouïs ces paroles, je déchirai mes vêtements, je fus saisi de crainte; je m\'arrachai les cheveux et la barbe, et je m\'assis tout contristé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Et tous ceux qui suivaient la loi du Dieu d\'Israël s\'assemblèrent auprès de moi, à cause de cette infraction aux préceptes; et moi, toujours assis, je gardai un morne silence jusqu\'au sacrifice du soir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Et pendant le sacrifice du soir, je sortis de mon abattement; après avoir déchiré mes vêtements, saisi de crainte, je me mis à genoux, et j\'étendis mes mains vers le Seigneur Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Et je dis: Seigneur, je suis plein de honte et de confusion, ô mon Dieu, en levant mon front devant vous; car nos dérèglements se sont accumulés sur nos têtes, et nos péchés ont monté jusqu\'au ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Depuis les jours de nos pères jusqu\'à ce jour, nous avons vécu dans le péché, et à cause de nos transgressions, nous, nos rois, nos fils, nous avons été livrés aux rois des nations, par le glaive, la captivité, le pillage, et nous avons eu la honte au front comme nous l\'avons encore.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Maintenant, notre Dieu a été bienveillant pour nous jusqu\'à nous sauver, nous rétablir en ce lieu où est son sanctuaire, nous éclaircir les yeux, et nous accorder un peu de vie dans notre esclavage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Car nous sommes esclaves; toutefois, en notre servitude, le Seigneur notre Dieu ne nous a pas abandonnés, et il nous a fait trouver miséricorde devant les rois de Perse, pour qu\'ils nous accordassent un peu de vie, qu\'ils relevassent le temple de notre Dieu, qu\'ils le rétablissent en sa désolation, et qu\'ils nous rendissent plus de sûreté en Juda et à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Que dirons-nous après cela, ô notre Dieu? Car nous avons abandonné vos commandements,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Que vous nous aviez donnés par vos serviteurs les prophètes, disant: La terre où vous allez pour qu\'elle soit votre héritage est une terre troublée de fond en comble par les abominations des peuples qui l\'habitent, et qui l\'ont remplie d\'un bout à l\'autre de leurs impuretés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Ne donnez donc pas vos filles à leurs fils, et ne prenez point pour vos fils leurs filles; ne cherchez jamais leur pain ni leur bien-être, afin que vous vous affermissiez, que vous mangiez les biens de cette terre, et que vous les transmettiez en héritage à vos fils pour toujours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Or, après tout ce qui nous est advenu à cause de nos mauvaises actions et de nos grands péchés, vous nous avez sauvés, parce qu\'il n\'est point de Dieu tel que vous, et que vous avez ôté nos iniquités.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Et nous avons recommencé à répudier vos commandements, à nous marier parmi ces peuples; ô Seigneur, ne soyez pas irrité contre nous jusqu\'à nous anéantir, sans que nul parmi nous échappe et soit épargné.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Seigneur Dieu d\'Israël, vous êtes juste, car nous voilà sains et saufs en ce jour; voilà que nous sommes devant vous dans nos péchés, et après de tels excès on ne peut subsister devant vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Et comme Esdras priait, et comme, en pleurant et priant, il élevait la voix devant le temple du Seigneur, la nombreuse Église d\'Israël se rassembla auprès de lui, hommes, femmes et jeunes gens; et le peuple pleura, et en pleurant il éleva la voix.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Et Sechénias, fils de Jehel, des fils d\'Elam, prit la parole, et il dit à Esdras: Nous avons violé la loi de notre Dieu, et nous avons épousé parmi les peuples de la terre promise des femmes étrangères; et maintenant, après cela, Israël espère encore.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Faisons donc alliance avec notre Dieu; et, s\'il le veut, chassons toutes ces femmes et ceux qui sont nés d\'elles. Lève-toi, inspire-leur la crainte des commandements de notre Dieu, et qu\'il soit fait selon la loi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Lève-toi, car l\'affaire te regarde, et nous sommes avec toi; sois fort et agis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Et Esdras se leva, et il fit prêter serment aux chefs, aux prêtres, aux lévites, à tout Israël, d\'exécuter ses ordres, et ils le jurèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Et Esdras se leva de devant le temple, et il alla au trésor gardé par Johanan, fils d\'Elisub, et il y entra, et il ne mangea pas de pain, et il ne but point d\'eau, car il pleurait sur l\'infidélité des fils de l\'exil.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Et l\'on fit dans Juda et à Jérusalem une proclamation qui disait: Tous les fils de l\'exil se réuniront à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Quiconque ne viendra pas dans trois jours, selon l\'ordre des princes et des prêtres, tous ses biens seront anathématisés, et lui-même sera expulsé de l\'Église des fils de l\'exil.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Tous les hommes de Juda et de Benjamin se rendirent donc à Jérusalem. On était au neuvième mois; le vingtième jour du même mois, tout le peuple se tint sur la place du temple de Dieu, à cause du trouble né de cette affaire, et à cause d\'une tempête.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Et Esdras, le prêtre, se leva, et il leur dit: Vous avez violé l\'alliance, et vous avez épousé des femmes étrangères, pour ajouter aux péchés d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Rendez maintenant gloire au Seigneur Dieu de vos pères, et faites ce qui est agréable à ses yeux; séparez-vous des peuples de la terre promise, et des femmes des étrangers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Et toute l\'Église s\'écria: Grande est pour nous cette parole de toi que nous devons accomplir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Mais le peuple est nombreux, le temps est à l\'orage, et il n\'est pas possible de se tenir dehors plus longtemps; d\'ailleurs, ce n\'est point l\'œuvre d\'un ou de deux jours, car, à ce sujet, nous avons multiplié nos fautes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Que nos chefs restent, et qu\'ils aillent, au temps prescrit, en toutes les villes, pour tous ceux qui ont épousé des femmes étrangères; que dans chaque ville ils s\'adjoignent les anciens et les juges, afin de détourner de nous la colère du Seigneur notre Dieu, au sujet de ce péché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Or, il n\'y eut avec moi que Jonathas, fils d\'Azaêl, et Jasias, fils de Thécoé, et ils eurent pour aides Mesollam, et Sabbathaï, le lévite.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Et voici ce que firent les chefs de l\'exil: le prêtre Esdras et les chefs de familles paternelles furent désignés tous nominativement, et ils partirent le premier jour du dixième mois pour faire des enquêtes sur cette affaire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Et, le premier jour du premier mois, ils eurent fini, et connurent tous les hommes qui avaient épousé des femmes étrangères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Et parmi eux furent trouvés des fils de prêtres nés de Josué, fils de Josédec et ses frères, savoir: Maasia, et Eliézer, et Jarib, et Gadalie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Et ils s\'engagèrent à répudier leurs femmes, et ils donnèrent chacun un bélier de son troupeau, pour le péché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Il y eut des fils d\'Emmer Anani et Zabdia;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Et des fils d\'Eram Masahel, Elia, Samaïa, et Ozias;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Et des fils de Phasur: Elionaï, Maasia, Ismaël, Nathanaël, Jozabad et Elasa;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Et des lévites: Jozabad, Samu, Colia (le même que Colite), Phetheia, Judas et Eliézer;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Et des chantres: Elisabadi; et des portiers, Solmen, Telmen et Oduth;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Et d\'Israël, des fils de Phoros: Ramia, Azia, Melchia, Méamin, Eléazar, Asabie et Banaïa;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Et des fils d\'Hélam: Matthanias, Zacharie et Jahiel, Abdias, Jarimoth et Eue;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Et des fils de Zathuca: Elionaï, Elisub, Matthanaï, Armoth, Zabad et Oziza;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Et des fils de Bubeï. Johanan, Ananie, Zabu et Thali;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Et des fils de Banuï: Mosollam, Maluch, Adaïas, Jasub, Saluïa et Remoth;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Et des fils de Phaath-Moab Edné, Chalet, Banaïa, Maasia, Matthanias, Béséléel, Banuï et Manassé;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Et des fils d\'Eram: Eliézer, Jésia, Melchia, Samaïas, Séméon,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Benjamin, Baluch, Samaria;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Et des fils d\'Asem: Metthanie, Matthatha, Zadab, Eliphalet, Jerami, Manassé, Sémeï;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Et des fils de Bani: Moodia, Amram, Uhel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Banaïas, Badaïas, Helcias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Vania, Marimoth, Eliasiph,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Matthanias, Matthanaï; et ainsi firent:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Les fils de Banui, et les fils de Sémeï,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Et Sélémia, et Nathan, et Adaïa,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 40, 'Machadnabu, Séseï, Sariu,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 41, 'Ezriel, et Sélémia, et Samaria,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 42, 'Et Sellum, Amaria, Joseph;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 43, 'Des fils de Nabu: Jahel, Matthanias, Zabad, Zebennas, Jadaï, Johel et Banaïa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 44, 'Tels furent ceux qui avaient épousé des femmes étrangères, et qui en avaient eu des enfants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Récits de Néhémias, fils d\'Helcias. Au mois de chaseleu, en la vingtième année, j\'étais à Suse, résidence royale.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Et Anani, l\'un de mes frères, vint, lui et des hommes de Juda, et je les questionnai, tant sur ceux qui étaient demeurés de la captivité et vivaient encore, que sur Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Et ils me dirent: Ceux qui sont demeurés, et qui ont été laissés de la captivité, sont dans la terre promise en grande détresse et opprobre; les murs de Jérusalem ont été abattus, et ses portes brûlées par le feu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Or, quand j\'eus ouï de telles paroles, je m\'assis et pleurai, et, pendant plusieurs jours, me lamentai, et j\'étais jeûnant et priant devant le Dieu du ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Et je dis: Que cela ne soit, je vous prie, Seigneur Dieu du ciel, Dieu fort, grand et redoutable qui gardez votre alliance et votre miséricorde à ceux qui vous aiment et observent vos commandements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Que votre oreille soit attentive, que vos yeux s\'ouvrent, afin d\'ouïr l\'oraison de votre serviteur que je fais maintenant devant vous, nuit et jour, pour vos serviteurs les enfants d\'Israël; et je me confesse pour les péchés des enfants d\'Israël, en lesquels nous avons péché contre vous. Moi et la maison de mon père avons péché.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Nous avons rompu l\'alliance; nous n\'avons point gardé les commandements, les jugements et les ordonnances que vous avez intimés à Moïse, votre serviteur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Souvenez-vous de la parole que vous avez intimée à Moïse, votre serviteur, disant: Si vous manquez à notre alliance, je vous disperserai parmi les nations.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Et si vous revenez à moi, si vous gardez mes commandements, si vous les pratiquez, quand vous seriez disséminés jusqu\'aux lieux où la terre touche le ciel, je vous en ramènerai, je vous réunirai en la terre que j\'ai choisie pour que mon nom y réside.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Et voici vos serviteurs et votre peuple que vous avez rachetés par votre toute-puissance et votre forte main.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Qu\'ils ne demeurent pas ainsi, Seigneur; mais que votre oreille soit attentive à l\'oraison de votre serviteur et à celle de vos serviteurs qui veulent craindre votre nom. Soyez-lui propice aujourd\'hui à votre serviteur; faites qu\'il trouve miséricorde devant les hommes; or, j\'étais échanson du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Et, au mois de nisan, en la vingtième année du règne d\'Arthasastha, le vin était devant moi, et je pris le vin et le versai au roi, et il n\'y avait là en sa présence nul autre que moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Et le roi me dit: D\'où vient que ton visage est mauvais, et que tu ne te contiens pas? Cela ne serait point si le mal n\'était en ton cœur. Et j\'eus grande crainte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Et je dis au roi: Que le roi vive toujours; comment mon visage ne serait-il pas mauvais, puisque la ville qui est la maison des sépulcres de mes pères est déserte, et que ses portes ont été brûlées par le feu?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Et le roi me dit: À quel sujet me demandes-tu cela? Et je priai le Dieu du ciel;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Et je répondis au roi: S\'il semble bon au roi, si son serviteur trouve grâce devant lui, je demande qu\'il envoie son serviteur en Juda, à la ville des sépulcres de mes pères, et je la réédifierai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Et le roi et sa concubine qui siégeait auprès de lui, me dirent: Jusqu\'à quand durera ton voyage? quand reviendras-tu? Et le roi le trouva bon, et il me laissa partir, et je lui donnai un terme.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Et je dis au roi: Si le roi le trouve bon, qu\'il me donne des lettres pour les gouverneurs au delà de l\'Euphrate, afin qu\'ils ne mettent point d\'obstacle à mon arrivée en Juda,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Et une lettre adressée à Asaph, le garde du jardin qui appartient au roi, afin qu\'il me fournisse du bois pour réparer les portes et les murs de la ville, et la maison où je me logerai. Et, comme la bonne main du Seigneur était avec moi, le roi me donna les lettres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Et j\'arrivai chez les gouverneurs au delà de l\'Euphrate, et je leur remis les lettres du roi. Or, le roi m\'avait fait accompagner par des chefs de l\'armée et par de la cavalerie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Et Sanaballat l\'Aronite, et Tobias, le serviteur ammonite, l\'ouïrent; et il était mauvais pour eux qu\'un homme fût venu faire du bien aux fils d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Et j\'entrai à Jérusalem, et j\'y restai trois jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Et je me levai de nuit, moi et quelque petit nombre de gens, et je ne dis à personne ce que Dieu m\'avait mis dans le cœur de faire pour Israël; et je n\'avais point de bête avec moi, sinon la bête sur laquelle j\'étais monté.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Et je sortis par la porte de la Vallée, passant devant la fontaine des Figuiers, et allant à la porte du Fumier; et je marchais le cœur brisé, à cause des remparts de Jérusalem qu\'ils avaient abattus, et des portes qu\'ils avaient brûlées par le feu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Et je passai devant la porte de la Fontaine, puis, devant la piscine du Roi; et il n\'y avait point de place par où la bête que j\'avais sous moi pût passer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Alors, je m\'en allai montant, de nuit, le long du torrent, et j\'avais le cœur brisé, à cause du mur, et je revins à la porte de la Vallée, et je rentrai.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Et les sentinelles ne surent ni où j\'étais allé ni ce que je voulais faire; et, jusque-là, je n\'en avais rien dit aux Juifs, ni aux prêtres, ni aux premiers du peuple, ni aux chefs, ni au reste de ceux qui faisaient les travaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Et je leur dis: Vous voyez l\'affliction où nous sommes: Jérusalem est déserte, et ses portes ont été brûlées par le feu. Allons, relevons les remparts de la ville, et nous ne serons plus outragés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Et je leur dis que la bonne main de Dieu était avec moi, à en juger par les paroles que le roi m\'avait dites, et j\'ajoutai: Levons-nous, édifions. Et leurs mains furent fortifiées en cette bonne œuvre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Et Sanaballat l\'Aronite, et Tobias le serviteur ammonite, et l\'Arabe Gésam, le surent, et ils nous raillèrent, et ils vinrent à nous, et ils dirent: Qu\'est-ce que vous faites? Vous révoltez-vous contre le roi?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Et je leur répliquai, et je leur dis: Le Dieu du ciel lui-même mènera notre œuvre à bien; et nous, ses serviteurs, nous sommes purs, et nous édifierons. Quant à vous, vous n\'avez ni part, ni droit, ni mémorial en Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Et Eliasub le grand prêtre se leva avec ses frères les prêtres, et ils édifièrent la porte Probatique; eux-mêmes la sanctifièrent, et ils mirent ses battants; ils sanctifièrent aussi la tour de cent coudées, et la tour d\'Anamehel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Et, auprès d\'eux, édifièrent des hommes de Jéricho, et des fils de Zacchur, fils d\'Aman.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Les fils d\'Asana édifièrent la porte des Poissons; eux-mêmes la couvrirent et mirent ses battants, serrures et verrous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Et, auprès d\'eux, édifièrent Ramoth, fils d\'Urie, fils d\'Accos, et Mosollam, fils de Barachias, fils de Mazebel; et, auprès de ceux-ci, Sadoc, fils de Baana.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Et, après ce dernier, se trouvaient des hommes de Thécoé; mais les nobles n\'offrirent pas de ployer leur cou pour un tel service.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Joad, fils de Phasec, et Mesulam, fils de Basodias, édifièrent la porte Ancienne; eux-mêmes la couvrirent et mirent ses battants, serrures et verrous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Et, auprès de ce lieu, édifia Oziel, fils d\'Arachias l\'orfèvre. Et, auprès, Ananias, fils de Roceïm, et les siens terminèrent Jérusalem jusqu\'aux murs de la Grande rue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Et, auprès de ce lieu, édifia Oziel, fils d\'Arachias l\'orfèvre. Et, auprès, Ananias, fils de Roceïm, et les siens terminèrent Jérusalem jusqu\'aux murs de la Grande rue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Et, auprès d\'eux, édifia Raphaïe, fils de Sur, chef de la moitié de la banlieue de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Et, auprès de lui, Jedaïe, fils d\'Eromaph, édifia en face sa maison; et, auprès de lui, Attuth, fils d\'Asabanias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Et, auprès de ce dernier, Melchias, fils d\'Héram, et Asub, fils de Phaat-Moab, édifièrent jusqu\'à la tour des Fours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Et, auprès de là, édifièrent Sallum, fils d\'Alloès, chef de la moitié de la banlieue de Jérusalem, lui et ses filles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Anun et les habitants de Zano relevèrent la porte de la Vallée; ils l\'édifièrent eux-mêmes, et mirent ses battants, serrures et verrous; et ils réparèrent mille coudées de muraille jusqu\'à la porte du Fumier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Et Melchias, fils de Réchab, chef de la banlieue de Bethaccharim, lui et ses fils relevèrent la porte du Fumier, et ils la couvrirent, et ils mirent ses battants, serrures et verrous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Il fit aussi le mur de la piscine où on lave les toisons lors de la tonte du roi, jusqu\'aux degrés qui descendent de la ville de David.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 16, 'Après lui, Néhémias, fils d\'Azabuch, chef de la moitié de la banlieue de Bethsur, édifia jusqu\'au jardin du sépulcre de David, et jusqu\'à la piscine artificielle, et jusqu\'à la maison des hommes vaillants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 17, 'Après lui, édifièrent les lévites, sous Rahum, fils de Bani; à côté de celui-ci, Asabie, chef de la moitié de la banlieue de Cella, avec ses habitants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 18, 'Et, après lui, étaient leurs frères, sous Béneï, fils d\'Enadad, chef de l\'autre moitié de la même banlieue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 19, 'Et, à côté de ceux-ci, Azur, fils de Josué, chef de Masphaï, releva une part de la tour de la Montée, celle qui tenait à l\'angle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 20, 'Après lui, Baruch, fils de Zabu, édifia une autre part, depuis l\'angle jusqu\'à la porte de la maison d\'Eliasub le grand prêtre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 21, 'Après lui, Meramoth, fils d\'Urie, fils d\'Accos, édifia une autre part, à partir de la porte de la maison d\'Eliasub, jusqu\'à l\'extrémité de cette maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 22, 'Après lui, édifièrent les prêtres, les hommes d\'Eccbechar.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 23, 'Après lui, Benjamin et Asub édifièrent devant leur maison; ensuite, Azarias, fils de Maasia, fils d\'Anania, le long de sa maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 24, 'Après celui-ci, Bani, fils d\'Adad, édifia une autre part, depuis la maison d\'Azarias, jusqu\'à l\'angle et jusqu\'au tournant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 25, 'Phalach, fils d\'Euzaï, édifia vis-à-vis l\'angle où la tour fait saillie sur le palais du roi, et domine la cour de la prison; et, après lui, Phadaïa, fils de Pharos,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 26, 'Et les Nathinéens se placèrent en Ophel, jusqu\'au jardin de la porte des Eaux, du côté de l\'orient, où une tour s\'élève en saillie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 27, 'Ensuite, ceux de Thécoé édifièrent une autre part, vis-à-vis la grande tour qui fait saillie, jusqu\'au mur d\'Ophla.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 28, 'Les prêtres édifièrent au-dessus de la porte des Cavaliers, chacun en face de sa maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 29, 'Après ceux-là, Saddoc, fils d\'Emmer, édifia en face de sa maison; et, après lui, Samaïa, fils de Sechénias, garde de la porte orientale du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 30, 'Après celui-cl, Ananias, fils de Sélémias, et Anom, sixième fils de Séleph, édifièrent; puis, Mesulam, fils de Barachias, édifia en face du trésor dont il était le gardien;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 31, 'puis, Méchias, fils de Saréphi, édifia jusqu\'à la maison des Nathinéens, et les petits marchands vis-à-vis la porte de Maphecad jusqu\'aux degrés du tournant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 32, 'Enfin, les forgerons et des détaillants édifièrent du côté de la porte Probatique.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 33, 'Or, lorsque Sanaballat apprit que nous relevions les remparts, il le trouva mauvais, s\'en courrouça grandement, et se moqua fort des Juifs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 34, 'Et il dit devant ses frères (c\'est-à-dire devant l\'armée samaritaine): Il est donc vrai que les Juifs réédifient leur ville?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 35, 'Et Tobias l\'Ammonite s\'approcha de lui, et il dit à la multitude: Est-ce qu\'ils sacrifieront et mangeront en ce lieu? Est-ce qu\'un renard en sautant ne renversera pas leur muraille de pierres?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 36, 'Écoutez, ô notre Dieu, car nous sommes un sujet de raillerie; faites retomber ces outrages sur leurs têtes, et qu\'eux-mêmes soient un sujet de raillerie en la terre où nous avons été captifs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 37, 'Ne couvrez pas leur iniquité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Or, lorsque Sanaballat, et Tobias, et les Arabes et les Ammonites, apprirent que les murs de Jérusalem reprenaient leur forme, et que leurs brèches commençaient à se fermer, ils le trouvèrent fort mauvais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Et ils se réunirent tous ensemble pour marcher contre Jérusalem, et la faire disparaître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Alors, nous priâmes notre Dieu, et nous mîmes, nuit et jour, des gardes, à cause d\'eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Et Juda dit: La force des ennemis est brisée; mais le monceau de ruines est énorme, et nous ne pourrons bâtir les remparts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Et nos oppresseurs dirent: Ils ne sauront, ils ne verront que lorsque nous arriverons au milieu d\'eux, et nous les massacrerons, et nous ferons cesser l\'œuvre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Et les Juifs qui habitaient dans le voisinage, vinrent, et nous dirent: Ils arrivent de toutes parts contre nous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Alors, je plaçai tout le peuple en bas, au pied des remparts, sous des abris, par familles, avec leurs épées, leurs javelines et leurs arcs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Et je regardai, me levai, et dis aux nobles, aux capitaines, à tout le reste du peuple: Ne craignez point leur face; souvenez-vous de notre Dieu grand et redoutable; combattez pour vos frères, vos fils, vos filles, vos femmes et vos foyers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Et aussitôt que nos ennemis apprirent qu\'ils nous avaient été signalés, Dieu dissipa leurs conseils, et nous retournâmes aux remparts, chacun à son ouvrage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Et, à partir de ce jour, la moitié de ceux que j\'avais attirés fit l\'œuvre; l\'autre moitié se rangea derrière les remparts avec des javelines, des boucliers, des arcs et des cuirasses; leurs chefs se tenant derrière toute la maison de Juda,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Et derrière ceux qui bâtissaient; ceux qui transportaient les matériaux ne quittaient point leurs armes; d\'une main ils faisaient leur tâche, de l\'autre ils tenaient un trait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Et chaque travailleur avait autour des reins son épée, et ils édifiaient, et celui qui sonnait de la trompette était auprès d\'eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Et je dis aux nobles, aux capitaines et au reste du peuple: L\'œuvre est grande et de longue étendue, et nous, sommes dispersés sur le rempart, chacun loin de son frère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'N\'importe où vous entendrez la trompette, accourez tous en ce lieu, et notre Dieu combattra avec nous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Ainsi, nous continuâmes nos travaux; la moitié de nous ne quitta point ses javelines, depuis les premières lueurs du jour jusqu\'au lever des étoiles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Et, en ce temps-là, je dis au peuple: Que chacun, avec son serviteur, demeure au milieu de Jérusalem; la nuit on veillera, le jour on se mettra au travail.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Et j\'étais là, et les hommes de garde se tenaient derrière moi, et nul de nous n\'ôtait ses vêtements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 18, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 19, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 20, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 21, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 22, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 23, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Et il y eut un grand cri du peuple et de leurs femmes, contre les Juifs leurs frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Et les uns disaient: Nous sommes en grand nombre avec nos fils et nos filles, vendons-en; puis nous achèterons du blé, et nous mangerons, et nous vivrons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Et d\'autres disaient: Engageons nos champs, nos vignes, nos maisons; puis, nous achèterons du blé, et nous mangerons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'D\'autres encore disaient: Nous avons emprunté de l\'argent pour les impôts du roi, sur nos champs, et nos vignes, et nos maisons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Et maintenant, notre chair est comme la chair de nos frères; nos fils sont comme leurs fils, et nous traitons nos fils et nos filles comme des esclaves; et il y a de nos filles qui sont servantes, et nous n\'avons pas le pouvoir de les racheter; car les nobles possèdent nos champs et nos vignes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Et j\'eus une grande affliction, quand j\'ouïs leur clameur et ces discours;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Et je tins conseil en mon cœur, et je combattis les nobles et les princes, et je leur dis: Un homme peut-il demander à son frère ce que vous demandez? Et je convoquai contre eux une grande assemblée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Et je leur dis: Nous avons, de nos dons volontaires, racheté nos frères les Juifs qui avaient été vendus aux gentils, et vous vendez vos frères; mais vous seront-ils livrés? Et ils gardèrent le silence, et ils ne trouvèrent pas un mot à dire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Et je dis: Elle n\'est pas bonne l\'action que vous faites; ce n\'est pas ainsi que vous vous soustrairez, par la crainte de Dieu, aux outrages des nations, vos ennemies.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Or, mes frères, mes parents et moi-même, nous leurs avons prêté de l\'argent et du blé; eh bien! renonçons à rien exiger d\'eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Rendez-leur dès aujourd\'hui leurs champs, leurs vignes, leurs oliviers et leurs maisons; et apportez-leur du blé, du vin et de l\'huile pour prix de l\'argent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Et ils dirent: Nous rendrons tout; nous ne leur demanderons rien, et nous ferons ce que tu dis. Et j\'appelai les prêtres, et je les adjurai de faire selon cette parole.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Et je secouai mon manteau, et je dis: Que Dieu ainsi secoue hors de sa maison et de son jardin tout homme qui n\'accomplira pas cette parole; que cet homme soit ainsi secoué et vide. Et toute l\'Église dit: Amen. Et ils louèrent le Seigneur, et le peuple fit comme il avait été dit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Depuis le jour où le roi m\'avait commandé d\'être leur chef en la terre de Juda: de la vingtième à la trente-deuxième année du règne d\'Arthasastha, pendant douze ans, ni moi ni mes frères nous ne mangeâmes de vivres extorqués d\'eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 15, 'Et toutes les extorsions dont mes devanciers les grevaient avant moi, leur avaient enlevé jusqu\'à leur dernier argent; ils leur prenaient pour le pain et le vin quarante sicles par jour; et leurs agents avaient toute autorité sur le peuple; et moi je ne fis pas ainsi, en face de la crainte de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 16, 'Et, pendant la réédification des murailles, je ne leur extorquai rien, je n\'achetai point de champ, non plus qu\'aucun de ceux que j\'avais rassemblés pour cette œuvre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 17, 'Et les Juifs, au nombre de cent cinquante, et ceux des gentils qui venaient d\'alentour auprès de nous, mangeaient à ma table.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 18, 'Et tous les jours on m\'amenait un bœuf, six brebis de choix et un chevreau. Et, tous les dix jours, il me venait pour nous tous une ample provision de vin; et, avec tout cela, je ne pris jamais de vivres par extorsion, parce que la servitude avait été pesante pour le peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 19, 'Souvenez-vous de moi, mon Dieu, pour mon bien, à cause de tout ce que j\'ai fait en faveur de ce peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Or, lorsque Sanaballat, Tobias, l\'Arabe Gésam et le reste de nos ennemis, ouïrent que j\'avais relevé le mur, ils en perdirent le souffle; cependant, alors, je n\'avais pas encore mis les battants des portes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Et Sanaballat et Gésam m\'envoyèrent des messagers, disant: Viens, et rencontrons-nous tous ensemble dans l\'un des bourgs de la plaine d\'Ono. Mais, ils pensaient à me faire du mal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Je leur envoyai des messagers, disant: Je suis à faire une grande œuvre, et je ne pourrai descendre vers vous, de peur qu\'elle ne soit suspendue; je descendrai dès qu\'elle sera finie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Ils me firent dire derechef ces paroles, et je leur répondis comme la première fois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Et Sanaballat m\'envoya son serviteur, avec une lettre ouverte qu\'il tenait à la main.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Et il y était écrit: On a oui dire, parmi les nations, que toi et les Juifs pensez à vous révolter; et que, pour cela, tu édifies le rempart, et que tu seras leur roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Et, outre cela, tu as aposté pour toi des prophètes, afin que tu sièges à Jérusalem, comme roi de Juda. Or, maintenant, ces choses vont être rapportées au roi; viens donc, et tenons conseil ensemble.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Et je lui envoyai encore des messagers, disant: Cela n\'est pas arrivé selon les paroles que tu dis, car tu les as feintes en ton cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Ils voulaient tous ainsi nous effrayer, et ils disaient: Leurs mains en seront énervées; quant à ce travail, il ne sera pas achevé; mais moi, je fortifiai mes mains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Et j\'entrai en la demeure de Sémei, fils de Daishi, fils de Métabéhel, et il y était enfermé, et il me dit: Réunissons-nous dans le temple de Dieu, et nous en clorons les portes; car cette nuit ils viendront pour te tuer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Et je répondis: Quel est l\'homme qui entrera dans le temple, et pourra vivre?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Et j\'observai, et voilà que Dieu ne me l\'avait pas envoyé; car sa prophétie était une fable inventée contre moi. En effet, Sanaballat et Tobias avaient salarié');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Contre moi une multitude de gens, afin que j\'eusse peur, que je fisse ce qu\'il conseillait, que je tombasse dans le péché, que j\'eusse parmi eux un mauvais renom, et qu\'ils m\'outrageassent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Souvenez-vous, ô mon Dieu, de Tobias et de Sanaballat, selon leurs actions, et de Noadias le prophète, et des autres prophètes qui tentèrent de m\'alarmer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 15, 'Et le mur fut achevé en cinquante-deux jours, le vingt-cinq du mois d\'étal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 16, 'Et il advint, quand nos ennemis l\'ouïrent, que toutes les nations d\'alentour furent épouvantées, et qu\'une grande frayeur tomba sur eux, et qu\'ils connurent que l\'achèvement de cette œuvre était de notre Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 17, 'Et, en ces jours-là, des lettres de plusieurs nobles de Juda arrivaient à Tobias, et celles de Tobias leur arrivaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 18, 'Car plusieurs en Juda s\'étaient engagés avec lui par serment, parce qu\'il était gendre de Sechénias, fils d\'Héraé; et que Jonan, son fils, avait épousé la fille de Mesulam, fils de Barachias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 19, 'Et ils me rapportaient ses paroles, et ils lui répétaient les miennes, et Tobias écrivait des lettres pour m\'effrayer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Or, après que le mur fut bâti, les battants des portes placés, les portiers, les chantres et les lévites abrités,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Je donnai des ordres à mon frère Annulas, et à Ananias, gouverneur du palais de Jerusalem; car celui-ci était un homme sincère, et craignant Dieu plus que beaucoup d\'autres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Et je leur dis: Que les portes de Jérusalem ne soient point ouvertes avant le lever du soleil, et que, pendant que tout le monde est encore éveillé, on les ferme et les verrouille; instituez aussi des gardes parmi les habitants de Jérusalem, chacun à son poste, chacun dans le quartier où est sa maison.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Or, la ville était grande et vaste, et le peuple en elle était peu nombreux; et les maisons n\'étaient pas réédifiées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Et Dieu me mit au cœur de réunir les nobles, les chefs et le peuple, pour le recensement, et je trouvai le livre du recensement des premiers arrivés, et j\'y vis écrit:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Voici les fils de la terre promise, délivrés de la captivité où les avait emmenés Nabuchodonosor, roi de Babylone; chacun d\'eux est de retour en sa ville: à Jérusalem et en Juda,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Avec Zorobabel, Josué, Néhémias, Azarias, Reelma, Naémani, Mardochée, Balsan, Maspharath, Esdras, Boguïas, Inaum, Baana et Masphar; hommes du peuple d\'Israël:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Fils de Phoros: deux mille cent soixante-douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Fils de Saphatia: trois cent soixante-douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Fils d\'Era: six cent cinquante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 11, 'Fils de Phaath-Moab, avec les fils de Josué et de Joab: deux mille six cent dix-huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 12, 'Fils d\'Elam: douze cent cinquante-quatre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 13, 'Fils de Zathuïa: huit cent quarante-cinq.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 14, 'Fils de Zacchu: sept cent soixante.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 15, 'Fils de Banni: six cent quarante-huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 16, 'Fils de Bébi: six cent vingt- huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 17, 'Fils d\'Asgad: deux mille trois cent vingt-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 18, 'Fils d\'Adonicam: six cent soixante-sept.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 19, 'Fils de Bagoï, deux mille soixante-sept.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 20, 'Fils d\'Edin: six cent cinquante-cinq.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 21, 'Fils d\'Ater, issu d\'Ezéchias: quatre-vingt-dix-huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 22, 'Fils d\'Esam: trois cent vingt-huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 23, 'Fils de Béseï: trois cent vingt-quatre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 24, 'Fils d\'Ariph: cent douze. Fils d\'Asen: deux cent vingt-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 25, 'Fils de Gabaon: quatre-vingt-quinze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 26, 'Fils de Béthalem: cent vingt-trois. Fils d\'Atopha: cinquante-six.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 27, 'Fils d\'Anathoth: cent vingt-huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 28, 'Hommes de Béthasmoth: quarante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 29, 'Hommes de Cariatharim, Caphira et Beroth: sept cent quarante-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 30, 'Hommes d\'Arama et de Gabaa: six cent vingt.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 31, 'Hommes de Machemas: cent vingt-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 32, 'Hommes de Béthel et d\'Haï: cent vingt-trois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 33, 'Hommes de Nabia: cent cinquante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 34, 'Hommes d\'Elamaar: douze cent cinquante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 35, 'Fils d\'Eram: trois cent vingt.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 36, 'Fils de Jéricho: trois cent quarante-cinq.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 37, 'Fils de Lodadid et d\'Ono, sept cent vingt et un.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 38, 'Fils de Sanana: trois mille neuf cent trente.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 39, 'Prêtres, fils de Joad, appartenant à la maison de Jésus: neuf cent soixante-treize.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 40, 'Fils d\'Emmer: mille cinquante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 41, 'Fils de Phaseür: douze cent quarante-sept.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 42, 'Fils d\'Eram: mille dix-sept.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 43, 'Lévites, fils de Jésus, fils de Cadmiel, avec les fils d\'Uduïa: soixante-quatorze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 44, 'Chantres, fils d\'Asaph: cent quarante-huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 45, 'Portiers, fils de Salum, fils d\'Ater, fils de Telmon, fils d\'Acub, fils d\'Atita, fils de Sabi: cent trente-huit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 46, 'Nathinéens: fils de Seha, fils d\'Aspha, fils de Labaoth,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 47, 'Fils de Ciras, fils d\'Asuïa, fils de Phadon,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 48, 'Fils de Labana, fils d\'Agaba, fils de Selmeï,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 49, 'Fils d\'Anan, fils de Gadel, fils de Gaar,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 50, 'Fils de Rahaïa, fils de Basson, fils de Necoda,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 51, 'Fils de Gézam, fils d\'Ozi, fils de Phesé,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 52, 'Fils de Bési, fils de Meïnon, fils de Nephosasi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 53, 'Fils de Bacbuc, fils d\'Achipha, fils d\'Arur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 54, 'Fils de Basaloth, fils de Mida, fils d\'Adasan,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 55, 'Fils de Barcué, fils de Sisarath, fils de Théma,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 56, 'Fils de Nisia, fils d\'Atipha,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 57, 'Fils des serviteurs de Salomon, fils de Suteï, fils de Sapharat, fils de Phérida,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 58, 'Fils de Jelel, fils de Dorcon, fils de Gadahel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 59, 'Fils de Saphatias, fils d\'Ettel, fils de Phacarath, fils de Sabaïm, fils d\'Emim.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 60, 'Total des Nathinéens et des fils des serviteurs de Salomon: trois cent quatre-vingt-douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 61, 'Et voici ceux qui partirent de Thelméleth, Thélarésa, Charub, Eron, Jemer, et ils n\'étaient point capables de déclarer leurs familles paternelles ni leur race; à savoir s\'ils étaient nés d\'Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 62, 'Fils de Dalaïa, fils de Tobias, fils de Necoda: six cent quarante-deux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 63, 'Et, parmi les prêtres, les fils d\'Ebia, les fils d\'Acos, les fils de Berzelli qui portaient ce nom, parce qu\'ils avaient épousé des filles issues de Berzelli le Galaadite,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 64, 'Cherchèrent leur inscription sur le rôle de ceux qui étaient revenus, et ils ne le trouvèrent pas, et ils furent rejetés du sacerdoce.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 65, 'Or, l\'athersastha leur dit de ne point manger des choses les plus saintes jusqu\'à ce que surgit un prêtre pour les éclairer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 66, 'Et toute l\'Église montait à environ quarante-deux mille trois cent soixante âmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 67, 'Sans compter leurs esclaves et leurs serviteurs, au nombre de sept mille trois cent trente-sept; et il y avait deux cent [quarante-cinq] chantres et chanteuses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 68, '[Sept cent trente-six chevaux, deux cent quarante-cinq mules.]');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 69, '[Quatre cent trente-cinq chameaux,] deux-mille sept cents ânes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 70, 'Et Néhémias reçut, d\'une partie des chefs des familles paternelles, pour le trésor des travaux, mille sicles d\'or, cinquante fioles et trente costumes sacerdotaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 71, 'Et une autre part des chefs des familles paternelles donna, pour le trésor des travaux, vingt mille pièces d\'or et deux mille deux cents pièces d\'argent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 72, 'Et le reste du peuple donna vingt mille pièces d\'or, deux mille deux cents mines d\'argent et soixante-sept costumes sacerdotaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 73, 'Et les prêtres, et les lévites, et les portiers et les chantres, et ceux du peuple, et les Nathinéens, et tout Israël, s\'établirent dans leurs villes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Et le septième mois arriva, et les fils d\'Israël étaient dans leurs villes; et tout le peuple se rassembla, comme un seul homme, sur la place, devant la porte de l\'Eau; et ils dirent à Esdras le scribe d\'apporter le livre de la loi de Moïse que le Seigneur a intimée à Israël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Et le premier jour du septième mois, Esdras, le prêtre, apporta la loi devant la multitude d\'hommes et de femmes, et devant tous ceux qui pouvaient l\'entendre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Et il la lut depuis l\'heure où le soleil éclaire jusqu\'au milieu du jour, devant les hommes et les femmes, et ils la comprenaient, et les oreilles de tout le peuple étaient attentives au livre de la loi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Et Esdras, le scribe, se tenait sur une estrade de bois, et il y avait auprès de lui, à sa droite: Matthathias, Samaïas, Ananias, Urie, Helcias et Maasia; à sa gauche: Phadaïas, Misahel, Melchias, Asom, Asubadma, Zacharie et Mesollam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Et Esdras ouvrit le livre à la vue de tout le peuple, car lui-même était plus élevé que le peuple, et lorsqu\'il ouvrit le livre, tout le peuple resta debout.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Et Esdras bénit le Seigneur, le Dieu très-grand, et le peuple élevant les mains, répondit: Amen. Et ils s\'inclinèrent, et ils adorèrent le Seigneur la face contre terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Ensuite, Josué, Banaïas et Sarabias, expliquèrent la loi au peuple, et le peuple ne bougea pas de sa place.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Et ils lurent dans le livre de la loi de Dieu; puis, Esdras enseigna, et il apprit au peuple à connaître le Seigneur, et le peuple comprit à la lecture.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Alors, Néhémias et Esdras, le scribe et prêtre, et les lévites qui expliquaient la loi au peuple, dirent à tout le peuple: Ce jour est consacré au Seigneur notre Dieu, ne vous affligez pas, ne pleurez point. Car tout le peuple pleurait quand il entendait les paroles de la loi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Et Néhémias leur dit: Allez, mangez des chairs grasses, buvez de douces boissons, et envoyez des parts à ceux qui n\'en ont point, car ce jour est consacré au Seigneur notre Dieu, et ne soyez point abattus, puisque le Seigneur est notre force.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Et les lévites faisaient taire tout le peuple, disant: Gardez le silence, car ce jour est saint, et ne soyez point abattus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Et tout le peuple s\'en alla pour manger, boire, envoyer des parts et faire grande liesse, parce qu\'il avait compris les paroles que Néhémias leur avait fait connaître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Et le second jour, les chefs de famille, tout le peuple, les prêtres et les lévites, se réunirent autour d\'Esdras, le scribe, pour qu\'il les instruisît sur toutes les paroles de la loi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Et ils trouvèrent écrit en la loi que le Seigneur avait commandé à Moïse que les fils d\'Israël demeurassent sous des tabernacles, durant la fête du septième mois,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Et qu\'ils le publiassent au son de la trompette en toutes leurs villes et à Jérusalem. Et Esdras dit: Allez sur la montagne, rapportez-en des rameaux d\'olivier, de cyprès, de tamaris, de palmier et de tous les arbres touffus, pour faire des tabernacles selon ce qui est écrit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Et le peuple sortit, et il rapporta des rameaux, et ils se firent des tabernacles, chacun sur sa terrasse, ou dans sa cour, ou dans les parvis du temple du Seigneur, ou dans les rues de la ville jusqu\'à la porte d\'Ephraïm.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Et toute l\'Église, tous ceux qui étaient revenus de la captivité se firent des tabernacles, et ils demeurèrent sous des tabernacles; et depuis le temps de Josué, fils de Nau, jusqu\'à ce jour-là, le peuple d\'Israël n\'avait pas fait ainsi, et grande fut sa joie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 18, 'Et on lut dans le livre de la loi, tous les jours, depuis le premier jusqu\'au dernier, et ils firent la fête sept jours, et le huitième jour la fin de la fête, selon la loi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Au vingt-quatrième jour de ce Mois, les fils d\'Israël se réunirent pour un jeûne, ayant des cendres sur la tête, et des cilices autour du corps.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Et les fils d\'Israël se tinrent séparés de tout fils de l\'étranger, et debout, ils confessèrent leurs péchés et les iniquités de leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Et, chacun demeurant immobile à sa place, ils lurent dans le livre de la loi du Seigneur leur Dieu; et ils étaient là, se confessant au Seigneur, adorant le Seigneur leur Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Ensuite, Josué, les fils de Cadmiel, Sechénias, fils de Sarabie, et les fils d\'Honeni se levèrent sur les degrés des lévites, et invoquèrent à grands cris le Seigneur leur Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Et les lévites Josué et Cadmiel dirent: Relevez-vous, bénissez le Seigneur notre Dieu, dans tous les siècles des siècles; que l\'on bénisse, ô Seigneur, votre nom et votre gloire; que l\'on vous exalte en toute bénédiction et louange.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Et Esdras dit: Vous êtes le seul Seigneur, vous avez créé le ciel et le ciel des cieux, et toute l\'armée céleste, et la terre et tout ce qui est en elle, et les mers et tout ce qui est en elles; c\'est vous qui vivifiez toutes choses, et c\'est vous que les armées du ciel adorent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Vous êtes le Seigneur Dieu, et vous avez élu Abram, et vous l\'avez amené du pays des Chaldéens, et vous lui avez donné le nom d\'Abrabam.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Et vous avez trouvé son cœur fidèle devant vous, et vous avez fait alliance avec lui, pour donner la terre des Chananéens, des Hettéens, des Amorrhéens, des Phérézéens, des Jébuséens et des Gergéséens, à lui et à sa race: et vous avez tenu parole, parce que vous êtes juste.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Et vous avez regardé l\'affliction de nos pères en Égypte, et vous avez ouï leurs cris sur les bords de la mer Rouge.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Et vous avez donné des signes et des prodiges en Égypte, sur Pharaon, ses serviteurs, tout le peuple de sa terre, parce que vous saviez qu\'ils traitaient votre peuple orgueilleusement, et vous vous êtes fait un grand nom, comme vous vous le faites encore aujourd\'hui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Et, devant eux, vous avez séparé la mer, et votre peuple l\'a traversée à sec, et, ceux qui le poursuivaient, vous les avez jetés dans l\'abîme comme une pierre dans l\'eau profonde.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Et le jour, vous avez guidé votre peuple par une colonne de nuée, et la nuit par une colonne de feu, pour éclairer la voie qu\'il devait suivre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Et vous êtes descendu sur le mont Sina, et, du haut du ciel, vous leur avez parlé, et vous leur avez donné des jugements droits, des lois de vérité, des commandements et des préceptes salutaires.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Et vous leur avez fait connaître votre sabbat saint, et vous leur avez intimé par la voix de Moïse, votre serviteur, la loi, les préceptes et les commandements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Et pour aliment, vous leur avez donné du pain du ciel, et pour leur soif, vous avez fait jaillir de l\'eau des rochers; et vous leur avez dit d\'entrer, pour qu\'elle soit leur héritage, en la terre sur laquelle vous aviez étendu la main, promettant de la leur donner.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Mais, eux et nos pères se sont enorgueillis, et ils ont endurci leur cœur, et ils n\'ont point obéi à vos commandements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Et ils ont refusé de rien entendre, et ils n\'ont pas eu mémoire de vos merveilles, que vous aviez faites pour eux; et ils ont endurci leur cœur, et ils ont songé à rentrer en la servitude d\'Égypte. Et vous, ô mon Dieu, miséricordieux et compatissant, clément et magnanime, vous ne les avez pas abandonnés,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Même lorsqu\'ils eurent jeté en fonte un veau d\'or, et qu\'ils eurent dit: Voilà les dieux qui nous ont fait sortir de l\'Égypte. Et ils vous ont gravement offensé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Mais vous, dans votre miséricorde infinie, vous ne les avez point abandonnés dans le désert; vous n\'avez point détourné d\'eux la colonne de nuée qui les guidait le jour, ni la colonne de feu qui, la nuit, éclairait leur voie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Et vous leur avez donné votre bon esprit pour les instruire; vous n\'avez point retiré la manne de leur bouche, et vous leur avez donné de l\'eau en leur soif.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Et vous les avez nourris quarante ans dans le désert, sans les laisser manquer de rien, et leurs vêtements ne se sont point usés, et leurs pieds n\'ont point été meurtris.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Et vous leur avez donné des royaumes, vous leur avez partagé des peuples, et ils ont possédé la terre de Séhon, roi d\'Esebon, et la terre d\'Og, roi de Basan.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Et vous avez multiplié leurs fils comme les étoiles du ciel, et vous les avez introduits en la terre que vous aviez promise à leurs pères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Et ils en ont fait leur héritage, et vous avez écrasé devant eux les habitants de la terre des Chananéens, et vous avez livré à leur merci les rois et les peuples de cette terre, pour qu\'ils les traitassent comme il leur plaisait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Ils ont donc pris des villes superbes, ils ont hérité de maisons pleines de biens, de citernes en pierres de taille, de vignes, d\'oliviers, et d\'une multitude d\'arbres fruitiers. Et ils ont mangé, et ils se sont rassasiés, et ils se sont engraissés, et ils ont abondé en délices par votre grande bonté.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Ensuite, ils ont changé; ils se sont retirés de vous; ils ont rejeté derrière eux la loi; ils ont tué vos prophètes qui les admonestaient pour les ramener à vous. Et ils vous ont gravement offensé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Alors, vous les avez livrés aux mains de ceux qui les opprimaient; ceux-ci les ont écrasés, et, au temps de leur affliction, ils ont crié à vous; et vous, du haut du ciel, vous les avez entendus; et, en votre grande miséricorde, vous leur avez envoyé des sauveurs, et vous les avez tirés des mains de ceux qui les opprimaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Mais, après s\'être reposés, ils ont encore fait le mal devant vous, et vous les avez livrés aux mains de leurs ennemis qui les ont maîtrisés. Et, derechef, ils ont crié à vous; et du haut du ciel, vous les avez encore entendus; et, en votre grande miséricorde, vous les avez délivrés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Et vous les avez admonestés pour qu\'ils se convertissent à votre loi; mais ils ne nous ont point écouté, et ils ont péché contre vos commandements et vos jugements, par lesquels, en les faisant, l\'homme vivra. Et ils ont tourné le dos, et ils ont endurci leur cœur, et ils ne vous ont pas écouté.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Vous avez différé avec eux bien des années, et vous les avez admonestés par votre esprit, par la voix de vos prophètes, et ils ne vous ont point écouté; enfin, vous les avez livrés aux peuples de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Mais, en votre grande miséricorde, vous ne les avez point anéantis, vous ne les avez point abandonnés; car, vous êtes fort, et compatissant, et miséricordieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Et maintenant, ô notre Dieu, Dieu fort, grand, puissant et redoutable, qui gardez votre alliance et votre miséricorde, ne tenez pas pour peu de chose toutes les souffrances qui ont atteint nous, nos rois, nos princes, nos prêtres, nos prophètes, nos pères et tout le peuple, depuis les jours du roi d\'Assyrie, jusqu\'à ce jour.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 33, 'Vous avez été juste en tout ce qui nous est advenu, car vous avez agi selon la vérité, et nous, nous avons péché;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 34, 'Nos rois, nos princes, nos prêtres, nos pères, n\'ont pas observé votre loi; ils n\'ont pas été attentifs à vos commandements, ni à vos témoignages que vous leur avez notifiés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 35, 'Et ils ne vous ont point servi dans votre royaume, au milieu de ces marques de votre grande bonté que vous leur avez données, dans cette terre vaste et grasse que vous avez fait apparaître devant eux, et ils ne se sont point détournés de leurs habitudes criminelles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 36, 'Et voilà qu\'aujourd\'hui nous sommes esclaves, en cette terre que vous avez donnée à nos pères, pour manger ses fruits et ses bonnes choses; voilà que nous sommes esclaves en elle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 37, 'Et ses fruits sont abondants pour les rois que vous avez mis sur nous en punition de nos péchés; ils ont pouvoir sur nos corps et sur nos troupeaux, à leur gré, et nous sommes dans une grande affliction.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 38, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Et, à cause de tout cela, nous vous promettons alliance et nous l\'écrivons, et nos princes, et nos lévites, et nos prêtres y mettent leur sceau.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Et à la tête de ceux qui la scellèrent furent Néhémias artasastha, fils d\'Achalias, et Sédécias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Fils d\'Araïas, et Azarias, et Jérémie,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 4, 'Phasur, Amarias, Melchias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 5, 'Attus, Sebani, Maluch,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 6, 'Iram, Meramoth, Abdia,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 7, 'Daniel, Gannathon, Baruch,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 8, 'Mesulam, Abia, Miamin,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 9, 'Maazia, Belgaï, Samaïa, tous ceux-là prêtres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 10, 'Puis les lévites: Josué, fils d\'Azanias, Banaïu, des fils d\'Enadad, Cadmiel;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 11, 'Et ses frères Sabanias, Oduïa, Calitan, Phélia, Anan,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 12, 'Micha, Roob, Asébias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 13, 'Zacchor, Sarabia, Sebania,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 14, 'Odum; les fils de Banuaï,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 15, 'Chefs du peuple: Pharos, Phaath-Moab, Zathuïa, fils de Bani,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 16, 'Asgad, Bébaï,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 17, 'Adania, Bagoï, Hédin,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 18, 'Ater, Ezéchias, Azur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 19, 'Oduïa, Esam, Bési,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 20, 'Ariph, Anathoth, Nobaï,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 21, 'Megaphès, Mesollam, Hézir,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 22, 'Mesozébel, Saduc, Jeddua,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 23, 'Phattia, Anan, Anaïa,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 24, 'Osée, Ananias, Asub,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 25, 'Aloès, Phalaï, Sobec,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 26, 'Reüm, Essabana, Maasia,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 27, 'Et Aïa, Ainan, Enam,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 28, 'Maluch, Héram, Baana.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 29, 'Et tout le reste du peuple, les prêtres, les lévites, les portiers, les chantres, les Nathinéens et tous ceux qui s\'étaient retirés des gentils de la terre, pour revenir à la loi de Dieu, et leurs femmes et leurs filles; tous ceux qui avaient savoir et intelligence,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 30, 'Furent pressants avec leurs frères, et les excitèrent par leurs malédictions; et ceux-ci s\'engagèrent, par malédictions et serments, à marcher selon la loi que Dieu a donnée par la main de Moïse, serviteur de Dieu, à garder les jugements, les préceptes et les commandements du Seigneur;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 31, 'À ne point donner nos filles en mariage aux peuples de la terre, et à ne point prendre leurs filles pour nos fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 32, 'Nous n\'achèterons rien, avons-nous dit, aux peuples de la terre qui viendront vendre le jour du sabbat; nous ne trafiquerons, ni le jour du sabbat; ni les jours sanctifiés; nous remettrons les dettes la septième année.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 33, 'Nous établirons une ordonnance afin de lever sur nous un tiers de drachme, par an, pour le service du temple de notre Dieu;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 34, 'Pour les pains de proposition, pour le sacrifice perpétuel, et pour l\'holocauste perpétuel, tant des sabbats que des nouvelles lunes, pour les fêtes et les jours saints, pour les péchés, pour les hosties pacifiques et pour les travaux du temple de notre Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 35, 'Nous avons ensuite jeté les sorts, entre les prêtres, les lévites et le peuple, par familles paternelles, pour régler l\'oblation du bois dans le temple de notre Dieu, aux époques prescrites chaque année, pour faire les holocaustes sur l\'autel du Seigneur notre Dieu, comme il est écrit en la loi;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 36, 'Pour que nous apportions les prémices des champs, et des arbres à fruit d\'année en année, dans le temple du Seigneur,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 37, 'Et l\'évaluation des fils premiers-nés, celle des premiers-nés des bêtes de somme, entre les mains des prêtres et des lévites de service dans le temple de Dieu; comme il est écrit en la loi, et les premiers-nés de nos bœufs et de nos brebis;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 38, 'Et pour que nous apportions aux prêtres, pour le trésor du temple de Dieu, les prémices de notre blé, des fruits de nos arbres, du vin et de l\'huile; et aux lévites la dîme de notre terre, et pour que les lévites perçoivent la dîme en toutes les villes de la terre que nous cultivons.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 39, 'Et nous avons dit: Le prêtre, fils d\'Aaron, aura part avec le lévite à la dîme des lévites; et les lévites offriront le dixième de leur dîme dans le temple de notre Dieu, et dans le trésor du temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 40, 'Car, les fils d\'Israël et les fils de Lévi apporteront au trésor les prémices de leur blé, de leur vin, de leur huile; et c\'est là que seront les vases saints, sous la garde des prêtres, des serviteurs du temple, des chantres et des portiers; et nous n\'abandonnerons pas le temple de notre Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 1, 'Et les princes du peuple s\'établirent à Jérusalem; et parmi le reste du peuple, le sort désigna un homme sur dix pour résider en la ville sainte, les neuf autres dixièmes se dispersèrent dans les villes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 2, 'Et le peuple bénit tous les hommes qui offrirent volontairement de rester à Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 3, 'Voici les princes de la terre qui habitèrent, soit Jérusalem, soit les villes de Juda; chacun demeura en son héritage et en sa ville: Israël, prêtres, lévites, Nathinéens, fils des serviteurs de Salomon:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 4, 'À Jérusalem, il y eut des fils de Juda et des fils de Benjamin; fils de Juda: Athaïa, fils d\'Azia, fils de Zacharie, fils de Samarie, fils de Saphatia, fils de Malalehel; fils de Pharès;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 5, 'Maasia, fils de Baruch, fils de Chaluza, fils d\'Ozias, fils d\'Adaïas, fils de Joarib, fils de Zacharie, fils de Seloni.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 6, 'Tous les fils de Pharès qui s\'établirent à Jérusalem, étaient au nombre de trois cent soixante-huit, c\'étaient des hommes vaillants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 7, 'Fils de Benjamin: Selo, fils de Mesulam, fils de Joad, fils de Phadaïa, fils de Coleïa, fils de Maasia, fils d\'Echiel, fils de Jésia,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 8, 'Et après lui Gebé, Séti, et neuf cent vingt-huit hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 9, 'Johel, fils de Zéchri, était leur surveillant, et il était secondé dans la ville par Juda, fils d\'Asana.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 10, 'Et il y avait les prêtres Jadia, fils de Joarib, Jachin, et');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 11, 'Saraïa, fils d\'Elcias, fils de Mesulam, fils de Saddoc, fils de Marioth, fils d\'Aïtoth, prince de la maison de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 12, 'Et leurs frères faisant les œuvres du temple, étaient au nombre de huit cent vingt-deux. Et Adaïa, fils de Jéroam, fils de Phalalia, fils d\'Amasi, fils de Zacharie, fils de Phassur, fils de Melchias,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 13, 'Et ses frères chefs de familles paternelles, au nombre de deux cent quarante-deux. Et Amasias, fils d\'Esdriel, fils de Mesarimith, fils d\'Emmer,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 14, 'Et ses frères, hommes vaillants, au nombre de cent vingt-huit; et ils avaient pour surveillant Badiel, fils de l\'un des puissants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 15, 'Et il y avait les lévites: Samaïa, fils d\'Esricam,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 16, 'Matthanias, fils de Micha, et Jobeb, fils de Samuï, et');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 17, 'Matthanias, fils de Micha, et Jobeb, fils de Samuï, et');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 18, 'Deux cent quatre-vingt-quatre hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 19, 'Et il y avait les portiers: Acub, Telamin et leurs frères, cent soixante-douze.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 20, 'Et le surveillant des lévites était le fils de Bani, fils d\'Ozi, fils d\'Asabia, fils de Micha. Et il y avait les chantres, fils d\'Asaph, employés au service du temple de Dieu,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 21, 'Et le surveillant des lévites était le fils de Bani, fils d\'Ozi, fils d\'Asabia, fils de Micha. Et il y avait les chantres, fils d\'Asaph, employés au service du temple de Dieu,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 22, 'Et le surveillant des lévites était le fils de Bani, fils d\'Ozi, fils d\'Asabia, fils de Micha. Et il y avait les chantres, fils d\'Asaph, employés au service du temple de Dieu,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 23, 'Selon le règlement que le roi David avait fait pour eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 24, 'Et Phathaïa, fils de Baseza, tenait lieu de la main du roi, pour toutes les affaires concernant le peuple,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 25, 'Et pour les affaires des bourgs et des champs. Et il y eut des fils de Juda, à Cariath-Arboc,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 26, 'Et à Josué,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 27, 'Et à Bersabée,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 28, 'et dans ses faubourgs, dont faisaient partie Lachis et ses champs; mais à Bersabée était la résidence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 29, 'et dans ses faubourgs, dont faisaient partie Lachis et ses champs; mais à Bersabée était la résidence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 30, 'et dans ses faubourgs, dont faisaient partie Lachis et ses champs; mais à Bersabée était la résidence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 31, 'Et des fils de Benjamin habitaient de Gabaa à Machmas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 32, 'Et quelques-uns des lévites avaient leurs parts en Juda et Benjamin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 33, 'Et quelques-uns des lévites avaient leurs parts en Juda et Benjamin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 34, 'Et quelques-uns des lévites avaient leurs parts en Juda et Benjamin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 35, 'Et quelques-uns des lévites avaient leurs parts en Juda et Benjamin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 36, 'Et quelques-uns des lévites avaient leurs parts en Juda et Benjamin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 1, 'Et voici les prêtres et les lévites qui étaient revenus avec Zorobabel, fils de Salathiel et Josué: Saraïa, Jérémie, Esdras,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 2, 'Amarias, Maluch,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 3, 'Sechénias;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 4, 'Tels étaient les princes des prêtres, et leurs frères du temps de Josué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 5, 'Tels étaient les princes des prêtres, et leurs frères du temps de Josué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 6, 'Tels étaient les princes des prêtres, et leurs frères du temps de Josué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 7, 'Tels étaient les princes des prêtres, et leurs frères du temps de Josué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 8, 'Et les lévites étaient Josué, Banuï, Cadmiel, Sarabia, Joad, Matthanias (celui-ci dirigeait les chants, et leurs frères étaient désignés');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 9, 'Pour les services journaliers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 10, 'Or, Josué engendra Joacim, et Joacim engendra Eliasib, et Eliasib engendra Joad,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 11, 'Et Joad engendra Jonathas, et Jonathas engendra Jadu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 12, 'Et du temps de Joacim, ses frères, les prêtres et les chefs des familles paternelles, étaient, savoir: De la famille de Saraïa, Amarias; de celle de Jérémie, Ananias;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 13, 'De celle d\'Esdras, Mesulam; de celle d\'Amarias, Johanan;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 14, 'De celle d\'Amaluch, Jonathas; de celle de Sechénias, Joseph;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 15, 'De celle d\'Aré, Mannas; de celle de Marioth, Elcaï;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 16, 'De celle d\'Adadaï, Zacharie; de celle de Ganathoth, Mesolam;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 17, 'De celle d\'Abias, Zéchri; de celle de Miamin, Maadaï; de celle de Phéléthi;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 18, 'De la famille de Balgas, Samué; de celle de Semias, Jonathan;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 19, 'De celle de Joarib, Matthanaï; de celle d\'Edio, Ozi;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 20, 'De celle de Salaï, Callaï; de celle d\'Amec, Abed;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 21, 'De celle d\'Elcias, Asabias; de celle de Jedeïu, Nathanaël;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 22, 'Les lévites du temps d\'Eliasib étaient Joad, Joas, Johanan et Idua, inscrits comme chefs de familles, ainsi que les prêtres sous le règne de Darius le Perse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 23, 'Les fils de Lévi, chefs de familles paternelles, ont été inscrits dans le livre du récit de ces temps, jusqu\'aux jours de Johanan, fils d\'Elisué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 24, 'Et les chefs des lévites étaient Asabia, et Sarabia, et Josué, et les fils de Cadmiel et leurs frères, se tenaient devant eux lorsqu\'ils chantaient les louanges du Seigneur, journellement comme l\'avait prescrit David, homme de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 25, 'Je ressemblai aussi les portiers,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 26, 'Du temps de Joacim, fils de Josué, fils de Josédec, et du temps de Néhémias, et alors Esdras était prêtre et scribe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 27, 'Et lorsque l\'on fit la dédicace des murs de Jérusalem, on chercha les lévites en leurs résidences pour les amener à Jérusalem, et faire la fête de la dédicace et les réjouissances, avec des actions de grâces et des chants accompagnés de harpes et de cymbales,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 28, 'Et les fils des chantres vinrent de la banlieue de Jérusalem, et de ses villages,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 29, 'Et de ses campagnes, car ils s\'étaient bâti des demeures autour de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 30, 'Et les prêtres et les lévites, après s\'être purifiés, purifièrent le peuple, et les portiers, et les remparts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 31, 'Et l\'on fit monter les princes de Juda sur le rempart avec deux chœurs, pour chanter des actions de grâces à Dieu, et ils tournèrent sur le rempart à droite se dirigeant vers la porte du Fumier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 32, 'Et derrière les chantres marchaient Osaïas et la moitié des princes de Juda,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 33, 'Et Azarias, Esdras, Mesollam,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 34, 'Juda, Benjamin, Samaïas et Jérémie,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 35, 'Et des fils des prêtres avec les trompettes: Zacharie, fils de Jonathas, fils de Samaïas, fils de Matthanias, fils de Michée, fils de Zacchur, fils d\'Asaph,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 36, 'Et ses frères Samaïas, Oziel et Gelod, Jama, Aïas, Nathanaël, Juda et Anani, et ils chantaient les cantiques de David, homme de Dieu; et Esdras, le scribe, les avait devancés');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 37, 'Sur la porte pour chanter devant eux les louanges du Seigneur. Et ils montèrent par les degrés de la ville de David sur le mur, au-dessus du palais de ce roi, et ils allèrent jusqu\'à la porte des Eaux à l\'Est [d\'Elihrem;]');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 38, '{Et le second chœur marcha du côté opposé, et je le suivais, moi et la moitié du peuple, sur la muraille, au-dessus de la tour des Fours, jusqu\'à la muraille large.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 39, '{Au dessus de la tour d\'Ephraïm,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 40, '{Et les deux chœurs s\'arrêtèrent dans la maison de Dieu, ainsi que moi et la moitié des magistrats, qui m\'accompagnait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 41, '{Et les sacrificateurs Eliakim, Maaséia, Minjamin, Micaïa, Eljoénaï, Zacharie, Hanania avec des trompettes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 42, '{et Maaséia et Sémaïa et Eléazar et Uzzi et Johanan et Malkija et Elam et Ezer, et les chantres furent entendus et comptés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 43, 'Et ce jour-là, on immola de nombreuses victimes et la joie était grande, car Dieu les avait grandement réjouis, et leurs femmes et leurs enfants prenaient part à ces réjouissances, et les cris joyeux de Jérusalem s\'entendaient au loin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 44, 'Et ce jour-là, on institua des gardiens des trésors, des prémices et des dîmes, et des hommes pour les recueillir dans les villes, et on les choisit parmi les prêtres et les lévites; car Juda se réjouissait d\'avoir vu les lévites et les prêtres reprendre leurs fonctions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 45, 'Et l\'on remit en vigueur les règlements de David et de Salomon, son fils, concernant les purifications, ainsi que les chantres et les portiers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 46, 'Car, du temps de David, Asaph était à la tête des chantres, et de ceux qui célébraient le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 47, 'Et du temps de Zorobabel et de Néhémias, tout le peuple d\'Israël assigna des parts aux chantres et aux portiers; on les leur distribuait chaque jour. On donnait aussi aux lévites ce qui leur était dû de la chair des sacrifices, et les lévites donnaient aux fils d\'Aaron la part qui leur en revenait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 1, 'En ce jour-là, on lut à haute voix au peuple le livre de Moïse, et on y trouva écrit: Que les Ammonites et les Moabites ne devaient jamais entrer dans l\'Église de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 2, 'Parce qu\'ils n\'étaient point venus au-devant d\'Israël avec du pain et de l\'eau, et qu\'ils avaient salarié Balaam pour le maudire; mais, notre Dieu changea la malédiction en bénédiction.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 3, 'Et lorsqu\'ils eurent ouï la loi, tous ceux qui s\'étaient mêlés à Israël en furent séparés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 4, 'Or, avant cela, Eliasib, le prêtre, très-proche allié de Tobias, demeurait dans le trésor du temple de notre Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 5, 'Et il s\'était fait faire un vaste magasin dans le lieu où l\'on déposait jadis les offrandes, l\'encens, les vases, la dîme du blé, du vin et de l\'huile, ce qui était dû aux lévites, aux chantres et aux portiers, et les prémices destinées aux prêtres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 6, 'Et, en ce temps-là, je n\'étais pas à Jérusalem. Car, dans la trente- deuxième année du règne d\'Arthasastha, roi de Babylone, j\'étais allé auprès du roi. Et, un certain nombre de jours étant accompli, je demandai au roi la permission de partir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 7, 'Et je revins à Jérusalem, et je reconnus le mal qu\'avait fait Eliasib avec Tobias en lui faisant un magasin dans le parvis du temple de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 8, 'Et cela me parut très-mal; et je jetai hors du magasin tous les meubles de la maison de Tobias.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 9, 'Et je parlai, et on purifia le magasin, et j\'y fis replacer les vases du temple, les offrandes et l\'encens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 10, 'Et je reconnus qu\'on n\'avait plus donné la part des lévites, de sorte que les lévites et les chantres faisant œuvre au temple s\'étaient enfuis chacun en sa terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 11, 'Et je fis des reproches aux officiers, et je leur dis: D\'où vient que le temple du Seigneur est abandonné? Puis, je rassemblai les lévites et les Chantres, et je les rétablis dans leurs fonctions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 12, 'Alors, tout Juda apporta dans les trésors la dîme du froment; de l\'huile et du vin,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 13, 'Entre les mains de Sélémias le prêtre, de Sadoc le scribe, et de Phadaïa, l\'un des lévites. Et ils avaient auprès d\'eux Anan, fils de Zacchur, fils de Matthanias; car ils étaient réputés fidèles, et ils furent chargés de faire les distributions à leurs frères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 14, 'Souvenez-vous de moi, ô mon Dieu, à cause de cela; que mes bonnes œuvres dans le temple du Seigneur Dieu ne soient point effacées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 15, 'En ces jours-là, je vis que dans Juda quelques-uns pressuraient le vin le jour du sabbat; je vis que d\'autres transportaient des gerbes, que d\'autres encore chargeaient leurs ânes de vin, de grappes, de figues, de toutes sortes de fardeaux, et qu\'ils les conduisaient à Jérusalem le jour du sabbat. Et je les avertis des jours où ils pouvaient trafiquer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 16, 'Et des gens s\'étaient établis à Jérusalem, apportant du poisson, vendant toutes sortes de marchandises aux Juifs, le jour du sabbat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 17, 'Et je réprimandai les fils de Juda de condition libre, et je leur dis: Quelle est cette mauvaise action que vous faites, en profanant le jour du sabbat?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 18, 'N\'est-ce point là ce que faisaient vos pères? n\'est-ce point la cause de tous les malheurs dont notre Dieu les à frappés, eux et notre ville? Et vous, n\'attirerez-vous pas un surcroît de colère sur Israël en profanant le sabbat?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 19, 'Or, quand les portes de Jérusalem furent rétablie, la veille d\'un sabbat, je parlai, et on ferma les portes; je parlai, et on ne les ouvrit qu\'après le sabbat, et je mis de mes serviteurs à chaque porte pour qu\'on ne pût introduire des fardeaux le jour du sabbat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 20, 'Et tous les marchands passèrent la nuit en plein air, et ils vendirent une ou deux fois hors de Jérusalem.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 21, 'Et je les avertis, et je leur dis: Pourquoi passez-vous la nuit devant les remparts? Si vous recommencez, j\'étendrai la main sur vous. Depuis lors, ils ne vinrent plus le jour du sabbat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 22, 'Et je dis aux lévites qui s\'étaient purifiés, et qui étaient venus garder les portes, de sanctifier le jour du sabbat: à cause de cela, souvenez-vous de moi, mon Dieu, et épargnez-moi, selon la plénitude de votre miséricorde.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 23, 'Or, en ces jours-là, je vis que des Juifs avaient épousé des femmes d\'Azot, et des Ammonites et des Moabites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 24, 'Et leurs fils parlaient à demi la langue d\'Azot, et ils ne savaient point parler juif.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 25, 'Et je les réprimandai, et je les maudis, et j\'en frappai quelques-uns, et je leur rasai la tête, et je leur fis jurer devant Dieu de ne point donner leurs filles aux fils des étrangers, et de ne point faire épouser par leurs fils des filles étrangères, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 26, 'N\'est-ce pas là le péché de Salomon, roi d\'Israël? Il n\'y avait point son pareil parmi les rois des nations: il aimait Dieu, Dieu lui avait donné le royaume entier d\'Israël, et les femmes étrangères le pervertirent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 27, 'Que nous n\'apprenions plus que vous faites ce péché; que vous violez l\'alliance avec notre Dieu; que vous épousez des femmes étrangères.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 28, 'Or, l\'un des fils de Joad, le grand prêtre Elisab, était gendre de Sanaballat l\'Horonite; je le chassai loin de moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 29, 'Souvenez-vous d\'eux, ô Seigneur, à cause de la violation du sacerdoce, et de votre alliance, touchant les prêtres et les lévites.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 30, 'Et je les purifiai de leur contact avec des étrangères, et je réglai les services journaliers des prêtres et des lévites,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 31, 'Et l\'offrande du bois des holocaustes au temps prescrit, lorsque l\'on taille la vigne. Souvenez-vous de moi, ô mon Dieu, dans votre mansuétude.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'La seconde année du règne du grand roi Artaxerxès, le premier de Nisan, le Juif Mardochée, fils de Jaïr, fils de Sémeï, fils de Cisée, de la tribu de Benjamin, Demeurant en la ville de Suse, homme considérable, servant dans le palais du roi, eut en songe une vision. Il était des captifs que Nabuchodonosor, roi de Babylone, avait emmenés avec Jéchonias, roi de la Judée, Et voici sa vision: Voilà qu\'il y avait voix et bruit, tonnerres et tremblements de terre, tumulte sur la terre, Et voilà que deux dragons s\'avancèrent, prêts à se combattre mutuellement; et ils poussaient de grands cris, Et à leurs cris chaque nation se préparait à la guerre, pour combattre la nation des justes. Voilà que c\'était un jour d\'obscurité et de ténèbres, de tribulation et d\'angoisse, d\'affliction et de grand tumulte sur la terre, Et toute la nation juste fut troublée, craignant sa propre affliction, et elle se tint prête à mourir, et elle cria au Seigneur Dieu. Et à ses cris, il vint comme un grand fleuve, sortant d\'une petite fontaine, Et la lumière et le soleil parurent, et les humbles furent exaltés, et ils dévorèrent les superbes. Et Mardochée, celui qui avait eu cette vision, s\'étant éveillé, se demanda en son cœur ce que Dieu voulait faire, et, toute la nuit, il n\'eut pas d\'autre pensée que de le découvrir. Or, Mardochée se tint tranquille dans le parvis près de Gabatha et de Tharra, deux eunuques du roi qui gardaient le palais, Et il entendit leurs réflexions et il surprit leurs préoccupations, et il apprit qu\'ils se préparaient à porter les mains sur le roi Artaxerxès, et il instruisit le roi de ce qui les concernait. Et le roi interrogea les deux eunuques; et ayant avoué, ils furent menés au supplice, Et le roi fit écrire ces choses en un mémorial, et Mardochée aussi écrivit le récit de ces choses. Et le roi ordonna que Mardochée servît dans l\'intérieur du palais, et il lui fit, à ce sujet, des présents. Or, Aman, fils d\'Amadathe le Bugéen, était en faveur auprès du roi, et il chercha à nuire à Mardochée et à son peuple à cause des deux eunuques du roi. Or, après ces choses, il advint durant les jours d\'Artaxerxès, qui régnait depuis l\'Inde sur cent vingt-sept contrées,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'En ces jours-là, tandis qu\'il trônait en la ville de Suse,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'La troisième année de son règne, il advint qu\'il fit un festin à ses amis et au reste des nations, et aux hommes considérables des Perses et des Mèdes, et aux premiers des satrapes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Et ensuite, après leur avoir montré les richesses de son royaume, et la splendeur de ses joies et de ses trésors, pendant cent quatre-vingts jours,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Lorsque les jours de ses noces furent remplis, il fit pendant six jours aux nations qui se trouvaient à Suse un festin dans le parvis du palais,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Orné de voiles du lin le plus fin, et de gaze tendue par des cordons de lin et de pourpre sur des socles d\'or et d\'argent, et sur des colonnes de marbre blanc et de pierre. Les lits, d\'argent et d\'or, étaient posés sur des mosaïques d\'émeraudes, de nacre et de marbre blanc; et les couvertures transparentes, diversement brodées, étaient encadrées de feuilles de roses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Les coupes étaient d\'argent et d\'or, et il y avait une petite coupe en diamant évaluée trente mille talents; on les remplissait de vin abondant et doux, le même que le roi buvait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Et le repas ne se fit pas selon la loi établie; le roi l\'avait ainsi voulu, et il avait ordonné à ses économes de se conformer à ses propres désirs et à ceux de ses convives.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Et Vasthi, la reine, fit un festin pour les femmes dans l\'intérieur du palais où résidait le roi Artaxerxès.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Le septième jour, le roi, étant en belle humeur, dit à Aman, à Bazan, à Tharra, à Barazi, à Zatholtha, à Abataza et à Tharaba, les sept eunuques attachés à sa personne,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'De lui amener la reine pour qu\'il la couronnât, qu\'il posât sur sa tête le diadème, et qu\'il la montrât dans sa beauté aux chefs et aux nations; car elle était belle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Mais la reine Vasthi refusa de suivre les eunuques, et le roi en fut affligé, et il se mit en colère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Et il dit à ses amis: Voici ce qu\'a dit la reine, faites donc à ce sujet loi et jugement.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Et Arcesée, Sarsathée et Maliséar, princes des Perses et des Mèdes, ceux qui se tenaient près du roi, et qui s\'asseyaient les premiers après lui, s\'approchèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Et ils lui firent connaître ce que selon la loi il était à propos de faire à la reine Vasthi, parce qu\'elle n\'avait point fait ce que lui avait commandé le roi par ses eunuques.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Et Muchée dit au roi et aux princes: Vasthi, la reine, n\'a pas nui au roi seul, mais aussi à tous les princes et aux grands officiers du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Et il leur dit les paroles de la reine, et comme elle avait contredit le roi, et continuant: De même, ajouta-t-il, qu\'elle a contredit le roi Artaxerxès,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Les autres femmes des Perses et des Mèdes du premier rang, apprenant ce qu\'elle a dit au roi, oseront à l\'avenir ne point honorer leurs époux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Si donc le roi le juge à propos, qu\'il rende un édit, qu\'il l\'écrive selon la loi des Perses et des Mèdes, que l\'on ne puisse y déroger; qu\'il défende à la reine de s\'approcher désormais de sa personne, et que le roi donne le diadème royal à une femme meilleure qu\'elle;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Et que l\'édit qu\'aura rendu le roi soit publié en tout son royaume. Alors, toutes les femmes mettront leurs soins à honorer leurs époux, depuis l\'indigent jusqu\'au riche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Or, ce conseil plut au roi et aux princes, et le roi fit comme avait dit Muchée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Et il envoya dans toutes les provinces de son royaume l\'édit traduit en leurs diverses langues, afin qu\'en toute demeure on eût crainte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Après ces choses, la colère du roi à la longue s\'assoupit; mais il ne rechercha plus la reine, se souvenant de ce qu\'elle avait dit, et du jugement qu\'il avait rendu contre elle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Et les serviteurs du roi dirent: Que l\'on cherche pour le roi des jeunes filles chastes et belles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Que le roi donne ses ordres aux comarques de toutes les provinces de son royaume; qu\'ils choisissent des jeunes filles vierges et belles pour le gynécée de la ville de Suse; qu\'on les mette entre les mains de l\'eunuque du roi gardien des femmes; et qu\'on leur donne là des cosmétiques et toutes sortes de soins.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Puis, la femme qui plaira au roi sera reine à la place de Vasthi. Ce projet fut agréable au roi, et il fit ainsi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Or, il y avait en la ville de Suse un Juif qui se nommait Mardochée, fils de Jaïr, fils de Sémeï, fils de Cisée, de la tribu de Benjamin,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Qui avait été fait captif à Jérusalem, parmi ceux qu\'avait emmenés Nabuchodonosor, roi de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Il avait élevé une enfant, fille d\'Aminadab, son oncle paternel, et elle se nommait Esther, et, ses parents étant morts, il l\'avait élevée pour qu\'elle fût sa femme, et la jeune fille était belle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Or, lorsque l\'édit du roi fut publié, beaucoup de jeunes filles furent réunies à Suse entre les mains de l\'eunuque Haï. Esther fut aussi conduite chez Haï, gardien des femmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Et la jeune fille lui plut et elle trouva grâce à ses yeux, et il se hâta de lui donner des cosmétiques et sa part, et sept jeunes filles du palais pour la servir; il en usa bien avec elle et avec ses suivantes, dans le gynécée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Et Esther ne fit connaître ni ses parents ni sa patrie, car Mardochée lui avait défendu d\'en rien déclarer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Et chaque jour Mardochée se promenait dans le parvis du gynécée, observant ce qui pouvait arriver à Esther.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Or, le moment où une jeune fille entre chez le roi, arrive quand les douze mois sont accomplis, car alors les jours de la purification sont écoulés; pendant six mois, elle s\'est ointe d\'huile de myrrhe, et pendant six mois d\'aromates et de cosmétiques de femmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Enfin, on l\'introduit chez le roi, et l\'eunuque à qui il en donne l\'ordre la conduit, pour qu\'elle aille auprès de lui, du gynécée aux chambres du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 14, 'Elle y entre le soir, et, le lendemain, elle retourne au second gynécée où est l\'eunuque Haï, gardien des femmes, et on ne la reconduit plus chez le roi, à moins qu\'il ne la demande par son nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 15, 'Et quand fut accompli le temps après lequel Esther, fille d\'Aminadab, oncle paternel de Mardochée, devait être présentée au roi, elle ne négligea rien de ce que lui prescrivit l\'eunuque, gardien des femmes. Car il était donné à Esther de trouver grâce aux yeux de tous ceux qui la voyaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 16, 'Elle entra donc chez le roi Artaxerxès, le douzième mois qui est adar, la septième année de son règne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 17, 'Et le roi aima Esther, et elle trouva grâce à ses yeux plus que toutes les autres vierges, et il lui mit le diadème de reine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 18, 'Et le roi fit un festin à tous ses amis et à tous ses grands, et la fête dura sept jours, et il célébra magnifiquement le mariage d\'Esther, et il fit remise de ce qui lui était dû par les sujets de son royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 19, 'Et Mardochée servait dans le parvis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 20, 'Et Esther ne déclara point quelle était sa patrie; car Mardochée le lui avait défendu, lui prescrivant de craindre Dieu et de suivre ses commandements, comme lorsqu\'elle demeurait en sa maison; et Esther ne changea rien à ses habitudes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 21, 'Et les deux eunuques, chefs des gardes du corps du roi, s\'affligèrent des honneurs auxquels s\'élevait Mardochée, et ils cherchèrent à tuer Artaxerxès.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 22, 'Et Mardochée découvrit le complot, et il le dit à Esther, qui dévoila tout au roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 23, 'Or, le roi interrogea les eunuques et il les fit pendre; et il prescrivit d\'écrire en un mémorial, dans les archives de la bibliothèque royale, une notice sur les bons offices de Mardochée, à sa louange.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Et, après cela, le roi Artaxerxès glorifia Aman, fils d\'Amadathe le Bugéen, et il l\'exalta, et il le fit asseoir sur un siège au-dessus de tous ses amis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Et tous ceux qui servaient dans le parvis l\'adoraient, car ainsi l\'avait ordonné le roi; et Mardochée ne se prosternait pas devant lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Et les serviteurs du parvis dirent à Mardochée: Mardochée, pourquoi désobéis-tu à ce qu\'a dit le roi?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Chaque jour ils lui parlaient ainsi, et il ne les écoutait pas; enfin, ils informèrent Aman que Mardochée résistait aux ordres du roi; or, Mardochée leur avait déclaré qu\'il était Juif.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Et Aman, en apprenant que Mardochée ne se prosternait pas devant lui, fut fort courroucé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Et il résolut d\'effacer tous les Juifs du royaume d\'Artaxerxès.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Et, en la douzième année du règne d\'Artaxerxès, il prépara un édit, et il agita les sorts pour savoir le mois et le jour où il exterminerait en même temps la race de Mardochée, et le sort tomba sur le quatorzième du mois qui est appelé adar.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Et il parla au roi disant: Il y a un peuple épars en toutes les provinces de ton royaume; leurs lois diffèrent de toutes les autres lois; ils n\'obéissent point à celles du roi; il n\'est pas à propos que le roi les laisse subsister.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'S\'il plaît au roi, qu\'il décrète qu\'on les détruise, et moi je ferai rentrer au trésor royal dix mille talents d\'argent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Et le roi ôtant son anneau le remit à Aman pour sceller l\'édit contre les Juifs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Et le roi lui dit: L\'argent sera pour toi, fais de ce peuple ce qu\'il te plaît.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Et, le treize du premier mois, les scribes du roi furent convoqués, et ils écrivirent, selon l\'ordre d\'Aman, aux généraux et aux gouverneurs des cent vingt-sept provinces de l\'Inde à l\'Éthiopie, et aux chefs des nations chacun en sa langue, de la part du roi Artaxerxès.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Et des courriers portèrent dans tout le royaume le commandement de détruire en un seul jour, le premier du douzième mois, qui est adar, toute la race des Juifs, et de piller leurs biens. Or, voici la copie de la lettre: Le grand roi Artaxerxès aux gouverneurs des cent vingt-sept provinces assujetties à son empire, de l\'Inde à l\'Éthiopie, et à leurs lieutenants écrit ce qui suit: Roi d\'une multitude de nations, maître de toute la terre habitable, j\'ai eu en l\'esprit, ne concevant aucun orgueil de l\'étendue de ma puissance, me conduisant avec une extrême modération et une très grande douceur, d\'assurer à mes sujets une vie toujours paisible, voulant faire jouir de l\'ordre et du repos mon empire, jusqu\'à ses extrêmes limites, et rétablir la paix que désirent tous les hommes. Quand j\'ai demandé à mes conseillers comment ce but serait atteint, celui qui excelle auprès de nous en sagesse, dont on connaît la bonne volonté constante et la fidélité inébranlable, le second de mon royaume en honneurs, Aman, Nous a fait savoir qu\'un peuple ennemi s\'est mêlé parmi les tribus de la terre habitable, opposé en ses lois à toute autre nation; négligeant toujours les ordres du roi, de telle sorte que l\'union des pouvoirs, qui a été réglée parmi nous d\'une manière irréprochable, ne puisse être établie. Ayant donc jugé que cette nation unique est toujours en opposition avec le reste des hommes, qu\'elle diffère de nous par des lois étrangères, qu\'elle est malveillante, complotant avec les pires intentions contre nos intérêts et contre la stabilité de l\'empire, Nous avons ordonné que ceux qui vous sont signalés dans les lettres à vous adressées, par mon second père, Aman, préposé aux affaires publiques, soient détruits radicalement avec leurs femmes et leurs enfants; qu\'on les passe au fil de l\'épée, sans pitié ni ménagements, le quatorzième jour du douzième mois, du mois d\'adar de la présente année, Pour qu\'en une seule journée, ces ennemis anciens et actuels descendent violemment aux enfers, et qu\'à l\'avenir, et jusqu\'à la fin, nos affaires soient stables, sans trouble.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Et les copies de ces lettres furent publiées en chaque province, et il fut enjoint à chaque nation de se tenir prête pour le jour indiqué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'On y avait mis de l\'empressement à Suse, et le roi et Aman buvaient à pleines coupes; mais la ville était toute troublée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Or, Mardochée, instruit de ce qu\'on avait fait, déchira ses vêtements, se ceignit d\'un cilice et se couvrit de cendre; puis, s\'élançant par les rues de la ville, il cria à haute voix: Un peuple innocent périt.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Et il arriva devant la porte du roi, et il s\'y tint debout; car il ne lui était pas permis d\'entrer dans la cour, ayant un cilice et de la cendre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Et en toute province, où l\'édit avait été publié, les Juifs s\'étaient couverts de cilices et de cendres, et l\'on n\'entendait que des cris, des gémissements et des pleurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Et les servantes et les eunuques de la reine entrèrent, et lui dirent ce qui était advenu, et elle en fut troublée, et elle envoya prier Mardochée de se vêtir d\'une robe et d\'ôter son cilice, et il n\'obéit pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Et Esther appela Achrathée, son eunuque, qui se tenait auprès d\'elle, et elle l\'envoya demander à Mardochée la vérité exacte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Et Mardochée lui fit connaître tout ce qui s\'était passé, et la promesse qu\'Aman avait faite au roi de verser au trésor dix mille talents d\'argent, afin qu\'il exterminât les Juifs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Et Mardochée lui fit connaître tout ce qui s\'était passé, et la promesse qu\'Aman avait faite au roi de verser au trésor dix mille talents d\'argent, afin qu\'il exterminât les Juifs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Et il lui donna, pour le montrer à Esther, l\'édit affiché dans Suse sur ce massacre, et il lui dit: Recommande à la reine d\'entrer chez le roi, pour l\'implorer et le supplier en faveur du peuple, dis-lui: Souviens-toi de ton humble état, quand je te nourrissais de ma main. Pourquoi Aman, le second après le roi, a-t-il parlé contre nous afin que nous périssions? Invoque le Seigneur; parle au roi pour nous sauver de la mort.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Or, Achrathée, étant rentré, répéta toutes ces paroles à la reine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Et Esther lui répondit: Va retrouver Mardochée, et dis-lui:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Toutes les nations de l\'empire savent que n\'importe quel homme ou femme qui entre auprès du roi, dans l\'intérieur du palais, sans y être appelé, n\'a pas de salut à espérer; sauf celui sur qui le roi étend sa verge d\'or; celui- là est sauvé. Et moi, voilà trente jours que je n\'ai été appelée pour entrer chez le roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Et Achrathée rapporta toutes les paroles d\'Esther à Mardochée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Et Mardochée lui répondit: Rentre, et dis-lui Esther, ne te dis pas à toi-même que dans tout le royaume, toi seule échapperais plutôt que tous les Juifs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Si en ce moment tu me désobéis, le secours et la protection viendront d\'ailleurs aux Juifs, et toi, et la maison de ton père, vous périrez. Et qui sait si ce n\'est pas à cette occasion que tu règnes?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Et Esther renvoya à Mardochée l\'homme qui était venu près d\'elle, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Éloigne-toi, rassemble tous les Juifs qui sont à Suse, jeûnez pour moi; passez trois jours et trois nuits sans manger ni boire, et moi et mes suivantes, nous ne prendrons aucun aliment; alors j\'entrerai chez le roi, contre la loi, dussé-je mourir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Et Mardochée, s\'étant éloigné, fit ce que lui avait prescrit Esther; et il pria le Seigneur, se souvenant de toutes les œuvres de Dieu, et il dit: Seigneur, Seigneur, Roi de tous les rois; il n\'est rien qui ne soit en votre puissance, et nul ne vous contredira si votre volonté est de sauver Israël. Vous avez créé le ciel et la terre et toutes les merveilles qui sont sous les cieux, vous êtes le Seigneur de toutes choses, et nul ne peut s\'opposer au Seigneur. Rien ne vous est caché; vous savez, Seigneur, que ce n\'est point par insolence, que ce n\'est point par orgueil, que ce n\'est point par vaine gloire, que j\'ai refusé d\'adorer le superbe Aman; car, pour le salut d\'Israël, Je lui eusse avec joie baisé la plante des pieds. Mais, je ne l\'ai point adoré, de peur de mettre la gloire d\'un homme au-dessus de la gloire de Dieu, et je n\'adorerai personne hormis vous, mon Seigneur, et je ne ferai point de telles choses par orgueil. Et maintenant, Seigneur Dieu et Roi, Dieu d\'Abraham, épargnez votre peuple, car ils nous regardent pour nous perdre, et dès l\'origine ils ont désiré détruire votre héritage. Ne méprisez point votre peuple particulier que vous avez délivré de la terre d\'Égypte; Exaucez ma prière, soyez propice à ceux que vous vous êtes réservés en partage; changez notre deuil en fêtes, afin que vivants nous chantions votre nom, ô Seigneur; ne fermez pas la bouche de ceux qui vous louent, ô Seigneur. Et tout Israël jeta des cris de toute sa force, car ils avaient la mort devant les yeux. Cependant, la reine Esther, comme saisie par l\'agonie de la mort, se réfugia vers le Seigneur; elle ôta ses vêtements de gloire pour prendre ceux du deuil et de la pauvreté, et au lieu des parfums des superbes, elle se couvrit la tête de poussière et de fange; elle se fit humble en toute sa personne, et tout le lieu où elle se parait en son allégresse, fut rempli des cheveux qu\'elle s\'arracha. Et elle pria le Seigneur Dieu d\'Israël, et elle dit: Ô mon Seigneur, notre roi, vous êtes unique, secourez-moi, moi qui suis seule devant vous: je n\'ai point de protecteur hormis vous, et mon danger est près de ma main. Dès ma naissance, j\'ai appris, dans ma tribu paternelle, que vous, Seigneur, vous avez choisi Israël parmi toutes les nations, et nos pères plutôt que leurs ancêtres, pour qu\'ils soient votre héritage éternel, et que vous avez fait pour eux tout ce que vous avez dit. Et maintenant, nous avons péché devant vous, et vous nous avez livrés à nos ennemis, parce que nous avions glorifiés leurs dieux. Vous êtes juste, Seigneur. Mais, l\'amertume de notre esclavage ne leur a pas suffi; ils ont mis la main sur la main de leurs idoles, pour annuler le décret prononcé par vous, effacer votre héritage, fermer la bouche de ceux qui vous louent, éteindre la gloire de votre temple et de votre autel, Ouvrir la bouche des gentils pour louer les vertus de leurs vaines idoles, et admirer à jamais un roi de chair. Seigneur, n\'abandonnez pas votre sceptre à ceux qui ne sont point; que nos ennemis ne rient point de notre chute; tournez contre eux leurs conseils, faites un exemple de celui qui s\'est élevé contre nous. Souvenez-vous de nous, Seigneur; manifestez-vous au temps de notre affliction; rassurez-moi, Roi des dieux, Maître de toute domination. Faites sortir de ma bouche, en présence du lion, des paroles harmonieuses; changez son cœur, et qu\'il prenne en haine notre ennemi; qu\'il le perde, lui et ses complices. Sauvez-nous par votre main, secourez-moi, seule comme je suis, et sans autre appui que vous. Rien ne vous est caché, et vous savez que je déteste la gloire des impies, que j\'ai en abomination la couche des incirconcis et de tout étranger. Vous n\'ignorez pas la contrainte où je vis; car j\'abhorre ce signe d\'orgueil que je pose sur ma tête en mes jours d\'apparat; je l\'ai en horreur comme le haillon le plus vil, et je n\'ai garde de le porter en mes jours de paix. Et votre servante n\'a point mangé à la table d\'Aman, et je n\'ai point honoré les banquets du roi, je n\'ai point bu le vin des libations, Et votre servante n\'a point eu de joie depuis le jour de son élévation jusqu\'à ce moment, si ce n\'est en vous Seigneur Dieu d\'Abraham. Ô Dieu, vous pouvez plus que tous; écoutez la voix des désespérés, sauvez nous de la main des méchants, et sauvez-moi de ma terreur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Et le troisième jour, lorsqu\'elle eut fini de prier, elle dépouilla les habits de la servitude et se revêtit de sa gloire, Et redevenue éclatante, après avoir invoqué le Dieu qui voit toutes choses et qui sauve, elle prit avec elle deux servantes; sur l\'une elle s\'appuya comme une femme délicate; l\'autre la suivit allégeant le poids de son manteau; Et elle-même s\'avança rougissant en la fraîcheur de sa beauté, le visage riant, plein de bienveillance, tandis que son cœur était oppressé par la crainte. Ayant franchi toutes les portes, elle s\'arrêta devant le roi. Or, il était assis sur son trône royal, et il s\'était revêtu de toute sa magnificence, et il était couvert d\'or et de pierres précieuses, et il était terrible. Et quand il leva son front rayonnant de majesté, un éclair de fureur brilla dans son regard. Et la reine tomba, et son teint se changea en une mortelle pâleur, et elle se pencha sur la tête de la servante qui la précédait. Et Dieu adoucit l\'esprit du roi; et saisi d\'angoisse, Artaxerxès s\'élança de son trône, et il la prit dans ses bras jusqu\'à ce qu\'elle revînt, et il la consola par des paroles caressantes, Et il lui dit: Esther! qu\'y a-t-il, je suis ton frère, rassure-toi, tu ne mourras point; mais notre loi est pour tous; approche.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Et ayant levé sa verge d\'or, il la posa sur son cou et il l\'embrassa, et il lui dit: Parle-moi, Et elle répondit: Je t\'ai vu, seigneur, comme l\'ange de Dieu, et mon cœur a été troublé par la crainte de ta gloire, car tu frappes d\'admiration, ô seigneur, et ton visage est l\'arbitre des grâces. Pendant qu\'elle parlait, elle s\'évanouit encore, et le roi fut troublé, et tous ses serviteurs la consolèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Et le roi dit: Que veux-tu, Esther? quelle est ta demande? Serait-ce la moitié de mon royaume, elle sera à toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Et Esther dit: Ce jour est pour moi un jour de fête, s\'il plaît au roi, qu\'il vienne avec Aman à un festin que je fais aujourd\'hui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Et le roi dit: Que l\'on se hâte d\'avertir Aman, afin que nous fassions selon la parole d\'Esther. Et tous les deux assistèrent au festin qu\'avait dit la reine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Et, pendant le repas, le roi lui dit: Qu\'y a-t-il, reine Esther? Ce que tu demandes sera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Et elle répondit: Ma requête et ma demande?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Si j\'ai trouvé grâce devant le roi, que le roi vienne encore avec Aman demain au festin que je leur ferai, et demain je ferai ma requête et ma demande.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Et Aman, au comble de la joie, sortit d\'auprès de son maître; et en apercevant dans le parvis le Juif Mardochée, il fut grandement courroucé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Et aussitôt rentré chez lui, il convoqua ses amis et Zosara, sa femme,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Et il leur décrivit ses richesses et les honneurs dont le roi l\'avait revêtu, et comme il l\'avait placé à la tête du royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Et il ajouta: La reine n\'a invité personne au festin qu\'elle vient de donner à son époux, si ce n\'est moi, et je suis convié encore pour demain.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Mais rien de tout cela ne me charmera tant que je verrai dans le parvis le Juif Mardochée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Et Zosara, sa femme, et ses amis lui dirent: Que l\'on te fasse une potence de cinquante coudées; parles-en demain au roi dès l\'aurore, et que Mardochée soit pendu à cette potence. Ensuite, va au festin avec ton maître, et sois joyeux. Et le conseil plut à Aman, et il fit dresser la potence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Or, cette nuit-là, le Seigneur éloigna du roi le sommeil, et Artaxerxès dit à son serviteur d\'apporter le livre de ses archives et de le lui lire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Et il tomba sur ce qui était écrit concernant Mardochée, quand il avait fait connaître au roi le complot des deux eunuques qui le gardaient, et qui voulaient porter les mains sur lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Et le roi dit: Quels honneurs, quelle grâce Mardochée a-t-il reçus de moi? Et les serviteurs répondirent:Tu n\'as rien fait pour lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Pendant que le roi se rappelait le zèle de Mardochée, Aman entra dans le parvis, et le roi dit: Y a-t-il quelqu\'un dans le parvis? Or, Aman arrivait pour demander au roi de pendre Mardochée à la potence qu\'il avait dressée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Et les serviteurs du roi répondirent: Voilà Aman dans le parvis. Et le roi dit: Appelez-le.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Et le roi dit à Aman: Que ferai-je pour l\'homme que je veux glorifier? Et Aman se dit: Qui donc le roi veut-il glorifier, si ce n\'est moi?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Et il répondit: Pour l\'homme que le roi veut glorifier,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Que les serviteurs du roi apportent la robe de fin lin dont il se revêt, et le cheval qu\'il monte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Que cela soit donné à l\'un des amis du roi, parmi ceux du premier rang; qu\'il habille l\'homme que le roi aime, qu\'il le fasse monter à cheval, que dans toutes les places de la ville il proclame ces mots: Ainsi sera-t-il fait à tout homme que le roi honore.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Et le roi dit à Aman: Tu as bien parlé; ainsi soit fait par toi au Juif Mardochée qui sert en mon parvis, et que rien ne soit négligé de ce que tu as dit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Aman prit donc la robe, et le cheval, et il habilla Mardochée, et il le fit monter à cheval, et il parcourut toutes les rues de la ville, et il proclama ces mots: Ainsi sera-t-il fait à tout homme que le roi voudra honorer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Et Mardochée revint au parvis, et Aman rentra en sa demeure avec un grand mal de tête.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Et il fit à Zosara, sa femme, et à ses amis, le récit de ce qui était advenu; et ses amis et sa femme lui dirent: Si Mardochée est de la race des Juifs, tu as commencé à être humilié devant lui; tu tomberas; et tu ne pourras te défendre contre lui; car le Dieu vivant est avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Comme ils parlaient encore, les eunuques vinrent presser Aman de se rendre au repas qu\'Esther avait préparé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Le roi et Aman entrèrent pour boire avec la reine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Et, à ce second festin, le roi dit à Esther: Qu\'y a-t-il, reine Esther? Quelle est ta requête, quelle est ta demande? Qu\'il te soit accordé jusqu\'à la moitié de mon royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Et elle répondit: Si j\'ai trouvé grâce devant le roi, qu\'il accorde à ma requête, ma vie, et à ma demande, mon peuple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Car moi et mon peuple nous sommes voués à la destruction, au pillage, à l\'esclavage, nous et nos enfants, nos serviteurs et nos servantes. Mais je n\'y ai point cru, parce que l\'accusateur n\'est pas digne du palais du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Et le roi: Qui donc est celui qui a osé faire cette clause?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Et Esther dit: Notre ennemi c\'est Aman, ce méchant homme. Or, Aman était plein de trouble à cause du roi et de la reine.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Et le roi se leva de table pour aller dans le jardin, et Aman implora la reine; car il se voyait dans le malheur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Et le roi rentra du jardin, et Aman était tombé sur le lit en suppliant la reine, et le roi s\'écria: Va-t-il jusqu\'à faire violence à ma femme dans mon palais? À ces mots, Aman eut le visage bouleversé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Et Bugathan, l\'un des eunuques, dit au roi: Aman a préparé pour Mardochée, qui a jadis averti le roi, une potence de cinquante coudées; elle est dressée dans sa maison. Et le roi dit: Qu\'on l\'y attache.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Et Aman fut pendu à la potence qu\'il tenait prête pour Mardochée, et la colère du roi s\'apaisa.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Et, en ce jour-là même, le roi Artaxerxès fit don à Esther de tout ce que possédait Aman l\'accusateur; et il appela Mardochée, car la reine lui avait dit leur parenté.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Et le roi prit l\'anneau qu\'il avait ôté à Aman et il le remit à Mardochée; et la reine chargea celui-ci d\'administrer les biens d\'Aman.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Et, continuant de parler au roi, elle se jeta à ses pieds, et lui demanda de rendre nuls les mauvais desseins d\'Aman, et ce qu\'il avait fait contre les Juifs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Et le roi étendit sur Esther sa verge d\'or, et elle fut encouragée à se placer auprès de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Et elle dit: S\'il te plaît, si j\'ai trouvé grâce, que l\'on fasse révoquer les édits qu\'a publiés Aman, ordonnant d\'exterminer tous les Juifs qui sont en ton royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Car, comment pourrais-je voir la ruine de mon peuple? Comment pourrais-je survivre à la destruction de ma patrie?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Et le roi dit à Esther: Puisque je t\'ai donné tous les biens d\'Aman, et que je t\'en ai gratifié; puisque je l\'ai fait pendre lui-même pour avoir porté les mains sur les Juifs, que demandes-tu encore?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Écrivez vous-mêmes en mon nom ce qu\'il vous plaira, et scellez-le avec mon anneau; car nul ne peut contredire ce qui est écrit par l\'ordre du roi, et revêtu de son scel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Les scribes furent donc convoqués le vingt-trois du premier mois, du mois de nisan, de la même année, et l\'on écrivit ce qui était ordonné, concernant les Juifs, aux intendants et aux chefs des satrapes des cent vingt-sept provinces, depuis l\'Inde jusqu\'à l\'Éthiopie, en la langue de chacune d\'elles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'On écrivit au nom du roi, et on scella de son sceau les lettres, et on les expédia par des courriers.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Elles prescrivaient de permettre aux Juifs, en chaque ville, de vivre selon leur loi, de leur porter secours, et de mettre à leur merci leurs ennemis et ceux qui résisteraient,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Dans le royaume d\'Artaxerxès, le treizième jour du douzième mois qui est adar. Voici la copie de la lettre: Le grand roi Artaxerxès aux satrapes des cent vingt-sept provinces, de l\'Inde à l\'Éthiopie, aux gouverneurs des districts, et aux hommes dévoués à mon service, salut. Il arrive que plusieurs, après avoir été souvent honorés des bienfaits de la bonté, ambitionnent plus encore; non seulement ils cherchent à maltraiter nos sujets, mais, incapables de modérer leur orgueil, ils méditent de mauvais desseins contre leurs bienfaiteurs; Non seulement ils veulent abolir la gratitude parmi les hommes, mais, exaltés par la vaine jactance de gens sans vertu, ils pensent se soustraire au jugement, fatal aux méchants, du Dieu qui voit toutes choses. Maintes fois la flatterie a rendu complices du crime de verser le sang innocent, et enveloppé de maux intolérables plusieurs de ceux qui sont investis de l\'autorité, à qui est confié le maniement des affaires de leurs amis; Certains hommes ayant trompé, par le faux raisonnement de la malice, la bienveillance sincère des puissants. Cela se peut voir moins par les plus anciennes histoires, que nous nous transmettons, qu\'en examinant, sous nos pieds, les choses accomplies d\'une manière criminelle par la pestilence d\'hommes indignement revêtus du pouvoir; Et il est de notre devoir, en vue de l\'avenir, de préserver de trouble le royaume, et de donner la paix à tous les hommes, En usant de changements utiles, en jugeant, avec l\'à-propos le plus équitable, les choses qui surviennent sous nos yeux. Aman, fils d\'Amadathe, Macédonien en réalité, étranger au sang des Perses, bien éloigné de notre bonté naturelle, amicalement accueilli par nous, Eut de notre amour, que nous portons à tous les hommes, une telle part que nous l\'appelions notre père, que nous le faisions adorer par tous, et que nous lui avions donné la seconde place du royaume. Mais, il ne put maîtriser son orgueil, et il entreprit de nous ôter la vie et le pouvoir. D\'abord; il nous demanda de perdre notre sauveur Mardochée, notre bienfaiteur en toute circonstance, et la reine Esther, notre irréprochable compagne, et tout leur peuple; et il me surprit par un tissu d\'accusations calomnieuses. Et il espérait par ses artifices dépeupler nos provinces, et faire passer aux Macédoniens l\'empire des Perses. Ce triple scélérat nous avait donc trahis au point de nous décider à exterminer les Juifs, quand nous avons reconnu que, loin d\'être portés à mal faire, ils obéissaient aux lois les plus justes, Qu\'ils étaient les fils du Dieu vivant, très-grand et très-haut, qui nous a dirigés nous et nos ancêtres pour mettre notre royaume en la situation la plus florissante. En conséquence, vous agirez bien en n\'exécutant pas l\'édit que vous a envoyé Aman, fils d\'Amadathe; car, pour ce qu\'il a fait, il a été pendu avec toute sa famille devant les portes de Suse; Dieu lui-même, le maître de toutes choses, l\'a promptement rétribué selon son mérite. Que la présente copie de lettre soit affichée en tout lieu, assurant aux Juifs la liberté de suivre leurs lois et d\'user de leurs richesses; qu\'au temps marqué pour leur affliction, le treize du douzième mois, du mois d\'adar, ils puissent se défendre eux-mêmes contre ceux qui les attaqueraient. Car Dieu, maître de toutes choses, a changé en un jour de joie le jour où devait périr la race qu\'il a choisie; Et vous-mêmes, vous le rangerez parmi vos fêtes solennelles, et vous le célébrerez par des festins universels; afin que, dès maintenant et à l\'avenir, ce soit un jour de délivrance tant pour nous que pour les amis des Perses, et que, pour ceux qui conspirent contre nous, ce jour soit un mémorial de destruction. Toute ville ou province qui désobéira aux présentes prescriptions, ressentira ma colère, et périra par le fer et la flamme; il ne suffira pas qu\'elle devienne Inaccessible aux hommes, les bêtes fauves et les oiseaux la haïront à jamais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Et que l\'on affiche cette copie en des places apparentes dans tout le royaume, et que, le jour indiqué, les Juifs se tiennent prêts à combattre leurs ennemis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Les courriers se hâtèrent de partir pour porter les ordres du roi, et l\'édit fut affiché dans Suse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Et Mardochée sortit, revêtu d\'une robe royale, ayant une couronne d\'or et un diadème pourpre du lin le plus fin; et le peuple de Suse, l\'ayant vu, se réjouit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Et, pour les Juifs, il y eut lumière et allégresse');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'En toute ville et province où l\'on afficha l\'édit et où il fut proclamé, ils firent des réjouissances et se donnèrent des repas. Et, parmi les gentils, beaucoup se circoncirent et judaïsèrent par crainte des Juifs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Le treize du douzième mois, du mois d\'adar, l\'édit du roi fut exécuté.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Ce jour-là, les ennemis des Juifs périrent, et nul ne se défendit à cause de la crainte qu\'ils avaient d\'eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Et les officiers des satrapes, et les rois, et les scribes royaux, honorèrent les Juifs; car ils redoutaient Mardochée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Et l\'édit du roi en vint à être loué dans tout le royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Pharsannès, et Delphon, et Phasgas,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Et Phardathas, et Barcas, et Sarbacas,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Et Marmarinas, et Ruphès, et Arsès, et Zabuthis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Et ils enlevèrent les dix fils d\'Aman, fils d\'Amadathe le Bugéen, l\'ennemi des Juifs, et ils pillèrent leurs maisons');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Ce même jour-là. Et on remit au roi le dénombrement de ceux qui, à Suse, avaient péri.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Et le roi dit à Esther: Les Juifs ont tué cinq cents hommes à Suse; combien penses-tu qu\'ils en aient exterminé dans les provinces? Que demandes- tu encore, que te faut-il?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Et Esther répondit: Qu\'il soit permis aux Juifs d\'en user de même demain jusqu\'à pendre les dix fils d\'Aman.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Et le roi le voulut ainsi; et les corps des fils d\'Aman furent livrés aux Juifs de la ville pour être pendus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Et les Juifs de Suse se réunirent le quatorze d\'Adar, et ils tuèrent trois cents hommes, et ils ne prirent rien de leurs dépouilles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Les autres Juifs du royaume se réunirent et se prêtèrent un mutuel secours, et ils se débarrassèrent de leurs ennemis; car ils en tuèrent quinze mille, le treize d\'adar, et ils ne prirent rien.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Et ils restèrent en repos le quatorze du même mois, car ils fêtèrent ce jour de repos par de grandes réjouissances.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Mais les Juifs de Suse ne cessèrent le massacre qu\'à fin du quatorze; et ils passèrent le quinze à se réjouir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'À cause de cela, les Juifs dispersés dans toutes les provinces ont coutume de fêter le quatorze d\'adar, et chacun envoie des parts à son voisin. {Mais ceux qui vivent au loin dans des grandes villes célèbrent la fête le quinze d\'Adar, en envoyant des parts à leurs voisins}.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Mardochée écrivit ces choses en un livre, et il envoya dire à tous les Juifs qui demeuraient dans le royaume d\'Artaxerxès, soit près, soit loin,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'D\'instituer ces jours comme des jours heureux, et de fêter le treize et le quatorze d\'adar.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Car, en ces deux journées, les Juifs avaient été délivrés de leurs ennemis; et le mois, qui est adar, durant lequel ils avaient passé du deuil à la joie, et des douleurs à un jour heureux, fut consacré tout entier aux jours heureux des noces et des réjouissances; et chacun envoya des parts à ses amis et aux indigents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Et les Juifs se sont conformés depuis à ce qu\'avait écrit Mardochée, leur faisant savoir:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Comme Aman, fils d\'Amadathe le Macédonien, était devenu leur ennemi; comme il avait fait un édit, et agité les sorts pour les exterminer;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Comme il était entré chez le roi, lui disant de faire pendre Mardochée; et comment tous les maux qu\'il avait essayé de faire tomber sur les Juifs étaient tombés sur lui-même, qui avait été pendu ainsi que ses fils.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'À cause de cela, ces jours furent appelés Phrurées, à cause des sorts (car, dans leur dialecte, les sorts se traduisent par Phrurées); à cause des paroles de ce livre de Mardochée, et à cause de ce qu\'ils avaient souffert à ce sujet et de ce qui leur était advenu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Et il régla les choses ainsi. Et les Juifs adoptèrent l\'usage de ces fêtes pour eux et pour leur race, et pour ceux qui se joignirent à eux pour les observer, et ils ne feront jamais autrement; et ces jours sont un mémorial gardé de générations en générations en chaque ville, chaque famille, chaque province.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Et ces jours des Phrurées, disent-ils, seront gardés en tout temps, et le mémorial ne manquera à aucune génération.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Et la reine Esther, fille d\'Aminadab, et le Juif Mardochée, écrivirent tout ce qu\'ils avaient fait pour confirmer la lettre concernant les Phrurées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Et Esther fit cela par un commandement pour toujours, et elle l\'écrivit en un mémoire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Et le roi écrivit ce qui concernait l\'empire de la terre et de la mer;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Et sa puissance, et sa valeur, et ses richesses, et sa gloire, sont décrites dans le livre des rois des Perses et des Mèdes, comme un mémorial.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Et Mardochée fut le lieutenant du roi Artaxerxès, et il fut grand dans le royaume, et il fut glorifié par les Juifs; et, aimé de tous, il exposa la suite de l\'événement à tout son peuple. Et Mardochée dit: Tout cela vient de Dieu; Car je me souviens de la vision que j\'ai eue au sujet de ces événements, et rien de ce qu\'elle annonçait n\'a manqué d\'advenir. La petite fontaine qui devint fleuve et qui fut lumière, soleil et onde abondante: c\'est Esther, c\'est elle qui est le fleuve; le roi l\'a épousée et il l\'a couronnée reine. Les deux dragons, c\'est moi et Aman. Les nations, c\'est la foule qui s\'assembla pour effacer le nom des Juifs. Et notre nation, c\'est Israël qui invoqua Dieu et fut sauvé. Et le Seigneur à protégé son peuple, et il nous a délivrés de tous ces maux, et il a fait éclater des prodiges, et il a montré des signes, ce qui n\'est jamais arrivé chez les nations. À cause de cela, il a fait deux sorts: l\'un pour son peuple, l\'autre pour les autres nations. Et les deux sorts ont comparu devant Dieu au moment et à l\'heure, le jour où il devait juger toutes les nations. Et Dieu s\'est souvenu de son peuple, et il a vengé son héritage. Et les jours d\'adar, le treize et le quatorze, seront célébrés devant Dieu par tout le peuple à jamais, par des réjouissances et des fêtes, en tout Israël. La quatrième année du règne de Ptolémée et de Cléopâtre, Dosithée, qui dit être prêtre et lévite, accompagné de Ptolémée, son fils, apporta cette lettre sur les Phrurées; et, tous les deux, déclarèrent qu\'elle avait été traduite à Jérusalem par Lysimaque, fils de Ptolémée.');
