INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 43, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 44, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 45, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 46, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 47, '');
