INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Il y avait un homme qui demeurait à Babylone, et son nom était Joakim.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Il prit une femme nommée Susanne, fille d\'Helcias, d\'une grande beauté et craignant Dieu;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'car ses parents, qui étaient justes, avaient instruit leur fille selon la loi de Moïse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Or Joakim était fort riche, et il avait un jardin près de sa maison, et les Juifs affluaient chez lui, parce qu\'il était le plus honorable de tous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'On avait établi juges cette année-là deux anciens d\'entre le peuple, dont le Maître a dit « L\'iniquité est sortie de Babylone par des vieillards qui étaient juges, qui paraissaient régir le peuple.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Ils fréquentaient la maison de Joakim, et tous ceux qui avaient des différends se rendaient auprès d\'eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'Vers le milieu du jour, lorsque le peuple s\'était retiré, Susanne entrait dans le jardin de son mari et s\'y promenait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'Les deux vieillards la voyaient chaque jour y entrer et s\'y promener, et ils conçurent pour elle une ardente passion.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Ils pervertirent leur sens et détournèrent leurs yeux pour ne pas voir le ciel et ne pas se souvenir des justes jugements de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Ils étaient donc blessés d\'amour pour elle, mais ils ne se communiquaient pas mutuellement leur souffrance,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'car ils avaient honte de révéler l\'un à l\'autre la passion qui leur faisait désirer d\'être avec elle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Ils l\'observaient chaque jour avec soin pour la voir, et ils se dirent l\'un à l\'autre:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 13, '« Allons chez nous, c\'est l\'heure du dîner ».Et ils sortirent et se séparèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 14, 'Mais étant revenus sur leurs pas, ils se rencontrèrent, et s\'étant demandé le motif de leur retour, ils s\'avouèrent leur passion; puis ils convinrent entre eux du moment où ils pourraient la trouver seule.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 15, 'Comme ils épiaient un jour convenable, il arriva que Suzanne entra dans le jardin, comme elle l\'avait fait la veille et l\'avant-veille, sans autre compagnie que deux jeunes filles; elle voulut se baigner dans le jardin, car il faisait chaud.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 16, 'Il n\'y avait là personne, sinon les deux vieillards, qui s\'étaient cachés et qui l\'épiaient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 17, 'Elle dit aux jeunes filles « Apportez-moi de l\'huile parfumée et des onguents, et fermez les portes du jardin, afin que je me baigne.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 18, 'Elles firent ce que Suzanne avait commandé et, ayant fermé la porte du jardin, elles sortirent par une porte de derrière, pour apporter ce qui leur avait été demandé; elles ne savaient pas que les vieillards étaient cachés dans le jardin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 19, 'Dès que les jeunes filles furent sorties, les deux vieillards se levèrent, coururent à Susanne et lui dirent:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 20, '« Vois, les portes du jardin sont fermées, personne ne nous aperçoit, et nous brûlons d\'amour pour toi; consens donc à notre désir et sois à nous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 21, 'Si non, nous nous porterons témoins contre toi, et nous dirons qu\'un jeune homme était avec toi, et que c\'est pour cela que tu as renvoyé les jeunes filles\'.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 22, 'Susanne soupira et dit « Du tous côtés l\'angoisse m\'environne. Si je fais cela, c\'est la mort pour moi, et si je ne le fais pas, je n\'échapperai pas de vos mains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 23, 'Mais il vaut mieux pour moi tomber entre vos mains sans avoir fait le mal que de pécher en présence du Seigneur.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 24, 'Alors Susanne jeta un grand cri, et les deux vieillards crièrent aussi contre elle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 25, 'Et l\'on d\'eux courut ouvrir les portes du jardin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 26, 'Quand les serviteurs de la maison entendirent les cris poussés dans le jardin, ils se précipitèrent par la porte de derrière pour voir ce qu\'il y avait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 27, 'Lorsque les vieillards se furent expliqués, les serviteurs eurent grande honte, parce qu\'on n\'avait jamais dit chose semblable de Susanne.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 28, 'Le lendemain, le peuple s\'étant rassemblé chez Joakim, mari de Susanne, les deux vieillards y vinrent aussi, tout remplis de pensées méchantes contre elle, afin de la faire périr.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 29, 'Ils dirent devant le peuple: « Envoyez chercher brillante, fille d\'Helcias, femme de Joakim.» Et on envoya aussitôt.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 30, 'Elle vint avec ses parents, ses fils et tous ses proches.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 31, 'Or Suzanne, avait les traits délicats et une grande beauté.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 32, 'Comme elle était voilée, les juges méchants commandèrent qu\'on lui ôtât son voile, pour se rassasier de sa beauté.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 33, 'Mais tous les siens et tous ceux qui la connaissaient versaient des larmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 34, 'Les deux vieillards, se levant au milieu du peuple, mirent leurs mains sur sa tête.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 35, 'Elle, en pleurant, regarda vers le ciel, car son cœur avait confiance dans le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 36, 'Les vieillards dirent: « Comme nous nous promenions seuls dans le jardin, elle est entrée avec deux jeunes filles et, après avoir fait fermer les portes du jardin, elle a renvoyé les jeunes filles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 37, 'Et un jeune homme qui était caché est venu à elle et a fait le mal avec elle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 38, 'Nous étions dans un coin du jardin; en voyant le crime, nous avons couru à eux, et nous les avons vus dans cette infamie.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 39, 'Nous n\'avons pu prendre le jeune homme, parce qu\'il était plus fort que nous, et qu\'ayant ouvert la porte, il s\'est échappé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 40, 'Mais elle, après l\'avoir prise, nous lui avons demandé quel était ce jeune homme, et elle n\'a pas voulu nous le dire. Voilà ce que nous attestons.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 41, 'La foule les crut, parce que c\'étaient des vieillards et des juges du peuple, et ils la condamnèrent à mort.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 42, 'Alors Susanne s\'écria à haute voix et dit: « Dieu éternel, qui connaissez ce qui est caché et qui savez toutes choses avant qu\'elles n\'arrivent,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 43, 'vous savez qu\'ils ont rendu un faux témoignage contre moi; et voici que je meurs, sans avoir rien fait de ce qu\'ils ont méchamment inventé contre moi.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 44, 'Le Seigneur entendit sa voix.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 45, 'Comme on la conduisait à la mort, Dieu éveilla l\'esprit saint d\'un jeune enfant nommé Daniel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 46, 'Il cria à haute voix « Pour moi, je suis pur du sang de cette femme!\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 47, 'Tout le peuple se tourna vers lui et lui dit « Que signifie cette parole que tu dis là?\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 48, 'Daniel, se tenant au milieu d\'eux, dit « Etes-vous donc insensés à ce point, enfants d\'Israël, de faire mourir une fille d\'Israël sans examen, sans chercher à connaître la vérité?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 49, 'Retournez au tribunal, car ils ont rendu un faux témoignage contre elle.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 50, 'Alors le peuple retourna en hâte, et les anciens dirent à Daniel « Viens, prends place au milieu de nous, et expose-nous ton avis, car Dieu t\'a donné l\'honneur de la vieillesse.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 51, 'Daniel dit au peuple « Séparez-les loin l\'un de l\'autre, et je les jugerai.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 52, 'Quand ils furent séparés l\'un de l\'autre, Daniel en appela un et lui dit « Homme vieilli dans le crime, les péchés que tu as commis autrefois sont maintenant venus sur toi,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 53, 'toi qui rendais des jugements injustes, qui condamnais les innocents et relâchais les coupables, quand le Seigneur a dit Tu ne feras pas mourir l\'innocent et le juste.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 54, 'Eh bien, si tu l\'as vue, dis sous quel arbre tu les as vus s\'entretenant ensemble». Il répondit « Sous un lentisque\'.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 55, 'Daniel dit « Justement tu dis un mensonge pour ta perte; car l\'ange de Dieu qui a déjà reçu l\'arrêt divin va te fendre par le milieu.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 56, 'Après l\'avoir renvoyé, il ordonna d\'amener l\'autre, et il lui dit « Race de Chanaan, et non de Juda, la beauté d\'une femme t\'a séduit et la passion a perverti ton cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 57, 'C\'est ainsi que vous en agissiez avec les filles d\'Israël, et elles, ayant peur de vous, vous parlaient; mais une fille de Juda n\'a pu souffrir votre iniquité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 58, 'Dis-moi donc maintenant sous quel arbre tu les as surpris s\'entretenant ensemble.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 59, 'Il dit « Sous un chêne». Daniel lui dit « Justement tu as dit, toi aussi, un mensonge pour ta perte; car l\'ange du Seigneur attend, le glaive en main, le moment de te couper par le milieu, afin de vous faire mourir.»');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 60, 'Alors toute l\'assemblée jeta un grand cri, et ils bénirent Dieu qui sauve ceux qui espèrent en lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 61, 'Puis ils s\'élevèrent contre les deux vieillards, que Daniel avait convaincus par leur propre bouche d\'avoir rendu un faux témoignage, et ils leur firent le mal qu\'eux-mêmes avaient voulu faire à leur prochain;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 62, 'afin d\'accomplir la loi de Moise, et ils les firent donc mourir, et le sang innocent fut sauvé en ce jour-là.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 63, 'Helcias et sa femme louèrent Dieu au sujet de leur fille Susanne, avec Joakim, son mari, et tous ses parents, parce qu\'il ne s\'était trouvé en elle rien de déshonnête.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 64, 'Et Daniel devint grand devant le peuple, à partir de ce jour et dans la suite des temps.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'En la troisième année du règne de Joakim, roi de Juda, Nabuchodonosor, roi de Babylone, vint à Jérusalem, et il l\'investit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Et le Seigneur lui livra le roi Joakim avec une partie des vases du temple de Dieu, et il emporta ces vases en la terre de Sennaar, où était le temple de son dieu, et il les déposa dans la maison du trésor de son dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Et le roi dit à Asphanez, chef de ses eunuques, de lui amener quelques-uns des fils des captifs d\'Israël de la race royale et des princes,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Jeunes gens sans infirmité, beaux de formes, initiés à toute sagesse, savants, doués de prudence et dignes d\'habiter le palais en présence du roi, et il lui ordonna de les instruire dans la langue et les lettres des Chaldéens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Et le roi ordonna que chaque jour on les nourrit durant trois ans des mets de sa table royale, et du vin dont lui-même buvait, et qu\'ensuite ils se tinssent en présence du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Et parmi eux se trouvèrent des fils de Juda, Daniel, Ananias, Azarias et Misaël.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Et le chef des eunuques leur donna des noms: il appela Daniel Baltasar, et Ananias Sidrach, et Misaël Misach, et Azarias Abdénago.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Mais Daniel eut à cœur de ne point se souiller des mets de la table du roi, ni du vin dont il faisait usage, et il pria le chef des eunuques de lui permettre de ne s\'en point souiller.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Et Dieu accorda que Daniel obtînt les bonnes grâces et la compassion du chef des eunuques.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Et le chef des eunuques dit à Daniel: J\'ai peur que le roi, mon maître, après m\'avoir donné des ordres pour vos aliments et votre breuvage, ne vous voie peut-être mauvais visage, en comparaison des jeunes gens de votre âge; et vous me feriez condamner à mort par le roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Et Daniel dit à Amelsad, à qui le chef des eunuques avait confié la garde de Daniel, d\'Ananias, de Misaël et d\'Azarias:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Éprouve tes serviteurs pendant dix jours, et fais nous donner quelques graines que nous mangerons; et nous boirons de l\'eau.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Puis regarde notre visage et le visage des jeunes gens qui se seront nourris de la table du roi; et selon ce que tu auras vu, agis à l\'égard de tes serviteurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Et il les exauça, et il les éprouva pendant dix jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Et au bout des dix jours il fut reconnu qu\'ils avaient le visage meilleur et les chairs plus fermes que les jeunes gens nourris de la table du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Alors Amelsad prit pour lui leurs mets et leur vin, et il leur donna des graines.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Et Dieu doua ces quatre jeunes gens de l\'intelligence et du savoir, dans tous les exercices; de la sagesse et des lettres; et Daniel sut interpréter les visions et les songes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Et à la fin des jours que le roi avait fixés pour qu\'on les lui amenât, le chef des eunuques les introduisit devant Nabuchodonosor.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Et le roi leur parla, et, parmi tous ces jeunes gens, il ne s\'en trouva point de comparables à Daniel, Ananias, Misaël et Azarias; et ils demeurèrent en présence du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Et dans toutes les questions de sagesse et de science sur lesquelles le roi les interrogea, il les reconnut dix fois plus habiles que les devins et les mages qui étaient en tout son royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 21, 'Et Daniel vécut ainsi jusqu\'à la première année du règne de Cyrus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'En la seconde année de son règne, Nabuchodonosor eut un songe, et son esprit en fut saisi de stupeur, et le sommeil s\'éloigna de lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Et le roi ordonna de convoquer les devins et les mages, les sorciers et les Chaldéens, pour interpréter le songe qu\'il avait eu. Ils vinrent donc, et ils comparurent devant le roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Et le roi leur dit: J\'ai eu un songe, et mon esprit en a été frappé de stupeur au point de ne rien connaître à ce songe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Et les Chaldéens dirent au roi en langue syriaque: Ô roi, vis à jamais, dis ton songe à tes serviteurs, et nous t\'en donnerons l\'interprétation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Le roi répondit aux Chaldéens: Les paroles se sont éloignées de moi; si vous ne me faites connaître le songe et son interprétation, vous serez mis à mort, et vos maisons seront pillées.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Mais si vous me faites connaître le songe et son interprétation, vous recevrez de moi des dons, des présents et de grands honneurs; seulement faites-moi connaître mon songe et son interprétation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Ils répondirent une seconde fois, et dirent: Que le roi dise à ses serviteurs quel songe il a eu, et nous lui en ferons connaître l\'interprétation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Et le roi reprit, et dit: En vérité, je sais, moi, que vous voulez gagner du temps, parce que vous voyez que les paroles du songe se sont éloignées de moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Si donc vous ne me dites pas mon songe, je sais que vous êtes convenus entre vous de me dire des paroles fausses et altérées, jusqu\'à ce que le temps se soit écoulé. Dites-moi mon songe, et alors je saurai que vous m\'en ferez connaître aussi l\'interprétation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Les Chaldéens répondirent devant le roi, et ils dirent: Il n\'est point d\'homme sur la terre qui puisse faire connaître cette parole au roi, de même qu\'il n\'est point de grand roi ni de prince qui fasse pareille question à un devin, ou mage, ou Chaldéen.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Car la parole sur laquelle le roi nous questionne est grave, et nul autre que nous ne pourra la découvrir au roi, sinon des dieux dont la demeure n\'est pas en la chair.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Alors le roi, plein de fureur et d\'indignation, ordonna que l\'on mît à mort tous les sages de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Et sa sentence s\'exécuta, et les sages furent mis à mort, et on chercha Daniel et ses amis pour les tuer aussi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Alors Daniel parla avec réflexion et sagesse à Arioch, chef des cuisines du roi, qui était sorti pour mettre à mort les sages de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Ministre du roi, lui dit-il, à quel sujet cet ordre impitoyable est-il sorti de la bouche du roi? Et Arioch fit connaître l\'affaire à Daniel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 16, 'Et Daniel demanda au roi de lui accorder du temps, promettant de lui faire connaître l\'interprétation du songe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 17, 'Et Daniel rentra dans sa maison, et il raconta l\'affaire à Ananias, Misaël, Azarias, ses amis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 18, 'Et ils implorèrent les miséricordes du Dieu du ciel sur ce mystère, afin que ni Daniel ni ses amis ne périssent avec le reste des sages de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 19, 'Alors à Daniel, en une vision nocturne, le mystère fut révélé, et il bénit le Dieu du ciel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 20, 'Disant: Que le nom du Seigneur soit béni, maintenant et dans tous les siècles, parce que toute sagesse et toute intelligence lui appartiennent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 21, 'C\'est lui qui change les heures et les temps, lui qui place et déplace les rois, lui qui donne la sagesse aux sages, et la prudence aux prudents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 22, 'C\'est lui qui révèle les choses profondes et cachées, lui qui sait ce qui est dans les ténèbres; et la lumière est avec lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 23, 'Vous donc, Dieu de mes pères, je vous rends hommage et je vous loue, parce que vous m\'avez donné la force et la sagesse, que vous m\'avez appris ce que nous vous avons demandé, et que vous m\'avez révélé la vision du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 24, 'Et Daniel alla trouver Arioch, que le roi avait chargé de mettre à mort les sages de Babylone, et il lui dit: N\'exécute pas les sages de Babylone; mais introduis-moi en présence du roi, et je donnerai au roi l\'interprétation du songe qu\'il a eu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 25, 'Aussitôt Arioch s\'empressa d\'introduire Daniel en présence du roi, et il lui dit: J\'ai trouvé un homme des fils des captifs de la Judée, qui donnera au roi l\'interprétation du songe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 26, 'Et le roi prit la parole, et il dit à Daniel, que l\'on nommait Baltasar: Pourras-tu me faire connaître le songe que j\'ai eu et son interprétation?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 27, 'Et Daniel répondit devant le roi, disant: Le mystère que le roi me demande, il n\'appartient ni aux juges, ni aux mages, ni aux devins, ni aux augures, de le révéler au roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 28, 'Mais c\'est Dieu qui, dans le ciel, révèle tous les mystères, et qui a fait connaître au roi Nabuchodonosor ce qui doit arriver dans les derniers jours. Ton songe et les visions de ta tête sur ta couche, les voici:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 29, 'Ô roi, tes pensées sur ta couche s\'étaient portées sur ce qui doit arriver après le moment présent; et Celui qui révèle les mystères t\'a fait connaître ce qui doit arriver');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 30, 'Et c\'est à moi qu\'il a révélé ce mystère, non à cause de la sagesse qui est en moi, ni dans les autres vivants; mais afin que je te découvre, ô roi, l\'interprétation de ton songe, et que tu connaisses les pensées de ton cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 31, 'Toi donc, ô roi, tu regardais; et voilà qu\'une statue se tint debout devant ta face; cette statue était grande, et son aspect terrible.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 32, 'C\'était une statue dont la tête était d\'or pur, les mains, la poitrine et les bras d\'argent, le ventre et les cuisses d\'airain;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 33, 'Les jambes de fer, et les pieds partie de fer, partie d\'argile.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 34, 'Tu regardais, quand une pierre détachée de la montagne, sans qu\'une main la poussât, vint frapper la statue à ses pieds de fer et d\'argile, et à la fin elle les broya.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 35, 'Alors furent broyés à la fois l\'argile, le fer, l\'airain, l\'argent et l\'or, et ils devinrent comme la poudre qui l\'été s\'élève au-dessus d\'une aire; et un souffle violent les emporta, et l\'on n\'en trouva plus la place. Et la pierre qui avait frappé la statue devint une grande montagne, et elle couvrit toute la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 36, 'Voilà ton songe, et nous allons en dire l\'interprétation devant le roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 37, 'Ô roi, tu es le roi des rois, à qui le Dieu du ciel a donné un empire puissant, fort et glorieux,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 38, 'En tout lieu où demeurent les fils des hommes; toi à qui il a soumis les bêtes fauves des champs, et les oiseaux du ciel, et les poissons de la mer; toi qu\'il a établi maître de toutes choses, tu es la tête d\'or.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 39, 'Et le royaume qui s\'élèvera après toi sera moindre que le tien; puis viendra un troisième royaume, qui sera d\'airain, et qui commandera à toute la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 40, 'Puis viendra un quatrième royaume qui sera fort comme le fer: de même que le fer broie et dompte toutes choses, il broiera et domptera toutes choses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 41, 'Et comme tu as vu les pieds et les doigts partie de fer, et partie d\'argile, ce royaume sera divisé, et il sera détaché de ses racines de fer, comme tu as vu le fer mêlé à l\'argile.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 42, 'Et les doigts des pieds étant partie de fer, partie d\'argile, une part de ce royaume sera forte, une autre sera broyée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 43, 'Et de même que tu as vu le fer confondu avec l\'argile, de même il y aura des mélanges dans la race des hommes; mais ce ne sera pas un tout parfaitement uni, pas plus qu\'il n\'y a d\'alliage entre l\'argile et le fer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 44, 'Et du temps de ces rois le Dieu du ciel suscitera un royaume qui ne périra point dans les siècles; et jamais son royaume ne sera subjugué par un autre peuple; et son royaume nivellera et vannera tous les royaumes, et il se maintiendra durant tous les siècles;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 45, 'Comme tu as vu la pierre se détacher de la montagne, sans qu\'une main la poussât, et broyer l\'argile, le fer, l\'airain, l\'argent et l\'or. C\'est ainsi que le grand Dieu a fait connaître au roi ce qui doit arriver après ces temps. Et véritable est le songe, et l\'interprétation digne de foi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 46, 'Alors le roi Nabuchodonosor tomba la face contre terre, et il adora Daniel, et il ordonna qu\'on lui offrît des oblations et de l\'encens.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 47, 'Et le roi, prenant la parole, dit à Daniel: En vérité, votre Dieu seul est le Dieu des dieux et le Seigneur des rois; c\'est lui qui révèle les mystères; car tu n\'aurais pu révéler celui-ci.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 48, 'Et le roi glorifia Daniel; il lui fit de grands et magnifiques présents, et il le mit à la tête de toute la province de Babylone, et il l\'institua chef des satrapes et de tous les sages de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 49, 'Et sur la demande de Daniel le roi chargea de toutes les affaires de la province de Babylone Sidrach, Misach et Abdénago, et Daniel resta dans le palais du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'La dix-huitième année de son règne, Nabuchodonosor fit faire une statue d\'or, haute de soixante coudées, sur six d\'épaisseur, et il l\'érigea en la plaine de Déira, dans la province de Babylone.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Et il convoqua les grands, les généraux et les gouverneurs, les rois, les tyrans et les dignitaires, et tous les chefs des provinces pour venir à l\'inauguration de la statue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Et les gouverneurs, les grands, les généraux, les rois, les principaux tyrans, les dignitaires et les chefs des provinces se rassemblèrent pour l\'inauguration de la statue qu\'avait érigée le roi Nabuchodonosor, et ils se placèrent debout devant la statue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Et le héraut proclama à haute voix: Ceci vous et prescrit, peuples, tribus, hommes de toutes langues:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'À l\'instant où vous entendrez le son de la trompette et de la flûte, de la cithare, de la harpe et du psaltérion, et des instruments de toute sorte, tombez la face contre terre, et adorez la statue d\'or que le roi Nabuchodonosor a érigée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Et celui qui n\'adorera pas, en tombant à genoux, sera jeté aussitôt dans la fournaise ardente où le feu est allumé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Or ceci advint: dès que les peuples entendirent le son de la trompette et de la flûte, de la cithare, de la harpe et du psaltérion, et des instruments de toute sorte, les peuples tombèrent la face contre terre, et ils adorèrent la statue d\'or que le roi Nabuchodonosor avait érigée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Alors vinrent des hommes de la Chaldée et ils accusèrent les Juifs');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Devant le roi, disant: Ô roi, vis à jamais!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Ô toi, tu as fait une ordonnance, disant: Que tout homme qui entendra le son de la trompette et de la flûte, de la cithare, de la harpe et du psaltérion, et des instruments de toute sorte,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Et qui ne tombera pas la face contre terre pour adorer la statue d\'or, soit jeté dans la fournaise ardente où le feu est allumé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Or il y a des hommes, des Juifs, que tu as chargés de toutes les affaires de la province de Babylone, Sidrach, Misach et Abdénago, qui n\'ont point obéi à ton ordre, ô roi; tes dieux, ils ne les honorent pas; et la statue d\'or que tu as érigée, ils ne l\'adorent point.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Alors Nabuchodonosor, plein de colère et de fureur, commanda de lui amener Sidrach, Misach et Abdénago, et on les amena en présence du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Et Nabuchodonosor prit la parole, et leur dit: Est-il vrai, Sidrach, Misach et Abdénago, que vous ne servez point mes dieux, et que vous n\'adorez pas la statue d\'or que j\'ai élevée?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Maintenant donc, si vous y êtes disposés, aussitôt que vous entendrez le son de la trompette, de la flûte et de la cithare, de la harpe et du psaltérion, et le concert des instruments de toute sorte, tombez la face contre terre, et adorez la statue d\'or que j\'ai faite. Que si vous ne l\'adorez pas, à l\'instant même vous serez jetés dans la fournaise ardente, où le feu est allumé; et quel est le Dieu qui vous tirera de mes mains?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Sidrach, Misach et Abdénago répondirent au roi Nabuchodonosor, disant: Il n\'est pas nécessaire que nous te fassions une réponse à cette question.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 17, 'Car notre Dieu qui est au ciel, le Dieu que nous servons, peut nous tirer de la fournaise ardente et nous sauver, ô roi, d\'entre tes mains.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 18, 'Et quand même il ne le ferait pas, sache, ô roi, que tes dieux nous ne les servons pas, et que la statue d\'or que tu as élevée, nous ne l\'adorons point.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 19, 'Alors Nabuchodonosor, plein de colère, changea de visage envers Sidrach, Misach et Abdénago, et il ordonna de rendre sept fois plus ardent le feu de la fournaise, jusqu\'à ce qu\'enfin il ne fût plus qu\'un brasier.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 20, 'Et il ordonna à des hommes robustes de mettre des entraves à Sidrach, Misach et Abdénago, puis de les jeter dans la fournaise ardente.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 21, 'Aussitôt ces jeunes gens furent enchaînés sans qu\'on leur ôtât ni leurs hauts-de-chausses, ni leurs tiares, ni leurs chaussures, et ils furent jetés au milieu des flammes de la fournaise;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 22, 'Car la parole du roi était pressante, et la fournaise était plus ardente que jamais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 23, 'Et Sidrach, Misach et Abdénago tombèrent tous trois enchaînés au milieu des flammes de la fournaise embrasée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 24, 'Et ils marchèrent au milieu des flammes, chantant Dieu et bénissant le Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 25, 'Et Azarias, debout, pria ainsi, et ayant ouvert la bouche au milieu des flammes:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 26, 'Béni soyez-vous, dit-il, Seigneur Dieu de nos pères, soyez loué; que votre nom soit glorifié dans tous les siècles!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 27, 'Car vous êtes juste en toutes les choses que vous avez faites; toutes vos œuvres sont vraies, vos voies sont droites, et tous vos jugements sont vérité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 28, 'Et vous avez fait des jugements équitables dans tous les maux que vous avez amenés contre nous et contre Jérusalem, ville sainte de nos pères, puisque vous avez fait toutes ces choses en vérité et en justice, à cause de nos péchés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 29, 'Car nous avons péché, nous nous sommes égarés en nous éloignant de vous, et nous avons failli en toutes choses. Nous avons été indociles à vos commandements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 30, 'Nous ne les avons pas observés; nous n\'avons point fait comme vous nous l\'aviez prescrit pour que nous fussions heureux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 31, 'Et tout ce que vous avez amené contre nous, tout ce que vous nous avez fait, vous l\'avez fait en justice et en vérité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 32, 'Et vous nous avez livrés aux mains d\'ennemis pervers, d\'infidèles abominables, d\'un roi inique et le plus méchant de toute la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 33, 'Et maintenant il ne nous est plus permis d\'ouvrir la bouche; nous sommes un sujet de confusion et d\'opprobre pour ceux qui vous servent et vous adorent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 34, 'Pour l\'amour de votre nom, ne nous livrez pas à jamais; ne rompez pas votre alliance.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 35, 'Ne détournez pas de nous votre miséricorde, en considération d\'Abraham, votre bien-aimé, d\'Isaac, votre serviteur, de Jacob, votre saint,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 36, 'À qui vous avez promis de multiplier leur postérité autant que les étoiles du ciel et que le sable du rivage de la mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 37, 'Seigneur, nous sommes les moindres en nombre, parmi toutes les nations, et nous sommes humiliés aujourd\'hui dans toute la terre, à cause de nos péchés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 38, 'Et dans le temps présent il n\'y a plus pour nous ni chef, ni prophète, ni roi, ni holocaustes, ni sacrifices, ni oblations, ni encens, ni de lieu où nous puissions porter les prémices de nos fruits en votre présence, et obtenir votre miséricorde.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 39, 'Mais l\'âme contrite et l\'esprit humilié, puissions-nous être accueillis de vous, comme un holocauste de béliers et de taureaux, comme l\'oblation de dix mille agneaux gras,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 40, 'Et qu\'il arrive jusqu\'à vous! car ceux qui ont confiance en vous ne seront jamais confondus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 41, 'Et maintenant, nous nous consacrons à vous de tout notre cœur, nous vous craignons, et nous cherchons votre visage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 42, 'Ne nous couvrez pas de honte; mais traitez-nous selon votre mansuétude et selon l\'abondance de voire miséricorde.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 43, 'Délivrez-nous par un de vos prodiges, et donnez la gloire à votre nom, ô Seigneur!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 44, 'Et qu\'ils tremblent tous ceux qui font connaître ces maux à vos serviteurs; qu\'ils soient humiliés par votre toute-puissance, et que toute leur force soit brisée');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 45, 'Qu\'ils sachent que vous êtes le Seigneur, le seul Dieu, le Dieu de gloire qui règne sur toute la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 46, 'Cependant les serviteurs du roi qui les avaient jetés dans la fournaise ne cessaient pas d\'y brûler du naphte et de la poix, des étoupes et du sarment.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 47, 'Et la flamme s\'élevait au-dessus de la fournaise à quarante-neuf coudées;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 48, 'Et elle se promena, et brûla ceux des Chaldéens qu\'elle trouva autour de la fournaise.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 49, 'Et l\'ange du Seigneur descendit en même temps vers ceux qui étaient dans la fournaise avec Azarias, et il secoua la flamme hors de la fournaise.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 50, 'Et il fit souffler au milieu de la fournaise comme un vent chargé de rosée; et le feu ne les atteignit aucunement, et il ne leur fit point de mal, et même il ne les incommoda point.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 51, 'Alors tous les trois se mirent à chanter d\'une seule voix, et ils glorifièrent Dieu, et ils le bénirent du fond de la fournaise, disant:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 52, 'Soyez béni, Seigneur Dieu de nos pères; soyez loué et infiniment exalté dans tous les siècles! Que béni soit votre nom saint et glorieux; qu\'il soit célébré, qu\'il soit exalté dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 53, 'Vous êtes béni dans le temple de votre gloire sainte; vous êtes au-dessus de toute louange et de toute gloire dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 54, 'Vous êtes béni sur le trône de votre royauté; vous êtes infiniment loué et exalté dans tous les siècles!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 55, 'Vous êtes béni, vous qui regardez les abîmes, vous qui êtes assis sur les chérubins; vous êtes infiniment loué et exalté dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 56, 'Vous êtes béni dans le firmament du ciel; vous êtes chanté et glorifié dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 57, 'Œuvres du Seigneur, bénissez toutes le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 58, 'Anges du Seigneur, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 59, 'Cieux, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 60, 'Eaux de la terre, eaux du ciel, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 61, 'Armée du Seigneur, bénis tout entière le Seigneur; chante-le, exalte-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 62, 'Soleil et lune, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 63, 'Étoiles du ciel, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 64, 'Pluie et rosée, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 65, 'Vents, bénissez tous le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 66, 'Feu et chaleur, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 67, 'Froidures (de l\'hiver) et canicules (de l\'été), bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 68, 'Rosées et neiges, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 69, 'Glace et froid, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 70, 'Gelées et neiges, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 71, 'Nuits et jours, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 72, 'Lumière et ténèbres, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 73, 'Éclairs et nuées, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 74, 'Que la terre bénisse le Seigneur; qu\'elle le chante, qu\'elle l\'exalte infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 75, 'Monts et collines, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 76, 'Plantes de la terre, bénissez toutes le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 77, 'Fontaines, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 78, 'Mer et fleuves, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 79, 'Monstres marins qui vous mouvez dans les ondes, bénissez tous le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 80, 'Oiseaux du ciel, bénissez tous le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 81, 'Bêtes fauves et troupeaux, bénissez tous le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 82, 'Fils des hommes, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 83, 'Israël, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 84, 'Prêtres, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 85, 'Serviteurs, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 86, 'Esprits et âmes des justes, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 87, 'Saints et humbles de cœur, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 88, 'Ananias, Azarias, Misaël, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles, parce qu\'il nous a tirés des enfers, qu\'il nous a sauvés des mains de la mort, délivrés du milieu de la fournaise en flammes, et protégés au milieu du feu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 89, 'Rendez gloire ensemble au Seigneur, parce qu\'il est bon, parce que sa miséricorde est éternelle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 90, 'Hommes pieux, bénissez le Seigneur, Dieu des dieux; chantez-le et rendez- lui gloire, parce que sa miséricorde est éternelle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 91, 'Et Nabuchodonosor les entendit chanter des hymnes, et il fut frappé d\'étonnement, et il se leva précipitamment, et il dit aux grands qui l\'entouraient: N\'avons-nous pas jeté au milieu du feu trois hommes enchaînés? et ils dirent au roi: Oui, seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 92, 'Et le roi dit: Et moi, je vois quatre hommes sans liens, se promenant au milieu des flammes, et la destruction n\'est pas avec eux, et l\'aspect du quatrième ressemble à un fils de Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 93, 'Alors Nabuchodonosor s\'approcha de la porte de la fournaise ardente, et il dit: Sidrach, Misach, Abdénago, serviteurs du Dieu tout-puissant, sortez et venez! Et Sidrach, Misach et Abdénago sortirent du milieu des flammes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 94, 'Et les satrapes, et les généraux, et les gouverneurs et les lieutenants du roi se rassemblèrent, et ils virent ces hommes sur qui le feu n\'avait eu nulle puissance en leur corps; pas un cheveu de leur tête n\'était brûlé; leur vêtement n\'était point altéré, et nulle odeur de feu n\'était en eux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 95, 'Et le roi Nabuchodonosor prit la parole, et il dit: Béni soit le Dieu de Sidrach, de Misach et d\'Abdénago, qui a envoyé son ange, et délivré ses serviteurs, parce qu\'ils avaient eu confiance eu lui; ils désobéirent à la parole du roi, et ils abandonnèrent leurs corps à la flamme, pour ne point adorer ni servir d\'autre dieu que leur Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 96, 'Et moi je proclame ce décret: Tout peuple, toute tribu, tout homme, de quelque langue qu\'il soit, qui profèrera un blasphème contre le Dieu de Sidrach, de Misach et d\'Abdénago, sera exterminé; ses maisons seront livrées au pillage; parce qu\'il n\'est point d\'autre Dieu qui puisse sauver ainsi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 97, 'Ensuite le roi rétablit Sidrach, Misach et Abdénago à la tête de la province de Babylone; et il les éleva en honneur, et les jugea dignes de commander à tous les Juifs qui étaient dans son royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 98, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 99, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 100, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Le roi Nabuchodonosor dit à tous les peuples, à toutes les tribus, à tous les hommes de langues diverses: Que la paix se multiplie parmi vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Les signes et les prodiges que vient d\'accomplir devant moi le Dieu très- haut, il me plaît de vous annoncer en personne');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Combien ils sont grands et irrésistibles; son royaume est le royaume éternel, et sa puissance s\'étend de génération en génération.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Moi, Nabuchodonosor, comme j\'étais en paix et florissant dans mon palais,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'J\'eus un songe, et il m\'effraya, et je fus troublé sur ma couche, et les visions de ma tête me troublèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Et, de moi-même, je donnai ordre d\'amener en ma présence tous les sages de Babylone, et qu\'ils me fissent connaître l\'interprétation de mon songe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Et les devins et les mages, les sorciers et les Chaldéens arrivèrent, et je dis mon songe devant eux, et ils ne m\'en firent pas connaître l\'interprétation;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Jusqu\'à ce que vint Daniel, que l\'on nommait Baltasar, selon le nom de mon dieu, et qui avait en lui l\'Esprit-Saint de Dieu, et je lui dis:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Baltasar, comme chef des devins, je sais que l\'Esprit-Saint de Dieu est en toi, et que nul mystère pour toi n\'est impénétrable; écoute donc la vision de mon songe, et dis-m\'en l\'interprétation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Je regardais sur ma couche, et voilà qu\'un arbre était au milieu de la terre, et sa hauteur était grande.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Il crût encore et se fortifia, et sa cime arrivait jusqu\'au ciel, et son tronc jusqu\'aux extrémités de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Ses feuilles étaient belles, et ses fruits abondants; et l\'aliment de tous les êtres se trouvait en lui; sous son ombre s\'abritaient les bêtes sauvages, et sur ses rameaux les oiseaux du ciel faisaient leurs nids, et de lui toute chair se nourrissait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'J\'étais attentif sur ma couche à cette vision de la nuit, et voilà qu\'un veillant et un saint descendit des cieux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Et, parlant à haute voix, il dit: Abattez l\'arbre, arrachez ses rameaux, secouez ses feuilles, et dispersez ses fruits; que les bêtes soient chassées de dessous lui, et les oiseaux du ciel de ses branches.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Cependant laissez en terre la souche de ses racines; quant à lui, qu\'il reste étendu en des chaînes de fer et d\'airain, parmi l\'herbe qui l\'entoure, à la rosée du ciel; et qu\'avec les bêtes il ait sa part de l\'herbe de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Son cœur deviendra différent du cœur des hommes; et un cœur de bête lui sera donné; et sept fois les temps changeront sur lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 17, 'Telle est la sentence du veillant et la parole des saints, afin que les vivants sachent que le Seigneur est le dominateur du royaume des hommes, et qu\'il le donne à qui bon lui semblera, et qu\'il élèvera pour le gouverner celui qui est en mépris parmi les hommes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 18, 'Tel est le songe que j\'ai eu, moi, le roi Nabuchodonosor, et toi, Baltasar, dis-m\'en l\'interprétation; car nul des sages de mon royaume ne peut me la donner; mais toi, Daniel, tu le peux, parce que l\'Esprit-Saint de Dieu est en toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 19, 'Alors Daniel, surnommé Baltasar, réfléchit environ une heure, et ses pensées le troublèrent. Enfin Baltasar répondit: Seigneur, dit-il, que ton songe soit pour ceux qui te haïssent, et son interprétation pour tes ennemis!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 20, 'L\'arbre que tu as vu grand et fort, dont la cime allait au ciel, et le tronc sur toute la terre;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 21, 'Dont les feuilles étaient florissantes et les fruits abondants, en qui se trouvait l\'aliment de tous, et sous lequel s\'abritaient les bêtes sauvages, tandis que les oiseaux du ciel faisaient leur nid dans ses rameaux;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 22, 'Cet arbre, ô roi, c\'est toi-même; car tu as grandi et tu t\'es fortifié, et ta grandeur n\'a cessé de croître, et elle est allée jusqu\'au ciel, et ta domination jusqu\'aux extrémités de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 23, 'Or quand le roi a vu le veillant et le saint descendre du ciel, et que le saint a dit: Arrachez l\'arbre, détruisez-le, mais laissez en terre la souche de ses racines; quant à lui, qu\'il reste étendu en des chaînes de fer et d\'airain, parmi l\'herbe qui l\'entoure, exposé à la rosée du ciel, et qu\'il partage avec les bêtes l\'herbe des champs, jusqu\'à ce que les temps aient changé sept fois sur lui:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 24, 'Voici ce que cela signifie, ô roi, et c\'est la sentence du Très-Haut, qui d\'avance vient avertir le roi mon maître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 25, 'On t\'exclura du commerce des hommes, et ta demeure sera parmi les bêtes sauvages, et l\'on te donnera ta part de fourrage comme à un bœuf, et tu passeras les nuits à la rosée du ciel, et les temps changeront sept fois sur toi, jusqu\'à ce que tu reconnaisses que le Très Haut est le maître du royaume des hommes, et qu\'il le donne à qui bon lui semble.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 26, 'Et puisqu\'il a été dit: Laissez en terre la souche des racines de l\'arbre, ta royauté subsistera, après que tu auras reconnu la puissance du ciel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 27, 'C\'est pourquoi, ô roi, que mon conseil te soit agréable; rachète tes péchés par des aumônes, et tes iniquités par la compassion pour les indigents, et Dieu peut-être sera longanime à tes offenses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 28, 'Or les choses suivantes arrivèrent au roi Nabuchodonosor:');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 29, 'Après le douzième mois, comme il se promenait dans son palais royal, en Babylone,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 30, 'Le roi prit la parole, et dit: N\'est-ce point là Babylone la grande, que j\'ai bâtie pour être ma résidence royale, dans ma force et ma puissance, en l\'honneur de ma gloire?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 31, 'Cette parole était encore dans la bouche du roi, quand une voix vint du ciel, disant: À toi, roi Nabuchodonosor, il est dit: Ton royaume t\'échappe.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 32, 'On va te chasser loin des hommes, et ta demeure sera parmi les bêtes sauvages; on te donnera du foin comme à un bœuf, et les temps changeront sept fois sur toi, jusqu\'à ce que tu reconnaisses que le Très-Haut est le maître du royaume des hommes, et qu\'il le donnera à qui bon lui semble.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 33, 'À l\'heure même, cette parole sur Nabuchodonosor s\'accomplit: il fut chassé loin des hommes, il mangea de l\'herbe comme un bœuf, et son corps fut baigné par la rosée du ciel, jusqu\'à ce que ses cheveux eussent crû comme la crinière d\'un lion, et ses ongles comme les griffes des oiseaux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 34, 'Et à la fin des jours moi, Nabuchodonosor, je levai les yeux au ciel, et les pensées me revinrent, et je bénis le Très-Haut, et je louai l\'Éternel, et je lui rendis gloire, parce que sa puissance est inébranlable, et son royaume pour toutes les générations.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 35, 'Et tous ceux qui habitent la terre sont comptés pour rien. En l\'armée du ciel et parmi les habitants de la terre, il fait à sa volonté, et nul ne peut résister à sa puissance, ni lui dire: Qu\'avez-vous fait?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 36, 'Au même instant les pensées me revinrent, et je rentrai dans les honneurs de ma royauté, et ma forme me fut rendue, et mes princes et mes grands me recherchèrent, et une plus grande magnificence me fut rendue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 37, 'Maintenant donc, moi, Nabuchodonosor, je louerai et j\'exalterai, et je glorifierai le Roi du ciel, parce que toutes ses œuvres sont vraies, que ses sentiers sont la justice, et qu\'il est en son pouvoir d\'humilier tous ceux qui marchent dans leur orgueil.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Le roi Baltasar offrit un magnifique repas à ses grands au nombre de mille, et devant les mille convives il y avait du vin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Et Balthasar buvait, et dans l\'ivresse du vin il dit que l\'on apportât les vases d\'or et d\'argent enlevés par Nabuchodonosor son père au temple de Jérusalem, et que le roi et ses grands, ses concubines et ses femmes, bussent dans ces vases.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Et l\'on apporta les vases d\'or et d\'argent que l\'on avait rapportés du temple de Jérusalem, et le roi et ses grands, ses concubines et ses femmes burent dans ces vases.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Ils burent du vin, et ils louèrent leurs dieux d\'or et d\'argent, d\'airain, de fer, de pierre et de bois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Au même instant apparurent des doigts d\'homme, et ils écrivirent devant le luminaire sur l\'enduit du mur du palais du roi, et le roi suivait du regard le mouvement des phalanges de la main qui écrivait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Alors le roi changea de visage, et ses pensées le troublèrent, et la ceinture de ses reins se dénoua, ses genoux s\'entre-choquèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Et le roi, criant de toute sa force, ordonna d\'amener les mages, les Chaldéens et les sorciers. Et il dit aux sages de Babylone: Celui qui lira ce qui est écrit, et qui m\'en fera connaître l\'interprétation, sera revêtu de pourpre, et il aura autour du cou un collier d\'or, et dans mon royaume il commandera le troisième après moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Et tous les sages du roi s\'avancèrent, et ils ne purent lire ce qui était écrit ni en donner au roi l\'interprétation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Et le roi Baltasar fut troublé, et il changea de visage, et ses grands furent troublés comme lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Et la reine entra dans la salle du festin, et elle dit: Roi, vis à jamais, que tes pensées ne se troublent pas, et ne change pas de visage!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Il est dans ton royaume un homme en qui est l\'Esprit de Dieu; et du temps de ton père la vigilance et la sagesse furent trouvées en lui, et le roi Nabuchodonosor ton père le fit chef des devins, des mages, des Chaldéens et des sorciers,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Parce que l\'esprit était supérieur en lui, et que la prudence et la sagesse étaient en lui pour interpréter les songes, pour répondre aux questions difficiles, pour dénouer les choses inextricables; c\'est Daniel, et ton père l\'appelait Baltasar; maintenant donc, qu\'on l\'appelle, et il te fera connaître son interprétation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Alors Daniel fut introduit devant le roi, et le roi dit à Daniel: Es-tu Daniel, l\'un des fils des captifs de la Judée qu\'a transportés mon père?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'J\'ai oui dire que l\'Esprit de Dieu est en toi, et que la vigilance, l\'intelligence et une sagesse supérieure ont été trouvées en toi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Or maintenant les sages, les mages, les sorciers sont venus devant moi, pour lire cette écriture, et m\'en faire connaître l\'interprétation; et ils n\'ont pu me rien dire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Et moi, j\'ai appris que tu peux interpréter les jugements; si donc tu peux lire cette écriture et me l\'interpréter, tu seras revêtu de pourpre, tu auras un collier d\'or autour du cou, et tu commanderas dans mon royaume, le troisième après moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Et Daniel dit en présence du roi: Que tes présents te restent, donne à un autre les dons de ton palais; pour moi, je te lirai ce qui est écrit, et je t\'en ferai connaître l\'interprétation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Roi, le Dieu très-haut a donné à Nabuchodonosor ton père la royauté et la magnificence, les honneurs et la gloire.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Et devant la grandeur que Dieu lui avait donnée, les peuples, les tribus, les hommes de toutes langues étaient tremblants et pleins de crainte devant son visage; ceux d\'entre eux qu\'il voulait tuer, il les tuait; ceux qu\'il voulait frapper, il les frappait; ceux qu\'il voulait glorifier, il les glorifiait; et ceux qu\'il voulait humilier, il les humiliait.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Et quand son cœur se fut élevé, et que son esprit se fut endurci dans son orgueil, il fut précipité du trône, et ses honneurs lui furent enlevés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Et il fut chassé loin des hommes, et un cœur lui fut donné comme aux bêtes, et sa demeure fut parmi les ânes sauvages; on lui donna sa part de fourrage comme à un bœuf, et son corps fut baigné par la rosée du ciel, jusqu\'à ce qu\'il eût reconnu que le Dieu très-haut est le maître du royaume des hommes, et qu\'il le donne à qui bon lui semble.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Et toi donc, son fils Baltasar, tu n\'as pas non plus humilié ton cœur devant Dieu: ne sais-tu point toutes ces choses?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Tu t\'es enorgueilli contre le Seigneur Dieu du ciel, et l\'on a apporté devant toi les vases de son temple; et toi et tes grands, tes concubines et tes femmes, vous avez bu du vin dans ces vases; et tu as loué les dieux d\'or et d\'argent, d\'airain, de fer, de pierre et de bois, qui ne voient, n\'entendent ni ne comprennent; et le Dieu qui tient en sa main ton souffle et toutes tes voies, tu ne l\'as point glorifié.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'C\'est pourquoi il a envoyé de devant lui les doigts de cette main, et lui a ordonné de tracer cette inscription.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Or, cette inscription, la voici: Mané, Thécel, Pharès.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 26, 'Et voici l\'interprétation de ces paroles: Mané, Dieu a mesuré ton règne, et en a marqué la fin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 27, 'Thécel, ta royauté a été placée sur la balance, et elle a été trouvée trop légère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 28, 'Pharès, ton royaume a été divisé, et donné aux Mèdes et aux Perses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 29, 'Et Baltasar donna ses ordres: et l\'on revêtit Daniel de pourpre, et on lui mit autour du cou un collier d\'or, et le roi lui-même le proclama le troisième chef du royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 30, 'Et cette même nuit fut tué Baltasar, le roi chaldéen.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 31, '');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Et le Mède Darius reçut le gouvernement de son royaume, à l\'âge de soixante-deux ans.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Et il plut à Darius d\'instituer cent vingt satrapes pour être en tout son royaume;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Et au-dessus d\'eux, trois gouverneurs, dont l\'un fut Daniel, pour que les satrapes leur rendissent compte, et que lui-même n\'en fût pas surchargé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Et Daniel fut au-dessus d\'eux, parce qu\'il y avait en lui un esprit supérieur, et le roi le mit à la tête de tout son royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Or les autres gouverneurs et les satrapes s\'efforcèrent de trouver un sujet d\'accusation contre Daniel, et ils ne purent trouver contre lui ni grief, ni délit, ni soupçon, parce qu\'il était fidèle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Et les gouverneurs se dirent: Nous ne trouverons pas de sujet d\'accusation contre Daniel, sinon à cause des lois de son Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Alors les gouverneurs et les satrapes comparurent devant le roi, et lui dirent: Ô roi Darius, vis à jamais!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Tous les officiers de ton royaume, généraux et satrapes, magistrats et intendants, ont tenu conseil pour qu\'il fût rendu un édit royal, et formellement ordonné que tout homme qui durant trente jours fera une demande soit à un dieu, soit à un homme autre que le roi, sera jeté dans la fosse aux lions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Maintenant, ô roi, rends l\'édit, et publie-le, afin que rien ne soit changé à ce qu\'ont résolu les Perses et les Mèdes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Et le roi Darius fit publier l\'édit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Or Daniel, aussitôt qu\'il sut ce que prescrivait l\'édit, entra dans sa maison, à l\'étage supérieur, les fenêtres ouvertes; tourné vers Jérusalem, trois fois par jour il se mit à genoux, priant son Dieu, et lui rendant grâces, comme il avait coutume de le faire auparavant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Cependant ces hommes l\'épièrent, et ils surprirent Daniel rendant grâces à son Dieu et lui faisant sa prière.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Et s\'approchant du roi, ils lui dirent: Ô roi, n\'as-tu point rendu cet édit, que tout homme qui, durant trente jours, fera une demande à un dieu ou à un homme autre que le roi, soit jeté dans la fosse aux lions? Et le roi répondit: Ce que vous dites est véritable, et l\'édit des Perses et des Mèdes ne sera pas violé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Et ils reprirent, disant au roi: Daniel, l\'un des fils des captifs de la Judée, ne s\'est point soumis à ton édit, et trois fois par jour il demande à son Dieu ce qu\'il veut lui demander.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Aussitôt que le roi eut oui ces paroles, il en fut fort contristé, et il fut combattu par le désir de sauver Daniel, et jusqu\'au soir il fut combattu par le désir de le sauver.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Mais ces hommes dirent à Darius: Sache, ô roi, qu\'il est réglé chez les Mèdes et les Perses que nul changement ne peut être fait à un édit, à un décret du roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Et le roi donna ses ordres, et l\'on emmena Daniel, et on le jeta dans la fosse aux lions, et le roi dit à Daniel: Ton Dieu que tu sers avec constance, lui-même te délivrera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Et l\'on apporta une pierre, et on la posa sur l\'ouverture de la fosse, et le roi la scella de son anneau et de l\'anneau de ses grands, afin que rien concernant Daniel ne fût changé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Et le roi rentra dans son palais; mais il se coucha sans avoir soupé; on ne lui présenta point d\'aliments, et le sommeil s\'éloigna de lui. Et Dieu ferma la gueule des lions, et ils ne firent aucun mal à Daniel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Et le roi se leva de grand matin, dès les premières lueurs du jour, et il alla en toute hâte à la fosse aux lions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Et, quand il fut près de la fosse, il cria à haute voix: Daniel, serviteur du Dieu vivant, ton Dieu, que tu sers avec constance, a-t-il pu te sauver de la gueule des lions?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 22, 'Et Daniel dit à Darius: Roi, vis à jamais');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 23, 'Mon Dieu m\'a envoyé son ange, et il a fermé la gueule des lions, et ils ne m\'ont fait aucun mal, parce qu\'à ses yeux j\'ai été trouvé juste, et qu\'à ton égard, ô roi, je n\'ai fait aucune offense.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 24, 'À ces mots le roi fut extrêmement réjoui, et il ordonna de retirer Daniel de la fosse, et il fut trouvé sain et sauf, parce qu\'il avait mis sa confiance en Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 25, 'Et le roi donna ses ordres, et l\'on amena les hommes qui avaient accusé Daniel, et on les jeta dans la fosse aux lions, eux, leurs fils et leurs femmes; et avant qu\'ils eussent touché le fond de la fosse, les lions s\'en emparèrent et leur broyèrent tous les os.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 26, 'Alors le roi Darius écrivit à tous les peuples, aux tribus, aux hommes de toutes langues, à tous les habitants de la terre: Que la paix se multiplie parmi vous!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 27, 'Le présent édit est rendu par moi pour toutes les principautés de mon royaume, afin que chacun soit plein de crainte et de tremblement devant la force du Dieu de Daniel; car lui seul est le Dieu vivant, et il demeure dans tous les siècles, et son royaume ne périra jamais, et son règne durera jusqu\'à la fin des temps.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 28, 'Il protège et il sauve, et il fait des signes et des miracles dans le ciel et sur la terre; c\'est lui qui a tiré Daniel de la griffe des lions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 29, 'Et Daniel vécut plein de prospérité, sous le règne de Darius et sous le règne de Cyrus le Perse.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 1, 'La première année du règne de Baltasar, roi des Chaldéens, Daniel eut un songe et des visions comme sa tête reposait sur sa couche, et il écrivit sa vision.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 2, 'Moi, Daniel, je regardais, et voilà que les quatre vents du ciel se déchaînèrent sur la grande mer.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 3, 'Et quatre grandes bêtes sortirent de la mer, différentes les unes des autres.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 4, 'La première était comme une lionne, et ses ailes étaient comme les ailes d\'un aigle; et pendant que je la regardais, ses ailes lui furent arrachées; et elle fut relevée de terre, et elle se tint sur des pieds d\'homme, et un cœur d\'homme lui fut donné.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 5, 'Et voilà que la seconde bête ressemblait à une ourse, et elle était couchée sur le flanc, et elle tenait dans ses dents trois côtes, et on lui disait: Lève-toi, et rassasie-toi de carnage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 6, 'Après cela, je regardai, et voilà qu\'il y avait une autre bête, comme un léopard; et elle avait sur le haut du corps quatre ailes d\'oiseau, et elle avait quatre têtes, et la puissance lui avait été donnée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 7, 'Après cela, je regardai, et voilà qu\'il y avait une quatrième bête, effroyable, horrible, et d\'une force prodigieuse; et ses dents étaient de fer; et elle allait dévorant, broyant, foulant le reste à ses pieds; et la différence était très grande entre elle et toutes les bêtes qui la précédaient; et elle avait dix cornes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 8, 'Je fis attention à ses cornes; et voilà qu\'au milieu d\'elles s\'éleva une petite corne, et devant elle trois des premières cornes furent déracinées; et voilà que cette corne avait des yeux, comme des yeux d\'homme, et une bouche disant de grandes choses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 9, 'Et je regardai jusqu\'à un endroit où des trônes étaient placés; et l\'Ancien des jours était assis; et sa robe était blanche comme de la neige, et ses cheveux ressemblaient à la laine la plus pure; son trône était de flamme et ses roues un feu ardent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 10, 'Un fleuve de feu coulait en sa présence; il avait des mille milliers de serviteurs; et des myriades de myriades l\'assistaient; le jugement s\'assit, et les livres furent ouverts.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 11, 'Je fus attentif alors au bruit des paroles superbes que cette corne disait, quand la bête fut tuée, exterminée, et son corps jeté au feu pour être brûlé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 12, 'Et la puissance des autres bêtes leur fut ôtée; mais leur vie fut encore prolongée quelque temps.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 13, 'Je considérais cette vision de la nuit; et voilà qu\'avec les nuées du ciel vint comme le Fils de l\'homme, et il s\'avança jusqu\'à l\'Ancien des jours, et il se présenta devant lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 14, 'Et il lui fut donné pouvoir, honneur et royauté; et les peuples, les tribus et les hommes de toutes langues le servirent. Sa puissance est une puissance éternelle qui ne passera point, et son royaume ne périra jamais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 15, 'Pour moi, Daniel, mon âme frémit en tout mon être, et les visions de ma tête me troublèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 16, 'Et je m\'approchai de l\'un des assistants, et je cherchai à apprendre de lui le sens vrai de toutes ces choses, et il me dit la vérité, et il me fit connaître l\'interprétation de ces choses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 17, 'Ces quatre bêtes sont les quatre empires qui s\'élèveront sur la terre et qui seront renversés.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 18, 'Et les saints du Très-Haut recueilleront la royauté, et ils la conserveront pendant les siècles des siècles.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 19, 'Et je m\'informai avec soin de la quatrième bête, parce qu\'elle était différente de toutes les autres, et encore plus épouvantable; ses dents étaient de fer et ses griffes d\'airain; et elle allait dévorant, broyant et foulant le reste à ses pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 20, 'Et je m\'informai des dix cornes de sa tête, et de cette autre qui s\'était élevée et avait déraciné quelques unes des premières, et qui avait des yeux et une bouche disant de grandes choses, et dont l\'aspect était plus terrible que celui des autres bêtes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 21, 'J\'étais attentif, et cette corne engagea la bataille avec les saints, et elle prévalut sur eux,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 22, 'Jusqu\'à la venue de l\'Ancien des jours; et il rendit justice aux saints du Très-Haut; et le temps arriva, et les saints possédèrent le royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 23, 'Et l\'assistant me dit: La quatrième bête sera le quatrième empire sur la terre; elle dominera sur tous les royaumes; elle dévorera toute la terre; elle la foulera aux pieds et la détruira.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 24, 'Et ses dix cornes sont dix rois qui s\'élèveront, et après eux un autre s\'élèvera, qui surpassera en mal tous les précédents et subjuguera trois rois.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 25, 'Et il parlera contre le Très-Haut, et il effacera les saints du Très-Haut, et il pensera changer les temps et la loi; et les saints lui seront livrés pendant un temps, et deux temps, et un demi-temps.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 26, 'Et le jugement sera rendu, et la royauté lui sera ôtée, et il sera effacé, et il sera détruit à jamais.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 27, 'Et la royauté, la puissance et la magnificence des rois qui sont sous le ciel a été donnée aux saints du Très-Haut. Et son royaume est un royaume éternel, et toutes les dominations le serviront et lui obéiront.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 28, 'Là finit le songe. Pour moi, Daniel, mes pensées me troublèrent longtemps, et je changeai de visage, et je conservai toutes ces paroles en mon cœur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 1, 'En la troisième année du règne de Baltasar, une vision m\'apparut à moi, Daniel, après celle qui m\'était d\'abord apparue.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 2, 'J\'étais dans le palais à Suse, qui est au pays d\'Élam, et j\'étais sur la rive du fleuve Ubal.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 3, 'Et je levai les yeux, et je regardai; et voilà qu\'un bélier se tenait devant l\'Ubal. Et il avait de grandes cornes, et l\'une était plus grande que l\'autre, et allait toujours croissant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 4, 'Et je vis le bélier frappant de ses cornes du côté de la mer, de l\'aquilon et du midi; et devant lui nulle bête ne pouvait tenir, et nul ne pouvait échapper à ses coups, et il fit ce qu\'il voulut, et il devint grand.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 5, 'Et j\'étais là, le regardant; et voilà qu\'un jeune bouc vint du sud-ouest, sur la face de toute la terre, et il ne touchait pas à terre; et ce bouc avait une corne entre les yeux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 6, 'Et il arriva jusqu\'au bélier qui avait des cornes, celui que j\'avais vu en face de l\'Ubal; et il s\'élança contre lui dans toute la force de sa fureur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 7, 'Et je le vis atteindre le bélier, et il se rua sur lui, et il le frappa, et lui brisa les deux cornes: et le bélier fut sans force pour lui résister en face. Puis il le jeta contre terre, et il le foula aux pieds, et nul n\'était là pour délivrer le bélier de ses coups.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 8, 'Or le bouc grandit à l\'excès; et pendant qu\'il croissait en force, sa grande corne se brisa, et quatre autres cornes lui poussèrent au-dessous de celle-ci, des quatre côtés du ciel, d\'où viennent les vents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 9, 'Et de l\'une de ces cornes sortit une autre corne puissante, qui s\'éleva prodigieusement contre le midi et contre un peuple fort;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 10, 'Et même elle s\'éleva jusqu\'à l\'armée du ciel; et elle fit tomber du ciel une partie de l\'armée et une partie des étoiles, et elles furent foulées aux pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 11, 'Et il en fut ainsi, jusqu\'à ce que le chef de l\'armée eût délivré ses captifs; et à cause de ce bouc les sacrifices furent interrompus, et il prospèrera, et le sanctuaire sera désolé.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 12, 'Et au lieu de victimes les offrandes furent le péché, et la justice fut renversée à terre. Pour lui, il fera son œuvre, et il prospèrera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 13, 'Et j\'entendis l\'un des saints qui parlait, et l\'un des saints dit à un autre qui m\'était inconnu: Jusques à quand durera cette vision des sacrifices abolis, du péché, cause de cette désolation, du sanctuaire et de l\'armée céleste foulés aux pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 14, 'Et le premier répondit: Du soir au matin, durant deux mille quatre cents jours, puis le sanctuaire sera purifié.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 15, 'Et ceci advint: tandis que moi, Daniel, j\'avais cette vision et que je cherchais à la comprendre, voilà que la vision d\'un homme se dressa devant moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 16, 'Et j\'entendis une voix d\'homme, entre l\'Ubal et moi, et elle appela et dit: Gabriel, explique à celui-ci sa vision.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 17, 'Et Gabriel s\'approcha, et il se tint auprès de moi, et pendant qu\'il venait j\'étais frappé de crainte; et je tombai la face contre terre, et il me dit: Comprends, fils de l\'homme; car cette vision s\'accomplira au temps marqué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 18, 'Et pendant qu\'il me dit ces paroles, je retombai encore la face contre terre, et il me toucha, et il me remit debout sur mes pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 19, 'Et il me dit: Je vais te faire savoir ce qui adviendra aux derniers jours de la colère; car c\'est aussi le temps marqué pour l\'accomplissement de ta vision.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 20, 'Le bélier que tu as vu ayant des cornes est le roi des Mèdes et des Perses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 21, 'Le bouc est le roi des Hellènes; et la grande corne qu\'il avait entre les deux yeux est leur premier roi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 22, 'Et quand elle a été brisée, les quatre cornes qui se sont élevées au- dessous sont quatre rois qui s\'élèveront parmi les nations, mais non par leur propre force.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 23, 'Et à la fin de leurs règnes, quand la mesure de leurs péchés sera remplie, un roi s\'élèvera, au front impudent, comprenant les énigmes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 24, 'Et sa force sera grande, et il détruira des choses admirables, et il prospèrera, et il entreprendra, et il détruira les forts et le peuple saint.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 25, 'Et le joug de sa chaîne sera bien dirigé; la fraude à la main, il se glorifiera en son cœur; il fera périr par ses ruses une multitude d\'hommes, et il s\'affermira par la ruine de plusieurs; et il les écrasera comme un œuf dans la main.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 26, 'Cette vision que tu as eue du soir au matin est véritable; mets-y le sceau, parce qu\'elle ne s\'accomplira qu\'après bien des jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 27, 'Après cela, moi, Daniel, je fus alité et je tombai dans la langueur; puis je me levai, et je m\'appliquai aux affaires du roi, et je fus émerveillé de ma vision; mais il n\'y eut personne pour la comprendre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 1, 'En la première année du règne de Darius, fils d\'Assuérus, de la race des Mèdes, qui régna sur l\'empire des Chaldéens,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 2, 'Moi, Daniel, je compris, au moyen des livres, le nombre des années que la parole du Seigneur avait fait connaître à Jérémie le prophète, sur le temps que devait durer la désolation de Jérusalem, et qui devait être de soixante-dix années.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 3, 'Et je tournai mon visage vers le Seigneur mon Dieu, pour l\'implorer et le prier, en jeûnant, et revêtu d\'un cilice.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 4, 'Et je fis ma prière au Seigneur mon Dieu, et je lui rendis gloire, et je dis: Seigneur, Dieu grand et admirable, qui gardez votre alliance, et réservez votre miséricorde en faveur de ceux qui vous aiment et observent vos commandements;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 5, 'Nous avons péché; nous avons commis l\'injustice et l\'iniquité; nous nous sommes retirés de vous; nous avons dévié de vos ordonnances et de vos jugements,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 6, 'Et nous n\'avons point écouté vos serviteurs les prophètes, qui, en votre nom, parlaient à nos rois, à nos princes, à nos pères et à tout le peuple de la terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 7, 'À vous, Seigneur, est la justice; à nous la honte au visage, comme aujourd\'hui à tout homme de Juda, à tout habitant de Jérusalem, à tout Israël, soit près d\'ici, soit au loin, en toute région où vous les avez dispersés à cause des prévarications qu\'ils ont commises.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 8, 'En vous, Seigneur, est notre justice; à nous la honte au visage, à nous, à nos rois, à nos princes et à nos pères; car nous avons tous péchés contre vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 9, 'À vous, Seigneur notre Dieu, les miséricordes et le pardon; car nous nous sommes retirés de vous,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 10, 'Et nous n\'avons point écouté la voix du Seigneur notre Dieu, pour marcher dans les lois qu\'il nous a données, face à face, par les mains de ses serviteurs les prophètes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 11, 'Tout Israël a transgressé votre loi; il s\'est détourné tout entier, pour ne pas entendre votre parole. Et votre malédiction est tombée sur nous, ainsi que l\'imprécation écrite dans la loi de Moise, serviteur de Dieu, parce que nous avons péché contre vous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 12, 'Et Dieu a confirmé ses paroles prononcées contre nous et contre les juges qui nous jugeaient, et qui ont amené sur nous de si grands maux, que jamais rien sous le ciel n\'advint comme ce qui est advenu à Jérusalem;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 13, 'Comme il est écrit en la loi de Moïse: Tous ces maux sont arrivés sur nous, et nous n\'avons point prié devant la face du Seigneur notre Dieu, pour qu\'il nous retirât de nos iniquités, et nous fit comprendre toute sa vérité.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 14, 'Mais le Seigneur a veillé sur nous, et il a amené sur nous ces maux, parce que le Seigneur notre Dieu est juste en toutes ses œuvres, et que nous n\'avions point écouté sa voix.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 15, 'Et maintenant, Seigneur notre Dieu, qui par votre main puissante avez délivré votre peuple de la terre d\'Égypte, et qui vous êtes fait alors un nom comme aujourd\'hui, nous avons péché, nous avons commis l\'iniquité!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 16, 'Seigneur, votre miséricorde est pour tous; que votre indignation et votre colère se détourne de votre ville de Jérusalem et de votre montagne sainte; car nous avons péché, et à cause de nos iniquités et de celles de nos pères, Jérusalem et votre peuple sont devenus un sujet d\'opprobre pour tous ceux qui nous entourent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 17, 'Et maintenant, Seigneur notre Dieu, écoutez la prière de votre serviteur et ses supplications; faites briller votre face dans votre sanctuaire délaissé; faites-le pour vous, Seigneur!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 18, 'Inclinez votre oreille, Seigneur mon Dieu, et exaucez-nous; ouvrez les yeux, et voyez notre anéantissement et celui de la cité à laquelle était donné votre nom; car ce n\'est point dans l\'attente de vos jugements que nous jetons devant vous notre cri de pitié, mais en vue de vos abondantes miséricordes, O Seigneur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 19, 'Exaucez-moi, Seigneur; apaisez-vous, Seigneur; aimez-moi, Seigneur: ne différez pas, ô mon Dieu, pour l\'amour de vous-même; car cette cité et ce peuple sont ceux à qui a été donné votre nom.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 20, 'Et comme je parlais encore, comme je priais, et que je confessais mes péchés et les péchés d\'Israël, mon peuple; comme je jetais en face du Seigneur mon Dieu mon cri de pitié pour la montagne sainte;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 21, 'Tandis que je parlais encore, voilà que l\'homme Gabriel, qui m\'était apparu au commencement de ma vision, vint en volant, et me toucha vers l\'heure du sacrifice du soir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 22, 'Et il m\'ouvrit l\'intelligence, et il me parla et me dit: Daniel, je suis venu pour t\'apporter l\'intelligence.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 23, 'Au commencement de ta prière, un ordre m\'est venu, et je suis venu pour t\'instruire; car tu es l\'homme des désirs, dit-il. Réfléchis donc à ma parole et comprends ta vision.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 24, 'Soixante-dix semaines ont été assignées à ton peuple et à la cité sainte, pour que le péché soit à sa fin, que les péchés soient abolis, que les iniquités soient effacées et expiées, que l\'éternelle justice soit ramenée, que le sceau soit mis à la vision et au prophète, et que le Saint des saints soit marqué de l\'onction.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 25, 'Sache donc et comprends qu\'à partir de l\'ordre qui sera donné de parler et de rebâtir Jérusalem, jusqu\'au roi Christ, il y aura sept semaines et soixante-deux semaines; et l\'ancien temps reviendra, les places et les remparts seront relevés, et les temps accomplis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 26, 'Et après les soixante-deux semaines le Christ sera mis à mort, et il n\'y aura pas en lui de sujet de condamnation; et il détruira la ville et le sanctuaire, à l\'aide d\'un chef qui surviendra; et ils disparaîtront dans un cataclysme, et à la fin de la guerre, qui sera abrégée, il livrera la ville aux désolations.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 27, 'Et durant une semaine il confirmera l\'alliance avec plusieurs. Et au milieu de la semaine la victime et les libations me seront ôtées, et l\'abomination de la désolation sera sur le temple, et la désolation aura sa fin à la consommation des temps.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 1, 'En la troisième année du règne de Cyrus, roi des Perses, une parole fut révélée à Daniel, que l\'on nommait Baltasar. Et cette parole était véritable, et une grande force et une grande intelligence lui furent données en cette vision.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 2, 'En ces jours-là, moi, Daniel, je fus pleurant durant trois semaines.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 3, 'Je ne mangeai point de pain agréable au goût; ni chair ni vin n\'entrèrent dans ma bouche, et je n\'usai d\'aucun parfum, jusqu\'à ce que les trois semaines fussent accomplies.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 4, 'Le vingt-quatrième jour du premier mois, j\'étais sur les bords du grand fleuve que l\'on appelle le Tigre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 5, 'Et je levai les yeux, et je regardai; et voilà qu\'il y avait un homme vêtu de lin, et ses reins étaient ceints d\'or d\'Ophaz;');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 6, 'Et son corps était comme Tharsis, et son front avait l\'aspect d\'un éclair; et ses yeux étaient comme des lampes de feu; ses bras et ses jambes avaient l\'aspect de l\'airain resplendissant; et sa voix, quand il parlait, était comme la voix d\'une multitude.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 7, 'Et moi, Daniel, j\'eus seul cette vision, et les hommes qui étaient avec moi ne la virent point; mais un grand trouble les saisit, et ils s\'enfuirent de terreur.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 8, 'Et moi je restai seul, et j\'eus cette grande vision; et mes forces m\'abandonnèrent, et la gloire de mon visage en fut altérée, et je ne pus recouvrer ma force.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 9, 'Et j\'entendis retentir ces paroles; et, en les entendant, j\'étais plein d\'épouvante, et j\'avais la face contre terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 10, 'Et voilà qu\'une main me toucha, et me releva sur mes genoux.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 11, 'Et il me dit: Daniel, homme des désirs, comprends les paroles que je te dis, et tiens-toi debout; car je suis envoyé vers toi; et pendant qu\'Il me dit ces mots je me relevai tremblant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 12, 'Et il me dit: N\'aie point peur, Daniel; car du premier jour où tu as appliqué ton cœur à converser avec le Seigneur ton Dieu, et à t\'affliger devant lui, tes prières ont été entendues, et je suis venu à tes prières.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 13, 'Or le prince du royaume des Perses m\'a résisté vingt et un jours, et Michel, l\'un des archanges, est venu à mon aide, et je l\'ai laissé au lieu où j\'étais, avec le prince du royaume des Perses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 14, 'Et je suis venu t\'enseigner les choses qui adviendront à ton peuple dans les derniers jours; car cette vision est pour bien des jours encore.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 15, 'Et pendant qu\'il me dit ces paroles, je retombai la face contre terre, et je fus rempli d\'épouvante.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 16, 'Et voilà qu\'une image du fils de l\'homme me toucha les lèvres, et j\'ouvris la bouche, et je parlai; et je dis à celui qui se tenait devant moi: Seigneur, à votre vue mes entrailles ont été émues, et j\'ai perdu ma force.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 17, 'Et comment, ô Seigneur, votre serviteur pourra-t-il s\'entretenir avec vous, mon seigneur? Je ne puis plus recouvrer aucune force, et il n\'est plus de souffle en moi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 18, 'Et celui qui avait l\'apparence d\'un homme s\'approcha, me toucha de nouveau et me raffermit.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 19, 'Et il me dit: N\'aie point peur, homme des désirs; la paix soit avec toi; sois homme et sois fort. Et pendant qu\'il me dit ces mots je me fortifiai, et je dis: Parlez-moi, seigneur, car vous m\'avez fortifié.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 20, 'Et il me dit: Sais-tu pourquoi je suis venu te trouver? Maintenant je vais retourner combattre le roi des Perses; car comme j\'entrais ici, le roi des Hellènes est venu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 21, 'Or je te dirai ce qui est prescrit en l\'Écriture au livre de vérité: Nul ne m\'assiste en toutes ces choses, sinon Michel, votre prince.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 1, 'Je suis celui qui, en la première année du règne de Cyrus, se tint près de lui pour le fortifier et l\'affermir.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 2, 'Et maintenant je te ferai connaître la vérité: trois rois règneront encore sur la Perse; le quatrième prospèrera et les surpassera tous en richesses; et lorsqu\'il sera en possession de ses richesses, il fera la guerre à tous les royaumes des Hellènes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 3, 'Et un roi puissant s\'élèvera, et il sera maître d\'un grand empire, et il fera ce qu\'il voudra.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 4, 'Et, au moment où son empire sera affermi, il sera brisé et partagé aux quatre vents du ciel; et il ne passera point à ses descendants, et il ne gardera point sa puissance selon ses désirs; car sa royauté lui sera arrachée; puis elle passera à d\'autres après lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 5, 'Et le roi du midi se fortifiera; mais l\'un de ces princes prévaudra contre lui, et il dominera sur un grand royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 6, 'Et quelques années après ils s\'uniront; et la fille du roi du midi ira trouver le roi de l\'aquilon pour faire alliance avec lui; mais elle ne retirera pas de là un bras puissant; et la race du vainqueur ne se maintiendra pas; et elle-même sera livrée avec ceux qui la conduisaient, et la jeune fille, et celui qui la fortifiait en ces temps.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 7, 'Mais un rejeton de la fleur de sa racine s\'élèvera bientôt après; et il s\'avancera à la tête d\'une armée, et il entrera dans les forteresses du roi de l\'aquilon; il combattra contre elles, et il s\'en rendra maître.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 8, 'Et il transportera en Égypte, avec les captifs, leurs dieux et leurs statues de fonte et leurs objets précieux d\'argent et d\'or; et lui-même subsistera plus longtemps que le roi de l\'aquilon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 9, 'Celui-ci à son tour entrera dans le royaume du roi du midi, puis il retournera en sa propre terre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 10, 'Et ses fils parmi maintes nations rassembleront une grande multitude; et l\'un d\'eux se mettra en campagne; et en sa marche il s\'avancera comme un torrent débordé; il passera, il campera et rassemblera, ses forces pour le combat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 11, 'Et le roi du midi s\'effarouchera, et il s\'avancera pour combattre le roi de l\'aquilon; et il lèvera une grande armée, et une grande multitude d\'ennemis lui sera livrée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 12, 'Et il prendra captive cette multitude, et son cœur s\'enorgueillira, et il massacrera des myriades d\'ennemis; mais il n\'en sera pas plus puissant.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 13, 'Car le roi de l\'aquilon reviendra, et il conduira des troupes en plus grand nombre que la première fois; et à la fin des temps et des années une armée envahissante arrivera avec une grande force et de grands approvisionnements.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 14, 'Et en ce temps-là plusieurs se soulèveront contre le roi du midi, et des fils de ton peuple s\'élèveront comme un fléau pour accomplir une vision; mais ils manqueront de force.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 15, 'Car le roi de l\'aquilon s\'avancera; il élèvera des terrasses; il prendra des villes fortes; et les bras du roi du midi soutiendront le choc, et ses troupes d\'élite se lèveront; mais ils ne seront pas de force à résister.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 16, 'Et le roi de l\'aquilon, après l\'avoir ainsi envahi, fera tout ce qu\'il voudra, et nul ne tiendra devant lui. Et il s\'arrêtera en la terre de Sabé; et il la détruira de sa main.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 17, 'Et il tournera son visage pour entrer en forces dans le royaume du midi, et toutes choses prospèreront devant lui; il donnera au roi ennemi une fille des femmes pour le perdre; mais il n\'y réussira point, et elle ne sera pas à lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 18, 'Alors il tournera son visage contre les îles, et il en prendra plusieurs; et il arrêtera d\'abord les princes de son opprobre; mais son opprobre retombera sur lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 19, 'Et il retournera son visage vers la force de sa terre; mais il sera affaibli, et il tombera, et on ne le retrouvera plus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 20, 'Et de sa racine s\'élèvera un rejeton qui sera comme un plant sur le trône qu\'il occupait avec gloire. Et en ces jours-là il sera encore brisé, mais non en face, non dans un combat.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 21, 'Un autre prendra sa place, qui sera méprisé; on ne lui aura point accordé les honneurs de la royauté; mais il viendra avec ruse, et à force d\'artifices il se rendra maître du royaume,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 22, 'Et les bras de son adversaire seront énervés devant sa face; ils seront brisés, ainsi que le chef de l\'alliance.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 23, 'Et après leur traité, il trompera encore celui-ci; il s\'avancera, et prévaudra sur lui avec un petit nombre de troupes.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 24, 'Il viendra en des régions paisibles et opulentes; et il fera ce que n\'ont fait ni ses pères ni les pères de ses pères; il emportera leur butin, leurs dépouilles, leurs richesses, et il concevra de mauvais desseins contre l\'Égypte; mais cela n\'aura qu\'un temps.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 25, 'Et sa force et son cœur s\'élèveront avec une grande force contre le roi du midi; et le roi du midi soutiendra aussi la guerre avec une force très grande et très redoutable; mais ses armées ne tiendront pas, parce que de mauvais desseins auront été formés contre lui.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 26, 'On mangera avec lui; puis on le brisera, et son ennemi engloutira ses armées, et les morts tomberont en foule.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 27, 'Et les deux rois, le cœur plein de perversité, assis à la même table, se diront des mensonges; mais cela ne réussira pas, parce que leur fin arrivera au temps marqué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 28, 'Et le roi de l\'aquilon retournera en sa terre avec de grandes richesses; et son cœur sera opposé à l\'alliance sainte, et il fera de grandes choses, et il rentrera dans son royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 29, 'Il reviendra au temps marqué, et marchera contre le midi; mais cette dernière invasion ne sera pas comme la première.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 30, 'Les Citians, sortis de leurs pays, marcheront contre lui; et par eux il sera abaissé, et il battra en retraite; il s\'irritera contre l\'alliance sainte, et agira contre elle; puis il se remettra en campagne, et s\'entendra avec ceux qui auront abandonné l\'alliance sainte.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 31, 'Et des rejetons de lui s\'élèveront, et ils profaneront le sanctuaire de la Toute-Puissance, et ils feront cesser le sacrifice perpétuel, et ils le remplaceront par l\'abomination de la désolation.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 32, 'Et les impies feront alliance entre eux pour faire le mal; mais un peuple connaissant son Dieu prévaudra et agira vaillamment.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 33, 'Et les sages du peuple comprendront beaucoup de choses; toutefois ils seront affaiblis par le glaive, par le feu, par la captivité, et par un pillage qui durera bien des jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 34, 'Et dans leur détresse ils recevront un faible secours; mais plusieurs se joindront à eux avec des vues perfides,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 35, 'Et parmi les sages quelques-uns auront beaucoup à souffrir pour être purifiés, élus et manifestés aux derniers jours; car ces choses doivent s\'accomplir au temps marqué.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 36, 'Et le roi fera selon sa volonté; il s\'élèvera, et il se glorifiera contre toute divinité, et il parlera un langage superbe, et il prospèrera jusqu\'à ce que la colère de Dieu s\'accomplisse; car cela doit finir ainsi.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 37, 'Et il ne reconnaîtra aucun des dieux de ses pères; il sera épris des femmes, et ne reconnaîtra aucun dieu; car il se croira plus grand qu\'eux tous.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 38, 'Et il honorera le dieu Maozim en son temple, et il le glorifiera en lui offrant de l\'or, de l\'argent, des pierres précieuses et des choses de prix, ce dieu que ses pères ne connaissaient pas.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 39, 'Et il donnera place dans les forteresses de refuge à un dieu étranger; il multipliera ses honneurs; il lui assujettira beaucoup d\'hommes, et il partagera la terre pour en faire des présents.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 40, 'Et au temps marqué il sera aux prises avec le roi du midi; et le roi de l\'aquilon conduira contre lui une multitude de chars, de cavaliers, de vaisseaux, et il envahira sa terre, et il la traversera, et il la foulera aux pieds.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 41, 'Et il entrera dans la terre de Sébaïm, et beaucoup succomberont. Et voici ceux qui échapperont à sa main: Édom, Moab et la principauté des fils d\'Ammon.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 42, 'Et il étendra son bras sur la terre de Palestine, et l\'Égypte ne sera pas sauvée.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 43, 'Et il se rendra maître des lieux où sont cachés l\'or et l\'argent et tout ce qu\'il y a de précieux en Égypte, en Libye et en Éthiopie, et dans leurs forteresses.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 44, 'Puis des rumeurs, des nouvelles pressantes, de l\'orient et du nord, le troubleront; et il viendra plein de colère pour exterminer beaucoup d\'ennemis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 45, 'Et il dressera les tentes de son palais entre les mers, sur la montagne sainte de Sébaïn, et il y viendra jusqu\'à sa fin, et nul ne pourra le sauver.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 1, 'En ce temps-là s\'élèvera Michel le grand prince, celui qui veille sur les fils de ton peuple. Et ce sera un temps de tribulation, de tribulation telle qu\'il n\'y en a jamais eu de semblable depuis qu\'il y a des nations sur la terre jusqu\'à ce jour. En ce temps-là sera sauvé tout homme de ton peuple qui sera inscrit dans le livre.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 2, 'Et nombre de ceux qui dorment sous des amas de terre se réveilleront, les uns pour la vie éternelle, les autres pour la honte et la confusion éternelle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 3, 'Et les sages brilleront comme les luminaires du firmament, et nombre de justes comme les étoiles, dans les siècles et au delà.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 4, 'Pour toi, Daniel, renferme ces paroles, scelle le livre jusqu\'au temps de l\'accomplissement de ces choses; car beaucoup viendront y apprendre, et par lui la science se multipliera.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 5, 'Et moi, Daniel, je regardai, et voilà qu\'il y avait comme deux autres hommes se tenant l\'un sur une rive du fleuve, l\'autre sur l\'autre rive.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 6, 'Et l\'un d\'eux dit à l\'homme vêtu de lin, qui était au-dessus de l\'eau du fleuve: Quand s\'accompliront ces prodiges dont tu as parlé?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 7, 'Et j\'entendis l\'homme vêtu de lin, qui était au dessus de l\'eau du fleuve; il leva les deux mains vers le ciel, et il jura par Celui qui vit éternellement qu\'après un temps, deux temps et la moitié d\'un temps à la fin de la dispersion, toutes ces choses seraient connues.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 8, 'Et j\'entendis, mais je ne compris pas, et je dis: Seigneur, quelle sera la fin de ces choses?');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 9, 'Et il dit: Va, Daniel; car ces paroles seront renfermées et scellées, jusqu\'à ce que les temps soient venus.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 10, 'Plusieurs seront élus, blanchis, éprouvés comme par le feu et sanctifiés; et les pécheurs pècheront, et nul des pécheurs ne comprendra, mais les sages comprendront.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 11, 'Et à partir du temps où a été supprimé le sacrifice perpétuel, l\'abomination de la désolation durera douze cent quatre-vingt-dix jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 12, 'Heureux celui qui attendra et parviendra jusqu\'à mille trois cent trente-cinq jours!');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 13, 'Pour toi, va, et sois en repos; car bien des jours et des heures s\'écouleront encore avant que les temps s\'accomplissent, et à la fin des temps tu ressusciteras pour recueillir ton partage.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Le roi Astyage ayant été réuni à ses pères, Cyrus le Perse reçut le royaume.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Or Daniel mangeait à la table du roi, et il était honoré plus que tous ses autres amis.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Il y avait chez les Babyloniens une idole nommée Bel; on dépensait chaque jour pour elle douze artabes de farine, quarante brebis et six métrètes de vin.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Le roi aussi la vénérait, et il allait chaque jour l\'adorer; mais Daniel adorait son Dieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Le roi lui dit \'Pourquoi n\'adores-tu pas Bel?\' Il lui répondit:\'Parce que je ne vénère pas des idoles faites de main d\'homme, mais le Dieu vivant qui a fait le ciel et la terre et qui a puissance sur toute chair.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Le roi lui dit \'Est-ce que Bel ne te semble pas un être vivant? Ne vois-tu pas tout ce qu\'il mange et boit chaque jour?\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Daniel répondit en souriant \'Ne t\'y trompes pas, ô roi; car il est de boue en dedans et d\'airain à l\'extérieur, et il n\'a jamais rien mangé.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Le roi irrité appela les prêtres de Bel et leur dit \'Si vous ne me dites pas qui est celui qui mange ces offrandes, vous mourrez; mais si vous me démontrez que c\'est Bel qui les mange, Daniel mourra, parce qu\'il a blasphémé contre Bel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Et Daniel dit au roi: qu\'il en soit selon ta parole. Or il y avait soixante-dix prêtres de Bel, sans compter leurs femmes et leurs enfants.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Et le roi se rendit avec Daniel au temple de Bel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Les prêtres de Bel dirent \'Voici que nous allons sortir; toi, ô roi, fais placer les mets et apporter le vin, après l\'avoir mélangé; puis ferme la porte, et scelle-la avec ton anneau. Et quand tu entreras demain matin, si tu ne trouves pas que tout a été mangé par Bel, nous mourrons; ou bien ce sera Daniel, qui a menti contre tous.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Ils songeaient qu\'ils avaient fait sous la table une ouverture secrète, par laquelle ils s\'introduisaient toujours et verraient consommer les offrandes');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Lorsqu\'ils furent sortis et que le roi eut fait mettre les aliments devant Bel,');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Daniel commanda à ses serviteurs d\'apporter de la cendre, et il la répandirent par tout le temple en présence du roi seul puis ils sortirent, fermèrent la porte en la scellant avec l\'anneau du roi, et s\'en allèrent.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Pendant la nuit, les prêtres entrèrent selon leur coutume avec leurs femmes et leurs enfants, et ils mangèrent et burent tout ce qui était là.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Le roi se leva dès le point du jour, et Daniel avec lui. Le roi dit');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, '\'Les sceaux sont-ils intacts, Daniel?\' Celui-ci répondit \'Ils sont intacts, ô roi.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Dès qu\'il eut ouvert la porte et regardé la table, le roi s\'écria à haute voix \'Tu es grand, ô Bel, et il n\'y a pas la moindre tromperie en toi.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 19, 'Daniel se prit à rire et, retenant le roi pour qu\'il n\'entrât pas plus avant, il lui dit \'Regarde le pavé, considère de qui sont ces pas.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 20, 'Le roi dit \'je vois des pas d\'hommes, de femmes et d\'enfants;\' et le roi entra dans une grande colère.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 21, 'Alors il fit saisir les prêtres, leurs femmes et leurs enfants, et ils lui montrèrent les portes secrètes par où ils s\'introduisaient et venaient manger ce qui était sur la table.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 22, 'Il les fit mettre à mort et livra Bel au pouvoir de Daniel, qui le détruisit ainsi que son temple.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 23, 'Il y avait aussi un grand dragon, et les Babyloniens le vénéraient.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 24, 'Le roi dit à Daniel \'Diras-tu encore que celui-ci est d\'airain? Vois, il vit, il mange et boit. Maintenant, tu ne pourras pas dire que ce n\'est pas un dieu vivant.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 25, 'Daniel répondit \'J\'adore le Seigneur, mon Dieu, car lui est un Dieu vivant; mais celui-ci n\'est point un dieu vivant. Toi, ô roi, donne-moi la permission, et je tuerai ce dragon sans épée ni bâton.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 26, 'Le roi dit: \'Je te la donne\'.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 27, 'Alors Daniel prit de la poix, de la graisse et des poils, fit bouillir le tout ensemble et en fit des boules qu\'il jeta dans la gueule du dragon. Et le dragon creva. Et il dit \'Voilà celui que vous vénériez!\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 28, 'Les Babyloniens, l\'ayant appris, furent saisis d\'une vive indignation; ils se rassemblèrent contre le roi et dirent \'Le roi est devenu juif; il a détruit Bel, fait mourir le dragon et massacrer les prêtres.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 29, 'Ils vinrent donc trouver le roi et lui dirent \'Livre-nous Daniel; sinon, nous te ferons mourir, toi et ta maison.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 30, 'Le roi vit qu\'ils se jetaient sur lui avec violence; cédant à la nécessité, il leur livra Daniel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 31, 'Ils le jetèrent dans la fosse aux lions, et il y demeura six jours.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 32, 'Dans la fosse, il y avait sept lions, et on leur donnait chaque jour deux corps et deux brebis; mais alors on ne leur donna pas cette pâture, afin qu\'ils dévorassent Daniel.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 33, 'Or le prophète Habacuc était en Judée; après avoir fait cuire une bouillie et émietté du pain dans un vase, il allait aux champs le porter à ses moissonneurs.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 34, 'L\'ange du Seigneur dit à Habacuc \'Porte le repas que tu tiens à Babylone, à Daniel, qui est dans la fosse aux lions.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 35, 'Habacuc dit \'Seigneur, je n\'ai jamais vu Babylone, et je ne connais pas la fosse.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 36, 'Alors l\'ange le prit par le haut de la tête, le porta, par les cheveux de sa tête, et le déposa à Babylone, au-dessus de la fosse, avec toute l\'agilité de sa nature spirituelle.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 37, 'Et Habacuc cria \'Daniel, serviteur de Dieu, prends le repas que Dieu t\'envoie.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 38, 'Daniel répondit \'Vous vous êtes, en effet, souvenu de moi, ô Dieu, et vous n\'avez pas abandonné ceux qui vous aiment.\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 39, 'Et Daniel se leva et mangea. Et l\'ange du Seigneur remit aussitôt Habacuc en son lieu.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 40, 'Le septième jour, le roi vint pour pleurer Daniel; étant venu vers la fosse, il regarda, et voici que Daniel était assis au milieu des lions.');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 41, 'Il cria à haute voix et dit \'Vous êtes grand, Seigneur, Dieu de Daniel, et il n\'y en a point d\'autre que vous!\'');
INSERT INTO `FreLXX_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 42, '');
